const std = @import("std");
const builtin = @import("builtin");
const mem = std.mem;
const assert = std.debug.assert;
const parser = @import("parser");
const ParseError = parser.ParseError;
const lexer = @import("lexer");
const LexError = lexer.LexError;
const token = lexer.token;
const ast = @import("ast");
const utils = @import("utils");
const semantics = @import("semantics");
const scope = semantics.scope;
const symbol = semantics.symbol;
const dtype = semantics.dtype;

/// Compatibility shim: ArrayList with embedded allocator (old-style managed API).
fn ArrayList(comptime T: type) type {
    return std.array_list.Managed(T);
}

/// Maximum native-recursion depth for the expression walkers. Guards against
/// stack-overflow segfaults on pathological input (deeply parenthesized
/// expressions, very long flat operator chains, which build deep ASTs). Set well
/// above any plausible human-written expression so legitimate code is unaffected,
/// while still leaving ample native stack headroom before the OS limit.
const max_expr_recursion_depth: usize = 800;

/// Errors that can occur during the transpilation process.
pub const TranspileError = error{
    /// Error indicating that a file is not found.
    FileNotFound,
    /// Error indicating an imported module file is not found.
    ImportFileNotFound,
    /// Error indicating that a file cannot be opened.
    FileOpenError,
    /// Error indicating that a file cannot be read.
    FileReadError,
    /// Error indicating that a file cannot be written.
    FileWriteError,
    /// Error indicating a file seek operation failed.
    FileSeekError,
    /// Error indicating a failure when writing to the output buffer.
    BufferWriteError,
    /// Error indicating memory allocation failure.
    MemoryAllocationFailed,
    /// Error indicating that a symbol is not defined.
    SymbolNotDefined,
    /// Error indicating that a symbol is already defined.
    DuplicateSymbol,
    /// Error indicating that a variable is already declared.
    VariableAlreadyDeclared,
    /// Error indicating unsupported import.
    UnsupportedImport,
    /// Error indicating circular import.
    CircularImport,
    /// Error indicating that the import path is invalid.
    InvalidImportPath,
    /// Error indicating unsupported AST node type.
    UnsupportedNodeType,

    /// Error indicating a type mismatch.
    TypeMismatch,

    /// Error indicating a field/member access is syntactically/semantically invalid.
    InvalidFieldAccess,
    /// Error indicating a named type does not have a requested field.
    UnknownField,

    /// Error indicating invalid inline assembly usage.
    InvalidAsm,

    /// Error indicating an invalid `sizeof(...)` usage.
    InvalidSizeof,
    /// Error indicating a function call has the wrong number of arguments.
    WrongArgCount,
    /// Error indicating a return statement does not match the function return type.
    ReturnTypeMismatch,
    /// Error indicating a condition expression has an invalid type.
    InvalidConditionType,
    /// Error indicating an expression is not callable.
    NotCallable,

    /// Error indicating compounds have cyclic by-value dependencies.
    CyclicCompoundDependency,
    /// Error indicating an index operation is applied to a non-array.
    IndexNonArray,

    /// Error indicating an expected warning annotation was not fulfilled.
    UnmetWarningExpectation,

    /// Error indicating an expression nests deeper than the compiler can safely
    /// recurse (guards the recursive-descent passes against native stack overflow
    /// on pathological input). Reported cleanly instead of segfaulting.
    ExpressionTooDeep,
};

/// General errors that can occur during the transpilation process.
pub const GeneralError = TranspileError || LexError || ParseError;

/// TranspileProcessFlags is an enumeration that defines flags for the transpile process.
pub const TranspileProcessFlags = packed struct {
    /// Flag to indicate execution process. When true, the output will be compiled and executed.
    exec: bool = true,
    /// Flag to indicate output file process. When true, the .c file will be generated.
    outf: bool = false,
    /// Flag to print AST nodes. When true, prints the Abstract Syntax Tree nodes.
    ast: bool = false,

    /// Flag to preload imported module symbols during parsing.
    ///
    /// This is primarily for parser identifier validation. Tooling (like `fls`) may disable
    /// it when indexing from in-memory text to avoid filesystem churn and noisy diagnostics
    /// when relative imports are resolved from a temp path.
    preload_imports: bool = true,

    /// Flag to preload stdlib signature modules during parsing.
    ///
    /// This is best-effort and non-fatal, but still touches the filesystem.
    preload_std_imports: bool = true,

    /// When false, suppress writing diagnostics to stderr.
    ///
    /// Tooling (like `fls`) may parse/lex temporary/incomplete snapshots while typing.
    /// Emitting those transient errors to stderr creates noisy logs without improving UX.
    emit_stderr: bool = true,

    /// When false, suppress unused-* warnings.
    ///
    /// Tooling paths such as `fls` may disable these to keep indexing/hover fast and avoid
    /// dependency-noise diagnostics while users are editing incomplete files.
    emit_unused_warnings: bool = false,

    /// When true, a single hard type error does not abort unused-* reporting for
    /// the whole module: typechecking continues per-module (best-effort) and the
    /// unused warnings are still emitted, then the first hard error is re-raised.
    /// Used by fls so a file with an unrelated error still shows unused squiggles.
    /// Implies the same detection as `emit_unused_warnings`.
    warn_unused_lenient: bool = false,

    /// When true, skip C code emission entirely after type-checking.
    ///
    /// Used by the diagnostics-only path (`fun -no-exec` without `-outf`) to avoid the
    /// full codegen pass when only error/warning output is needed.  Reduces compile time
    /// by roughly half for large files.
    diag_only: bool = false,

    /// When true, emit `#line` directives in generated C so debuggers (gdb, lldb)
    /// map back to Fun source lines.  Also causes the C compiler to be invoked with
    /// `-g` (DWARF symbols) instead of `-g0`.
    debug_info: bool = false,

    /// When true (the `fun test` CLI subcommand), `test "name" { ... }` blocks
    /// are type-checked and emitted as C functions, and a generated runner
    /// `main` replaces any user-defined `main`. When false (an ordinary
    /// compile), `test` blocks are parsed but otherwise completely ignored —
    /// not type-checked, not emitted — matching `zig build` vs `zig test`.
    test_mode: bool = false,

    /// When true (the `fun fuzz` CLI subcommand), exactly one `fuzz "name"
    /// (data, len) { ... }` block (selected by `fuzz_target`) is
    /// type-checked and emitted as a harness function under the fixed ABI
    /// name a coverage-guided fuzzing engine expects, replacing any
    /// user-defined `main` (the fuzzing engine supplies its own). When
    /// false, `fuzz` blocks are parsed but otherwise completely ignored —
    /// not type-checked, not emitted — same reasoning as `test_mode`.
    fuzz_mode: bool = false,
};

/// GlobalSymbolInfo tracks information about symbols across modules
pub const GlobalSymbolInfo = struct {
    symbol_name: []const u8,
    file_path: []const u8,
    is_function: bool,
    is_public: bool,
};

const ImplKey = struct {
    type_name: []const u8,
    quirk_sig: []const u8,
};

const GenericSpec = struct {
    cnode: *ast.Node,
    dt: *const dtype.DataType,
    mangled: []const u8,
};

const ImplKeyContext = struct {
    pub fn hash(_: @This(), key: ImplKey) u64 {
        const a = std.hash.Wyhash.hash(0, key.type_name);
        return std.hash.Wyhash.hash(a, key.quirk_sig);
    }

    pub fn eql(_: @This(), a: ImplKey, b: ImplKey) bool {
        return mem.eql(u8, a.type_name, b.type_name) and mem.eql(u8, a.quirk_sig, b.quirk_sig);
    }
};

pub const TypeRegistry = struct {
    allocator: mem.Allocator,

    /// Maps `enum` names to their defining heap node.
    enums_by_name: std.StringHashMap(*ast.Node),

    /// Maps `compound` names to their defining heap node.
    compounds_by_name: std.StringHashMap(*ast.Node),

    /// Maps quirk names to a canonical signature key.
    quirk_sig_by_name: std.StringHashMap([]const u8),

    /// Maps canonical signature key to the (first-seen) quirk definition node.
    quirks_by_sig: std.StringHashMap(*ast.Node),

    /// Caches hash(sig) for canonical quirk signature keys.
    quirk_hash_by_sig: std.StringHashMap(u64),

    /// Maps `<Type> + <QuirkSig>` to the impl definition node.
    impls_by_key: std.HashMap(ImplKey, *ast.Node, ImplKeyContext, 80),

    /// Owned allocations for registry-internal keys (quirk signatures, alias-qualified names).
    owned_keys: ArrayList([]const u8),

    pub fn init(allocator: mem.Allocator) TypeRegistry {
        return .{
            .allocator = allocator,
            .enums_by_name = std.StringHashMap(*ast.Node).init(allocator),
            .compounds_by_name = std.StringHashMap(*ast.Node).init(allocator),
            .quirk_sig_by_name = std.StringHashMap([]const u8).init(allocator),
            .quirks_by_sig = std.StringHashMap(*ast.Node).init(allocator),
            .quirk_hash_by_sig = std.StringHashMap(u64).init(allocator),
            .impls_by_key = std.HashMap(ImplKey, *ast.Node, ImplKeyContext, 80).init(allocator),
            .owned_keys = ArrayList([]const u8).init(allocator),
        };
    }

    pub fn deinit(self: *TypeRegistry) void {
        self.enums_by_name.deinit();
        self.compounds_by_name.deinit();
        self.quirk_sig_by_name.deinit();
        self.quirks_by_sig.deinit();
        self.quirk_hash_by_sig.deinit();
        self.impls_by_key.deinit();
        for (self.owned_keys.items) |key| {
            self.allocator.free(key);
        }
        self.owned_keys.deinit();
    }
};

pub const TranspileProcess = struct {
    const DeferScopeKind = enum {
        normal,
        loop,
        function,
    };

    const DeferEntry = struct {
        body: *ast.Node,
        pos: ?token.Pos,
    };

    const DeferScopeFrame = struct {
        start_index: usize,
        kind: DeferScopeKind,
    };

    /// Transpilation flags for this process.
    flags: TranspileProcessFlags,

    /// The specific fuzz target's name to compile when `flags.fuzz_mode` is
    /// set (a file may declare several `fuzz` blocks; the harness can only
    /// ever target one at a time). Required whenever more than one exists;
    /// auto-selected when there's exactly one. Not part of the packed
    /// `TranspileProcessFlags` bag since `?[]const u8` isn't bit-packable.
    fuzz_target: ?[]const u8 = null,

    /// I/O handle used for all file system operations.
    io: std.Io,

    /// Current token position for diagnostics.
    pos: token.Pos,

    /// When `flags.debug_info` is true, holds the Fun source position that the
    /// next `write_indent()` call should emit as a `#line` directive.
    pending_line_directive: ?token.Pos = null,

    /// Input/output file handles.
    ifile: std.Io.File,
    ofile: ?std.Io.File,
    outbuf: ?ArrayList(u8),

    /// Tracked read offset for cross-platform positional file reads.
    file_pos: u64 = 0,

    /// Token and node storage.
    tokens: utils.Vector(token.Token),
    nodes: utils.Vector(ast.Node),
    warnings: ArrayList(u8),
    pending_warning_allows: ArrayList(PendingWarningControl),
    pending_warning_expects: ArrayList(PendingWarningControl),
    owned_nodes: ArrayList(*ast.Node),
    owned_scope_entities: ArrayList(*scope.ScopeEntity),
    defer_stack: ArrayList(DeferEntry),
    defer_scope_stack: ArrayList(DeferScopeFrame),

    /// Scope tracking.
    scope: ?struct {
        root: ?*scope.Scope,
        current: ?*scope.Scope,
    } = null,

    /// Active symbol tables.
    symbols: struct {
        active_table: ?*symbol.SymbolTable,
        tables: utils.Vector(*symbol.SymbolTable),
    },

    /// Arena allocator used for most allocations.
    allocator: mem.Allocator,

    /// Current indentation level (4 spaces per level).
    indent_level: u32 = 0,

    /// Length of the run of consecutive trailing newlines written so far
    /// (across possibly many separate `write()` calls -- see `write`'s own
    /// doc comment). Used to collapse 2+ consecutive blank lines down to
    /// one wherever several independent emission passes each add their own
    /// trailing separator at a section boundary.
    consecutive_newlines: u32 = 0,

    /// Generic type substitution during emission.
    type_subst_params: ?*const utils.Vector(ArrayList(u8)) = null,
    type_subst_args: ?[]*dtype.DataType = null,

    /// The declared return type of the method body currently being emitted, used to
    /// monomorphize a constructed generic enum whose own param does not appear in the
    /// active substitution (e.g. `ret Option.None` inside `impl MapIter<K,V> as
    /// Iterator<K>`, whose return type `Option<K>` mangles to `Option__str`).
    current_method_return_dtype: ?*const dtype.DataType = null,

    /// Optional override for specialized function names during emission.
    override_fn_name: ?[]const u8 = null,

    /// Track if we're emitting function params/body.
    in_function_params: bool = false,
    in_function_body: bool = false,
    function_body_depth: usize = 0,
    in_main: bool = false,

    /// Track return type of current function (for warnings).
    current_fn_return: ?CheckedType = null,

    /// Track whether current function is variadic.
    current_fn_is_variadic: bool = false,

    /// Track whether current function is async (for await semantics in typecheck).
    current_fn_is_async: bool = false,

    /// The function/method node whose body is currently being typechecked
    /// (null outside any function body, e.g. while checking module globals).
    /// Stamped onto `GenericFnInstantiation.owner_fn` so a placeholder
    /// instantiation registered from a call site *inside a generic function's
    /// own template body* can later be resolved by identity, not by type-param
    /// NAME -- two unrelated generic functions overwhelmingly both name their
    /// type param "T", so name-only matching would wrongly cross-substitute.
    typecheck_owner_fn: ?*ast.Node = null,

    /// True while inferring the operand of an `await` unary expression.
    in_await_operand_inference: bool = false,

    /// True while inferring the call expression of a `fork` statement. A fork
    /// target is an async function invoked WITHOUT `await` (fire-and-forget), so
    /// the "async call must be awaited" guard is suppressed in this mode.
    in_fork_target_inference: bool = false,

    /// Source position of the top-level call currently being awaited.
    await_operand_target_pos: ?token.Pos = null,

    /// Temp name counter for codegen.
    tmp_counter: usize = 0,

    /// Current native-recursion depth of the expression walkers (`infer_expr_type`,
    /// `transpile_node`). Guarded against pathological nesting (deeply parenthesized
    /// expressions, very long flat operator chains) so the compiler reports a clean
    /// `ExpressionTooDeep` error instead of overflowing the native stack and
    /// segfaulting. The limit is generous — far beyond any human-written code.
    recursion_depth: usize = 0,

    /// True while emitting a context where a bare C brace-list `{...}` is the
    /// correct form for an array literal — an array variable's initializer, a 2D
    /// array row, or a compound-init field. When FALSE, an array literal sits in a
    /// value position (e.g. a call argument) and must be emitted as a C compound
    /// literal `(T[]){...}` instead, which is a valid expression.
    in_array_initializer: bool = false,

    /// One-time emission guards.
    did_emit_user_types: bool = false,
    did_emit_impls: bool = false,

    backing_allocator: mem.Allocator,

    /// Arena used for AST/scopes/registries (simplifies ownership and cleanup).
    arena: *std.heap.ArenaAllocator,

    /// Initialize a new indentation field to track active statement type
    current_statement_type: enum {
        None,
        If,
        ElseIf,
        Else,
        Other,
    } = .None,

    /// Track the next statement for proper formatting
    next_statement_type: enum {
        None,
        ElseIf,
        Else,
        Other,
    } = .None,

    /// Track imported files to avoid circular imports
    imported_files: std.StringHashMap(bool),

    /// Compile-wide set of canonical file paths that have already been lex/parsed,
    /// across all import branches. Meaningful only on the root process (children
    /// query/update it through `get_root()` via `imported_files_is_globally_parsed`
    /// / `mark_globally_parsed`). Prevents diamond imports from re-parsing the
    /// same module once per branch. Keys are owned by the root's arena.
    globally_parsed_files: std.StringHashMap(bool),

    /// Forced generic instantiations discovered during typecheck.
    forced_generic_instantiations: ArrayList(*const dtype.DataType),
    forced_generic_instantiation_keys: std.StringHashMap(bool),

    /// Mangled names of emitted generic compound specializations.
    emitted_generic_spec_keys: std.StringHashMap(bool),

    /// Forced generic function instantiations discovered during typecheck.
    generic_fn_instantiations: ArrayList(GenericFnInstantiation),
    generic_fn_instantiation_keys: std.StringHashMap(bool),

    /// Call-site overrides for generic function names (keyed by position).
    generic_call_overrides: std.StringHashMap([]const u8),

    /// Per-construction-site override mapping a generic data-enum variant
    /// construction (`Option.Some(5)` / `.Some(5)`) to the MANGLED instance name
    /// (`Option__num`) resolved from the expected type at typecheck. Codegen reads
    /// it so the emitted compound literal/cast uses `Option__num` + `Option__num_Some`
    /// instead of the bare template name. Keyed by call-position like the other maps.
    enum_ctor_overrides: std.StringHashMap([]const u8),

    /// Call-site overrides for await lowering (resolved callee + receiver strategy).
    await_call_overrides: std.StringHashMap(AwaitCallOverride),

    /// Per-for-statement overrides for `for item : <iterable>` element typing
    /// over a Vec (see `ForIterInfo`'s own doc comment), keyed by position
    /// like the other override maps above.
    for_iter_overrides: std.StringHashMap(ForIterInfo),

    /// Import chain to detect circular dependencies
    import_chain: ArrayList([]const u8),

    /// Track global symbols across all modules to detect duplicates
    global_symbols: std.StringHashMap(GlobalSymbolInfo),

    /// Import aliases declared in this module (`alias` -> import path).
    import_aliases: std.StringHashMap([]const u8),

    /// Optional override for import alias resolution (used while emitting child modules).
    import_aliases_override: ?*std.StringHashMap([]const u8) = null,

    /// If this process came from an aliased import, the alias namespace.
    import_alias: ?[]const u8 = null,

    /// While emitting child modules, this tracks which module's file path
    /// is currently being emitted (used for symbol qualification).
    emit_input_file_path: ?[]const u8 = null,

    /// While emitting child modules, this tracks the current module process
    /// so identifier emission can resolve local function names.
    emit_module_proc: ?*TranspileProcess = null,

    /// Registry for user-defined types (`compound`/`quirk`/`impl`).
    /// Stored only on the root process; children access it through `get_root()`.
    type_registry: ?TypeRegistry = null,

    /// Parent TranspileProcess if this is a child import process
    parent: ?*TranspileProcess = null,

    /// Child import processes
    children: ArrayList(*TranspileProcess),

    /// Standard library imports to be added at the beginning of the output
    std_imports: ArrayList([]const u8),

    /// True when `std.c.thread` or `std.c.thread_windows` is imported
    /// anywhere in this module tree.
    /// When set, codegen emits a small Windows compatibility layer that maps
    /// pthread-shaped symbols onto Win32 synchronization/thread primitives.
    requires_thread_compat_layer: bool = false,

    /// True when `std.c.process` is imported anywhere in this module tree.
    /// On POSIX this just needs the real `spawn.h`/`sys/wait.h`/`unistd.h`
    /// headers; on Windows there is no `posix_spawn`/`waitpid` equivalent at
    /// all, so codegen emits a small compat layer built on `CreateProcess`.
    requires_process_compat_layer: bool = false,

    /// True when a `fork` statement appears anywhere in this module tree. Gates the
    /// M:N scheduler runtime in the prelude and the `__fun_sched_wait_idle()` call at
    /// each `main` exit, plus the per-callee `__fun_fork_*` support helpers. Set by a
    /// pre-scan (uses_fork_recursive) before the prelude is emitted.
    uses_fork: bool = false,

    /// True when `std.c.net` is imported anywhere in this module tree.
    /// When set, codegen emits host-specific socket headers and Windows
    /// close-socket compatibility aliases.
    requires_net_compat_layer: bool = false,

    /// The input file path (used for relative path resolution)
    input_file_path: []const u8,

    /// Full source contents of the input file.
    /// Used for exact span-preserving features (e.g. raw asm blocks).
    input_source: []const u8,

    /// Standard library root directory (expected to contain `std/`), if discovered.
    /// Typical installed layout is: `<prefix>/share/fun/std/*.fn`.
    stdlib_dir: ?[]const u8 = null,

    /// Whether the current file is importing other files
    is_importing: bool = false,

    /// The current token being processed
    current_token: ?token.Token = null,

    const Self = @This();

    fn is_abs_path(path: []const u8) bool {
        return std.fs.path.isAbsolute(path);
    }

    fn globalIo() std.Io {
        return std.Io.Threaded.global_single_threaded.io();
    }

    fn dir_exists(path: []const u8) bool {
        const io = globalIo();
        if (is_abs_path(path)) {
            var d = std.Io.Dir.openDirAbsolute(io, path, .{}) catch return false;
            d.close(io);
            return true;
        }
        var d = std.Io.Dir.cwd().openDir(io, path, .{}) catch return false;
        d.close(io);
        return true;
    }

    fn dupe_arena(a: mem.Allocator, s: []const u8) TranspileError![]const u8 {
        return a.dupe(u8, s) catch TranspileError.MemoryAllocationFailed;
    }

    fn join_alloc(allocator: mem.Allocator, parts: []const []const u8) TranspileError![]const u8 {
        return std.fs.path.join(allocator, parts) catch TranspileError.MemoryAllocationFailed;
    }

    fn discover_stdlib_dir(backing: mem.Allocator, a: mem.Allocator) TranspileError!?[]const u8 {
        const io = globalIo();
        // 1) Explicit override (best for installers and CI)
        if (std.c.getenv("FUN_STDLIB_DIR")) |z| {
            const p = std.mem.sliceTo(z, 0);
            if (p.len > 0) return try dupe_arena(a, p);
        }

        // 2) Relative to executable: `<exe_dir>/../share/fun`
        const exe_path = std.process.executablePathAlloc(io, backing) catch null;
        if (exe_path) |exe| {
            defer backing.free(exe);
            const exe_dir = std.fs.path.dirname(exe) orelse null;
            if (exe_dir) |d| {
                const prefix_dir = std.fs.path.dirname(d) orelse d;
                const cand = try join_alloc(backing, &[_][]const u8{ prefix_dir, "share", "fun" });
                defer backing.free(cand);
                if (dir_exists(cand)) return try dupe_arena(a, cand);
            }
        }

        // 3) Dev-tree fallbacks (when running from repo root)
        {
            const cand_workspace = "stdlib";
            if (dir_exists(cand_workspace)) {
                const abs = std.Io.Dir.cwd().realPathFileAlloc(io, cand_workspace, backing) catch null;
                if (abs) |p| {
                    defer backing.free(p);
                    return try dupe_arena(a, p);
                }
                return try dupe_arena(a, cand_workspace);
            }

            const cand_install = "zig-out/share/fun";
            if (dir_exists(cand_install)) {
                const abs = std.Io.Dir.cwd().realPathFileAlloc(io, cand_install, backing) catch null;
                if (abs) |p| {
                    defer backing.free(p);
                    return try dupe_arena(a, p);
                }
                return try dupe_arena(a, cand_install);
            }
        }

        // 4) Common system locations
        if (builtin.target.os.tag == .windows) {
            if (std.c.getenv("LOCALAPPDATA")) |z| {
                const base = std.mem.sliceTo(z, 0);
                const cand = try join_alloc(backing, &[_][]const u8{ base, "fun", "share", "fun" });
                defer backing.free(cand);
                if (dir_exists(cand)) return try dupe_arena(a, cand);
            }
            if (std.c.getenv("ProgramFiles")) |z| {
                const base = std.mem.sliceTo(z, 0);
                const cand = try join_alloc(backing, &[_][]const u8{ base, "fun", "share", "fun" });
                defer backing.free(cand);
                if (dir_exists(cand)) return try dupe_arena(a, cand);
            }
        } else {
            const cand1 = "/usr/local/share/fun";
            if (dir_exists(cand1)) return try dupe_arena(a, cand1);
            const cand2 = "/usr/share/fun";
            if (dir_exists(cand2)) return try dupe_arena(a, cand2);

            if (std.c.getenv("HOME")) |z| {
                const h = std.mem.sliceTo(z, 0);
                const cand = try join_alloc(backing, &[_][]const u8{ h, ".local", "share", "fun" });
                defer backing.free(cand);
                if (dir_exists(cand)) return try dupe_arena(a, cand);
            }
        }

        return null;
    }

    fn is_await_dynamic_quirk_dispatch(self: *Self, call_node: ast.Node) bool {
        if (self.lookup_await_call_override(call_node)) |ov| {
            if (ov.dynamic_quirk_dispatch) return true;
        }

        if (call_node.type != .Expression or call_node.node_variant == null or !mem.eql(u8, call_node.node_variant.?.exp.op, "()")) {
            return false;
        }
        const call = call_node.node_variant.?.exp;
        const callee = call.left orelse return false;
        if (callee.*.type != .Expression or callee.*.node_variant == null or !mem.eql(u8, callee.*.node_variant.?.exp.op, ".")) {
            return false;
        }
        const dot = callee.*.node_variant.?.exp;
        const recv = dot.left orelse return false;
        return self.expr_is_quirk_typed_from_scope(recv.*);
    }

    fn discover_stdlib_dir_near_input(backing: mem.Allocator, a: mem.Allocator, ifilepath: []const u8) TranspileError!?[]const u8 {
        const io = globalIo();
        const abs = if (std.fs.path.isAbsolute(ifilepath))
            (backing.dupe(u8, ifilepath) catch return TranspileError.MemoryAllocationFailed)
        else blk: {
            const rp = std.Io.Dir.cwd().realPathFileAlloc(io, ifilepath, backing) catch return null;
            break :blk rp;
        };
        defer backing.free(abs);

        var cur_dir = std.fs.path.dirname(abs) orelse return null;
        var depth: usize = 0;
        while (depth < 12) : (depth += 1) {
            const cand = try join_alloc(backing, &[_][]const u8{ cur_dir, "stdlib" });
            defer backing.free(cand);
            if (dir_exists(cand)) {
                const resolved = std.Io.Dir.cwd().realPathFileAlloc(io, cand, backing) catch null;
                if (resolved) |r| {
                    defer backing.free(r);
                    return try dupe_arena(a, r);
                }
                return try dupe_arena(a, cand);
            }

            const parent_opt = std.fs.path.dirname(cur_dir);
            if (parent_opt == null) break;
            const parent = parent_opt.?;
            if (parent.len == cur_dir.len) break;
            cur_dir = parent;
        }

        return null;
    }

    fn normalize_stdlib_dir(backing: mem.Allocator, a: mem.Allocator, candidate: []const u8) TranspileError![]const u8 {
        const candidate_std = try join_alloc(backing, &[_][]const u8{ candidate, "std" });
        defer backing.free(candidate_std);
        if (dir_exists(candidate_std)) {
            return try dupe_arena(a, candidate);
        }

        const base = std.fs.path.basename(candidate);
        if (std.mem.eql(u8, base, "std")) {
            const parent = std.fs.path.dirname(candidate) orelse candidate;
            const parent_std = try join_alloc(backing, &[_][]const u8{ parent, "std" });
            defer backing.free(parent_std);
            if (dir_exists(parent_std)) {
                return try dupe_arena(a, parent);
            }
        }

        return try dupe_arena(a, candidate);
    }

    fn get_root(self: *Self) *Self {
        var cur: *Self = self;
        while (cur.parent) |p| {
            cur = p;
        }
        return cur;
    }

    /// Compile-wide dedup: has this canonical file already been lex/parsed
    /// anywhere in the current import tree? Tracked on the root process so that
    /// a module reachable through multiple sibling branches (a diamond import)
    /// is parsed exactly once instead of once per branch. Public symbols still
    /// reach every consumer via `sync_global_symbols_to_parent`, which walks up
    /// to the root, so skipping the redundant re-parse is behavior-preserving.
    fn imported_files_is_globally_parsed(self: *Self, canon: []const u8) bool {
        return self.get_root().globally_parsed_files.contains(canon);
    }

    /// Record (best-effort) that `canon` has been parsed compile-wide. The key
    /// is duped into the root's arena so it outlives this child process. A
    /// failure here is non-fatal: it only forfeits the dedup for this file.
    fn mark_globally_parsed(self: *Self, canon: []const u8) void {
        const root = self.get_root();
        if (root.globally_parsed_files.contains(canon)) return;
        const key = root.allocator.dupe(u8, canon) catch return;
        root.globally_parsed_files.put(key, true) catch {};
    }

    fn find_process_for_file(self: *Self, filename: []const u8) ?*TranspileProcess {
        if (std.mem.eql(u8, self.input_file_path, filename)) return self;
        const fname_base = std.fs.path.basename(filename);
        if (std.mem.eql(u8, std.fs.path.basename(self.input_file_path), fname_base)) return self;
        for (self.children.items) |child| {
            if (child.find_process_for_file(filename)) |found| return found;
        }
        return null;
    }

    fn find_import_alias_path(self: *Self, alias: []const u8) ?[]const u8 {
        if (self.import_aliases.get(alias)) |p| return p;
        for (self.children.items) |child| {
            if (child.find_import_alias_path(alias)) |p| return p;
        }
        return null;
    }

    fn make_alias_qualified_symbol_name(self: *Self, alias: []const u8, name: []const u8) TranspileError![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        defer buf.deinit();
        buf.appendSlice(alias) catch return TranspileError.MemoryAllocationFailed;
        buf.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
        buf.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;
        return buf.toOwnedSlice() catch TranspileError.MemoryAllocationFailed;
    }

    fn register_import_alias(self: *Self, alias: []const u8, import_path: []const u8) TranspileError!void {
        if (self.import_aliases.get(alias)) |existing| {
            if (!mem.eql(u8, existing, import_path)) {
                self.err("Import alias '{s}' already used for '{s}'", .{ alias, existing });
                return TranspileError.DuplicateSymbol;
            }
            return;
        }
        const alias_copy = self.allocator.dupe(u8, alias) catch return TranspileError.MemoryAllocationFailed;
        errdefer self.allocator.free(alias_copy);
        const path_copy = self.allocator.dupe(u8, import_path) catch return TranspileError.MemoryAllocationFailed;
        errdefer self.allocator.free(path_copy);
        self.import_aliases.put(alias_copy, path_copy) catch return TranspileError.MemoryAllocationFailed;
    }

    fn alias_map_for_node(self: *Self, ref_node: ?*const ast.Node) *const std.StringHashMap([]const u8) {
        if (self.import_aliases_override) |m| return m;
        if (ref_node) |n| {
            if (n.pos) |p| {
                const root = self.get_root();
                if (root.find_process_for_file(p.filename)) |proc| {
                    return &proc.import_aliases;
                }
            }
        }
        return &self.import_aliases;
    }

    fn resolve_alias_qualified_symbol_name(self: *Self, ref_node: ?*const ast.Node, alias: []const u8, name: []const u8) TranspileError!?[]const u8 {
        const alias_map = self.alias_map_for_node(ref_node);
        const import_path = alias_map.get(alias);
        if (import_path == null) return null;
        self.mark_import_used_by_alias(alias);
        const import_path_unwrapped = import_path.?;
        if (std.mem.startsWith(u8, import_path_unwrapped, "std.c.")) {
            return self.allocator.dupe(u8, name) catch TranspileError.MemoryAllocationFailed;
        }
        return try self.make_alias_qualified_symbol_name(alias, name);
    }

    /// True when `alias` (in the scope of `ref_node`) resolves to a `std.c.*`
    /// C-binding module. Such calls emit the RAW libc symbol name (e.g. `log`,
    /// `pow`) rather than an `alias__fn` mangling, which is why their bare name
    /// can collide in the typecheck `fns` map with an unrelated stdlib function
    /// of the same name (e.g. `std.log`'s `log(LogLevel, str)`). Inference must
    /// therefore look these up under an alias-qualified key, not the bare name.
    fn alias_is_c_binding(self: *Self, ref_node: ?*const ast.Node, alias: []const u8) bool {
        const alias_map = self.alias_map_for_node(ref_node);
        const import_path = alias_map.get(alias) orelse return false;
        return std.mem.startsWith(u8, import_path, "std.c.");
    }

    /// Build a C name for a helper function that lives in the same module as the current call.
    /// When the call was `alias.fn(...)`, `module_alias` is `"alias"` and the result is
    /// `"alias__fn_name"`.  When there is no module alias (bare `fn(...)`), returns `fn_name`.
    /// Caller must free the returned slice with self.allocator.
    fn prefixed_fn_name(self: *Self, module_alias: ?[]const u8, fn_name: []const u8) TranspileError![]const u8 {
        if (module_alias) |alias| {
            return std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ alias, fn_name }) catch TranspileError.MemoryAllocationFailed;
        }
        return self.allocator.dupe(u8, fn_name) catch TranspileError.MemoryAllocationFailed;
    }

    fn ensure_type_registry(self: *Self) *TypeRegistry {
        const root = self.get_root();
        if (root.type_registry == null) {
            root.type_registry = TypeRegistry.init(root.allocator);
        }
        return &root.type_registry.?;
    }

    fn append_dtype_sig(self: *Self, buf: *ArrayList(u8), dt: *const dtype.DataType) TranspileError!void {
        buf.appendSlice(dt.type_str.items) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        if (dt.generic_args) |gargs| {
            buf.append('<') catch return TranspileError.MemoryAllocationFailed;
            for (gargs.items(), 0..) |ga, i| {
                if (i != 0) buf.appendSlice(",") catch return TranspileError.MemoryAllocationFailed;
                try self.append_dtype_sig(buf, ga);
            }
            buf.append('>') catch return TranspileError.MemoryAllocationFailed;
        }
        if (dt.pointer_depth > 0) {
            var i: usize = 0;
            while (i < dt.pointer_depth) : (i += 1) {
                buf.append('*') catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
        }
        if (dt.array) |arr| {
            var i: usize = 0;
            while (i < arr.brackets.count) : (i += 1) {
                buf.appendSlice("[]") catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
        }
    }

    fn quirk_signature_key(self: *Self, qnode: *ast.Node) TranspileError![]const u8 {
        if (qnode.node_variant == null) return TranspileError.UnsupportedNodeType;
        const q = qnode.node_variant.?.quirk;

        var buf = ArrayList(u8).init(self.allocator);
        defer buf.deinit();

        const methods = q.methods.items();
        var idxs = self.allocator.alloc(usize, methods.len) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        defer self.allocator.free(idxs);
        for (methods, 0..) |_, i| idxs[i] = i;

        // Structural equivalence should not depend on declaration order.
        std.sort.pdq(usize, idxs, methods, struct {
            fn lessThan(ctx: []const ast.QuirkMethodSig, a: usize, b: usize) bool {
                return mem.lessThan(u8, ctx[a].name.items, ctx[b].name.items);
            }
        }.lessThan);

        for (idxs) |mi| {
            const m = methods[mi];

            if (m.is_async) {
                buf.appendSlice("async ") catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }

            buf.appendSlice(m.name.items) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            buf.append('(') catch {
                return TranspileError.MemoryAllocationFailed;
            };

            const args = m.args.items();
            for (args, 0..) |a, ai| {
                if (ai != 0) {
                    buf.appendSlice(",") catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }
                try self.append_dtype_sig(&buf, a.dtype);
            }

            buf.appendSlice(")->") catch {
                return TranspileError.MemoryAllocationFailed;
            };
            try self.append_dtype_sig(&buf, &m.rtype);
            buf.append(';') catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        const owned = buf.toOwnedSlice() catch {
            return TranspileError.MemoryAllocationFailed;
        };
        return owned;
    }

    fn collect_type_registry_module(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        for (proc.owned_nodes.items) |n| {
            if (self.is_std_c_signature_node(n)) continue;
            switch (n.type) {
                .Enum => {
                    if (n.node_variant == null) continue;
                    const name = n.node_variant.?.enum_decl.name.items;
                    if (reg.enums_by_name.get(name)) |existing| {
                        if (!self.same_node_file(n, existing)) return TranspileError.DuplicateSymbol;
                        // See the Compound branch: still owe the alias-qualified key
                        // when this proc is an aliased re-import of an already-seen
                        // type, so `alias.EnumType` annotations resolve.
                        if (proc.import_alias) |alias| {
                            const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                            if (reg.enums_by_name.contains(alias_name)) {
                                self.allocator.free(alias_name);
                            } else {
                                reg.enums_by_name.put(alias_name, existing) catch {
                                    self.allocator.free(alias_name);
                                    return TranspileError.MemoryAllocationFailed;
                                };
                                reg.owned_keys.append(alias_name) catch {
                                    self.allocator.free(alias_name);
                                    return TranspileError.MemoryAllocationFailed;
                                };
                            }
                        }
                        continue;
                    }
                    if (reg.compounds_by_name.contains(name) or reg.quirk_sig_by_name.contains(name)) {
                        return TranspileError.DuplicateSymbol;
                    }
                    reg.enums_by_name.put(name, n) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };

                    if (proc.import_alias) |alias| {
                        const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                        if (reg.enums_by_name.get(alias_name)) |existing| {
                            if (!self.same_node_file(n, existing)) {
                                self.allocator.free(alias_name);
                                return TranspileError.DuplicateSymbol;
                            }
                            self.allocator.free(alias_name);
                        } else {
                            reg.enums_by_name.put(alias_name, n) catch {
                                self.allocator.free(alias_name);
                                return TranspileError.MemoryAllocationFailed;
                            };
                            reg.owned_keys.append(alias_name) catch {
                                self.allocator.free(alias_name);
                                return TranspileError.MemoryAllocationFailed;
                            };
                        }
                    }
                },
                .Compound => {
                    if (n.node_variant == null) continue;
                    const name = n.node_variant.?.compound.name.items;
                    if (reg.compounds_by_name.get(name)) |existing| {
                        if (!self.same_node_file(n, existing)) return TranspileError.DuplicateSymbol;
                        // The bare name is already registered (same stdlib type
                        // imported both unaliased — transitively — and aliased). If
                        // THIS proc carries an import alias we still owe the
                        // alias-qualified type key (`s__StringBuilder`) so an
                        // `s.StringBuilder` annotation resolves. Mirrors the FnSig
                        // fix in collect_fn_sigs.
                        if (proc.import_alias) |alias| {
                            const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                            if (reg.compounds_by_name.contains(alias_name)) {
                                self.allocator.free(alias_name);
                            } else {
                                reg.compounds_by_name.put(alias_name, existing) catch {
                                    self.allocator.free(alias_name);
                                    return TranspileError.MemoryAllocationFailed;
                                };
                                reg.owned_keys.append(alias_name) catch {
                                    self.allocator.free(alias_name);
                                    return TranspileError.MemoryAllocationFailed;
                                };
                            }
                        }
                        continue;
                    }
                    reg.compounds_by_name.put(name, n) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };

                    if (proc.import_alias) |alias| {
                        const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                        if (reg.compounds_by_name.get(alias_name)) |existing| {
                            if (!self.same_node_file(n, existing)) {
                                self.allocator.free(alias_name);
                                return TranspileError.DuplicateSymbol;
                            }
                            self.allocator.free(alias_name);
                        } else {
                            reg.compounds_by_name.put(alias_name, n) catch {
                                self.allocator.free(alias_name);
                                return TranspileError.MemoryAllocationFailed;
                            };
                            reg.owned_keys.append(alias_name) catch {
                                self.allocator.free(alias_name);
                                return TranspileError.MemoryAllocationFailed;
                            };
                        }
                    }
                },
                .Quirk => {
                    if (n.node_variant == null) continue;
                    const name = n.node_variant.?.quirk.name.items;

                    // Compute signature, but only keep one allocated key per unique signature.
                    const sig_key_tmp = try self.quirk_signature_key(n);
                    const sig_hash = std.hash.Wyhash.hash(0, sig_key_tmp);

                    const gop = reg.quirks_by_sig.getOrPut(sig_key_tmp) catch {
                        reg.allocator.free(sig_key_tmp);
                        return TranspileError.MemoryAllocationFailed;
                    };

                    const sig_key = gop.key_ptr.*;
                    if (gop.found_existing) {
                        const existing = gop.value_ptr.*;
                        if (!self.same_node_file(n, existing)) {
                            reg.allocator.free(sig_key_tmp);
                            return TranspileError.DuplicateSymbol;
                        }
                        // Not inserted; free the temporary signature string.
                        reg.allocator.free(sig_key_tmp);
                    } else {
                        // Inserted; keep and free at registry teardown.
                        reg.owned_keys.append(sig_key) catch {
                            reg.allocator.free(sig_key);
                            return TranspileError.MemoryAllocationFailed;
                        };
                        gop.value_ptr.* = n;
                    }

                    // Cache hash(sig) for fast codegen naming.
                    if (!reg.quirk_hash_by_sig.contains(sig_key)) {
                        reg.quirk_hash_by_sig.put(sig_key, sig_hash) catch {
                            return TranspileError.MemoryAllocationFailed;
                        };
                    }

                    // Map name -> canonical signature.
                    if (reg.quirk_sig_by_name.get(name)) |existing_sig| {
                        const existing_node = reg.quirks_by_sig.get(existing_sig) orelse null;
                        if (existing_node == null or !self.same_node_file(n, existing_node.?)) {
                            return TranspileError.DuplicateSymbol;
                        }
                    } else {
                        reg.quirk_sig_by_name.put(name, sig_key) catch {
                            return TranspileError.MemoryAllocationFailed;
                        };
                    }

                    if (proc.import_alias) |alias| {
                        const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                        if (reg.quirk_sig_by_name.get(alias_name)) |existing_sig| {
                            const existing_node = reg.quirks_by_sig.get(existing_sig) orelse null;
                            if (existing_node == null or !self.same_node_file(n, existing_node.?)) {
                                self.allocator.free(alias_name);
                                return TranspileError.DuplicateSymbol;
                            }
                            self.allocator.free(alias_name);
                        } else {
                            reg.quirk_sig_by_name.put(alias_name, sig_key) catch {
                                self.allocator.free(alias_name);
                                return TranspileError.MemoryAllocationFailed;
                            };
                            reg.owned_keys.append(alias_name) catch {
                                self.allocator.free(alias_name);
                                return TranspileError.MemoryAllocationFailed;
                            };
                        }
                    }
                },
                .Impl => {
                    // Collected in a second pass after all quirks are known.
                },
                else => {},
            }
        }
    }

    fn collect_type_registry_recursive(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        try self.collect_type_registry_module(proc, reg);
        for (proc.children.items) |child| {
            try self.collect_type_registry_recursive(child, reg);
        }
    }

    /// Post-pass mirroring `register_alias_stub_sigs` but for the TYPE registry:
    /// an aliased re-import of an already-parsed module is a node-less stub, so
    /// `collect_type_registry_module` registers no `alias__Type` keys for it. Here
    /// we find the real parsed proc for the stub's module and mirror each of its
    /// compound/enum names under the stub's alias, so an `s.StringBuilder`
    /// annotation (mangled `s__StringBuilder`) resolves. Runs AFTER the recursive
    /// collection so all bare type names are present.
    fn register_alias_stub_types(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        const is_node_less = proc.nodes.items().len == 0 and proc.owned_nodes.items.len == 0;
        if (is_node_less) {
            if (proc.import_alias) |alias| {
                if (self.find_parsed_proc_by_path(proc.input_file_path)) |real| {
                    try self.mirror_alias_types_from_proc(real, alias, reg);
                }
            }
        }
        for (proc.children.items) |child| {
            try self.register_alias_stub_types(child, reg);
        }
    }

    fn mirror_alias_types_from_proc(self: *Self, src: *Self, alias: []const u8, reg: *TypeRegistry) TranspileError!void {
        for (src.owned_nodes.items) |n| {
            if (n.node_variant == null) continue;
            const bare: []const u8 = switch (n.type) {
                .Compound => n.node_variant.?.compound.name.items,
                .Enum => n.node_variant.?.enum_decl.name.items,
                else => continue,
            };
            const alias_name = try self.make_alias_qualified_symbol_name(alias, bare);
            switch (n.type) {
                .Compound => {
                    if (reg.compounds_by_name.contains(alias_name)) {
                        self.allocator.free(alias_name);
                        continue;
                    }
                    const existing = reg.compounds_by_name.get(bare) orelse n;
                    reg.compounds_by_name.put(alias_name, existing) catch {
                        self.allocator.free(alias_name);
                        return TranspileError.MemoryAllocationFailed;
                    };
                    reg.owned_keys.append(alias_name) catch {
                        self.allocator.free(alias_name);
                        return TranspileError.MemoryAllocationFailed;
                    };
                },
                .Enum => {
                    if (reg.enums_by_name.contains(alias_name)) {
                        self.allocator.free(alias_name);
                        continue;
                    }
                    const existing = reg.enums_by_name.get(bare) orelse n;
                    reg.enums_by_name.put(alias_name, existing) catch {
                        self.allocator.free(alias_name);
                        return TranspileError.MemoryAllocationFailed;
                    };
                    reg.owned_keys.append(alias_name) catch {
                        self.allocator.free(alias_name);
                        return TranspileError.MemoryAllocationFailed;
                    };
                },
                else => self.allocator.free(alias_name),
            }
        }
    }

    fn collect_impls_module(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const imp = n.node_variant.?.impl;
            const type_name = imp.type_name.items;

            // Plain impl blocks (`impl Type { ... }`) are not part of the quirk registry.
            const quirk_name = if (imp.quirk_name) |qn| qn.items else continue;

            const sig = reg.quirk_sig_by_name.get(quirk_name) orelse quirk_name;

            // Validate: quirk impl must implement all quirk methods. For a
            // concrete instantiation (`impl Config as From<JsonValue>`),
            // validate against the SUBSTITUTED signature (`synthesize_quirk_instantiations_recursive`
            // already registered it above, under `quirk_concrete_instantiation`'s
            // mangled name) rather than the generic template — otherwise the
            // missing-method list/stub reports the bare type param (`from(T value)`)
            // instead of the concrete arg (`from(JsonValue value)`).
            const validate_sig = if (imp.quirk_concrete_instantiation) |qci|
                reg.quirk_sig_by_name.get(qci.items) orelse sig
            else
                sig;
            try proc.validate_quirk_impl_complete(n, type_name, quirk_name, validate_sig, reg);

            const key: ImplKey = .{ .type_name = type_name, .quirk_sig = sig };
            if (reg.impls_by_key.get(key)) |existing| {
                if (!self.same_node_file(n, existing)) return TranspileError.DuplicateSymbol;
            } else {
                reg.impls_by_key.put(key, n) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }

            // A CONCRETE instantiation binding (`impl Point as To<num>`, or
            // `impl Counter as Iterator<num>` where Counter isn't generic) is
            // ALSO registered under its own distinct quirk identity
            // (`synthesize_quirk_instantiations_module` already registered
            // `To__num`'s substituted sig by this point), in ADDITION to the
            // bare-name registration above — so a quirk-typed parameter or
            // variable naming that same concrete instantiation can dispatch to
            // this impl too, without disturbing any existing mechanism that
            // keys off the bare quirk name.
            if (imp.quirk_concrete_instantiation) |qci| {
                const inst_name = qci.items;
                if (reg.quirk_sig_by_name.get(inst_name)) |inst_sig| {
                    const inst_key: ImplKey = .{ .type_name = type_name, .quirk_sig = inst_sig };
                    if (!reg.impls_by_key.contains(inst_key)) {
                        reg.impls_by_key.put(inst_key, n) catch {
                            return TranspileError.MemoryAllocationFailed;
                        };
                    }
                }
            }
        }
    }

    fn collect_impls_recursive(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        try self.collect_impls_module(proc, reg);
        for (proc.children.items) |child| {
            try self.collect_impls_recursive(child, reg);
        }
    }

    /// Register a concrete (non-generic) synthesized quirk for `mangled_name`
    /// (e.g. `To__num`, from `impl Point as To<num>` — see the parser's
    /// concrete-vs-symbolic quirk-arg mangling) if not already registered.
    /// Substitutes the base generic quirk's own type params into a cloned
    /// method list, computes the substituted structural signature the same
    /// way an ordinary concrete quirk declaration would, and registers it so
    /// every existing quirk mechanism (dispatch, vtable/coercion codegen,
    /// `impls_by_key` validation) treats it exactly like a hand-written
    /// non-generic quirk — no changes needed anywhere else.
    fn synthesize_quirk_instantiation(self: *Self, reg: *TypeRegistry, mangled_name: []const u8) TranspileError!void {
        if (reg.quirk_sig_by_name.contains(mangled_name)) return;

        const dt = (try self.dtype_from_mangled_type(mangled_name)) orelse return;
        const base_name = dt.type_str.items;
        const base_sig = reg.quirk_sig_by_name.get(base_name) orelse return;
        const base_qnode = reg.quirks_by_sig.get(base_sig) orelse return;
        if (base_qnode.node_variant == null) return;
        const base_q = base_qnode.node_variant.?.quirk;
        if (!base_q.is_generic) return; // already concrete; nothing to synthesize
        const base_params = base_q.type_params orelse return;
        const concrete_args = dt.generic_args orelse return;
        if (concrete_args.items().len != base_params.count) return; // arity mismatch: let normal validation report it

        var new_methods = utils.Vector(ast.QuirkMethodSig).init(reg.allocator);
        for (base_q.methods.items()) |m| {
            var new_args = utils.Vector(ast.QuirkArg).init(reg.allocator);
            for (m.args.items()) |a| {
                const substituted = try self.clone_dtype_with_subst_for_inst(a.dtype, &base_params, concrete_args.items());
                var aname = ArrayList(u8).init(reg.allocator);
                aname.appendSlice(a.name.items) catch return TranspileError.MemoryAllocationFailed;
                new_args.push(.{ .name = aname, .dtype = substituted }) catch return TranspileError.MemoryAllocationFailed;
            }
            const new_rtype_ptr = try self.clone_dtype_with_subst_for_inst(&m.rtype, &base_params, concrete_args.items());
            const new_rtype = new_rtype_ptr.*;
            reg.allocator.destroy(new_rtype_ptr);
            var mname = ArrayList(u8).init(reg.allocator);
            mname.appendSlice(m.name.items) catch return TranspileError.MemoryAllocationFailed;
            new_methods.push(.{ .name = mname, .rtype = new_rtype, .args = new_args, .is_async = m.is_async }) catch return TranspileError.MemoryAllocationFailed;
        }

        var qname_copy = ArrayList(u8).init(reg.allocator);
        qname_copy.appendSlice(mangled_name) catch return TranspileError.MemoryAllocationFailed;

        const new_node = reg.allocator.create(ast.Node) catch return TranspileError.MemoryAllocationFailed;
        new_node.* = ast.Node{
            .type = .Quirk,
            .pos = base_qnode.pos,
            // Inherit the base quirk's visibility — `can_access` checks
            // `is_public or same_module`, and this synthesized node's `.pos`
            // points at the base quirk's declaring file, which is almost
            // always a different module than the call site using `To<num>`.
            .flags = base_qnode.flags,
            .node_variant = .{ .quirk = .{ .name = qname_copy, .methods = new_methods, .is_generic = false, .type_params = null } },
        };

        const sig_key = try self.quirk_signature_key(new_node);
        const gop = reg.quirks_by_sig.getOrPut(sig_key) catch {
            reg.allocator.free(sig_key);
            return TranspileError.MemoryAllocationFailed;
        };
        if (gop.found_existing) {
            reg.allocator.free(sig_key);
        } else {
            reg.owned_keys.append(sig_key) catch {
                reg.allocator.free(sig_key);
                return TranspileError.MemoryAllocationFailed;
            };
            gop.value_ptr.* = new_node;
        }

        // Own a durable copy of the name for the map key — callers may pass a
        // temporary buffer (e.g. a freshly mangled name from a type annotation
        // scan), not just an AST-owned string (e.g. an impl's `quirk_name`).
        const name_key = reg.allocator.dupe(u8, mangled_name) catch return TranspileError.MemoryAllocationFailed;
        reg.owned_keys.append(name_key) catch {
            reg.allocator.free(name_key);
            return TranspileError.MemoryAllocationFailed;
        };
        reg.quirk_sig_by_name.put(name_key, gop.key_ptr.*) catch return TranspileError.MemoryAllocationFailed;
    }

    fn synthesize_quirk_instantiations_module(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const imp = n.node_variant.?.impl;
            const mangled_name = if (imp.quirk_concrete_instantiation) |qn| qn.items else continue;
            try self.synthesize_quirk_instantiation(reg, mangled_name);
        }
    }

    fn synthesize_quirk_instantiations_recursive(self: *Self, proc: *Self, reg: *TypeRegistry) TranspileError!void {
        try self.synthesize_quirk_instantiations_module(proc, reg);
        for (proc.children.items) |child| {
            try self.synthesize_quirk_instantiations_recursive(child, reg);
        }
    }

    /// A library function can declare a quirk-typed parameter (`fun
    /// to_json_value(To<JsonValue> value) JsonValue { ret value.to(); }`) and
    /// call the quirk's OWN method directly on it — this must typecheck
    /// regardless of whether the CURRENT compilation unit contains any
    /// concrete `impl X as To<JsonValue>` at all (the impl may live in
    /// whatever program eventually calls this function). So, in addition to
    /// discovering instantiations from impls (`synthesize_quirk_instantiations_module`),
    /// also scan every type annotation in the program (function params/return
    /// types, compound fields, variables — reusing the same scan generic
    /// compound/enum monomorphization uses) for a concrete instantiation of
    /// each known generic quirk, so the quirk itself becomes resolvable for
    /// direct method calls even with zero concrete impls in scope.
    fn synthesize_quirk_instantiations_from_type_annotations(self: *Self, reg: *TypeRegistry) TranspileError!void {
        var generic_quirk_names = ArrayList([]const u8).init(self.allocator);
        defer generic_quirk_names.deinit();
        var qit = reg.quirks_by_sig.iterator();
        while (qit.next()) |entry| {
            const qnode = entry.value_ptr.*;
            if (qnode.node_variant == null) continue;
            const q = qnode.node_variant.?.quirk;
            if (!q.is_generic) continue;
            generic_quirk_names.append(q.name.items) catch return TranspileError.MemoryAllocationFailed;
        }

        for (generic_quirk_names.items) |base_name| {
            var keys = std.StringHashMap(bool).init(self.allocator);
            defer {
                var kit = keys.iterator();
                while (kit.next()) |e| self.allocator.free(e.key_ptr.*);
                keys.deinit();
            }
            var out = ArrayList(*const dtype.DataType).init(self.allocator);
            defer out.deinit();
            try self.collect_generic_instantiations_recursive(self, base_name, &keys, &out);

            for (out.items) |dt| {
                if (dt.generic_args == null) continue;
                if (self.dtype_has_unresolved_placeholder(dt)) continue;
                const mangled = try self.type_name_mangled(dt);
                defer self.allocator.free(mangled);
                if (self.mangled_contains_unresolved_placeholder(mangled)) continue;
                try self.synthesize_quirk_instantiation(reg, mangled);
            }
        }
    }

    fn validate_quirk_impl_complete(
        self: *Self,
        impl_node: *ast.Node,
        type_name: []const u8,
        quirk_name: []const u8,
        quirk_sig: []const u8,
        reg: *TypeRegistry,
    ) TranspileError!void {
        const qnode = reg.quirks_by_sig.get(quirk_sig) orelse {
            self.report_type_error(impl_node.*, "unknown quirk '{s}'", .{quirk_name});
            return TranspileError.SymbolNotDefined;
        };
        if (qnode.node_variant == null) return TranspileError.UnsupportedNodeType;
        const q = qnode.node_variant.?.quirk;

        if (impl_node.node_variant == null) return TranspileError.UnsupportedNodeType;
        const im = impl_node.node_variant.?.impl;

        // Build a lookup from base method name -> function node.
        // Impl methods are parsed as Function nodes with generated names:
        // `<Type>__<Quirk>__<method>`.
        var methods_by_name = std.StringHashMap(*ast.Node).init(self.backing_allocator);
        defer methods_by_name.deinit();

        for (im.methods.items()) |m_ptr| {
            const m = m_ptr.*;
            if (m.type != .Function or m.node_variant == null) continue;
            const fnv = m.node_variant.?.function;
            const gen = if (fnv.name) |nm| nm.items else continue;
            const base = base_method_name_from_generated(gen) orelse continue;
            if (base.len == 0) continue;
            // Keep the first occurrence; duplicates are already handled elsewhere.
            if (!methods_by_name.contains(base)) {
                methods_by_name.put(base, m_ptr) catch return TranspileError.MemoryAllocationFailed;
            }
        }

        // Collect missing methods.
        var missing = ArrayList(ast.QuirkMethodSig).init(self.backing_allocator);
        defer missing.deinit();

        for (q.methods.items()) |qm| {
            const name = qm.name.items;
            const m_ptr = methods_by_name.get(name) orelse {
                missing.append(qm) catch return TranspileError.MemoryAllocationFailed;
                continue;
            };
            const m = m_ptr.*;
            const fnv = m.node_variant.?.function;

            // Must have a body to count as implemented.
            if (fnv.body == null) {
                missing.append(qm) catch return TranspileError.MemoryAllocationFailed;
                continue;
            }

            // Signature must match the quirk declaration.
            try self.validate_quirk_method_signature(impl_node, name, m, qm);
        }

        if (missing.items.len != 0) {
            var buf = ArrayList(u8).init(self.backing_allocator);
            defer buf.deinit();

            buf.print(
                "impl '{s}' for quirk '{s}' is missing {d} method(s):\n",
                .{ type_name, quirk_name, missing.items.len },
            ) catch return TranspileError.MemoryAllocationFailed;

            for (missing.items) |qm| {
                buf.appendSlice("- ") catch return TranspileError.MemoryAllocationFailed;
                try self.append_quirk_method_stub_sig(&buf, qm);
                buf.append('\n') catch return TranspileError.MemoryAllocationFailed;
            }

            self.report_type_error(impl_node.*, "{s}", .{buf.items});
            return TranspileError.TypeMismatch;
        }
    }

    fn validate_quirk_method_signature(
        self: *Self,
        impl_node: *ast.Node,
        method_name: []const u8,
        impl_method_node: ast.Node,
        quirk_sig: ast.QuirkMethodSig,
    ) TranspileError!void {
        if (impl_method_node.node_variant == null or impl_method_node.type != .Function) {
            self.report_type_error(impl_node.*, "invalid impl method '{s}'", .{method_name});
            return TranspileError.UnsupportedNodeType;
        }
        const impl_fn = impl_method_node.node_variant.?.function;

        if (impl_fn.is_async != quirk_sig.is_async) {
            self.report_type_error(
                impl_node.*,
                "impl method '{s}' async modifier mismatch: expected {s}",
                .{ method_name, if (quirk_sig.is_async) "async" else "non-async" },
            );
            return TranspileError.TypeMismatch;
        }

        // Impl args include implicit `self` as arg0; quirk sig args do not.
        const impl_args = if (impl_fn.args) |a| a.items() else &[_]*ast.Node{};
        const quirk_args = quirk_sig.args.items();
        const impl_user_args = if (impl_args.len > 0) impl_args[1..] else impl_args;

        if (impl_user_args.len != quirk_args.len) {
            self.report_type_error(
                impl_node.*,
                "impl method '{s}' arg count mismatch for quirk method '{s}'",
                .{ method_name, method_name },
            );
            return TranspileError.WrongArgCount;
        }
        var impl_rtype: dtype.DataType = .{ .type_str = ArrayList(u8).init(self.backing_allocator) };
        defer impl_rtype.type_str.deinit();
        if (impl_fn.rtype) |rt| {
            impl_rtype.type_str.appendSlice(rt.type_str.items) catch return TranspileError.MemoryAllocationFailed;
            impl_rtype.pointer_depth = rt.pointer_depth;
            impl_rtype.array = rt.array;
            impl_rtype.type = rt.type;
            // Preserve generic args (e.g. `Option<T>`) so a generic-quirk signature
            // like `next() Option<T>` compares equal to its impl's return type.
            impl_rtype.generic_args = rt.generic_args;
        } else {
            impl_rtype.type = .Void;
            impl_rtype.type_str.appendSlice("void") catch return TranspileError.MemoryAllocationFailed;
        }

        if (!dtype_sig_equal_relaxed(&impl_rtype, &quirk_sig.rtype)) {
            var want = ArrayList(u8).init(self.backing_allocator);
            defer want.deinit();
            var got = ArrayList(u8).init(self.backing_allocator);
            defer got.deinit();
            try self.append_dtype_sig(&want, &quirk_sig.rtype);
            try self.append_dtype_sig(&got, &impl_rtype);
            self.report_type_error(
                impl_node.*,
                "impl method '{s}' return type mismatch: expected {s}, got {s}",
                .{ method_name, want.items, got.items },
            );
            return TranspileError.ReturnTypeMismatch;
        }

        for (quirk_args, 0..) |qa, i| {
            const impl_arg_node = impl_user_args[i];
            if (impl_arg_node.node_variant == null or impl_arg_node.type != .Variable) {
                self.report_type_error(impl_node.*, "invalid impl method '{s}' arg", .{method_name});
                return TranspileError.UnsupportedNodeType;
            }
            const impl_dt = impl_arg_node.node_variant.?.variable.type;
            if (!dtype_sig_equal_relaxed(impl_dt, qa.dtype)) {
                var want = ArrayList(u8).init(self.backing_allocator);
                defer want.deinit();
                var got = ArrayList(u8).init(self.backing_allocator);
                defer got.deinit();
                try self.append_dtype_sig(&want, qa.dtype);
                try self.append_dtype_sig(&got, impl_dt);
                self.report_type_error(
                    impl_node.*,
                    "impl method '{s}' arg {d} type mismatch: expected {s}, got {s}",
                    .{ method_name, i + 1, want.items, got.items },
                );
                return TranspileError.TypeMismatch;
            }
        }
    }

    fn dtype_sig_equal(a: *const dtype.DataType, b: *const dtype.DataType) bool {
        if (!mem.eql(u8, a.type_str.items, b.type_str.items)) return false;
        if ((a.generic_args == null) != (b.generic_args == null)) return false;
        if (a.generic_args) |ga| {
            const gb = b.generic_args.?.items();
            const ai = ga.items();
            if (ai.len != gb.len) return false;
            for (ai, 0..) |a_dt, i| {
                if (!dtype_sig_equal(a_dt, gb[i])) return false;
            }
        }
        if (a.pointer_depth != b.pointer_depth) return false;
        const a_arr = a.array;
        const b_arr = b.array;
        if ((a_arr == null) != (b_arr == null)) return false;
        if (a_arr) |aa| {
            if (b_arr) |bb| {
                if (aa.brackets.count != bb.brackets.count) return false;
            } else return false;
        }
        return true;
    }

    /// Heuristic: a bare type-parameter spelling (`T`, `K`, `V`, `E`, `T1`, ...) — a
    /// short all-uppercase identifier with no generic args, pointer, or array. Used to
    /// match abstract type params across a generic-quirk signature and its impl, where
    /// the param NAMES are free to differ (`Iterator<T>` satisfied by `Option<K>`).
    fn dtype_is_bare_type_param(dt: *const dtype.DataType) bool {
        if (dt.generic_args != null) return false;
        if (dt.pointer_depth != 0) return false;
        if (dt.array != null) return false;
        const s = dt.type_str.items;
        if (s.len == 0 or s.len > 2) return false;
        for (s) |ch| {
            if (!((ch >= 'A' and ch <= 'Z') or (ch >= '0' and ch <= '9'))) return false;
        }
        return (s[0] >= 'A' and s[0] <= 'Z');
    }

    /// Like `dtype_sig_equal`, but for validating a GENERIC-quirk impl against the
    /// quirk's abstract signature. `a` is the impl's type, `b` is the quirk's. A bare
    /// type parameter ON THE QUIRK SIDE (`b`, e.g. the `T` in `Iterator<T>.next()
    /// Option<T>`) matches WHATEVER the impl bound it to — whether another bare param
    /// (`impl MapIter<K,V> as Iterator<K>`, K↔T) or a concrete type (`impl Counter as
    /// Iterator<num>`, where `next()` returns `Option<num>`). This is sound because the
    /// `as Quirk<...>` binding fixes the quirk's params for this impl.
    fn dtype_sig_equal_relaxed(a: *const dtype.DataType, b: *const dtype.DataType) bool {
        if (dtype_is_bare_type_param(b)) return true;
        if (dtype_is_bare_type_param(a)) return true;
        if (!mem.eql(u8, a.type_str.items, b.type_str.items)) return false;
        if ((a.generic_args == null) != (b.generic_args == null)) return false;
        if (a.generic_args) |ga| {
            const gb = b.generic_args.?.items();
            const ai = ga.items();
            if (ai.len != gb.len) return false;
            for (ai, 0..) |a_dt, i| {
                if (!dtype_sig_equal_relaxed(a_dt, gb[i])) return false;
            }
        }
        if (a.pointer_depth != b.pointer_depth) return false;
        const a_arr = a.array;
        const b_arr = b.array;
        if ((a_arr == null) != (b_arr == null)) return false;
        if (a_arr) |aa| {
            if (b_arr) |bb| {
                if (aa.brackets.count != bb.brackets.count) return false;
            } else return false;
        }
        return true;
    }

    fn base_method_name_from_generated(gen: []const u8) ?[]const u8 {
        // Split on "__" and return the last segment.
        var i: usize = gen.len;
        while (i >= 2) : (i -= 1) {
            if (gen[i - 1] == '_' and gen[i - 2] == '_') {
                return gen[i..];
            }
        }
        return null;
    }

    fn impl_type_params(self: *Self, impl_node: *const ast.Node) ?*const utils.Vector(ArrayList(u8)) {
        if (impl_node.node_variant == null) return null;
        const im = &impl_node.node_variant.?.impl;
        if (im.type_params) |*params| return params;
        if (mem.indexOf(u8, im.type_name.items, "__") != null) return null;
        const base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
        const reg = self.root_registry() orelse return null;
        const cnode = reg.compounds_by_name.get(base) orelse return null;
        if (cnode.node_variant == null) return null;
        const c = &cnode.node_variant.?.compound;
        if (c.type_params) |*params| return params;
        return null;
    }

    fn register_generic_instantiation(self: *Self, dt: *const dtype.DataType) TranspileError!void {
        if (dt.generic_args == null) return;
        if (dt.type_str.items.len == 0) return;
        if (@intFromPtr(dt.type_str.items.ptr) == 0) return;
        if (self.dtype_has_unresolved_placeholder(dt)) return;
        // Reject an instantiation whose OWN generic arg names a generic type
        // but is missing its own required generic arguments (e.g.
        // `Result<Option>` instead of `Result<Option<Token>>`) -- see the
        // matching check/comment in `register_generic_fn_instantiation`.
        if (self.root_registry()) |reg| {
            for (dt.generic_args.?.items()) |ga| {
                if (ga.generic_args != null) continue;
                if (ga.type_str.items.len == 0) continue;
                const required: usize = blk: {
                    if (reg.enums_by_name.get(ga.type_str.items)) |enode| {
                        if (enode.node_variant) |nv| {
                            if (nv.enum_decl.type_params) |tp| break :blk tp.count;
                        }
                    }
                    if (reg.compounds_by_name.get(ga.type_str.items)) |cnode| {
                        if (cnode.node_variant) |nv| {
                            if (nv.compound.type_params) |tp| break :blk tp.count;
                        }
                    }
                    break :blk 0;
                };
                if (required > 0) return;
            }
        }
        const root = self.get_root();
        const local_key = try self.type_name_mangled(dt);
        if (root.forced_generic_instantiation_keys.contains(local_key)) {
            self.allocator.free(local_key);
            return;
        }

        const key = if (@intFromPtr(root) == @intFromPtr(self))
            local_key
        else blk: {
            const root_key = root.allocator.dupe(u8, local_key) catch {
                self.allocator.free(local_key);
                return TranspileError.MemoryAllocationFailed;
            };
            self.allocator.free(local_key);
            break :blk root_key;
        };

        const clone = try self.clone_dtype_with_allocator(root.allocator, dt);
        root.forced_generic_instantiation_keys.put(key, true) catch return TranspileError.MemoryAllocationFailed;
        root.forced_generic_instantiations.append(clone) catch return TranspileError.MemoryAllocationFailed;
    }

    fn register_generic_instantiations_from_dtype(self: *Self, dt: *const dtype.DataType) TranspileError!void {
        if (dt.generic_args == null) {
            if (dt.type_str.items.len > 0 and mem.indexOf(u8, dt.type_str.items, "__") != null) {
                if (try self.dtype_from_mangled_type(dt.type_str.items)) |synthetic| {
                    try self.register_generic_instantiations_from_dtype(synthetic);
                }
            }
            return;
        }
        if (dt.type_str.items.len > 0 and @intFromPtr(dt.type_str.items.ptr) != 0 and !self.dtype_has_unresolved_placeholder(dt)) {
            try self.register_generic_instantiation(dt);
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                try self.register_generic_instantiations_from_dtype(ga);
            }
        }
    }

    fn register_generic_instantiation_from_checked_type(self: *Self, ct: CheckedType) TranspileError!void {
        const name = ct.mangled_name orelse ct.name orelse return;
        if (mem.indexOf(u8, name, "__") == null) return;
        if (try self.dtype_from_mangled_type(name)) |synthetic| {
            try self.register_generic_instantiations_from_dtype(synthetic);
        }
    }

    fn dtype_from_mangled_type(self: *Self, type_name: []const u8) TranspileError!?*dtype.DataType {
        if (mem.indexOf(u8, type_name, "__") == null) return null;
        const reg = self.root_registry() orelse return null;

        var segments = ArrayList([]const u8).init(self.allocator);
        defer segments.deinit();
        var it = mem.splitSequence(u8, type_name, "__");
        while (it.next()) |seg| {
            if (seg.len == 0) continue;
            segments.append(seg) catch return TranspileError.MemoryAllocationFailed;
        }
        if (segments.items.len == 0) return null;

        var idx: usize = 0;
        return self.dtype_from_mangled_segments(reg, segments.items, &idx);
    }

    /// Splits a trailing `_ptrN` suffix (added by `append_mangled_type_depth`/
    /// `append_mangled_type_with_subst_depth` to keep `Vec<Node>` and
    /// `Vec<Node*>` from mangling to the same name) back off a reconstructed
    /// segment name, recovering the base name and pointer depth.
    fn splitMangledPointerSuffix(name: []const u8) struct { base: []const u8, depth: usize } {
        if (mem.lastIndexOf(u8, name, "_ptr")) |i| {
            const digits = name[i + 4 ..];
            if (digits.len > 0) {
                var all_digits = true;
                for (digits) |c| {
                    if (c < '0' or c > '9') {
                        all_digits = false;
                        break;
                    }
                }
                if (all_digits) {
                    if (std.fmt.parseInt(usize, digits, 10) catch null) |depth| {
                        return .{ .base = name[0..i], .depth = depth };
                    }
                }
            }
        }
        return .{ .base = name, .depth = 0 };
    }

    fn dtype_from_mangled_segments(self: *Self, reg: *TypeRegistry, segments: [][]const u8, idx: *usize) TranspileError!?*dtype.DataType {
        if (idx.* >= segments.len) return null;
        const raw_name = segments[idx.*];
        const split = splitMangledPointerSuffix(raw_name);
        const name = split.base;
        idx.* += 1;

        const out = self.allocator.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        out.* = .{
            .flags = if (split.depth > 0) .{ .is_pointer = true } else null,
            .type = .Unknown,
            .type_str = ArrayList(u8).init(self.allocator),
            .pointer_depth = split.depth,
            .array = null,
            .generic_args = null,
        };
        out.type_str.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;

        // Recover generic args by consuming the following segments, once per
        // declared type param. Works for both generic COMPOUNDS and generic ENUMS
        // (Option<T>/Result<T> are enums) — without the enum branch, a mangled
        // name like `Option__JsonValue` yields generic_args=null, so a chained
        // method returning the type param T (e.g. `opt.unwrap_or(..)` -> T) can't
        // substitute T and the chain falls back to invalid raw C member access.
        const type_params: ?*const utils.Vector(ArrayList(u8)) = blk: {
            if (reg.compounds_by_name.get(name)) |cnode| {
                if (cnode.node_variant != null) {
                    if (cnode.node_variant.?.compound.type_params) |*p| break :blk p;
                }
            }
            if (reg.enums_by_name.get(name)) |enode| {
                if (enode.node_variant != null) {
                    if (enode.node_variant.?.enum_decl.type_params) |*p| break :blk p;
                }
            }
            // A generic quirk (`quirk To<T> { ... }`) used as a concrete
            // instantiation (`To<num>`, e.g. an `impl X as To<num>` binding, or
            // a `To<num>`-typed parameter) — same recovery as compounds/enums
            // above, needed to reconstruct the concrete arg for substitution.
            if (reg.quirk_sig_by_name.get(name)) |qsig| {
                if (reg.quirks_by_sig.get(qsig)) |qnode| {
                    if (qnode.node_variant != null) {
                        if (qnode.node_variant.?.quirk.type_params) |*p| break :blk p;
                    }
                }
            }
            break :blk null;
        };
        if (type_params) |params| {
            if (params.count > 0) {
                var args = utils.Vector(*dtype.DataType).init(self.allocator);
                errdefer {
                    for (args.items()) |ga| {
                        ga.type_str.deinit();
                        self.allocator.destroy(ga);
                    }
                    args.deinit();
                }
                var i: usize = 0;
                while (i < params.count) : (i += 1) {
                    const arg_dt = try self.dtype_from_mangled_segments(reg, segments, idx) orelse return null;
                    args.push(arg_dt) catch return TranspileError.MemoryAllocationFailed;
                }
                out.generic_args = args;
            }
        }

        return out;
    }

    fn add_spec_from_dtype(self: *Self, registry: *TypeRegistry, dt: *const dtype.DataType, spec_keys: *std.StringHashMap(bool), specs: *ArrayList(GenericSpec)) TranspileError!void {
        var use_dt: *const dtype.DataType = dt;
        if (use_dt.generic_args == null and use_dt.type_str.items.len > 0 and mem.indexOf(u8, use_dt.type_str.items, "__") != null) {
            if (try self.dtype_from_mangled_type(use_dt.type_str.items)) |synthetic| {
                use_dt = synthetic;
            }
        }
        if (use_dt.generic_args == null) return;
        if (self.dtype_has_unresolved_placeholder(use_dt)) return;

        const dep_base = if (mem.indexOf(u8, use_dt.type_str.items, "__")) |idx| use_dt.type_str.items[0..idx] else use_dt.type_str.items;
        const dep_cnode = registry.compounds_by_name.get(dep_base) orelse return;
        if (dep_cnode.node_variant == null) return;
        const dep_params = dep_cnode.node_variant.?.compound.type_params orelse return;
        if (use_dt.generic_args == null) return;
        if (use_dt.generic_args.?.items().len != dep_params.count) return;

        const dep_mangled = try self.type_name_mangled(use_dt);
        if (self.mangled_contains_unresolved_placeholder(dep_mangled)) {
            self.allocator.free(dep_mangled);
            return;
        }
        const spec_dt = (try self.dtype_from_mangled_type(dep_mangled)) orelse use_dt;
        if (!spec_keys.contains(dep_mangled)) {
            spec_keys.put(dep_mangled, true) catch return TranspileError.MemoryAllocationFailed;
            specs.append(.{ .cnode = dep_cnode, .dt = spec_dt, .mangled = dep_mangled }) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else {
            self.allocator.free(dep_mangled);
        }
    }

    fn add_specs_from_dtype(self: *Self, registry: *TypeRegistry, dt: *const dtype.DataType, spec_keys: *std.StringHashMap(bool), specs: *ArrayList(GenericSpec)) TranspileError!void {
        try self.add_spec_from_dtype(registry, dt, spec_keys, specs);
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                try self.add_specs_from_dtype(registry, ga, spec_keys, specs);
            }
        }
    }

    fn add_specs_from_body(self: *Self, registry: *TypeRegistry, body: *const ast.Node, spec_keys: *std.StringHashMap(bool), specs: *ArrayList(GenericSpec)) TranspileError!void {
        if (body.type != .Body or body.node_variant == null) return;
        const stmts = body.node_variant.?.body.statements;
        for (stmts.items()) |stmt_ptr| {
            const stmt = stmt_ptr.*;
            switch (stmt.type) {
                .Variable => {
                    const v = stmt.node_variant.?.variable;
                    try self.add_specs_from_dtype(registry, v.type, spec_keys, specs);
                },
                .StatementIf => {
                    const ifs = stmt.node_variant.?.statement.if_stmt;
                    try self.add_specs_from_body(registry, ifs.body, spec_keys, specs);
                },
                .StatementElseIf => {
                    const elif = stmt.node_variant.?.statement.elif_stmt;
                    try self.add_specs_from_body(registry, elif.body, spec_keys, specs);
                },
                .StatementElse => {
                    const els = stmt.node_variant.?.statement.else_stmt;
                    try self.add_specs_from_body(registry, els.body, spec_keys, specs);
                },
                .StatementFit => {
                    const fit = stmt.node_variant.?.statement.fit_stmt;
                    for (fit.branches.items()) |br| {
                        try self.add_specs_from_body(registry, br.body, spec_keys, specs);
                    }
                },
                .StatementFor => {
                    const f = stmt.node_variant.?.statement.for_stmt;
                    switch (f) {
                        .cond => |fc| try self.add_specs_from_body(registry, fc.body, spec_keys, specs),
                        .iter => |fi| try self.add_specs_from_body(registry, fi.body, spec_keys, specs),
                        .range => |fr| try self.add_specs_from_body(registry, fr.body, spec_keys, specs),
                    }
                },
                else => {},
            }
        }
    }

    fn add_specs_from_node(self: *Self, registry: *TypeRegistry, node: *ast.Node, spec_keys: *std.StringHashMap(bool), specs: *ArrayList(GenericSpec)) TranspileError!void {
        switch (node.type) {
            .Function => if (node.node_variant) |f| {
                if (f.function.rtype) |*rt| try self.add_specs_from_dtype(registry, rt, spec_keys, specs);
                if (f.function.args) |args| {
                    for (args.items()) |a| {
                        if (a.node_variant) |av| {
                            try self.add_specs_from_dtype(registry, av.variable.type, spec_keys, specs);
                        }
                    }
                }
            },
            else => {},
        }
    }

    fn add_specs_from_nodes_recursive(self: *Self, proc: *Self, registry: *TypeRegistry, spec_keys: *std.StringHashMap(bool), specs: *ArrayList(GenericSpec)) TranspileError!void {
        for (proc.nodes.items()) |*node| {
            try self.add_specs_from_node(registry, node, spec_keys, specs);
        }
        for (proc.owned_nodes.items) |node_ptr| {
            try self.add_specs_from_node(registry, node_ptr, spec_keys, specs);
        }
        for (proc.children.items) |child| {
            try self.add_specs_from_nodes_recursive(child, registry, spec_keys, specs);
        }
    }

    fn register_generic_instantiations_in_body(self: *Self, body: *const ast.Node) TranspileError!void {
        if (body.type != .Body or body.node_variant == null) return;
        const stmts = body.node_variant.?.body.statements;
        for (stmts.items()) |stmt_ptr| {
            const stmt = stmt_ptr.*;
            switch (stmt.type) {
                .Variable => if (stmt.node_variant) |v| {
                    try self.register_generic_instantiations_from_dtype(v.variable.type);
                },
                .StatementIf => if (stmt.node_variant) |sv| {
                    try self.register_generic_instantiations_in_body(sv.statement.if_stmt.body);
                },
                .StatementElseIf => if (stmt.node_variant) |sv| {
                    try self.register_generic_instantiations_in_body(sv.statement.elif_stmt.body);
                },
                .StatementElse => if (stmt.node_variant) |sv| {
                    try self.register_generic_instantiations_in_body(sv.statement.else_stmt.body);
                },
                .StatementFit => if (stmt.node_variant) |sv| {
                    const fit = sv.statement.fit_stmt;
                    for (fit.branches.items()) |br| {
                        try self.register_generic_instantiations_in_body(br.body);
                    }
                },
                .StatementFor => if (stmt.node_variant) |sv| {
                    const f = sv.statement.for_stmt;
                    switch (f) {
                        .cond => |fc| try self.register_generic_instantiations_in_body(fc.body),
                        .iter => |fi| try self.register_generic_instantiations_in_body(fi.body),
                        .range => |fr| try self.register_generic_instantiations_in_body(fr.body),
                    }
                },
                else => {},
            }
        }
    }

    fn seed_forced_generic_instantiations_from_signatures_module(self: *Self, proc: *Self) TranspileError!void {
        for (proc.nodes.items()) |node| {
            switch (node.type) {
                .Variable => if (node.node_variant) |v| try self.register_generic_instantiations_from_dtype(v.variable.type),
                .Compound => if (node.node_variant) |c| {
                    for (c.compound.fields.items()) |f| {
                        try self.register_generic_instantiations_from_dtype(f.dtype);
                    }
                },
                .Function => if (node.node_variant) |f| {
                    if (f.function.rtype) |*rt| try self.register_generic_instantiations_from_dtype(rt);
                    if (f.function.args) |args| {
                        for (args.items()) |a| {
                            if (a.node_variant) |av| {
                                try self.register_generic_instantiations_from_dtype(av.variable.type);
                            }
                        }
                    }
                    if (f.function.body) |body| {
                        try self.register_generic_instantiations_in_body(body);
                    }
                },
                .Impl => if (node.node_variant) |iv| {
                    const im = iv.impl;
                    for (im.methods.items()) |m| {
                        if (m.type != .Function or m.node_variant == null) continue;
                        const fnv = m.node_variant.?.function;
                        if (fnv.rtype) |*rt| try self.register_generic_instantiations_from_dtype(rt);
                        if (fnv.args) |args| {
                            for (args.items()) |a| {
                                if (a.node_variant) |av| {
                                    try self.register_generic_instantiations_from_dtype(av.variable.type);
                                }
                            }
                        }
                        if (fnv.body) |body| {
                            try self.register_generic_instantiations_in_body(body);
                        }
                    }
                },
                else => {},
            }
        }

        for (proc.owned_nodes.items) |node_ptr| {
            const node = node_ptr.*;
            switch (node.type) {
                .Variable => if (node.node_variant) |v| try self.register_generic_instantiations_from_dtype(v.variable.type),
                .Compound => if (node.node_variant) |c| {
                    for (c.compound.fields.items()) |f| {
                        try self.register_generic_instantiations_from_dtype(f.dtype);
                    }
                },
                .Function => if (node.node_variant) |f| {
                    if (f.function.rtype) |*rt| try self.register_generic_instantiations_from_dtype(rt);
                    if (f.function.args) |args| {
                        for (args.items()) |a| {
                            if (a.node_variant) |av| {
                                try self.register_generic_instantiations_from_dtype(av.variable.type);
                            }
                        }
                    }
                    if (f.function.body) |body| {
                        try self.register_generic_instantiations_in_body(body);
                    }
                },
                .Impl => if (node.node_variant) |iv| {
                    const im = iv.impl;
                    for (im.methods.items()) |m| {
                        if (m.type != .Function or m.node_variant == null) continue;
                        const fnv = m.node_variant.?.function;
                        if (fnv.rtype) |*rt| try self.register_generic_instantiations_from_dtype(rt);
                        if (fnv.args) |args| {
                            for (args.items()) |a| {
                                if (a.node_variant) |av| {
                                    try self.register_generic_instantiations_from_dtype(av.variable.type);
                                }
                            }
                        }
                        if (fnv.body) |body| {
                            try self.register_generic_instantiations_in_body(body);
                        }
                    }
                },
                else => {},
            }
        }

        for (proc.children.items) |child| {
            try self.seed_forced_generic_instantiations_from_signatures_module(child);
        }
    }

    fn seed_forced_generic_instantiations_from_signatures(self: *Self) TranspileError!void {
        try self.seed_forced_generic_instantiations_from_signatures_module(self.get_root());
    }

    fn call_pos_key_alloc(self: *Self, p: token.Pos) TranspileError![]const u8 {
        const end_line = if (p.end_line == 0) p.line else p.end_line;
        return std.fmt.allocPrint(self.allocator, "{s}:{d}:{d}:{d}:{d}", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    fn call_pos_key_buf(p: token.Pos, buf: []u8) ?[]const u8 {
        const end_line = if (p.end_line == 0) p.line else p.end_line;
        return std.fmt.bufPrint(buf, "{s}:{d}:{d}:{d}:{d}", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch null;
    }

    fn lookup_generic_call_override(self: *Self, node: ast.Node) ?[]const u8 {
        const p = node.pos orelse return null;
        var buf: [512]u8 = undefined;
        const key = call_pos_key_buf(p, &buf) orelse return null;
        // Overrides are stored on the root process (see where they are recorded),
        // because a generic call inside an IMPORTED module is typechecked under a
        // child process but may be emitted via a different process. Reading from
        // the root makes the override visible regardless of which process emits.
        const raw = self.get_root().generic_call_overrides.get(key) orelse return null;

        // A call to a generic function FROM WITHIN another generic function's own
        // body (a self-recursive call, or a sibling generic call using the same
        // type param name) was typechecked ONCE against the abstract TEMPLATE —
        // at that point the callee's own type args can only be inferred as the
        // bare, still-unresolved type param itself (e.g. `K` calling itself with
        // `K`), so the recorded override baked in the never-emitted
        // "callee__K" forever, regardless of which CONCRETE instantiation
        // (`callee__str`, `callee__num`, ...) is later emitted. Unlike enum
        // construction/fit (`mangled_enum_with_active_subst`), there was no
        // per-emission re-resolution step for this. If the stored override still
        // names an active type param, re-mangle it through the ACTIVE
        // substitution (arena-owned so it's safe to return without an explicit
        // free contract matching the existing non-substituted return path).
        if (self.type_subst_params) |params| {
            if (self.type_subst_args) |sargs| {
                if (self.mangled_contains_type_param(raw, params)) {
                    if (self.resubstitute_mangled_segments(raw, params.*, sargs) catch null) |resolved| {
                        return resolved;
                    }
                }
            }
        }
        return raw;
    }

    /// Splits `name` on "__" and re-mangles every segment that exactly matches
    /// an active type param name against its concrete substitution, rejoining
    /// with "__". Returns an arena-owned string, or null if nothing needed
    /// substituting. Mirrors the sizeof(Generic<T>)-inside-a-generic-function
    /// re-mangling this session already added, generalized into a shared helper.
    fn resubstitute_mangled_segments(self: *Self, name: []const u8, params: utils.Vector(ArrayList(u8)), args: []*dtype.DataType) TranspileError!?[]const u8 {
        var buf = ArrayList(u8).init(self.arena.allocator());
        var it = mem.splitSequence(u8, name, "__");
        var first = true;
        var changed = false;
        while (it.next()) |seg| {
            if (!first) buf.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
            first = false;
            var replaced = false;
            for (params.items(), 0..) |p, i| {
                if (!mem.eql(u8, p.items, seg)) continue;
                const m = self.type_name_mangled_as_arg(args[i]) catch break;
                defer self.allocator.free(m);
                buf.appendSlice(m) catch return TranspileError.MemoryAllocationFailed;
                replaced = true;
                changed = true;
                break;
            }
            if (!replaced) buf.appendSlice(seg) catch return TranspileError.MemoryAllocationFailed;
        }
        if (!changed) return null;
        return buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
    }

    /// Record that the generic-data-enum construction at `node` resolves to the
    /// monomorphized instance `mangled` (e.g. `Option__num`). Stored on the root so
    /// it's visible regardless of which process emits the construction.
    fn record_enum_ctor_override(self: *Self, node: ast.Node, mangled: []const u8) TranspileError!void {
        const p = node.pos orelse return;
        const root = self.get_root();
        const key = root.call_pos_key_alloc(p) catch return;
        const gop = root.enum_ctor_overrides.getOrPut(key) catch {
            root.allocator.free(key);
            return TranspileError.MemoryAllocationFailed;
        };
        if (gop.found_existing) root.allocator.free(key);
        gop.value_ptr.* = root.allocator.dupe(u8, mangled) catch return TranspileError.MemoryAllocationFailed;
    }

    fn lookup_enum_ctor_override(self: *Self, node: ast.Node) ?[]const u8 {
        const p = node.pos orelse return null;
        var buf: [512]u8 = undefined;
        const key = call_pos_key_buf(p, &buf) orelse return null;
        return self.get_root().enum_ctor_overrides.get(key);
    }

    fn record_await_call_override(
        self: *Self,
        node: ast.Node,
        callee_name: []const u8,
        has_receiver: bool,
        receiver_pass_by_ref: bool,
    ) TranspileError!void {
        const p = node.pos orelse return;
        const key = try self.call_pos_key_alloc(p);
        const gop = self.await_call_overrides.getOrPut(key) catch {
            self.allocator.free(key);
            return TranspileError.MemoryAllocationFailed;
        };
        if (gop.found_existing) {
            self.allocator.free(key);
        }
        gop.value_ptr.* = .{
            .callee_name = callee_name,
            .has_receiver = has_receiver,
            .receiver_pass_by_ref = receiver_pass_by_ref,
        };
    }

    fn record_await_dynamic_quirk_override(self: *Self, node: ast.Node) TranspileError!void {
        const p = node.pos orelse return;
        const key = try self.call_pos_key_alloc(p);
        const gop = self.await_call_overrides.getOrPut(key) catch {
            self.allocator.free(key);
            return TranspileError.MemoryAllocationFailed;
        };
        if (gop.found_existing) {
            self.allocator.free(key);
        }
        gop.value_ptr.* = .{
            .callee_name = "",
            .dynamic_quirk_dispatch = true,
        };
    }

    fn lookup_await_call_override(self: *Self, node: ast.Node) ?AwaitCallOverride {
        const p = node.pos orelse return null;
        var buf: [512]u8 = undefined;
        const key = call_pos_key_buf(p, &buf) orelse return null;
        return self.await_call_overrides.get(key);
    }

    fn record_for_iter_override(self: *Self, node: ast.Node, info: ForIterInfo) TranspileError!void {
        const p = node.pos orelse return;
        const key = try self.call_pos_key_alloc(p);
        // Stored on the ROOT process, same reasoning as generic_call_overrides:
        // a `for` loop inside an IMPORTED module is typechecked under a child
        // process but its body may be emitted via a different process (the
        // parent, when a caller's body is copied/inlined for cross-module
        // emission) -- reading from the root makes the override visible
        // regardless of which process ends up emitting it. Confirmed this
        // matters directly: without it, a `for x : recv.field` loop inside an
        // imported module's function failed to find its own just-recorded
        // override at emission time and hit the "no array identifier" error.
        const root = self.get_root();
        const gop = root.for_iter_overrides.getOrPut(key) catch {
            self.allocator.free(key);
            return TranspileError.MemoryAllocationFailed;
        };
        if (gop.found_existing) {
            self.allocator.free(key);
        }
        gop.value_ptr.* = info;
    }

    fn lookup_for_iter_override(self: *Self, node: ast.Node) ?ForIterInfo {
        const p = node.pos orelse return null;
        var buf: [512]u8 = undefined;
        const key = call_pos_key_buf(p, &buf) orelse return null;
        return self.get_root().for_iter_overrides.get(key);
    }

    const PrintFmtArgKind = enum {
        any,
        str,
        num,
        dec,
        bin,
        chr,
        ptr,
        raw,
    };

    fn escape_printf_literal(buf: *ArrayList(u8), s: []const u8) TranspileError!void {
        for (s) |c| {
            switch (c) {
                '"' => buf.appendSlice("\\\"") catch return TranspileError.MemoryAllocationFailed,
                '\\' => buf.appendSlice("\\\\") catch return TranspileError.MemoryAllocationFailed,
                '\n' => buf.appendSlice("\\n") catch return TranspileError.MemoryAllocationFailed,
                '\r' => buf.appendSlice("\\r") catch return TranspileError.MemoryAllocationFailed,
                '\t' => buf.appendSlice("\\t") catch return TranspileError.MemoryAllocationFailed,
                0 => buf.appendSlice("\\0") catch return TranspileError.MemoryAllocationFailed,
                else => buf.append(c) catch return TranspileError.MemoryAllocationFailed,
            }
        }
    }

    /// Emits a Fun source string `s` as a C string-literal body whose RUNTIME value
    /// equals the Fun string with its escape sequences decoded.
    ///
    /// Fun string tokens are stored verbatim by the lexer (e.g. `a\tb` is the four
    /// bytes `a`, `\`, `t`, `b`). Direct `printf`/`println` paths drop that body into
    /// a C literal, so the C compiler decodes the escapes. But the typed
    /// `format_impl` path passes the string to a runtime function that copies bytes
    /// verbatim — so `\t` would survive as a literal backslash+t unless we decode it
    /// here first. We decode each recognized `\x` to its real byte, then re-escape
    /// that byte for embedding in the emitted C literal. An unrecognized escape is
    /// preserved verbatim (the lexer already rejects invalid char escapes; in
    /// strings we keep prior lenient behavior rather than failing codegen).
    fn escape_format_impl_literal(buf: *ArrayList(u8), s: []const u8) TranspileError!void {
        var i: usize = 0;
        while (i < s.len) : (i += 1) {
            if (s[i] == '\\' and i + 1 < s.len) {
                if (utils.get_escape_char(s[i + 1])) |decoded| {
                    try escape_printf_literal(buf, &[_]u8{decoded});
                    i += 1; // consume the escaped char too
                    continue;
                }
            }
            try escape_printf_literal(buf, s[i .. i + 1]);
        }
    }

    /// Emits a Fun string literal `s` as a C string-literal body (between the
    /// surrounding quotes), bounding `\xHH` hex escapes. In C, `\x` greedily
    /// consumes EVERY following hex digit, so `"\x42C"` is a single out-of-range
    /// escape rather than byte 0x42 followed by 'C'. We split such a run with C
    /// string-literal concatenation (`"\x42" "C"`) so each `\x` reads exactly the
    /// two intended digits. Other bytes (including `\n`, `\t`, `\"`, `\\`) pass
    /// through unchanged — the C compiler decodes them.
    fn write_c_string_literal_body(self: *Self, s: []const u8) TranspileError!void {
        var i: usize = 0;
        while (i < s.len) : (i += 1) {
            try self.write(s[i .. i + 1]);
            if (s[i] == '\\' and i + 1 < s.len and (s[i + 1] == 'x' or s[i + 1] == 'X')) {
                // Emit the `x` and up to two hex digits, then if more hex digits
                // follow, break the literal so they aren't folded into the escape.
                try self.write(s[i + 1 .. i + 2]);
                i += 1;
                var digits: usize = 0;
                while (i + 1 < s.len and utils.is_hex_number(s[i + 1]) and digits < 2) {
                    try self.write(s[i + 1 .. i + 2]);
                    i += 1;
                    digits += 1;
                }
                if (i + 1 < s.len and utils.is_hex_number(s[i + 1])) {
                    // A 3rd hex digit would extend the escape — split the literal.
                    try self.write("\" \"");
                }
            }
        }
    }

    /// Emits a backtick RAW string literal's literal bytes as a C
    /// string-literal body. Unlike `write_c_string_literal_body` (whose
    /// input already IS valid C escape syntax, verbatim from the lexer),
    /// a raw string's bytes are the user's literal, unescaped content --
    /// this actively encodes the handful of bytes that would otherwise
    /// break or change the meaning of a C string literal: a backslash
    /// (else read as the start of an escape), a double-quote (else ends
    /// the literal early), and a real newline (a multi-line raw string's
    /// line-joins -- C string literals can't contain one directly).
    /// Everything else (including tabs and non-ASCII bytes) passes
    /// through unchanged.
    fn write_c_string_literal_body_from_raw(self: *Self, s: []const u8) TranspileError!void {
        for (s) |c| {
            switch (c) {
                '\\' => try self.write("\\\\"),
                '"' => try self.write("\\\""),
                '\n' => try self.write("\\n"),
                '\r' => try self.write("\\r"),
                else => try self.write(&[_]u8{c}),
            }
        }
    }

    fn next_tmp_name(self: *Self, prefix: []const u8) TranspileError![]const u8 {
        var buf: [64]u8 = undefined;
        const name = std.fmt.bufPrint(&buf, "__fun_{s}_{d}", .{ prefix, self.tmp_counter }) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        self.tmp_counter += 1;
        return self.allocator.dupe(u8, name) catch TranspileError.MemoryAllocationFailed;
    }

    fn build_printf_format(fmt: []const u8, out_fmt: *ArrayList(u8), kinds: *ArrayList(PrintFmtArgKind)) TranspileError!void {
        var i: usize = 0;
        while (i < fmt.len) {
            const c = fmt[i];
            if (c == '{') {
                if (i + 1 < fmt.len and fmt[i + 1] == '{') {
                    out_fmt.append('{') catch return TranspileError.MemoryAllocationFailed;
                    i += 2;
                    continue;
                }
                if (i + 1 < fmt.len and fmt[i + 1] == '}') {
                    out_fmt.appendSlice("%s") catch return TranspileError.MemoryAllocationFailed;
                    kinds.append(.any) catch return TranspileError.MemoryAllocationFailed;
                    i += 2;
                    continue;
                }
                if (i + 4 < fmt.len and fmt[i + 4] == '}') {
                    const a = fmt[i + 1];
                    const b = fmt[i + 2];
                    const d = fmt[i + 3];
                    if (a == 's' and b == 't' and d == 'r') {
                        out_fmt.appendSlice("%s") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.str) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                    if (a == 'n' and b == 'u' and d == 'm') {
                        out_fmt.appendSlice("%lld") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.num) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                    if (a == 'd' and b == 'e' and d == 'c') {
                        out_fmt.appendSlice("%g") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.dec) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                    if (a == 'b' and b == 'i' and d == 'n') {
                        out_fmt.appendSlice("%s") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.bin) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                    if (a == 'c' and b == 'h' and d == 'r') {
                        out_fmt.appendSlice("%c") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.chr) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                    if (a == 'p' and b == 't' and d == 'r') {
                        out_fmt.appendSlice("%p") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.ptr) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                    if (a == 'r' and b == 'a' and d == 'w') {
                        out_fmt.appendSlice("%p") catch return TranspileError.MemoryAllocationFailed;
                        kinds.append(.raw) catch return TranspileError.MemoryAllocationFailed;
                        i += 5;
                        continue;
                    }
                }
            }

            if (c == '}' and i + 1 < fmt.len and fmt[i + 1] == '}') {
                out_fmt.append('}') catch return TranspileError.MemoryAllocationFailed;
                i += 2;
                continue;
            }

            if (c == '%') {
                out_fmt.appendSlice("%%") catch return TranspileError.MemoryAllocationFailed;
            } else {
                out_fmt.append(c) catch return TranspileError.MemoryAllocationFailed;
            }
            i += 1;
        }
    }

    fn emit_print_fmt_literal(self: *Self, node: ast.Node, is_newline: bool, args_node: ?*ast.Node, module_alias: ?[]const u8) TranspileError!bool {
        if (args_node == null) return false;

        var args_nodes = ArrayList(*ast.Node).init(self.allocator);
        defer args_nodes.deinit();
        try self.flatten_call_args_ptr(args_node.?, &args_nodes);
        if (args_nodes.items.len == 0) return false;

        const fmt_node = args_nodes.items[0].*;
        if (fmt_node.type != .String or fmt_node.data == null) return false;
        // A raw (backtick) format string's bytes are literal, unescaped
        // content, not this fast path's assumed "already valid C escape
        // syntax" shape -- fall back to the general call path instead of
        // threading raw-escaping through the whole printf-format rewrite.
        if (fmt_node.is_raw_string) return false;

        const fmt = fmt_node.data.?.sval.items;
        var fmt_out = ArrayList(u8).init(self.allocator);
        defer fmt_out.deinit();

        var kinds = ArrayList(PrintFmtArgKind).init(self.allocator);
        defer kinds.deinit();

        try build_printf_format(fmt, &fmt_out, &kinds);

        // Keep the optimization only for explicitly typed placeholders.
        // Bare `{}` should use the regular vararg path, which handles mixed argument kinds.
        for (kinds.items) |k| {
            if (k == .any) return false;
        }

        if (is_newline) {
            fmt_out.append('\n') catch return TranspileError.MemoryAllocationFailed;
        }

        const expected_args = kinds.items.len;
        const provided_args = if (args_nodes.items.len > 0) args_nodes.items.len - 1 else 0;
        if (provided_args != expected_args) {
            // Hard error: aborting prevents emitting malformed C (the half-written
            // initializer `... = ;`) and yields a nonzero exit code.
            self.report_error(node, "print_fmt expects {d} arguments, got {d}", .{ expected_args, provided_args });
            return TranspileError.WrongArgCount;
        }

        var escaped = ArrayList(u8).init(self.allocator);
        defer escaped.deinit();
        try escape_format_impl_literal(&escaped, fmt);

        const vec_name = try self.next_tmp_name("fmt_args");
        const out_name = try self.next_tmp_name("fmt_out");

        // Resolve alias-qualified names for all inlined helper functions.
        // The alias is taken directly from the call expression (e.g. `io2.print_fmt` → alias = "io2").
        const c_fmt_num = try self.prefixed_fn_name(module_alias, "fmt_num");
        defer self.allocator.free(c_fmt_num);
        const c_fmt_dec = try self.prefixed_fn_name(module_alias, "fmt_dec");
        defer self.allocator.free(c_fmt_dec);
        const c_fmt_bin = try self.prefixed_fn_name(module_alias, "fmt_bin");
        defer self.allocator.free(c_fmt_bin);
        const c_fmt_chr = try self.prefixed_fn_name(module_alias, "fmt_chr");
        defer self.allocator.free(c_fmt_chr);
        const c_fmt_raw = try self.prefixed_fn_name(module_alias, "fmt_raw");
        defer self.allocator.free(c_fmt_raw);
        const c_format_impl = try self.prefixed_fn_name(module_alias, "format_impl");
        defer self.allocator.free(c_format_impl);

        try self.write("{ ");
        try self.write("Vec__str ");
        try self.write(vec_name);
        try self.write("; ");
        try self.write(vec_name);
        try self.write(".len = ");
        try self.print("{d}", .{expected_args});
        try self.write("; ");
        try self.write(vec_name);
        try self.write(".cap = ");
        try self.print("{d}", .{expected_args});
        try self.write("; ");

        if (expected_args > 0) {
            try self.write(vec_name);
            try self.write(".data = (char**)malloc(sizeof(char*) * ");
            try self.print("{d}", .{expected_args});
            try self.write("); ");

            var arg_i: usize = 0;
            while (arg_i < expected_args) : (arg_i += 1) {
                const kind = kinds.items[arg_i];
                const arg_node = args_nodes.items[arg_i + 1].*;
                try self.write(vec_name);
                try self.write(".data[");
                try self.print("{d}", .{arg_i});
                try self.write("] = ");
                switch (kind) {
                    .any => unreachable,
                    .str => try self.transpile_node(arg_node),
                    .num => {
                        try self.write(c_fmt_num);
                        try self.write("((long long)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .dec => {
                        try self.write(c_fmt_dec);
                        try self.write("((double)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .bin => {
                        try self.write(c_fmt_bin);
                        try self.write("((bool)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .chr => {
                        try self.write(c_fmt_chr);
                        try self.write("((char)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .ptr, .raw => {
                        try self.write(c_fmt_raw);
                        try self.write("((void*)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                }
                try self.write("; ");
            }
        } else {
            try self.write(vec_name);
            try self.write(".data = NULL; ");
        }

        try self.write("char* ");
        try self.write(out_name);
        try self.write(" = ");
        try self.write(c_format_impl);
        try self.write("(\"");
        try self.write(escaped.items);
        try self.write("\", &");
        try self.write(vec_name);
        try self.write("); ");

        try self.write("if (");
        try self.write(out_name);
        try self.write(") { ");
        if (is_newline) {
            try self.write("puts(");
            try self.write(out_name);
            try self.write("); ");
        } else {
            try self.write("printf(\"%s\", ");
            try self.write(out_name);
            try self.write("); ");
        }
        try self.write("free(");
        try self.write(out_name);
        try self.write("); }");

        if (expected_args > 0) {
            var free_i: usize = 0;
            while (free_i < expected_args) : (free_i += 1) {
                const kind = kinds.items[free_i];
                if (kind == .str) continue;
                try self.write(" free(");
                try self.write(vec_name);
                try self.write(".data[");
                try self.print("{d}", .{free_i});
                try self.write("]); ");
            }
            try self.write(" free(");
            try self.write(vec_name);
            try self.write(".data);");
        }

        try self.write(" }");
        return true;
    }

    fn emit_format_literal(self: *Self, node: ast.Node, args_node: ?*ast.Node, module_alias: ?[]const u8) TranspileError!bool {
        if (args_node == null) return false;

        var args_nodes = ArrayList(*ast.Node).init(self.allocator);
        defer args_nodes.deinit();
        try self.flatten_call_args_ptr(args_node.?, &args_nodes);
        if (args_nodes.items.len == 0) return false;

        const fmt_node = args_nodes.items[0].*;
        if (fmt_node.type != .String or fmt_node.data == null) return false;
        // A raw (backtick) format string's bytes are literal, unescaped
        // content, not this fast path's assumed "already valid C escape
        // syntax" shape -- fall back to the general call path instead of
        // threading raw-escaping through the whole printf-format rewrite.
        if (fmt_node.is_raw_string) return false;

        const fmt = fmt_node.data.?.sval.items;
        var fmt_out = ArrayList(u8).init(self.allocator);
        defer fmt_out.deinit();

        var kinds = ArrayList(PrintFmtArgKind).init(self.allocator);
        defer kinds.deinit();

        try build_printf_format(fmt, &fmt_out, &kinds);

        // Keep the optimization only for explicitly typed placeholders.
        // Bare `{}` should use the regular vararg path, which handles mixed argument kinds.
        for (kinds.items) |k| {
            if (k == .any) return false;
        }

        const expected_args = kinds.items.len;
        const provided_args = if (args_nodes.items.len > 0) args_nodes.items.len - 1 else 0;
        if (provided_args != expected_args) {
            // Hard error: aborting prevents emitting malformed C (`char* r = ;`).
            self.report_error(node, "format expects {d} arguments, got {d}", .{ expected_args, provided_args });
            return TranspileError.WrongArgCount;
        }

        var escaped = ArrayList(u8).init(self.allocator);
        defer escaped.deinit();
        try escape_format_impl_literal(&escaped, fmt);

        const vec_name = try self.next_tmp_name("fmt_args");
        const out_name = try self.next_tmp_name("fmt_out");

        // Resolve alias-qualified names for all inlined helper functions.
        const c_fmt_num = try self.prefixed_fn_name(module_alias, "fmt_num");
        defer self.allocator.free(c_fmt_num);
        const c_fmt_dec = try self.prefixed_fn_name(module_alias, "fmt_dec");
        defer self.allocator.free(c_fmt_dec);
        const c_fmt_bin = try self.prefixed_fn_name(module_alias, "fmt_bin");
        defer self.allocator.free(c_fmt_bin);
        const c_fmt_chr = try self.prefixed_fn_name(module_alias, "fmt_chr");
        defer self.allocator.free(c_fmt_chr);
        const c_fmt_raw = try self.prefixed_fn_name(module_alias, "fmt_raw");
        defer self.allocator.free(c_fmt_raw);
        const c_format_impl = try self.prefixed_fn_name(module_alias, "format_impl");
        defer self.allocator.free(c_format_impl);

        try self.write("({ ");
        try self.write("Vec__str ");
        try self.write(vec_name);
        try self.write("; ");
        try self.write(vec_name);
        try self.write(".len = ");
        try self.print("{d}", .{expected_args});
        try self.write("; ");
        try self.write(vec_name);
        try self.write(".cap = ");
        try self.print("{d}", .{expected_args});
        try self.write("; ");

        if (expected_args > 0) {
            try self.write(vec_name);
            try self.write(".data = (char**)malloc(sizeof(char*) * ");
            try self.print("{d}", .{expected_args});
            try self.write("); ");

            var arg_i: usize = 0;
            while (arg_i < expected_args) : (arg_i += 1) {
                const kind = kinds.items[arg_i];
                const arg_node = args_nodes.items[arg_i + 1].*;
                try self.write(vec_name);
                try self.write(".data[");
                try self.print("{d}", .{arg_i});
                try self.write("] = ");
                switch (kind) {
                    .any => unreachable,
                    .str => try self.transpile_node(arg_node),
                    .num => {
                        try self.write(c_fmt_num);
                        try self.write("((long long)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .dec => {
                        try self.write(c_fmt_dec);
                        try self.write("((double)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .bin => {
                        try self.write(c_fmt_bin);
                        try self.write("((bool)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .chr => {
                        try self.write(c_fmt_chr);
                        try self.write("((char)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                    .ptr, .raw => {
                        try self.write(c_fmt_raw);
                        try self.write("((void*)(");
                        try self.transpile_node(arg_node);
                        try self.write("))");
                    },
                }
                try self.write("; ");
            }
        } else {
            try self.write(vec_name);
            try self.write(".data = NULL; ");
        }

        try self.write("char* ");
        try self.write(out_name);
        try self.write(" = ");
        try self.write(c_format_impl);
        try self.write("(\"");
        try self.write(escaped.items);
        try self.write("\", &");
        try self.write(vec_name);
        try self.write("); ");

        if (expected_args > 0) {
            var free_i: usize = 0;
            while (free_i < expected_args) : (free_i += 1) {
                const kind = kinds.items[free_i];
                if (kind == .str) continue;
                try self.write(" free(");
                try self.write(vec_name);
                try self.write(".data[");
                try self.print("{d}", .{free_i});
                try self.write("]); ");
            }
            try self.write(" free(");
            try self.write(vec_name);
            try self.write(".data);");
        }

        try self.write(" ");
        try self.write(out_name);
        try self.write("; })");
        return true;
    }

    fn base_type_name(t: CheckedType) ?[]const u8 {
        if (t.base == .Unknown) return t.name;
        return switch (t.base) {
            .Void => "void",
            .Raw => "raw",
            .Chr => "chr",
            .Str => "str",
            .Dec => "dec",
            .Num => "num",
            .Bin => "bin",
            .Unknown => null,
        };
    }

    fn checked_type_to_dtype(self: *Self, t: CheckedType) TranspileError!?*dtype.DataType {
        if (t.dtype_ref) |dt| {
            if (t.base == .Unknown and t.mangled_name != null) {
                const cloned = try self.clone_dtype(dt);
                // The CheckedType may have an ADJUSTED pointer depth/array-ness vs the
                // referenced dtype (e.g. `*pb` derefs a `Box<num>*` to a `Box<num>`).
                // Honor the CheckedType's shape so `let x = *pb` infers the value
                // type, not the original pointer type.
                cloned.pointer_depth = t.pointer_depth;
                cloned.array_depth = t.array_depth;
                // Keep the `is_pointer`/`is_array` flags consistent with the adjusted
                // depths — `write_type` falls back to these flags when pointer_depth
                // is 0, so a stale `is_pointer` would re-introduce a spurious `*`.
                if (cloned.flags) |*f| {
                    f.is_pointer = t.pointer_depth > 0;
                    f.is_array = t.is_array;
                } else if (t.pointer_depth > 0 or t.is_array) {
                    cloned.flags = dtype.DataTypeFlags{ .is_pointer = t.pointer_depth > 0, .is_array = t.is_array };
                }
                return cloned;
            }
        }

        var normalized = t;
        if (normalized.base == .Unknown and normalized.name != null) {
            const n = normalized.name.?;
            if (mem.eql(u8, n, "num")) normalized.base = .Num;
            if (mem.eql(u8, n, "dec")) normalized.base = .Dec;
            if (mem.eql(u8, n, "str")) normalized.base = .Str;
            if (mem.eql(u8, n, "chr")) normalized.base = .Chr;
            if (mem.eql(u8, n, "bin")) normalized.base = .Bin;
            if (mem.eql(u8, n, "raw")) normalized.base = .Raw;
            if (mem.eql(u8, n, "void")) normalized.base = .Void;
        }

        const name = base_type_name(normalized) orelse return null;
        const out = self.allocator.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        out.* = .{
            .flags = null,
            .type = normalized.base,
            .type_str = ArrayList(u8).init(self.allocator),
            .pointer_depth = normalized.pointer_depth,
            .array = null,
            .generic_args = null,
            .array_depth = normalized.array_depth,
        };
        if (normalized.is_array) {
            var flags = out.flags orelse dtype.DataTypeFlags{};
            flags.is_array = true;
            out.flags = flags;
        }
        out.type_str.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;
        return out;
    }

    fn alloc_simple_dtype(self: *Self, name: []const u8) TranspileError!*dtype.DataType {
        const out = self.allocator.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        out.* = .{
            .flags = null,
            .type = .Unknown,
            .type_str = ArrayList(u8).init(self.allocator),
            .pointer_depth = 0,
            .array = null,
            .generic_args = null,
        };
        out.type_str.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;
        return out;
    }

    fn clone_dtype_with_allocator(self: *Self, alloc: mem.Allocator, dt: *const dtype.DataType) TranspileError!*dtype.DataType {
        if (dt.array != null) return TranspileError.TypeMismatch;

        const out = alloc.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        out.* = dt.*;
        out.type_str = ArrayList(u8).init(alloc);
        out.type_str.appendSlice(dt.type_str.items) catch return TranspileError.MemoryAllocationFailed;
        out.generic_args = null;

        if (dt.generic_args) |gargs| {
            var out_args = utils.Vector(*dtype.DataType).init(alloc);
            errdefer {
                for (out_args.items()) |ga| {
                    ga.type_str.deinit();
                    alloc.destroy(ga);
                }
                out_args.deinit();
            }
            for (gargs.items()) |ga| {
                const ga_copy = try self.clone_dtype_with_allocator(alloc, ga);
                out_args.push(ga_copy) catch return TranspileError.MemoryAllocationFailed;
            }
            out.generic_args = out_args;
        }

        return out;
    }

    fn clone_dtype(self: *Self, dt: *const dtype.DataType) TranspileError!*dtype.DataType {
        return self.clone_dtype_with_allocator(self.allocator, dt);
    }

    fn validate_compound_init(self: *Self, init_node: ast.Node, dt: *dtype.DataType, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!void {
        if (dt.pointer_depth != 0 or (dt.flags != null and dt.flags.?.is_array)) {
            self.report_type_error(init_node, "compound initializer expects a non-pointer, non-array compound type", .{});
            return TranspileError.TypeMismatch;
        }

        try self.ensure_dtype_visible(init_node, dt, env.type_params);

        const root = self.root_registry() orelse {
            self.report_type_error(init_node, "unknown compound type", .{});
            return TranspileError.SymbolNotDefined;
        };
        const base_name = if (mem.indexOf(u8, dt.type_str.items, "__")) |idx| dt.type_str.items[0..idx] else dt.type_str.items;
        const cnode = root.compounds_by_name.get(base_name) orelse {
            self.report_type_error(init_node, "type '{s}' is not a compound", .{base_name});
            return TranspileError.TypeMismatch;
        };
        if (!self.can_access(&init_node, cnode)) {
            self.report_type_error(init_node, "type '{s}' is private", .{base_name});
            return TranspileError.SymbolNotDefined;
        }

        const cdef = cnode.node_variant.?.compound;
        const params = cdef.type_params;

        // If generic args are omitted (e.g. `Box{value = 7}`), infer them from field values.
        if (params != null and dt.generic_args == null) {
            var bindings = std.StringHashMap(*dtype.DataType).init(self.allocator);
            defer bindings.deinit();

            const ci_infer = init_node.node_variant.?.compound_init;
            for (ci_infer.fields.items()) |field| {
                var field_dtype: ?*dtype.DataType = null;
                for (cdef.fields.items()) |f| {
                    if (mem.eql(u8, f.name.items, field.name.items)) {
                        field_dtype = f.dtype;
                        break;
                    }
                }
                if (field_dtype == null) continue;

                const actual_ct = try self.infer_expr_type(field.value.*, env, fns);
                const actual_dt = (try self.checked_type_to_dtype(actual_ct)) orelse continue;
                _ = try self.bind_generic_param(field_dtype.?, actual_dt, &params.?, &bindings);
            }

            var inferred_args = utils.Vector(*dtype.DataType).init(self.allocator);
            errdefer inferred_args.deinit();
            for (params.?.items()) |p| {
                const bound = bindings.get(p.items) orelse {
                    self.report_type_error(init_node, "cannot infer generic parameter '{s}' in compound initializer", .{p.items});
                    return TranspileError.TypeMismatch;
                };
                inferred_args.push(bound) catch return TranspileError.MemoryAllocationFailed;
            }
            dt.generic_args = inferred_args;
        }

        const gargs = if (dt.generic_args) |ga| ga.items() else null;
        if (params != null) {
            const pcount = params.?.count;
            const gcount = if (gargs) |ga| ga.len else 0;
            if (pcount != gcount) {
                self.report_type_error(init_node, "compound initializer generic arg count mismatch", .{});
                return TranspileError.TypeMismatch;
            }
        }
        if (dt.generic_args != null) {
            try self.register_generic_instantiation(dt);
        }

        var seen = std.StringHashMap(bool).init(self.allocator);
        defer seen.deinit();

        const ci = init_node.node_variant.?.compound_init;
        for (ci.fields.items()) |field| {
            if (seen.contains(field.name.items)) {
                self.report_type_error(init_node, "duplicate field '{s}' in compound initializer", .{field.name.items});
                return TranspileError.TypeMismatch;
            }
            seen.put(field.name.items, true) catch return TranspileError.MemoryAllocationFailed;

            var fdt: ?*dtype.DataType = null;
            for (cdef.fields.items()) |f| {
                if (mem.eql(u8, f.name.items, field.name.items)) {
                    fdt = f.dtype;
                    break;
                }
            }
            if (fdt == null) {
                self.report_type_error(init_node, "unknown field '{s}' in compound initializer", .{field.name.items});
                return TranspileError.UnknownField;
            }
            // A leading-underscore field is module-private: it cannot be set from a
            // compound initializer in another module (same rule as field access).
            try self.check_private_field_access(init_node, base_name, field.name.items);

            const expected = if (params != null and gargs != null)
                try self.type_from_dtype_with_subst(fdt.?, params.?, gargs.?)
            else
                try self.type_from_dtype_with_mangled(fdt.?);

            if (field.value.*.type == .CompoundInit) {
                try self.bind_compound_init_expected(field.value, expected, env, fns);
            }
            if (self.expected_enum_name(expected)) |enum_name| {
                if (dot_shorthand_variant_name(field.value)) |_| {
                    _ = try self.resolve_dot_shorthand_enum_variant(field.value, enum_name);
                } else {
                    // Shorthand data-variant construction as a compound-init value.
                    try self.resolve_shorthand_enum_call(field.value, enum_name);
                }
            }

            const actual = try self.infer_expr_type(field.value.*, env, fns);
            if (is_known_type(expected) and is_known_type(actual) and !(try self.can_implicit_coerce(expected, actual))) {
                self.report_type_error(init_node, "type mismatch for field '{s}' in compound initializer", .{field.name.items});
                return TranspileError.TypeMismatch;
            }
        }
    }

    fn bind_compound_init_expected(self: *Self, init_node: *ast.Node, expected: CheckedType, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!void {
        if (init_node.type != .CompoundInit or init_node.node_variant == null) return;
        const ci = &init_node.node_variant.?.compound_init;
        if (ci.dtype == null) {
            if (expected.dtype_ref) |dt| {
                if (dt.pointer_depth != 0 or (dt.flags != null and dt.flags.?.is_array)) {
                    self.report_type_error(init_node.*, "compound initializer expects a non-pointer, non-array compound type", .{});
                    return TranspileError.TypeMismatch;
                }
                ci.dtype = try self.clone_dtype(dt);
            } else if (expected.name) |name| {
                const dt = self.allocator.create(dtype.DataType) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                dt.* = .{
                    .flags = null,
                    .type = .Unknown,
                    .type_str = ArrayList(u8).init(self.allocator),
                    .pointer_depth = 0,
                    .array = null,
                    .generic_args = null,
                };
                dt.type_str.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;
                ci.dtype = dt;
            } else {
                return;
            }
        }

        if (ci.dtype) |dt| {
            try self.validate_compound_init(init_node.*, dt, env, fns);
        }
    }

    /// When a value expression is a data-enum variant construction whose expected
    /// type is a GENERIC enum instance (`Option<num> x = .Some(5)` /
    /// `= Option.Some(5)`), record the construction site's monomorphized name
    /// (`Option__num`) so codegen emits the mangled cast + tag. No-op for
    /// non-generic enums (their construction already uses the plain name) or
    /// non-construction values.
    fn bind_enum_ctor_expected(self: *Self, value_node: *ast.Node, expected: CheckedType) TranspileError!void {
        if (value_node.type != .Expression or value_node.node_variant == null) return;
        const exp = value_node.node_variant.?.exp;
        // The value is either a variant CONSTRUCTION `Enum.Variant(args)` (op "()")
        // or a payload-free variant VALUE `Enum.Variant` (op "."). Both need the
        // monomorphized name at codegen.
        const ctor_node: *ast.Node = if (mem.eql(u8, exp.op, "()")) (exp.left orelse return) else value_node;
        const path = self.enum_variant_path(ctor_node) orelse return;
        _ = path;

        // Determine the expected enum's mangled instance name from its dtype.
        const dt = expected.dtype_ref orelse return;
        if (dt.generic_args == null) return; // non-generic enum: nothing to mangle
        const base = if (dt.type_str.items.len > 0) dt.type_str.items else (expected.name orelse return);
        const reg = self.root_registry() orelse return;
        if (!reg.enums_by_name.contains(base)) return;

        // Mangle the expected enum dtype to its concrete instance. Inside a
        // monomorphized method the expected type may still mention the enclosing
        // type's params (`Option<K>` in `impl MapIter<K,V> as Iterator<K>`), so apply
        // the active substitution (`K`->`str`) to reach `Option__str` rather than the
        // never-emitted `Option__K`.
        const mangled = blk: {
            if (self.type_subst_params) |params| {
                if (self.type_subst_args) |sargs| {
                    if (self.type_name_mangled_with_subst(dt, params.*, sargs) catch null) |m| break :blk m;
                }
            }
            break :blk (self.type_name_mangled(dt) catch return);
        };
        defer self.allocator.free(mangled);
        if (mem.eql(u8, mangled, base)) return; // not actually mangled
        // Skip the generic TEMPLATE typecheck pass, where the args are still type
        // parameters (mangled name like `Option__T`). Only record a concrete
        // instance (`Option__num`), which codegen actually emits. Without this the
        // template method would emit a reference to the never-defined `Option__T`.
        if (self.mangled_contains_unresolved_placeholder(mangled)) return;
        if (self.type_subst_params) |params| {
            if (self.mangled_contains_type_param(mangled, params)) return;
        }
        try self.record_enum_ctor_override(value_node.*, mangled);
    }

    fn make_vec_str_dtype(self: *Self) TranspileError!*dtype.DataType {
        const dt_str = self.allocator.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        dt_str.* = .{
            .flags = null,
            .type = .Str,
            .type_str = ArrayList(u8).init(self.allocator),
            .pointer_depth = 0,
            .array = null,
            .generic_args = null,
        };
        dt_str.type_str.appendSlice("str") catch return TranspileError.MemoryAllocationFailed;

        var gargs = utils.Vector(*dtype.DataType).init(self.allocator);
        gargs.push(dt_str) catch return TranspileError.MemoryAllocationFailed;

        const dt_vec = self.allocator.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        dt_vec.* = .{
            .flags = null,
            .type = .Unknown,
            .type_str = ArrayList(u8).init(self.allocator),
            .pointer_depth = 0,
            .array = null,
            .generic_args = gargs,
        };
        dt_vec.type_str.appendSlice("Vec") catch return TranspileError.MemoryAllocationFailed;
        return dt_vec;
    }

    fn clone_dtype_with_ptr_adjust(self: *Self, dt: *const dtype.DataType, new_ptr_depth: usize) TranspileError!*dtype.DataType {
        const out = self.allocator.create(dtype.DataType) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        out.* = dt.*;
        out.pointer_depth = new_ptr_depth;
        if (new_ptr_depth > 0) {
            var flags = out.flags orelse dtype.DataTypeFlags{};
            flags.is_pointer = true;
            out.flags = flags;
        }
        out.type_str = ArrayList(u8).init(self.allocator);
        out.type_str.appendSlice(dt.type_str.items) catch return TranspileError.MemoryAllocationFailed;
        return out;
    }

    fn dtype_equiv(a: *const dtype.DataType, b: *const dtype.DataType) bool {
        if (a.pointer_depth != b.pointer_depth) return false;
        if ((a.flags != null and a.flags.?.is_array) != (b.flags != null and b.flags.?.is_array)) return false;
        const a_name = a.type_str.items;
        const b_name = b.type_str.items;
        if (!mem.eql(u8, a_name, b_name)) return false;
        if ((a.generic_args == null) != (b.generic_args == null)) return false;
        if (a.generic_args) |ag| {
            const bg = b.generic_args.?.items();
            if (ag.items().len != bg.len) return false;
            for (ag.items(), 0..) |ga, i| {
                if (!dtype_equiv(ga, bg[i])) return false;
            }
        }
        return true;
    }

    fn bind_generic_param(self: *Self, expected: *const dtype.DataType, actual: *const dtype.DataType, params: *const utils.Vector(ArrayList(u8)), out: *std.StringHashMap(*dtype.DataType)) TranspileError!bool {
        // Type param match.
        if ((expected.type == null or expected.type == .Unknown) and expected.type_str.items.len > 0) {
            for (params.items()) |p| {
                if (mem.eql(u8, p.items, expected.type_str.items)) {
                    if (actual.pointer_depth < expected.pointer_depth) return false;
                    const adj_ptr = actual.pointer_depth - expected.pointer_depth;
                    const adj = if (expected.pointer_depth == 0) @constCast(actual) else try self.clone_dtype_with_ptr_adjust(actual, adj_ptr);
                    if (out.get(p.items)) |existing| {
                        if (!dtype_equiv(existing, adj)) return false;
                    } else {
                        out.put(p.items, adj) catch return TranspileError.MemoryAllocationFailed;
                    }
                    return true;
                }
            }
        }

        // Non-param: ensure base matches.
        if (expected.pointer_depth != actual.pointer_depth) return false;
        if ((expected.flags != null and expected.flags.?.is_array) != (actual.flags != null and actual.flags.?.is_array)) return false;
        if (expected.type != null and expected.type != .Unknown) {
            // A dtype resolved through generic-arg substitution (e.g. a
            // compound field's type param V bound to `num` via a caller's
            // `TreeNode<K, num>*`) can end up with the right `type_str`
            // ("num") but an unpopulated `.type` (still `.Unknown`) --
            // structurally "not yet recognized as the primitive keyword"
            // even though it unambiguously names it. Comparing `.type`
            // fields strictly then spuriously rejected `num` (expected,
            // `.type = .Num`) against `num` (actual, `.type = .Unknown`)
            // as a mismatch. Fall back to a type_str comparison when
            // `actual.type` isn't populated, rather than failing outright.
            if (expected.type != actual.type) {
                const actual_unresolved = actual.type == null or actual.type == .Unknown;
                if (!actual_unresolved or !mem.eql(u8, expected.type_str.items, actual.type_str.items)) {
                    return false;
                }
            }
        } else {
            if (!mem.eql(u8, expected.type_str.items, actual.type_str.items)) {
                return false;
            }
        }

        if (expected.generic_args) |eg| {
            const ag = actual.generic_args orelse return false;
            if (eg.items().len != ag.items().len) return false;
            for (eg.items(), 0..) |egv, i| {
                if (!(try self.bind_generic_param(egv, ag.items()[i], params, out))) return false;
            }
        }
        return true;
    }

    fn mangle_generic_fn_name(self: *Self, fname: []const u8, gargs: []*dtype.DataType) TranspileError![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        buf.appendSlice(fname) catch return TranspileError.MemoryAllocationFailed;
        for (gargs) |ga| {
            buf.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
            try self.append_mangled_type(&buf, ga);
        }
        return buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
    }

    fn register_generic_fn_instantiation(self: *Self, fn_node: *ast.Node, params: *const utils.Vector(ArrayList(u8)), gargs: []*dtype.DataType, name: []const u8, owner_fn: ?*ast.Node, impl_arg_count: usize) TranspileError!void {
        const root = self.get_root();
        // The key is stored on (and freed by) `root`, so it MUST be allocated with
        // root's allocator. When a generic fn is instantiated from an IMPORTED
        // module, `self` is a child process with a different arena; using
        // `self.allocator` here would let root free a child-arena pointer (a
        // cross-arena free → corruption). Allocate on root.
        var key_buf = ArrayList(u8).init(root.allocator);
        defer key_buf.deinit();
        key_buf.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;
        const key = key_buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
        if (root.generic_fn_instantiation_keys.contains(key)) {
            root.allocator.free(key);
            return;
        }
        // Reject an instantiation whose bound arg NAMES a generic type but is
        // missing its own required generic arguments (e.g. binding a generic
        // wrapper's `T` to a bare "Option" instead of "Option<Token>"). Such a
        // dtype is structurally incomplete and could never be validly
        // emitted -- one arose from a legitimate call site (`ok(.None)`
        // inside a function returning `Result<Option<Token>>`), but a
        // SEPARATE, independent re-inference of that same shorthand `.None`
        // argument (elsewhere in the typecheck/codegen pipeline) didn't carry
        // the concrete instantiation through, producing this phantom
        // duplicate alongside the correct one. Silently dropping it here is
        // safe: the correct, fully-specified instantiation is registered
        // separately (under a different mangled key) and is what real
        // codegen actually emits.
        if (self.root_registry()) |reg| {
            for (gargs) |g| {
                if (g.generic_args != null) continue;
                if (g.type_str.items.len == 0) continue;
                const required: usize = blk: {
                    if (reg.enums_by_name.get(g.type_str.items)) |enode| {
                        if (enode.node_variant) |nv| {
                            if (nv.enum_decl.type_params) |tp| break :blk tp.count;
                        }
                    }
                    if (reg.compounds_by_name.get(g.type_str.items)) |cnode| {
                        if (cnode.node_variant) |nv| {
                            if (nv.compound.type_params) |tp| break :blk tp.count;
                        }
                    }
                    break :blk 0;
                };
                if (required > 0) {
                    root.allocator.free(key);
                    return;
                }
            }
        }
        root.generic_fn_instantiation_keys.put(key, true) catch return TranspileError.MemoryAllocationFailed;
        root.generic_fn_instantiations.append(.{
            .fn_node = fn_node,
            .params = params,
            .args = gargs,
            .name = name,
            .owner_fn = owner_fn,
            .impl_arg_count = impl_arg_count,
        }) catch return TranspileError.MemoryAllocationFailed;
    }

    /// A generic function calling a DIFFERENT generic function from its own
    /// template body (e.g. `identity(x)` inside `double_it<T>`) gets an
    /// instantiation registered at typecheck time too, but only with the
    /// caller's own still-abstract type param as the arg (`identity__T`) --
    /// `T` isn't bound to a concrete type until a call site OUTSIDE any
    /// generic function instantiates `double_it` itself. That placeholder
    /// entry is filtered out of emission (`mangled_contains_unresolved_placeholder`),
    /// so `identity__num` was never registered and never emitted, even though
    /// call-site text for it resolves correctly via `resubstitute_mangled_segments`.
    ///
    /// Called once per concrete instantiation `inst` (e.g. `double_it__num`,
    /// params=["T"], args=[num]) right as it's about to be emitted, with the
    /// binding therefore known. Scans every OTHER still-placeholder instantiation
    /// for one whose args reference one of `inst`'s own params, substitutes
    /// through to get concrete args, and registers the result -- which the
    /// caller's index-based worklist loop will then pick up and emit in a
    /// later iteration of the same pass.
    fn resolve_transitive_generic_fn_instantiations(self: *Self, inst: GenericFnInstantiation) TranspileError!void {
        if (inst.args.len == 0) return;
        const root = self.get_root();
        var i: usize = 0;
        while (i < root.generic_fn_instantiations.items.len) : (i += 1) {
            const other = root.generic_fn_instantiations.items[i];
            if (other.args.len == 0) continue;
            if (!self.mangled_contains_unresolved_placeholder(other.name)) continue;
            // Scope by IDENTITY of the enclosing function, not by type-param
            // NAME: an unrelated generic function elsewhere in the program
            // (e.g. `ok_or<T>` in std.option) almost certainly also names its
            // type param "T", so a name-only check would wrongly treat its
            // placeholder instantiations as belonging to `inst` and substitute
            // them with `inst`'s unrelated concrete args.
            const owner = other.owner_fn orelse continue;
            if (owner != inst.fn_node) continue;

            var any_ref = false;
            for (other.args) |a| {
                if (self.dtype_contains_type_param(a, inst.params)) {
                    any_ref = true;
                    break;
                }
            }
            if (!any_ref) continue;

            const resolved = self.allocator.alloc(*dtype.DataType, other.args.len) catch return TranspileError.MemoryAllocationFailed;
            for (other.args, 0..) |a, ai| {
                resolved[ai] = try self.clone_dtype_with_subst_for_inst(a, inst.params, inst.args);
            }

            const other_fnv = other.fn_node.node_variant orelse continue;
            const other_fname = other_fnv.function.name orelse continue;
            // A METHOD's own generated name is `Type__method` (e.g. `Box__inner`,
            // unmangled for generics) -- naively appending ALL resolved args to
            // it (the free-function convention) produces `Box__inner__num__num`
            // instead of the method naming convention `Box__num__inner__num`.
            // Reconstruct it properly when `impl_arg_count` marks this as a
            // method-shaped instantiation (impl-level args first, then the
            // method's own).
            const new_name = if (other.impl_arg_count > 0 and other.impl_arg_count <= resolved.len) blk: {
                const method_base = base_method_name_from_generated(other_fname.items) orelse
                    break :blk try self.mangle_generic_fn_name(other_fname.items, resolved);
                const type_base = other_fname.items[0 .. other_fname.items.len - method_base.len - 2];
                const type_mangled = try self.mangle_generic_fn_name(type_base, resolved[0..other.impl_arg_count]);
                defer self.allocator.free(type_mangled);
                const type_and_method = std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ type_mangled, method_base }) catch return TranspileError.MemoryAllocationFailed;
                defer self.allocator.free(type_and_method);
                break :blk try self.mangle_generic_fn_name(type_and_method, resolved[other.impl_arg_count..]);
            } else try self.mangle_generic_fn_name(other_fname.items, resolved);
            // Still references a type param further up an even deeper call
            // chain (e.g. a THIRD generic function called from `identity`'s
            // own body) -- leave it for a later `inst` in the worklist whose
            // binding resolves it the rest of the way.
            if (self.mangled_contains_unresolved_placeholder(new_name)) continue;

            try self.register_generic_fn_instantiation(other.fn_node, other.params, resolved, new_name, null, other.impl_arg_count);
        }
    }

    fn append_quirk_method_stub_sig(self: *Self, buf: *ArrayList(u8), m: ast.QuirkMethodSig) TranspileError!void {
        if (m.is_async) {
            buf.appendSlice("async ") catch return TranspileError.MemoryAllocationFailed;
        }
        buf.appendSlice(m.name.items) catch return TranspileError.MemoryAllocationFailed;
        buf.append('(') catch return TranspileError.MemoryAllocationFailed;

        const args = m.args.items();
        for (args, 0..) |a, i| {
            if (i != 0) buf.appendSlice(", ") catch return TranspileError.MemoryAllocationFailed;
            try self.append_dtype_sig(buf, a.dtype);
            buf.append(' ') catch return TranspileError.MemoryAllocationFailed;
            buf.appendSlice(a.name.items) catch return TranspileError.MemoryAllocationFailed;
        }
        buf.append(')') catch return TranspileError.MemoryAllocationFailed;

        if (m.rtype.type != .Void) {
            buf.append(' ') catch return TranspileError.MemoryAllocationFailed;
            try self.append_dtype_sig(buf, &m.rtype);
        }
    }

    fn collect_type_registry_all(self: *Self) TranspileError!void {
        const reg = self.ensure_type_registry();

        // Rebuild from scratch each transpile run.
        reg.deinit();
        self.get_root().type_registry = TypeRegistry.init(self.get_root().allocator);
        const new_reg = &self.get_root().type_registry.?;

        try self.collect_type_registry_recursive(self, new_reg);

        // Register alias-qualified type keys for aliased re-imports that were
        // deduped to node-less stubs (so `alias.Type` annotations resolve).
        try self.register_alias_stub_types(self, new_reg);

        // Third pass: register concrete instantiations of generic quirks used
        // by `impl X as Quirk<Concrete>` bindings (e.g. `To__num`), so that
        // BOTH the impl registration below and any later type resolution of
        // the same instantiation (e.g. a `To<num>`-typed parameter) find a
        // real, substituted quirk signature instead of an unmangled name.
        try self.synthesize_quirk_instantiations_recursive(self, new_reg);

        // Fourth pass: ALSO discover instantiations from bare type annotations
        // (a quirk-typed parameter/field/variable, independent of any impl in
        // this compilation unit — e.g. a library function that declares
        // `To<JsonValue>` and calls its method directly must typecheck even
        // when no concrete impl is in scope here).
        try self.synthesize_quirk_instantiations_from_type_annotations(new_reg);

        // Second pass: impls need quirk name->signature resolution.
        try self.collect_impls_recursive(self, new_reg);
    }

    /// Whole-program check: two DIFFERENT files each declaring their own
    /// private (non-`pub`) top-level function under the same bare name
    /// (e.g. two small modules each with their own `mk_bin`/`peek`/`advance`
    /// helper) currently both emit a plain, unmangled C function with that
    /// name — a genuine C "redefinition" once both are reachable from the
    /// same program, even though NEITHER file imports the other and Fun's
    /// own visibility rules correctly keep them from calling each other's
    /// private helper. Public collisions are already caught elsewhere
    /// (global symbol registration); this catches the previously-uncaught
    /// private/private case with a clear Fun-level diagnostic instead of a
    /// confusing raw C compiler error surfacing after the fact. Found via a
    /// multi-file compiler-shaped torture test (parser.fn and main.fn each
    /// declaring their own private `mk_bin`/`mk_num`/`mk_var`).
    fn check_no_duplicate_private_function_names(self: *Self) TranspileError!void {
        var seen = std.StringHashMap(*ast.Node).init(self.backing_allocator);
        defer seen.deinit();
        try self.collect_private_functions_checking_dupes(&seen);
    }

    fn collect_private_functions_checking_dupes(self: *Self, seen: *std.StringHashMap(*ast.Node)) TranspileError!void {
        for (self.nodes.items()) |*n| {
            if (n.type != .Function or n.node_variant == null) continue;
            if (n.flags != null and n.flags.?.is_public) continue;
            const fnv = n.node_variant.?.function;
            const nm = (fnv.name orelse continue).items;
            if (nm.len == 0) continue;

            if (seen.get(nm)) |existing| {
                if (existing == n) continue;
                const existing_file = if (existing.pos) |p| p.filename else "<unknown>";
                self.report_type_error(
                    n.*,
                    "private function '{s}' is also declared (privately) in '{s}'; private top-level function names must be unique across the whole program — rename one or make it `pub`",
                    .{ nm, existing_file },
                );
                return TranspileError.DuplicateSymbol;
            }
            seen.put(nm, n) catch return TranspileError.MemoryAllocationFailed;
        }
        for (self.children.items) |child| {
            try child.collect_private_functions_checking_dupes(seen);
        }
    }

    fn has_compound_named(proc: *Self, name: []const u8) bool {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Compound or n.node_variant == null) continue;
            if (mem.eql(u8, n.node_variant.?.compound.name.items, name)) return true;
        }
        for (proc.children.items) |child| {
            if (has_compound_named(child, name)) return true;
        }
        return false;
    }

    fn has_quirk_named(proc: *Self, name: []const u8) bool {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Quirk or n.node_variant == null) continue;
            if (mem.eql(u8, n.node_variant.?.quirk.name.items, name)) return true;
        }
        for (proc.children.items) |child| {
            if (has_quirk_named(child, name)) return true;
        }
        return false;
    }

    fn has_enum_named(proc: *Self, name: []const u8) bool {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Enum or n.node_variant == null) continue;
            if (mem.eql(u8, n.node_variant.?.enum_decl.name.items, name)) return true;
        }
        for (proc.children.items) |child| {
            if (has_enum_named(child, name)) return true;
        }
        return false;
    }

    fn find_fn_defining_decl(self: *Self, kind_kw: []const u8, name: []const u8) !?[]u8 {
        // Best-effort: scan workspace files for a `compound <Name>` or `quirk <Name>` declaration.
        // Returns a backing-allocator owned relative path like `parent/child/some.fn`.
        var matches = ArrayList([]u8).init(self.backing_allocator);
        defer {
            for (matches.items) |m| self.backing_allocator.free(m);
            matches.deinit();
        }

        var root_dir = try std.Io.Dir.cwd().openDir(self.io, ".", .{ .iterate = true });
        defer root_dir.close(self.io);
        var walker = try root_dir.walk(self.backing_allocator);
        defer walker.deinit();

        var pat_buf: [256]u8 = undefined;
        const pat = try std.fmt.bufPrint(&pat_buf, "{s} {s}", .{ kind_kw, name });

        const isIdentChar = struct {
            fn call(ch: u8) bool {
                return std.ascii.isAlphanumeric(ch) or ch == '_';
            }
        }.call;

        while (try walker.next(self.io)) |entry| {
            // Skip generated/vendor trees.
            if (mem.startsWith(u8, entry.path, ".zig-cache") or mem.startsWith(u8, entry.path, "zig-out") or mem.startsWith(u8, entry.path, ".git") or mem.startsWith(u8, entry.path, "stdlib")) {
                continue;
            }
            if (entry.kind != .file) continue;
            if (!mem.endsWith(u8, entry.path, ".fn")) continue;

            const contents = root_dir.readFileAlloc(self.io, entry.path, self.backing_allocator, .limited(512 * 1024)) catch continue;
            defer self.backing_allocator.free(contents);

            var found = false;
            var search_pos: usize = 0;
            while (mem.indexOfPos(u8, contents, search_pos, pat)) |hit| {
                const after = hit + pat.len;
                const left_ok = hit == 0 or !isIdentChar(contents[hit - 1]);
                const right_ok = after >= contents.len or !isIdentChar(contents[after]);
                if (left_ok and right_ok) {
                    found = true;
                    break;
                }
                search_pos = hit + 1;
            }
            if (!found) continue;
            try matches.append(try self.backing_allocator.dupe(u8, entry.path));
            if (matches.items.len > 1) break;
        }

        if (matches.items.len != 1) return null;
        return try self.backing_allocator.dupe(u8, matches.items[0]);
    }

    fn process_local_import_full_path(self: *Self, full_path: []const u8, import_alias: ?[]const u8) GeneralError!void {
        // Minimal variant of `process_local_import()` that takes a resolved `.fn` path.
        // Used for auto-importing type definitions so entrypoint scripts can run unchanged.

        const canon_path = std.Io.Dir.cwd().realPathFileAlloc(self.io, full_path, self.allocator) catch null;
        const canon = canon_path orelse (self.allocator.dupe(u8, full_path) catch return TranspileError.MemoryAllocationFailed);
        errdefer self.allocator.free(canon);

        // When the file is already imported, we may still need to register a new alias.
        // If so, create a minimal stub child process (no lex/parse) so that
        // transpile_children_recursive can emit #define stubs for the new alias.
        // See `imported_files_is_globally_parsed` for why the compile-wide set is
        // consulted in addition to this subtree's local `imported_files`.
        if (self.imported_files.contains(canon) or self.imported_files_is_globally_parsed(canon)) {
            if (import_alias) |alias| {
                var stub_proc = self.backing_allocator.create(TranspileProcess) catch {
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
                stub_proc.* = TranspileProcess.init_with_stdlib_dir(self.backing_allocator, canon, "temp.c", .{ .outf = false }, self.stdlib_dir) catch {
                    self.backing_allocator.destroy(stub_proc);
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
                stub_proc.parent = self;
                stub_proc.is_importing = true;
                stub_proc.import_alias = stub_proc.allocator.dupe(u8, alias) catch {
                    stub_proc.deinit();
                    self.backing_allocator.destroy(stub_proc);
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
                self.children.append(stub_proc) catch {
                    stub_proc.deinit();
                    self.backing_allocator.destroy(stub_proc);
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
            }
            self.allocator.free(canon);
            return;
        }

        std.Io.Dir.cwd().access(self.io, canon, .{}) catch {
            self.report_error(null, "Import file not found: {s}", .{full_path});
            return TranspileError.ImportFileNotFound;
        };

        self.imported_files.put(canon, true) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        self.mark_globally_parsed(canon);

        var import_proc = self.backing_allocator.create(TranspileProcess) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer self.backing_allocator.destroy(import_proc);

        // Inherit ONLY the parent's test/warning-visibility mode (test_mode,
        // emit_unused_warnings) so e.g. `fun test entry.fn` also type-checks and emits
        // `test` blocks declared in an IMPORTED module, not just the entry file's own --
        // `typecheck_module`'s `.Test`-node handling is gated on exactly these two
        // fields. Without this, a child process always got `test_mode = false`
        // regardless of the parent, so an imported module's `test` block was parsed but
        // never type-checked -- yet codegen still tried to emit it, embedding the
        // unresolved `__let_infer__` placeholder for any `let` binding whose type only
        // typecheck ever resolves.
        //
        // Deliberately NOT a wholesale `self.flags` copy: `preload_imports`/
        // `preload_std_imports`/`emit_stderr`/etc. are parse-strategy/output flags the
        // ROOT process sets for its own reasons (e.g. the test harness disables import
        // preloading to avoid redundant filesystem probing) that must NOT cascade to
        // children -- doing so broke transitive import processing for std.channel/
        // std.net (children stopped preloading their OWN nested imports).
        var child_flags = TranspileProcessFlags{ .outf = false };
        child_flags.test_mode = self.flags.test_mode;
        child_flags.fuzz_mode = self.flags.fuzz_mode;
        child_flags.emit_unused_warnings = self.flags.emit_unused_warnings;
        import_proc.* = try TranspileProcess.init_with_stdlib_dir(self.backing_allocator, canon, "temp.c", child_flags, self.stdlib_dir);
        import_proc.fuzz_target = self.fuzz_target;
        import_proc.parent = self;
        import_proc.is_importing = true;
        if (import_alias) |alias| {
            import_proc.import_alias = import_proc.allocator.dupe(u8, alias) catch return TranspileError.MemoryAllocationFailed;
        }

        // Copy imported files to child (prevents duplicate imports across branches).
        var it = self.imported_files.iterator();
        while (it.next()) |entry| {
            const imported_file_copy = import_proc.allocator.dupe(u8, entry.key_ptr.*) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer import_proc.allocator.free(imported_file_copy);
            import_proc.imported_files.put(imported_file_copy, true) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        for (self.import_chain.items) |chain_path| {
            const chain_path_copy = import_proc.allocator.dupe(u8, chain_path) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer import_proc.allocator.free(chain_path_copy);
            import_proc.import_chain.append(chain_path_copy) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        const import_path_copy = import_proc.allocator.dupe(u8, canon) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer import_proc.allocator.free(import_path_copy);
        import_proc.import_chain.append(import_path_copy) catch {
            return TranspileError.MemoryAllocationFailed;
        };

        var lex_proc = lexer.LexProcess.init(import_proc);
        var parse_proc = parser.ParseProcess.init(import_proc);
        try lex_proc.lex();
        try parse_proc.parse();

        for (import_proc.nodes.items()) |node| {
            if (node.type == .Import) {
                try import_proc.process_import(node);
            }
        }

        try import_proc.sync_global_symbols_to_parent();

        self.children.append(import_proc) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    fn collect_user_type_refs_in_body(self: *Self, body: *ast.Node, out: *std.StringHashMap(bool)) TranspileError!void {
        if (body.type != .Body or body.node_variant == null) return;
        const stmts = body.node_variant.?.body.statements;
        for (stmts.items()) |stmt_ptr| {
            const stmt = stmt_ptr.*;
            switch (stmt.type) {
                .Variable => {
                    const v = stmt.node_variant.?.variable;
                    const dt = v.type;
                    if (dt.type == .Unknown and dt.type_str.items.len != 0) {
                        out.put(dt.type_str.items, true) catch return TranspileError.MemoryAllocationFailed;
                    }
                },
                .StatementIf => {
                    const ifs = stmt.node_variant.?.statement.if_stmt;
                    try self.collect_user_type_refs_in_body(ifs.body, out);
                },
                .StatementElseIf => {
                    const elif = stmt.node_variant.?.statement.elif_stmt;
                    try self.collect_user_type_refs_in_body(elif.body, out);
                },
                .StatementElse => {
                    const els = stmt.node_variant.?.statement.else_stmt;
                    try self.collect_user_type_refs_in_body(els.body, out);
                },
                .StatementFit => {
                    const fit = stmt.node_variant.?.statement.fit_stmt;
                    for (fit.branches.items()) |br| {
                        try self.collect_user_type_refs_in_body(br.body, out);
                    }
                },
                .StatementFor => {
                    const f = stmt.node_variant.?.statement.for_stmt;
                    switch (f) {
                        .cond => |fc| try self.collect_user_type_refs_in_body(fc.body, out),
                        .iter => |fi| try self.collect_user_type_refs_in_body(fi.body, out),
                        .range => |fr| try self.collect_user_type_refs_in_body(fr.body, out),
                    }
                },
                else => {},
            }
        }
    }

    fn auto_import_missing_user_types(self: *Self) GeneralError!void {
        // Scan root file for referenced user-defined types (e.g. `Data data;`, `impl Data Display`).
        // If a referenced type isn't currently defined in the import graph, try to find a unique
        // declaration in the workspace and import that file automatically.

        var refs = std.StringHashMap(bool).init(self.backing_allocator);
        defer refs.deinit();

        var generic_param_names = std.StringHashMap(bool).init(self.backing_allocator);
        defer generic_param_names.deinit();

        const normalizeTypeName = struct {
            fn call(raw: []const u8) []const u8 {
                var name = std.mem.trim(u8, raw, " \t\r\n");
                if (name.len == 0) return name;

                if (std.mem.indexOfScalar(u8, name, '<')) |lt| {
                    name = std.mem.trim(u8, name[0..lt], " \t\r\n");
                }

                while (name.len >= 2 and std.mem.eql(u8, name[name.len - 2 ..], "[]")) {
                    name = std.mem.trim(u8, name[0 .. name.len - 2], " \t\r\n");
                }

                while (name.len != 0) {
                    const tail = name[name.len - 1];
                    if (tail == '*' or tail == '&') {
                        name = std.mem.trim(u8, name[0 .. name.len - 1], " \t\r\n");
                        continue;
                    }
                    break;
                }

                return name;
            }
        }.call;

        // Root nodes
        for (self.nodes.items()) |n| {
            switch (n.type) {
                .Variable => {
                    if (n.node_variant == null) continue;
                    const v = n.node_variant.?.variable;
                    const dt = v.type;
                    if (dt.type == .Unknown and dt.type_str.items.len != 0) {
                        refs.put(dt.type_str.items, true) catch return TranspileError.MemoryAllocationFailed;
                    }
                },
                .Function => {
                    if (n.node_variant == null) continue;
                    const f = n.node_variant.?.function;
                    if (f.type_params) |*params| {
                        for (params.items()) |*p| {
                            if (p.items.len == 0) continue;
                            generic_param_names.put(p.items, true) catch return TranspileError.MemoryAllocationFailed;
                        }
                    }
                    if (f.args) |args| {
                        for (args.items()) |arg| {
                            if (arg.type != .Variable or arg.node_variant == null) continue;
                            const dt = arg.node_variant.?.variable.type;
                            if (dt.type == .Unknown and dt.type_str.items.len != 0) {
                                const norm = normalizeTypeName(dt.type_str.items);
                                if (norm.len != 0) refs.put(norm, true) catch return TranspileError.MemoryAllocationFailed;
                            }
                        }
                    }
                    if (f.rtype) |rt| {
                        if (rt.type == .Unknown and rt.type_str.items.len != 0) {
                            const norm = normalizeTypeName(rt.type_str.items);
                            if (norm.len != 0) refs.put(norm, true) catch return TranspileError.MemoryAllocationFailed;
                        }
                    }
                    if (f.body) |b| {
                        try self.collect_user_type_refs_in_body(b, &refs);
                    }
                },
                .Compound => {
                    if (n.node_variant == null) continue;
                    const c = n.node_variant.?.compound;
                    if (c.type_params) |*params| {
                        for (params.items()) |*p| {
                            if (p.items.len == 0) continue;
                            generic_param_names.put(p.items, true) catch return TranspileError.MemoryAllocationFailed;
                        }
                    }
                },
                .Impl => {
                    if (n.node_variant == null) continue;
                    const im = n.node_variant.?.impl;
                    if (im.type_params) |*params| {
                        for (params.items()) |*p| {
                            if (p.items.len == 0) continue;
                            generic_param_names.put(p.items, true) catch return TranspileError.MemoryAllocationFailed;
                        }
                    }
                    if (im.type_name.items.len != 0) {
                        const norm = normalizeTypeName(im.type_name.items);
                        if (norm.len != 0) refs.put(norm, true) catch return TranspileError.MemoryAllocationFailed;
                    }
                    if (im.quirk_name) |qn| {
                        const norm = normalizeTypeName(qn.items);
                        if (norm.len != 0) refs.put(norm, true) catch return TranspileError.MemoryAllocationFailed;
                    }
                },
                else => {},
            }
        }

        // Body-collected refs were inserted raw; normalize into a new set so generics like
        // `Pair<L, R>` and pointer/array forms don't trigger broad auto-import searches.
        var normalized_refs = std.StringHashMap(bool).init(self.backing_allocator);
        defer normalized_refs.deinit();
        var refs_it = refs.iterator();
        while (refs_it.next()) |entry| {
            const norm = normalizeTypeName(entry.key_ptr.*);
            if (norm.len == 0) continue;
            normalized_refs.put(norm, true) catch return TranspileError.MemoryAllocationFailed;
        }

        var it = normalized_refs.iterator();
        while (it.next()) |entry| {
            const name = entry.key_ptr.*;

            // Skip builtins.
            if (mem.eql(u8, name, "num") or mem.eql(u8, name, "dec") or mem.eql(u8, name, "str") or mem.eql(u8, name, "chr") or mem.eql(u8, name, "bin") or mem.eql(u8, name, "raw") or mem.eql(u8, name, "void") or mem.eql(u8, name, "__let_infer__")) {
                continue;
            }

            // Skip in-scope generic type params (e.g. T, K, V).
            if (generic_param_names.contains(name)) {
                continue;
            }

            // Heuristic fallback: single uppercase identifiers are overwhelmingly generic params.
            if (name.len == 1 and std.ascii.isUpper(name[0])) {
                continue;
            }

            // If the type already exists in the current import graph, nothing to do.
            // A name already declared as an ENUM locally must ALSO be skipped here
            // (previously only compound/quirk were checked): a workspace-wide
            // best-effort auto-import scan (`find_fn_defining_decl`) can find an
            // UNRELATED file that happens to declare a `compound`/`quirk` with the
            // same bare name and auto-import it, colliding with the local enum and
            // misattributing the resulting "private/duplicate type" error to that
            // unrelated file. Found via a compiler-shaped torture test: a program
            // declaring `enum Shape` broke when run from within this repo's root,
            // because `examples/advanced/quirks.fn` happens to declare `quirk Shape`.
            if (has_compound_named(self, name) or has_quirk_named(self, name) or has_enum_named(self, name)) continue;

            // Prefer compounds; if not found, try quirks.
            if (self.find_fn_defining_decl("compound", name) catch null) |path| {
                defer self.backing_allocator.free(path);
                try self.process_local_import_full_path(path, null);
                continue;
            }
            if (self.find_fn_defining_decl("quirk", name) catch null) |path| {
                defer self.backing_allocator.free(path);
                try self.process_local_import_full_path(path, null);
                continue;
            }
        }
    }

    fn build_full_import_path(self: *Self, import_path: []const u8) TranspileError![]const u8 {
        // This path is a temporary helper string; keep it off the arena.
        var file_path = ArrayList(u8).init(self.backing_allocator);
        defer file_path.deinit();

        const dir_path = std.fs.path.dirname(self.input_file_path) orelse ".";
        file_path.appendSlice(dir_path) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        file_path.append('/') catch {
            return TranspileError.MemoryAllocationFailed;
        };

        // Convert dotted imports to a path. Additionally, support parent traversal via dot runs:
        // - `.`  => path separator
        // - `..` => `../` (one parent)
        // - `....` => `../../` (two parents)
        var i: usize = 0;
        while (i < import_path.len) {
            if (import_path[i] != '.') {
                file_path.append(import_path[i]) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                i += 1;
                continue;
            }

            var j = i;
            while (j < import_path.len and import_path[j] == '.') : (j += 1) {}
            const run_len = j - i;
            const parents = run_len / 2;
            const sep = (run_len % 2) == 1;

            var p: usize = 0;
            while (p < parents) : (p += 1) {
                file_path.appendSlice("..") catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                file_path.append('/') catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
            if (sep) {
                file_path.append('/') catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }

            i = j;
        }

        file_path.appendSlice(".fn") catch {
            return TranspileError.MemoryAllocationFailed;
        };

        return file_path.toOwnedSlice() catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    /// Preload global symbol names from an import path before parsing the rest of the file.
    ///
    /// This enables identifier validation in the parser to recognize functions defined in
    /// locally imported modules.
    pub fn preload_import_global_symbols(self: *Self, import_node: ast.Node, import_path: []const u8, import_alias: ?[]const u8) GeneralError!void {
        if (!self.flags.preload_imports) return;
        if (std.mem.indexOf(u8, import_path, "std.") != null) return;

        const full_path = try self.build_full_import_path(import_path);
        defer self.backing_allocator.free(full_path);

        const canon_path = std.Io.Dir.cwd().realPathFileAlloc(self.io, full_path, self.allocator) catch null;
        const canon = canon_path orelse (self.allocator.dupe(u8, full_path) catch return TranspileError.MemoryAllocationFailed);
        defer self.allocator.free(canon);

        std.Io.Dir.cwd().access(self.io, canon, .{}) catch {
            self.report_error(import_node, "Import file not found: {s}", .{full_path});
            return TranspileError.ImportFileNotFound;
        };

        // Early direct circular import detection (A imports B, and B imports A).
        // This is intentionally lightweight and mirrors the check in process_local_import.
        {
            const file_contents = std.Io.Dir.cwd().readFileAlloc(self.io, full_path, self.backing_allocator, .limited(1024 * 1024)) catch |read_err| {
                self.report_error(import_node, "Failed to read import file '{s}': {any}", .{ full_path, read_err });
                return TranspileError.FileReadError;
            };
            defer self.backing_allocator.free(file_contents);

            const our_name = std.fs.path.stem(self.input_file_path);
            var import_line = ArrayList(u8).init(self.backing_allocator);
            defer import_line.deinit();
            import_line.appendSlice("imp ") catch {
                return TranspileError.MemoryAllocationFailed;
            };
            import_line.appendSlice(our_name) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            import_line.appendSlice(";") catch {
                return TranspileError.MemoryAllocationFailed;
            };

            if (std.mem.indexOf(u8, file_contents, import_line.items)) |_| {
                const basename1 = std.fs.path.basename(self.input_file_path);
                const basename2 = std.fs.path.basename(full_path);
                self.report_error(import_node, "CIRCULAR IMPORT DETECTED: '{s}' imports '{s}', but '{s}' also imports '{s}', creating a circular dependency", .{ basename1, basename2, basename2, basename1 });
                return TranspileError.CircularImport;
            }
        }

        var import_proc = try TranspileProcess.init_with_stdlib_dir(self.backing_allocator, canon, "temp.c", .{ .exec = false, .outf = false, .ast = false }, self.stdlib_dir);
        defer import_proc.deinit();

        var lex_proc = lexer.LexProcess.init(&import_proc);
        defer lex_proc.deinit();
        try lex_proc.lex();

        const tokens = import_proc.tokens.items();
        var i: usize = 0;
        while (i < tokens.len) : (i += 1) {
            const t = tokens[i];
            if (t.type != .Keyword) continue;

            var is_public = false;
            var decl_kind: ?[]const u8 = null;
            if (mem.eql(u8, t.data.sval.items, "pub")) {
                var j: usize = i + 1;
                while (j < tokens.len and token.is_nl_or_comment_or_newline_separator(tokens[j])) : (j += 1) {}
                if (j >= tokens.len) continue;
                if (tokens[j].type != .Keyword) continue;

                const kw = tokens[j].data.sval.items;
                if (!mem.eql(u8, kw, "fun") and !mem.eql(u8, kw, "compound") and !mem.eql(u8, kw, "enum") and !mem.eql(u8, kw, "quirk")) continue;

                is_public = true;
                decl_kind = kw;
                i = j; // continue parsing as `fun`
            } else {
                continue;
            }

            var j: usize = i + 1;
            while (j < tokens.len and token.is_nl_or_comment_or_newline_separator(tokens[j])) : (j += 1) {}
            if (j >= tokens.len) continue;

            const name_tok = tokens[j];
            if (name_tok.type != .Identifier) continue;

            const name = name_tok.data.sval.items;
            if (!is_public) continue;
            if (decl_kind != null and mem.eql(u8, decl_kind.?, "fun") and mem.eql(u8, name, "main")) continue;

            const key_name = if (import_alias) |alias|
                (try self.make_alias_qualified_symbol_name(alias, name))
            else
                (self.allocator.dupe(u8, name) catch return TranspileError.MemoryAllocationFailed);
            errdefer self.allocator.free(key_name);

            if (self.global_symbols.get(key_name)) |existing| {
                if (!mem.eql(u8, existing.file_path, canon) and !mem.eql(u8, existing.file_path, self.input_file_path)) {
                    self.err("Symbol '{s}' already defined in module '{s}'", .{ key_name, existing.file_path });
                    return TranspileError.DuplicateSymbol;
                }
            }

            const path_copy = self.allocator.dupe(u8, canon) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer self.allocator.free(path_copy);

            self.global_symbols.put(key_name, .{
                .symbol_name = key_name,
                .file_path = path_copy,
                .is_function = decl_kind != null and mem.eql(u8, decl_kind.?, "fun"),
                .is_public = true,
            }) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }
    }

    /// Initializes a new instance of `TranspileProcess`.
    ///
    /// This function opens the input file in read-only mode and creates the output file
    /// with read permissions. It also initializes the token list with the provided allocator.
    ///
    /// Parameters:
    /// - `allocator`: The memory allocator to use for memory allocation operations.
    /// - `ifilepath`: The file path of the input file.
    /// - `ofilepath`: The file path of the output file.
    /// - `flags`: The flags to set for the transpiler.
    ///
    /// Returns:
    /// - `Self`: A new instance of `TranspileProcess`.
    ///
    /// Errors:
    /// - Returns an error if opening the input file or creating the output file fails.
    pub fn init(allocator: mem.Allocator, ifilepath: []const u8, ofilepath: []const u8, flags: TranspileProcessFlags) TranspileError!Self {
        return init_with_stdlib_dir(allocator, ifilepath, ofilepath, flags, null);
    }

    /// Same as `init`, but opens the input file read-write.
    ///
    /// This is required for operations that modify the input file in-place (e.g. the formatter).
    pub fn init_rw(allocator: mem.Allocator, ifilepath: []const u8, ofilepath: []const u8, flags: TranspileProcessFlags) TranspileError!Self {
        return init_with_stdlib_dir_mode(allocator, ifilepath, ofilepath, flags, null, .read_write);
    }

    pub fn init_with_stdlib_dir(
        allocator: mem.Allocator,
        ifilepath: []const u8,
        ofilepath: []const u8,
        flags: TranspileProcessFlags,
        stdlib_dir_override: ?[]const u8,
    ) TranspileError!Self {
        return init_with_stdlib_dir_mode(allocator, ifilepath, ofilepath, flags, stdlib_dir_override, .read_only);
    }

    fn init_with_stdlib_dir_mode(
        allocator: mem.Allocator,
        ifilepath: []const u8,
        ofilepath: []const u8,
        flags: TranspileProcessFlags,
        stdlib_dir_override: ?[]const u8,
        input_mode: std.Io.Dir.OpenFileOptions.Mode,
    ) TranspileError!Self {
        const io = globalIo();
        const ifile = blk: {
            const is_abs = std.fs.path.isAbsolute(ifilepath) or (@import("builtin").target.os.tag == .windows and ifilepath.len >= 2 and ifilepath[1] == ':');
            if (is_abs) {
                break :blk std.Io.Dir.openFileAbsolute(io, ifilepath, .{ .mode = input_mode }) catch {
                    return TranspileError.FileOpenError;
                };
            }
            break :blk std.Io.Dir.cwd().openFile(io, ifilepath, .{ .mode = input_mode }) catch {
                return TranspileError.FileOpenError;
            };
        };
        errdefer ifile.close(io);

        const arena_ptr = allocator.create(std.heap.ArenaAllocator) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer allocator.destroy(arena_ptr);
        arena_ptr.* = std.heap.ArenaAllocator.init(allocator);
        errdefer arena_ptr.deinit();
        const a = arena_ptr.allocator();

        var ofile: ?std.Io.File = null;
        var outbuf: ?ArrayList(u8) = null;

        if (flags.outf) {
            ofile = blk: {
                const is_abs = std.fs.path.isAbsolute(ofilepath) or (@import("builtin").target.os.tag == .windows and ofilepath.len >= 2 and ofilepath[1] == ':');
                if (is_abs) {
                    break :blk std.Io.Dir.createFileAbsolute(io, ofilepath, .{ .read = true }) catch {
                        return TranspileError.FileOpenError;
                    };
                }
                break :blk std.Io.Dir.cwd().createFile(io, ofilepath, .{ .read = true }) catch {
                    return TranspileError.FileOpenError;
                };
            };
            errdefer if (ofile) |f| f.close(io);
        } else {
            outbuf = ArrayList(u8).init(a);
        }

        // Create initial symbol table
        const initial_table = a.create(symbol.SymbolTable) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer a.destroy(initial_table);
        initial_table.* = .{
            .symbols = utils.Vector(symbol.Symbol).init(a),
            .name = "",
        };
        errdefer initial_table.symbols.deinit();

        // Initialize import-related structures
        var imported_files = std.StringHashMap(bool).init(a);
        errdefer imported_files.deinit();

        var import_chain = ArrayList([]const u8).init(a);
        errdefer import_chain.deinit();

        const input_file_path = a.dupe(u8, ifilepath) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer a.free(input_file_path);

        const input_source = blk: {
            var read_buf: [65536]u8 = undefined;
            var file_reader = ifile.reader(io, &read_buf);
            const src = file_reader.interface.allocRemaining(a, .limited(64 * 1024 * 1024)) catch {
                return TranspileError.FileReadError;
            };
            break :blk src;
        };

        imported_files.put(input_file_path, true) catch {
            return TranspileError.MemoryAllocationFailed;
        }; // Mark current file as imported

        import_chain.append(input_file_path) catch {
            return TranspileError.MemoryAllocationFailed;
        };

        const discovered_stdlib_dir_raw: ?[]const u8 = if (stdlib_dir_override) |p|
            p
        else blk: {
            if (try discover_stdlib_dir(allocator, a)) |d| break :blk d;
            break :blk try discover_stdlib_dir_near_input(allocator, a, ifilepath);
        };

        const discovered_stdlib_dir: ?[]const u8 = if (discovered_stdlib_dir_raw) |d|
            (try normalize_stdlib_dir(allocator, a, d))
        else
            null;

        return Self{
            .flags = flags,
            .pos = .{ .col = 1, .line = 1, .start_col = 1, .end_col = 1, .filename = input_file_path },
            .ifile = ifile,
            .ofile = ofile,
            .outbuf = outbuf,
            .tokens = utils.Vector(token.Token).init(a),
            .nodes = utils.Vector(ast.Node).init(a),
            .warnings = ArrayList(u8).init(a),
            .pending_warning_allows = ArrayList(PendingWarningControl).init(a),
            .pending_warning_expects = ArrayList(PendingWarningControl).init(a),
            .owned_nodes = ArrayList(*ast.Node).init(a),
            .owned_scope_entities = ArrayList(*scope.ScopeEntity).init(a),
            .defer_stack = ArrayList(DeferEntry).init(a),
            .defer_scope_stack = ArrayList(DeferScopeFrame).init(a),
            .scope = null,
            .symbols = .{
                .active_table = initial_table,
                .tables = utils.Vector(*symbol.SymbolTable).init(a),
            },
            .allocator = a,
            .backing_allocator = allocator,
            .arena = arena_ptr,
            .imported_files = imported_files,
            .globally_parsed_files = std.StringHashMap(bool).init(a),
            .import_chain = import_chain,
            .global_symbols = std.StringHashMap(GlobalSymbolInfo).init(a),
            .import_aliases = std.StringHashMap([]const u8).init(a),
            .children = ArrayList(*TranspileProcess).init(a),
            .std_imports = ArrayList([]const u8).init(a),
            .forced_generic_instantiations = ArrayList(*const dtype.DataType).init(a),
            .forced_generic_instantiation_keys = std.StringHashMap(bool).init(a),
            .emitted_generic_spec_keys = std.StringHashMap(bool).init(a),
            .generic_fn_instantiations = ArrayList(GenericFnInstantiation).init(a),
            .generic_fn_instantiation_keys = std.StringHashMap(bool).init(a),
            .generic_call_overrides = std.StringHashMap([]const u8).init(a),
            .enum_ctor_overrides = std.StringHashMap([]const u8).init(a),
            .await_call_overrides = std.StringHashMap(AwaitCallOverride).init(a),
            .for_iter_overrides = std.StringHashMap(ForIterInfo).init(a),
            .input_file_path = input_file_path,
            .input_source = input_source,
            .stdlib_dir = discovered_stdlib_dir,
            .io = io,
        };
    }

    fn build_stdlib_module_path(self: *Self, import_path: []const u8) TranspileError!?[]const u8 {
        if (!std.mem.startsWith(u8, import_path, "std.")) return null;
        if (self.stdlib_dir == null) return null;

        // Canonical layout:
        // - `std.c.io` => <stdlib>/std/c/io.fn
        // - `std.io`   => <stdlib>/std/io.fn
        const rel_after_std = import_path["std.".len..];
        const has_c_prefix = std.mem.startsWith(u8, rel_after_std, "c.");
        const rel = if (has_c_prefix) rel_after_std["c.".len..] else rel_after_std;

        const StdPathLayout = enum { c, pure };

        const Builder = struct {
            fn build_with_root(self2: *Self, root: []const u8, rel2: []const u8, layout: StdPathLayout) TranspileError![]const u8 {
                var tmp = ArrayList(u8).init(self2.backing_allocator);
                defer tmp.deinit();

                tmp.appendSlice(root) catch return TranspileError.MemoryAllocationFailed;
                tmp.append('/') catch return TranspileError.MemoryAllocationFailed;
                tmp.appendSlice("std") catch return TranspileError.MemoryAllocationFailed;
                tmp.append('/') catch return TranspileError.MemoryAllocationFailed;
                if (layout == .c) {
                    tmp.appendSlice("c") catch return TranspileError.MemoryAllocationFailed;
                    tmp.append('/') catch return TranspileError.MemoryAllocationFailed;
                }
                for (rel2) |ch| {
                    if (ch == '.') {
                        tmp.append('/') catch return TranspileError.MemoryAllocationFailed;
                    } else {
                        tmp.append(ch) catch return TranspileError.MemoryAllocationFailed;
                    }
                }
                tmp.appendSlice(".fn") catch return TranspileError.MemoryAllocationFailed;
                return tmp.toOwnedSlice() catch TranspileError.MemoryAllocationFailed;
            }
        };

        const layout: StdPathLayout = if (has_c_prefix) .c else .pure;
        const full_path = try Builder.build_with_root(self, self.stdlib_dir.?, rel, layout);
        std.Io.Dir.cwd().access(self.io, full_path, .{}) catch {
            self.backing_allocator.free(full_path);

            if (try discover_stdlib_dir_near_input(self.backing_allocator, self.allocator, self.input_file_path)) |near| {
                const near_norm = try normalize_stdlib_dir(self.backing_allocator, self.allocator, near);
                if (!std.mem.eql(u8, near_norm, self.stdlib_dir.?)) {
                    const near_path = try Builder.build_with_root(self, near_norm, rel, layout);
                    if (std.Io.Dir.cwd().access(self.io, near_path, .{})) |_| {
                        self.stdlib_dir = near_norm;
                        return near_path;
                    } else |_| {
                        self.backing_allocator.free(near_path);
                    }
                }
            }

            if (try discover_stdlib_dir(self.backing_allocator, self.allocator)) |auto| {
                const auto_norm = try normalize_stdlib_dir(self.backing_allocator, self.allocator, auto);
                if (!std.mem.eql(u8, auto_norm, self.stdlib_dir.?)) {
                    const auto_path = try Builder.build_with_root(self, auto_norm, rel, layout);
                    if (std.Io.Dir.cwd().access(self.io, auto_path, .{})) |_| {
                        self.stdlib_dir = auto_norm;
                        return auto_path;
                    } else |_| {
                        self.backing_allocator.free(auto_path);
                    }
                }
            }

            return null;
        };
        return full_path;
    }

    /// Best-effort preload of stdlib signature modules (non-fatal).
    ///
    /// This is for tooling/identifier validation: it allows `imp std.c.*;` (and the `std.*` alias)
    /// source of truth when installed, without changing codegen behavior.
    pub fn preload_std_import_global_symbols(self: *Self, import_node: ast.Node, import_path: []const u8, import_alias: ?[]const u8) void {
        if (!self.flags.preload_std_imports) return;
        const full_path_opt = self.build_stdlib_module_path(import_path) catch return;
        if (full_path_opt == null) return;
        const full_path = full_path_opt.?;
        defer self.backing_allocator.free(full_path);

        std.Io.Dir.cwd().access(self.io, full_path, .{}) catch return;

        const canon_path = std.Io.Dir.cwd().realPathFileAlloc(self.io, full_path, self.backing_allocator) catch null;
        defer if (canon_path) |p| self.backing_allocator.free(p);
        const canon = canon_path orelse full_path;

        var import_proc = TranspileProcess.init_with_stdlib_dir(
            self.backing_allocator,
            canon,
            "temp.c",
            .{ .exec = false, .outf = false, .ast = false },
            self.stdlib_dir,
        ) catch return;
        defer import_proc.deinit();

        var lex_proc = lexer.LexProcess.init(&import_proc);
        defer lex_proc.deinit();
        lex_proc.lex() catch return;

        const tokens = import_proc.tokens.items();
        var i: usize = 0;
        while (i < tokens.len) : (i += 1) {
            const t = tokens[i];
            if (t.type != .Keyword) continue;
            if (!mem.eql(u8, t.data.sval.items, "fun")) continue;

            var j: usize = i + 1;
            while (j < tokens.len and token.is_nl_or_comment_or_newline_separator(tokens[j])) : (j += 1) {}
            if (j >= tokens.len) continue;

            const name_tok = tokens[j];
            if (name_tok.type != .Identifier) continue;

            const name = name_tok.data.sval.items;
            if (mem.eql(u8, name, "main")) continue;

            const key_name = if (import_alias) |alias|
                (self.make_alias_qualified_symbol_name(alias, name) catch return)
            else
                (self.allocator.dupe(u8, name) catch return);
            errdefer self.allocator.free(key_name);

            if (self.global_symbols.get(key_name)) |existing| {
                if (!mem.eql(u8, existing.file_path, full_path) and !mem.eql(u8, existing.file_path, self.input_file_path)) {
                    // Keep behavior consistent with local preloading.
                    self.report_error(import_node, "Symbol '{s}' already defined in module '{s}'", .{ key_name, existing.file_path });
                    return;
                }
            }

            const path_copy = self.allocator.dupe(u8, canon) catch return;
            errdefer self.allocator.free(path_copy);

            self.global_symbols.put(key_name, .{
                .symbol_name = key_name,
                .file_path = path_copy,
                .is_function = true,
                .is_public = true,
            }) catch return;
        }
    }

    pub fn get_warnings(self: *Self) ?[]const u8 {
        if (self.warnings.items.len == 0) return null;
        return self.warnings.items;
    }

    /// Logs an error message with the current position in the token stream.
    ///
    /// This function logs an error message along with the line number, column span.,
    /// and filename where the error occurred.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `fmt`: The format string for the error message.
    /// - `args`: The arguments for the format string.
    pub fn err(self: *Self, comptime fmt: []const u8, args: anytype) void {
        if (!self.flags.emit_stderr) return;

        var buf: [4096]u8 = undefined;
        std.Io.File.stderr().writeStreamingAll(self.io, "\n[Error]\n") catch {};
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, fmt, args) catch fmt) catch {};

        if (self.current_token) |ct| {
            const end_line = if (ct.pos.end_line == 0) ct.pos.line else ct.pos.end_line;
            if (end_line == ct.pos.line) {
                std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}\n", .{ ct.pos.filename, ct.pos.line, ct.pos.start_col, ct.pos.end_col }) catch "") catch {};
            } else {
                std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}:{d}\n", .{ ct.pos.filename, ct.pos.line, ct.pos.start_col, end_line, ct.pos.end_col }) catch "") catch {};
            }
        } else {
            std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}\n", .{ self.pos.filename, self.pos.line, self.pos.col }) catch "") catch {};
        }
        // Do not deinit here. Callers typically `defer tp.deinit()`; implicitly
        // deinitializing inside `err()` causes double-close crashes (especially on Windows).
    }

    fn queue_warning_control(self: *Self, action: ast.WarningControlAction, id: ast.WarningId, reason: []const u8, pos: ?token.Pos) TranspileError!void {
        const pending: PendingWarningControl = .{
            .id = id,
            .reason = reason,
            .pos = pos,
        };
        switch (action) {
            .allow => self.pending_warning_allows.append(pending) catch return TranspileError.MemoryAllocationFailed,
            .expect => self.pending_warning_expects.append(pending) catch return TranspileError.MemoryAllocationFailed,
        }
    }

    fn consume_warning_control(self: *Self, id: ast.WarningId) bool {
        // `expect` is one-shot: it asserts exactly one matching warning occurs, so
        // it is marked and won't match a second time.
        for (self.pending_warning_expects.items) |*pending| {
            if (pending.id == id and !pending.matched) {
                pending.matched = true;
                return true;
            }
        }
        // `allow` suppresses EVERY matching warning in its scope, not just the
        // first one — so it is NOT consumed/marked here. (We still flag it matched
        // for the "unused allow" bookkeeping, but keep suppressing subsequent hits.)
        for (self.pending_warning_allows.items) |*pending| {
            if (pending.id == id) {
                pending.matched = true;
                return true;
            }
        }
        return false;
    }

    fn report_warning_expectation_error(self: *Self, pending: PendingWarningControl) void {
        if (!self.flags.emit_stderr) return;

        var buf: [4096]u8 = undefined;
        std.Io.File.stderr().writeStreamingAll(self.io, "\n[Error]\n") catch {};
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "expected warning '{s}' was not emitted; reason: \"{s}\"", .{ ast.warning_id_to_string(pending.id), pending.reason }) catch "") catch {};

        if (pending.pos) |p| {
            const end_line = if (p.end_line == 0) p.line else p.end_line;
            if (end_line == p.line) {
                std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}\n", .{ p.filename, p.line, p.start_col, p.end_col }) catch "") catch {};
            } else {
                std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}:{d}\n", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch "") catch {};
            }
            return;
        }
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}\n", .{ self.pos.filename, self.pos.line, self.pos.col }) catch "") catch {};
    }

    fn finalize_warning_expectations(self: *Self) TranspileError!void {
        var has_unmet = false;
        for (self.pending_warning_expects.items) |pending| {
            if (pending.matched) continue;
            has_unmet = true;
            self.report_warning_expectation_error(pending);
        }
        if (has_unmet) return TranspileError.UnmetWarningExpectation;
    }

    /// Emit a `return_local_ptr` warning if `ret_expr` is `&<name>` where `<name>
    /// is declared in a body-local scope (TypeEnv frame index ≥ 1).  Frame 0
    /// contains module-level globals and function arguments; frames 1+ are pushed
    /// by `check_body` for each nested block and hold true locals.
    fn warn_if_returning_local_ptr_in_env(self: *Self, ret_expr: ast.Node, env: *TypeEnv) void {
        if (ret_expr.type != .Unary or ret_expr.node_variant == null) return;
        const unary = ret_expr.node_variant.?.unary;
        if (!mem.eql(u8, unary.op, "&")) return;

        const operand = unary.operand.*;
        if (operand.type != .Identifier or operand.data == null) return;
        const name = operand.data.?.sval.items;

        // Only warn for locals declared inside a function body (frame 1+).  Frame 0
        // holds module-level globals and function args — those live for the entire
        // call, but taking their address is less dangerous and not warned on here.
        if (env.scopes.items.len < 2) return;
        for (env.scopes.items[1..]) |scope_map| {
            if (scope_map.contains(name)) {
                self.report_warning(.return_local_ptr, operand, "returning address of local variable '{s}' from a pointer-returning function; this pointer will dangle after return", .{name});
                return;
            }
        }
    }

    fn warn_if_returning_address_of_local(self: *Self, ret_expr: ast.Node) void {
        const fn_ret = self.current_fn_return orelse return;
        if (fn_ret.pointer_depth == 0) return;

        if (ret_expr.type != .Unary or ret_expr.node_variant == null) return;
        const unary = ret_expr.node_variant.?.unary;
        if (!mem.eql(u8, unary.op, "&")) return;

        const operand = unary.operand.*;
        if (operand.type != .Identifier or operand.data == null) return;
        const name = operand.data.?.sval.items;

        // Only warn for locals: `get_scope_entity` searches the active scope chain,
        // excluding the global/root scope.
        _ = self.get_scope_entity(name) orelse return;

        self.report_warning(.return_local_ptr, operand, "returning address of local variable '{s}' from a pointer-returning function; this pointer will dangle after return", .{name});
    }

    const CheckedType = struct {
        base: dtype.DataTypeType,
        is_array: bool = false,
        /// Number of array dimensions (e.g. 1 for num[], 2 for num[][], etc.).
        array_depth: usize = 0,
        pointer_depth: usize = 0,
        /// True when this value is the integer literal 0 (C null pointer constant).
        is_null_literal: bool = false,
        /// True when this value is a `panic("msg")` expression -- unifies with
        /// WHATEVER type is expected at its use site (see `can_implicit_coerce`),
        /// same idea as `is_null_literal` but for any type, not just pointers/str.
        is_panic_literal: bool = false,
        /// For user-defined types, `base` is `.Unknown` and `name` holds the identifier.
        name: ?[]const u8 = null,
        /// For generic specializations, a mangled name (e.g. Vec__num).
        mangled_name: ?[]const u8 = null,
        /// Optional backing dtype (preserves generic args for named types).
        dtype_ref: ?*const dtype.DataType = null,

        fn eql(a: CheckedType, b: CheckedType) bool {
            if (a.base != b.base) return false;
            if (a.is_array != b.is_array) return false;
            if (a.array_depth != b.array_depth) return false;
            if (a.pointer_depth != b.pointer_depth) return false;
            const a_name = a.mangled_name orelse a.name;
            const b_name = b.mangled_name orelse b.name;
            if (a_name == null and b_name == null) return true;
            if (a_name == null or b_name == null) return false;
            return mem.eql(u8, a_name.?, b_name.?);
        }
    };

    const FnSig = struct {
        rtype: CheckedType,
        args: []CheckedType,
        is_variadic: bool = false,
        is_async: bool = false,
        type_params: ?*const utils.Vector(ArrayList(u8)) = null,
        /// Minimum required positional args = count of params with NO default value.
        /// Sentinel `maxInt` means "unset" → treated as `args.len` (no defaults), so any
        /// FnSig built without explicitly setting this behaves exactly as before. A call
        /// may pass between `effectiveMinArgs()` and `args.len` args; the missing trailing
        /// ones are filled with the callee's default expressions at emission.
        min_args: usize = std.math.maxInt(usize),

        fn effectiveMinArgs(self: FnSig) usize {
            return if (self.min_args == std.math.maxInt(usize)) self.args.len else self.min_args;
        }
    };

    /// Count leading params that have no default value (the minimum a caller must pass).
    /// Trailing-only enforcement (Phase: validate_default_param_order) guarantees all
    /// defaulted params come last, so this is simply the index of the first defaulted param.
    /// True if an expression node references the bare identifier `name` anywhere.
    /// Conservative recursive walk over the common expression shapes; used to reject a
    /// parameter default that depends on `self` or an earlier parameter (such defaults are
    /// materialized in the CALLER's scope where those names don't exist).
    fn default_expr_references_name(node: *const ast.Node, name: []const u8) bool {
        if (node.node_variant == null) {
            if (node.type == .Identifier and node.data != null) {
                return mem.eql(u8, node.data.?.sval.items, name);
            }
            return false;
        }
        switch (node.type) {
            .Identifier => {
                if (node.data) |d| return mem.eql(u8, d.sval.items, name);
                return false;
            },
            .Expression => {
                const e = node.node_variant.?.exp;
                if (e.left) |l| if (default_expr_references_name(l, name)) return true;
                if (e.right) |r| if (default_expr_references_name(r, name)) return true;
                return false;
            },
            .ExpressionParenthesis => return default_expr_references_name(node.node_variant.?.paren.exp, name),
            .Unary => return default_expr_references_name(node.node_variant.?.unary.operand, name),
            else => return false,
        }
    }

    /// Validate a function/method's parameter defaults:
    /// 1. Defaults must be TRAILING (`fun f(num x = 1, num y)` is rejected) — a call fills
    ///    the omitted tail, so a required param can't follow a defaulted one.
    /// 2. A default expression must be SELF-CONTAINED: it may not reference `self` or an
    ///    earlier parameter, because the default is materialized at the CALL SITE where
    ///    those names aren't in scope (emitting `f(&c, self.cfg)` would be invalid C).
    /// Reports a type error and returns it on violation; no-op when valid.
    fn validate_default_param_order(self: *Self, fnv_args: ?utils.Vector(*ast.Node), node: ast.Node) TranspileError!void {
        const args = (fnv_args orelse return).items();
        var seen_default = false;
        for (args, 0..) |arg_ptr, i| {
            const arg = arg_ptr.*;
            if (arg.type != .Variable or arg.node_variant == null) continue;
            const v = arg.node_variant.?.variable;
            if (v.val) |dflt| {
                seen_default = true;
                // Reject reference to `self`.
                if (default_expr_references_name(dflt, "self")) {
                    self.report_type_error(node, "a parameter default cannot reference 'self' (defaults are evaluated at the call site)", .{});
                    return TranspileError.TypeMismatch;
                }
                // Reject reference to any EARLIER parameter.
                var j: usize = 0;
                while (j < i) : (j += 1) {
                    const prev = args[j].*;
                    if (prev.type != .Variable or prev.node_variant == null) continue;
                    const pname = prev.node_variant.?.variable.name.items;
                    if (default_expr_references_name(dflt, pname)) {
                        self.report_type_error(node, "a parameter default cannot reference an earlier parameter '{s}'", .{pname});
                        return TranspileError.TypeMismatch;
                    }
                }
            } else if (seen_default) {
                self.report_type_error(node, "a parameter without a default cannot follow a parameter with a default", .{});
                return TranspileError.WrongArgCount;
            }
        }
    }

    fn normalize_expr_to_expected_type(self: *Self, expr: *ast.Node, expected: CheckedType, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!void {
        if (expr.type == .CompoundInit) {
            try self.bind_compound_init_expected(expr, expected, env, fns);
        }
        if (self.expected_enum_name(expected)) |enum_name| {
            if (dot_shorthand_variant_name(expr)) |_| {
                _ = try self.resolve_dot_shorthand_enum_variant(expr, enum_name);
            }
            try self.resolve_shorthand_enum_call(expr, enum_name);
            try self.bind_enum_ctor_expected(expr, expected);
        }
    }

    fn validate_parameter_defaults(self: *Self, fnv_args: ?utils.Vector(*ast.Node), owner: ast.Node, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!void {
        const args = (fnv_args orelse return).items();
        for (args) |arg_ptr| {
            const arg = arg_ptr.*;
            if (arg.type != .Variable or arg.node_variant == null) continue;
            const v = arg.node_variant.?.variable;
            const dflt = v.val orelse continue;
            const expected = try self.type_from_dtype_with_mangled(v.type);
            try self.normalize_expr_to_expected_type(dflt, expected, env, fns);
            const actual = try self.infer_expr_type(dflt.*, env, fns);
            if (is_known_type(expected) and is_known_type(actual) and !(try self.can_implicit_coerce(expected, actual))) {
                self.report_type_error(owner, "type mismatch in default value for parameter '{s}'", .{v.name.items});
                return TranspileError.TypeMismatch;
            }
            self.check_int_literal_range(v.type, dflt, owner);
        }
    }

    fn count_required_args_from_node(args_vec: utils.Vector(*ast.Node)) usize {
        const items = args_vec.items();
        var n: usize = 0;
        for (items) |arg_ptr| {
            const arg = arg_ptr.*;
            const has_default = arg.type == .Variable and arg.node_variant != null and
                arg.node_variant.?.variable.val != null;
            if (has_default) break;
            n += 1;
        }
        return n;
    }

    const AwaitLoweringInfo = struct {
        callee_name: []const u8,
        receiver_expr: ?*ast.Node = null,
        receiver_pass_by_ref: bool = false,
    };

    /// Resolved element-typing info for a `for item : <iterable>` loop over
    /// a Vec, recorded once during typecheck (which already infers arbitrary
    /// expressions fine via `infer_expr_type`) and read back during codegen
    /// via `lookup_for_iter_override` -- so the emission path isn't limited
    /// to re-deriving this from a bare identifier's scope entity the way the
    /// raw-C-array fast path still has to (that path's `sizeof`-based length
    /// computation is inherently identifier-only; this override is what
    /// lets the SEPARATE Vec fast path support any expression instead).
    const ForIterInfo = struct {
        vec_item_dt: ?*dtype.DataType = null,
    };

    const AwaitCallOverride = struct {
        callee_name: []const u8,
        has_receiver: bool = false,
        receiver_pass_by_ref: bool = false,
        dynamic_quirk_dispatch: bool = false,
    };

    const GenericFnInstantiation = struct {
        fn_node: *ast.Node,
        params: *const utils.Vector(ArrayList(u8)),
        args: []*dtype.DataType,
        name: []const u8,
        /// The generic function whose template body this call site was found
        /// in, if any (null for calls made from ordinary, non-generic code).
        /// See `typecheck_owner_fn` for why identity, not name, is used to
        /// scope `resolve_transitive_generic_fn_instantiations`'s substitution.
        owner_fn: ?*ast.Node = null,
        /// For a METHOD with its own type param (`impl Box<T> { pub map<U>(...) }`),
        /// `params`/`args` are the impl-level params/args (e.g. ["T"]) followed by
        /// the method's own (e.g. ["U"]) -- this is how many of the LEADING
        /// entries belong to the impl, so `resolve_transitive_generic_fn_instantiations`
        /// can reconstruct the method naming convention (`Type__method__ownargs`)
        /// instead of the free-function one (`fn_name__allargs`) when re-mangling
        /// a placeholder found by IDENTITY under a method's own node. 0 for a
        /// free function or an ordinary (non-generic-method) method.
        impl_arg_count: usize = 0,
    };

    const PendingWarningControl = struct {
        id: ast.WarningId,
        reason: []const u8,
        pos: ?token.Pos,
        matched: bool = false,
    };

    const TypeEnv = struct {
        const TypeBinding = struct {
            ty: CheckedType,
            decl_node: ?*ast.Node = null,
            warn_on_unused: bool = false,
            used: bool = false,
        };

        allocator: mem.Allocator,
        scopes: ArrayList(std.StringHashMap(TypeBinding)),
        type_params: ?[]const []const u8 = null,

        fn init(allocator: mem.Allocator) TypeEnv {
            return .{
                .allocator = allocator,
                .scopes = ArrayList(std.StringHashMap(TypeBinding)).init(allocator),
                .type_params = null,
            };
        }

        fn deinit(self: *TypeEnv) void {
            for (self.scopes.items) |*scope_map| {
                scope_map.deinit();
            }
            self.scopes.deinit();
        }

        fn push(self: *TypeEnv) TranspileError!void {
            self.scopes.append(std.StringHashMap(TypeBinding).init(self.allocator)) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        fn pop(self: *TypeEnv) void {
            if (self.scopes.pop()) |popped| {
                var last = popped;
                last.deinit();
            }
        }

        fn put_current(self: *TypeEnv, name: []const u8, ty: CheckedType) TranspileError!void {
            return self.put_current_binding(name, ty, null, false);
        }

        fn put_current_marked(self: *TypeEnv, name: []const u8, ty: CheckedType, decl_node: ?*ast.Node) TranspileError!void {
            return self.put_current_binding(name, ty, decl_node, false);
        }

        fn put_current_decl(self: *TypeEnv, name: []const u8, ty: CheckedType, decl_node: ?*ast.Node) TranspileError!void {
            return self.put_current_binding(name, ty, decl_node, true);
        }

        fn put_current_binding(self: *TypeEnv, name: []const u8, ty: CheckedType, decl_node: ?*ast.Node, warn_on_unused: bool) TranspileError!void {
            if (self.scopes.items.len == 0) return TranspileError.MemoryAllocationFailed;
            var scope_map = &self.scopes.items[self.scopes.items.len - 1];
            scope_map.put(name, .{ .ty = ty, .decl_node = decl_node, .warn_on_unused = warn_on_unused }) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        fn get(self: *TypeEnv, name: []const u8) ?CheckedType {
            var i: usize = self.scopes.items.len;
            while (i > 0) : (i -= 1) {
                var scope_map = &self.scopes.items[i - 1];
                if (scope_map.getPtr(name)) |binding| {
                    binding.used = true;
                    if (binding.decl_node) |decl_node| {
                        if (decl_node.flags == null) decl_node.flags = .{};
                        decl_node.flags.?.is_used = true;
                    }
                    return binding.ty;
                }
            }
            return null;
        }

        /// Looks up `name`'s own DECLARING node (the `.Variable` node this
        /// binding was registered from — see `put_current_decl`), without
        /// marking it used (unlike `get`) — used by `check_const_reassignment`
        /// to read the declaration's own `is_const` flag, a check that
        /// shouldn't itself count as a "read" of the binding.
        fn get_decl_node(self: *TypeEnv, name: []const u8) ?*ast.Node {
            var i: usize = self.scopes.items.len;
            while (i > 0) : (i -= 1) {
                var scope_map = &self.scopes.items[i - 1];
                if (scope_map.getPtr(name)) |binding| {
                    return binding.decl_node;
                }
            }
            return null;
        }

        fn set_type_params(self: *TypeEnv, params: ?[]const []const u8) void {
            self.type_params = params;
        }

        fn has_type_param(self: *TypeEnv, name: []const u8) bool {
            if (self.type_params) |params| {
                for (params) |p| {
                    if (mem.eql(u8, p, name)) return true;
                }
            }
            return false;
        }
    };

    fn should_warn_unused_variable(name: []const u8) bool {
        if (name.len == 0) return false;
        if (mem.eql(u8, name, "_")) return false;
        // A leading underscore marks a binding/parameter as intentionally unused
        // (e.g. a generic-type witness param like `_default_value`), suppressing
        // the warning without dropping the name — the same convention as Zig/Rust.
        if (name[0] == '_') return false;
        if (mem.eql(u8, name, "self")) return false;
        if (mem.eql(u8, name, "vargs")) return false;
        return true;
    }

    fn warn_unused_bindings_in_current_scope(self: *Self, env: *TypeEnv) void {
        if (!self.flags.emit_unused_warnings) return;
        if (self.is_importing) return;
        if (env.scopes.items.len == 0) return;

        var scope_map = &env.scopes.items[env.scopes.items.len - 1];
        var it = scope_map.iterator();
        while (it.next()) |entry| {
            const name = entry.key_ptr.*;
            const binding = entry.value_ptr;
            if (binding.used) continue;
            if (binding.decl_node == null) continue;
            if (!binding.warn_on_unused) continue;
            if (!should_warn_unused_variable(name)) continue;

            const decl_node = binding.decl_node.?;
            self.report_warning(.unused_variable, decl_node.*, "unused variable '{s}'", .{name});
        }
    }

    fn fit_branch_warning_node(branch: ast.FitBranch) ast.Node {
        if (branch.condition) |cond| return cond.*;
        return branch.body.*;
    }

    fn fit_branch_enum_variant_name(enum_name: []const u8, cond: *ast.Node) ?[]const u8 {
        if (dot_shorthand_variant_name(cond)) |short_name| return short_name;
        if (cond.type != .Expression or cond.node_variant == null) return null;

        const exp = cond.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, ".")) return null;

        const left = exp.left orelse return null;
        const right = exp.right orelse return null;
        if (left.type != .Identifier or left.data == null) return null;
        if (right.type != .Identifier or right.data == null) return null;
        if (!mem.eql(u8, left.data.?.sval.items, enum_name)) return null;
        return right.data.?.sval.items;
    }

    fn warn_if_fit_has_unreachable_branches(self: *Self, condition_type: CheckedType, branches: []const ast.FitBranch) void {
        var saw_default = false;
        var has_true = false;
        var has_false = false;

        const enum_name = self.expected_enum_name(condition_type);
        const root = self.get_root();
        const enum_variant_count: usize = blk: {
            if (enum_name == null or root.type_registry == null) break :blk 0;
            const reg = &root.type_registry.?;
            const enode = reg.enums_by_name.get(enum_name.?) orelse break :blk 0;
            if (enode.node_variant == null) break :blk 0;
            break :blk enode.node_variant.?.enum_decl.variants.items().len;
        };

        var seen_variants = std.StringHashMap(bool).init(self.backing_allocator);
        defer seen_variants.deinit();
        var seen_variant_count: usize = 0;

        for (branches) |branch| {
            const warn_node = fit_branch_warning_node(branch);

            if (branch.condition == null) {
                if (saw_default) {
                    self.report_warning(.fit_unreachable_branch, warn_node, "fit branch is unreachable because a catch-all '_' branch was already handled earlier", .{});
                } else if (condition_type.base == .Bin and has_true and has_false) {
                    self.report_warning(.fit_unreachable_branch, warn_node, "fit catch-all '_' branch is unreachable because earlier branches already cover all bin values", .{});
                } else if (enum_name != null and enum_variant_count != 0 and seen_variant_count == enum_variant_count) {
                    self.report_warning(.fit_unreachable_branch, warn_node, "fit catch-all '_' branch is unreachable because earlier branches already cover all variants of enum '{s}'", .{enum_name.?});
                }

                saw_default = true;
                continue;
            }

            const cond = branch.condition.?;
            if (saw_default) {
                self.report_warning(.fit_unreachable_branch, warn_node, "fit branch is unreachable because a catch-all '_' branch was already handled earlier", .{});
                continue;
            }

            if (condition_type.base == .Bin and cond.*.type == .Boolean) {
                const cond_value = cond.data != null and cond.data.?.bval;
                if (cond_value) {
                    if (has_true) {
                        self.report_warning(.fit_unreachable_branch, warn_node, "fit branch is unreachable because condition 'true' was already handled earlier", .{});
                    } else {
                        has_true = true;
                    }
                } else {
                    if (has_false) {
                        self.report_warning(.fit_unreachable_branch, warn_node, "fit branch is unreachable because condition 'false' was already handled earlier", .{});
                    } else {
                        has_false = true;
                    }
                }
                continue;
            }

            if (enum_name) |name| {
                if (fit_branch_enum_variant_name(name, cond)) |variant_name| {
                    if (seen_variants.contains(variant_name)) {
                        self.report_warning(.fit_unreachable_branch, warn_node, "fit branch is unreachable because variant '{s}.{s}' was already handled earlier", .{ name, variant_name });
                    } else {
                        seen_variants.put(variant_name, true) catch {};
                        seen_variant_count += 1;
                    }
                }
            }
        }
    }

    fn report_type_error(self: *Self, node: ?ast.Node, comptime fmt: []const u8, args: anytype) void {
        if (!self.flags.emit_stderr) return;

        var buf: [4096]u8 = undefined;
        std.Io.File.stderr().writeStreamingAll(self.io, "\n[TypeError]\n") catch {};
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, fmt, args) catch fmt) catch {};

        if (node) |n| {
            if (n.pos) |p| {
                const end_line = if (p.end_line == 0) p.line else p.end_line;
                if (end_line == p.line) {
                    std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}\n", .{ p.filename, p.line, p.start_col, p.end_col }) catch "") catch {};
                } else {
                    std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}:{d}\n", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch "") catch {};
                }
                return;
            }
        }
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}\n", .{ self.pos.filename, self.pos.line, self.pos.col }) catch "") catch {};
    }

    fn report_warning(self: *Self, id: ast.WarningId, node: ?ast.Node, comptime fmt: []const u8, args: anytype) void {
        if (self.consume_warning_control(id)) return;

        var warn_buf: [4096]u8 = undefined;

        if (self.flags.emit_stderr) {
            std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&warn_buf, "\n[Warning:{s}]\n", .{ast.warning_id_to_string(id)}) catch "\n[Warning]\n") catch {};
            std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&warn_buf, fmt, args) catch fmt) catch {};
        }

        // Warnings are advisory: if the in-memory buffer can't grow (OOM), drop
        // the text rather than panic the whole compile via `catch unreachable`.
        self.warnings.print("\n[Warning:{s}]\n", .{ast.warning_id_to_string(id)}) catch {};
        self.warnings.print(fmt, args) catch {};

        if (node) |n| {
            if (n.pos) |p| {
                const end_line = if (p.end_line == 0) p.line else p.end_line;
                if (end_line == p.line) {
                    const loc = std.fmt.bufPrint(&warn_buf, "\nLocation: {s}:{d}:{d}-{d}\n", .{ p.filename, p.line, p.start_col, p.end_col }) catch "";
                    if (self.flags.emit_stderr) std.Io.File.stderr().writeStreamingAll(self.io, loc) catch {};
                    self.warnings.print("\nLocation: {s}:{d}:{d}-{d}\n", .{ p.filename, p.line, p.start_col, p.end_col }) catch {};
                } else {
                    const loc = std.fmt.bufPrint(&warn_buf, "\nLocation: {s}:{d}:{d}-{d}:{d}\n", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch "";
                    if (self.flags.emit_stderr) std.Io.File.stderr().writeStreamingAll(self.io, loc) catch {};
                    self.warnings.print("\nLocation: {s}:{d}:{d}-{d}:{d}\n", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch {};
                }
                return;
            }
        }

        const loc = std.fmt.bufPrint(&warn_buf, "\nLocation: {s}:{d}:{d}\n", .{ self.pos.filename, self.pos.line, self.pos.col }) catch "";
        if (self.flags.emit_stderr) std.Io.File.stderr().writeStreamingAll(self.io, loc) catch {};
        self.warnings.print("\nLocation: {s}:{d}:{d}\n", .{ self.pos.filename, self.pos.line, self.pos.col }) catch {};
    }

    fn report_error(self: *Self, node: ?ast.Node, comptime fmt: []const u8, args: anytype) void {
        if (!self.flags.emit_stderr) return;

        var buf: [4096]u8 = undefined;
        std.Io.File.stderr().writeStreamingAll(self.io, "\n[Error]\n") catch {};
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, fmt, args) catch fmt) catch {};

        if (node) |n| {
            if (n.pos) |p| {
                const end_line = if (p.end_line == 0) p.line else p.end_line;
                if (end_line == p.line) {
                    std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}\n", .{ p.filename, p.line, p.start_col, p.end_col }) catch "") catch {};
                } else {
                    std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}-{d}:{d}\n", .{ p.filename, p.line, p.start_col, end_line, p.end_col }) catch "") catch {};
                }
                return;
            }
        }
        std.Io.File.stderr().writeStreamingAll(self.io, std.fmt.bufPrint(&buf, "\nLocation: {s}:{d}:{d}\n", .{ self.pos.filename, self.pos.line, self.pos.col }) catch "") catch {};
    }

    fn type_from_dtype(dt: *const dtype.DataType) CheckedType {
        const base = dt.type orelse .Unknown;
        const is_arr = (dt.flags != null and dt.flags.?.is_array);
        // Backward compat: if is_array is set but array_depth wasn't populated (legacy), treat as depth 1.
        const depth = if (is_arr and dt.array_depth == 0) 1 else dt.array_depth;
        return .{
            .base = base,
            .is_array = is_arr,
            .array_depth = depth,
            .pointer_depth = dt.pointer_depth,
            .name = if (base == .Unknown and dt.type_str.items.len > 0) dt.type_str.items else null,
            .dtype_ref = dt,
        };
    }

    fn type_from_dtype_with_mangled(self: *Self, dt: *const dtype.DataType) TranspileError!CheckedType {
        var t = type_from_dtype(dt);
        if (dt.type == .Unknown and dt.generic_args != null) {
            t.mangled_name = try self.type_name_mangled(dt);
        }
        return t;
    }

    /// Builds a `FnSig` (the shape ordinary call-checking already knows how to
    /// validate arguments/arity against) from a function-TYPE parameter's
    /// `dtype.FnTypeSig` (params + return type parsed from `fun(T1, T2) R`).
    fn fn_sig_from_dtype_fn_sig(self: *Self, sig: *const dtype.FnTypeSig) TranspileError!FnSig {
        var args = ArrayList(CheckedType).initCapacity(self.allocator, sig.params.count) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        for (sig.params.items()) |p| {
            args.append(type_from_dtype(p)) catch return TranspileError.MemoryAllocationFailed;
        }
        return .{
            .rtype = type_from_dtype(sig.rtype),
            .args = args.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed,
        };
    }

    fn ensure_named_type_visible(self: *Self, ref_node: ast.Node, name: []const u8) TranspileError!void {
        const base_name = if (mem.indexOf(u8, name, "__")) |idx| name[0..idx] else name;
        // Builtins are always visible.
        if (mem.eql(u8, base_name, "void") or mem.eql(u8, base_name, "raw") or mem.eql(u8, base_name, "num") or mem.eql(u8, base_name, "dec") or mem.eql(u8, base_name, "str") or mem.eql(u8, base_name, "bin") or mem.eql(u8, base_name, "chr")) {
            return;
        }

        // Known C typedef aliases are treated as externally visible. (Marking
        // the owning std.c.* import used is handled in `ensure_dtype_visible`,
        // the common entry point for all type positions, since the typedef's
        // semantic type is often resolved to a primitive before reaching here.)
        if (utils.get_c_typedef_alias_datatype_type(base_name) != null) {
            return;
        }

        // Allow stdarg.h variadic type.
        if (mem.eql(u8, base_name, "va_list")) {
            return;
        }

        const reg = self.root_registry() orelse {
            self.report_type_error(ref_node, "unknown type '{s}'", .{name});
            return TranspileError.SymbolNotDefined;
        };

        // Prefer the full name (supports alias-qualified types like `m__User`),
        // then fall back to the base prefix for legacy mangled/derived lookups.
        var names_buf: [2][]const u8 = undefined;
        var names_len: usize = 1;
        names_buf[0] = name;
        if (!mem.eql(u8, name, base_name)) {
            names_buf[1] = base_name;
            names_len = 2;
        }

        for (names_buf[0..names_len]) |cand| {
            if (reg.enums_by_name.get(cand)) |enode| {
                if (!self.can_access(&ref_node, enode)) {
                    self.report_type_error(ref_node, "type '{s}' is private", .{cand});
                    return TranspileError.SymbolNotDefined;
                }
                self.mark_node_used_and_sync_top_level_copy(enode);
                if (!same_module(&ref_node, enode)) {
                    if (enode.pos) |p| self.mark_import_used_by_origin_file(p.filename);
                }
                return;
            }

            if (reg.compounds_by_name.get(cand)) |cnode| {
                if (!self.can_access(&ref_node, cnode)) {
                    self.report_type_error(ref_node, "type '{s}' is private", .{cand});
                    return TranspileError.SymbolNotDefined;
                }
                self.mark_node_used_and_sync_top_level_copy(cnode);
                if (std.mem.indexOf(u8, cand, "__")) |idx| {
                    const alias = cand[0..idx];
                    if (self.alias_map_for_node(&ref_node).contains(alias)) {
                        self.mark_import_used_by_alias(alias);
                    }
                } else if (!same_module(&ref_node, cnode)) {
                    if (cnode.pos) |p| self.mark_import_used_by_origin_file(p.filename);
                }
                return;
            }

            if (reg.quirk_sig_by_name.get(cand)) |sig| {
                const qnode = reg.quirks_by_sig.get(sig) orelse null;
                if (qnode == null or qnode.?.node_variant == null) {
                    self.report_type_error(ref_node, "unknown type '{s}'", .{cand});
                    return TranspileError.SymbolNotDefined;
                }
                if (!self.can_access(&ref_node, qnode.?)) {
                    self.report_type_error(ref_node, "type '{s}' is private", .{cand});
                    return TranspileError.SymbolNotDefined;
                }
                self.mark_node_used_and_sync_top_level_copy(qnode.?);
                if (!same_module(&ref_node, qnode.?)) {
                    if (qnode.?.pos) |p| self.mark_import_used_by_origin_file(p.filename);
                }
                return;
            }
        }

        self.report_type_error(ref_node, "unknown type '{s}'", .{name});
        return TranspileError.SymbolNotDefined;
    }

    fn ensure_dtype_visible(self: *Self, ref_node: ast.Node, dt: *const dtype.DataType, allow: ?[]const []const u8) TranspileError!void {
        // A function-type parameter (`fun(T1, T2) R`) is not a named type to
        // look up -- `type_str` is just a synthesized display string. Recurse
        // into its param/return types instead (so THEIR visibility is still
        // checked) and skip the named-type lookup below entirely.
        if (dt.fn_sig) |sig| {
            for (sig.params.items()) |p| try self.ensure_dtype_visible(ref_node, p, allow);
            try self.ensure_dtype_visible(ref_node, sig.rtype, allow);
            return;
        }
        // A C typedef type name (`size_t`, `time_t`, `FILE`, `va_list`, …) is
        // resolved to a primitive semantic type during parsing, so `dt.type` is
        // often non-Unknown and the visibility check below is skipped. Mark the
        // std.c.* module that documents the typedef as used here, regardless of
        // the resolved semantic type, so importing it for such a type is not
        // reported as unused. Recurses into generic args via the loop below.
        if (dt.type_str.items.len > 0) {
            if (c_typedef_owner_module(dt.type_str.items)) |owner| {
                self.mark_import_used_by_path(owner);
            }
        }
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            if (allow) |list| {
                for (list) |p| {
                    if (mem.eql(u8, p, dt.type_str.items)) return;
                }
                if (dt.type_str.items.len == 1) {
                    const c = dt.type_str.items[0];
                    if (c >= 'A' and c <= 'Z') return;
                }
            } else if (dt.type_str.items.len == 1) {
                const c = dt.type_str.items[0];
                if (c >= 'A' and c <= 'Z') return;
            }
            try self.ensure_named_type_visible(ref_node, dt.type_str.items);
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                try self.ensure_dtype_visible(ref_node, ga, allow);
            }
            // Enforce constrained generic COMPOUNDS (`compound Box<T: num | str>`):
            // a concrete instantiation like `Box<bin>` must satisfy the declared
            // bound. Only check when every generic arg is a concrete/known type
            // (not a still-symbolic type param inside the compound's own impl),
            // to avoid false positives during generic-body typechecking.
            const base = if (mem.indexOf(u8, dt.type_str.items, "__")) |i| dt.type_str.items[0..i] else dt.type_str.items;
            if (self.root_registry()) |reg| {
                if (reg.compounds_by_name.get(base)) |cnode| {
                    if (cnode.node_variant != null) {
                        if (cnode.node_variant.?.compound.type_param_forced_insts) |forced| {
                            const arg_items = gargs.items();
                            var all_concrete = true;
                            for (arg_items) |ga| {
                                const gt = type_from_dtype(ga);
                                if (!is_known_type(gt) or (allow != null and self.dtype_names_type_param(ga, allow.?))) {
                                    all_concrete = false;
                                    break;
                                }
                            }
                            if (all_concrete and !impl_allows_generic_args(forced, arg_items)) {
                                self.report_type_error(ref_node, "'{s}' does not satisfy its generic constraint: type argument is not in the declared bound", .{dt.type_str.items});
                                return TranspileError.TypeMismatch;
                            }
                        }
                    }
                }
            }
        }
    }

    /// True when `dt`'s type name is one of the allowed (still-symbolic) type
    /// parameter names in `allow` (e.g. `T` inside `impl Box<T>`), so constraint
    /// enforcement should be skipped for it.
    fn dtype_names_type_param(self: *Self, dt: *const dtype.DataType, allow: []const []const u8) bool {
        _ = self;
        for (allow) |p| {
            if (mem.eql(u8, p, dt.type_str.items)) return true;
        }
        return false;
    }

    fn is_known_type(t: CheckedType) bool {
        return t.base != .Unknown or t.name != null;
    }

    fn is_user_named_type(t: CheckedType) bool {
        return t.base == .Unknown and t.name != null;
    }

    fn node_is_public(node: *const ast.Node) bool {
        return node.flags != null and node.flags.?.is_public;
    }

    fn node_is_used(node: *const ast.Node) bool {
        return node.flags != null and node.flags.?.is_used;
    }

    fn mark_node_used(node: *ast.Node) void {
        if (node.flags == null) node.flags = .{};
        node.flags.?.is_used = true;
    }

    /// Single source of truth mapping a best-effort C macro/constant identifier
    /// to the `std.c.*` module that documents it. Returns null for names that are
    /// not recognized C builtins. Drives both the value typing in
    /// `infer_expr_type` (Identifier) and the import-usage marking, so the two
    /// can never drift. Keep in sync with the C-binding doc modules under
    /// `stdlib/std/c/`.
    fn c_builtin_owner_module(name: []const u8) ?[]const u8 {
        const Entry = struct { name: []const u8, module: []const u8 };
        const table = [_]Entry{
            // stddef.h -> std.c.def
            .{ .name = "NULL", .module = "std.c.def" },
            .{ .name = "SIZE_MAX", .module = "std.c.def" },
            .{ .name = "RSIZE_MAX", .module = "std.c.def" },
            .{ .name = "PTRDIFF_MIN", .module = "std.c.def" },
            .{ .name = "PTRDIFF_MAX", .module = "std.c.def" },
            .{ .name = "WCHAR_MIN", .module = "std.c.def" },
            .{ .name = "WCHAR_MAX", .module = "std.c.def" },
            .{ .name = "WINT_MIN", .module = "std.c.def" },
            .{ .name = "WINT_MAX", .module = "std.c.def" },
            // stdio.h -> std.c.io
            .{ .name = "EOF", .module = "std.c.io" },
            .{ .name = "SEEK_SET", .module = "std.c.io" },
            .{ .name = "SEEK_CUR", .module = "std.c.io" },
            .{ .name = "SEEK_END", .module = "std.c.io" },
            // stdlib.h -> std.c.mem
            .{ .name = "EXIT_SUCCESS", .module = "std.c.mem" },
            .{ .name = "EXIT_FAILURE", .module = "std.c.mem" },
            // limits.h -> std.c.limits
            .{ .name = "CHAR_BIT", .module = "std.c.limits" },
            .{ .name = "MB_LEN_MAX", .module = "std.c.limits" },
            .{ .name = "SCHAR_MIN", .module = "std.c.limits" },
            .{ .name = "SCHAR_MAX", .module = "std.c.limits" },
            .{ .name = "UCHAR_MAX", .module = "std.c.limits" },
            .{ .name = "CHAR_MIN", .module = "std.c.limits" },
            .{ .name = "CHAR_MAX", .module = "std.c.limits" },
            .{ .name = "SHRT_MIN", .module = "std.c.limits" },
            .{ .name = "SHRT_MAX", .module = "std.c.limits" },
            .{ .name = "USHRT_MAX", .module = "std.c.limits" },
            .{ .name = "INT_MAX", .module = "std.c.limits" },
            .{ .name = "INT_MIN", .module = "std.c.limits" },
            .{ .name = "UINT_MAX", .module = "std.c.limits" },
            .{ .name = "LONG_MAX", .module = "std.c.limits" },
            .{ .name = "LONG_MIN", .module = "std.c.limits" },
            .{ .name = "ULONG_MAX", .module = "std.c.limits" },
            .{ .name = "LLONG_MAX", .module = "std.c.limits" },
            .{ .name = "LLONG_MIN", .module = "std.c.limits" },
            .{ .name = "ULLONG_MAX", .module = "std.c.limits" },
            // time.h -> std.c.time
            .{ .name = "CLOCKS_PER_SEC", .module = "std.c.time" },
        };
        for (table) |e| {
            if (mem.eql(u8, name, e.name)) return e.module;
        }
        return null;
    }

    /// Single source of truth mapping a best-effort C typedef *type name*
    /// (`size_t`, `time_t`, `FILE`, `va_list`, `pthread_*`, …) to the `std.c.*`
    /// module that documents it. Returns null for names with no owning Fun module
    /// (e.g. `stdint.h` types like `int32_t`/`intptr_t`, which have no `std.c.*`
    /// module and are available for free via included headers).
    ///
    /// These names resolve in `ensure_named_type_visible` (type position) — the
    /// type-position analogue of `c_builtin_owner_module` (value position). Keep
    /// the member set aligned with `utils.get_c_typedef_alias_datatype_type`.
    fn c_typedef_owner_module(name: []const u8) ?[]const u8 {
        const Entry = struct { name: []const u8, module: []const u8 };
        const table = [_]Entry{
            // stddef.h -> std.c.def
            .{ .name = "size_t", .module = "std.c.def" },
            .{ .name = "ptrdiff_t", .module = "std.c.def" },
            .{ .name = "wchar_t", .module = "std.c.def" },
            .{ .name = "rsize_t", .module = "std.c.def" },
            .{ .name = "ssize_t", .module = "std.c.def" },
            // stdarg.h is documented alongside stddef in std.c.def
            .{ .name = "va_list", .module = "std.c.def" },
            // time.h -> std.c.time
            .{ .name = "time_t", .module = "std.c.time" },
            .{ .name = "clock_t", .module = "std.c.time" },
            // stdio.h -> std.c.io
            .{ .name = "FILE", .module = "std.c.io" },
            // pthread.h -> std.c.thread
            .{ .name = "pthread_t", .module = "std.c.thread" },
            .{ .name = "pthread_attr_t", .module = "std.c.thread" },
            .{ .name = "pthread_mutex_t", .module = "std.c.thread" },
            .{ .name = "pthread_mutexattr_t", .module = "std.c.thread" },
            .{ .name = "pthread_cond_t", .module = "std.c.thread" },
            .{ .name = "pthread_condattr_t", .module = "std.c.thread" },
            // spawn.h / sys/wait.h -> std.c.process
            .{ .name = "pid_t", .module = "std.c.process" },
            .{ .name = "posix_spawn_file_actions_t", .module = "std.c.process" },
            .{ .name = "posix_spawnattr_t", .module = "std.c.process" },
            // NOTE: stdint.h types (int*_t / intptr_t / uintptr_t) intentionally
            // omitted — there is no std.c.stdint Fun module to attribute them to.
        };
        for (table) |e| {
            if (mem.eql(u8, name, e.name)) return e.module;
        }
        return null;
    }

    fn mark_node_used_and_sync_top_level_copy(self: *Self, node: *ast.Node) void {
        mark_node_used(node);

        const target_pos = node.pos orelse return;
        for (self.nodes.items()) |*candidate| {
            if (candidate.type != node.type) continue;
            const candidate_pos = candidate.pos orelse continue;
            if (!mem.eql(u8, candidate_pos.filename, target_pos.filename)) continue;
            if (candidate_pos.line != target_pos.line) continue;
            if (candidate_pos.start_col != target_pos.start_col) continue;
            if (candidate_pos.end_col != target_pos.end_col) continue;
            mark_node_used(candidate);
            return;
        }
    }

    fn import_node_matches_file_path(self: *Self, node: *const ast.Node, file_path: []const u8) bool {
        if (node.type != .Import or node.node_variant == null) return false;
        const imp = node.node_variant.?.import;

        const full_path = blk: {
            if (std.mem.startsWith(u8, imp.path, "std.")) {
                const built = self.build_stdlib_module_path(imp.path) catch return false;
                if (built == null) return false;
                break :blk built.?;
            }
            break :blk self.build_full_import_path(imp.path) catch return false;
        };
        defer self.backing_allocator.free(full_path);

        const canon_opt = std.Io.Dir.cwd().realPathFileAlloc(self.io, full_path, self.allocator) catch null;
        defer if (canon_opt) |canon| self.allocator.free(canon);
        const resolved = canon_opt orelse full_path;
        return std.mem.eql(u8, resolved, file_path);
    }

    fn mark_import_used_by_alias(self: *Self, alias: []const u8) void {
        for (self.nodes.items()) |*node| {
            if (node.type != .Import or node.node_variant == null) continue;
            const imp = node.node_variant.?.import;
            if (imp.alias == null) continue;
            if (!std.mem.eql(u8, imp.alias.?, alias)) continue;
            mark_node_used(node);
            return;
        }
    }

    fn mark_import_used_by_origin_file(self: *Self, file_path: []const u8) void {
        for (self.nodes.items()) |*node| {
            if (node.type != .Import or node.node_variant == null) continue;
            const imp = node.node_variant.?.import;
            if (imp.alias != null) continue;
            if (!self.import_node_matches_file_path(node, file_path)) continue;
            mark_node_used(node);
            return;
        }
    }

    /// True if the module brought in by `import_node` is a "re-export passthrough"
    /// module: it declares no top-level symbols of its own but pulls in other
    /// modules via `imp`. Importing such a module is meaningful even when none of
    /// *its own* names are referenced — its purpose is to forward the symbols it
    /// re-imports (and, for some, to trigger codegen compat layers). The canonical
    /// example is `std.c.thread_windows`, which only does `imp std.c.thread;`.
    ///
    /// Detected from the already-parsed child process (no filesystem re-read):
    /// the child's nodes contain at least one `.Import` and zero own symbol
    /// declarations (function/compound/quirk/enum/typed global).
    fn import_is_reexport_passthrough(self: *Self, import_node: *const ast.Node) bool {
        if (import_node.type != .Import or import_node.node_variant == null) return false;
        const imp = import_node.node_variant.?.import;

        const full_path = blk: {
            if (std.mem.startsWith(u8, imp.path, "std.")) {
                const built = self.build_stdlib_module_path(imp.path) catch return false;
                break :blk built orelse return false;
            }
            break :blk self.build_full_import_path(imp.path) catch return false;
        };
        defer self.backing_allocator.free(full_path);

        const canon_opt = std.Io.Dir.cwd().realPathFileAlloc(self.io, full_path, self.allocator) catch null;
        defer if (canon_opt) |canon| self.allocator.free(canon);
        const resolved = canon_opt orelse full_path;

        const child = self.get_root().find_process_for_file(resolved) orelse return false;

        var has_import = false;
        for (child.nodes.items()) |n| {
            switch (n.type) {
                .Import => has_import = true,
                .Function, .Compound, .Enum, .Quirk, .Impl, .Variable => return false,
                else => {},
            }
        }
        return has_import;
    }

    /// Marks the import of `module_path` (e.g. "std.c.def") as used by matching
    /// the import node's declared path. Used for signature-only C-binding modules
    /// that declare no Fun symbols, so usage cannot be detected via the origin
    /// file. Matches the canonical `std.*` form (legacy `stdlib.std.*` is
    /// rewritten per `process_import`) and handles aliased imports.
    fn mark_import_used_by_path(self: *Self, module_path: []const u8) void {
        for (self.nodes.items()) |*node| {
            if (node.type != .Import or node.node_variant == null) continue;
            const imp = node.node_variant.?.import;
            const canon = if (std.mem.startsWith(u8, imp.path, "stdlib.std."))
                imp.path["stdlib.".len..]
            else
                imp.path;
            if (!std.mem.eql(u8, canon, module_path)) continue;
            if (imp.alias) |alias| {
                self.mark_import_used_by_alias(alias);
            } else {
                mark_node_used(node);
            }
            return;
        }
    }

    fn mark_function_node_used_and_sync_import(self: *Self, fn_node: *ast.Node) void {
        mark_node_used(fn_node);

        const fn_pos = fn_node.pos orelse return;
        if (mem.eql(u8, fn_pos.filename, self.input_file_path)) return;
        self.mark_import_used_by_origin_file(fn_pos.filename);
    }

    fn lookup_receiver_dtype(self: *Self, recv: ast.Node) ?*dtype.DataType {
        if (recv.type == .Identifier and recv.data != null) {
            const name = recv.data.?.sval.items;
            if (self.get_scope_entity(name)) |ent| {
                if (ent.node) |ent_node| {
                    if (ent_node.type == .Variable and ent_node.node_variant != null) {
                        return ent_node.node_variant.?.variable.type;
                    }
                }
            }
        }
        return null;
    }

    fn concrete_type_name(self: *Self, recv: ast.Node, recv_t: CheckedType) TranspileError!?[]const u8 {
        if (!is_user_named_type(recv_t)) return null;
        if (recv_t.mangled_name) |mn| return mn;
        if (recv_t.dtype_ref) |dt| {
            if (dt.generic_args != null) {
                return try self.type_name_mangled(dt);
            }
        } else if (self.lookup_receiver_dtype(recv)) |dt| {
            if (dt.generic_args != null) {
                return try self.type_name_mangled(dt);
            }
        }
        return recv_t.name.?;
    }

    fn expected_enum_name(self: *Self, t: CheckedType) ?[]const u8 {
        if (t.base != .Unknown) return null;
        if (t.pointer_depth != 0 or t.is_array) return null;
        const name = t.name orelse return null;
        const reg = self.root_registry() orelse return null;
        if (!reg.enums_by_name.contains(name)) return null;
        return name;
    }

    fn dot_shorthand_variant_name(node: *ast.Node) ?[]const u8 {
        if (node.type != .Expression or node.node_variant == null) return null;
        const exp = node.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, ".")) return null;
        const left = exp.left orelse return null;
        const right = exp.right orelse return null;
        if (left.*.type != .Blank) return null;
        if (right.*.type != .Identifier or right.*.data == null) return null;
        return right.*.data.?.sval.items;
    }

    const AliasEnumVariantParts = struct {
        alias_name: []const u8,
        enum_name: []const u8,
        variant_name: []const u8,
    };

    fn extract_alias_enum_variant_parts(left: *ast.Node, right: *ast.Node) ?AliasEnumVariantParts {
        // Right-associative parse shape:
        //   alias . (Enum . Variant)
        if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Expression and right.*.node_variant != null and mem.eql(u8, right.*.node_variant.?.exp.op, ".")) {
            const inner = right.*.node_variant.?.exp;
            const enum_node = inner.left orelse return null;
            const variant_node = inner.right orelse return null;
            if (enum_node.*.type == .Identifier and enum_node.*.data != null and variant_node.*.type == .Identifier and variant_node.*.data != null) {
                return .{
                    .alias_name = left.*.data.?.sval.items,
                    .enum_name = enum_node.*.data.?.sval.items,
                    .variant_name = variant_node.*.data.?.sval.items,
                };
            }
        }

        // Left-associative parse shape:
        //   (alias . Enum) . Variant
        if (left.*.type == .Expression and left.*.node_variant != null and mem.eql(u8, left.*.node_variant.?.exp.op, ".") and right.*.type == .Identifier and right.*.data != null) {
            const inner = left.*.node_variant.?.exp;
            const alias_node = inner.left orelse return null;
            const enum_node = inner.right orelse return null;
            if (alias_node.*.type == .Identifier and alias_node.*.data != null and enum_node.*.type == .Identifier and enum_node.*.data != null) {
                return .{
                    .alias_name = alias_node.*.data.?.sval.items,
                    .enum_name = enum_node.*.data.?.sval.items,
                    .variant_name = right.*.data.?.sval.items,
                };
            }
        }

        return null;
    }

    /// Look up the AST EnumVariant for `enum_name.variant_name`, or null if either
    /// the enum or the variant is unknown.
    fn lookup_enum_variant(self: *Self, enum_name: []const u8, variant_name: []const u8) ?ast.EnumVariant {
        const reg = self.root_registry() orelse return null;
        // Accept a mangled instance name (`Option__num`) by falling back to its base
        // enum (`Option`), so variant lookup works on monomorphized generic enums.
        const enode = reg.enums_by_name.get(enum_name) orelse blk: {
            const base = if (mem.indexOf(u8, enum_name, "__")) |idx| enum_name[0..idx] else break :blk null;
            break :blk reg.enums_by_name.get(base);
        } orelse return null;
        if (enode.node_variant == null) return null;
        for (enode.node_variant.?.enum_decl.variants.items()) |v| {
            if (mem.eql(u8, v.name.items, variant_name)) return v;
        }
        return null;
    }

    /// True when `dt` is exactly one of the (possibly mangled) enum's declared type
    /// parameters (e.g. payload type `T` of `enum Option<T>`). Such a payload accepts
    /// any argument at a variant constructor — the argument fixes the concrete type;
    /// the surrounding `Option<num>` annotation drives monomorphization.
    fn enum_payload_is_type_param(self: *Self, enum_name: []const u8, dt: *const dtype.DataType) bool {
        if (dt.type != null and dt.type != .Unknown) return false;
        if (dt.type_str.items.len == 0) return false;
        const reg = self.root_registry() orelse return false;
        const enode = reg.enums_by_name.get(enum_name) orelse blk: {
            const base = if (mem.indexOf(u8, enum_name, "__")) |idx| enum_name[0..idx] else break :blk null;
            break :blk reg.enums_by_name.get(base);
        } orelse return false;
        if (enode.node_variant == null) return false;
        const params = enode.node_variant.?.enum_decl.type_params orelse return false;
        for (params.items()) |p| {
            if (mem.eql(u8, p.items, dt.type_str.items)) return true;
        }
        return false;
    }

    /// Broader than `enum_payload_is_type_param`: true when the payload type
    /// merely REFERENCES a type param somewhere in its structure, not just
    /// when it bare-IS one. Needed for a self-referential recursive generic
    /// enum (`enum List<T> { Cons(T, List<T>*), Nil }`) — the SECOND payload
    /// field, `List<T>*`, isn't `T` itself but nests it as a generic arg of
    /// the enum's OWN (unsubstituted) type. Outside any active generic
    /// function/method context (e.g. constructing `List.Cons(v, tail)` inside
    /// a plain, non-generic function whose param happens to be a concrete
    /// `List<dec>*`), there's no substitution available to resolve that bare
    /// `T` down to `dec` before comparing — so the strict check spuriously
    /// rejected a well-typed `List<dec>*` argument as a "payload field type
    /// mismatch" against the abstract, unresolved `List<T>*`.
    fn enum_payload_references_type_param(self: *Self, enum_name: []const u8, dt: *const dtype.DataType) bool {
        const reg = self.root_registry() orelse return false;
        const enode = reg.enums_by_name.get(enum_name) orelse blk: {
            const base = if (mem.indexOf(u8, enum_name, "__")) |idx| enum_name[0..idx] else break :blk null;
            break :blk reg.enums_by_name.get(base);
        } orelse return false;
        if (enode.node_variant == null) return false;
        const params = enode.node_variant.?.enum_decl.type_params orelse return false;
        return self.dtype_contains_type_param(dt, &params);
    }

    /// Resolve a fit-arm payload's concrete dtype for SCOPE REGISTRATION (codegen),
    /// given the (possibly mangled) subject enum name. A concrete payload (`Circle(num)`,
    /// `Array(Vec<JsonValue>)`) returns itself. A type-parameter payload (`Ok(T)` of a
    /// mangled `Result__JsonValue`) is mapped to the instance's concrete arg (`JsonValue`)
    /// by reconstructing the subject's dtype from its mangled name. Returns null when the
    /// payload can't be resolved to something registrable (caller leaves it `__auto_type`).
    /// Build an arena-owned dtype naming a non-generic type (`JsonValue`), for binding
    /// resolution when no structured dtype is available.
    fn simple_dtype_named(self: *Self, name: []const u8) ?*dtype.DataType {
        const out = self.arena.allocator().create(dtype.DataType) catch return null;
        out.* = .{
            .array = null,
            .pointer_depth = 0,
            .type = .Unknown,
            .type_str = ArrayList(u8).init(self.arena.allocator()),
            .flags = .{},
            .generic_args = null,
        };
        out.type_str.appendSlice(name) catch return null;
        return out;
    }

    fn resolve_fit_payload_dtype(self: *Self, enum_name: []const u8, payload_dt: *dtype.DataType) ?*dtype.DataType {
        if (!self.enum_payload_is_type_param(enum_name, payload_dt)) {
            return payload_dt;
        }
        // Type-param payload: find its index in the base enum's params, then map to the
        // mangled subject instance's concrete arg.
        const reg = self.root_registry() orelse return null;
        const enode = reg.enums_by_name.get(enum_name) orelse blk: {
            const base = if (mem.indexOf(u8, enum_name, "__")) |idx| enum_name[0..idx] else break :blk null;
            break :blk reg.enums_by_name.get(base);
        } orelse return null;
        if (enode.node_variant == null) return null;
        const params = enode.node_variant.?.enum_decl.type_params orelse return null;
        var pidx: ?usize = null;
        for (params.items(), 0..) |p, i| {
            if (mem.eql(u8, p.items, payload_dt.type_str.items)) {
                pidx = i;
                break;
            }
        }
        const idx = pidx orelse return null;
        // Reconstruct the subject instance's concrete args. Prefer the structured
        // `dtype_from_mangled_type`; if it can't recover generic_args (it doesn't for
        // some recursive instances), fall back to splitting the mangled suffix. For a
        // SINGLE-parameter enum (`Option<T>`, `Result<T>`) the whole suffix after the
        // first `__` is that one arg's mangled name (`Result__JsonValue` -> `JsonValue`,
        // `Option__Vec__JsonValue` -> `Vec__JsonValue`).
        if (self.dtype_from_mangled_type(enum_name) catch null) |sdt| {
            if (sdt.generic_args) |gargs| {
                if (idx < gargs.count) return gargs.items()[idx];
            }
        }
        if (params.count == 1 and idx == 0) {
            const sep = mem.indexOf(u8, enum_name, "__") orelse return null;
            const arg_name = enum_name[sep + 2 ..];
            if (arg_name.len == 0) return null;
            return self.dtype_from_mangled_type(arg_name) catch null orelse self.simple_dtype_named(arg_name);
        }
        return null;
    }

    /// Compute the CheckedType of a fit-arm payload binding. For a concrete payload
    /// (`Circle(num)`) it's just that type. For a generic enum's type-parameter
    /// payload (`Some(T)` of `Option<num>`), substitute the parameter with the
    /// concrete argument from the SUBJECT's generic args (`subject_t` is the
    /// `Option<num>` value being matched) so the binding is typed `num`, not `T`.
    fn fit_binding_type(self: *Self, enum_name: []const u8, subject_t: CheckedType, payload_dt: *dtype.DataType) TranspileError!CheckedType {
        // Concrete (non-type-param) payload: use it directly. Must go through
        // `type_from_dtype_with_mangled` (not the bare `type_from_dtype`) so a
        // generic-compound payload (e.g. `Call(str, Vec<Expr*>)`'s `Vec<Expr*>`)
        // gets its `mangled_name` populated — without it, this binding's type
        // and the SAME type resolved through any other path (e.g. a function
        // parameter's declared type) disagreed on `mangled_name` and a call
        // passing the bound variable spuriously failed as a type mismatch.
        const is_bare_param = self.enum_payload_is_type_param(enum_name, payload_dt);
        if (!is_bare_param and !self.enum_payload_references_type_param(enum_name, payload_dt)) {
            return self.type_from_dtype_with_mangled(payload_dt);
        }
        // Resolve the enum's own declared type params so we can substitute
        // through either shape below: a bare `T` payload, or a NESTED
        // reference to `T` inside a self-referential recursive generic enum's
        // own type (`List<T>*` in `enum List<T> { Cons(T, List<T>*), Nil }`).
        // Without substituting the nested case, a fit-bound `tail` (payload
        // field 1) kept the abstract, unresolved `List<T>*` as its type
        // instead of the subject's actual concrete instantiation
        // (`List<dec>*`), and passing it to anything declared to take
        // `List<dec>*` spuriously failed as a type mismatch.
        const reg = self.root_registry() orelse return CheckedType{ .base = .Unknown };
        const enode = reg.enums_by_name.get(enum_name) orelse blk: {
            const base = if (mem.indexOf(u8, enum_name, "__")) |idx| enum_name[0..idx] else break :blk null;
            break :blk reg.enums_by_name.get(base);
        } orelse return CheckedType{ .base = .Unknown };
        if (enode.node_variant == null) return CheckedType{ .base = .Unknown };
        const params = enode.node_variant.?.enum_decl.type_params orelse return CheckedType{ .base = .Unknown };
        const sdt = subject_t.dtype_ref orelse return CheckedType{ .base = .Unknown };
        const gargs = sdt.generic_args orelse return CheckedType{ .base = .Unknown };
        if (gargs.count != params.count) return CheckedType{ .base = .Unknown };

        if (is_bare_param) {
            var pidx: ?usize = null;
            for (params.items(), 0..) |p, i| {
                if (mem.eql(u8, p.items, payload_dt.type_str.items)) {
                    pidx = i;
                    break;
                }
            }
            const idx = pidx orelse return CheckedType{ .base = .Unknown };
            if (idx >= gargs.count) return CheckedType{ .base = .Unknown };
            return self.type_from_dtype_with_mangled(gargs.items()[idx]);
        }

        // Nested reference: substitute every occurrence of the enum's own
        // type params through `payload_dt`'s structure using the subject's
        // concrete args (the same substitution machinery generic quirk
        // instantiation already relies on), then mangle the result.
        const substituted = try self.clone_dtype_with_subst_for_inst(payload_dt, &params, gargs.items());
        return self.type_from_dtype_with_mangled(substituted);
    }

    /// True when `name` is a declared enum that is a tagged union (sum type).
    fn enum_name_is_tagged_union(self: *Self, name: []const u8) bool {
        const reg = self.root_registry() orelse return false;
        const enode = reg.enums_by_name.get(name) orelse return false;
        if (enode.node_variant == null) return false;
        return enum_is_tagged_union(enode.node_variant.?.enum_decl);
    }

    /// If `callee` is `EnumName.Variant` for a declared enum variant, return
    /// {enum_name, variant_name}. Handles the shorthand `.Variant` form too (the
    /// LHS is a blank/empty identifier). Returns null when it isn't an enum-variant
    /// path. Does NOT require the variant to carry a payload.
    fn enum_variant_path(self: *Self, callee: *const ast.Node) ?struct { enum_name: []const u8, variant: []const u8 } {
        if (callee.type != .Expression or callee.node_variant == null) return null;
        const cexp = callee.node_variant.?.exp;
        if (!mem.eql(u8, cexp.op, ".")) return null;
        const left = cexp.left orelse return null;
        const right = cexp.right orelse return null;
        if (left.*.type != .Identifier or left.*.data == null) return null;
        if (right.*.type != .Identifier or right.*.data == null) return null;
        const ename = left.*.data.?.sval.items;
        const vname = right.*.data.?.sval.items;
        const reg = self.root_registry() orelse return null;
        if (!reg.enums_by_name.contains(ename)) return null;
        return .{ .enum_name = ename, .variant = vname };
    }

    /// Type-check a data-carrying enum construction `EnumName.Variant(args...)`.
    /// Returns the enum's CheckedType on success, null when `callee` is not an
    /// enum-variant path (so the caller falls through to normal call inference).
    /// Errors when the variant has no payload, or the arg count/types mismatch.
    fn infer_enum_variant_construction(self: *Self, node: ast.Node, callee: *const ast.Node, args: []const *ast.Node, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!?CheckedType {
        const path = self.enum_variant_path(callee) orelse return null;
        const variant = self.lookup_enum_variant(path.enum_name, path.variant) orelse {
            self.report_type_error(node, "enum '{s}' has no variant '{s}'", .{ path.enum_name, path.variant });
            return TranspileError.UnknownField;
        };
        const payload = variant.payload orelse {
            self.report_type_error(node, "enum variant '{s}.{s}' carries no data and cannot be called like a constructor", .{ path.enum_name, path.variant });
            return TranspileError.NotCallable;
        };
        const ptypes = payload.items();
        if (args.len != ptypes.len) {
            self.report_type_error(node, "enum variant '{s}.{s}' expects {d} payload value(s), got {d}", .{ path.enum_name, path.variant, ptypes.len, args.len });
            return TranspileError.WrongArgCount;
        }
        for (args, 0..) |arg, i| {
            // A payload that is a generic type PARAMETER (`Some(T)` of `Option<T>`)
            // accepts any argument — the argument fixes the concrete T, and the
            // surrounding `Option<num>` annotation drives monomorphization. Still
            // infer the arg (to mark callees used / register instantiations), but
            // skip the strict match against the bare `T`.
            //
            // A payload that merely REFERENCES a type param somewhere in its
            // structure without bare-BEING one (`List<T>*` in a self-
            // referential `enum List<T> { Cons(T, List<T>*), Nil }`) needs the
            // same leniency: outside an active generic function/method's own
            // substitution context, `T` here can't be resolved to the
            // concrete instantiation actually being constructed (e.g.
            // `List<dec>`), so the strict check would compare against the
            // abstract, unresolved `List<T>*` and spuriously reject a
            // perfectly well-typed `List<dec>*` argument.
            if (self.enum_payload_is_type_param(path.enum_name, ptypes[i]) or
                self.enum_payload_references_type_param(path.enum_name, ptypes[i]))
            {
                // If this construction site's concrete instantiation was
                // already bound (e.g. via `bind_enum_ctor_expected` from an
                // enclosing `ret`/`let`: `ret .Some(.Cval('a'));` in a
                // function returning `Option<Data>`), resolve a nested
                // shorthand payload argument against the bound concrete
                // type. Without this, a shorthand argument sitting in a
                // bare-type-param payload slot (T isn't resolvable here on
                // its own -- that's exactly why this branch exists) was
                // never resolved and failed later with "method calls
                // require a named receiver" (a blank dot-path misread as a
                // method-call receiver).
                if (self.lookup_enum_ctor_override(node)) |mangled| {
                    if (self.resolve_fit_payload_dtype(mangled, ptypes[i])) |concrete| {
                        const concrete_t = try self.type_from_dtype_with_mangled(concrete);
                        if (self.expected_enum_name(concrete_t)) |enum_name| {
                            if (dot_shorthand_variant_name(arg)) |_| {
                                _ = try self.resolve_dot_shorthand_enum_variant(arg, enum_name);
                            } else {
                                try self.resolve_shorthand_enum_call(arg, enum_name);
                            }
                            try self.bind_enum_ctor_expected(arg, concrete_t);
                        }
                    }
                }
                _ = try self.infer_expr_type(arg.*, env, fns);
                continue;
            }
            // Use the mangled form so a generic-instance payload (`Box<num>`) carries
            // its `Box__num` identity and matches the argument's inferred type.
            const expected = try self.type_from_dtype_with_mangled(ptypes[i]);
            if (ptypes[i].generic_args != null) {
                self.register_generic_instantiation(ptypes[i]) catch {};
            }
            // Enum shorthand payload: `Option.Some(.Cval('a'))` where the
            // payload field's own type is itself an enum. Without this, a
            // nested shorthand argument (bare `.Variant` or a data-carrying
            // `.Variant(...)` call) was never resolved and failed later with
            // "method calls require a named receiver" (a blank dot-path
            // misread as a method-call receiver).
            if (self.expected_enum_name(expected)) |enum_name| {
                if (dot_shorthand_variant_name(arg)) |_| {
                    _ = try self.resolve_dot_shorthand_enum_variant(arg, enum_name);
                } else {
                    try self.resolve_shorthand_enum_call(arg, enum_name);
                    try self.resolve_shorthand_args_via_generic_wrapper(arg, expected, fns);
                }
                try self.bind_enum_ctor_expected(arg, expected);
            }
            const actual = try self.infer_expr_type(arg.*, env, fns);
            if (is_known_type(expected) and is_known_type(actual) and !(try self.can_implicit_coerce(expected, actual))) {
                self.report_type_error(node, "enum variant '{s}.{s}' payload field {d} type mismatch", .{ path.enum_name, path.variant, i });
                return TranspileError.TypeMismatch;
            }
        }
        // If this construction site was already bound to a concrete generic
        // instantiation (e.g. `Option__Token`, via `bind_enum_ctor_expected`
        // from an enclosing `ret`/`let`/generic-wrapper-call resolution),
        // carry that concrete dtype forward instead of the bare
        // `{name: "Option"}`. Without this, a later INDEPENDENT re-inference
        // of this same `.Some(x)` construction (e.g. a generic wrapper call's
        // own T-inference from its argument) saw an incomplete,
        // dtype_ref-less type and bound T to it, producing a malformed
        // "Result__Option" (missing its own argument) instance/call-site
        // override that could never be satisfied -- misreported as a cyclic
        // dependency at typecheck time, or an undeclared-function error at
        // codegen time.
        if (self.lookup_enum_ctor_override(node)) |mangled| {
            if (try self.dtype_from_mangled_type(mangled)) |synth_dt| {
                return .{ .base = .Unknown, .name = path.enum_name, .mangled_name = mangled, .dtype_ref = synth_dt };
            }
        }
        return .{ .base = .Unknown, .name = path.enum_name };
    }

    fn resolve_enum_variant_constant_type(self: *Self, node: ast.Node, enum_name: []const u8, variant_name: []const u8) TranspileError!?CheckedType {
        const root = self.get_root();
        if (root.type_registry == null) return null;
        const reg = &root.type_registry.?;
        const enode = reg.enums_by_name.get(enum_name) orelse return null;

        if (!self.can_access(&node, enode)) {
            self.report_type_error(node, "enum '{s}' is private", .{enum_name});
            return TranspileError.SymbolNotDefined;
        }

        // Naming a variant uses the enum, and so uses whatever import brought
        // it in -- the same marking every other type-name path does. Without
        // it, a file whose ONLY mention of an imported enum is a variant
        // constant (`f(Sink.Stdout)` where `f` is declared elsewhere, so the
        // type name never appears here in a declaration) was reported as not
        // using that import at all.
        self.mark_node_used_and_sync_top_level_copy(enode);
        if (!same_module(&node, enode)) {
            if (enode.pos) |p| self.mark_import_used_by_origin_file(p.filename);
        }

        if (enode.node_variant != null) {
            var ok = false;
            for (enode.node_variant.?.enum_decl.variants.items()) |v| {
                if (mem.eql(u8, v.name.items, variant_name)) {
                    ok = true;
                    break;
                }
            }
            if (!ok) {
                self.report_type_error(node, "enum '{s}' has no variant '{s}'", .{ enum_name, variant_name });
                return TranspileError.UnknownField;
            }
        }

        return .{ .base = .Unknown, .name = enum_name };
    }

    fn resolve_dot_shorthand_enum_variant(self: *Self, node: *ast.Node, enum_name: []const u8) TranspileError!CheckedType {
        const variant_name = dot_shorthand_variant_name(node) orelse return .{ .base = .Unknown };
        const reg = self.root_registry() orelse return .{ .base = .Unknown };
        const enode = reg.enums_by_name.get(enum_name) orelse {
            self.report_type_error(node.*, "unknown enum '{s}'", .{enum_name});
            return TranspileError.TypeMismatch;
        };
        if (!self.can_access(node, enode)) {
            self.report_type_error(node.*, "enum '{s}' is private", .{enum_name});
            return TranspileError.SymbolNotDefined;
        }
        if (enode.node_variant == null) return .{ .base = .Unknown };

        var ok = false;
        for (enode.node_variant.?.enum_decl.variants.items()) |v| {
            if (mem.eql(u8, v.name.items, variant_name)) {
                ok = true;
                break;
            }
        }
        if (!ok) {
            self.report_type_error(node.*, "enum '{s}' has no variant '{s}'", .{ enum_name, variant_name });
            return TranspileError.UnknownField;
        }

        // Rewrite `.Variant` into `Enum.Variant` by mutating the blank LHS node.
        const left_ptr = node.node_variant.?.exp.left.?;
        // AST nodes are arena-owned; allocate via `self.allocator` to keep ownership consistent.
        var sval = ArrayList(u8).init(self.allocator);
        sval.appendSlice(enum_name) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        left_ptr.* = ast.Node{
            .type = .Identifier,
            .pos = left_ptr.*.pos orelse node.pos,
            .data = .{ .sval = sval },
            .binded = null,
            .node_variant = null,
        };

        return .{ .base = .Unknown, .name = enum_name };
    }

    /// If `node` is a shorthand data-variant CONSTRUCTION call `.Variant(args...)`
    /// (a `()` call whose callee is `<blank>.Variant`), rewrite the callee's blank
    /// LHS to `enum_name` so it becomes `Enum.Variant(args...)`. This lets shorthand
    /// construction work wherever the expected enum type is known (typed var-init,
    /// `ret`, compound-init field, fit subject). No-op if `node` isn't that shape.
    fn resolve_shorthand_enum_call(self: *Self, node: *ast.Node, enum_name: []const u8) TranspileError!void {
        if (node.type != .Expression or node.node_variant == null) return;
        const exp = node.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, "()")) return;
        const callee = exp.left orelse return;
        // Callee must be a shorthand `.Variant` (blank LHS dot expression).
        if (dot_shorthand_variant_name(callee) == null) return;
        // Reuse the non-call rewrite on the callee path (mutates its blank LHS to
        // the enum name and validates the variant exists).
        _ = try self.resolve_dot_shorthand_enum_variant(callee, enum_name);
    }

    /// When `node` is a call to a generic function whose declared return type
    /// is the SAME named container as `expected` (e.g. `ok<T>(T value)
    /// Result<T>` called where `expected` is `Result<Option<Token>>`),
    /// resolves any of the call's ARGUMENTS that are themselves enum-variant
    /// shorthand (`.None`, `.Some(x)`) against `expected`'s own generic
    /// argument. The callee's abstract template has no concrete `T` to
    /// resolve the shorthand against on its own -- generic instantiation only
    /// happens after typecheck -- so without this, `ret ok(.None);` left
    /// `.None` as an unresolved blank dot-path and failed at codegen with
    /// "field access requires a compound-typed value".
    fn resolve_shorthand_args_via_generic_wrapper(self: *Self, node: *ast.Node, expected: CheckedType, fns: *const std.StringHashMap(FnSig)) TranspileError!void {
        if (node.type != .Expression or node.node_variant == null) return;
        const exp = node.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, "()")) return;
        const callee = exp.left orelse return;
        if (callee.type != .Identifier or callee.data == null) return;
        const expected_dt = expected.dtype_ref orelse return;
        const gargs = expected_dt.generic_args orelse return;
        if (gargs.count == 0) return;
        const expected_name = self.expected_enum_name(expected) orelse return;
        const sig = fns.get(callee.data.?.sval.items) orelse return;
        const callee_rt_name = sig.rtype.name orelse return;
        if (!mem.eql(u8, callee_rt_name, expected_name)) return;
        const type_params = sig.type_params orelse return;
        if (type_params.count == 0) return;
        // Only the FIRST type param is substituted -- the wrapper functions
        // this targets (`ok<T>`, `err_kind<T>`, `some<T>`) all have exactly
        // one, and matching by NAME below is what keeps this from touching
        // an unrelated concrete-typed argument (see below).
        const tparam_name = type_params.items()[0].items;
        const inner_dt = gargs.items()[0];
        const inner_t = try self.type_from_dtype_with_mangled(inner_dt);
        const inner_enum = self.expected_enum_name(inner_t) orelse return;

        var args_list = ArrayList(*ast.Node).init(self.allocator);
        defer args_list.deinit();
        if (exp.right) |right| {
            try self.flatten_call_args_ptr(right, &args_list);
        }
        for (args_list.items, 0..) |arg, i| {
            if (i >= sig.args.len) break;
            // Only resolve arguments whose DECLARED param type is genuinely
            // the callee's own bare type param -- e.g. `err_kind<T>(ErrorKind
            // kind, str message, T default)`'s first argument is a REAL,
            // unrelated `ErrorKind` and must not be resolved against T's
            // binding too.
            const param_name = sig.args[i].name orelse continue;
            if (!mem.eql(u8, param_name, tparam_name)) continue;
            if (dot_shorthand_variant_name(arg)) |_| {
                _ = try self.resolve_dot_shorthand_enum_variant(arg, inner_enum);
            } else {
                try self.resolve_shorthand_enum_call(arg, inner_enum);
            }
            // Record the concrete monomorphized instance (`Option__Token`) for
            // BOTH shapes -- a bare value (`.None`) and a construction call
            // (`.Some(x)`). Without this for the bare-value case, a later
            // independent re-inference of this same arg (e.g. the callee's
            // OWN generic-function-call machinery inferring `ok<T>`'s T from
            // its argument) had no concrete dtype to consult, fell back to a
            // dtype_ref-less bare "Option" CheckedType, and spuriously bound
            // T to that incomplete type -- producing a malformed "Result__Option"
            // (missing its own argument) instantiation that could never be
            // satisfied, intermittently misreported as a cyclic dependency.
            try self.bind_enum_ctor_expected(arg, inner_t);
        }
    }

    fn infer_let_enum_dot_shorthand(self: *Self, node: *ast.Node) TranspileError!?CheckedType {
        const variant_name = dot_shorthand_variant_name(node) orelse return null;
        const reg = self.root_registry() orelse return null;

        var found_enum: ?[]const u8 = null;

        var it = reg.enums_by_name.iterator();
        while (it.next()) |entry| {
            const enum_name = entry.key_ptr.*;
            const enode = entry.value_ptr.*;
            if (!self.can_access(node, enode)) continue;
            if (enode.node_variant == null) continue;

            var has_variant = false;
            for (enode.node_variant.?.enum_decl.variants.items()) |v| {
                if (mem.eql(u8, v.name.items, variant_name)) {
                    has_variant = true;
                    break;
                }
            }
            if (!has_variant) continue;

            if (found_enum != null) {
                self.report_type_error(node.*, "cannot infer enum for '.{s}'; variant exists in both '{s}' and '{s}'", .{ variant_name, found_enum.?, enum_name });
                return TranspileError.TypeMismatch;
            }

            found_enum = enum_name;
        }

        if (found_enum == null) {
            self.report_type_error(node.*, "cannot infer enum for '.{s}'; no matching enum in scope", .{variant_name});
            return TranspileError.TypeMismatch;
        }

        return try self.resolve_dot_shorthand_enum_variant(node, found_enum.?);
    }

    fn lookup_compound_field(self: *Self, compound_name: []const u8, field_name: []const u8) ?*const dtype.DataType {
        const root = self.get_root();
        if (root.type_registry == null) return null;
        const reg = &root.type_registry.?;
        const cnode = reg.compounds_by_name.get(compound_name) orelse return null;
        if (cnode.node_variant == null) return null;
        const fields = cnode.node_variant.?.compound.fields.items();
        for (fields) |f| {
            if (mem.eql(u8, f.name.items, field_name)) return f.dtype;
        }
        return null;
    }

    /// Enforce leading-underscore field privacy: a field whose name begins with
    /// `_` is module-private (accessible only from the file where its compound is
    /// declared). `ref_node` is the access site; `compound_base_name` is the
    /// (un-mangled) compound name. No-op when the field is not underscore-prefixed,
    /// when the compound isn't found, or when the access is in the same module.
    fn check_private_field_access(self: *Self, ref_node: ast.Node, compound_base_name: []const u8, field_name: []const u8) TranspileError!void {
        if (field_name.len == 0 or field_name[0] != '_') return;
        const reg = self.root_registry() orelse return;
        const cnode = reg.compounds_by_name.get(compound_base_name) orelse return;
        if (!same_module(&ref_node, cnode)) {
            self.report_type_error(ref_node, "field '{s}' is private to its module (leading '_'); it cannot be accessed from another module", .{field_name});
            return TranspileError.InvalidFieldAccess;
        }
    }

    fn canonical_compound_name(self: *Self, name: []const u8) []const u8 {
        const root = self.get_root();
        if (root.type_registry == null) return name;
        const reg = &root.type_registry.?;
        const cnode = reg.compounds_by_name.get(name) orelse return name;
        if (cnode.node_variant == null) return name;
        return cnode.node_variant.?.compound.name.items;
    }

    fn lookup_quirk_method(self: *Self, ref_node: ast.Node, quirk_name: []const u8, method_name: []const u8) ?ast.QuirkMethodSig {
        const root = self.get_root();
        if (root.type_registry == null) return null;
        const reg = &root.type_registry.?;

        const sig = reg.quirk_sig_by_name.get(quirk_name) orelse return null;
        const qnode = reg.quirks_by_sig.get(sig) orelse return null;
        if (qnode.node_variant == null) return null;
        if (!self.can_access(&ref_node, qnode)) return null;
        const methods = qnode.node_variant.?.quirk.methods.items();
        for (methods) |m| {
            if (mem.eql(u8, m.name.items, method_name)) return m;
        }
        return null;
    }

    fn infer_compound_field_access_type(self: *Self, node: ast.Node, base: CheckedType, field_name: []const u8, env: *TypeEnv) TranspileError!CheckedType {
        // Field access on a value whose type is a still-symbolic generic type
        // parameter (e.g. `x.v` inside `fun f<T>(T x) num { ret x.v; }`) cannot be
        // resolved at the generic definition — the concrete type (and thus its
        // fields) is only known per monomorphization. Defer: return Unknown rather
        // than reporting `unknown type 'T'`. The real field-type check happens when
        // the specialized body is emitted for each concrete T.
        if (base.name) |bn| {
            if (env.has_type_param(bn)) return CheckedType{ .base = .Unknown };
        }

        if (!is_user_named_type(base)) {
            self.report_type_error(node, "field access requires a compound-typed value", .{});
            return TranspileError.InvalidFieldAccess;
        }

        const tname = base.mangled_name orelse base.name.?;
        const base_name = if (mem.indexOf(u8, tname, "__")) |idx| tname[0..idx] else tname;
        try self.ensure_named_type_visible(node, tname);

        // Leading-underscore fields are module-private: `compound User { num _pw; }`
        // exposes `_pw` only to code in the same module as the type's declaration.
        // A method body (`self._pw`) lives in the same file as the type, so it is
        // always allowed; a cross-module `u._pw` is rejected.
        try self.check_private_field_access(node, base_name, field_name);

        if (base.pointer_depth > 1) {
            self.report_type_error(node, "field access supports at most one pointer indirection", .{});
            return TranspileError.InvalidFieldAccess;
        }

        // For generic-specialized receivers (e.g. Box__AsyncCounter), resolve
        // fields from the generic declaration with type-parameter substitution.
        if (base.mangled_name) |mangled| {
            if (try self.dtype_from_mangled_type(mangled)) |spec_dt| {
                if (spec_dt.generic_args) |gargs_vec| {
                    if (self.root_registry()) |reg| {
                        const spec_lookup_name = if (spec_dt.type_str.items.len != 0) spec_dt.type_str.items else base_name;
                        const spec_lookup_base = if (mem.indexOf(u8, spec_lookup_name, "__")) |idx| spec_lookup_name[0..idx] else spec_lookup_name;
                        if (reg.compounds_by_name.get(spec_lookup_base)) |cnode| {
                            if (cnode.node_variant != null) {
                                const cdef = cnode.node_variant.?.compound;
                                if (cdef.type_params) |params| {
                                    const gargs = gargs_vec.items();
                                    if (params.count == gargs.len) {
                                        for (cdef.fields.items()) |f| {
                                            if (mem.eql(u8, f.name.items, field_name)) {
                                                return try self.type_from_dtype_with_subst(f.dtype, params, gargs);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Also handle generic receivers represented as `dtype_ref` without a
        // mangled name (for example function returns like `Box<AsyncCounter>`).
        if (base.dtype_ref) |base_dt| {
            if (base_dt.generic_args) |gargs_vec| {
                if (self.root_registry()) |reg| {
                    const lookup_name = if (base_dt.type_str.items.len != 0) base_dt.type_str.items else base_name;
                    const lookup_base = if (mem.indexOf(u8, lookup_name, "__")) |idx| lookup_name[0..idx] else lookup_name;
                    if (reg.compounds_by_name.get(lookup_base)) |cnode| {
                        if (cnode.node_variant != null) {
                            const cdef = cnode.node_variant.?.compound;
                            if (cdef.type_params) |params| {
                                const gargs = gargs_vec.items();
                                if (params.count == gargs.len) {
                                    for (cdef.fields.items()) |f| {
                                        if (mem.eql(u8, f.name.items, field_name)) {
                                            return try self.type_from_dtype_with_subst(f.dtype, params, gargs);
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        const fdt = self.lookup_compound_field(tname, field_name) orelse
            (if (!mem.eql(u8, tname, base_name)) self.lookup_compound_field(base_name, field_name) else null) orelse {
            self.report_type_error(node, "type '{s}' has no field '{s}'", .{ tname, field_name });
            return TranspileError.UnknownField;
        };
        return try self.type_from_dtype_with_mangled(fdt);
    }

    fn lookup_plain_impl_method_fn_proc(self: *Self, proc: *Self, ref_node: ?*const ast.Node, type_name: []const u8, method_name: []const u8) ?[]const u8 {
        // First pass: plain impls only (the common, unambiguous case). A second pass
        // below considers GENERIC quirk impls, whose static method bodies are emitted
        // under `<Type>__<Quirk>__<method>` and so are callable directly on a concrete
        // receiver (e.g. `it.next()` where `it: MapIter<num,bin>` implements
        // `Iterator<num>`).
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            if (im.quirk_name != null) continue; // only plain impl
            if (!mem.eql(u8, im.type_name.items, type_name)) {
                if (self.impl_type_params(n) != null) {
                    const base = if (mem.indexOf(u8, type_name, "__")) |idx| type_name[0..idx] else type_name;
                    if (!mem.eql(u8, im.type_name.items, base)) continue;

                    for (im.methods.items()) |m| {
                        if (m.type != .Function or m.node_variant == null) continue;
                        if (!self.can_access_method(ref_node, n, m)) continue;
                        const fnv = m.node_variant.?.function;
                        if (fnv.name == null) continue;
                        const full = fnv.name.?.items;
                        if (!mem.startsWith(u8, full, im.type_name.items)) continue;
                        const base_name = base_method_name_from_generated(full) orelse continue;
                        if (!mem.eql(u8, base_name, method_name)) continue;

                        return std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ type_name, method_name }) catch null;
                    }
                }
                continue;
            }

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                if (!self.can_access_method(ref_node, n, m)) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const full = fnv.name.?.items;
                // Expected: `<Type>__<method>`
                if (!mem.startsWith(u8, full, type_name)) continue;
                const need_len = type_name.len + 2 + method_name.len;
                if (full.len != need_len) continue;
                if (!mem.eql(u8, full[type_name.len .. type_name.len + 2], "__")) continue;
                if (!mem.eql(u8, full[type_name.len + 2 ..], method_name)) continue;
                return full;
            }
        }

        // Second pass: generic quirk impls. The emitted symbol carries the quirk
        // segment (`<MangledType>__<Quirk>__<method>`).
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            const quirk_name = if (im.quirk_name) |qn| qn.items else continue;
            // Only generic quirks are dispatched statically by direct call; non-generic
            // quirks go through the vtable/coercion path, not a bare method call.
            const sig = (self.root_registry() orelse continue).quirk_sig_by_name.get(quirk_name) orelse continue;
            const qnode = (self.root_registry() orelse continue).quirks_by_sig.get(sig) orelse continue;
            if (qnode.node_variant == null or !qnode.node_variant.?.quirk.is_generic) continue;

            const im_base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            const recv_base = if (mem.indexOf(u8, type_name, "__")) |idx| type_name[0..idx] else type_name;
            if (!mem.eql(u8, im_base, recv_base)) continue;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                if (!self.can_access_method(ref_node, n, m)) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const base_name = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                if (!mem.eql(u8, base_name, method_name)) continue;
                // `<receiver-instance>__<Quirk>__<method>`, e.g.
                // `MapIter__num__bin__Iterator__next`. For a still-templated receiver
                // (`MapIter__T__bin`) this yields the template name, monomorphized later.
                return std.fmt.allocPrint(self.allocator, "{s}__{s}__{s}", .{ type_name, quirk_name, method_name }) catch null;
            }
        }

        for (proc.children.items) |child| {
            if (self.lookup_plain_impl_method_fn_proc(child, ref_node, type_name, method_name)) |n| return n;
        }
        return null;
    }

    fn lookup_plain_impl_method_fn(self: *Self, ref_node: ?*const ast.Node, type_name: []const u8, method_name: []const u8) ?[]const u8 {
        const root = self.get_root();
        return self.lookup_plain_impl_method_fn_proc(root, ref_node, type_name, method_name);
    }

    const PlainImplMethodHit = struct {
        impl_node: *ast.Node,
        method_node: *ast.Node,
    };

    fn find_plain_impl_method_node_proc(self: *Self, proc: *Self, type_base: []const u8, method_name: []const u8) ?PlainImplMethodHit {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            if (im.quirk_name != null) continue;
            const base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            if (!mem.eql(u8, base, type_base)) continue;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const full = fnv.name.?.items;
                const base_name = base_method_name_from_generated(full) orelse continue;
                if (!mem.eql(u8, base_name, method_name)) continue;
                return .{ .impl_node = n, .method_node = m };
            }
        }

        for (proc.children.items) |child| {
            if (self.find_plain_impl_method_node_proc(child, type_base, method_name)) |hit| return hit;
        }
        return null;
    }

    fn find_plain_impl_method_node(self: *Self, type_base: []const u8, method_name: []const u8) ?PlainImplMethodHit {
        const root = self.get_root();
        return self.find_plain_impl_method_node_proc(root, type_base, method_name);
    }

    /// Like `find_plain_impl_method_node`, but also matches methods declared in a
    /// quirk impl (`impl Type as Quirk { ... }`). Used for return-type resolution and
    /// method chaining where a quirk-impl method (e.g. `Iterator.next`) is called
    /// directly on a concrete receiver via static dispatch.
    fn find_any_impl_method_node_proc(self: *Self, proc: *Self, type_base: []const u8, method_name: []const u8) ?PlainImplMethodHit {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            const base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            if (!mem.eql(u8, base, type_base)) continue;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const full = fnv.name.?.items;
                const base_name = base_method_name_from_generated(full) orelse continue;
                if (!mem.eql(u8, base_name, method_name)) continue;
                return .{ .impl_node = n, .method_node = m };
            }
        }

        for (proc.children.items) |child| {
            if (self.find_any_impl_method_node_proc(child, type_base, method_name)) |hit| return hit;
        }
        return null;
    }
    fn find_any_impl_method_node(self: *Self, type_base: []const u8, method_name: []const u8) ?PlainImplMethodHit {
        const root = self.get_root();
        return self.find_any_impl_method_node_proc(root, type_base, method_name);
    }

    /// Like `find_any_impl_method_node`, but collects EVERY matching impl instead of
    /// just the first — a type can have several impl blocks defining the same method
    /// name under different constraints (e.g. stdlib's `impl Vec<T: num | dec>` and
    /// `impl Vec<str>` both define `contains`), and `check_impl_generic_constraint`
    /// needs to know about all of them, not just whichever one source order happens
    /// to register first.
    fn collect_all_impl_method_nodes_proc(self: *Self, proc: *Self, type_base: []const u8, method_name: []const u8, out: *ArrayList(PlainImplMethodHit)) TranspileError!void {
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            const base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            if (!mem.eql(u8, base, type_base)) continue;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const full = fnv.name.?.items;
                const base_name = base_method_name_from_generated(full) orelse continue;
                if (!mem.eql(u8, base_name, method_name)) continue;
                out.append(.{ .impl_node = n, .method_node = m }) catch return TranspileError.MemoryAllocationFailed;
            }
        }

        for (proc.children.items) |child| {
            try self.collect_all_impl_method_nodes_proc(child, type_base, method_name, out);
        }
    }
    fn collect_all_impl_method_nodes(self: *Self, type_base: []const u8, method_name: []const u8, out: *ArrayList(PlainImplMethodHit)) TranspileError!void {
        const root = self.get_root();
        try self.collect_all_impl_method_nodes_proc(root, type_base, method_name, out);
    }

    /// When a method call resolves to an impl block that constrains its type
    /// parameters (`impl Box<T: num | dec> { ... }`), verify the concrete receiver
    /// type args satisfy the constraint. Emits a Fun TypeError on violation
    /// instead of leaving the constrained-out specialization un-emitted (which the
    /// old behavior turned into an opaque C linker error `undefined Box__str__get`).
    /// Returns error.TypeMismatch on violation; no-op when unconstrained or the
    /// receiver args aren't statically concrete.
    ///
    /// A type can have SEVERAL impl blocks defining the same method name under
    /// different constraints — e.g. stdlib's `impl Vec<T: num | dec>` and
    /// `impl Vec<str>` both define `contains`. Checking only the FIRST matching
    /// impl (by source-registration order) was wrong: `Vec<str>.contains(...)`
    /// picked up the numeric-constrained impl first and rejected `str` outright,
    /// even though the str-specific impl right below it plainly accepts it and is
    /// what actually gets dispatched to. Fixed by checking EVERY matching impl and
    /// only erroring when ALL of them reject the args (or are otherwise
    /// constrained against them) — an accepting or unconstrained match anywhere
    /// in the set is enough.
    fn check_impl_generic_constraint(self: *Self, node: ast.Node, recv_dt: ?*const dtype.DataType, recv_base: []const u8, method_name: []const u8) TranspileError!void {
        const dt = recv_dt orelse return;
        const gargs_vec = dt.generic_args orelse return;
        const gargs = gargs_vec.items();
        if (gargs.len == 0) return;
        const base = if (mem.indexOf(u8, recv_base, "__")) |idx| recv_base[0..idx] else recv_base;
        var hits = ArrayList(PlainImplMethodHit).init(self.allocator);
        defer hits.deinit();
        try self.collect_all_impl_method_nodes(base, method_name, &hits);
        if (hits.items.len == 0) return;
        const hit = hits.items[0];
        // Only check when every generic arg is CONCRETE — not a still-symbolic type
        // parameter. A call made inside a generic body (e.g. stdlib `impl Vec<T>`
        // calling a constrained sibling with receiver `Vec__T`) has `T` as the arg;
        // that is not a real instantiation and must not be constraint-checked here
        // (it is checked at the concrete call site). Skip if any arg is unknown, is
        // one of the impl's own type-param names, or is a bare single-uppercase
        // placeholder / still contains `__`-free uppercase-only spelling.
        const impl_params = self.impl_type_params(hit.impl_node);
        for (gargs) |ga| {
            const gt = type_from_dtype(ga);
            if (!is_known_type(gt)) return;
            const spelling = ga.type_str.items;
            if (impl_params) |params| {
                for (params.items()) |p| {
                    if (mem.eql(u8, p.items, spelling)) return;
                }
            }
            // A conventional bare type-param placeholder (single uppercase letter,
            // or all-uppercase with no `__` mangling) — not a concrete type.
            if (spelling.len >= 1 and spelling[0] >= 'A' and spelling[0] <= 'Z' and
                mem.indexOf(u8, spelling, "__") == null)
            {
                var all_upper_ident = true;
                for (spelling) |ch| {
                    if (!((ch >= 'A' and ch <= 'Z') or (ch >= '0' and ch <= '9') or ch == '_')) {
                        all_upper_ident = false;
                        break;
                    }
                }
                // Only treat as a type-param if it is NOT a known concrete type name.
                if (all_upper_ident) {
                    const reg = self.root_registry();
                    const is_concrete_type = reg != null and
                        (reg.?.compounds_by_name.contains(spelling) or reg.?.enums_by_name.contains(spelling));
                    if (!is_concrete_type) return;
                }
            }
        }
        for (hits.items) |candidate| {
            const cim = candidate.impl_node.node_variant.?.impl;
            const cforced = cim.type_param_forced_insts orelse return; // unconstrained match accepts anything
            if (impl_allows_generic_args(cforced, gargs)) return; // an accepting match is enough
        }
        const mangled = self.type_name_mangled(dt) catch dt.type_str.items;
        self.report_type_error(node, "'{s}' does not satisfy the constraint on 'impl {s}' for method '{s}'", .{ mangled, base, method_name });
        return TranspileError.TypeMismatch;
    }

    fn synthesize_generic_plain_method_sig(self: *Self, recv_dt: *const dtype.DataType, recv_name: []const u8, method_name: []const u8) ?FnSig {
        if (recv_dt.generic_args == null) return null;
        const base = if (mem.indexOf(u8, recv_name, "__")) |idx| recv_name[0..idx] else recv_name;
        // Match plain- AND quirk-impl methods: a generic receiver may call a quirk
        // method statically (`it.next()` where `it: MapIter<T,bin>` implements
        // `Iterator<T>`). The sig is synthesized by substituting the receiver's type
        // args, identical for plain and quirk impls.
        const hit = self.find_any_impl_method_node(base, method_name) orelse return null;
        if (hit.method_node.node_variant == null) return null;
        const fnv = hit.method_node.node_variant.?.function;
        const params = self.impl_type_params(hit.impl_node) orelse return null;
        const gargs = recv_dt.generic_args.?.items();
        if (gargs.len != params.count) return null;

        const args_vec = fnv.args orelse utils.Vector(*ast.Node).init(self.allocator);
        const args_items = args_vec.items();
        var args_slice = self.allocator.alloc(CheckedType, args_items.len) catch return null;

        var i: usize = 0;
        for (args_items) |arg_ptr| {
            const arg = arg_ptr.*;
            if (arg.type == .Variable and arg.node_variant != null) {
                args_slice[i] = self.type_from_dtype_with_subst(arg.node_variant.?.variable.type, params.*, gargs) catch return null;
            } else {
                args_slice[i] = .{ .base = .Unknown };
            }
            i += 1;
        }

        // IMPORTANT: pass a pointer to the AST node's STORED rtype, not to a
        // by-value stack capture (`if (fnv.rtype) |rt|`). `type_from_dtype_with_subst`
        // sets the resulting CheckedType's `dtype_ref` to the passed pointer; a stack
        // local would dangle and later crash when a chained field access reads it
        // (e.g. `b.get_inner().code` where get_inner returns a compound).
        const rtype = if (hit.method_node.node_variant.?.function.rtype != null)
            self.type_from_dtype_with_subst(&hit.method_node.node_variant.?.function.rtype.?, params.*, gargs) catch return null
        else
            CheckedType{ .base = .Void };
        return .{ .rtype = rtype, .args = args_slice, .is_variadic = fnv.is_variadic, .is_async = fnv.is_async, .min_args = count_required_args_from_node(args_vec) };
    }

    /// Synthesize a generic-method sig from a MANGLED instance name (`Box__str`) by
    /// reconstructing its dtype (base + type args) and delegating to
    /// `synthesize_generic_plain_method_sig`. Resolves the case where a concrete-typed
    /// impl (`impl Box<str>`) — possibly for a type the program never instantiates —
    /// calls a sibling method defined on the generic base `impl Box<T>`: the receiver's
    /// scope dtype is the bare mangled name (no generic_args), so the earlier
    /// generic_args-based paths miss it. Returns null when not applicable.
    fn synthesize_generic_method_sig_from_mangled(self: *Self, mangled_name: []const u8, method_name: []const u8) ?FnSig {
        if (mem.indexOf(u8, mangled_name, "__") == null) return null;
        const dt = (self.dtype_from_mangled_type(mangled_name) catch return null) orelse return null;
        if (dt.generic_args == null) return null;
        return self.synthesize_generic_plain_method_sig(dt, mangled_name, method_name);
    }

    /// Result of resolving a value's iterability for `for item : value`.
    const IterableElem = struct {
        /// The element type yielded each step (the `T` in the iterator's `Option<T>`).
        elem: *dtype.DataType,
        /// When true, `value` is a collection exposing `iter()` that must be CALLED to
        /// obtain the iterator; when false, `value` already IS an iterator (has `next`).
        needs_iter_call: bool,
        /// The iterator's own (monomorphized) type name to declare the loop temp with,
        /// e.g. `VecIter__num`. Equals the receiver's mangled name when needs_iter_call
        /// is false. Arena-owned.
        iter_type_name: []const u8,
    };

    /// Given the dtype of a `for ... : value` iterable, decide how to drive it via the
    /// Iterator protocol and what element type it yields. Mirrors how `{}` resolves
    /// `Display.to_string()`: a value is iterable if its type (a) implements
    /// `Iterator<T>` directly (has `next() Option<T>`), or (b) exposes `iter()`
    /// returning such an iterator. Returns null when neither applies (caller then
    /// falls back to the raw-array / Vec fast path or errors).
    fn resolve_iterable_elem(self: *Self, dt: *const dtype.DataType) ?IterableElem {
        if (dt.pointer_depth != 0 or dt.type_str.items.len == 0) return null;
        const base = if (mem.indexOf(u8, dt.type_str.items, "__")) |i| dt.type_str.items[0..i] else dt.type_str.items;

        // Reconstruct full args if dt is a bare mangled instance (e.g. `VecIter__num`).
        var dt_full: *const dtype.DataType = dt;
        if (dt.generic_args == null and mem.indexOf(u8, dt.type_str.items, "__") != null) {
            if (self.dtype_from_mangled_type(dt.type_str.items) catch null) |recon| dt_full = recon;
        }

        // (a) `value` itself is an iterator: it has `next() Option<T>`.
        if (self.iterator_next_elem(base, dt_full)) |elem| {
            const itn = self.type_name_mangled(dt_full) catch dt.type_str.items;
            return .{ .elem = elem, .needs_iter_call = false, .iter_type_name = self.arena.allocator().dupe(u8, itn) catch dt.type_str.items };
        }

        // (b) `value` is a collection exposing `iter() -> SomeIter<...>`.
        const iter_hit = self.find_any_impl_method_node(base, "iter") orelse return null;
        if (iter_hit.method_node.node_variant == null) return null;
        const iter_rt = iter_hit.method_node.node_variant.?.function.rtype orelse return null;
        if (iter_rt.pointer_depth != 0) return null;
        // Monomorphize the iterator type with the collection's type args.
        const iter_dt: *dtype.DataType = blk: {
            if (self.impl_type_params(iter_hit.impl_node)) |params| {
                if (dt_full.generic_args) |ga| {
                    const gargs = ga.items();
                    if (gargs.len == params.count) {
                        if (self.clone_dtype_with_subst_for_inst(&iter_rt, params, gargs) catch null) |sub| break :blk sub;
                    }
                }
            }
            break :blk self.clone_dtype(&iter_rt) catch return null;
        };
        const iter_base = if (mem.indexOf(u8, iter_dt.type_str.items, "__")) |i| iter_dt.type_str.items[0..i] else iter_dt.type_str.items;
        const elem = self.iterator_next_elem(iter_base, iter_dt) orelse return null;
        const itn = self.type_name_mangled(iter_dt) catch iter_dt.type_str.items;
        return .{ .elem = elem, .needs_iter_call = true, .iter_type_name = self.arena.allocator().dupe(u8, itn) catch iter_dt.type_str.items };
    }

    const MapKV = struct { key: *dtype.DataType, val: *dtype.DataType };

    /// If `dt` is a `Map<K, V>` instance, return its (K, V) element dtypes — used to
    /// type `for k, v :: map` pair iteration. Returns null for non-Map types.
    fn map_kv_dtypes(self: *Self, dt: *const dtype.DataType) ?MapKV {
        if (dt.pointer_depth != 0) return null;
        const base = if (mem.indexOf(u8, dt.type_str.items, "__")) |i| dt.type_str.items[0..i] else dt.type_str.items;
        if (!mem.eql(u8, base, "Map")) return null;
        var dt_full: *const dtype.DataType = dt;
        if (dt.generic_args == null and mem.indexOf(u8, dt.type_str.items, "__") != null) {
            if (self.dtype_from_mangled_type(dt.type_str.items) catch null) |recon| dt_full = recon;
        }
        const ga = (dt_full.generic_args orelse return null).items();
        if (ga.len != 2) return null;
        return .{ .key = ga[0], .val = ga[1] };
    }

    /// If `base` (instantiated as `dt`) has a `next()` method returning `Option<T>`,
    /// return the monomorphized `T` (substituting `dt`'s type args through the impl's
    /// params). Returns null when there is no such method.
    fn iterator_next_elem(self: *Self, base: []const u8, dt: *const dtype.DataType) ?*dtype.DataType {
        const hit = self.find_any_impl_method_node(base, "next") orelse return null;
        if (hit.method_node.node_variant == null) return null;
        const rt = hit.method_node.node_variant.?.function.rtype orelse return null;
        // Must return Option<...>.
        const rbase = if (mem.indexOf(u8, rt.type_str.items, "__")) |i| rt.type_str.items[0..i] else rt.type_str.items;
        if (!mem.eql(u8, rbase, "Option")) return null;
        if (rt.generic_args == null) return null;
        const opt_arg = rt.generic_args.?.items();
        if (opt_arg.len != 1) return null;
        // Substitute the impl's type params (e.g. `T`) with `dt`'s concrete args.
        if (self.impl_type_params(hit.impl_node)) |params| {
            if (dt.generic_args) |ga| {
                const gargs = ga.items();
                if (gargs.len == params.count) {
                    if (self.clone_dtype_with_subst_for_inst(opt_arg[0], params, gargs) catch null) |sub| return sub;
                }
            }
        }
        return self.clone_dtype(opt_arg[0]) catch null;
    }

    fn find_function_node_proc(self: *Self, proc: *Self, name: []const u8) ?*ast.Node {
        for (proc.nodes.items()) |*n| {
            if (n.type != .Function or n.node_variant == null) continue;
            const fnv = n.node_variant.?.function;
            if (fnv.name != null and mem.eql(u8, fnv.name.?.items, name)) return n;
        }

        for (proc.owned_nodes.items) |impl_node| {
            if (impl_node.type != .Impl or impl_node.node_variant == null) continue;
            const im = impl_node.node_variant.?.impl;
            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name != null and mem.eql(u8, fnv.name.?.items, name)) return m;
            }
        }

        for (proc.children.items) |child| {
            if (self.find_function_node_proc(child, name)) |found| return found;
        }
        return null;
    }

    fn find_global_variable_node_proc(self: *Self, proc: *Self, name: []const u8) ?*ast.Node {
        for (proc.nodes.items()) |*n| {
            if (n.type != .Variable or n.node_variant == null) continue;
            if (mem.eql(u8, n.node_variant.?.variable.name.items, name)) return n;
        }
        for (proc.children.items) |child| {
            if (self.find_global_variable_node_proc(child, name)) |found| return found;
        }
        return null;
    }

    /// Finds a top-level (module-scope) `.Variable` declaration node by name
    /// — the GLOBAL-scope counterpart of `find_function_node`, same "current
    /// module first, then whole-program" search order. Needed by
    /// `check_const_reassignment` because a global's OWN `TypeEnv` binding
    /// (`global_env` in `typecheck_module`) is scoped to the MODULE-level
    /// pass only — every function body typechecks under its own completely
    /// fresh `TypeEnv` that never inherits it, so a global referenced from
    /// inside a function body has no `env`-visible declaration node to
    /// check `is_const` against without this fallback.
    fn find_global_variable_node(self: *Self, name: []const u8) ?*ast.Node {
        if (self.find_global_variable_node_proc(self, name)) |found| return found;
        const root = self.get_root();
        return self.find_global_variable_node_proc(root, name);
    }

    fn find_function_node(self: *Self, name: []const u8) ?*ast.Node {
        // Try the CALLING module's own scope first (its own top-level
        // functions/impl methods, then its own imports) before falling back
        // to a whole-program search rooted at the entrypoint. Two different,
        // unrelated files can each declare their own private (non-`pub`)
        // helper under the same bare name (e.g. two small parser-ish
        // modules each with their own `mk_bin`/`peek`/`advance`) — searching
        // from the root ALWAYS finds whichever same-named node the root's
        // fixed traversal order happens to reach first, regardless of which
        // module is actually calling, so a module's call to its OWN local
        // helper could resolve to a completely different file's PRIVATE
        // same-named function and get spuriously rejected as "is private".
        if (self.find_function_node_proc(self, name)) |found| return found;
        const root = self.get_root();
        return self.find_function_node_proc(root, name);
    }

    fn find_generic_fn_instantiation(self: *Self, name: []const u8) ?*const GenericFnInstantiation {
        const root = self.get_root();
        for (root.generic_fn_instantiations.items) |*inst| {
            if (mem.eql(u8, inst.name, name)) return inst;
        }
        return null;
    }

    fn find_imported_proc_by_alias(self: *Self, ref_node: ?*const ast.Node, alias: []const u8) ?*Self {
        const root = self.get_root();
        const owner = blk: {
            if (ref_node) |n| {
                if (n.pos) |p| {
                    if (root.find_process_for_file(p.filename)) |proc| break :blk proc;
                }
            }
            break :blk self;
        };
        for (owner.children.items) |child| {
            if (child.import_alias) |child_alias| {
                if (mem.eql(u8, child_alias, alias)) return child;
            }
        }
        return null;
    }

    const FreeCallDefaultInfo = struct {
        fn_node: *ast.Node,
        subst_params: ?*const utils.Vector(ArrayList(u8)) = null,
        subst_args: ?[]*dtype.DataType = null,
    };

    fn resolve_free_call_default_info(self: *Self, call_node: ast.Node, callee: *ast.Node) ?FreeCallDefaultInfo {
        if (self.lookup_generic_call_override(call_node)) |spec_name| {
            const inst = self.find_generic_fn_instantiation(spec_name) orelse return null;
            return .{ .fn_node = inst.fn_node, .subst_params = inst.params, .subst_args = inst.args };
        }

        if (callee.type == .Identifier and callee.data != null) {
            const fname = callee.data.?.sval.items;
            const fname_base = if (std.mem.lastIndexOf(u8, fname, "__")) |sep| fname[sep + 2 ..] else fname;
            const fn_node = self.find_function_node(fname) orelse self.find_function_node(fname_base) orelse return null;
            return .{ .fn_node = fn_node };
        }

        if (callee.type == .Expression and callee.node_variant != null and mem.eql(u8, callee.node_variant.?.exp.op, ".")) {
            const dot = callee.node_variant.?.exp;
            const left = dot.left orelse return null;
            const right = dot.right orelse return null;
            if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                const alias_name = left.*.data.?.sval.items;
                const member_name = right.*.data.?.sval.items;
                if (self.alias_map_for_node(&call_node).contains(alias_name)) {
                    if (self.alias_is_c_binding(&call_node, alias_name)) return null;
                    if (self.find_imported_proc_by_alias(&call_node, alias_name)) |proc| {
                        if (self.find_function_node_proc(proc, member_name)) |fn_node| {
                            return .{ .fn_node = fn_node };
                        }
                    }
                    if (self.find_function_node(member_name)) |fn_node| {
                        return .{ .fn_node = fn_node };
                    }
                }
            }
        }

        return null;
    }

    fn emit_expr_with_subst(self: *Self, expr: ast.Node, subst_params: ?*const utils.Vector(ArrayList(u8)), subst_args: ?[]*dtype.DataType) TranspileError!void {
        const prev_params = self.type_subst_params;
        const prev_args = self.type_subst_args;
        if (subst_params != null and subst_args != null) {
            self.type_subst_params = subst_params;
            self.type_subst_args = subst_args;
        }
        defer {
            self.type_subst_params = prev_params;
            self.type_subst_args = prev_args;
        }
        try self.transpile_node(expr);
    }

    fn emit_omitted_default_args_from_params(self: *Self, params: []const *ast.Node, passed: usize, initially_wrote_any: bool, subst_params: ?*const utils.Vector(ArrayList(u8)), subst_args: ?[]*dtype.DataType) TranspileError!void {
        if (passed >= params.len) return;

        var wrote_any = initially_wrote_any;
        var idx: usize = passed;
        while (idx < params.len) : (idx += 1) {
            const p = params[idx].*;
            if (p.type != .Variable or p.node_variant == null) return;
            const dflt = p.node_variant.?.variable.val orelse return;
            if (wrote_any) try self.write(", ");
            try self.emit_expr_with_subst(dflt.*, subst_params, subst_args);
            wrote_any = true;
        }
    }

    /// Append the callee's default-value expressions for any TRAILING params the call
    /// omitted. `right` is the call's (flattened) argument expression; `passed` is how
    /// many args the caller actually wrote. For each param index in [passed, param_count)
    /// whose AST node carries a default (`Variable.val`), emit `, <default>`. Emitted in
    /// the general (non-variadic) call path so a single chokepoint covers free-function
    /// calls; methods/generics route through their own paths and are handled separately.
    /// No-op when the callee isn't found, has no defaults, or the call is already full.
    fn emit_trailing_default_args(self: *Self, call_node: ast.Node, callee: *ast.Node, right: ?*ast.Node) TranspileError!void {
        const info = self.resolve_free_call_default_info(call_node, callee) orelse return;
        const fn_node = info.fn_node;
        if (fn_node.node_variant == null) return;
        const fnv = fn_node.node_variant.?.function;
        if (fnv.is_variadic) return; // variadic path handles its own arg list
        const args_vec = fnv.args orelse return;
        const params = args_vec.items();
        if (params.len == 0) return;

        // Count how many args the caller actually passed.
        var passed: usize = 0;
        if (right) |r| {
            var tmp = ArrayList(*ast.Node).init(self.allocator);
            defer tmp.deinit();
            self.flatten_call_args_ptr(r, &tmp) catch return;
            passed = tmp.items.len;
        }
        try self.emit_omitted_default_args_from_params(params, passed, passed > 0, info.subst_params, info.subst_args);
    }

    /// Method variant: fill omitted trailing default args for a resolved method whose
    /// C function is `fn_name` (e.g. `Box__add`). `c_args_emitted` is how many C args were
    /// already written (the receiver counts as one, plus the user args). The method node's
    /// own param list does NOT include `self`, so a param at user-index `u` maps to
    /// C-arg-index `u + 1`; we fill the method-node params from `c_args_emitted - 1`.
    /// `wrote_any` must be true (the receiver is always emitted first). No-op when no
    /// defaults apply.
    fn emit_trailing_default_args_for_method(self: *Self, type_name_canon: []const u8, method_base: []const u8, c_args_emitted: usize) TranspileError!void {
        // Resolve the method's AST node by TYPE + METHOD base name (not the mangled C
        // name): a generic method's node is stored under its template name (`get`), so a
        // mangled-name lookup like `Gen__num__get` would miss it. find_any_impl_method_node
        // matches the BASE type (no generic suffix) + method across plain and quirk impls,
        // so strip any `__<args>` mangling from the receiver type first.
        const canon = self.canonical_compound_name(type_name_canon);
        const type_base = if (mem.indexOf(u8, canon, "__")) |idx| canon[0..idx] else canon;
        const hit = self.find_any_impl_method_node(type_base, method_base) orelse return;
        const fn_node = hit.method_node;
        if (fn_node.node_variant == null) return;
        const fnv = fn_node.node_variant.?.function;
        if (fnv.is_variadic) return;
        const args_vec = fnv.args orelse return;
        const params = args_vec.items();
        // Whether the method node's first param is an explicit `self`.
        var first_is_self = false;
        if (params.len > 0 and params[0].*.type == .Variable and params[0].*.node_variant != null) {
            first_is_self = mem.eql(u8, params[0].*.node_variant.?.variable.name.items, "self");
        }
        const self_offset: usize = if (first_is_self) 1 else 0;
        // C arg 0 is the receiver. User args occupy C args [1, c_args_emitted). So the
        // next method-node param to consider is at index (c_args_emitted - 1) + self_offset.
        if (c_args_emitted == 0) return;
        var idx: usize = (c_args_emitted - 1) + self_offset;
        while (idx < params.len) : (idx += 1) {
            const p = params[idx].*;
            if (p.type != .Variable or p.node_variant == null) return;
            const dflt = p.node_variant.?.variable.val orelse return;
            try self.write(", ");
            try self.transpile_node(dflt.*);
        }
    }

    fn any_accessible_function_named_proc(self: *Self, proc: *Self, ref_node: ?*const ast.Node, name: []const u8) bool {
        for (proc.nodes.items()) |*n| {
            if (n.type != .Function or n.node_variant == null) continue;
            const fnv = n.node_variant.?.function;
            if (fnv.name != null and mem.eql(u8, fnv.name.?.items, name)) {
                if (self.can_access(ref_node, n)) return true;
            }
        }
        for (proc.children.items) |child| {
            if (self.any_accessible_function_named_proc(child, ref_node, name)) return true;
        }
        return false;
    }

    /// True if some top-level function named `name` reachable from the root is
    /// accessible from `ref_node` (public, or in the same module). Used to gate
    /// alias-qualified calls without false-positiving on a benign name collision
    /// between a private fn in one module and a public fn in another.
    fn any_accessible_function_named(self: *Self, ref_node: ?*const ast.Node, name: []const u8) bool {
        const root = self.get_root();
        return self.any_accessible_function_named_proc(root, ref_node, name);
    }

    const GlobalVarScan = struct { exists: bool, accessible: bool };

    fn scan_global_var_named_proc(self: *Self, proc: *Self, ref_node: ?*const ast.Node, name: []const u8, out: *GlobalVarScan) void {
        for (proc.nodes.items()) |*n| {
            if (n.type != .Variable or n.node_variant == null) continue;
            const v = n.node_variant.?.variable;
            if (mem.eql(u8, v.name.items, name)) {
                out.exists = true;
                if (self.can_access(ref_node, n)) out.accessible = true;
            }
        }
        for (proc.children.items) |child| {
            self.scan_global_var_named_proc(child, ref_node, name, out);
        }
    }

    /// Scans the root + imported modules for a top-level (global) variable named
    /// `name`, reporting whether any exists and whether any is accessible from
    /// `ref_node` (public, or same module). Used to gate alias-qualified GLOBAL
    /// reads (`alias.global`): a private global must not be reachable through an
    /// alias (it otherwise emitted an undeclared `alias__global`, invalid C). The
    /// "any accessible" form avoids false-positives on a name collision between a
    /// private global in one module and a public one in another.
    fn scan_global_var_named(self: *Self, ref_node: ?*const ast.Node, name: []const u8) GlobalVarScan {
        var out = GlobalVarScan{ .exists = false, .accessible = false };
        const root = self.get_root();
        self.scan_global_var_named_proc(root, ref_node, name, &out);
        return out;
    }

    fn lookup_quirk_impl_method_fn_for_self(self: *Self, type_name: []const u8, method_name: []const u8) ?[]const u8 {
        const root = self.get_root();
        if (root.type_registry == null) return null;
        const reg = &root.type_registry.?;

        var it = reg.impls_by_key.iterator();
        while (it.next()) |entry| {
            const key = entry.key_ptr.*;
            if (!mem.eql(u8, key.type_name, type_name)) continue;

            // Only consider quirk impls.
            const impl_node = entry.value_ptr.*;
            if (impl_node.node_variant == null) continue;
            const im = impl_node.node_variant.?.impl;
            if (im.quirk_name == null) continue;

            // Ensure the quirk signature actually contains this method name.
            const qnode = reg.quirks_by_sig.get(key.quirk_sig) orelse continue;
            if (qnode.node_variant == null) continue;
            const q = qnode.node_variant.?.quirk;
            var has_method = false;
            for (q.methods.items()) |qm| {
                if (mem.eql(u8, qm.name.items, method_name)) {
                    has_method = true;
                    break;
                }
            }
            if (!has_method) continue;

            // Find the generated method function name by suffix match. Match
            // `full` ending in `__<method_name>` without materializing the
            // suffix string (method names are unbounded, so a fixed buffer could
            // overflow): require the trailing `<method_name>` to be preceded by
            // `__`.
            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const full = fnv.name.?.items;
                if (full.len >= method_name.len + 2 and
                    mem.endsWith(u8, full, method_name) and
                    mem.eql(u8, full[full.len - method_name.len - 2 .. full.len - method_name.len], "__"))
                {
                    return full;
                }
            }
        }
        return null;
    }

    const QuirkImplMethodResolution = struct {
        fn_name: ?[]const u8 = null,
        quirk_name: ?[]const u8 = null,
        ambiguous: bool = false,
        other_quirk_name: ?[]const u8 = null,
    };

    const DisplayCallResolution = struct {
        fn_name: []const u8,
        pass_by_ref: bool,
    };

    fn resolve_quirk_impl_method_for_concrete(self: *Self, ref_node: ast.Node, type_name: []const u8, method_name: []const u8) QuirkImplMethodResolution {
        const root = self.get_root();
        if (root.type_registry == null) return .{};
        const reg = &root.type_registry.?;

        const base_name = if (mem.indexOf(u8, type_name, "__")) |idx| type_name[0..idx] else type_name;

        var res: QuirkImplMethodResolution = .{};
        var it = reg.impls_by_key.iterator();
        while (it.next()) |entry| {
            const key = entry.key_ptr.*;
            const matches_exact = mem.eql(u8, key.type_name, type_name);
            const matches_generic = mem.eql(u8, key.type_name, base_name);
            if (!matches_exact and !matches_generic) continue;

            const impl_node = entry.value_ptr.*;
            if (impl_node.node_variant == null) continue;
            const im = impl_node.node_variant.?.impl;
            if (im.quirk_name == null) continue;

            const qnode = reg.quirks_by_sig.get(key.quirk_sig) orelse continue;
            if (qnode.node_variant == null) continue;
            if (!self.can_access(&ref_node, qnode)) continue;
            const q = qnode.node_variant.?.quirk;
            const qname = q.name.items;

            // The method may be a quirk-CONTRACT method, OR an EXTRA `pub` method
            // declared in the `impl Type as Quirk { ... }` block (not part of the
            // contract). Both are emitted as `Type__Quirk__method` and callable on
            // the concrete type. Previously only contract methods were resolved, so
            // an extra pub method (e.g. stdlib `Vec.capacity()`) was unreachable.
            var has_method = false;
            for (q.methods.items()) |qm| {
                if (mem.eql(u8, qm.name.items, method_name)) {
                    has_method = true;
                    break;
                }
            }
            if (!has_method) {
                for (im.methods.items()) |m| {
                    if (m.type != .Function or m.node_variant == null) continue;
                    const fnv = m.node_variant.?.function;
                    if (fnv.name == null) continue;
                    const full = fnv.name.?.items;
                    const bn = base_method_name_from_generated(full) orelse continue;
                    if (mem.eql(u8, bn, method_name)) {
                        has_method = true;
                        break;
                    }
                }
            }
            if (!has_method) continue;

            var fn_name: ?[]const u8 = null;
            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                if (!self.can_access_method(&ref_node, impl_node, m)) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const full = fnv.name.?.items;
                // Match `full` ending in `__<method_name>` without allocating a
                // suffix string (method names are unbounded).
                if (full.len >= method_name.len + 2 and
                    mem.endsWith(u8, full, method_name) and
                    mem.eql(u8, full[full.len - method_name.len - 2 .. full.len - method_name.len], "__"))
                {
                    if (matches_exact) {
                        fn_name = full;
                    } else {
                        fn_name = std.fmt.allocPrint(self.allocator, "{s}__{s}__{s}", .{ type_name, qname, method_name }) catch null;
                    }
                    break;
                }
            }
            if (fn_name == null) continue;

            if (res.fn_name == null) {
                res.fn_name = fn_name;
                res.quirk_name = qname;
            } else {
                // Multiple quirks implemented by this type share the same method name.
                res.ambiguous = true;
                res.other_quirk_name = qname;
                return res;
            }
        }
        return res;
    }

    /// Emit a variadic argument expression with any required bool cast applied.
    /// Used to inline variadic args directly (avoiding __auto_type / GNU ({}) extensions).
    fn emit_va_arg_expr(self: *Self, var_node: ast.Node) TranspileError!void {
        if (var_node.type == .Boolean) {
            try self.write("(bool)");
            try self.transpile_node(var_node);
        } else if (var_node.type == .Identifier and var_node.data != null) {
            const nm = var_node.data.?.sval.items;
            if (self.identifier_declared_dtype(nm)) |dt| {
                if (dt.type == .Bin) {
                    try self.write("(bool)");
                }
            }
            try self.transpile_node(var_node);
        } else {
            try self.transpile_node(var_node);
        }
    }

    fn resolve_display_call_for_expr(self: *Self, ref_node: ast.Node, expr: ast.Node) ?DisplayCallResolution {
        if (expr.type == .ExpressionParenthesis and expr.node_variant != null) {
            return self.resolve_display_call_for_expr(ref_node, expr.node_variant.?.paren.exp.*);
        }

        if (expr.type == .Identifier and expr.data != null) {
            const nm = expr.data.?.sval.items;
            const dt = self.identifier_declared_dtype(nm) orelse return null;
            if (dt.type != .Unknown) return null;

            // A generic compound's `type_str` is just the bare template name
            // (e.g. "Node" for `Node<num>`) — `generic_args` holds the concrete
            // arg separately. Resolving against the bare name would dispatch to
            // `Node__Display__to_string` (never emitted); mangle to `Node__num`
            // first, matching how direct method calls (`lookup_plain_impl_method_fn`
            // callers above) already do it.
            var type_name: []const u8 = dt.type_str.items;
            var owned_type_name = false;
            if (dt.generic_args != null) {
                type_name = self.type_name_mangled_for_emit(dt) catch return null;
                owned_type_name = true;
            }
            defer if (owned_type_name) self.allocator.free(@constCast(type_name));

            const type_name_canon = self.canonical_compound_name(type_name);
            const res = self.resolve_quirk_impl_method_for_concrete(ref_node, type_name_canon, "to_string");
            if (res.fn_name == null or res.quirk_name == null or res.ambiguous) return null;
            if (!mem.eql(u8, res.quirk_name.?, "Display")) return null;

            return .{
                .fn_name = res.fn_name.?,
                .pass_by_ref = dt.pointer_depth == 0,
            };
        }

        if (expr.type == .Unary and expr.node_variant != null) {
            const u = expr.node_variant.?.unary;
            if (mem.eql(u8, u.op, "&")) {
                const op = u.operand.*;
                if (op.type != .Identifier or op.data == null) return null;
                const nm = op.data.?.sval.items;
                const dt = self.identifier_declared_dtype(nm) orelse return null;
                if (dt.type != .Unknown) return null;

                var type_name: []const u8 = dt.type_str.items;
                var owned_type_name = false;
                if (dt.generic_args != null) {
                    type_name = self.type_name_mangled_for_emit(dt) catch return null;
                    owned_type_name = true;
                }
                defer if (owned_type_name) self.allocator.free(@constCast(type_name));

                const type_name_canon = self.canonical_compound_name(type_name);
                const res = self.resolve_quirk_impl_method_for_concrete(ref_node, type_name_canon, "to_string");
                if (res.fn_name == null or res.quirk_name == null or res.ambiguous) return null;
                if (!mem.eql(u8, res.quirk_name.?, "Display")) return null;

                return .{
                    .fn_name = res.fn_name.?,
                    .pass_by_ref = false,
                };
            }

            // `*ptr` dereferencing a pointer down to a plain value — e.g.
            // `println_fmt("{}", *program)` for an `Expr*` AST node, or the
            // `fit *self { ... }`-derived recursive `format("{}", *e)` calls
            // a Display impl's own to_string() makes on its pointer fields.
            // Previously unhandled here, so it fell through to `return null`
            // and format() printed the raw (garbage-looking) bytes instead
            // of dispatching to Display.
            if (mem.eql(u8, u.op, "*")) {
                const op = u.operand.*;
                if (op.type != .Identifier or op.data == null) return null;
                const nm = op.data.?.sval.items;
                const dt = self.identifier_declared_dtype(nm) orelse return null;
                if (dt.type != .Unknown or dt.pointer_depth == 0) return null;

                var type_name: []const u8 = dt.type_str.items;
                var owned_type_name = false;
                if (dt.generic_args != null) {
                    type_name = self.type_name_mangled_for_emit(dt) catch return null;
                    owned_type_name = true;
                }
                defer if (owned_type_name) self.allocator.free(@constCast(type_name));

                const type_name_canon = self.canonical_compound_name(type_name);
                const res = self.resolve_quirk_impl_method_for_concrete(ref_node, type_name_canon, "to_string");
                if (res.fn_name == null or res.quirk_name == null or res.ambiguous) return null;
                if (!mem.eql(u8, res.quirk_name.?, "Display")) return null;

                return .{
                    .fn_name = res.fn_name.?,
                    .pass_by_ref = dt.pointer_depth == 1,
                };
            }
        }

        // A plain field access (`self.gender`, e.g. a Display impl's own
        // body formatting one of its fields whose OWN type also implements
        // Display, `format("... {} ...", self.gender)` inside `impl User as
        // Display`) — resolves the receiver's OWN declared type, then that
        // type's compound field registry, to find the field's declared
        // type. Previously unhandled, so a field of a Display-implementing
        // type printed its raw underlying representation (an enum's bare
        // ordinal, e.g.) instead of dispatching to Display — confirmed via
        // a real minimal repro, not previously exercised by the existing
        // test/example corpus. Narrower than the general case: only a
        // bare-identifier receiver (`self`, `recv`), matching this
        // function's own existing scope for every other case above.
        if (expr.type == .Expression and expr.node_variant != null and mem.eql(u8, expr.node_variant.?.exp.op, ".")) {
            const dot = expr.node_variant.?.exp;
            const left = dot.left orelse return null;
            const right = dot.right orelse return null;
            if (left.*.type != .Identifier or left.*.data == null) return null;
            if (right.*.type != .Identifier or right.*.data == null) return null;
            const recv_name = left.*.data.?.sval.items;
            const field_name = right.*.data.?.sval.items;

            const recv_dt = self.identifier_declared_dtype(recv_name) orelse return null;
            if (recv_dt.type != .Unknown) return null;

            var recv_type_name: []const u8 = recv_dt.type_str.items;
            var recv_type_owned = false;
            if (recv_dt.generic_args != null) {
                recv_type_name = self.type_name_mangled_for_emit(recv_dt) catch return null;
                recv_type_owned = true;
            }
            defer if (recv_type_owned) self.allocator.free(@constCast(recv_type_name));
            const recv_type_canon = self.canonical_compound_name(recv_type_name);

            const field_dt = self.lookup_compound_field(recv_type_canon, field_name) orelse return null;

            var field_type_name: []const u8 = field_dt.type_str.items;
            var field_type_owned = false;
            if (field_dt.generic_args != null) {
                field_type_name = self.type_name_mangled_for_emit(field_dt) catch return null;
                field_type_owned = true;
            }
            defer if (field_type_owned) self.allocator.free(@constCast(field_type_name));
            const field_type_canon = self.canonical_compound_name(field_type_name);

            const res = self.resolve_quirk_impl_method_for_concrete(ref_node, field_type_canon, "to_string");
            if (res.fn_name == null or res.quirk_name == null or res.ambiguous) return null;
            if (!mem.eql(u8, res.quirk_name.?, "Display")) return null;

            return .{
                .fn_name = res.fn_name.?,
                .pass_by_ref = field_dt.pointer_depth == 0,
            };
        }

        return null;
    }

    fn is_enum_named_type(self: *Self, t: CheckedType) bool {
        if (!is_user_named_type(t)) return false;
        if (t.is_array or t.pointer_depth != 0) return false;
        const root = self.get_root();
        if (root.type_registry == null) return false;
        return root.type_registry.?.enums_by_name.contains(t.name.?);
    }

    fn is_compound_named_type(self: *Self, t: CheckedType) bool {
        if (!is_user_named_type(t)) return false;
        const root = self.get_root();
        if (root.type_registry == null) return false;
        return root.type_registry.?.compounds_by_name.contains(t.name.?);
    }

    fn are_same_enum_type(self: *Self, a: CheckedType, b: CheckedType) bool {
        if (!self.is_enum_named_type(a) or !self.is_enum_named_type(b)) return false;
        const root = self.get_root();
        if (root.type_registry == null) return false;
        const reg = &root.type_registry.?;
        const an = a.name orelse return false;
        const bn = b.name orelse return false;
        const a_node = reg.enums_by_name.get(an) orelse return false;
        const b_node = reg.enums_by_name.get(bn) orelse return false;
        return a_node == b_node;
    }

    fn are_same_compound_type(self: *Self, a: CheckedType, b: CheckedType) bool {
        if (!self.is_compound_named_type(a) or !self.is_compound_named_type(b)) return false;
        if (a.is_array != b.is_array or a.pointer_depth != b.pointer_depth) return false;
        const root = self.get_root();
        if (root.type_registry == null) return false;
        const reg = &root.type_registry.?;
        const an = a.name orelse return false;
        const bn = b.name orelse return false;
        const a_node = reg.compounds_by_name.get(an) orelse return false;
        const b_node = reg.compounds_by_name.get(bn) orelse return false;
        if (a_node != b_node) return false;
        // Same base compound — but distinct generic instantiations are DIFFERENT
        // types (`Box<num>` != `Box<str>`). When either side is a generic instance,
        // require the mangled names to match; otherwise we'd wrongly accept
        // `Box<num>` where `Box<str>` is expected (which then emits invalid C).
        const a_mangled = a.mangled_name;
        const b_mangled = b.mangled_name;
        if (a_mangled != null or b_mangled != null) {
            if (a_mangled == null or b_mangled == null) return false;
            return mem.eql(u8, a_mangled.?, b_mangled.?);
        }
        return true;
    }

    fn is_numeric_type(self: *Self, t: CheckedType) bool {
        const tn = normalize_builtin_named_checked_type(t);
        if (tn.is_array or tn.pointer_depth != 0) return false;
        if (tn.base == .Num or tn.base == .Dec or tn.base == .Chr) return true;
        return self.is_enum_named_type(tn);
    }

    fn is_pointer_type(t: CheckedType) bool {
        return !t.is_array and t.pointer_depth > 0;
    }

    fn promote_numeric_type(a: CheckedType, b: CheckedType) dtype.DataTypeType {
        // Assumes numeric-compatible operands.
        if (a.base == .Dec or b.base == .Dec) return .Dec;
        return .Num;
    }

    fn is_quirk_named_type(self: *Self, t: CheckedType) bool {
        if (!is_user_named_type(t)) return false;
        const root = self.get_root();
        if (root.type_registry == null) return false;
        return root.type_registry.?.quirk_sig_by_name.contains(t.name.?);
    }

    fn normalize_builtin_named_checked_type(t: CheckedType) CheckedType {
        var out = t;
        if (out.base != .Unknown or out.name == null) return out;

        const n = out.name.?;
        if (mem.eql(u8, n, "num")) {
            out.base = .Num;
            out.name = null;
            out.mangled_name = null;
            return out;
        }
        if (mem.eql(u8, n, "dec")) {
            out.base = .Dec;
            out.name = null;
            out.mangled_name = null;
            return out;
        }
        if (mem.eql(u8, n, "str")) {
            out.base = .Str;
            out.name = null;
            out.mangled_name = null;
            return out;
        }
        if (mem.eql(u8, n, "chr")) {
            out.base = .Chr;
            out.name = null;
            out.mangled_name = null;
            return out;
        }
        if (mem.eql(u8, n, "bin")) {
            out.base = .Bin;
            out.name = null;
            out.mangled_name = null;
            return out;
        }
        if (mem.eql(u8, n, "raw")) {
            out.base = .Raw;
            out.name = null;
            out.mangled_name = null;
            return out;
        }
        if (mem.eql(u8, n, "void")) {
            out.base = .Void;
            out.name = null;
            out.mangled_name = null;
            return out;
        }

        return out;
    }

    fn can_implicit_coerce(self: *Self, expected: CheckedType, actual: CheckedType) TranspileError!bool {
        const expected_n = normalize_builtin_named_checked_type(expected);
        const actual_n = normalize_builtin_named_checked_type(actual);

        if (CheckedType.eql(expected_n, actual_n)) return true;

        // `panic("msg")` unifies with WHATEVER type is expected -- it never
        // actually produces a value (prints the message and aborts), so it's
        // compatible with any type at all, not just pointers/str like `nil`.
        if (actual_n.is_panic_literal) return true;

        // A bare function name used as a value (e.g. passing `add` where a
        // `fun(num, num) num` parameter is expected, as in `sort_by(cmp)`)
        // infers as an opaque `raw*` (see `infer_expr_type`'s `.Identifier`
        // case) -- accept it wherever a function-type parameter is expected.
        // Not signature-checked against the declared `fn_sig` yet (matches
        // the existing `raw* start_routine`-style callback bindings, which
        // are similarly unchecked); a real mismatch still fails at the C
        // level, same as those.
        if (expected_n.dtype_ref != null and expected_n.dtype_ref.?.fn_sig != null and
            actual_n.base == .Raw and actual_n.pointer_depth == 1 and !actual_n.is_array)
        {
            return true;
        }

        // Allow equivalent enum types referenced through different visible names
        // (e.g. `ErrorCode` and `err__ErrorCode`).
        if (self.are_same_enum_type(expected_n, actual_n)) return true;

        // Allow equivalent compound types referenced through different visible names
        // (e.g. `Vec2` and `geom__Vec2`).
        if (self.are_same_compound_type(expected_n, actual_n)) return true;

        // Enums behave as numeric values for coercion with `num` (a deliberate,
        // tested C-style design choice — see "typecheck enums behave as numeric
        // values across contexts"). NOTE: this means an arbitrary `num` can become
        // an enum implicitly, which can defeat `fit` exhaustiveness — flagged by the
        // audit as a soundness trade-off, but it is intended language semantics, not
        // a bug, so it is left as-is.
        if (self.is_enum_named_type(expected_n) and !actual_n.is_array and actual_n.pointer_depth == 0 and actual_n.base == .Num) {
            return true;
        }
        if (!expected_n.is_array and expected_n.pointer_depth == 0 and expected_n.base == .Num and self.is_enum_named_type(actual_n)) {
            return true;
        }

        // Quirk coercion: allow `T*` -> `Quirk` if an `impl T as Quirk { ... }` exists.
        if (self.is_quirk_named_type(expected_n) and is_user_named_type(actual_n) and actual_n.pointer_depth == 1 and !actual_n.is_array) {
            const root = self.get_root();
            if (root.type_registry == null) return false;
            const reg = &root.type_registry.?;
            // A CONCRETE instantiation of a generic quirk (`To<num>`) registers
            // its own substituted signature under the MANGLED name (`To__num`,
            // synthesized in `synthesize_quirk_instantiation`), distinct from
            // the bare generic template's own sig (`To`, still `to()->T;`).
            // Prefer the mangled name so this resolves against the concrete
            // instantiation's impls, not the unbound template's.
            const sig = reg.quirk_sig_by_name.get(expected_n.mangled_name orelse expected_n.name.?) orelse return false;
            // A generic instantiation registers its impl under the MANGLED name
            // (`impl Box<num> as Sized` -> key `Box__num`), so try the mangled
            // name first and fall back to the plain base name for non-generics.
            if (actual_n.mangled_name) |mn| {
                if (reg.impls_by_key.contains(.{ .type_name = mn, .quirk_sig = sig })) return true;
            }
            if (reg.impls_by_key.contains(.{ .type_name = actual_n.name.?, .quirk_sig = sig })) return true;
        }

        // Array-element quirk coercion: `Quirk[]` accepts an array literal of
        // concrete pointers `T*[]` when each `T` impls the quirk (e.g.
        // `Q[] arr = [&p0, &p1]`). Mirrors the scalar `T*` -> `Quirk` rule, applied
        // element-wise (the codegen coerces each element). NOTE: a Bracket's
        // inferred CheckedType drops the element pointer_depth (it's 0 on the array),
        // so confirm the element is a pointer via the backing `dtype_ref`.
        if (expected_n.is_array and actual_n.is_array and self.is_quirk_named_type(expected_n) and
            is_user_named_type(actual_n))
        {
            // (A Bracket's inferred CheckedType drops the element pointer_depth, so
            // we can't require it here; the codegen coerces each `&p` element, and
            // only an array whose element type impls the quirk reaches this point.)
            const root = self.get_root();
            if (root.type_registry) |*reg| {
                if (reg.quirk_sig_by_name.get(expected_n.mangled_name orelse expected_n.name.?)) |sig| {
                    if (actual_n.mangled_name) |mn| {
                        if (reg.impls_by_key.contains(.{ .type_name = mn, .quirk_sig = sig })) return true;
                    }
                    if (reg.impls_by_key.contains(.{ .type_name = actual_n.name.?, .quirk_sig = sig })) return true;
                }
            }
        }

        // C-style null pointer constant: allow `0` to convert to any pointer type.
        if (!expected_n.is_array and expected_n.pointer_depth > 0 and !actual_n.is_array and actual_n.pointer_depth == 0 and actual_n.is_null_literal) {
            return true;
        }

        // Treat `str` as a nullable reference type: allow `0` to convert to `str`.
        if (!expected_n.is_array and expected_n.pointer_depth == 0 and expected_n.base == .Str and !actual_n.is_array and actual_n.pointer_depth == 0 and actual_n.is_null_literal) {
            return true;
        }

        // Allow raw pointers to coerce to `str` (malloc-style allocations).
        if (!expected_n.is_array and expected_n.pointer_depth == 0 and expected_n.base == .Str and !actual_n.is_array and actual_n.base == .Raw and actual_n.pointer_depth > 0) {
            return true;
        }

        // Allow chr[] arrays to coerce to str (C-style buffers).
        if (!expected_n.is_array and expected_n.pointer_depth == 0 and expected_n.base == .Str and actual_n.is_array and actual_n.base == .Chr) {
            return true;
        }

        // Allow `str` to coerce to `raw*` (C APIs that accept void*).
        if (!expected_n.is_array and expected_n.base == .Raw and expected_n.pointer_depth > 0 and !actual_n.is_array and actual_n.base == .Str and actual_n.pointer_depth == 0) {
            return true;
        }

        // Allow raw pointers to coerce to array-typed values (malloc/realloc patterns).
        if (expected_n.is_array and !actual_n.is_array and actual_n.base == .Raw and actual_n.pointer_depth > 0) {
            return true;
        }

        // Allow array values to coerce to raw pointers (e.g., realloc/free/memset).
        if (!expected_n.is_array and expected_n.base == .Raw and expected_n.pointer_depth > 0 and actual_n.is_array) {
            return true;
        }

        if (expected_n.is_array != actual_n.is_array or expected_n.pointer_depth != actual_n.pointer_depth) return false;

        // `raw*` behaves like C `void*`: allow implicit conversion to/from any object pointer.
        if (!expected_n.is_array and expected_n.pointer_depth > 0 and actual_n.pointer_depth > 0) {
            if (expected_n.base == .Raw or actual_n.base == .Raw) return true;
        }

        // Allow widening conversions.
        if (expected_n.base == .Dec and actual_n.base == .Num and !expected_n.is_array and expected_n.pointer_depth == 0) return true;

        // `chr`/`num` already interoperate freely in arithmetic and comparisons
        // (see `can_compare_or_match` below, and `is_numeric_type` treating
        // `.Chr` as numeric) -- C itself allows implicit int<->char conversion
        // both ways, so extend that same bidirectional interop to assignment/
        // argument-passing instead of only letting it through via a `c + 0`
        // arithmetic-promotion workaround. Needed for e.g. `std.ctype`'s
        // `chr`-typed wrappers to call the underlying `num`-typed `std.c.ctype`
        // bindings directly.
        if (!expected_n.is_array and expected_n.pointer_depth == 0 and !actual_n.is_array and actual_n.pointer_depth == 0) {
            if ((expected_n.base == .Num and actual_n.base == .Chr) or (expected_n.base == .Chr and actual_n.base == .Num)) {
                return true;
            }
        }
        return false;
    }

    fn can_compare_or_match(self: *Self, a: CheckedType, b: CheckedType) bool {
        if (CheckedType.eql(a, b)) return true;

        if (self.are_same_enum_type(a, b)) return true;

        // Two DIFFERENT enum types are not comparable. Without this guard the
        // numeric fallthrough below (enums count as numeric) would let unrelated
        // enums compare by raw ordinal — a soundness hole inconsistent with
        // assignment/parameter rules, which already reject the mix. (Enum-vs-number
        // literal comparisons still flow through the numeric path below.)
        if (self.is_enum_named_type(a) and self.is_enum_named_type(b)) return false;

        // Numeric comparisons/coercion.
        if (self.is_numeric_type(a) and self.is_numeric_type(b)) return true;

        // Allow chr <-> num comparisons (C-style char/int coercions).
        if ((a.base == .Chr and b.base == .Num) or (a.base == .Num and b.base == .Chr)) return true;

        // C-style null pointer constant comparisons: allow `ptr == 0` / `ptr != 0`.
        // Array types (`T[]`, including unresolved generic element types) decay to
        // pointers under the hood, so they're nil-comparable too, not just `is_pointer_type`.
        if ((is_pointer_type(a) or a.is_array) and !b.is_array and b.pointer_depth == 0 and b.is_null_literal) return true;
        if ((is_pointer_type(b) or b.is_array) and !a.is_array and a.pointer_depth == 0 and a.is_null_literal) return true;

        // Also allow `str` to compare against null constant: `s == 0` / `s != 0`.
        if (!a.is_array and a.pointer_depth == 0 and a.base == .Str and !b.is_array and b.pointer_depth == 0 and b.is_null_literal) return true;
        if (!b.is_array and b.pointer_depth == 0 and b.base == .Str and !a.is_array and a.pointer_depth == 0 and a.is_null_literal) return true;

        // `raw*` behaves like `void*`: allow equality comparisons to other pointers.
        if (is_pointer_type(a) and is_pointer_type(b) and (a.base == .Raw or b.base == .Raw)) return true;

        return false;
    }

    fn is_let_infer_dtype(dt: *const dtype.DataType) bool {
        return (dt.type == null or dt.type == .Unknown) and mem.eql(u8, dt.type_str.items, "__let_infer__");
    }

    fn infer_let_variable_dtype(self: *Self, stmt: *ast.Node, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!?CheckedType {
        if (stmt.type != .Variable or stmt.node_variant == null) return null;
        const v = stmt.node_variant.?.variable;
        if (!is_let_infer_dtype(v.type)) return null;
        const val = v.val orelse {
            self.report_type_error(stmt.*, "'let' variable '{s}' requires an initializer", .{v.name.items});
            return TranspileError.TypeMismatch;
        };
        const inferred_t = blk: {
            if (dot_shorthand_variant_name(val)) |_| {
                if (try self.infer_let_enum_dot_shorthand(val)) |t| {
                    break :blk t;
                }
            }
            break :blk try self.infer_expr_type(val.*, env, fns);
        };
        if (!is_known_type(inferred_t)) {
            self.report_type_error(stmt.*, "cannot infer type for let variable '{s}'", .{v.name.items});
            return TranspileError.TypeMismatch;
        }
        // A void-returning call has no value to bind. `let x = void_fn()` would emit
        // an invalid `void x = ...;`, so reject it.
        if (inferred_t.base == .Void and !inferred_t.is_array and inferred_t.pointer_depth == 0) {
            self.report_type_error(stmt.*, "'let' variable '{s}' cannot be initialized from a value of type void", .{v.name.items});
            return TranspileError.TypeMismatch;
        }
        if (self.is_quirk_named_type(inferred_t)) {
            self.report_type_error(stmt.*, "let cannot infer quirk type for '{s}'; declare the quirk type explicitly", .{v.name.items});
            return TranspileError.TypeMismatch;
        }
        const inferred_dt = (try self.checked_type_to_dtype(inferred_t)) orelse {
            self.report_type_error(stmt.*, "cannot infer type for let variable '{s}'", .{v.name.items});
            return TranspileError.TypeMismatch;
        };
        stmt.node_variant.?.variable.type = inferred_dt;
        return inferred_t;
    }

    fn flatten_call_args_ptr(self: *Self, node: *ast.Node, out: *ArrayList(*ast.Node)) TranspileError!void {
        // Function call arguments are parsed as a parenthesis node that wraps an expression.
        // For zero-arg calls this inner expression is `.Blank`.
        if (node.type == .ExpressionParenthesis and node.node_variant != null) {
            const inner = node.node_variant.?.paren.exp;
            if (inner.*.type == .Blank) return;
            return try self.flatten_call_args_ptr(inner, out);
        }

        // A `.Blank` node represents an empty argument list.
        if (node.type == .Blank) return;

        if (node.type == .Expression and node.node_variant != null and mem.eql(u8, node.node_variant.?.exp.op, ",")) {
            const exp = node.node_variant.?.exp;
            if (exp.left) |left| try self.flatten_call_args_ptr(left, out);
            if (exp.right) |right| try self.flatten_call_args_ptr(right, out);
            return;
        }
        out.append(node) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    fn validate_async_call_usage(
        self: *Self,
        call_node: ast.Node,
        callee_name: ?[]const u8,
        callee_is_async: bool,
        async_known: bool,
    ) TranspileError!void {
        const display = callee_name orelse "<call>";

        const is_await_target_call = blk: {
            if (!self.in_await_operand_inference) break :blk false;
            const target = self.await_operand_target_pos orelse break :blk false;
            const call_pos = call_node.pos orelse break :blk false;
            break :blk std.mem.eql(u8, target.filename, call_pos.filename) and
                target.line == call_pos.line and
                target.start_col == call_pos.start_col and
                target.end_line == call_pos.end_line and
                target.end_col == call_pos.end_col;
        };

        if (is_await_target_call) {
            if (!async_known) {
                self.report_type_error(call_node, "await target '{s}' must resolve to an async function", .{display});
                return TranspileError.TypeMismatch;
            }
            if (!callee_is_async) {
                self.report_type_error(call_node, "await target '{s}' is not async", .{display});
                return TranspileError.TypeMismatch;
            }
            return;
        }

        // A `fork` target is an async function invoked fire-and-forget (no await),
        // so it is exempt from the must-be-awaited rule.
        if (self.in_fork_target_inference) return;

        if (async_known and callee_is_async) {
            self.report_type_error(call_node, "call to async function '{s}' must be awaited", .{display});
            return TranspileError.TypeMismatch;
        }
    }

    fn resolve_await_lowering_info(self: *Self, call_node: ast.Node) TranspileError!?AwaitLoweringInfo {
        if (call_node.type != .Expression or call_node.node_variant == null or !mem.eql(u8, call_node.node_variant.?.exp.op, "()")) {
            return null;
        }

        if (self.lookup_await_call_override(call_node)) |ov| {
            if (ov.dynamic_quirk_dispatch) {
                return null;
            }

            var receiver_expr: ?*ast.Node = null;
            if (ov.has_receiver) {
                const call = call_node.node_variant.?.exp;
                const callee = call.left orelse return null;
                if (callee.*.type != .Expression or callee.*.node_variant == null or !mem.eql(u8, callee.*.node_variant.?.exp.op, ".")) {
                    return null;
                }
                receiver_expr = callee.*.node_variant.?.exp.left;
                if (receiver_expr == null) return null;
            }

            return .{
                .callee_name = self.allocator.dupe(u8, ov.callee_name) catch {
                    return TranspileError.MemoryAllocationFailed;
                },
                .receiver_expr = receiver_expr,
                .receiver_pass_by_ref = ov.receiver_pass_by_ref,
            };
        }

        if (self.lookup_generic_call_override(call_node)) |ov| {
            return .{
                .callee_name = self.allocator.dupe(u8, ov) catch {
                    return TranspileError.MemoryAllocationFailed;
                },
            };
        }

        const call = call_node.node_variant.?.exp;
        const callee = call.left orelse return null;

        if (callee.*.type == .Identifier and callee.*.data != null) {
            return .{
                .callee_name = self.allocator.dupe(u8, callee.*.data.?.sval.items) catch {
                    return TranspileError.MemoryAllocationFailed;
                },
            };
        }

        if (callee.*.type == .Expression and callee.*.node_variant != null and mem.eql(u8, callee.*.node_variant.?.exp.op, ".")) {
            const dot = callee.*.node_variant.?.exp;
            const left = dot.left orelse return null;
            const right = dot.right orelse return null;
            if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                const left_name = left.*.data.?.sval.items;
                const right_name = right.*.data.?.sval.items;

                if (try self.resolve_alias_qualified_symbol_name(&call_node, left_name, right_name)) |qualified| {
                    return .{ .callee_name = qualified };
                }

                if (self.identifier_is_quirk_typed(left_name)) {
                    return null;
                }

                const recv_dt = self.identifier_declared_dtype(left_name) orelse return null;
                if (recv_dt.type != .Unknown or self.is_quirk_name(recv_dt.type_str.items)) {
                    return null;
                }
                if (recv_dt.pointer_depth != 0 and recv_dt.pointer_depth != 1) {
                    return null;
                }

                var type_name: []const u8 = recv_dt.type_str.items;
                var owned_type_name = false;
                if (recv_dt.generic_args != null) {
                    type_name = try self.type_name_mangled_for_emit(recv_dt);
                    owned_type_name = true;
                }
                defer if (owned_type_name) self.allocator.free(@constCast(type_name));

                const type_name_canon = self.canonical_compound_name(type_name);

                if (self.lookup_plain_impl_method_fn(&call_node, type_name_canon, right_name)) |fn_name| {
                    return .{
                        .callee_name = self.allocator.dupe(u8, fn_name) catch {
                            return TranspileError.MemoryAllocationFailed;
                        },
                        .receiver_expr = left,
                        .receiver_pass_by_ref = recv_dt.pointer_depth == 0,
                    };
                }

                const qres = self.resolve_quirk_impl_method_for_concrete(call_node, type_name_canon, right_name);
                if (!qres.ambiguous) {
                    if (qres.fn_name) |qfn_name| {
                        return .{
                            .callee_name = self.allocator.dupe(u8, qfn_name) catch {
                                return TranspileError.MemoryAllocationFailed;
                            },
                            .receiver_expr = left,
                            .receiver_pass_by_ref = recv_dt.pointer_depth == 0,
                        };
                    }
                }
            }
        }

        return null;
    }

    /// Best-effort compile-time fold of an integer-constant expression to its
    /// value. Returns null when the expression is not a pure integer constant
    /// (an identifier, call, dec literal, …) or when a sub-expression divides by
    /// zero (so we never fold *past* an undefined operation — the caller diagnoses
    /// the outermost `/0`/`%0`). Used only to reject constant division by zero at
    /// compile time; it intentionally handles just the operators that produce an
    /// integer: literals, parens, unary `+`/`-`, and `+ - * / %`.
    fn const_fold_int(self: *Self, node: ast.Node) ?i64 {
        switch (node.type) {
            .Number => {
                const d = node.data orelse return null;
                return switch (d) {
                    .llnum => |n| n,
                    else => null, // dec literal etc. — not an integer constant
                };
            },
            .ExpressionParenthesis => {
                const p = node.node_variant orelse return null;
                return self.const_fold_int(p.paren.exp.*);
            },
            .Unary => {
                const u = node.node_variant orelse return null;
                if (u.unary.indirection != null) return null;
                const v = self.const_fold_int(u.unary.operand.*) orelse return null;
                if (mem.eql(u8, u.unary.op, "-")) return -%v;
                if (mem.eql(u8, u.unary.op, "+")) return v;
                return null;
            },
            .Expression => {
                const e = node.node_variant orelse return null;
                const exp = e.exp;
                const left = exp.left orelse return null;
                const right = exp.right orelse return null;
                const l = self.const_fold_int(left.*) orelse return null;
                const r = self.const_fold_int(right.*) orelse return null;
                if (mem.eql(u8, exp.op, "+")) return l +% r;
                if (mem.eql(u8, exp.op, "-")) return l -% r;
                if (mem.eql(u8, exp.op, "*")) return l *% r;
                if (mem.eql(u8, exp.op, "/")) {
                    if (r == 0) return null; // don't fold past a div-by-zero
                    if (l == std.math.minInt(i64) and r == -1) return null; // overflow
                    return @divTrunc(l, r);
                }
                if (mem.eql(u8, exp.op, "%")) {
                    if (r == 0) return null;
                    if (l == std.math.minInt(i64) and r == -1) return null;
                    return @rem(l, r);
                }
                return null;
            },
            else => return null,
        }
    }

    /// Advisory static check: when a variable is declared with an arbitrary-width
    /// integer type (`uN`/`iN`) and initialized from a compile-time integer
    /// constant, warn if the value cannot be represented in that width — a value
    /// too large for the width, or a negative value assigned to an unsigned type.
    /// Only fires for constants the const-folder can resolve; anything dynamic is
    /// left alone (zero false positives). Emitted as a warning (like unused_*),
    /// gated on `flags.emit_unused_warnings`, and honors `allow`/`expect`.
    fn check_int_literal_range(self: *Self, decl_type: *const dtype.DataType, val: *const ast.Node, node: ast.Node) void {
        if (!self.flags.emit_unused_warnings) return;
        const dyn = utils.parse_dynamic_int_datatype(decl_type.type_str.items) orelse return;
        // A pointer/array of the int type is not a scalar literal target.
        if (decl_type.pointer_depth != 0) return;
        if (decl_type.flags != null and decl_type.flags.?.is_array) return;
        const value = self.const_fold_int(val.*) orelse return;

        // Compute the representable range in i128 to avoid overflow at the edges
        // (u64/i64 bounds don't fit in i64/u64 respectively).
        if (dyn.bits == 0 or dyn.bits > 128) return;
        if (!dyn.is_signed and value < 0) {
            self.report_warning(.integer_literal_out_of_range, node, "negative literal {d} assigned to unsigned type 'u{d}'", .{ value, dyn.bits });
            return;
        }
        const v128: i128 = value;
        if (dyn.is_signed) {
            const lo: i128 = -(@as(i128, 1) << @intCast(dyn.bits - 1));
            const hi: i128 = (@as(i128, 1) << @intCast(dyn.bits - 1)) - 1;
            if (v128 < lo or v128 > hi) {
                self.report_warning(.integer_literal_out_of_range, node, "literal {d} out of range for 'i{d}' (valid {d}..{d})", .{ value, dyn.bits, lo, hi });
            }
        } else {
            const hi: i128 = (@as(i128, 1) << @intCast(dyn.bits)) - 1;
            if (v128 > hi) {
                self.report_warning(.integer_literal_out_of_range, node, "literal {d} out of range for 'u{d}' (valid 0..{d})", .{ value, dyn.bits, hi });
            }
        }
    }

    /// Reports a type error when `left` (an assignment's own target) is a
    /// bare identifier resolving to a `const`-declared binding — `const`'s
    /// whole point is that its own binding is never reassignable after its
    /// one (required) initializer. Looked up via `env` (the SAME `TypeEnv`
    /// walk `infer_expr_type` itself uses for a plain identifier, see
    /// `TypeEnv.get_decl_node`) rather than `self.get_scope_entity` — the
    /// latter reflects PARSE-time scope, not the typecheck-time scope this
    /// runs under, and a local's own parse-time scope entity is long gone by
    /// the time a function body is typechecked. `node` is the whole
    /// assignment expression, used only for the diagnostic's own position.
    /// Deliberately narrow: only a DIRECT `name = ...` target is checked
    /// here, not a field/index/dereference through one (`p.x = 5;` where `p`
    /// is const, e.g.) — enforcing const-ness through an arbitrary chain
    /// would need tracking it on every intermediate type, not just the leaf
    /// binding.
    fn check_const_reassignment(self: *Self, node: ast.Node, left: *ast.Node, env: *TypeEnv) TranspileError!void {
        if (left.*.type != .Identifier or left.*.data == null) return;
        const name = left.*.data.?.sval.items;
        const decl = env.get_decl_node(name) orelse self.find_global_variable_node(name) orelse return;
        if (decl.type != .Variable or decl.node_variant == null) return;
        if (decl.node_variant.?.variable.is_const) {
            self.report_type_error(node, "cannot assign to const '{s}'", .{name});
            return TranspileError.TypeMismatch;
        }
    }

    fn infer_expr_type(self: *Self, node: ast.Node, env: *TypeEnv, fns: *const std.StringHashMap(FnSig)) TranspileError!CheckedType {
        if (self.recursion_depth >= max_expr_recursion_depth) {
            self.report_type_error(node, "expression nests too deeply for the compiler to analyze (limit {d})", .{max_expr_recursion_depth});
            return TranspileError.ExpressionTooDeep;
        }
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;
        switch (node.type) {
            .CompoundInit => {
                const ci = node.node_variant.?.compound_init;
                if (ci.dtype == null) {
                    return .{ .base = .Unknown };
                }
                try self.validate_compound_init(node, ci.dtype.?, env, fns);
                return try self.type_from_dtype_with_mangled(ci.dtype.?);
            },
            .Bracket => {
                // Array literal: `[a, b, c]`. The parser stores elements under `bracket.inner`.
                var elems = ArrayList(*ast.Node).init(self.allocator);
                defer elems.deinit();
                try self.flatten_call_args_ptr(node.node_variant.?.bracket.inner, &elems);

                var elem_type: ?CheckedType = null;
                for (elems.items) |elem_node| {
                    const t = try self.infer_expr_type(elem_node.*, env, fns);
                    if (elem_type == null) {
                        elem_type = t;
                        continue;
                    }
                    if (!CheckedType.eql(t, elem_type.?)) {
                        self.report_type_error(node, "array literal elements must share a type", .{});
                        return TranspileError.TypeMismatch;
                    }
                }

                var out: CheckedType = .{
                    .base = if (elem_type) |et| et.base else .Unknown,
                    .is_array = true,
                    .array_depth = if (elem_type) |et| et.array_depth + 1 else 1,
                    .pointer_depth = 0,
                };
                if (elem_type) |et| {
                    out.name = et.name;
                    out.mangled_name = et.mangled_name;
                    out.dtype_ref = et.dtype_ref;
                }
                return out;
            },
            .Number => {
                if (node.data) |d| {
                    return switch (d) {
                        .dnum => .{ .base = .Dec },
                        .llnum => |n| .{ .base = .Num, .is_null_literal = (n == 0) },
                        else => .{ .base = .Num },
                    };
                }
                return .{ .base = .Num };
            },
            .String => return .{ .base = .Str },
            .Boolean => return .{ .base = .Bin },
            // `nil` types exactly like the `NULL` identifier: a null-pointer/string
            // sentinel. The is_null_literal flag drives the existing coercions to
            // pointer and str (and == comparisons against them).
            .Nil => return .{ .base = .Num, .is_null_literal = true },
            // `panic("msg")` never actually produces a value (prints the message
            // and aborts); the is_panic_literal flag makes `can_implicit_coerce`
            // accept it in place of ANY expected type, so it composes with a
            // `ret`/`let`/fit-arm/argument position regardless of that position's
            // real type. `.Unknown` base is a placeholder -- callers must check
            // `is_panic_literal` before relying on `base` for a panic value.
            .Panic => {
                if (node.node_variant) |nv| {
                    const mt = try self.infer_expr_type(nv.panic_expr.message.*, env, fns);
                    if (mt.base != .Str) {
                        self.report_type_error(node, "panic message must be str", .{});
                        return TranspileError.TypeMismatch;
                    }
                }
                return .{ .base = .Unknown, .is_panic_literal = true };
            },
            .Character => return .{ .base = .Chr },
            .Identifier => {
                if (node.data == null) return .{ .base = .Unknown };
                const name = node.data.?.sval.items;
                if (env.get(name)) |t| return t;
                // Allow function symbols as callback values.
                if (fns.get(name) != null) {
                    if (self.find_function_node(name)) |fn_node| {
                        self.mark_function_node_used_and_sync_import(fn_node);
                        if (!self.can_access(&node, fn_node)) {
                            self.report_type_error(node, "function '{s}' is private", .{name});
                            return TranspileError.SymbolNotDefined;
                        }
                    }
                    return .{ .base = .Raw, .pointer_depth = 1 };
                }

                // Best-effort typing for common C macro constants.
                // - `NULL` behaves like a C null pointer constant.
                // - Common numeric macros (limits/stdio/stdlib/time) behave like integers.
                //
                // Each recognized name is also associated with the `std.c.*` module
                // that documents it (see `c_builtin_owner_module`), and that import
                // is marked used here. These C-binding modules are signature-only
                // doc files that declare no Fun symbols, so without this they would
                // always be reported as unused even when their constants are used.
                if (c_builtin_owner_module(name)) |owner| {
                    self.mark_import_used_by_path(owner);
                    if (mem.eql(u8, name, "NULL")) {
                        return .{ .base = .Num, .is_null_literal = true };
                    }
                    return .{ .base = .Num };
                }

                return .{ .base = .Unknown };
            },
            .ExpressionParenthesis => {
                return try self.infer_expr_type(node.node_variant.?.paren.exp.*, env, fns);
            },
            .Unary => {
                const u = node.node_variant.?.unary;

                if (mem.eql(u8, u.op, "await")) {
                    if (!self.current_fn_is_async) {
                        self.report_type_error(node, "await is only allowed inside async functions", .{});
                        return TranspileError.TypeMismatch;
                    }

                    const operand = u.operand.*;
                    if (operand.type != .Expression or operand.node_variant == null or !mem.eql(u8, operand.node_variant.?.exp.op, "()")) {
                        self.report_type_error(node, "await expects a function call", .{});
                        return TranspileError.TypeMismatch;
                    }

                    const prev = self.in_await_operand_inference;
                    const prev_target = self.await_operand_target_pos;
                    self.in_await_operand_inference = true;
                    self.await_operand_target_pos = operand.pos;
                    defer {
                        self.in_await_operand_inference = prev;
                        self.await_operand_target_pos = prev_target;
                    }

                    return try self.infer_expr_type(operand, env, fns);
                }

                const operand_t = try self.infer_expr_type(u.operand.*, env, fns);

                // Indirection unary: `*x`, `**x`, ...
                if (u.indirection) |ind| {
                    if (operand_t.pointer_depth < ind.depth) {
                        self.report_type_error(node, "cannot dereference a non-pointer", .{});
                        return TranspileError.TypeMismatch;
                    }
                    var out = operand_t;
                    out.pointer_depth -= ind.depth;
                    return out;
                }

                // Address-of: `&x`
                if (mem.eql(u8, u.op, "&")) {
                    var out = operand_t;
                    out.pointer_depth += 1;
                    return out;
                }

                if (mem.eql(u8, u.op, "!")) {
                    if (operand_t.base != .Bin) {
                        self.report_type_error(node, "unary '!' expects bin operand", .{});
                        return TranspileError.TypeMismatch;
                    }
                    return .{ .base = .Bin };
                }
                // A type param (e.g. T) is unknown but may be constrained to numeric
                // types; allow it here too so a constrained generic body (e.g.
                // `fun abs<T: num | dec>(T x) T { ret -x; }`) typechecks at the
                // template pass, mirroring the binary-operator allowance below.
                const operand_is_num_or_param = operand_t.base == .Num or operand_t.base == .Dec or
                    (operand_t.base == .Unknown and operand_t.name != null and env.has_type_param(operand_t.name.?));
                if (mem.eql(u8, u.op, "-") or mem.eql(u8, u.op, "+")) {
                    if (!operand_is_num_or_param) {
                        self.report_type_error(node, "unary '{s}' expects num/dec operand", .{u.op});
                        return TranspileError.TypeMismatch;
                    }
                    return operand_t;
                }
                if (mem.eql(u8, u.op, "++") or mem.eql(u8, u.op, "--")) {
                    if (!operand_is_num_or_param) {
                        self.report_type_error(node, "unary '{s}' expects num/dec operand", .{u.op});
                        return TranspileError.TypeMismatch;
                    }
                    return operand_t;
                }
                return operand_t;
            },
            .Tenary => {
                const t = node.node_variant.?.tenary;
                const cond_t = try self.infer_expr_type(t.condition.*, env, fns);
                if (cond_t.base != .Bin) {
                    self.report_type_error(node, "tenary condition must be bin", .{});
                    return TranspileError.InvalidConditionType;
                }
                const a = try self.infer_expr_type(t.true.*, env, fns);
                const b = try self.infer_expr_type(t.false.*, env, fns);
                if (CheckedType.eql(a, b)) return a;
                if (self.is_numeric_type(a) and self.is_numeric_type(b)) {
                    return .{ .base = promote_numeric_type(a, b) };
                }
                self.report_type_error(node, "tenary branches must have the same type", .{});
                return TranspileError.TypeMismatch;
            },
            .Expression => {
                const exp = node.node_variant.?.exp;
                const op = exp.op;

                if (mem.eql(u8, op, "()")) {
                    const callee = exp.left orelse {
                        self.report_type_error(node, "invalid call expression", .{});
                        return TranspileError.NotCallable;
                    };

                    var args_nodes = ArrayList(*ast.Node).init(self.allocator);
                    defer args_nodes.deinit();
                    if (exp.right) |right| {
                        try self.flatten_call_args_ptr(right, &args_nodes);
                    }

                    // Data-carrying enum construction: `EnumName.Variant(args...)`
                    // (or shorthand `.Variant(args...)` once resolved). Recognize it
                    // before the function-call machinery so it isn't mistaken for a
                    // method/free call. Returns a value of the enum type.
                    if (try self.infer_enum_variant_construction(node, callee, args_nodes.items, env, fns)) |ct| {
                        return ct;
                    }

                    // Standard function call: `foo(...)`.
                    var maybe_sig: ?FnSig = null;
                    var call_rtype: CheckedType = .{ .base = .Unknown };
                    var method_sig: ?ast.QuirkMethodSig = null;
                    var plain_method_sig: ?FnSig = null;
                    var plain_method_name: ?[]const u8 = null;
                    var skip_signature_typecheck: bool = false;
                    var handled_generic_call: bool = false;
                    var callee_name: ?[]const u8 = null;
                    var callee_is_async: bool = false;
                    var callee_async_known: bool = false;
                    var await_lowering_callee: ?[]const u8 = null;
                    var await_lowering_has_receiver: bool = false;
                    var await_lowering_receiver_by_ref: bool = false;
                    var await_lowering_dynamic_quirk_dispatch: bool = false;

                    if (callee.type == .Identifier and callee.data != null) {
                        const fname = callee.data.?.sval.items;
                        callee_name = fname;

                        if (self.in_await_operand_inference and
                            (mem.eql(u8, fname, "sizeof") or
                                mem.eql(u8, fname, "va_start") or
                                mem.eql(u8, fname, "va_end") or
                                mem.eql(u8, fname, "va_copy") or
                                mem.eql(u8, fname, "va_arg_num") or
                                mem.eql(u8, fname, "va_arg_dec") or
                                mem.eql(u8, fname, "va_arg_bin") or
                                mem.eql(u8, fname, "va_arg_chr") or
                                mem.eql(u8, fname, "va_arg_str") or
                                mem.eql(u8, fname, "va_arg_raw")))
                        {
                            self.report_type_error(node, "await target '{s}' is not async", .{fname});
                            return TranspileError.TypeMismatch;
                        }

                        if (mem.eql(u8, fname, "va_start")) {
                            if (args_nodes.items.len != 2) {
                                self.report_type_error(node, "va_start expects 2 arguments", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Void };
                        }
                        if (mem.eql(u8, fname, "va_end")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_end expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Void };
                        }
                        if (mem.eql(u8, fname, "va_copy")) {
                            if (args_nodes.items.len != 2) {
                                self.report_type_error(node, "va_copy expects 2 arguments", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Void };
                        }
                        if (mem.eql(u8, fname, "va_arg_num")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_arg_num expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Num };
                        }
                        if (mem.eql(u8, fname, "va_arg_dec")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_arg_dec expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Dec };
                        }
                        if (mem.eql(u8, fname, "va_arg_bin")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_arg_bin expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Bin };
                        }
                        if (mem.eql(u8, fname, "va_arg_chr")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_arg_chr expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Chr };
                        }
                        if (mem.eql(u8, fname, "va_arg_str")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_arg_str expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Str };
                        }
                        if (mem.eql(u8, fname, "va_arg_raw")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "va_arg_raw expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            return .{ .base = .Raw, .pointer_depth = 1 };
                        }

                        // Type-aware map/set key intrinsics (used by the stdlib).
                        // `__fun_key_eq(a, b) -> bin`, `__fun_key_hash(a) -> num`.
                        // Validate the argument expressions but accept any key type.
                        if (mem.eql(u8, fname, "__fun_key_eq")) {
                            if (args_nodes.items.len != 2) {
                                self.report_type_error(node, "__fun_key_eq expects 2 arguments", .{});
                                return TranspileError.WrongArgCount;
                            }
                            _ = try self.infer_expr_type(args_nodes.items[0].*, env, fns);
                            _ = try self.infer_expr_type(args_nodes.items[1].*, env, fns);
                            return .{ .base = .Bin };
                        }
                        if (mem.eql(u8, fname, "__fun_key_hash")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "__fun_key_hash expects 1 argument", .{});
                                return TranspileError.WrongArgCount;
                            }
                            _ = try self.infer_expr_type(args_nodes.items[0].*, env, fns);
                            return .{ .base = .Num };
                        }

                        // Builtin: `sizeof(Type)`.
                        if (mem.eql(u8, fname, "sizeof")) {
                            if (args_nodes.items.len != 1) {
                                self.report_type_error(node, "sizeof expects exactly 1 argument", .{});
                                return TranspileError.InvalidSizeof;
                            }
                            const arg0 = args_nodes.items[0].*;
                            if (arg0.type != .Identifier or arg0.data == null) {
                                self.report_type_error(node, "sizeof argument must be a type name", .{});
                                return TranspileError.InvalidSizeof;
                            }

                            const type_name = arg0.data.?.sval.items;
                            // A pointer-typed operand (`sizeof(num*)`) carries a trailing
                            // `*` suffix from the parser; strip it for the type checks
                            // (the size is the same regardless of pointee type).
                            var type_base = type_name;
                            while (type_base.len > 0 and type_base[type_base.len - 1] == '*') {
                                type_base = type_base[0 .. type_base.len - 1];
                            }
                            // For a generic type operand the parser produces a mangled
                            // name like `Box__num`; the base type for the declared-check
                            // is the segment before the first `__`.
                            const base_name = if (mem.indexOf(u8, type_base, "__")) |i| type_base[0..i] else type_base;
                            const is_builtin = utils.keyword_is_datatype(type_base);

                            const is_declared = blk: {
                                const root = self.get_root();
                                if (root.type_registry == null) break :blk false;
                                const reg = &root.type_registry.?;
                                if (reg.enums_by_name.contains(base_name)) break :blk true;
                                if (reg.compounds_by_name.contains(base_name)) break :blk true;
                                if (reg.quirk_sig_by_name.contains(base_name)) break :blk true;
                                break :blk false;
                            };

                            const is_type_param = env.has_type_param(type_base);

                            // `sizeof(v)` where `v` is a value in scope: accept it (codegen
                            // resolves it to the C type of its declared dtype). During
                            // typecheck the scope isn't populated, so consult the TypeEnv.
                            // (Only the bare, non-pointer name can be a scope value.)
                            const is_scope_value = !is_builtin and !is_declared and !is_type_param and env.get(type_name) != null;

                            if (!is_builtin and !is_declared and !is_type_param and !is_scope_value) {
                                self.report_type_error(node, "sizeof unknown type '{s}'", .{type_name});
                                return TranspileError.InvalidSizeof;
                            }

                            // A bound generic type parameter (`sizeof(E)` inside
                            // `impl Result<T, E> { ... }`) must NEVER go through the
                            // global-visibility check below, even when `is_declared`
                            // also happens to be true -- `is_declared` only means
                            // SOME enum/compound/quirk ANYWHERE in the whole compiled
                            // program shares this bare name (e.g. an unrelated file's
                            // own top-level `enum E { ... }`), which has nothing to do
                            // with the CURRENT generic parameter. Without this
                            // exclusion, `ensure_named_type_visible` checked
                            // visibility against that unrelated global symbol and
                            // could spuriously fail with "type 'E' is private" even
                            // though nothing private was actually being referenced.
                            if (is_declared and !is_scope_value and !is_type_param) {
                                try self.ensure_named_type_visible(node, base_name);
                                // Register the generic instantiation so its struct is emitted.
                                if (mem.indexOf(u8, type_name, "__") != null) {
                                    if (try self.dtype_from_mangled_type(type_name)) |dt| {
                                        try self.register_generic_instantiations_from_dtype(dt);
                                    }
                                }
                            }

                            return .{ .base = .Num };
                        }

                        // Calling a function-TYPED local/parameter (`fun(T1, T2) R
                        // cb`), e.g. inside `sort_by`'s comparator body. A local of
                        // this shape shadows any same-named top-level function,
                        // matching ordinary scoping.
                        const fn_param_sig: ?FnSig = blk_fn_param_call: {
                            const vt = env.get(fname) orelse break :blk_fn_param_call null;
                            const dref = vt.dtype_ref orelse break :blk_fn_param_call null;
                            const fsig = dref.fn_sig orelse break :blk_fn_param_call null;
                            break :blk_fn_param_call try self.fn_sig_from_dtype_fn_sig(fsig);
                        };
                        if (fn_param_sig) |sig| {
                            maybe_sig = sig;
                            call_rtype = sig.rtype;
                        } else if (fns.get(fname)) |sig| {
                            maybe_sig = sig;
                            call_rtype = sig.rtype;
                            callee_is_async = sig.is_async;
                            callee_async_known = true;
                            await_lowering_callee = fname;
                            if (self.find_function_node(fname)) |fn_node| {
                                self.mark_function_node_used_and_sync_import(fn_node);
                                if (!self.can_access(&node, fn_node)) {
                                    self.report_type_error(node, "function '{s}' is private", .{fname});
                                    return TranspileError.SymbolNotDefined;
                                }
                            }
                        } else {
                            // If the name is known from preloaded imports/stdlib signatures, treat it
                            // as an external function and skip type checking.
                            // Otherwise, this is a real semantic error (we don't want to defer to C).
                            if (self.global_symbols.get(fname)) |g| {
                                if (!mem.eql(u8, g.file_path, self.input_file_path)) {
                                    self.mark_import_used_by_origin_file(g.file_path);
                                }
                                skip_signature_typecheck = true;
                                call_rtype = .{ .base = .Unknown };
                            } else if (is_known_extern_function_name(fname)) {
                                skip_signature_typecheck = true;
                                call_rtype = .{ .base = .Unknown };
                            }

                            if (!skip_signature_typecheck) {
                                self.report_type_error(node, "unknown function '{s}'", .{fname});
                                return TranspileError.SymbolNotDefined;
                            }
                        }
                    } else if (callee.type == .Expression and callee.node_variant != null and mem.eql(u8, callee.node_variant.?.exp.op, ".")) {
                        // Method call: `x.method(...)`.
                        const dot = callee.node_variant.?.exp;
                        const recv = dot.left orelse {
                            self.report_type_error(node, "invalid method call", .{});
                            return TranspileError.NotCallable;
                        };
                        const member = dot.right orelse {
                            self.report_type_error(node, "invalid method call", .{});
                            return TranspileError.NotCallable;
                        };
                        if (member.type != .Identifier or member.data == null) {
                            self.report_type_error(node, "invalid method call", .{});
                            return TranspileError.NotCallable;
                        }

                        // Aliased call to a GENERIC function (`alias.genfn(args)`):
                        // must be routed through the generic-call inference below so it
                        // is monomorphized and a call override is registered. Without
                        // this it fell into the plain alias path and emitted an
                        // undeclared `alias__genfn` (the generic was never instantiated).
                        // The alias only qualifies which module the function lives in;
                        // monomorphization keys off the base name.
                        const alias_generic_fn = blk: {
                            if (recv.type != .Identifier or recv.data == null) break :blk false;
                            const alias_map = self.alias_map_for_node(&node);
                            if (!alias_map.contains(recv.data.?.sval.items)) break :blk false;
                            const fnode = self.find_function_node(member.data.?.sval.items) orelse break :blk false;
                            if (fnode.node_variant == null) break :blk false;
                            break :blk fnode.node_variant.?.function.type_params != null;
                        };
                        if (alias_generic_fn) {
                            // Fall through to the generic-call inference with the bare
                            // (base) function name as the callee.
                            callee_name = member.data.?.sval.items;
                        } else
                        // Module alias call: `alias.fn(...)`.
                        if (recv.type == .Identifier and recv.data != null) {
                            const alias_name = recv.data.?.sval.items;
                            const member_name = member.data.?.sval.items;
                            callee_name = member_name;
                            if (try self.resolve_alias_qualified_symbol_name(&node, alias_name, member_name)) |qualified| {
                                defer self.allocator.free(qualified);

                                // Enforce visibility across the alias: a private
                                // (non-`pub`) function in the aliased module must not
                                // be callable as `alias.fn(...)`. The alias always
                                // points at a different module, so `same_module` is
                                // false and access reduces to "is the target public".
                                // Only user functions resolve via `find_function_node`;
                                // std/extern symbols return null and are unaffected.
                                // We reject only when EVERY same-named function in the
                                // program is inaccessible — if any public same-named fn
                                // exists, the alias plausibly resolves to it, so we
                                // don't false-positive on a name collision.
                                if (self.find_function_node(member_name) != null and
                                    !self.any_accessible_function_named(&node, member_name))
                                {
                                    self.report_type_error(node, "function '{s}' is private to its module and cannot be called through alias '{s}'", .{ member_name, alias_name });
                                    return TranspileError.SymbolNotDefined;
                                }

                                // For a std.c.* binding, `qualified` is the bare libc
                                // name (e.g. `log`), which can collide in `fns` with an
                                // unrelated stdlib function of the same name. Prefer the
                                // alias-qualified sig (`cmath__log`) registered by
                                // collect_fn_sigs so we read the C binding's real return
                                // type, not the collider's.
                                var c_binding_sig: ?FnSig = null;
                                if (self.alias_is_c_binding(&node, alias_name)) {
                                    const c_key = try self.make_alias_qualified_symbol_name(alias_name, member_name);
                                    defer self.allocator.free(c_key);
                                    if (fns.get(c_key)) |csig| c_binding_sig = csig;
                                }

                                if (c_binding_sig) |sig| {
                                    maybe_sig = sig;
                                    call_rtype = sig.rtype;
                                    callee_is_async = sig.is_async;
                                    callee_async_known = true;
                                } else if (fns.get(qualified)) |sig| {
                                    maybe_sig = sig;
                                    call_rtype = sig.rtype;
                                    callee_is_async = sig.is_async;
                                    callee_async_known = true;
                                } else if (self.global_symbols.get(qualified)) |g| {
                                    if (!mem.eql(u8, g.file_path, self.input_file_path)) {
                                        self.mark_import_used_by_origin_file(g.file_path);
                                    }
                                    skip_signature_typecheck = true;
                                    call_rtype = .{ .base = .Unknown };
                                    callee_async_known = false;
                                } else if (is_known_extern_function_name(qualified)) {
                                    skip_signature_typecheck = true;
                                    call_rtype = .{ .base = .Unknown };
                                    callee_async_known = false;
                                } else {
                                    self.report_type_error(node, "unknown function '{s}.{s}'", .{ alias_name, member_name });
                                    return TranspileError.SymbolNotDefined;
                                }

                                for (args_nodes.items) |arg_node| {
                                    _ = try self.infer_expr_type(arg_node.*, env, fns);
                                }
                                try self.validate_async_call_usage(node, callee_name, callee_is_async, callee_async_known);
                                return call_rtype;
                            }
                        }

                        // Skip the method-on-value path for an aliased generic call;
                        // it falls through to the generic-call inference below.
                        if (!alias_generic_fn) {
                            const recv_t = try self.infer_expr_type(recv.*, env, fns);
                            const mname = member.data.?.sval.items;
                            callee_name = mname;
                            if (!is_user_named_type(recv_t)) {
                                self.report_type_error(node, "method calls require a named receiver", .{});
                                return TranspileError.NotCallable;
                            }

                            if (recv_t.dtype_ref) |dt| {
                                if (dt.generic_args != null) {
                                    try self.register_generic_instantiation(dt);
                                }
                            } else if (self.lookup_receiver_dtype(recv.*)) |dt| {
                                if (dt.generic_args != null) {
                                    try self.register_generic_instantiation(dt);
                                }
                            }

                            const recv_name = try self.concrete_type_name(recv.*, recv_t) orelse {
                                self.report_type_error(node, "method calls require a named receiver", .{});
                                return TranspileError.NotCallable;
                            };
                            const recv_name_owned = if (self.lookup_receiver_dtype(recv.*)) |dt| dt.generic_args != null else false;
                            const recv_name_canon = self.canonical_compound_name(recv_name);

                            if (mem.indexOf(u8, recv_name, "__") != null) {
                                if (try self.dtype_from_mangled_type(recv_name)) |recv_dt_mangled| {
                                    try self.register_generic_instantiations_from_dtype(recv_dt_mangled);
                                }
                            }

                            // If the receiver is a quirk type, typecheck against the quirk signature.
                            // Otherwise, treat as a plain impl method call and typecheck against the
                            // generated `Type__method` function signature.
                            const reg = self.root_registry();
                            const recv_is_quirk = if (reg) |r| r.quirk_sig_by_name.contains(recv_name) else false;

                            // A method may declare its OWN type parameter(s) in addition to
                            // the impl's (`impl Box<T> { pub map<U>(U x) U { ... } }`).
                            // Detect and handle this BEFORE the ordinary dispatch below,
                            // which assumes every param type is already concrete -- combines
                            // the receiver's already-known impl-level type args (if any) with
                            // ones inferred from THIS call's arguments for the method's own
                            // params, then reuses the SAME `generic_fn_instantiations`
                            // machinery a generic free function's call site uses (register +
                            // call-site override), since emission never cares whether
                            // `fn_node` is a free function or a method's own node.
                            var handled_generic_method_call = false;
                            if (!recv_is_quirk) {
                                const recv_base = if (mem.indexOf(u8, recv_name_canon, "__")) |idx| recv_name_canon[0..idx] else recv_name_canon;
                                if (self.find_plain_impl_method_node(recv_base, mname)) |hit| {
                                    const mfnv = hit.method_node.node_variant.?.function;
                                    if (mfnv.type_params) |method_params_val| {
                                        const method_params_ptr: *const utils.Vector(ArrayList(u8)) = &method_params_val;

                                        const impl_params = self.impl_type_params(hit.impl_node);
                                        const recv_dt_for_impl = if (recv_t.dtype_ref) |dt| dt else self.lookup_receiver_dtype(recv.*) orelse null;
                                        const impl_args: []*dtype.DataType = blk: {
                                            const dt = recv_dt_for_impl orelse break :blk &[_]*dtype.DataType{};
                                            const ga = dt.generic_args orelse break :blk &[_]*dtype.DataType{};
                                            break :blk ga.items();
                                        };

                                        const margs_items = if (mfnv.args) |a| a.items() else &[_]*ast.Node{};
                                        // First declared arg is the implicit `self`; user args start at index 1.
                                        const user_margs = if (margs_items.len > 0) margs_items[1..] else margs_items;

                                        if (args_nodes.items.len != user_margs.len) {
                                            self.report_type_error(node, "method '{s}' expects {d} args, got {d}", .{ mname, user_margs.len, args_nodes.items.len });
                                            return TranspileError.WrongArgCount;
                                        }

                                        var mbindings = std.StringHashMap(*dtype.DataType).init(self.allocator);
                                        defer mbindings.deinit();

                                        for (args_nodes.items, 0..) |arg_node, idx| {
                                            const marg = user_margs[idx];
                                            if (marg.type != .Variable or marg.node_variant == null) continue;
                                            const declared_dt = marg.node_variant.?.variable.type;
                                            // Resolve any reference to the IMPL's own T first, so only
                                            // the method's OWN param(s) remain to solve for.
                                            const declared_dt_impl_resolved: *const dtype.DataType = if (impl_params) |ip|
                                                try self.clone_dtype_with_subst_for_inst(declared_dt, ip, impl_args)
                                            else
                                                declared_dt;

                                            const actual_ct = try self.infer_expr_type(arg_node.*, env, fns);
                                            const actual_dt = (try self.checked_type_to_dtype(actual_ct)) orelse {
                                                self.report_type_error(node, "cannot infer generic argument from value", .{});
                                                return TranspileError.TypeMismatch;
                                            };

                                            const ok = try self.bind_generic_param(declared_dt_impl_resolved, actual_dt, method_params_ptr, &mbindings);
                                            if (!ok) {
                                                self.report_type_error(node, "type mismatch in call to method '{s}' argument {d}", .{ mname, idx + 1 });
                                                return TranspileError.TypeMismatch;
                                            }
                                        }

                                        const method_gargs = self.allocator.alloc(*dtype.DataType, method_params_ptr.count) catch {
                                            return TranspileError.MemoryAllocationFailed;
                                        };
                                        var mpi: usize = 0;
                                        for (method_params_ptr.items()) |p| {
                                            if (mbindings.get(p.items)) |dt_ptr| {
                                                method_gargs[mpi] = dt_ptr;
                                            } else {
                                                self.report_type_error(node, "cannot infer generic parameter '{s}' for method '{s}'", .{ p.items, mname });
                                                return TranspileError.TypeMismatch;
                                            }
                                            mpi += 1;
                                        }

                                        if (!impl_allows_generic_args(mfnv.type_param_forced_insts, method_gargs)) {
                                            self.report_type_error(node, "call to method '{s}' violates generic constraint: type argument does not satisfy the declared bound", .{mname});
                                            return TranspileError.TypeMismatch;
                                        }

                                        // Combine impl-level params/args with the method's own, so
                                        // codegen substitution (a linear name lookup) resolves
                                        // references to EITHER scope uniformly. Root-allocated: the
                                        // combined record outlives this call's typecheck.
                                        const root_alloc = self.get_root().allocator;
                                        var combined_params = utils.Vector(ArrayList(u8)).init(root_alloc);
                                        if (impl_params) |ip| {
                                            for (ip.items()) |p| {
                                                var cloned = ArrayList(u8).init(root_alloc);
                                                cloned.appendSlice(p.items) catch return TranspileError.MemoryAllocationFailed;
                                                combined_params.push(cloned) catch return TranspileError.MemoryAllocationFailed;
                                            }
                                        }
                                        for (method_params_ptr.items()) |p| {
                                            var cloned = ArrayList(u8).init(root_alloc);
                                            cloned.appendSlice(p.items) catch return TranspileError.MemoryAllocationFailed;
                                            combined_params.push(cloned) catch return TranspileError.MemoryAllocationFailed;
                                        }
                                        const combined_params_ptr = root_alloc.create(utils.Vector(ArrayList(u8))) catch return TranspileError.MemoryAllocationFailed;
                                        combined_params_ptr.* = combined_params;

                                        const combined_args = root_alloc.alloc(*dtype.DataType, impl_args.len + method_gargs.len) catch return TranspileError.MemoryAllocationFailed;
                                        for (impl_args, 0..) |a, i| combined_args[i] = a;
                                        for (method_gargs, 0..) |a, i| combined_args[impl_args.len + i] = a;

                                        const method_base_name_buf = std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ recv_name_canon, mname }) catch return TranspileError.MemoryAllocationFailed;
                                        defer self.allocator.free(method_base_name_buf);
                                        const combined_name = try self.mangle_generic_fn_name(method_base_name_buf, method_gargs);

                                        try self.register_generic_fn_instantiation(hit.method_node, combined_params_ptr, combined_args, combined_name, self.typecheck_owner_fn, impl_args.len);

                                        if (node.pos) |p| {
                                            const root = self.get_root();
                                            const key = try self.call_pos_key_alloc(p);
                                            if (!root.generic_call_overrides.contains(key)) {
                                                root.generic_call_overrides.put(key, combined_name) catch return TranspileError.MemoryAllocationFailed;
                                            } else {
                                                self.allocator.free(key);
                                            }
                                        }

                                        if (mfnv.rtype) |rt| {
                                            call_rtype = try self.type_from_dtype_with_subst(&rt, combined_params_ptr.*, combined_args);
                                        } else {
                                            call_rtype = .{ .base = .Void };
                                        }
                                        callee_is_async = mfnv.is_async;
                                        callee_async_known = true;
                                        plain_method_name = mname;
                                        await_lowering_callee = combined_name;

                                        handled_generic_method_call = true;
                                    }
                                }
                            }

                            if (handled_generic_method_call) {
                                // Falls through to the shared post-processing below
                                // (`await_lowering_callee`, async validation, return).
                            } else if (recv_is_quirk) {
                                method_sig = self.lookup_quirk_method(node, recv_name, mname) orelse {
                                    self.report_type_error(node, "quirk '{s}' has no method '{s}'", .{ recv_name, mname });
                                    return TranspileError.NotCallable;
                                };
                                // `lookup_quirk_method` returns a VALUE copy (its
                                // `for (methods) |m| return m;` loop copies the AST's
                                // QuirkMethodSig out), so `method_sig` -- and its
                                // embedded `.rtype: DataType` -- live on THIS call's own
                                // stack frame. `type_from_dtype` stores whatever pointer
                                // it's given straight into the returned CheckedType's
                                // `dtype_ref`; passing `&method_sig.?.rtype` directly
                                // would leak a pointer that dangles the moment this call
                                // returns -- any later field access on the call's result
                                // (e.g. `c.now().epoch`) then reads freed stack memory.
                                // Copy `.rtype` into a heap slot with the compile's own
                                // lifetime instead (same allocator/pattern as
                                // `dtype_from_mangled_type`'s persistent DataType nodes).
                                const rtype_copy = self.allocator.create(dtype.DataType) catch {
                                    return TranspileError.MemoryAllocationFailed;
                                };
                                rtype_copy.* = method_sig.?.rtype;
                                call_rtype = type_from_dtype(rtype_copy);
                                callee_is_async = method_sig.?.is_async;
                                callee_async_known = true;
                                await_lowering_dynamic_quirk_dispatch = method_sig.?.is_async;
                            } else {
                                if (recv_t.pointer_depth > 1) {
                                    self.report_type_error(node, "method calls support at most one pointer indirection", .{});
                                    return TranspileError.NotCallable;
                                }

                                await_lowering_has_receiver = true;
                                await_lowering_receiver_by_ref = recv_t.pointer_depth == 0;

                                const recv_dt = if (recv_t.dtype_ref) |dt| dt else self.lookup_receiver_dtype(recv.*) orelse null;
                                if (recv_dt != null and recv_dt.?.generic_args != null) {
                                    if (self.synthesize_generic_plain_method_sig(recv_dt.?, recv_name_canon, mname)) |sig| {
                                        plain_method_sig = sig;
                                        plain_method_name = mname;
                                        call_rtype = sig.rtype;
                                        if (self.lookup_plain_impl_method_fn(&node, recv_name_canon, mname)) |fn_name| {
                                            await_lowering_callee = fn_name;
                                        }
                                    }
                                }
                                // The receiver may be a bare MANGLED instance (`Box__str`) with no
                                // generic_args on its scope dtype — typical inside a concrete-typed impl
                                // (`impl Box<str>`) calling a sibling defined on the generic base. Recover
                                // base+args from the mangled name and synthesize the method sig.
                                if (plain_method_sig == null and (recv_dt == null or recv_dt.?.generic_args == null)) {
                                    if (self.synthesize_generic_method_sig_from_mangled(recv_name_canon, mname)) |sig| {
                                        plain_method_sig = sig;
                                        plain_method_name = mname;
                                        call_rtype = sig.rtype;
                                        if (self.lookup_plain_impl_method_fn(&node, recv_name_canon, mname)) |fn_name| {
                                            await_lowering_callee = fn_name;
                                        }
                                    }
                                }

                                if (plain_method_sig == null) {
                                    if (self.lookup_plain_impl_method_fn(&node, recv_name_canon, mname)) |fn_name| {
                                        plain_method_sig = fns.get(fn_name) orelse blk: {
                                            const recv_dt2 = if (recv_t.dtype_ref) |dt| dt else self.lookup_receiver_dtype(recv.*) orelse null;
                                            if (recv_dt2 != null) {
                                                if (self.synthesize_generic_plain_method_sig(recv_dt2.?, recv_name_canon, mname)) |sig| {
                                                    break :blk sig;
                                                }
                                            }
                                            self.report_type_error(node, "type '{s}' has no method '{s}'", .{ recv_name_canon, mname });
                                            return TranspileError.NotCallable;
                                        };
                                        plain_method_name = mname;
                                        call_rtype = plain_method_sig.?.rtype;
                                        await_lowering_callee = fn_name;
                                    }
                                }

                                if (plain_method_sig != null) {
                                    // Resolved via plain impl. If the owning impl is
                                    // constrained (`impl Box<T: num | dec>`), verify the
                                    // concrete receiver satisfies it — else this call
                                    // would reference an un-emitted specialization and
                                    // fail at C link time.
                                    const check_dt: ?*const dtype.DataType = if (recv_t.dtype_ref) |dt| dt else self.lookup_receiver_dtype(recv.*);
                                    try self.check_impl_generic_constraint(node, check_dt, recv_name_canon, mname);
                                } else {
                                    // fallback to alt generic name or quirk impl
                                    // Retry with a mangled generic receiver name if available.
                                    var alt_name: ?[]const u8 = null;
                                    var alt_owned = false;
                                    if (recv_t.dtype_ref) |dt| {
                                        if (dt.generic_args != null) {
                                            alt_name = try self.type_name_mangled(dt);
                                            alt_owned = true;
                                        }
                                    } else if (self.lookup_receiver_dtype(recv.*)) |dt| {
                                        if (dt.generic_args != null) {
                                            alt_name = try self.type_name_mangled(dt);
                                            alt_owned = true;
                                        }
                                    }

                                    if (alt_name) |alt| {
                                        if (self.lookup_plain_impl_method_fn(&node, alt, mname)) |fn_name| {
                                            plain_method_sig = fns.get(fn_name) orelse blk: {
                                                const recv_dt_alt = if (recv_t.dtype_ref) |dt| dt else self.lookup_receiver_dtype(recv.*) orelse null;
                                                if (recv_dt_alt != null) {
                                                    if (self.synthesize_generic_plain_method_sig(recv_dt_alt.?, alt, mname)) |sig| {
                                                        break :blk sig;
                                                    }
                                                }
                                                if (alt_owned) self.allocator.free(@constCast(alt));
                                                self.report_type_error(node, "type '{s}' has no method '{s}'", .{ recv_name_canon, mname });
                                                return TranspileError.NotCallable;
                                            };
                                            plain_method_name = mname;
                                            call_rtype = plain_method_sig.?.rtype;
                                            await_lowering_callee = fn_name;
                                            if (alt_owned) self.allocator.free(@constCast(alt));
                                        } else {
                                            if (alt_owned) self.allocator.free(@constCast(alt));
                                            const qres = self.resolve_quirk_impl_method_for_concrete(node, recv_name_canon, mname);
                                            if (qres.ambiguous) {
                                                self.report_type_error(node, "type '{s}' method '{s}' is ambiguous (quirks: '{s}', '{s}')", .{ recv_t.name.?, mname, qres.quirk_name orelse "<unknown>", qres.other_quirk_name orelse "<unknown>" });
                                                return TranspileError.NotCallable;
                                            }
                                            if (qres.fn_name) |qfn| {
                                                plain_method_sig = fns.get(qfn) orelse {
                                                    self.report_type_error(node, "type '{s}' has no method '{s}'", .{ recv_name_canon, mname });
                                                    return TranspileError.NotCallable;
                                                };
                                                plain_method_name = mname;
                                                call_rtype = plain_method_sig.?.rtype;
                                                await_lowering_callee = qfn;
                                            } else {
                                                self.report_type_error(node, "type '{s}' has no method '{s}'", .{ recv_name_canon, mname });
                                                return TranspileError.NotCallable;
                                            }
                                        }
                                    } else {
                                        // Also allow calling quirk-impl methods directly on concrete types.
                                        // If the type implements exactly one quirk that defines this method name,
                                        // lower/typecheck as a direct call to the generated impl function.
                                        const qres = self.resolve_quirk_impl_method_for_concrete(node, recv_name_canon, mname);
                                        if (qres.ambiguous) {
                                            self.report_type_error(node, "type '{s}' method '{s}' is ambiguous (quirks: '{s}', '{s}')", .{ recv_t.name.?, mname, qres.quirk_name orelse "<unknown>", qres.other_quirk_name orelse "<unknown>" });
                                            return TranspileError.NotCallable;
                                        }
                                        if (qres.fn_name) |qfn| {
                                            plain_method_sig = fns.get(qfn) orelse {
                                                self.report_type_error(node, "type '{s}' has no method '{s}'", .{ recv_name_canon, mname });
                                                return TranspileError.NotCallable;
                                            };
                                            plain_method_name = mname;
                                            call_rtype = plain_method_sig.?.rtype;
                                            await_lowering_callee = qfn;
                                        } else if (self.synthesize_generic_method_sig_from_mangled(recv_name_canon, mname)) |sig| {
                                            // Concrete-typed impl (`impl Box<str>`) calling a sibling method
                                            // defined on the generic base (`impl Box<T>`), where the receiver's
                                            // scope dtype is the bare mangled name. Recover base+args from the
                                            // mangled name and synthesize the generic method's sig.
                                            plain_method_sig = sig;
                                            plain_method_name = mname;
                                            call_rtype = sig.rtype;
                                            if (self.lookup_plain_impl_method_fn(&node, recv_name_canon, mname)) |fn_name| {
                                                await_lowering_callee = fn_name;
                                            }
                                        } else {
                                            self.report_type_error(node, "type '{s}' has no method '{s}'", .{ recv_name_canon, mname });
                                            return TranspileError.NotCallable;
                                        }
                                    }
                                }
                            }

                            if (recv_name_owned) {
                                self.allocator.free(recv_name);
                            }

                            if (plain_method_sig != null) {
                                callee_is_async = plain_method_sig.?.is_async;
                                callee_async_known = true;
                            }
                        } // end if (!alias_generic_fn)
                    } else {
                        self.report_type_error(node, "only calling named functions or quirk methods is supported", .{});
                        return TranspileError.NotCallable;
                    }

                    // Even when skipping signature-based type checking (extern functions), we still
                    // need to semantically validate each argument expression so member access, etc.
                    // errors are not missed.
                    if (skip_signature_typecheck) {
                        for (args_nodes.items) |arg_node| {
                            _ = try self.infer_expr_type(arg_node.*, env, fns);
                        }
                        try self.validate_async_call_usage(node, callee_name, callee_is_async, callee_async_known);
                        return call_rtype;
                    }

                    // Generic function call inference. Only applies to a bare/aliased
                    // function-name call -- a call already resolved as a method
                    // (`plain_method_sig`/`method_sig`) must not be re-resolved against
                    // an unrelated generic free function that happens to share the
                    // method's bare name (`callee_name` is set to the method name too,
                    // purely for diagnostics/async-validation further down).
                    if (callee_name != null and method_sig == null and plain_method_sig == null) {
                        const fn_node = self.find_function_node(callee_name.?) orelse null;
                        if (fn_node != null and fn_node.?.node_variant != null and fn_node.?.node_variant.?.function.type_params != null) {
                            const fnv = &fn_node.?.node_variant.?.function;
                            const params_ptr = blk: {
                                if (fnv.type_params) |*p| break :blk p;
                                self.report_type_error(node, "unknown function '{s}'", .{callee_name.?});
                                return TranspileError.SymbolNotDefined;
                            };

                            // Infer type arguments from call arguments.
                            var bindings = std.StringHashMap(*dtype.DataType).init(self.allocator);
                            defer bindings.deinit();

                            // Explicit generic type arguments (`ok<num, MyErrorKind>(42)`)
                            // pre-seed the bindings map -- needed for a param like `E`
                            // that appears only in the return type, with no argument
                            // value to infer it from. The argument-inference loop below
                            // still runs and, via `bind_generic_param`'s "already bound"
                            // branch, VALIDATES each inferred arg type against these
                            // rather than silently trusting them.
                            if (exp.generic_args) |explicit_gargs| {
                                if (explicit_gargs.count != params_ptr.count) {
                                    self.report_type_error(node, "call to '{s}' provides {d} explicit generic argument(s), expected {d}", .{ callee_name.?, explicit_gargs.count, params_ptr.count });
                                    return TranspileError.TypeMismatch;
                                }
                                for (params_ptr.items(), 0..) |p, gi| {
                                    bindings.put(p.items, explicit_gargs.items()[gi]) catch return TranspileError.MemoryAllocationFailed;
                                }
                            }

                            const expected_items = if (fnv.args) |args| args.items() else &[_]*ast.Node{};
                            const fixed_len = expected_items.len;
                            // Trailing params may carry a default (`fun f<T>(Node<T>* head, bin
                            // with_addr = false)`); omitting them is valid, so the true floor is
                            // the count of LEADING params without one, not the full param list —
                            // mirrors the non-generic call path's use of the same helper.
                            const required_len = if (fnv.args) |args| count_required_args_from_node(args) else 0;

                            if (!fnv.is_variadic and (args_nodes.items.len < required_len or args_nodes.items.len > fixed_len)) {
                                self.report_type_error(node, "function '{s}' expects {d} args, got {d}", .{ callee_name.?, fixed_len, args_nodes.items.len });
                                return TranspileError.WrongArgCount;
                            }
                            if (fnv.is_variadic and args_nodes.items.len < required_len) {
                                self.report_type_error(node, "function '{s}' expects at least {d} args, got {d}", .{ callee_name.?, required_len, args_nodes.items.len });
                                return TranspileError.WrongArgCount;
                            }

                            var idx: usize = 0;
                            while (idx < args_nodes.items.len and idx < fixed_len) : (idx += 1) {
                                const arg_node = args_nodes.items[idx];
                                const expected_node = expected_items[idx];
                                if (expected_node.type != .Variable or expected_node.node_variant == null) continue;
                                const expected_dt = expected_node.node_variant.?.variable.type;

                                // Resolve enum/compound shorthand (`.Io`, `.Some(v)`) against
                                // the DECLARED (unsubstituted) param type before inferring the
                                // arg's type below. For a concrete (non-type-param) param this
                                // is already the real expected type, so the rewrite is safe to
                                // do here in the same pass that binds T from other arguments —
                                // otherwise a concretely-typed param preceding the type-param
                                // one (e.g. `err_kind<T>(ErrorKind kind, ..., T default)`) would
                                // have its shorthand arg inferred with no expected type yet and
                                // fail as a bare field access on a blank receiver.
                                try self.normalize_expr_to_expected_type(arg_node, try self.type_from_dtype_with_mangled(expected_dt), env, fns);

                                const actual_ct = try self.infer_expr_type(arg_node.*, env, fns);
                                const actual_dt = (try self.checked_type_to_dtype(actual_ct)) orelse {
                                    self.report_type_error(node, "cannot infer generic argument from value", .{});
                                    return TranspileError.TypeMismatch;
                                };

                                const ok = try self.bind_generic_param(expected_dt, actual_dt, params_ptr, &bindings);
                                if (!ok) {
                                    self.report_type_error(node, "type mismatch in call to '{s}' argument {d}", .{ callee_name.?, idx + 1 });
                                    return TranspileError.TypeMismatch;
                                }
                            }

                            // Ensure all params are bound.
                            var gargs = self.allocator.alloc(*dtype.DataType, params_ptr.count) catch {
                                return TranspileError.MemoryAllocationFailed;
                            };
                            var pi: usize = 0;
                            for (params_ptr.items()) |p| {
                                if (bindings.get(p.items)) |dt_ptr| {
                                    gargs[pi] = dt_ptr;
                                } else {
                                    self.report_type_error(node, "cannot infer generic parameter '{s}' for '{s}'", .{ p.items, callee_name.? });
                                    return TranspileError.TypeMismatch;
                                }
                                pi += 1;
                            }

                            // Enforce the declared constraint set (`fun f<T: a | b>`):
                            // the inferred concrete type args must satisfy one of the
                            // forced instantiations. Unlike the impl path (which
                            // silently omits emission), a free-fn violation is a real
                            // Fun-level TypeError rather than an opaque C link error.
                            if (!impl_allows_generic_args(fnv.type_param_forced_insts, gargs)) {
                                self.report_type_error(node, "call to '{s}' violates generic constraint: type argument does not satisfy the declared bound", .{callee_name.?});
                                return TranspileError.TypeMismatch;
                            }

                            // Typecheck args against substituted signature.
                            idx = 0;
                            while (idx < args_nodes.items.len and idx < fixed_len) : (idx += 1) {
                                const expected_node = expected_items[idx];
                                if (expected_node.type != .Variable or expected_node.node_variant == null) continue;
                                const expected_dt = expected_node.node_variant.?.variable.type;
                                const expected_t = try self.type_from_dtype_with_subst(expected_dt, params_ptr.*, gargs);
                                try self.normalize_expr_to_expected_type(args_nodes.items[idx], expected_t, env, fns);
                                const actual_t = try self.infer_expr_type(args_nodes.items[idx].*, env, fns);
                                if (is_known_type(expected_t) and is_known_type(actual_t) and !(try self.can_implicit_coerce(expected_t, actual_t))) {
                                    self.report_type_error(node, "type mismatch in call to '{s}' argument {d}", .{ callee_name.?, idx + 1 });
                                    return TranspileError.TypeMismatch;
                                }
                            }

                            // Compute specialized return type.
                            if (fnv.rtype) |rt| {
                                call_rtype = try self.type_from_dtype_with_subst(&rt, params_ptr.*, gargs);
                            } else {
                                call_rtype = .{ .base = .Void };
                            }
                            callee_is_async = fnv.is_async;
                            callee_async_known = true;

                            // Register instantiation and call override for codegen.
                            const spec_name = try self.mangle_generic_fn_name(callee_name.?, gargs);
                            try self.register_generic_fn_instantiation(fn_node.?, params_ptr, gargs, spec_name, self.typecheck_owner_fn, 0);
                            await_lowering_callee = spec_name;
                            if (node.pos) |p| {
                                // Store on the ROOT (alongside the instantiation) so the
                                // call rewrite is found at emit time even when the call
                                // lives in an imported module typechecked under a child.
                                const root = self.get_root();
                                const key = try self.call_pos_key_alloc(p);
                                if (!root.generic_call_overrides.contains(key)) {
                                    root.generic_call_overrides.put(key, spec_name) catch return TranspileError.MemoryAllocationFailed;
                                } else {
                                    self.allocator.free(key);
                                }
                            }

                            handled_generic_call = true;
                        }
                    }

                    if (handled_generic_call) {
                        try self.validate_async_call_usage(node, callee_name, callee_is_async, callee_async_known);
                        return call_rtype;
                    }

                    if (maybe_sig) |sig| {
                        // Function call. With default params the accepted count is the
                        // range [effectiveMinArgs(), args.len]; too few or (non-variadic)
                        // too many is an error.
                        const sig_min = sig.effectiveMinArgs();
                        if (args_nodes.items.len < sig_min) {
                            const fname = callee.data.?.sval.items;
                            if (sig_min == sig.args.len) {
                                self.report_type_error(node, "function '{s}' expects {d} args, got {d}", .{ fname, sig.args.len, args_nodes.items.len });
                            } else {
                                self.report_type_error(node, "function '{s}' expects at least {d} args, got {d}", .{ fname, sig_min, args_nodes.items.len });
                            }
                            return TranspileError.WrongArgCount;
                        }
                        if (!sig.is_variadic and args_nodes.items.len > sig.args.len) {
                            const fname = callee.data.?.sval.items;
                            self.report_type_error(node, "function '{s}' expects {d} args, got {d}", .{ fname, sig.args.len, args_nodes.items.len });
                            return TranspileError.WrongArgCount;
                        }
                        for (args_nodes.items, 0..) |arg_node, idx| {
                            // Enum shorthand args: `foo(.Blue)` where param type is `Color`.
                            if (idx < sig.args.len) {
                                const expected = sig.args[idx];
                                try self.normalize_expr_to_expected_type(arg_node, expected, env, fns);
                            }

                            const actual = try self.infer_expr_type(arg_node.*, env, fns);
                            if (idx < sig.args.len) {
                                const expected = sig.args[idx];
                                if (is_known_type(expected) and is_known_type(actual) and !(try self.can_implicit_coerce(expected, actual))) {
                                    const fname = callee.data.?.sval.items;
                                    self.report_type_error(node, "type mismatch in call to '{s}' argument {d}", .{ fname, idx + 1 });
                                    return TranspileError.TypeMismatch;
                                }
                            }
                        }
                    } else if (method_sig) |msig| {
                        // Quirk method call.
                        const expected_args = msig.args.items();
                        if (args_nodes.items.len != expected_args.len) {
                            self.report_type_error(node, "method '{s}' expects {d} args, got {d}", .{ msig.name.items, expected_args.len, args_nodes.items.len });
                            return TranspileError.WrongArgCount;
                        }
                        for (args_nodes.items, 0..) |arg_node, idx| {
                            const expected = type_from_dtype(expected_args[idx].dtype);
                            try self.normalize_expr_to_expected_type(arg_node, expected, env, fns);

                            const actual = try self.infer_expr_type(arg_node.*, env, fns);
                            if (is_known_type(expected) and is_known_type(actual) and !(try self.can_implicit_coerce(expected, actual))) {
                                self.report_type_error(node, "type mismatch in call to method '{s}' argument {d}", .{ msig.name.items, idx + 1 });
                                return TranspileError.TypeMismatch;
                            }
                        }
                    } else if (plain_method_sig) |psig| {
                        // Plain impl method call. The generated function signature includes the
                        // implicit `self` parameter as the first argument.
                        if (!psig.is_variadic and psig.args.len == 0) {
                            self.report_type_error(node, "invalid method signature", .{});
                            return TranspileError.NotCallable;
                        }

                        // User args = params minus the implicit `self`. With defaults the
                        // accepted count is [min_user, max_user]; min subtracts self from
                        // the required-param count too.
                        const expected_user_args = if (psig.args.len > 0) psig.args.len - 1 else 0;
                        const psig_min = psig.effectiveMinArgs();
                        const min_user_args = if (psig_min > 0) psig_min - 1 else 0;
                        if (args_nodes.items.len < min_user_args) {
                            if (min_user_args == expected_user_args) {
                                self.report_type_error(node, "method '{s}' expects {d} args, got {d}", .{ plain_method_name orelse "<method>", expected_user_args, args_nodes.items.len });
                            } else {
                                self.report_type_error(node, "method '{s}' expects at least {d} args, got {d}", .{ plain_method_name orelse "<method>", min_user_args, args_nodes.items.len });
                            }
                            return TranspileError.WrongArgCount;
                        }
                        if (!psig.is_variadic and args_nodes.items.len > expected_user_args) {
                            self.report_type_error(node, "method '{s}' expects {d} args, got {d}", .{ plain_method_name orelse "<method>", expected_user_args, args_nodes.items.len });
                            return TranspileError.WrongArgCount;
                        }

                        for (args_nodes.items, 0..) |arg_node, idx| {
                            const sig_idx = idx + 1; // skip implicit self
                            if (sig_idx < psig.args.len) {
                                const expected = psig.args[sig_idx];
                                try self.normalize_expr_to_expected_type(arg_node, expected, env, fns);
                            }

                            const actual = try self.infer_expr_type(arg_node.*, env, fns);
                            if (sig_idx < psig.args.len) {
                                const expected = psig.args[sig_idx];
                                if (is_known_type(expected) and is_known_type(actual) and !(try self.can_implicit_coerce(expected, actual))) {
                                    self.report_type_error(node, "type mismatch in call to method '{s}' argument {d}", .{ plain_method_name orelse "<method>", idx + 1 });
                                    return TranspileError.TypeMismatch;
                                }
                            }
                        }
                    }

                    if (await_lowering_callee) |lower_name| {
                        try self.record_await_call_override(node, lower_name, await_lowering_has_receiver, await_lowering_receiver_by_ref);
                    }
                    if (self.in_await_operand_inference and await_lowering_dynamic_quirk_dispatch) {
                        try self.record_await_dynamic_quirk_override(node);
                    }

                    try self.validate_async_call_usage(node, callee_name, callee_is_async, callee_async_known);
                    return call_rtype;
                }

                if (mem.eql(u8, op, ".")) {
                    const left = exp.left orelse return .{ .base = .Unknown };
                    const right = exp.right orelse return .{ .base = .Unknown };

                    // Aliased enum variant constant:
                    // `alias.Enum.Variant` (supports both parse associativities).
                    if (extract_alias_enum_variant_parts(left, right)) |parts| {
                        if (self.alias_map_for_node(&node).contains(parts.alias_name)) {
                            const qualified_enum = try self.make_alias_qualified_symbol_name(parts.alias_name, parts.enum_name);
                            if (try self.resolve_enum_variant_constant_type(node, qualified_enum, parts.variant_name)) |_| {
                                // An aliased import is tracked by its alias, so
                                // reaching a variant through one uses it. Marking by
                                // origin file (which the resolver above does) does not
                                // reach the aliased entry.
                                self.mark_import_used_by_alias(parts.alias_name);
                                self.allocator.free(qualified_enum);
                                return .{ .base = .Unknown, .name = parts.enum_name };
                            }
                            self.allocator.free(qualified_enum);
                        }
                    }

                    // Module alias symbol access (`alias.symbol`).
                    if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                        const alias_name = left.*.data.?.sval.items;
                        const member_name = right.*.data.?.sval.items;
                        if (try self.resolve_alias_qualified_symbol_name(&node, alias_name, member_name)) |qualified| {
                            defer self.allocator.free(qualified);
                            // Enforce visibility for an alias-qualified GLOBAL read:
                            // a private (non-`pub`) global in the aliased module is
                            // not accessible through the alias (it would otherwise
                            // emit an undeclared `alias__global`, invalid C). Reject
                            // only when a same-named global exists and NONE is
                            // accessible (so a public global — or a name collision
                            // with a public one elsewhere — still works).
                            const gscan = self.scan_global_var_named(&node, member_name);
                            if (gscan.exists and !gscan.accessible) {
                                self.report_type_error(node, "global '{s}' is private to its module and cannot be accessed through alias '{s}'", .{ member_name, alias_name });
                                return TranspileError.SymbolNotDefined;
                            }
                            return .{ .base = .Unknown };
                        }
                    }

                    // Enum variant constant: `Enum.Variant`.
                    // Treat this form as enum access when `Enum` is a known enum type (even if declared later).
                    if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                        const enum_name = left.*.data.?.sval.items;
                        const variant_name = right.*.data.?.sval.items;
                        if (try self.resolve_enum_variant_constant_type(node, enum_name, variant_name)) |t| {
                            // If this specific site was already bound to a concrete
                            // generic instantiation (e.g. `Option__Token`, recorded
                            // when a shorthand `.None`/`.Some(x)` was resolved
                            // against an outer expected type), carry that concrete
                            // dtype forward instead of the bare `{name: "Option"}`.
                            // Without this, a later INDEPENDENT re-inference of this
                            // same node (e.g. a generic wrapper call's own T-inference
                            // from its argument) saw an incomplete, dtype_ref-less
                            // type and bound T to it, producing a malformed
                            // "Result__Option" (missing its own argument) instance
                            // that could never be satisfied -- misreported as a
                            // cyclic dependency.
                            if (self.lookup_enum_ctor_override(node)) |mangled| {
                                if (try self.dtype_from_mangled_type(mangled)) |synth_dt| {
                                    var t2 = t;
                                    t2.mangled_name = mangled;
                                    t2.dtype_ref = synth_dt;
                                    return t2;
                                }
                            }
                            return t;
                        }
                    }

                    var lt = try self.infer_expr_type(left.*, env, fns);

                    // The parser can encode chained field access right-associatively:
                    // `rect.a.x` -> `rect . (a . x)`.
                    // Support both `left . Identifier` and `left . (a . b . c)` forms.
                    if (right.type == .Identifier and right.data != null) {
                        return try self.infer_compound_field_access_type(node, lt, right.data.?.sval.items, env);
                    }

                    if (right.type == .Expression and right.node_variant != null and mem.eql(u8, right.node_variant.?.exp.op, "[]")) {
                        const rex = right.node_variant.?.exp;
                        const rleft = rex.left orelse {
                            self.report_type_error(node, "field access requires an identifier", .{});
                            return TranspileError.InvalidFieldAccess;
                        };
                        const rright = rex.right orelse {
                            self.report_type_error(node, "array index must be num", .{});
                            return TranspileError.TypeMismatch;
                        };
                        if (rleft.*.type != .Identifier or rleft.*.data == null) {
                            self.report_type_error(node, "field access requires an identifier", .{});
                            return TranspileError.InvalidFieldAccess;
                        }
                        const field_dt = try self.infer_compound_field_access_type(node, lt, rleft.*.data.?.sval.items, env);
                        const idx_t = try self.infer_expr_type(rright.*, env, fns);
                        if (idx_t.base != .Num) {
                            self.report_type_error(node, "array index must be num", .{});
                            return TranspileError.TypeMismatch;
                        }
                        if (!field_dt.is_array and field_dt.pointer_depth > 0) {
                            return .{ .base = field_dt.base, .is_array = false, .pointer_depth = field_dt.pointer_depth - 1, .name = field_dt.name };
                        }
                        if (!field_dt.is_array) {
                            self.report_type_error(node, "indexing requires an array", .{});
                            return TranspileError.IndexNonArray;
                        }
                        return .{ .base = field_dt.base, .is_array = false, .pointer_depth = field_dt.pointer_depth, .name = field_dt.name };
                    }

                    if (right.type == .Expression and right.node_variant != null and mem.eql(u8, right.node_variant.?.exp.op, ".")) {
                        var cursor: ast.Node = right.*;
                        while (true) {
                            if (cursor.type == .Expression and cursor.node_variant != null and mem.eql(u8, cursor.node_variant.?.exp.op, ".")) {
                                const dot = cursor.node_variant.?.exp;
                                const seg = dot.left orelse {
                                    self.report_type_error(node, "field access requires an identifier", .{});
                                    return TranspileError.InvalidFieldAccess;
                                };
                                if (seg.type == .Identifier and seg.data != null) {
                                    lt = try self.infer_compound_field_access_type(node, lt, seg.data.?.sval.items, env);
                                } else if (seg.type == .Expression and seg.node_variant != null and mem.eql(u8, seg.node_variant.?.exp.op, "[]")) {
                                    const segexp = seg.node_variant.?.exp;
                                    const segleft = segexp.left orelse {
                                        self.report_type_error(node, "field access requires an identifier", .{});
                                        return TranspileError.InvalidFieldAccess;
                                    };
                                    const segright = segexp.right orelse {
                                        self.report_type_error(node, "array index must be num", .{});
                                        return TranspileError.TypeMismatch;
                                    };
                                    if (segleft.*.type != .Identifier or segleft.*.data == null) {
                                        self.report_type_error(node, "field access requires an identifier", .{});
                                        return TranspileError.InvalidFieldAccess;
                                    }
                                    const field_dt = try self.infer_compound_field_access_type(node, lt, segleft.*.data.?.sval.items, env);
                                    const idx_t = try self.infer_expr_type(segright.*, env, fns);
                                    if (idx_t.base != .Num) {
                                        self.report_type_error(node, "array index must be num", .{});
                                        return TranspileError.TypeMismatch;
                                    }
                                    if (!field_dt.is_array and field_dt.pointer_depth > 0) {
                                        lt = .{ .base = field_dt.base, .is_array = false, .pointer_depth = field_dt.pointer_depth - 1, .name = field_dt.name };
                                    } else if (!field_dt.is_array) {
                                        self.report_type_error(node, "indexing requires an array", .{});
                                        return TranspileError.IndexNonArray;
                                    } else {
                                        lt = .{ .base = field_dt.base, .is_array = false, .pointer_depth = field_dt.pointer_depth, .name = field_dt.name };
                                    }
                                } else {
                                    self.report_type_error(node, "field access requires an identifier", .{});
                                    return TranspileError.InvalidFieldAccess;
                                }

                                const next = dot.right orelse {
                                    self.report_type_error(node, "field access requires an identifier", .{});
                                    return TranspileError.InvalidFieldAccess;
                                };
                                cursor = next.*;
                                continue;
                            }

                            if (cursor.type == .Identifier and cursor.data != null) {
                                lt = try self.infer_compound_field_access_type(node, lt, cursor.data.?.sval.items, env);
                                return lt;
                            }

                            self.report_type_error(node, "field access requires an identifier", .{});
                            return TranspileError.InvalidFieldAccess;
                        }
                    }

                    self.report_type_error(node, "field access requires an identifier", .{});
                    return TranspileError.TypeMismatch;
                }

                if (mem.eql(u8, op, ",")) {
                    // Comma expression type is the RHS type.
                    if (exp.right) |right| return try self.infer_expr_type(right.*, env, fns);
                    if (exp.left) |left| return try self.infer_expr_type(left.*, env, fns);
                    return .{ .base = .Unknown };
                }

                if (mem.eql(u8, op, "[]")) {
                    const left = exp.left orelse return .{ .base = .Unknown };
                    const right = exp.right orelse return .{ .base = .Unknown };
                    const lt = try self.infer_expr_type(left.*, env, fns);
                    const rt = try self.infer_expr_type(right.*, env, fns);
                    if (lt.base == .Str and !lt.is_array) {
                        if (rt.base != .Num) {
                            self.report_type_error(node, "array index must be num", .{});
                            return TranspileError.TypeMismatch;
                        }
                        return .{ .base = .Chr };
                    }
                    if (!lt.is_array and lt.pointer_depth > 0) {
                        if (rt.base != .Num) {
                            self.report_type_error(node, "array index must be num", .{});
                            return TranspileError.TypeMismatch;
                        }
                        return .{ .base = lt.base, .is_array = false, .pointer_depth = lt.pointer_depth - 1, .name = lt.name, .mangled_name = lt.mangled_name, .dtype_ref = lt.dtype_ref };
                    }
                    if (!lt.is_array) {
                        self.report_type_error(node, "indexing requires an array", .{});
                        return TranspileError.IndexNonArray;
                    }
                    if (rt.base != .Num) {
                        self.report_type_error(node, "array index must be num", .{});
                        return TranspileError.TypeMismatch;
                    }
                    // Indexing a multi-dimensional array (`num[2][3]`, array_depth 2)
                    // once yields an array of one-lower depth (`num[3]`, still an
                    // array); a final index produces the element. Without this, a 2D
                    // subscript `m[i][j]` was wrongly rejected ("indexing requires an
                    // array") on the second `[]` even though the declaration emits a
                    // valid C 2D array.
                    const remaining_depth = if (lt.array_depth > 1) lt.array_depth - 1 else 0;
                    return .{
                        .base = lt.base,
                        .is_array = remaining_depth > 0,
                        .array_depth = remaining_depth,
                        .pointer_depth = lt.pointer_depth,
                        .name = lt.name,
                        .mangled_name = lt.mangled_name,
                        .dtype_ref = lt.dtype_ref,
                    };
                }

                const is_assign = mem.eql(u8, op, "=") or
                    mem.eql(u8, op, "+=") or mem.eql(u8, op, "-=") or mem.eql(u8, op, "*=") or mem.eql(u8, op, "/=") or
                    mem.eql(u8, op, "<<=") or mem.eql(u8, op, ">>=");

                if (is_assign) {
                    const left = exp.left orelse return .{ .base = .Unknown };
                    const right = exp.right orelse return .{ .base = .Unknown };
                    try self.check_const_reassignment(node, left, env);
                    const lt = try self.infer_expr_type(left.*, env, fns);
                    // Enum shorthand assignment: `c = .Blue`.
                    // Resolve the shorthand before inferring RHS type.
                    if (self.expected_enum_name(lt)) |enum_name| {
                        if (dot_shorthand_variant_name(right)) |_| {
                            _ = try self.resolve_dot_shorthand_enum_variant(right, enum_name);
                        } else {
                            // Shorthand data-variant construction in assignment
                            // position: `d = .Cval('a');` or `f.data = .Cval('a');`.
                            // Without this, only the plain-variant shorthand
                            // (`c = .Blue`) was resolved here -- a data-carrying
                            // variant's shorthand CALL (`.Cval(...)`) fell through
                            // with no enum context and was misdiagnosed as an
                            // ordinary (nonexistent) function call.
                            try self.resolve_shorthand_enum_call(right, enum_name);
                            // Or nested one level inside a generic wrapper call
                            // (`d = ok(.None);`) -- see the function doc.
                            try self.resolve_shorthand_args_via_generic_wrapper(right, lt, fns);
                        }
                        // For a GENERIC enum (`List<dec>`), record the monomorphized
                        // name at this construction site (mirrors the `.Variable`
                        // declaration case above) so codegen emits `List__dec` +
                        // `List__dec_Cons` instead of the bare, never-emitted
                        // template name. Without this, re-assigning into an
                        // ALREADY-DECLARED variable/dereferenced pointer (`*n =
                        // List.Cons(v, tail);`, as opposed to declaring it inline
                        // with `List<dec>* n = ...`) from a plain, non-generic
                        // function had no expected-type context at all to resolve
                        // the concrete instantiation from.
                        try self.bind_enum_ctor_expected(right, lt);
                    }

                    if (right.*.type == .CompoundInit) {
                        try self.bind_compound_init_expected(right, lt, env, fns);
                    }

                    const rt = try self.infer_expr_type(right.*, env, fns);
                    const lt_n = normalize_builtin_named_checked_type(lt);
                    const rt_n = normalize_builtin_named_checked_type(rt);

                    // For compound assignments, require numeric types.
                    if (!mem.eql(u8, op, "=")) {
                        if (mem.eql(u8, op, "<<=") or mem.eql(u8, op, ">>=")) {
                            if (lt_n.base != .Num or rt_n.base != .Num) {
                                self.report_type_error(node, "compound assignment '{s}' expects num", .{op});
                                return TranspileError.TypeMismatch;
                            }
                            return .{ .base = .Num };
                        }

                        if (!self.is_numeric_type(lt_n) or !self.is_numeric_type(rt_n)) {
                            self.report_type_error(node, "compound assignment '{s}' expects num/dec", .{op});
                            return TranspileError.TypeMismatch;
                        }
                        const res_base = promote_numeric_type(lt_n, rt_n);
                        if (res_base != lt_n.base) {
                            self.report_type_error(node, "compound assignment '{s}' would change the variable type", .{op});
                            return TranspileError.TypeMismatch;
                        }
                        return lt_n;
                    }

                    if (is_known_type(lt) and is_known_type(rt) and !(try self.can_implicit_coerce(lt, rt))) {
                        self.report_type_error(node, "type mismatch in assignment", .{});
                        return TranspileError.TypeMismatch;
                    }
                    return lt;
                }

                // Equality needs special handling for enum dot shorthand, since `.Variant` cannot
                // be type-inferred without an expected enum type.
                if (mem.eql(u8, op, "==") or mem.eql(u8, op, "!=")) {
                    const left = exp.left orelse return .{ .base = .Unknown };
                    const right = exp.right orelse return .{ .base = .Unknown };

                    const left_is_shorthand = dot_shorthand_variant_name(left) != null;
                    const right_is_shorthand = dot_shorthand_variant_name(right) != null;

                    // If both sides are shorthand, we have no context to infer the enum.
                    if (left_is_shorthand and right_is_shorthand) {
                        self.report_type_error(node, "cannot infer enum type for dot shorthand on both sides of '{s}'", .{op});
                        return TranspileError.TypeMismatch;
                    }

                    var lt: CheckedType = .{ .base = .Unknown };
                    var rt: CheckedType = .{ .base = .Unknown };

                    if (!left_is_shorthand) {
                        lt = try self.infer_expr_type(left.*, env, fns);
                        if (self.expected_enum_name(lt)) |enum_name| {
                            if (right_is_shorthand) {
                                _ = try self.resolve_dot_shorthand_enum_variant(right, enum_name);
                            }
                        }
                        rt = try self.infer_expr_type(right.*, env, fns);
                        if (left_is_shorthand) {
                            if (self.expected_enum_name(rt)) |enum_name| {
                                _ = try self.resolve_dot_shorthand_enum_variant(left, enum_name);
                                lt = .{ .base = .Unknown, .name = enum_name };
                            }
                        }
                    } else {
                        // Left is shorthand, right is not.
                        rt = try self.infer_expr_type(right.*, env, fns);
                        if (self.expected_enum_name(rt)) |enum_name| {
                            _ = try self.resolve_dot_shorthand_enum_variant(left, enum_name);
                            lt = .{ .base = .Unknown, .name = enum_name };
                        } else {
                            // Try to infer the left after resolution attempt; will error with a clearer message elsewhere.
                            lt = try self.infer_expr_type(left.*, env, fns);
                        }
                    }

                    if (is_known_type(lt) and is_known_type(rt) and !self.can_compare_or_match(lt, rt)) {
                        self.report_type_error(node, "equality '{s}' expects both sides to have the same type", .{op});
                        return TranspileError.TypeMismatch;
                    }
                    return .{ .base = .Bin };
                }

                const l: CheckedType = if (exp.left) |left| try self.infer_expr_type(left.*, env, fns) else CheckedType{ .base = .Unknown };
                const r: CheckedType = if (exp.right) |right| try self.infer_expr_type(right.*, env, fns) else CheckedType{ .base = .Unknown };

                // A type param (e.g. T) is unknown but may be constrained to numeric types;
                // allow it in numeric/comparison contexts so generic bodies typecheck.
                const is_num_or_param = struct {
                    fn call(checker: *Self, t: CheckedType, e: *TypeEnv) bool {
                        if (checker.is_numeric_type(t)) return true;
                        if (t.base == .Unknown and t.name != null and e.has_type_param(t.name.?)) return true;
                        return false;
                    }
                }.call;

                if (mem.eql(u8, op, "+") or mem.eql(u8, op, "-") or mem.eql(u8, op, "*") or mem.eql(u8, op, "/") or mem.eql(u8, op, "%")) {
                    // Reject a constant zero divisor at compile time rather than
                    // emitting C that divides by zero (UB / SIGFPE at runtime).
                    if (mem.eql(u8, op, "/") or mem.eql(u8, op, "%")) {
                        if (exp.right) |rdiv| {
                            if (self.const_fold_int(rdiv.*)) |dv| {
                                if (dv == 0) {
                                    self.report_type_error(node, "division by zero: right operand of '{s}' is the constant 0", .{op});
                                    return TranspileError.TypeMismatch;
                                }
                            }
                        }
                    }
                    if (mem.eql(u8, op, "%")) {
                        if (l.base != .Num or r.base != .Num) {
                            self.report_type_error(node, "operator '{s}' expects num operands", .{op});
                            return TranspileError.TypeMismatch;
                        }
                        return .{ .base = .Num };
                    }

                    if (!is_num_or_param(self, l, env) or !is_num_or_param(self, r, env)) {
                        self.report_type_error(node, "operator '{s}' expects num/dec operands", .{op});
                        return TranspileError.TypeMismatch;
                    }
                    if (l.base == .Unknown and r.base == .Unknown and l.name != null and r.name != null and
                        mem.eql(u8, l.name.?, r.name.?) and env.has_type_param(l.name.?))
                    {
                        return l;
                    }
                    return .{ .base = promote_numeric_type(l, r) };
                }

                if (mem.eql(u8, op, "<") or mem.eql(u8, op, "<=") or mem.eql(u8, op, ">") or mem.eql(u8, op, ">=")) {
                    if (!is_num_or_param(self, l, env) or !is_num_or_param(self, r, env)) {
                        self.report_type_error(node, "comparison '{s}' expects num/dec operands", .{op});
                        return TranspileError.TypeMismatch;
                    }
                    return .{ .base = .Bin };
                }

                // NOTE: equality is handled above to support enum dot shorthand.

                if (mem.eql(u8, op, "&&") or mem.eql(u8, op, "||")) {
                    if (l.base != .Bin or r.base != .Bin) {
                        self.report_type_error(node, "logical '{s}' expects bin operands", .{op});
                        return TranspileError.TypeMismatch;
                    }
                    return .{ .base = .Bin };
                }

                if (mem.eql(u8, op, "..")) {
                    if (l.base != .Num or r.base != .Num) {
                        self.report_type_error(node, "range '..' expects num endpoints", .{});
                        return TranspileError.TypeMismatch;
                    }
                    return .{ .base = .Unknown };
                }

                return l;
            },
            else => return .{ .base = .Unknown },
        }
    }

    fn check_body(self: *Self, body: *ast.Node, env: *TypeEnv, fns: *const std.StringHashMap(FnSig), fn_rtype: CheckedType) TranspileError!void {
        if (body.type != .Body) return;

        try env.push();
        defer env.pop();
        defer self.warn_unused_bindings_in_current_scope(env);

        const stmts = body.node_variant.?.body.statements;
        var scope_terminated = false;
        var reported_unreachable = false;
        for (stmts.items()) |stmt_ptr| {
            const stmt = stmt_ptr.*;

            if (scope_terminated and stmt.type != .StatementWarningControl and !reported_unreachable) {
                self.report_warning(.unreachable_code, stmt, "statement is unreachable because the previous statement always exits the current scope", .{});
                reported_unreachable = true;
            }

            switch (stmt.type) {
                .Variable => {
                    const inferred_let_t = try self.infer_let_variable_dtype(stmt_ptr, env, fns);
                    const v = stmt_ptr.node_variant.?.variable;
                    const name = v.name.items;
                    const vtype = if (inferred_let_t) |it| it else try self.type_from_dtype_with_mangled(v.type);
                    try self.ensure_dtype_visible(stmt, v.type, env.type_params);
                    if (v.type.generic_args != null) {
                        try self.register_generic_instantiation(v.type);
                    }
                    if (inferred_let_t) |it| {
                        try self.register_generic_instantiation_from_checked_type(it);
                    }
                    try env.put_current_decl(name, vtype, stmt_ptr);
                    if (v.val) |val| {
                        if (val.*.type == .CompoundInit) {
                            try self.bind_compound_init_expected(val, vtype, env, fns);
                        }
                        if (self.expected_enum_name(vtype)) |enum_name| {
                            if (dot_shorthand_variant_name(val)) |_| {
                                _ = try self.resolve_dot_shorthand_enum_variant(val, enum_name);
                            } else {
                                // Shorthand data-variant construction: `.Variant(args)`.
                                try self.resolve_shorthand_enum_call(val, enum_name);
                                // Or nested one level inside a generic wrapper call
                                // (`let t = ok(.Some(x));`) -- see the function doc.
                                try self.resolve_shorthand_args_via_generic_wrapper(val, vtype, fns);
                            }
                            // For a GENERIC enum (`Option<num>`), record the
                            // monomorphized name at the construction site so codegen
                            // emits `Option__num` + `Option__num_Some`.
                            try self.bind_enum_ctor_expected(val, vtype);
                        }
                        const init_t = try self.infer_expr_type(val.*, env, fns);
                        if (is_known_type(vtype) and is_known_type(init_t) and !(try self.can_implicit_coerce(vtype, init_t))) {
                            self.report_type_error(stmt, "type mismatch in initialization of '{s}'", .{name});
                            return TranspileError.TypeMismatch;
                        }
                        // uN/iN literal range/signedness check (advisory).
                        self.check_int_literal_range(v.type, val, stmt);
                    }
                },
                .StatementReturn => {
                    const has_expr = stmt.node_variant != null;
                    if (fn_rtype.base == .Void) {
                        if (has_expr) {
                            self.report_type_error(stmt, "void function cannot return a value", .{});
                            return TranspileError.ReturnTypeMismatch;
                        }
                    } else {
                        if (!has_expr) {
                            self.report_type_error(stmt, "non-void function must return a value", .{});
                            return TranspileError.ReturnTypeMismatch;
                        }
                        const rv = stmt.node_variant.?.statement.return_stmt;
                        if (rv.*.type == .CompoundInit) {
                            try self.bind_compound_init_expected(rv, fn_rtype, env, fns);
                        }
                        if (self.expected_enum_name(fn_rtype)) |enum_name| {
                            if (dot_shorthand_variant_name(rv)) |_| {
                                _ = try self.resolve_dot_shorthand_enum_variant(rv, enum_name);
                            } else {
                                // Shorthand data-variant construction in return position.
                                try self.resolve_shorthand_enum_call(rv, enum_name);
                                // Or nested one level inside a generic wrapper call
                                // (`ret ok(.None);`) -- see the function doc.
                                try self.resolve_shorthand_args_via_generic_wrapper(rv, fn_rtype, fns);
                            }
                            // Generic enum returned (`ret Option.Some(x)` in a fn whose
                            // return type is `Option<num>`): record the monomorphized
                            // construction name so codegen emits `Option__num`.
                            try self.bind_enum_ctor_expected(rv, fn_rtype);
                        }
                        const rt = try self.infer_expr_type(rv.*, env, fns);
                        // A declared return type that's still a symbolic, numerically
                        // constrained type param (e.g. `fun sign<T: num | dec>(T x) T`)
                        // can legitimately return a concrete numeric LITERAL (`ret -1;`,
                        // whose inferred type is plain `Num`, not `T`). The real
                        // constraint (does the concrete `T` actually accept `Num`?) is
                        // enforced at each call site via `impl_allows_generic_args`, so
                        // the template body itself only needs this numeric/param
                        // allowance — mirroring the same relaxation already applied to
                        // unary/binary operators on a constrained type param above.
                        const rtype_is_numeric_param = fn_rtype.base == .Unknown and fn_rtype.name != null and env.has_type_param(fn_rtype.name.?);
                        const rt_is_num_or_param = rt.base == .Num or rt.base == .Dec or
                            (rt.base == .Unknown and rt.name != null and env.has_type_param(rt.name.?));
                        const skip_return_check = rtype_is_numeric_param and rt_is_num_or_param;
                        if (!skip_return_check and is_known_type(fn_rtype) and is_known_type(rt) and !(try self.can_implicit_coerce(fn_rtype, rt))) {
                            self.report_type_error(stmt, "return type mismatch", .{});
                            return TranspileError.ReturnTypeMismatch;
                        }
                        // Warn if returning the address of a body-local variable.
                        if (fn_rtype.pointer_depth > 0) {
                            self.warn_if_returning_local_ptr_in_env(rv.*, env);
                        }
                    }
                },
                .StatementDefer => {
                    const d = stmt.node_variant.?.statement.defer_stmt;
                    if (d.body.type == .Body) {
                        try self.check_body(d.body, env, fns, fn_rtype);
                    } else {
                        _ = try self.infer_expr_type(d.body.*, env, fns);
                    }
                },
                .StatementAsm => {
                    const asm_s = stmt.node_variant.?.statement.asm_stmt;
                    for (asm_s.outputs.items()) |op| {
                        _ = try self.infer_expr_type(op.expr.*, env, fns);
                    }
                    for (asm_s.inputs.items()) |op| {
                        _ = try self.infer_expr_type(op.expr.*, env, fns);
                    }
                },
                .StatementIf => {
                    const ifs = stmt.node_variant.?.statement.if_stmt;
                    const ct = try self.infer_expr_type(ifs.condition.*, env, fns);
                    if (ct.base != .Bin) {
                        self.report_type_error(stmt, "if condition must be bin", .{});
                        return TranspileError.InvalidConditionType;
                    }
                    try self.check_body(ifs.body, env, fns, fn_rtype);
                },
                .StatementElseIf => {
                    const elif = stmt.node_variant.?.statement.elif_stmt;
                    const ct = try self.infer_expr_type(elif.condition.*, env, fns);
                    if (ct.base != .Bin) {
                        self.report_type_error(stmt, "elif condition must be bin", .{});
                        return TranspileError.InvalidConditionType;
                    }
                    try self.check_body(elif.body, env, fns, fn_rtype);
                },
                .StatementElse => {
                    const els = stmt.node_variant.?.statement.else_stmt;
                    try self.check_body(els.body, env, fns, fn_rtype);
                },
                .StatementFit => {
                    const fit = stmt.node_variant.?.statement.fit_stmt;
                    const target_t = try self.infer_expr_type(fit.exp.*, env, fns);
                    const target_enum = self.expected_enum_name(target_t);
                    const subject_is_tagged = if (target_enum) |en| self.enum_name_is_tagged_union(en) else false;
                    // Matching `fit s { Enum.Variant -> ... }` USES the enum `Enum`, so
                    // mark the import that provides it. Variant-path conditions are
                    // patterns (not value expressions), so they otherwise never reach
                    // type resolution → the import was wrongly flagged unused. Use the
                    // base name (a monomorphized subject may carry `Result__JsonValue`).
                    if (subject_is_tagged) {
                        if (target_enum) |en| {
                            const en_base = if (mem.indexOf(u8, en, "__")) |i| en[0..i] else en;
                            try self.ensure_named_type_visible(stmt, en_base);
                        }
                    }
                    for (fit.branches.items()) |branch| {
                        if (branch.condition) |cond| {
                            if (target_enum) |enum_name| {
                                if (dot_shorthand_variant_name(cond)) |_| {
                                    _ = try self.resolve_dot_shorthand_enum_variant(cond, enum_name);
                                }
                            }
                            // For a tagged-union subject, a variant-path condition
                            // (`Enum.Variant`) is a pattern, not a comparable value —
                            // validate it names a real variant instead of type-matching.
                            if (subject_is_tagged) {
                                const vname = self.fit_variant_name_of(cond.*) orelse {
                                    self.report_type_error(stmt, "fit arm on a data-carrying enum must match a variant", .{});
                                    return TranspileError.TypeMismatch;
                                };
                                if (self.lookup_enum_variant(target_enum.?, vname) == null) {
                                    self.report_type_error(stmt, "enum '{s}' has no variant '{s}'", .{ target_enum.?, vname });
                                    return TranspileError.UnknownField;
                                }
                            } else {
                                const ct = try self.infer_expr_type(cond.*, env, fns);
                                if (is_known_type(target_t) and is_known_type(ct) and !self.can_compare_or_match(target_t, ct)) {
                                    self.report_type_error(stmt, "fit branch condition type must match fit expression type", .{});
                                    return TranspileError.TypeMismatch;
                                }
                            }
                        }
                        // Destructuring arm: register payload bindings as locals in a
                        // fresh scope so the arm body type-checks against them.
                        if (branch.bindings != null and branch.condition != null and subject_is_tagged) {
                            try env.push();
                            defer env.pop();
                            const vname = self.fit_variant_name_of(branch.condition.?.*).?;
                            const variant = self.lookup_enum_variant(target_enum.?, vname);
                            const payload = if (variant) |v| v.payload else null;
                            for (branch.bindings.?.items(), 0..) |bname, i| {
                                const bt = if (payload != null and i < payload.?.count)
                                    try self.fit_binding_type(target_enum.?, target_t, payload.?.items()[i])
                                else
                                    CheckedType{ .base = .Unknown };
                                try env.put_current(bname.items, bt);
                            }
                            try self.check_body(branch.body, env, fns, fn_rtype);
                        } else {
                            try self.check_body(branch.body, env, fns, fn_rtype);
                        }
                    }
                    self.warn_if_fit_has_unreachable_branches(target_t, fit.branches.items());
                    self.warn_if_fit_not_exhausted(stmt, target_t, fit.branches.items());
                },
                .StatementFor => {
                    const f = stmt.node_variant.?.statement.for_stmt;
                    switch (f) {
                        .cond => |fc| {
                            if (fc.condition) |cond| {
                                const ct = try self.infer_expr_type(cond.*, env, fns);
                                if (ct.base != .Bin) {
                                    self.report_type_error(stmt, "for condition must be bin", .{});
                                    return TranspileError.InvalidConditionType;
                                }
                            }
                            try env.push();
                            defer env.pop();
                            try self.check_body(fc.body, env, fns, fn_rtype);
                        },
                        .range => |fr| {
                            // for i : start..end { ... }
                            const range_node = fr.range.*;
                            if (range_node.type != .Expression or !mem.eql(u8, range_node.node_variant.?.exp.op, "..")) {
                                self.report_type_error(stmt, "for-range expects '..'", .{});
                                return TranspileError.TypeMismatch;
                            }
                            _ = try self.infer_expr_type(range_node, env, fns);
                            try env.push();
                            defer env.pop();
                            try env.put_current(fr.index_name, .{ .base = .Num });
                            try self.check_body(fr.body, env, fns, fn_rtype);
                        },
                        .iter => |fi| {
                            const it_t = try self.infer_expr_type(fi.iterable.*, env, fns);
                            const vec_item_dt = blk: {
                                const dt = it_t.dtype_ref orelse break :blk null;
                                if (dt.pointer_depth != 0 or dt.array_depth != 0 or dt.generic_args == null) break :blk null;
                                if (!mem.eql(u8, dt.type_str.items, "Vec")) break :blk null;
                                const gargs = dt.generic_args.?.items();
                                if (gargs.len != 1) break :blk null;
                                break :blk gargs[0];
                            };
                            // Any value whose type drives the Iterator protocol (a
                            // collection with `iter()`, or an iterator with `next()`).
                            // Vec keeps its direct fast path above; everything else
                            // (Map/Set/user types/iterators) resolves its element type
                            // here and is lowered to the next()/fit-Option loop.
                            const iter_elem = if (vec_item_dt == null and !it_t.is_array)
                                (if (it_t.dtype_ref) |dt| self.resolve_iterable_elem(dt) else null)
                            else
                                null;
                            // `for k, v :: map` — pair iteration: `k` binds each key, `v`
                            // its value. Only valid over a Map (and only with an index name).
                            const map_kv = if (fi.index_name != null)
                                (if (it_t.dtype_ref) |dt| self.map_kv_dtypes(dt) else null)
                            else
                                null;
                            if (!it_t.is_array and vec_item_dt == null and iter_elem == null and map_kv == null) {
                                self.report_type_error(stmt, "for-iter expects an array, a Vec, a Map (for 'k, v :: map'), or a value implementing Iterator (or exposing iter())", .{});
                                return TranspileError.TypeMismatch;
                            }
                            // An index counter (`for i, item : ...`) is only meaningful for
                            // indexable sources (arrays/Vec). A non-Map Iterator is
                            // positionless, so reject the index form there.
                            if (fi.index_name != null and iter_elem != null and map_kv == null) {
                                self.report_type_error(stmt, "for-iter with an index ('i, item') requires an array, a Vec, or a Map", .{});
                                return TranspileError.TypeMismatch;
                            }
                            // Record the resolved Vec item type for codegen's fast path
                            // (see ForIterInfo's doc comment) -- resolved here from the
                            // iterable's inferred type, which `infer_expr_type` already
                            // handles for any expression (an identifier, a field access,
                            // a call, ...), not just a bare identifier. Codegen no longer
                            // has to re-derive this via a name-only scope-entity lookup,
                            // which is what previously limited the Vec fast path to
                            // identifier iterables only.
                            if (vec_item_dt) |item_dt| {
                                try self.record_for_iter_override(stmt, .{ .vec_item_dt = item_dt });
                            }
                            try env.push();
                            defer env.pop();
                            if (map_kv) |kv| {
                                // k : K, v : V
                                try env.put_current(fi.index_name.?, try self.type_from_dtype_with_mangled(kv.key));
                                try env.put_current(fi.item_name, try self.type_from_dtype_with_mangled(kv.val));
                                try self.check_body(fi.body, env, fns, fn_rtype);
                            } else {
                                if (fi.index_name) |iname| {
                                    try env.put_current(iname, .{ .base = .Num });
                                }
                                var item_t = if (iter_elem) |ie|
                                    try self.type_from_dtype_with_mangled(ie.elem)
                                else if (vec_item_dt) |elem_dt|
                                    try self.type_from_dtype_with_mangled(elem_dt)
                                else
                                    it_t;
                                if (vec_item_dt == null and iter_elem == null) {
                                    // Element is one dimension fewer than the iterable.
                                    item_t.array_depth = if (it_t.array_depth > 0) it_t.array_depth - 1 else 0;
                                    item_t.is_array = item_t.array_depth > 0;
                                }
                                try env.put_current(fi.item_name, item_t);
                                try self.check_body(fi.body, env, fns, fn_rtype);
                            }
                        },
                    }
                },
                .Body => {
                    try self.check_body(stmt_ptr, env, fns, fn_rtype);
                },
                .StatementAssert => {
                    const stmtv = stmt.node_variant.?.statement.assert_stmt;
                    const ct = try self.infer_expr_type(stmtv.condition.*, env, fns);
                    if (ct.base != .Bin) {
                        self.report_type_error(stmt, "assert expects bin condition", .{});
                        return TranspileError.TypeMismatch;
                    }
                    if (stmtv.message) |msg| {
                        const mt = try self.infer_expr_type(msg.*, env, fns);
                        if (mt.base != .Str) {
                            self.report_type_error(stmt, "assert message must be str", .{});
                            return TranspileError.TypeMismatch;
                        }
                    }
                    if (stmtv.condition.*.type == .Boolean) {
                        if (stmtv.condition.*.data != null and stmtv.condition.*.data.?.bval) {
                            self.report_warning(.assert_constant, stmt, "assert condition is always true", .{});
                        } else {
                            self.report_warning(.assert_constant, stmt, "assert condition is always false and will always abort", .{});
                        }
                    }
                },
                .StatementWarningControl => {
                    // Queue allow/expect entries during typecheck so that subsequent
                    // return_local_ptr warning checks in the same body see them.
                    if (stmt.node_variant) |nv| {
                        const ctrl = nv.statement.warning_ctrl;
                        try self.queue_warning_control(ctrl.action, ctrl.id, ctrl.reason, stmt.pos);
                    }
                },
                .StatementFork => {
                    // `fork f(args)` — type-check the spawned call so its callee is
                    // marked used (otherwise an async fn used ONLY as a fork target
                    // false-positives the unused_function warning). Mirrors how a
                    // bare call / `await f(x)` marks its callee via infer_expr_type.
                    // The fork-target flag exempts the call from the must-be-awaited
                    // rule (fork invokes an async fn fire-and-forget).
                    const fk = stmt.node_variant.?.statement.fork_stmt;
                    const prev_fork = self.in_fork_target_inference;
                    self.in_fork_target_inference = true;
                    defer self.in_fork_target_inference = prev_fork;
                    _ = try self.infer_expr_type(fk.expr.*, env, fns);
                },
                else => {
                    // Expression statements, break/continue, etc.
                    _ = try self.infer_expr_type(stmt, env, fns);
                },
            }

            if (node_is_scope_terminator(stmt_ptr)) scope_terminated = true;
        }
    }

    /// True when `proc` is a `std.c.*` C-binding module (its source lives under
    /// `stdlib/std/c/`). Such modules declare bodyless bindings whose bare names
    /// (`log`, `pow`, `sin`, ...) can collide in the typecheck `fns` map with an
    /// unrelated stdlib function of the same name (e.g. `std.log`'s
    /// `log(LogLevel, str)`). Stdlib module paths are always built with `/`
    /// separators (see build_stdlib_module_path), so a substring check suffices.
    fn proc_is_c_binding_module(proc: *Self) bool {
        return std.mem.indexOf(u8, proc.input_file_path, "/std/c/") != null or
            std.mem.indexOf(u8, proc.input_file_path, "\\std\\c\\") != null;
    }

    /// Build a `FnSig` from a function node, allocating a fresh `args` slice and
    /// tracking it in `owned_args` for later free. Mirrors the per-node sig
    /// construction used in the main `collect_fn_sigs` loops.
    fn build_fn_sig_from_node(self: *Self, proc: *Self, fnv: anytype, owned_args: *ArrayList([]CheckedType)) TranspileError!FnSig {
        const args_vec = fnv.args orelse utils.Vector(*ast.Node).init(proc.allocator);
        const args_items = args_vec.items();
        var args_slice = proc.allocator.alloc(CheckedType, args_items.len) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer proc.allocator.free(args_slice);

        var i: usize = 0;
        for (args_items) |arg_ptr| {
            const arg = arg_ptr.*;
            if (arg.type == .Variable and arg.node_variant != null) {
                try self.register_generic_instantiations_from_dtype(arg.node_variant.?.variable.type);
                args_slice[i] = try self.type_from_dtype_with_mangled(arg.node_variant.?.variable.type);
            } else {
                args_slice[i] = .{ .base = .Unknown };
            }
            try self.register_generic_instantiation_from_checked_type(args_slice[i]);
            i += 1;
        }

        owned_args.append(args_slice) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        const fn_rtype: CheckedType = if (fnv.rtype) |rt| blk: {
            const rt_heap = try self.clone_dtype(&rt);
            try self.register_generic_instantiations_from_dtype(rt_heap);
            break :blk try self.type_from_dtype_with_mangled(rt_heap);
        } else .{ .base = .Void };
        try self.register_generic_instantiation_from_checked_type(fn_rtype);
        return .{
            .rtype = fn_rtype,
            .args = args_slice,
            .is_variadic = fnv.is_variadic,
            .is_async = fnv.is_async,
            .type_params = if (fnv.type_params) |*params| params else null,
            .min_args = count_required_args_from_node(args_vec),
        };
    }

    /// Register the alias-qualified key (`alias__name`) for a function whose bare
    /// name is already present in `fns`. This handles the case where the same
    /// stdlib module is imported both unaliased (often transitively, e.g. std.json
    /// does `imp std.math;`) and aliased (`imp std.math as m`): the bare-name dedup
    /// would otherwise skip the alias-registration block, leaving `m.sqrt_dec(...)`
    /// unable to infer its return type.
    ///
    /// For a normal module we clone the already-registered bare `FnSig` (const-shared
    /// for typecheck only; sharing its `args`/`type_params`) under the alias key — no
    /// new `owned_args` entry, so there is no double-free.
    ///
    /// For a `std.c.*` C-binding module the bare `fns.get(name)` entry may be an
    /// UNRELATED collider (e.g. `std.log`'s void `log`), so cloning it would poison
    /// the alias key with the wrong return type. Instead we build the alias-qualified
    /// sig from the C binding's OWN function node (`fnv`), giving `cmath.log(...)` its
    /// real `dec` return type for typecheck while codegen still emits the raw libc name.
    fn register_alias_qualified_from_existing(self: *Self, proc: *Self, fns: *std.StringHashMap(FnSig), fnv: anytype, owned_args: *ArrayList([]CheckedType)) TranspileError!void {
        const alias = proc.import_alias orelse return;
        const name = (fnv.name orelse return).items;
        const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
        if (fns.contains(alias_name)) {
            self.allocator.free(alias_name);
            return;
        }
        const sig: FnSig = if (proc_is_c_binding_module(proc))
            try self.build_fn_sig_from_node(proc, fnv, owned_args)
        else
            (fns.get(name) orelse {
                self.allocator.free(alias_name);
                return;
            });
        fns.put(alias_name, sig) catch {
            self.allocator.free(alias_name);
            return TranspileError.MemoryAllocationFailed;
        };
    }

    fn collect_fn_sigs(self: *Self, proc: *Self, fns: *std.StringHashMap(FnSig), owned_args: *ArrayList([]CheckedType)) TranspileError!void {
        for (proc.nodes.items(), 0..) |node, node_i| {
            if (node.type != .Function or node.node_variant == null) continue;
            const fnv = node.node_variant.?.function;
            if (fnv.name == null) continue;
            const name = fnv.name.?.items;

            if (fns.contains(name)) {
                // The bare name is already registered (e.g. the same stdlib module
                // was imported both unaliased — transitively — and aliased). Even so,
                // if THIS proc carries an import alias, we still owe the
                // alias-qualified key (`m__fn`) so `m.fn(...)` calls can infer their
                // return type. Reuse the already-registered bare signature (it is
                // const-shared for typecheck only; do NOT add another owned_args entry).
                try self.register_alias_qualified_from_existing(proc, fns, fnv, owned_args);
                continue;
            }

            const args_vec = fnv.args orelse utils.Vector(*ast.Node).init(proc.allocator);
            const args_items = args_vec.items();
            var args_slice = proc.allocator.alloc(CheckedType, args_items.len) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer proc.allocator.free(args_slice);

            var i: usize = 0;
            for (args_items) |arg_ptr| {
                const arg = arg_ptr.*;
                if (arg.type == .Variable and arg.node_variant != null) {
                    try self.register_generic_instantiations_from_dtype(arg.node_variant.?.variable.type);
                    args_slice[i] = try self.type_from_dtype_with_mangled(arg.node_variant.?.variable.type);
                } else {
                    args_slice[i] = .{ .base = .Unknown };
                }
                try self.register_generic_instantiation_from_checked_type(args_slice[i]);
                i += 1;
            }

            owned_args.append(args_slice) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            const fn_rtype: CheckedType = if (fnv.rtype) |rt| blk: {
                const rt_heap = try self.clone_dtype(&rt);
                try self.register_generic_instantiations_from_dtype(rt_heap);
                break :blk try self.type_from_dtype_with_mangled(rt_heap);
            } else .{ .base = .Void };
            try self.register_generic_instantiation_from_checked_type(fn_rtype);
            const fn_min_args = count_required_args_from_node(args_vec);
            // A pointer into `fnv.type_params` itself would dangle: `fnv` is a
            // by-value copy of this loop iteration's node, reused (and thus
            // overwritten) by the NEXT iteration's `fnv` at the same stack
            // slot. Any `FnSig` stored with such a pointer would have it
            // silently corrupted by the time something dereferences it later
            // (e.g. `type_params.items()[0].items` reading garbage) -- point
            // into the STABLE backing array (`proc.nodes`) instead.
            const stable_type_params = if (fnv.type_params != null) &proc.nodes.items()[node_i].node_variant.?.function.type_params.? else null;
            fns.put(name, .{
                .rtype = fn_rtype,
                .args = args_slice,
                .is_variadic = fnv.is_variadic,
                .is_async = fnv.is_async,
                .type_params = stable_type_params,
                .min_args = fn_min_args,
            }) catch {
                return TranspileError.MemoryAllocationFailed;
            };

            if (proc.import_alias) |alias| {
                const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                if (!fns.contains(alias_name)) {
                    fns.put(alias_name, .{
                        .rtype = fn_rtype,
                        .args = args_slice,
                        .is_variadic = fnv.is_variadic,
                        .is_async = fnv.is_async,
                        .type_params = stable_type_params,
                        .min_args = fn_min_args,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                } else {
                    self.allocator.free(alias_name);
                }
            }
        }

        // Some modules keep function nodes only in `owned_nodes`.
        for (proc.owned_nodes.items) |node_ptr| {
            const node = node_ptr.*;
            if (node.type != .Function or node.node_variant == null) continue;
            const fnv = node.node_variant.?.function;
            if (fnv.name == null) continue;
            const name = fnv.name.?.items;

            if (fns.contains(name)) {
                // See the note in the `proc.nodes` loop above: still owe the
                // alias-qualified key when this proc carries an import alias.
                try self.register_alias_qualified_from_existing(proc, fns, fnv, owned_args);
                continue;
            }

            const args_vec = fnv.args orelse utils.Vector(*ast.Node).init(proc.allocator);
            const args_items = args_vec.items();
            var args_slice = proc.allocator.alloc(CheckedType, args_items.len) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer proc.allocator.free(args_slice);

            var i: usize = 0;
            for (args_items) |arg_ptr| {
                const arg = arg_ptr.*;
                if (arg.type == .Variable and arg.node_variant != null) {
                    try self.register_generic_instantiations_from_dtype(arg.node_variant.?.variable.type);
                    args_slice[i] = try self.type_from_dtype_with_mangled(arg.node_variant.?.variable.type);
                } else {
                    args_slice[i] = .{ .base = .Unknown };
                }
                try self.register_generic_instantiation_from_checked_type(args_slice[i]);
                i += 1;
            }

            owned_args.append(args_slice) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            const fn_rtype: CheckedType = if (fnv.rtype) |rt| blk: {
                const rt_heap = try self.clone_dtype(&rt);
                try self.register_generic_instantiations_from_dtype(rt_heap);
                break :blk try self.type_from_dtype_with_mangled(rt_heap);
            } else .{ .base = .Void };
            try self.register_generic_instantiation_from_checked_type(fn_rtype);
            const fn_min_args = count_required_args_from_node(args_vec);
            // See the matching comment in the `proc.nodes` loop above: point
            // into `node_ptr` (already a stable pointer) instead of the
            // by-value `fnv`/`node` copies, which don't survive past this
            // loop iteration.
            const stable_type_params = if (fnv.type_params != null) &node_ptr.node_variant.?.function.type_params.? else null;
            fns.put(name, .{
                .rtype = fn_rtype,
                .args = args_slice,
                .is_variadic = fnv.is_variadic,
                .is_async = fnv.is_async,
                .type_params = stable_type_params,
                .min_args = fn_min_args,
            }) catch {
                return TranspileError.MemoryAllocationFailed;
            };

            if (proc.import_alias) |alias| {
                const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
                if (!fns.contains(alias_name)) {
                    fns.put(alias_name, .{
                        .rtype = fn_rtype,
                        .args = args_slice,
                        .is_variadic = fnv.is_variadic,
                        .is_async = fnv.is_async,
                        .type_params = stable_type_params,
                        .min_args = fn_min_args,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                } else {
                    self.allocator.free(alias_name);
                }
            }
        }

        // Impl methods are nested under `.Impl` nodes, not in `proc.nodes`.
        // Collect their generated function signatures too so method calls can be typechecked.
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            if (proc.impl_type_params(n)) |params| {
                var inst_keys = std.StringHashMap(bool).init(self.allocator);
                defer {
                    var it = inst_keys.iterator();
                    while (it.next()) |e| {
                        self.allocator.free(e.key_ptr.*);
                    }
                    inst_keys.deinit();
                }

                var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
                defer inst_list.deinit();
                const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
                try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);

                for (inst_list.items) |dt| {
                    if (dt.generic_args == null) continue;
                    const gargs = dt.generic_args.?.items();
                    if (gargs.len != params.count) continue;
                    if (!self.generic_args_are_concrete(params, gargs)) continue;
                    if (self.dtype_contains_type_param(dt, params)) continue;

                    const mangled = try self.type_name_mangled(dt);
                    defer self.allocator.free(mangled);
                    if (self.mangled_contains_type_param(mangled, params)) continue;
                    if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

                    for (im.methods.items()) |m| {
                        if (m.type != .Function or m.node_variant == null) continue;
                        const fnv = m.node_variant.?.function;
                        if (fnv.name == null) continue;
                        const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                        const spec_name = if (im.quirk_name) |qn|
                            (std.fmt.allocPrint(proc.allocator, "{s}__{s}__{s}", .{ mangled, qn.items, base }) catch {
                                return TranspileError.MemoryAllocationFailed;
                            })
                        else
                            (std.fmt.allocPrint(proc.allocator, "{s}__{s}", .{ mangled, base }) catch {
                                return TranspileError.MemoryAllocationFailed;
                            });

                        if (fns.contains(spec_name)) continue;

                        const args_vec = fnv.args orelse utils.Vector(*ast.Node).init(proc.allocator);
                        const args_items = args_vec.items();
                        var args_slice = proc.allocator.alloc(CheckedType, args_items.len) catch {
                            return TranspileError.MemoryAllocationFailed;
                        };
                        errdefer proc.allocator.free(args_slice);

                        var i: usize = 0;
                        for (args_items) |arg_ptr| {
                            const arg = arg_ptr.*;
                            if (arg.type == .Variable and arg.node_variant != null) {
                                try self.register_generic_instantiations_from_dtype(arg.node_variant.?.variable.type);
                                args_slice[i] = try self.type_from_dtype_with_subst(arg.node_variant.?.variable.type, params.*, gargs);
                            } else {
                                args_slice[i] = .{ .base = .Unknown };
                            }
                            try self.register_generic_instantiation_from_checked_type(args_slice[i]);
                            i += 1;
                        }

                        owned_args.append(args_slice) catch {
                            return TranspileError.MemoryAllocationFailed;
                        };
                        const fn_rtype: CheckedType = if (fnv.rtype) |rt| blk: {
                            const rt_heap = try self.clone_dtype(&rt);
                            try self.register_generic_instantiations_from_dtype(rt_heap);
                            break :blk try self.type_from_dtype_with_subst(rt_heap, params.*, gargs);
                        } else .{ .base = .Void };
                        try self.register_generic_instantiation_from_checked_type(fn_rtype);
                        fns.put(spec_name, .{
                            .rtype = fn_rtype,
                            .args = args_slice,
                            .is_variadic = fnv.is_variadic,
                            .is_async = fnv.is_async,
                            .type_params = null,
                            .min_args = count_required_args_from_node(args_vec),
                        }) catch {
                            return TranspileError.MemoryAllocationFailed;
                        };
                    }
                }

                continue;
            }
            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                const name = fnv.name.?.items;

                if (fns.contains(name)) continue;

                const args_vec = fnv.args orelse utils.Vector(*ast.Node).init(proc.allocator);
                const args_items = args_vec.items();
                var args_slice = proc.allocator.alloc(CheckedType, args_items.len) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                errdefer proc.allocator.free(args_slice);

                var i: usize = 0;
                for (args_items) |arg_ptr| {
                    const arg = arg_ptr.*;
                    if (arg.type == .Variable and arg.node_variant != null) {
                        try self.register_generic_instantiations_from_dtype(arg.node_variant.?.variable.type);
                        args_slice[i] = try self.type_from_dtype_with_mangled(arg.node_variant.?.variable.type);
                    } else {
                        args_slice[i] = .{ .base = .Unknown };
                    }
                    try self.register_generic_instantiation_from_checked_type(args_slice[i]);
                    i += 1;
                }

                owned_args.append(args_slice) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                const fn_rtype: CheckedType = if (fnv.rtype) |rt| blk: {
                    const rt_heap = try self.clone_dtype(&rt);
                    try self.register_generic_instantiations_from_dtype(rt_heap);
                    break :blk try self.type_from_dtype_with_mangled(rt_heap);
                } else .{ .base = .Void };
                try self.register_generic_instantiation_from_checked_type(fn_rtype);
                fns.put(name, .{
                    .rtype = fn_rtype,
                    .args = args_slice,
                    .is_variadic = fnv.is_variadic,
                    .is_async = fnv.is_async,
                    .type_params = null,
                    .min_args = count_required_args_from_node(args_vec),
                }) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
        }

        for (proc.children.items) |child| {
            try self.collect_fn_sigs(child, fns, owned_args);
        }
    }

    /// Post-pass over the whole process tree that registers alias-qualified
    /// function signatures for aliased re-imports that were deduped to a
    /// node-less STUB (see process_local_import: when a module is already
    /// globally parsed and then re-imported `as x`, only an empty stub child is
    /// created). Because the stub has no function nodes, `collect_fn_sigs`
    /// registers nothing for it, so `x.fn(...)` cannot infer its return type.
    /// Here we locate the real, parsed proc that owns the module (matched by
    /// canonical `input_file_path`) and mirror each of its bare `fns` entries
    /// under the stub's `alias__fn` key. Must run AFTER the full `collect_fn_sigs`
    /// walk so every bare signature is already present.
    fn register_alias_stub_sigs(self: *Self, proc: *Self, fns: *std.StringHashMap(FnSig)) TranspileError!void {
        const is_node_less = proc.nodes.items().len == 0 and proc.owned_nodes.items.len == 0;
        if (is_node_less) {
            if (proc.import_alias) |alias| {
                if (self.find_parsed_proc_by_path(proc.input_file_path)) |real| {
                    try self.mirror_alias_sigs_from_proc(real, alias, fns);
                }
            }
        }
        for (proc.children.items) |child| {
            try self.register_alias_stub_sigs(child, fns);
        }
    }

    /// Find the parsed process in the tree (rooted at `self`) whose
    /// `input_file_path` equals `path` and that actually carries function nodes.
    fn find_parsed_proc_by_path(self: *Self, path: []const u8) ?*Self {
        if ((self.nodes.items().len != 0 or self.owned_nodes.items.len != 0) and
            std.mem.eql(u8, self.input_file_path, path))
        {
            return self;
        }
        for (self.children.items) |child| {
            if (child.find_parsed_proc_by_path(path)) |found| return found;
        }
        return null;
    }

    /// Register `alias__fnname` for every top-level function of `src` proc,
    /// reusing the bare `fnname` signature already present in `fns`.
    fn mirror_alias_sigs_from_proc(self: *Self, src: *Self, alias: []const u8, fns: *std.StringHashMap(FnSig)) TranspileError!void {
        try self.mirror_alias_sigs_from_nodes(src.nodes.items(), alias, fns);
        try self.mirror_alias_sigs_from_nodes(src.owned_nodes.items, alias, fns);
    }

    fn mirror_alias_sigs_from_nodes(self: *Self, nodes: anytype, alias: []const u8, fns: *std.StringHashMap(FnSig)) TranspileError!void {
        for (nodes) |node_entry| {
            const node = switch (@typeInfo(@TypeOf(node_entry))) {
                .pointer => node_entry.*,
                else => node_entry,
            };
            if (node.type != .Function or node.node_variant == null) continue;
            const fnv = node.node_variant.?.function;
            if (fnv.name == null) continue;
            const name = fnv.name.?.items;
            const existing = fns.get(name) orelse continue;
            const alias_name = try self.make_alias_qualified_symbol_name(alias, name);
            if (fns.contains(alias_name)) {
                self.allocator.free(alias_name);
                continue;
            }
            fns.put(alias_name, existing) catch {
                self.allocator.free(alias_name);
                return TranspileError.MemoryAllocationFailed;
            };
        }
    }

    fn typecheck_all(self: *Self) TranspileError!void {
        var fns = std.StringHashMap(FnSig).init(self.allocator);
        defer fns.deinit();
        var owned_args = ArrayList([]CheckedType).init(self.allocator);
        defer {
            for (owned_args.items) |slice| self.allocator.free(slice);
            owned_args.deinit();
        }

        try self.collect_fn_sigs(self, &fns, &owned_args);
        try self.register_alias_stub_sigs(self, &fns);

        // Lenient mode (used by fls diagnostics): a single hard type error must NOT
        // suppress every unused-* diagnostic for the whole module. Typecheck each
        // module catching the first error, then still emit the unused warnings
        // (which only read `used`/`public` markers, populated as far as checking
        // reached), and re-raise the first recorded error at the end so the file
        // still shows its real type error too. Strict mode keeps aborting on the
        // first error as before.
        if (self.flags.warn_unused_lenient) {
            const LenientWalker = struct {
                fn walk(proc: *Self, fns_ref: *const std.StringHashMap(FnSig), first_err: *?TranspileError) void {
                    typecheck_module(proc, fns_ref) catch |e| {
                        if (first_err.* == null) first_err.* = e;
                        // Body checking aborted; still emit unused warnings best-effort.
                        proc.emit_unused_top_level_warnings() catch {};
                    };
                    for (proc.children.items) |child| {
                        walk(child, fns_ref, first_err);
                    }
                }
            };
            var first_err: ?TranspileError = null;
            LenientWalker.walk(self, &fns, &first_err);
            if (first_err) |e| return e;
            return;
        }

        // Check this module and all imported modules recursively.
        const Walker = struct {
            fn walk(proc: *Self, fns_ref: *const std.StringHashMap(FnSig)) TranspileError!void {
                try typecheck_module(proc, fns_ref);
                for (proc.children.items) |child| {
                    try walk(child, fns_ref);
                }
            }
        };
        try Walker.walk(self, &fns);
    }

    // Best-effort helper for LSP indexing: infer let types without failing the caller.
    // This avoids full transpilation while still updating AST variable types so
    // the index can expose concrete types for hover/completion.
    pub fn infer_let_types_best_effort(self: *Self) void {
        var fns = std.StringHashMap(FnSig).init(self.allocator);
        defer fns.deinit();
        var owned_args = ArrayList([]CheckedType).init(self.allocator);
        defer {
            for (owned_args.items) |slice| self.allocator.free(slice);
            owned_args.deinit();
        }

        self.collect_fn_sigs(self, &fns, &owned_args) catch return;
        self.register_alias_stub_sigs(self, &fns) catch return;

        // Ensure the type registry is populated so local type checks can resolve named types.
        self.collect_type_registry_all() catch return;

        var global_env = TypeEnv.init(self.allocator);
        defer global_env.deinit();
        global_env.push() catch return;

        // Infer let types for globals and seed the env where possible.
        for (self.nodes.items()) |*gn| {
            if (gn.type != .Variable or gn.node_variant == null) continue;
            const inferred_let_t = self.infer_let_variable_dtype(gn, &global_env, &fns) catch null;

            const v = gn.node_variant.?.variable;
            const vtype = if (inferred_let_t) |it| it else (self.type_from_dtype_with_mangled(v.type) catch continue);
            global_env.put_current(v.name.items, vtype) catch {};
        }

        // Infer let types inside function bodies (best-effort typechecking).
        for (self.nodes.items()) |node| {
            if (node.type != .Function or node.node_variant == null) continue;
            const fnv = node.node_variant.?.function;
            const fn_rtype: CheckedType = if (fnv.rtype) |rt|
                (self.type_from_dtype_with_mangled(&rt) catch CheckedType{ .base = .Unknown })
            else
                CheckedType{ .base = .Void };

            var fn_env = TypeEnv.init(self.allocator);
            defer fn_env.deinit();
            fn_env.push() catch {};

            // Seed globals into function scope for better inference.
            for (self.nodes.items()) |gn| {
                if (gn.type == .Variable and gn.node_variant != null and gn.binded == null) {
                    const v = gn.node_variant.?.variable;
                    const vtype = self.type_from_dtype_with_mangled(v.type) catch continue;
                    fn_env.put_current(v.name.items, vtype) catch {};
                }
            }

            // Seed args.
            if (fnv.args) |args| {
                for (args.items()) |arg_ptr| {
                    const arg = arg_ptr.*;
                    if (arg.type != .Variable or arg.node_variant == null) continue;
                    const v = arg.node_variant.?.variable;
                    const vtype = self.type_from_dtype_with_mangled(v.type) catch continue;
                    fn_env.put_current(v.name.items, vtype) catch {};
                }
            }

            if (fnv.is_variadic) {
                const vdt = self.make_vec_str_dtype() catch null;
                if (vdt) |dt| {
                    const vtype = self.type_from_dtype_with_mangled(dt) catch null;
                    if (vtype) |vt| fn_env.put_current("vargs", vt) catch {};
                }
            }

            if (fnv.body) |b| {
                const prev_async = self.current_fn_is_async;
                self.current_fn_is_async = fnv.is_async;
                defer self.current_fn_is_async = prev_async;
                self.check_body(b, &fn_env, &fns, fn_rtype) catch {};
            }
        }

        // Best-effort inference inside impl methods too.
        for (self.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            const self_base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            const self_type: CheckedType = .{ .base = .Unknown, .name = self_base, .mangled_name = im.type_name.items, .pointer_depth = 1 };
            const concrete_impl = mem.indexOf(u8, im.type_name.items, "__") != null;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                const fn_rtype: CheckedType = if (fnv.rtype) |rt|
                    (self.type_from_dtype_with_mangled(&rt) catch CheckedType{ .base = .Unknown })
                else
                    CheckedType{ .base = .Void };

                var fn_env = TypeEnv.init(self.allocator);
                defer fn_env.deinit();
                fn_env.push() catch {};

                // Seed globals.
                for (self.nodes.items()) |gn| {
                    if (gn.type == .Variable and gn.node_variant != null and gn.binded == null) {
                        const v = gn.node_variant.?.variable;
                        const vtype = self.type_from_dtype_with_mangled(v.type) catch continue;
                        fn_env.put_current(v.name.items, vtype) catch {};
                    }
                }

                // Seed implicit self.
                fn_env.put_current("self", self_type) catch {};

                // Seed args.
                if (fnv.args) |args| {
                    for (args.items()) |arg_ptr| {
                        const arg = arg_ptr.*;
                        if (arg.type != .Variable or arg.node_variant == null) continue;
                        const v = arg.node_variant.?.variable;
                        if (concrete_impl and mem.eql(u8, v.name.items, "self")) {
                            fn_env.put_current("self", self_type) catch {};
                            continue;
                        }
                        const vtype = self.type_from_dtype_with_mangled(v.type) catch continue;
                        fn_env.put_current(v.name.items, vtype) catch {};
                    }
                }

                if (fnv.is_variadic) {
                    const vdt = self.make_vec_str_dtype() catch null;
                    if (vdt) |dt| {
                        const vtype = self.type_from_dtype_with_mangled(dt) catch null;
                        if (vtype) |vt| fn_env.put_current("vargs", vt) catch {};
                    }
                }

                if (fnv.body) |b| {
                    const prev_async = self.current_fn_is_async;
                    self.current_fn_is_async = fnv.is_async;
                    defer self.current_fn_is_async = prev_async;
                    self.check_body(b, &fn_env, &fns, fn_rtype) catch {};
                }
            }
        }
    }

    fn typecheck_module(proc: *Self, fns: *const std.StringHashMap(FnSig)) TranspileError!void {
        var global_env = TypeEnv.init(proc.allocator);
        defer global_env.deinit();
        try global_env.push();

        // An enum with no variants is meaningless and lowers to an empty C `enum`,
        // which is invalid. Reject it cleanly at the front end.
        for (proc.nodes.items()) |node| {
            if (node.type != .Enum or node.node_variant == null) continue;
            const e = node.node_variant.?.enum_decl;
            if (e.variants.items().len == 0) {
                proc.report_type_error(node, "enum '{s}' must declare at least one variant", .{e.name.items});
                return TranspileError.TypeMismatch;
            }
        }

        for (proc.nodes.items()) |*gn| {
            if (gn.type != .Variable or gn.node_variant == null or gn.binded != null) continue;
            const inferred_let_t = try proc.infer_let_variable_dtype(gn, &global_env, fns);

            const v = gn.node_variant.?.variable;
            const vtype = if (inferred_let_t) |it| it else try proc.type_from_dtype_with_mangled(v.type);
            try proc.ensure_dtype_visible(gn.*, v.type, null);
            if (v.type.generic_args != null) {
                try proc.register_generic_instantiation(v.type);
            }
            if (inferred_let_t) |it| {
                try proc.register_generic_instantiation_from_checked_type(it);
            }
            try global_env.put_current_marked(v.name.items, vtype, gn);

            if (v.val) |val| {
                if (val.*.type == .CompoundInit) {
                    try proc.bind_compound_init_expected(val, vtype, &global_env, fns);
                }
                if (proc.expected_enum_name(vtype)) |enum_name| {
                    if (dot_shorthand_variant_name(val)) |_| {
                        _ = try proc.resolve_dot_shorthand_enum_variant(val, enum_name);
                    }
                }
                const init_t = try proc.infer_expr_type(val.*, &global_env, fns);
                if (is_known_type(vtype) and is_known_type(init_t) and !(try proc.can_implicit_coerce(vtype, init_t))) {
                    proc.report_type_error(gn.*, "type mismatch in initialization of '{s}'", .{v.name.items});
                    return TranspileError.TypeMismatch;
                }
                // uN/iN literal range/signedness check (advisory).
                proc.check_int_literal_range(v.type, val, gn.*);
            }
        }

        for (proc.nodes.items()) |node| {
            if (node.type != .Function or node.node_variant == null) continue;
            const fnv = node.node_variant.?.function;

            if (fnv.is_async and fnv.is_variadic) {
                proc.report_type_error(node, "async variadic functions are not supported yet", .{});
                return TranspileError.TypeMismatch;
            }

            // Default params must be trailing.
            try proc.validate_default_param_order(fnv.args, node);

            const fn_rtype: CheckedType = if (fnv.rtype) |rt| try proc.type_from_dtype_with_mangled(&rt) else CheckedType{ .base = .Void };

            var allow_params: ?[]const []const u8 = null;
            var allow_store: ?ArrayList([]const u8) = null;
            defer if (allow_store) |*s| s.deinit();
            if (fnv.type_params) |params| {
                var buf = ArrayList([]const u8).init(proc.allocator);
                for (params.items()) |p| {
                    buf.append(p.items) catch return TranspileError.MemoryAllocationFailed;
                }
                allow_store = buf;
                allow_params = allow_store.?.items;
            }

            if (fnv.rtype) |rt| {
                try proc.ensure_dtype_visible(node, &rt, allow_params);
            }

            var fn_env = TypeEnv.init(proc.allocator);
            defer fn_env.deinit();
            try fn_env.push();
            fn_env.set_type_params(allow_params);

            // Add module-level globals (nodes without binded context).
            for (proc.nodes.items()) |*gn| {
                if (gn.type == .Variable and gn.node_variant != null and gn.binded == null) {
                    const v = gn.node_variant.?.variable;
                    try fn_env.put_current_marked(v.name.items, try proc.type_from_dtype_with_mangled(v.type), gn);
                }
            }

            // Add args.
            if (fnv.args) |args| {
                for (args.items()) |arg_ptr| {
                    const arg = arg_ptr.*;
                    if (arg.type != .Variable or arg.node_variant == null) continue;
                    const v = arg.node_variant.?.variable;
                    try proc.ensure_dtype_visible(node, v.type, allow_params);
                    try fn_env.put_current_decl(v.name.items, try proc.type_from_dtype_with_mangled(v.type), arg_ptr);
                }
            }

            if (fnv.is_variadic) {
                const vdt = try proc.make_vec_str_dtype();
                try fn_env.put_current("vargs", try proc.type_from_dtype_with_mangled(vdt));
            }

            try proc.validate_parameter_defaults(fnv.args, node, &fn_env, fns);

            if (fnv.body) |body| {
                const prev_async = proc.current_fn_is_async;
                proc.current_fn_is_async = fnv.is_async;
                defer proc.current_fn_is_async = prev_async;
                const prev_owner_fn = proc.typecheck_owner_fn;
                proc.typecheck_owner_fn = if (fnv.name) |fname| proc.find_function_node(fname.items) else null;
                defer proc.typecheck_owner_fn = prev_owner_fn;
                try proc.check_body(body, &fn_env, fns, fn_rtype);

                proc.warn_unused_bindings_in_current_scope(&fn_env);

                // Missing-return check (top-level function only, NOT nested blocks): a
                // non-void function must return on every path, else the emitted C falls
                // off the end with an indeterminate value. This is a correctness warning
                // (like return_local_ptr) so it is NOT gated on -warn-unused.
                // `body_always_returns` is conservative (only provable fall-through fires).
                if (fn_rtype.base != .Void and is_known_type(fn_rtype) and !proc.body_always_returns(body)) {
                    proc.report_warning(.missing_return, node, "function may reach the end of its body without returning a value", .{});
                }
            }
        }

        // Impl methods live under `.Impl` nodes in `proc.owned_nodes`.
        // Typecheck them too, with an implicit `self` binding.
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            const self_base = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            const self_type: CheckedType = .{ .base = .Unknown, .name = self_base, .mangled_name = im.type_name.items, .pointer_depth = 1 };
            const concrete_impl = mem.indexOf(u8, im.type_name.items, "__") != null;

            var allow_params: ?[]const []const u8 = null;
            var allow_store: ?ArrayList([]const u8) = null;
            defer if (allow_store) |*s| s.deinit();
            if (im.type_params) |*params| {
                var buf = ArrayList([]const u8).init(proc.allocator);
                for (params.items()) |p| {
                    buf.append(p.items) catch return TranspileError.MemoryAllocationFailed;
                }
                allow_store = buf;
                allow_params = allow_store.?.items;
            } else if (proc.impl_type_params(n)) |params| {
                var buf = ArrayList([]const u8).init(proc.allocator);
                for (params.items()) |p| {
                    buf.append(p.items) catch return TranspileError.MemoryAllocationFailed;
                }
                allow_store = buf;
                allow_params = allow_store.?.items;
            }

            if (allow_params == null) {
                if (mem.indexOf(u8, im.type_name.items, "__")) |_| {
                    var buf = ArrayList([]const u8).init(proc.allocator);
                    var i: usize = 0;
                    var seg_start: usize = 0;
                    while (i + 1 < im.type_name.items.len) : (i += 1) {
                        if (im.type_name.items[i] == '_' and im.type_name.items[i + 1] == '_') {
                            if (seg_start != 0 and i > seg_start) {
                                buf.append(im.type_name.items[seg_start..i]) catch return TranspileError.MemoryAllocationFailed;
                            }
                            i += 1;
                            seg_start = i + 1;
                        }
                    }
                    if (seg_start != 0 and seg_start < im.type_name.items.len) {
                        buf.append(im.type_name.items[seg_start..]) catch return TranspileError.MemoryAllocationFailed;
                    }
                    if (buf.items.len > 0) {
                        allow_store = buf;
                        allow_params = allow_store.?.items;
                    } else {
                        buf.deinit();
                    }
                }
            }

            try proc.ensure_named_type_visible(n.*, im.type_name.items);
            if (im.quirk_name) |qn| {
                try proc.ensure_named_type_visible(n.*, qn.items);
            }

            for (im.methods.items()) |m_ptr| {
                const m = m_ptr.*;
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;

                if (fnv.is_async and fnv.is_variadic) {
                    proc.report_type_error(m, "async variadic methods are not supported yet", .{});
                    return TranspileError.TypeMismatch;
                }

                // Default params must be trailing. (The implicit leading `self` has no
                // default and precedes user params, so it never triggers a false positive.)
                try proc.validate_default_param_order(fnv.args, m);

                // A method may declare its OWN type param(s) in addition to the
                // impl's (`impl Box<T> { pub map<U>(U x) U { ... } }`) -- extend
                // the impl-level `allow_params` with the method's own for THIS
                // method's body only, so references to U (in its return type, arg
                // types, or operators like `x + x` inside its body) resolve as a
                // known in-scope type-param name rather than an unknown type.
                var method_allow_params = allow_params;
                var method_allow_store: ?ArrayList([]const u8) = null;
                defer if (method_allow_store) |*s| s.deinit();
                if (fnv.type_params) |*mparams| {
                    var buf = ArrayList([]const u8).init(proc.allocator);
                    if (allow_params) |ap| {
                        for (ap) |p| buf.append(p) catch return TranspileError.MemoryAllocationFailed;
                    }
                    for (mparams.items()) |p| {
                        buf.append(p.items) catch return TranspileError.MemoryAllocationFailed;
                    }
                    method_allow_store = buf;
                    method_allow_params = method_allow_store.?.items;
                }

                const fn_rtype: CheckedType = if (fnv.rtype) |rt| try proc.type_from_dtype_with_mangled(&rt) else CheckedType{ .base = .Void };

                if (fnv.rtype) |rt| {
                    try proc.ensure_dtype_visible(n.*, &rt, method_allow_params);
                }

                var fn_env = TypeEnv.init(proc.allocator);
                defer fn_env.deinit();
                try fn_env.push();
                fn_env.set_type_params(method_allow_params);

                // Add module-level globals.
                for (proc.nodes.items()) |*gn| {
                    if (gn.type == .Variable and gn.node_variant != null and gn.binded == null) {
                        const v = gn.node_variant.?.variable;
                        try fn_env.put_current_marked(v.name.items, try proc.type_from_dtype_with_mangled(v.type), gn);
                    }
                }

                // Add implicit `self`.
                try fn_env.put_current("self", self_type);

                // Add explicit args.
                if (fnv.args) |args| {
                    for (args.items()) |arg_ptr| {
                        const arg = arg_ptr.*;
                        if (arg.type != .Variable or arg.node_variant == null) continue;
                        const v = arg.node_variant.?.variable;
                        if (concrete_impl and mem.eql(u8, v.name.items, "self")) {
                            try fn_env.put_current("self", self_type);
                            continue;
                        }
                        try proc.ensure_dtype_visible(n.*, v.type, method_allow_params);
                        try fn_env.put_current_decl(v.name.items, try proc.type_from_dtype_with_mangled(v.type), arg_ptr);
                    }
                }

                if (fnv.body) |body| {
                    try proc.validate_parameter_defaults(fnv.args, m, &fn_env, fns);

                    const prev_async = proc.current_fn_is_async;
                    proc.current_fn_is_async = fnv.is_async;
                    defer proc.current_fn_is_async = prev_async;
                    const prev_owner_fn = proc.typecheck_owner_fn;
                    proc.typecheck_owner_fn = m_ptr;
                    defer proc.typecheck_owner_fn = prev_owner_fn;
                    try proc.check_body(body, &fn_env, fns, fn_rtype);

                    proc.warn_unused_bindings_in_current_scope(&fn_env);

                    // Missing-return check for methods (see the free-function site above).
                    if (fn_rtype.base != .Void and is_known_type(fn_rtype) and !proc.body_always_returns(body)) {
                        proc.report_warning(.missing_return, m, "method may reach the end of its body without returning a value", .{});
                    }
                }
            }
        }

        // Visit compound field types. Without this, a type used *only* as a
        // compound field (e.g. `compound CliArgs { Map<str,str> opts; }`) is
        // never run through `ensure_dtype_visible`, so the import that provides
        // the field type is wrongly reported as unused. `ensure_dtype_visible`
        // recurses into generic args, so `Map<str,str>` marks `std.map` used and
        // validates `str`. The compound's own type params are passed as the
        // `allow` list so `T`/`K`/`V` are not treated as unknown types.
        for (proc.nodes.items()) |*node| {
            if (node.type != .Compound or node.node_variant == null) continue;
            const comp = node.node_variant.?.compound;

            var allow_params: ?[]const []const u8 = null;
            var allow_store: ?ArrayList([]const u8) = null;
            defer if (allow_store) |*s| s.deinit();
            if (comp.type_params) |*params| {
                var buf = ArrayList([]const u8).init(proc.allocator);
                for (params.items()) |p| {
                    buf.append(p.items) catch return TranspileError.MemoryAllocationFailed;
                }
                allow_store = buf;
                allow_params = allow_store.?.items;
            }

            for (comp.fields.items()) |f| {
                try proc.ensure_dtype_visible(node.*, f.dtype, allow_params);
            }
        }

        // `test "name" { ... }` blocks: only type-checked in `fun test` mode
        // (an ordinary compile ignores them entirely, not even type-checking
        // their bodies, so a program doesn't need its test dependencies to
        // compile just to run normally) -- OR when `emit_unused_warnings` is
        // set (fls's lenient diagnostic pass, `-warn-unused-lenient`, which
        // shells out WITHOUT `-test`). Without this, a private helper used
        // only from a test block (e.g. a small `_lex` wrapper around
        // `tokenize` for test fixtures) was always reported as "unused" by
        // fls, since its only call site was never even visited.
        if (proc.flags.test_mode or proc.flags.emit_unused_warnings) {
            for (proc.nodes.items()) |node| {
                if (node.type != .Test or node.node_variant == null) continue;
                const tv = node.node_variant.?.test_decl;

                var test_env = TypeEnv.init(proc.allocator);
                defer test_env.deinit();
                try test_env.push();

                for (proc.nodes.items()) |*gn| {
                    if (gn.type == .Variable and gn.node_variant != null and gn.binded == null) {
                        const v = gn.node_variant.?.variable;
                        try test_env.put_current_marked(v.name.items, try proc.type_from_dtype_with_mangled(v.type), gn);
                    }
                }

                try proc.check_body(tv.body, &test_env, fns, CheckedType{ .base = .Void });
                proc.warn_unused_bindings_in_current_scope(&test_env);
            }
        }

        // `fuzz "name" (data, len) { ... }` blocks: same reasoning as
        // `test` above (only type-checked in `fun fuzz` mode, or fls's
        // lenient pass), but ALSO seeds the two fixed-type synthetic
        // parameters into the body's own env first, exactly the way a
        // real function's own `args` get seeded (see `typecheck_module`'s
        // function-body loop above) -- `data_param`/`len_param` are
        // themselves `Variable` nodes (see `parse_fuzz`), not bare names,
        // for exactly this reason.
        if (proc.flags.fuzz_mode or proc.flags.emit_unused_warnings) {
            for (proc.nodes.items()) |node| {
                if (node.type != .Fuzz or node.node_variant == null) continue;
                const fv = node.node_variant.?.fuzz_decl;

                var fuzz_env = TypeEnv.init(proc.allocator);
                defer fuzz_env.deinit();
                try fuzz_env.push();

                for (proc.nodes.items()) |*gn| {
                    if (gn.type == .Variable and gn.node_variant != null and gn.binded == null) {
                        const v = gn.node_variant.?.variable;
                        try fuzz_env.put_current_marked(v.name.items, try proc.type_from_dtype_with_mangled(v.type), gn);
                    }
                }

                inline for (.{ fv.data_param, fv.len_param }) |param_node| {
                    const v = param_node.node_variant.?.variable;
                    try fuzz_env.put_current_decl(v.name.items, try proc.type_from_dtype_with_mangled(v.type), param_node);
                }

                try proc.check_body(fv.body, &fuzz_env, fns, CheckedType{ .base = .Void });
                proc.warn_unused_bindings_in_current_scope(&fuzz_env);
            }
        }

        try proc.run_concurrency_lints();
        try proc.emit_unused_top_level_warnings();
    }

    /// Static concurrency lints for the `fork` keyword. Conservative by design:
    /// only fires on the high-confidence structural shape so correct programs are
    /// never flagged. Currently detects `shared_mutable_capture_race`: a forked
    /// `async fun` receives a pointer to a compound that has NO internal `Mutex`
    /// field (i.e. is not self-synchronizing, unlike `Channel`/`WaitGroup`) and
    /// mutates one of that pointee's fields, while the SAME pointer is handed to
    /// multiple concurrently-live forked tasks — the classic unsynchronized shared
    /// mutable state race (e.g. sharing `&rand` across forked workers). Gated on
    /// the same flag as the other advisory lints and honors `allow`/`expect`.
    fn run_concurrency_lints(proc: *Self) TranspileError!void {
        if (proc.is_importing or !proc.flags.emit_unused_warnings) return;

        for (proc.nodes.items()) |*node| {
            if (node.type != .Function or node.node_variant == null) continue;
            const fnv = node.node_variant.?.function;
            if (fnv.body) |body| {
                try proc.lint_forks_in_body(body);
                proc.lint_channel_capacity_in_body(body);
            }
        }
        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            for (n.node_variant.?.impl.methods.items()) |m_ptr| {
                const m = m_ptr.*;
                if (m.type != .Function or m.node_variant == null) continue;
                if (m.node_variant.?.function.body) |body| {
                    try proc.lint_forks_in_body(body);
                    proc.lint_channel_capacity_in_body(body);
                }
            }
        }
    }

    /// Channel-capacity static lint (MVP): flag a bounded channel that receives
    /// more BLOCKING sends than its capacity with no concurrent receiver, so the
    /// producer blocks forever. Conservative to the point of zero false positives:
    /// only fires for the straight-line shape where a channel local is created
    /// with a literal `channel_new_cap(_, C)` and then gets > C top-level
    /// `ch <- v` sends BEFORE any `fork` is spawned and before any `ch.recv()` /
    /// `ch.close()` — i.e. a single-threaded producer that provably overflows its
    /// own buffer (e.g. `let c = channel_new_cap(0, 1); c <- 1; c <- 2; c <- 3;`).
    /// Anything with a prior fork, a receive, a loop, or a non-literal capacity is
    /// left alone (those may have a concurrent drainer the lint can't see).
    fn lint_channel_capacity_in_body(self: *Self, body: *ast.Node) void {
        if (body.type != .Body or body.node_variant == null) return;
        const stmts = body.node_variant.?.body.statements.items();

        // channel name -> literal capacity (only channels created in THIS body).
        var caps = std.StringHashMap(i64).init(self.allocator);
        defer caps.deinit();
        // channel name -> top-level blocking-send count seen so far.
        var sends = std.StringHashMap(i64).init(self.allocator);
        defer sends.deinit();
        // Once any fork appears, a concurrent receiver may exist — stop analyzing.
        var forked = false;
        // Channels that have been received-from / closed at top level are exempt.
        var drained = std.StringHashMap(void).init(self.allocator);
        defer drained.deinit();

        for (stmts) |s| {
            if (forked) break;
            switch (s.type) {
                .StatementFork => {
                    forked = true;
                },
                .Variable => {
                    const v = s.node_variant.?.variable;
                    if (v.val) |val| {
                        if (self.channel_new_cap_literal(val)) |c| {
                            caps.put(v.name.items, c) catch {};
                            sends.put(v.name.items, 0) catch {};
                        }
                    }
                },
                .Expression => {
                    // Assignment form `c = channel_new_cap(...)`, or a channel op.
                    const e = s.node_variant.?.exp;
                    if (mem.eql(u8, e.op, "=")) {
                        if (e.left) |l| {
                            if (l.type == .Identifier and l.data != null) {
                                if (e.right) |r| {
                                    if (self.channel_new_cap_literal(r)) |c| {
                                        caps.put(l.data.?.sval.items, c) catch {};
                                        sends.put(l.data.?.sval.items, 0) catch {};
                                    }
                                }
                            }
                        }
                    } else if (channel_op_of(s)) |op| {
                        if (mem.eql(u8, op.method, "send")) {
                            if (sends.getPtr(op.name)) |sp| sp.* += 1;
                        }
                    }
                },
                else => {},
            }
        }

        // A receive or close ANYWHERE in the body (including on a `let x = <- c`
        // RHS, in a nested block, or after the sends) means the buffer is drained,
        // so exempt that channel — we only flag a provably one-way over-send.
        collect_channel_drainers(body, &drained);

        if (forked) return; // a concurrent receiver may exist; don't guess.
        var it = caps.iterator();
        while (it.next()) |entry| {
            const name = entry.key_ptr.*;
            const cap = entry.value_ptr.*;
            if (drained.contains(name)) continue;
            const n_sends = sends.get(name) orelse 0;
            if (cap >= 0 and n_sends > cap) {
                self.report_warning(
                    .channel_capacity_overflow,
                    body.*,
                    "possible deadlock: {d} blocking send(s) into channel '{s}' of capacity {d} with no concurrent receiver; the producer will block once the buffer is full. Increase the capacity or receive concurrently (e.g. via fork).",
                    .{ n_sends, name, cap },
                );
            }
        }
    }

    /// Walk a function body collecting `fork` statements and, for each, count how
    /// many times the SAME `&var` pointer argument is forked (across the whole
    /// body, including inside loops — a fork inside a `for` is treated as spawning
    /// many concurrent copies). A shared pointer forked 2+ times (or once inside a
    /// loop) into a mutating, unsynchronized-compound async fn is flagged.
    const ForkOccurrence = struct { node: *ast.Node, in_loop: bool };

    fn lint_forks_in_body(proc: *Self, body: *ast.Node) TranspileError!void {
        // Collect (fork node, in_loop) pairs.
        var forks = ArrayList(ForkOccurrence).init(proc.allocator);
        defer forks.deinit();
        collect_fork_stmts(body, false, &forks);
        if (forks.items.len == 0) return;

        // Count occurrences of each shared `&var` name across all forks.
        var shared_counts = std.StringHashMap(u32).init(proc.allocator);
        defer shared_counts.deinit();
        for (forks.items) |f| {
            const call = f.node.node_variant.?.statement.fork_stmt.expr;
            var call_args = ArrayList(*ast.Node).init(proc.allocator);
            defer call_args.deinit();
            proc.fork_call_args(call, &call_args);
            for (call_args.items) |arg_ptr| {
                if (addr_of_operand_name(arg_ptr.*)) |vname| {
                    const bump: u32 = if (f.in_loop) 2 else 1;
                    const gop = shared_counts.getOrPut(vname) catch continue;
                    if (!gop.found_existing) gop.value_ptr.* = 0;
                    gop.value_ptr.* += bump;
                }
            }
        }

        // Now warn on each fork whose `&var` arg is shared concurrently and lands
        // on a mutated, unsynchronized compound parameter.
        for (forks.items) |f| {
            const call = f.node.node_variant.?.statement.fork_stmt.expr;
            const callee = fork_call_callee_name(call) orelse continue;
            var call_args = ArrayList(*ast.Node).init(proc.allocator);
            defer call_args.deinit();
            proc.fork_call_args(call, &call_args);
            const target = proc.find_async_fn_node(callee) orelse continue;
            const tfnv = target.node_variant.?.function;
            const tparams = tfnv.args orelse continue;
            const tbody = tfnv.body orelse continue;

            const params = tparams.items();
            var i: usize = 0;
            while (i < call_args.items.len and i < params.len) : (i += 1) {
                const vname = addr_of_operand_name(call_args.items[i].*) orelse continue;
                const shared = (shared_counts.get(vname) orelse 0) >= 2;
                if (!shared) continue;

                const param = params[i].*;
                if (param.type != .Variable or param.node_variant == null) continue;
                const pv = param.node_variant.?.variable;
                if (pv.type.pointer_depth == 0) continue; // not a pointer param
                const pname = pv.name.items;
                const compound_name = base_compound_type_name(pv.type.type_str.items);
                if (proc.compound_is_self_synchronizing(compound_name)) continue; // safe to share
                if (!body_writes_param_field(tbody, pname)) continue; // no mutation -> read-only share is fine

                proc.report_warning(
                    .shared_mutable_capture_race,
                    f.node.*,
                    "data race: '&{s}' ({s}) is shared across concurrently forked '{s}' tasks and mutated without synchronization; guard it with a Mutex or give each task its own copy",
                    .{ vname, compound_name, callee },
                );
                // Continue scanning the remaining args: several distinct shared
                // objects can each race, and reporting only the first would hide the
                // others (e.g. flagging `wg` must not mask the real `r` race).
            }
        }

        // Deadlock lint: a WaitGroup created with a literal `wait_group_new(0)` has
        // a signalling channel clamped to capacity 1, so once more than a bufferful
        // of tasks call `done()` before `wait()` starts draining (the typical
        // fork-in-a-loop-then-wait shape), the extra `done()` calls BLOCK and the
        // program can deadlock when the number of in-flight forks is large. Flag it
        // so the size is fixed at compile time rather than hanging at runtime.
        var zerocap_wgs = std.StringHashMap(void).init(proc.allocator);
        defer zerocap_wgs.deinit();
        collect_zero_cap_wait_groups(body, &zerocap_wgs);
        if (zerocap_wgs.count() != 0) {
            for (forks.items) |f| {
                if (!f.in_loop) continue; // only a loop can overflow the buffer
                const call = f.node.node_variant.?.statement.fork_stmt.expr;
                var call_args = ArrayList(*ast.Node).init(proc.allocator);
                defer call_args.deinit();
                proc.fork_call_args(call, &call_args);
                for (call_args.items) |arg_ptr| {
                    const vname = addr_of_operand_name(arg_ptr.*) orelse continue;
                    if (!zerocap_wgs.contains(vname)) continue;
                    // add() grows the signalling buffer to match, so a
                    // wait_group_new(0) that's paired with add() isn't the
                    // "clamped to capacity 1 forever" hazard this lint exists
                    // to catch.
                    if (body_calls_wait_group_add(body, vname)) continue;
                    proc.report_warning(
                        .blocking_fork_deadlock,
                        f.node.*,
                        "possible deadlock: WaitGroup '{s}' was created with wait_group_new(0) (signal buffer capacity 1) but is done()'d from tasks forked in a loop; size it to the number of tasks (wait_group_new(count)) so done() never blocks before wait() drains",
                        .{vname},
                    );
                    break;
                }
            }
        }
    }

    /// Collect names of WaitGroup locals in `body` initialized with a literal
    /// `wait_group_new(0)` — the pattern whose signal buffer is clamped to 1 and
    /// therefore blocks `done()` once a loopful of tasks signal before `wait()`.
    fn collect_zero_cap_wait_groups(node: *ast.Node, out: *std.StringHashMap(void)) void {
        const nv = node.node_variant orelse return;
        switch (node.type) {
            .Body => {
                for (nv.body.statements.items()) |s| collect_zero_cap_wait_groups(s, out);
            },
            .Variable => {
                const v = nv.variable;
                if (v.val) |val| {
                    if (call_is_wait_group_new_zero(val)) {
                        out.put(v.name.items, {}) catch {};
                    }
                }
            },
            .Expression => {
                // `WaitGroup wg = wait_group_new(0)` may also appear as an
                // assignment expression `wg = wait_group_new(0)`.
                const e = nv.exp;
                if (mem.eql(u8, e.op, "=")) {
                    if (e.left) |l| {
                        if (l.type == .Identifier and l.data != null) {
                            if (e.right) |r| {
                                if (call_is_wait_group_new_zero(r)) out.put(l.data.?.sval.items, {}) catch {};
                            }
                        }
                    }
                }
            },
            else => {},
        }
    }

    /// True when `expr` is a call `wait_group_new(0)` with a literal `0` argument.
    fn call_is_wait_group_new_zero(expr: *ast.Node) bool {
        if (expr.type != .Expression or expr.node_variant == null) return false;
        const e = expr.node_variant.?.exp;
        if (!mem.eql(u8, e.op, "()")) return false;
        const callee = e.left orelse return false;
        if (callee.type != .Identifier or callee.data == null) return false;
        if (!mem.eql(u8, callee.data.?.sval.items, "wait_group_new")) return false;
        // Argument must be the literal 0.
        const args = e.right orelse return false;
        var inner = args;
        if (inner.type == .ExpressionParenthesis and inner.node_variant != null) {
            inner = inner.node_variant.?.paren.exp;
        }
        if (inner.type == .Number and inner.data != null) {
            return switch (inner.data.?) {
                .llnum => |v| v == 0,
                .lnum => |v| v == 0,
                .inum => |v| v == 0,
                .dnum => |v| v == 0,
                else => false,
            };
        }
        return false;
    }

    /// True when `body` contains a call `<vname>.add(...)` anywhere (any
    /// nesting depth — inside a fork loop, an `if`, etc.). `WaitGroup.add()`
    /// grows its signalling buffer to match the new expected count (see
    /// std.task.fn), so a `wait_group_new(0)` that's always paired with
    /// `add()` before use is NOT the "clamped to capacity 1 forever" hazard
    /// `collect_zero_cap_wait_groups` exists to catch — only a
    /// `wait_group_new(0)` that never grows its own buffer is.
    fn body_calls_wait_group_add(node: *ast.Node, vname: []const u8) bool {
        const nv = node.node_variant orelse return false;
        switch (node.type) {
            .Body => {
                for (nv.body.statements.items()) |s| {
                    if (body_calls_wait_group_add(s, vname)) return true;
                }
                return false;
            },
            .StatementIf => return body_calls_wait_group_add(nv.statement.if_stmt.body, vname),
            .StatementElseIf => return body_calls_wait_group_add(nv.statement.elif_stmt.body, vname),
            .StatementElse => return body_calls_wait_group_add(nv.statement.else_stmt.body, vname),
            .StatementFor => {
                const body_node = switch (nv.statement.for_stmt) {
                    .cond => |c| c.body,
                    .iter => |it| it.body,
                    .range => |r| r.body,
                };
                return body_calls_wait_group_add(body_node, vname);
            },
            .StatementFit => {
                for (nv.statement.fit_stmt.branches.items()) |br| {
                    if (body_calls_wait_group_add(br.body, vname)) return true;
                }
                return false;
            },
            .Expression => {
                const e = nv.exp;
                if (!mem.eql(u8, e.op, "()")) return false;
                const callee = e.left orelse return false;
                if (callee.type != .Expression or callee.node_variant == null) return false;
                const dot = callee.node_variant.?.exp;
                if (!mem.eql(u8, dot.op, ".")) return false;
                const recv = dot.left orelse return false;
                const method = dot.right orelse return false;
                if (recv.type != .Identifier or recv.data == null) return false;
                if (method.type != .Identifier or method.data == null) return false;
                return mem.eql(u8, recv.data.?.sval.items, vname) and mem.eql(u8, method.data.?.sval.items, "add");
            },
            else => return false,
        }
    }

    /// If `expr` is a `channel_new_cap(<buffering>, <cap>)` call whose CAPACITY
    /// (2nd) argument is a compile-time integer literal, return that capacity.
    fn channel_new_cap_literal(self: *Self, expr: *ast.Node) ?i64 {
        if (expr.type != .Expression or expr.node_variant == null) return null;
        const e = expr.node_variant.?.exp;
        if (!mem.eql(u8, e.op, "()")) return null;
        const callee = e.left orelse return null;
        if (callee.type != .Identifier or callee.data == null) return null;
        if (!mem.eql(u8, callee.data.?.sval.items, "channel_new_cap")) return null;
        const args_node = e.right orelse return null;
        var flat = ArrayList(*ast.Node).init(self.allocator);
        defer flat.deinit();
        self.flatten_call_args_ptr(args_node, &flat) catch return null;
        if (flat.items.len != 2) return null;
        return self.const_fold_int(flat.items[1].*);
    }

    /// If `node` is a channel operation `ch.<method>(...)` (the desugared form of
    /// `ch <- v` -> `ch.send(v)` and `<- ch` -> `ch.recv()`), return
    /// `.{ name, method }` for the base channel identifier and method name.
    const ChannelOp = struct { name: []const u8, method: []const u8 };
    fn channel_op_of(node: *const ast.Node) ?ChannelOp {
        if (node.type != .Expression or node.node_variant == null) return null;
        const e = node.node_variant.?.exp;
        if (!mem.eql(u8, e.op, "()")) return null;
        const callee = e.left orelse return null;
        if (callee.type != .Expression or callee.node_variant == null) return null;
        const ce = callee.node_variant.?.exp;
        if (!mem.eql(u8, ce.op, ".")) return null;
        const recv = ce.left orelse return null;
        const meth = ce.right orelse return null;
        if (recv.type != .Identifier or recv.data == null) return null;
        if (meth.type != .Identifier or meth.data == null) return null;
        return .{ .name = recv.data.?.sval.items, .method = meth.data.?.sval.items };
    }

    /// Recursively record every channel that is received-from (`recv`) or closed
    /// anywhere under `node`, so the capacity lint can exempt drained channels
    /// regardless of where the receive appears (top-level stmt, `let x = <- c`
    /// RHS, a nested block, etc.). Conservative on purpose — any receive at all
    /// suppresses the one-way-over-send warning.
    fn collect_channel_drainers(node: *const ast.Node, out: *std.StringHashMap(void)) void {
        if (channel_op_of(node)) |op| {
            if (mem.eql(u8, op.method, "recv") or mem.eql(u8, op.method, "close")) {
                out.put(op.name, {}) catch {};
            }
        }
        const nv = node.node_variant orelse return;
        switch (node.type) {
            .Body => for (nv.body.statements.items()) |s| collect_channel_drainers(s, out),
            .Variable => if (nv.variable.val) |val| collect_channel_drainers(val, out),
            .Expression => {
                if (nv.exp.left) |l| collect_channel_drainers(l, out);
                if (nv.exp.right) |r| collect_channel_drainers(r, out);
            },
            .ExpressionParenthesis => collect_channel_drainers(nv.paren.exp, out),
            .Unary => collect_channel_drainers(nv.unary.operand, out),
            .StatementIf => collect_channel_drainers(nv.statement.if_stmt.body, out),
            .StatementElseIf => collect_channel_drainers(nv.statement.elif_stmt.body, out),
            .StatementElse => collect_channel_drainers(nv.statement.else_stmt.body, out),
            .StatementFor => {
                const b = switch (nv.statement.for_stmt) {
                    .cond => |c| c.body,
                    .range => |r| r.body,
                    .iter => |it| it.body,
                };
                collect_channel_drainers(b, out);
            },
            .StatementDefer => collect_channel_drainers(nv.statement.defer_stmt.body, out),
            else => {},
        }
    }

    /// Recursively collect `fork` statements from a body, tracking whether each is
    /// lexically inside a loop (a fork in a loop spawns many concurrent instances).
    fn collect_fork_stmts(node: *ast.Node, in_loop: bool, out: *ArrayList(ForkOccurrence)) void {
        const nv = node.node_variant orelse return;
        switch (node.type) {
            .StatementFork => {
                out.append(.{ .node = node, .in_loop = in_loop }) catch {};
            },
            .Body => {
                for (nv.body.statements.items()) |s| collect_fork_stmts(s, in_loop, out);
            },
            .StatementFor => {
                const body = switch (nv.statement.for_stmt) {
                    .cond => |c| c.body,
                    .range => |r| r.body,
                    .iter => |it| it.body,
                };
                collect_fork_stmts(body, true, out);
            },
            .StatementIf => collect_fork_stmts(nv.statement.if_stmt.body, in_loop, out),
            .StatementElseIf => collect_fork_stmts(nv.statement.elif_stmt.body, in_loop, out),
            .StatementElse => collect_fork_stmts(nv.statement.else_stmt.body, in_loop, out),
            else => {},
        }
    }

    /// Extract the callee function name from a `fork <call>` expression.
    /// Extract the callee function name from a `fork <call>` expression. The call
    /// is an `.Expression` with op `"()"`, `left` = the callee identifier and
    /// `right` = the parenthesized argument list (see how calls are parsed).
    fn fork_call_callee_name(call: *ast.Node) ?[]const u8 {
        if (call.type == .Function and call.node_variant != null) {
            if (call.node_variant.?.function.name) |nm| return nm.items;
        }
        if (call.type == .Expression and call.node_variant != null) {
            const e = call.node_variant.?.exp;
            if (mem.eql(u8, e.op, "()")) {
                if (e.left) |l| {
                    if (l.type == .Identifier and l.data != null) return l.data.?.sval.items;
                }
            }
        }
        return null;
    }

    /// Collect the flattened argument nodes from a `fork <call>` expression into
    /// `out` (top-level comma-separated args of the `()` call).
    fn fork_call_args(proc: *Self, call: *ast.Node, out: *ArrayList(*ast.Node)) void {
        if (call.type == .Function and call.node_variant != null) {
            const f = call.node_variant.?.function;
            if (f.args) |args| {
                for (args.items()) |a| out.append(a) catch {};
            }
            return;
        }
        if (call.type == .Expression and call.node_variant != null) {
            const e = call.node_variant.?.exp;
            if (mem.eql(u8, e.op, "()")) {
                if (e.right) |r| proc.flatten_call_args_ptr(r, out) catch {};
            }
        }
    }

    /// If `node` is an `&x` (address-of) unary on a plain identifier, return `x`.
    fn addr_of_operand_name(node: ast.Node) ?[]const u8 {
        if (node.type != .Unary or node.node_variant == null) return null;
        const u = node.node_variant.?.unary;
        if (!mem.eql(u8, u.op, "&")) return null;
        const op = u.operand;
        if (op.*.type == .Identifier and op.*.data != null) return op.*.data.?.sval.items;
        return null;
    }

    /// Find a top-level `async fun` node by name in this module.
    fn find_async_fn_node(proc: *Self, name: []const u8) ?*ast.Node {
        for (proc.nodes.items()) |*n| {
            if (n.type != .Function or n.node_variant == null) continue;
            const f = n.node_variant.?.function;
            if (!f.is_async) continue;
            if (f.name) |nm| {
                if (mem.eql(u8, nm.items, name)) return n;
            }
        }
        return null;
    }

    /// Strip pointer/array/generic decoration to the base compound type name.
    fn base_compound_type_name(type_str: []const u8) []const u8 {
        var s = std.mem.trim(u8, type_str, " \t\r\n");
        if (std.mem.indexOfScalar(u8, s, '<')) |lt| s = s[0..lt];
        // Trim trailing `*` and whitespace.
        while (s.len > 0 and (s[s.len - 1] == '*' or s[s.len - 1] == ' ' or s[s.len - 1] == '\t')) s = s[0 .. s.len - 1];
        return std.mem.trim(u8, s, " \t\r\n");
    }

    /// True when the named compound is SELF-SYNCHRONIZING — safe to share across
    /// concurrent tasks — so it should not be flagged as a data race. This holds
    /// when the type is itself a known synchronization primitive (`Mutex`,
    /// `Channel`, `WaitGroup`) or transitively contains a `Mutex`/`Channel` field
    /// (e.g. a `Channel` carries a `Mutex mu`; a `WaitGroup` carries a signalling
    /// `Channel`). Only plain data compounds with no internal synchronization
    /// (like `Rand`, which is just `num state`) fall through to the race check.
    fn compound_is_self_synchronizing(proc: *Self, compound_name: []const u8) bool {
        if (mem.eql(u8, compound_name, "Mutex") or
            mem.eql(u8, compound_name, "Channel") or
            mem.eql(u8, compound_name, "WaitGroup"))
        {
            return true;
        }
        const reg = proc.root_registry() orelse return false;
        const cnode = reg.compounds_by_name.get(compound_name) orelse return false;
        if (cnode.node_variant == null) return false;
        for (cnode.node_variant.?.compound.fields.items()) |field| {
            const ft = base_compound_type_name(field.dtype.type_str.items);
            if (mem.eql(u8, ft, "Mutex") or mem.eql(u8, ft, "Channel")) return true;
        }
        return false;
    }

    /// True when `body` may MUTATE the pointee reached through pointer parameter
    /// `param` — either a direct field assignment `param.field = ...` OR a method
    /// call `param.method(...)`. A method on a non-Mutex compound can mutate `self`
    /// (e.g. `r.next()` advancing a PRNG's state), and the caller (`run_concurrency_lints`)
    /// already restricts this to shared, unsynchronized compounds, so treating any
    /// method call on the shared receiver as a potential unsynchronized write is the
    /// right conservative signal for a data-race lint.
    fn body_writes_param_field(body: *ast.Node, param: []const u8) bool {
        return node_writes_param_field(body, param);
    }

    fn node_writes_param_field(node: *ast.Node, param: []const u8) bool {
        if (node.node_variant == null) return false;
        switch (node.type) {
            .Body => {
                for (node.node_variant.?.body.statements.items()) |s| {
                    if (node_writes_param_field(s, param)) return true;
                }
                return false;
            },
            .Expression => {
                const exp = node.node_variant.?.exp;
                // Assignment `param.field = ...` (or compound-assign): LHS is a `.`
                // access whose base identifier is `param`.
                if (is_assignment_op(exp.op)) {
                    if (exp.left) |lhs| {
                        if (expr_base_is_ident(lhs, param)) return true;
                    }
                }
                // Method call `param.method(...)`: an `()`-call expression whose
                // callee (left) is a `.`-access chain rooted at `param`. A method
                // on a non-Mutex compound can mutate `self` (e.g. `r.next()`), so
                // treat it as a potential unsynchronized write. (The receiver may
                // also be reached through the `.`-expr's own right operand being an
                // invocation, so check both shapes.)
                if (mem.eql(u8, exp.op, "()")) {
                    if (exp.left) |callee| {
                        if (callee.type == .Expression and callee.node_variant != null) {
                            const ce = callee.node_variant.?.exp;
                            if (mem.eql(u8, ce.op, ".")) {
                                if (ce.left) |recv| {
                                    if (expr_base_is_ident(recv, param)) return true;
                                }
                            }
                        }
                    }
                }
                if (mem.eql(u8, exp.op, ".")) {
                    if (exp.left) |l| {
                        if (expr_base_is_ident(l, param)) {
                            if (exp.right) |r| {
                                if (expr_is_invocation(r)) return true;
                            }
                        }
                    }
                }
                if (exp.left) |l| {
                    if (node_writes_param_field(l, param)) return true;
                }
                if (exp.right) |r| {
                    if (node_writes_param_field(r, param)) return true;
                }
                return false;
            },
            .StatementIf => return node_writes_param_field(node.node_variant.?.statement.if_stmt.body, param),
            .StatementElseIf => return node_writes_param_field(node.node_variant.?.statement.elif_stmt.body, param),
            .StatementElse => return node_writes_param_field(node.node_variant.?.statement.else_stmt.body, param),
            .StatementFor => {
                const body = switch (node.node_variant.?.statement.for_stmt) {
                    .cond => |c| c.body,
                    .range => |r| r.body,
                    .iter => |it| it.body,
                };
                return node_writes_param_field(body, param);
            },
            .StatementDefer => return node_writes_param_field(node.node_variant.?.statement.defer_stmt.body, param),
            else => return false,
        }
    }

    fn is_assignment_op(op: []const u8) bool {
        return mem.eql(u8, op, "=") or mem.eql(u8, op, "+=") or mem.eql(u8, op, "-=") or
            mem.eql(u8, op, "*=") or mem.eql(u8, op, "/=") or mem.eql(u8, op, "%=");
    }

    /// True when `expr` represents a call/invocation — a `.Function` call node, or
    /// an expression whose right operand is an `ExpressionParenthesis` argument
    /// list (the shape a method call `recv.method(args)` desugars to in the AST).
    fn expr_is_invocation(expr: *ast.Node) bool {
        if (expr.type == .Function) return true;
        if (expr.type == .ExpressionParenthesis) return true;
        if (expr.type == .Expression and expr.node_variant != null) {
            const e = expr.node_variant.?.exp;
            if (e.right) |r| {
                if (r.type == .ExpressionParenthesis or r.type == .Function) return true;
            }
        }
        return false;
    }

    /// True when `expr` is a `.`-access chain whose leftmost identifier is `name`
    /// (e.g. `r.state` or `r.a.b` with base `r`).
    fn expr_base_is_ident(expr: *ast.Node, name: []const u8) bool {
        var cur = expr;
        while (true) {
            if (cur.type == .Identifier and cur.data != null) {
                return mem.eql(u8, cur.data.?.sval.items, name);
            }
            if (cur.type == .Expression and cur.node_variant != null) {
                const e = cur.node_variant.?.exp;
                if (mem.eql(u8, e.op, ".")) {
                    cur = e.left orelse return false;
                    continue;
                }
            }
            return false;
        }
    }

    fn emit_unused_top_level_warnings(proc: *Self) TranspileError!void {
        if (proc.is_importing or !proc.flags.emit_unused_warnings) return;

        // Pre-scan ALL top-level warning-control pragmas first so `allow`/`expect`
        // are FILE-scoped for unused_* diagnostics, not order-sensitive. Previously
        // the pragma was queued inline as the loop reached it, so `allow unused_import`
        // only suppressed imports that appeared textually AFTER it — e.g. a pragma on
        // line 4 could not silence imports on lines 1-3. Queue every control up front.
        for (proc.nodes.items()) |*node| {
            if (node.type != .StatementWarningControl) continue;
            if (node.node_variant) |nv| {
                const ctrl = nv.statement.warning_ctrl;
                try proc.queue_warning_control(ctrl.action, ctrl.id, ctrl.reason, node.pos);
            }
        }

        for (proc.nodes.items()) |*node| {
            switch (node.type) {
                .StatementWarningControl => {
                    // Already queued in the pre-scan above.
                },
                .Import => {
                    if (node_is_used(node)) continue;
                    // Re-export passthrough modules (declare nothing, only forward
                    // other imports — e.g. `std.c.thread_windows`) are meaningful
                    // when imported even if none of their own names are referenced.
                    if (proc.import_is_reexport_passthrough(node)) continue;
                    const imp = node.node_variant.?.import;
                    if (imp.alias) |alias| {
                        proc.report_warning(.unused_import, node.*, "unused import '{s}' as '{s}'", .{ imp.path, alias });
                    } else {
                        proc.report_warning(.unused_import, node.*, "unused import '{s}'", .{imp.path});
                    }
                },
                .Variable => {
                    if (node.binded != null) continue;
                    if (node_is_public(node) or node_is_used(node)) continue;
                    const v = node.node_variant.?.variable;
                    if (!should_warn_unused_variable(v.name.items)) continue;
                    proc.report_warning(.unused_variable, node.*, "unused variable '{s}'", .{v.name.items});
                },
                .Function => {
                    const fnv = node.node_variant.?.function;
                    if (fnv.name == null or fnv.body == null) continue;
                    if (node_is_public(node) or node_is_used(node)) continue;
                    if (mem.eql(u8, fnv.name.?.items, "main")) continue;
                    proc.report_warning(.unused_function, node.*, "unused function '{s}'", .{fnv.name.?.items});
                },
                .Compound => {
                    if (node_is_public(node) or node_is_used(node)) continue;
                    const compound = node.node_variant.?.compound;
                    proc.report_warning(.unused_compound, node.*, "unused compound '{s}'", .{compound.name.items});
                },
                else => {},
            }
        }
    }

    fn warn_if_fit_not_exhausted(self: *Self, fit_stmt: ast.Node, condition_type: CheckedType, branches: []const ast.FitBranch) void {
        // If there is any default branch, treat it as exhausted.
        for (branches) |branch| {
            if (branch.condition == null) return;
        }

        // Boolean (`bin`) and enums are the only types we can treat as exhaustive without a catch-all.
        // Everything else (num/dec/chr/str/raw*/unknown pointers, etc) should warn unless
        // there is a `_ -> ...` default branch.
        var has_true = false;
        var has_false = false;
        for (branches) |branch| {
            const cond = branch.condition orelse continue;
            if (cond.type == .Boolean) {
                if (cond.data != null and cond.data.?.bval) {
                    has_true = true;
                } else {
                    has_false = true;
                }
            }
        }

        // Exhaustive boolean fit: true + false present.
        if (has_true and has_false) return;

        const root = self.get_root();
        if (root.type_registry != null) {
            if (self.expected_enum_name(condition_type)) |enum_name| {
                const reg = &root.type_registry.?;
                if (reg.enums_by_name.get(enum_name)) |enode| {
                    if (enode.node_variant != null) {
                        const variants = enode.node_variant.?.enum_decl.variants.items();

                        var covered = std.StringHashMap(bool).init(self.backing_allocator);
                        defer covered.deinit();

                        for (branches) |branch| {
                            const bcond = branch.condition orelse continue;
                            if (dot_shorthand_variant_name(bcond)) |short_name| {
                                covered.put(short_name, true) catch {};
                                continue;
                            }
                            if (bcond.type != .Expression or bcond.node_variant == null) continue;
                            const exp = bcond.node_variant.?.exp;
                            if (!mem.eql(u8, exp.op, ".")) continue;
                            const left = exp.left orelse continue;
                            const right = exp.right orelse continue;
                            if (left.type != .Identifier or left.data == null) continue;
                            if (right.type != .Identifier or right.data == null) continue;
                            if (!mem.eql(u8, left.data.?.sval.items, enum_name)) continue;
                            covered.put(right.data.?.sval.items, true) catch {};
                        }

                        var missing = ArrayList(u8).init(self.backing_allocator);
                        defer missing.deinit();

                        var missing_count: usize = 0;
                        for (variants) |v| {
                            if (covered.contains(v.name.items)) continue;
                            if (missing_count > 0) {
                                missing.appendSlice(", ") catch {};
                            }
                            missing.print("{s}.{s}", .{ enum_name, v.name.items }) catch {};
                            missing_count += 1;
                        }

                        if (missing_count == 0) return;

                        self.report_warning(
                            .fit_non_exhaustive,
                            fit_stmt,
                            "fit statement is not exhausted for enum '{s}' condition (missing: {s}; add catch-all '_' branch to silence)",
                            .{ enum_name, missing.items },
                        );
                        return;
                    }
                }
            }
        }

        const cond_type = condition_type.base;
        if (cond_type == .Unknown) {
            self.report_warning(.fit_non_exhaustive, fit_stmt, "fit statement is not exhausted for unknown condition (missing catch-all '_' branch)", .{});
            return;
        }

        if (cond_type != .Bin) {
            self.report_warning(.fit_non_exhaustive, fit_stmt, "fit statement is not exhausted for {s} condition (missing catch-all '_' branch)", .{@tagName(cond_type)});
            return;
        }

        if (!(has_true and has_false)) {
            if (!has_true and !has_false) {
                self.report_warning(.fit_non_exhaustive, fit_stmt, "fit statement is not exhausted for bin condition (missing true and false branches)", .{});
            } else if (!has_true) {
                self.report_warning(.fit_non_exhaustive, fit_stmt, "fit statement is not exhausted for bin condition (missing true branch)", .{});
            } else {
                self.report_warning(.fit_non_exhaustive, fit_stmt, "fit statement is not exhausted for bin condition (missing false branch)", .{});
            }
        }
    }

    /// Creates a new symbol table and sets it as the active table.
    ///
    /// This function creates a new symbol table and initializes its symbols vector.
    /// If there is an existing active table, it is pushed to the list of tables before
    /// the new table is created and set as the active table.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    ///
    /// Errors:
    /// - Returns an error if creating the new symbol table or initializing its symbols fails.
    pub fn new_table(self: *Self) TranspileError!void {
        if (self.symbols.active_table) |table| {
            self.symbols.tables.push(table) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }
        const table = self.allocator.create(symbol.SymbolTable) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        table.*.symbols = utils.Vector(symbol.Symbol).init(self.allocator);
        self.symbols.active_table = table;
    }

    /// Ends the current active symbol table and restores the previous one.
    ///
    /// This function removes the current active symbol table from the list of tables
    /// and sets the last table in the list as the new active table.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    pub fn end_table(self: *Self) void {
        const last_table = self.symbols.tables.back();
        self.symbols.active_table = last_table;
        self.symbols.tables.pop();
    }

    /// Pushes a symbol to the active symbol table.
    ///
    /// This function adds the specified symbol to the active symbol table.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `s (symbol.Symbol)`: The symbol to be added.
    ///
    /// Errors:
    /// - Returns an error if the symbol cannot be added to the active symbol table.
    pub fn push_symbol(self: *Self, s: symbol.Symbol) TranspileError!void {
        self.symbols.active_table.?.symbols.push(s) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    /// Retrieves a symbol by name from the active symbol table.
    ///
    /// This function searches for a symbol with the specified name in the active symbol table.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `name ( []const u8 )`: The name of the symbol to search for.
    ///
    /// Returns:
    /// - `?symbol.Symbol`: The symbol if found, otherwise `null`.
    pub fn get_symbol(self: *Self, name: []const u8) ?symbol.Symbol {
        for (self.symbols.active_table.?.symbols.items()) |s| {
            if (mem.eql(u8, s.name, name)) {
                return s;
            }
        }
        return null;
    }

    /// Retrieves a symbol by name from a specific symbol table.
    ///
    /// This function searches for a symbol with the specified name in the given symbol table.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `table`: The symbol table to search in.
    /// - `name ( []const u8 )`: The name of the symbol to search for.
    ///
    /// Returns:
    /// - `?symbol.Symbol`: The symbol if found, otherwise `null`.
    pub fn get_symbol_from_table(_: *Self, table: *symbol.SymbolTable, name: []const u8) ?symbol.Symbol {
        for (table.symbols.items()) |s| {
            if (mem.eql(u8, s.name, name)) {
                return s;
            }
        }
        return null;
    }

    /// Retrieves a symbol table by its name.
    ///
    /// This function searches for a symbol table with the specified name in the list of symbol tables.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `name ( []const u8 )`: The name of the symbol table to search for.
    ///
    /// Returns:
    /// - `?*symbol.SymbolTable`: The symbol table if found, otherwise `null`.
    pub fn get_symbol_table(self: *Self, name: []const u8) ?*symbol.SymbolTable {
        for (self.symbols.tables.items()) |table| {
            if (mem.eql(u8, table.name, name)) {
                return table;
            }
        }
        return null;
    }

    /// Retrieves a native function symbol by name from all symbol tables.
    ///
    /// This function searches for a symbol with the specified name and type `NativeFunction`
    /// in all symbol tables.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `name ( []const u8 )`: The name of the native function to search for.
    ///
    /// Returns:
    /// - `?symbol.Symbol`: The native function symbol if found, otherwise `null`.
    pub fn get_symbol_for_native_function(self: *Self, name: []const u8) ?symbol.Symbol {
        for (self.symbols.tables.items()) |table| {
            for (table.symbols.items()) |s| {
                if (s.type == symbol.SymbolType.NativeFunction and mem.eql(u8, s.name, name)) {
                    return s;
                }
            }
        }
        return null;
    }

    /// Registers a new symbol in the active symbol table.
    ///
    /// This function checks if a symbol with the same name already exists in the active symbol table
    /// or in any imported module. If a duplicate is found, an error is logged.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `s (symbol.Symbol)`: The symbol to register.
    ///
    /// Errors:
    /// - Logs an error if a symbol with the same name already exists.
    /// - Returns an error if the symbol cannot be added to the active symbol table.
    pub fn register_symbol(self: *Self, s: symbol.Symbol) TranspileError!void {
        // Check if symbol is already defined in the current module
        if (self.get_symbol(s.name) != null) {
            self.err("Symbol '{s}' already defined in the current module", .{s.name});
            return TranspileError.DuplicateSymbol;
        }

        // Skip duplicate checks for main function - each module can have its own main
        if (!mem.eql(u8, s.name, "main")) {
            // Check if symbol is defined in any imported modules by checking global_symbols
            if (self.global_symbols.get(s.name)) |existing| {
                // Only report error if it's from a different file, not the same file
                if (!mem.eql(u8, existing.file_path, self.input_file_path)) {
                    self.err("Symbol '{s}' already defined in module '{s}'", .{ s.name, existing.file_path });
                    return TranspileError.DuplicateSymbol;
                }
            }
        }

        // Determine if this is a function symbol and whether it is public.
        var is_function = false;
        var is_public = false;
        if (s.type == symbol.SymbolType.Node) {
            if (s.data) |data| {
                is_function = data.node.type == .Function;
                is_public = node_is_public(&data.node);
            }
        }

        // Register the symbol in global registry to detect conflicts in other modules.
        // Only public symbols are visible across modules.
        if (is_public and !mem.eql(u8, s.name, "main")) {
            self.global_symbols.put(s.name, .{
                .symbol_name = s.name,
                .file_path = self.input_file_path,
                .is_function = is_function,
                .is_public = true,
            }) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        // Add the symbol to the active symbol table
        try self.push_symbol(s);
    }

    /// Registers a symbol for a given AST node.
    ///
    /// This function creates a symbol for the provided AST node and registers it in the active symbol table.
    /// The symbol type is set to `Node`, and the symbol name is derived from the node's variant (e.g., variable or function).
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `node (*ast.Node)`: The AST node for which the symbol will be registered.
    ///
    /// Errors:
    /// - Returns an error if registering the symbol fails.
    pub fn register_global_node_symbol(self: *Self, node: ast.Node) TranspileError!void {
        switch (node.node_variant.?) {
            .variable => |variable| {
                const s = symbol.Symbol{
                    .type = symbol.SymbolType.Node,
                    .name = variable.name.items,
                    .data = .{ .node = node },
                    .symbol_table = null,
                };

                // Check if this symbol exists in any imported module
                if (self.global_symbols.get(variable.name.items)) |existing| {
                    self.err("Variable '{s}' already defined in module '{s}'", .{ variable.name.items, existing.file_path });
                    return TranspileError.DuplicateSymbol;
                }

                if (node_is_public(&node)) {
                    // Register the symbol in global registry
                    self.global_symbols.put(variable.name.items, .{
                        .symbol_name = variable.name.items,
                        .file_path = self.input_file_path,
                        .is_function = false,
                        .is_public = true,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }

                try self.register_symbol(s);
            },
            .function => |function| {
                if (function.name == null) return;

                const s = symbol.Symbol{
                    .type = symbol.SymbolType.Node,
                    .name = function.name.?.items,
                    .data = .{ .node = node },
                    .symbol_table = null,
                };

                // Skip main functions in imported modules
                if (function.name != null and mem.eql(u8, function.name.?.items, "main")) {
                    // Only include main function from the main module (not from imported modules)
                    if (self.is_importing) {
                        return; // Skip this main function from an imported module
                    }

                    // Check if this function exists in any imported module
                    if (self.global_symbols.get(function.name.?.items)) |existing| {
                        self.err("Function '{s}' already defined in module '{s}'", .{ function.name.?.items, existing.file_path });
                        return TranspileError.DuplicateSymbol;
                    }
                }

                if (node_is_public(&node)) {
                    // Register the symbol in global registry
                    self.global_symbols.put(function.name.?.items, .{
                        .symbol_name = function.name.?.items,
                        .file_path = self.input_file_path,
                        .is_function = true,
                        .is_public = true,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }

                try self.register_symbol(s);
            },
            .compound => |compound| {
                const is_public = node_is_public(&node);
                if (is_public) {
                    self.global_symbols.put(compound.name.items, .{
                        .symbol_name = compound.name.items,
                        .file_path = self.input_file_path,
                        .is_function = false,
                        .is_public = true,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }
            },
            .enum_decl => |enum_decl| {
                const is_public = node_is_public(&node);
                if (is_public) {
                    self.global_symbols.put(enum_decl.name.items, .{
                        .symbol_name = enum_decl.name.items,
                        .file_path = self.input_file_path,
                        .is_function = false,
                        .is_public = true,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }
            },
            .quirk => |quirk| {
                const is_public = node_is_public(&node);
                if (is_public) {
                    self.global_symbols.put(quirk.name.items, .{
                        .symbol_name = quirk.name.items,
                        .file_path = self.input_file_path,
                        .is_function = false,
                        .is_public = true,
                    }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }
            },
            else => {},
        }
    }

    /// Initializes the root scope for the transpiler.
    ///
    /// This function initializes the root scope and sets it as the current scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    ///
    /// Returns:
    /// - `scope.Scope`: The initialized root scope.
    pub fn init_root_scope(self: *Self) TranspileError!scope.Scope {
        assert(self.scope == null);
        const root_scope = self.allocator.create(scope.Scope) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer self.allocator.destroy(root_scope);
        root_scope.* = scope.Scope.init(self.allocator);
        self.scope = .{
            .root = root_scope,
            .current = root_scope,
        };
        return root_scope.*;
    }

    /// Deinitializes a scope and its parent scopes recursively.
    ///
    /// This function deinitializes the given scope and its parent scopes recursively.
    /// It destroys the memory allocated for each scope using the provided allocator.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `s`: The scope to deinitialize.
    fn deinit_scope(self: *Self, s: *scope.Scope) void {
        if (s.parent) |parent| {
            self.deinit_scope(parent);
            self.allocator.destroy(parent);
        }
        s.deinit();
    }

    /// Deinitializes the root scope for the transpiler.
    ///
    /// This function deinitializes the root scope and sets the current scope to null.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    pub fn deinit_root_scope(self: *Self) void {
        assert(self.scope != null);
        if (self.scope.?.current) |current_scope| {
            self.deinit_scope(current_scope);
            self.allocator.destroy(current_scope);
        }
        self.scope.?.root = null;
        self.scope.?.current = null;
        self.scope = null;
    }

    /// Creates a new scope for the transpiler.
    ///
    /// This function initializes a new scope and sets its parent to the current scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    ///
    /// Returns:
    /// - `scope.Scope`: The initialized new scope.
    pub fn new_scope(self: *Self) TranspileError!scope.Scope {
        assert(self.scope != null);
        const nc = self.allocator.create(scope.Scope) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer self.allocator.destroy(nc);
        nc.* = scope.Scope.init(self.allocator);
        nc.parent = self.scope.?.current;
        self.scope.?.current = nc;
        return nc.*;
    }

    /// Retrieves a scope entity by name from the current scope.
    ///
    /// This function searches for a scope entity with the specified name in the current scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `name`: The name of the scope entity to search for.
    ///
    /// Returns:
    /// - `?*ScopeEntity`: The scope entity if found, otherwise `null`.
    pub fn get_current_scope_entity(self: *Self, name: []const u8) ?*scope.ScopeEntity {
        if (self.scope.?.current == null) {
            return null;
        }
        return self.scope.?.current.?.get_entity_by_name(name);
    }

    /// Retrieves a scope entity by name from a specific scope.
    ///
    /// This function searches for a scope entity with the specified name in the given scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `name`: The name of the scope entity to search for.
    /// - `scope`: The scope to search in.
    ///
    /// Returns:
    /// - `?*ScopeEntity`: The scope entity if found, otherwise `null`.
    pub fn get_scope_entity_from_scope(_: *Self, name: []const u8, s: ?*scope.Scope) ?*scope.ScopeEntity {
        if (s == null) {
            return null;
        }
        return s.?.get_entity_by_name(name);
    }

    /// Retrieves a scope entity by name recursively from the current scope.
    ///
    /// This function searches for a scope entity with the specified name in the current scope
    /// and its parent scopes.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `name`: The name of the scope entity to search for.
    ///
    /// Returns:
    /// - `?*ScopeEntity`: The scope entity if found, otherwise `null`.
    pub fn get_scope_entity(self: *Self, name: []const u8) ?*scope.ScopeEntity {
        if (self.scope == null or self.scope.?.current == null) {
            return null;
        }
        var entity = self.get_current_scope_entity(name);
        if (entity) |e| {
            return e;
        }
        var current = self.scope.?.current;
        while (current.?.parent) |parent| {
            current = parent;
            entity = self.get_scope_entity_from_scope(name, current);
            if (entity) |e| {
                return e;
            }
        }
        current = self.scope.?.root;
        return null;
    }

    /// Retrieves the last entity from the current scope, stopping at a specified scope.
    ///
    /// This function retrieves the last entity from the current scope, stopping at the specified stop scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `stop_scope`: The scope to stop at when retrieving the last entity.
    ///
    /// Returns:
    /// - `?*ScopeEntity`: The last entity from the current scope, or `null` if not found.
    pub fn last_scope_entity_stop_at(self: *Self, stop_scope: ?*scope.Scope) ?*scope.ScopeEntity {
        return scope.Scope.last_entity_from_scope_stop_at(self.scope.?.current, stop_scope);
    }

    /// Retrieves the last entity from the current scope.
    ///
    /// This function retrieves the last entity from the current scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    ///
    /// Returns:
    /// - `?*ScopeEntity`: The last entity from the current scope, or `null` if not found.
    pub fn last_scope_entity(self: *Self) ?*scope.ScopeEntity {
        return self.last_scope_entity_stop_at(null);
    }

    /// Pushes an entity to the current scope.
    ///
    /// This function adds the specified entity pointer to the entities of the current scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `entity`: The scope entity to be added.
    ///
    /// Errors:
    /// - Returns an error if the entity could not be added.
    pub fn push_scope_entity(self: *Self, entity: *scope.ScopeEntity) TranspileError!void {
        self.scope.?.current.?.entities.push(entity) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    /// Finishes the current scope and sets the parent scope as the current scope.
    ///
    /// This function deinitializes the current scope and sets its parent scope as the new current scope.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    pub fn finish_scope(self: *Self) void {
        const new_current_scope = self.scope.?.current.?.parent;
        // Free the current scope's allocations (entities vector, etc.).
        self.scope.?.current.?.deinit();
        self.allocator.destroy(self.scope.?.current.?);
        self.scope.?.current = new_current_scope;
        if (self.scope.?.root != null and self.scope.?.current == null) {
            self.scope.?.root = null;
        }
    }

    /// Deinitializes the node and all its resources.
    /// Recursively frees memory allocated for child nodes and their resources.
    ///
    /// Parameters:
    ///   - `self`: The instance of the transpiler to deinitialize.
    ///   - `node`: The node to deinitialize
    pub fn deinit_node(self: *Self, node: ast.Node) void {
        const allocator = self.allocator;
        if (node.binded) |b| {
            if (b.owner) |owner| {
                self.deinit_node(owner.*);
                allocator.destroy(owner);
            }
            if (b.function) |function| {
                self.deinit_node(function.*);
                allocator.destroy(function);
            }
            allocator.destroy(b);
        }
        // NOTE: `ast.Node.data.sval` is borrowed from the token stream.
        // Tokens own and free their string buffers in `TranspileProcess.deinit()`.
        // Deinitializing `.sval` here would double-free.
        if (node.node_variant) |variant| {
            switch (variant) {
                .import => |imp| {
                    // Import paths are allocated by the parser (toOwnedSlice).
                    self.allocator.free(imp.path);
                    if (imp.alias) |alias| self.allocator.free(alias);
                },
                .exp => |exp| {
                    if (exp.left) |left| {
                        self.deinit_node(left.*);
                        allocator.destroy(left);
                    }
                    if (exp.right) |right| {
                        self.deinit_node(right.*);
                        allocator.destroy(right);
                    }
                },
                .paren => |paren| {
                    self.deinit_node(paren.exp.*);
                    allocator.destroy(paren.exp);
                },
                .panic_expr => |p| {
                    self.deinit_node(p.message.*);
                    allocator.destroy(p.message);
                },
                .variable => |variable| {
                    if (variable.val) |val| {
                        self.deinit_node(val.*);
                        allocator.destroy(val);
                    }
                    variable.type.type_str.deinit();
                    if (variable.type.generic_args) |*gargs| {
                        for (gargs.items()) |ga| {
                            ga.type_str.deinit();
                            if (ga.array) |array| {
                                if (!array.brackets.is_empty()) {
                                    for (array.brackets.items()) |bracket| {
                                        self.deinit_node(bracket);
                                    }
                                }
                                array.brackets.deinit();
                            }
                            allocator.destroy(ga);
                        }
                        gargs.deinit();
                    }
                    if (variable.type.array) |array| {
                        if (!array.brackets.is_empty()) {
                            for (array.brackets.items()) |bracket| {
                                self.deinit_node(bracket);
                            }
                        }
                        array.brackets.deinit();
                    }
                    if (variable.type.fn_sig) |sig| {
                        for (sig.params.items()) |p| {
                            p.type_str.deinit();
                            allocator.destroy(p);
                        }
                        sig.params.deinit();
                        sig.rtype.type_str.deinit();
                        allocator.destroy(sig.rtype);
                        allocator.destroy(sig);
                    }
                    allocator.destroy(variable.type);
                    variable.name.deinit();
                },
                .unary => |unary| {
                    self.deinit_node(unary.operand.*);
                    allocator.destroy(unary.operand);
                },
                .tenary => |tenary| {
                    self.deinit_node(tenary.condition.*);
                    allocator.destroy(tenary.condition);
                    self.deinit_node(tenary.true.*);
                    allocator.destroy(tenary.true);
                    self.deinit_node(tenary.false.*);
                    allocator.destroy(tenary.false);
                },
                .bracket => |bracket| {
                    self.deinit_node(bracket.inner.*);
                    allocator.destroy(bracket.inner);
                },
                .compound_init => |cinit| {
                    if (cinit.dtype) |dt| {
                        dt.type_str.deinit();
                        if (dt.generic_args) |*gargs| {
                            for (gargs.items()) |ga| {
                                ga.type_str.deinit();
                                if (ga.array) |array| {
                                    if (!array.brackets.is_empty()) {
                                        for (array.brackets.items()) |bracket| {
                                            self.deinit_node(bracket);
                                        }
                                    }
                                    array.brackets.deinit();
                                }
                                allocator.destroy(ga);
                            }
                            gargs.deinit();
                        }
                        if (dt.array) |array| {
                            if (!array.brackets.is_empty()) {
                                for (array.brackets.items()) |bracket| {
                                    self.deinit_node(bracket);
                                }
                            }
                            array.brackets.deinit();
                        }
                        allocator.destroy(dt);
                    }
                    for (cinit.fields.items()) |f| {
                        f.name.deinit();
                        self.deinit_node(f.value.*);
                        allocator.destroy(f.value);
                    }
                    cinit.fields.deinit();
                },
                .body => |body| {
                    for (body.statements.items()) |statement| {
                        self.deinit_node(statement.*);
                        allocator.destroy(statement);
                    }
                    body.statements.deinit();
                },
                .function => |function| {
                    if (function.args) |args| {
                        for (args.items()) |arg| {
                            self.deinit_node(arg.*);
                            allocator.destroy(arg);
                        }
                        args.deinit();
                    }
                    if (function.body) |body| {
                        self.deinit_node(body.*);
                        allocator.destroy(body);
                    }
                    if (function.type_params) |*params| {
                        for (params.items()) |*p| {
                            p.deinit();
                        }
                        params.deinit();
                    }
                    if (function.rtype) |rtype| {
                        rtype.type_str.deinit();
                        if (rtype.generic_args) |*gargs| {
                            for (gargs.items()) |ga| {
                                ga.type_str.deinit();
                                if (ga.array) |array| {
                                    if (!array.brackets.is_empty()) {
                                        for (array.brackets.items()) |bracket| {
                                            self.deinit_node(bracket);
                                        }
                                    }
                                    array.brackets.deinit();
                                }
                                allocator.destroy(ga);
                            }
                            gargs.deinit();
                        }
                    }
                    if (function.name) |name| {
                        name.deinit();
                    }
                },
                .compound => |c| {
                    c.name.deinit();
                    if (c.type_params) |*params| {
                        for (params.items()) |*p| {
                            p.deinit();
                        }
                        params.deinit();
                    }
                    for (c.fields.items()) |f| {
                        f.name.deinit();
                        f.dtype.type_str.deinit();
                        if (f.dtype.generic_args) |*gargs| {
                            for (gargs.items()) |ga| {
                                ga.type_str.deinit();
                                if (ga.array) |array| {
                                    if (!array.brackets.is_empty()) {
                                        for (array.brackets.items()) |bracket| {
                                            self.deinit_node(bracket);
                                        }
                                    }
                                    array.brackets.deinit();
                                }
                                allocator.destroy(ga);
                            }
                            gargs.deinit();
                        }
                        if (f.dtype.array) |array| {
                            if (!array.brackets.is_empty()) {
                                for (array.brackets.items()) |bracket| {
                                    self.deinit_node(bracket);
                                }
                            }
                            array.brackets.deinit();
                        }
                        allocator.destroy(f.dtype);
                    }
                    c.fields.deinit();
                },
                .quirk => |q| {
                    q.name.deinit();
                    if (q.type_params) |*tp| {
                        for (tp.items()) |*p| p.deinit();
                        var mtp = tp.*;
                        mtp.deinit();
                    }
                    for (q.methods.items()) |m| {
                        m.name.deinit();
                        m.rtype.type_str.deinit();
                        if (m.rtype.generic_args) |*gargs| {
                            for (gargs.items()) |ga| {
                                ga.type_str.deinit();
                                if (ga.array) |array| {
                                    if (!array.brackets.is_empty()) {
                                        for (array.brackets.items()) |bracket| {
                                            self.deinit_node(bracket);
                                        }
                                    }
                                    array.brackets.deinit();
                                }
                                allocator.destroy(ga);
                            }
                            gargs.deinit();
                        }
                        for (m.args.items()) |a| {
                            a.name.deinit();
                            a.dtype.type_str.deinit();
                            if (a.dtype.generic_args) |*gargs| {
                                for (gargs.items()) |ga| {
                                    ga.type_str.deinit();
                                    if (ga.array) |array| {
                                        if (!array.brackets.is_empty()) {
                                            for (array.brackets.items()) |bracket| {
                                                self.deinit_node(bracket);
                                            }
                                        }
                                        array.brackets.deinit();
                                    }
                                    allocator.destroy(ga);
                                }
                                gargs.deinit();
                            }
                            if (a.dtype.array) |array| {
                                if (!array.brackets.is_empty()) {
                                    for (array.brackets.items()) |bracket| {
                                        self.deinit_node(bracket);
                                    }
                                }
                                array.brackets.deinit();
                            }
                            allocator.destroy(a.dtype);
                        }
                        m.args.deinit();
                    }
                    q.methods.deinit();
                },
                .enum_decl => |e| {
                    e.name.deinit();
                    for (e.variants.items()) |v| {
                        v.name.deinit();
                    }
                    e.variants.deinit();
                },
                .impl => |im| {
                    im.type_name.deinit();
                    if (im.type_params) |*params| {
                        for (params.items()) |*p| {
                            p.deinit();
                        }
                        params.deinit();
                    }
                    if (im.type_param_forced_insts) |*insts| {
                        for (insts.items()) |*combo| {
                            for (combo.items()) |*t| {
                                t.deinit();
                            }
                            combo.deinit();
                        }
                        insts.deinit();
                    }
                    if (im.quirk_name) |*qn| {
                        qn.deinit();
                    }
                    if (im.quirk_concrete_instantiation) |*qci| {
                        qci.deinit();
                    }
                    for (im.methods.items()) |m| {
                        self.deinit_node(m.*);
                        allocator.destroy(m);
                    }
                    im.methods.deinit();
                },
                .statement => |statement| {
                    switch (statement) {
                        .return_stmt => |ret| {
                            self.deinit_node(ret.*);
                            allocator.destroy(ret);
                        },
                        .defer_stmt => |d| {
                            _ = d;
                            // Defer bodies are owned elsewhere in the AST; avoid double-free.
                        },
                        .asm_stmt => |a| {
                            a.template.deinit();
                            if (a.arch) |*arch| {
                                arch.deinit();
                            }
                            for (a.outputs.items()) |op| {
                                op.name.deinit();
                                op.constraint.deinit();
                                self.deinit_node(op.expr.*);
                                allocator.destroy(op.expr);
                            }
                            a.outputs.deinit();
                            for (a.inputs.items()) |op| {
                                op.name.deinit();
                                op.constraint.deinit();
                                self.deinit_node(op.expr.*);
                                allocator.destroy(op.expr);
                            }
                            a.inputs.deinit();
                            for (a.clobbers.items()) |cl| {
                                cl.deinit();
                            }
                            a.clobbers.deinit();
                        },
                        .for_stmt => |for_s| {
                            switch (for_s) {
                                .cond => |fc| {
                                    if (fc.condition) |cond| {
                                        self.deinit_node(cond.*);
                                        allocator.destroy(cond);
                                    }
                                    self.deinit_node(fc.body.*);
                                    allocator.destroy(fc.body);
                                },
                                .range => |fr| {
                                    self.deinit_node(fr.range.*);
                                    allocator.destroy(fr.range);
                                    self.deinit_node(fr.body.*);
                                    allocator.destroy(fr.body);
                                },
                                .iter => |fi| {
                                    self.deinit_node(fi.iterable.*);
                                    allocator.destroy(fi.iterable);
                                    self.deinit_node(fi.body.*);
                                    allocator.destroy(fi.body);
                                },
                            }
                        },
                        .if_stmt => |if_s| {
                            self.deinit_node(if_s.condition.*);
                            allocator.destroy(if_s.condition);
                            self.deinit_node(if_s.body.*);
                            allocator.destroy(if_s.body);
                        },
                        .elif_stmt => |elif| {
                            self.deinit_node(elif.condition.*);
                            allocator.destroy(elif.condition);
                            self.deinit_node(elif.body.*);
                            allocator.destroy(elif.body);
                        },
                        .else_stmt => |else_s| {
                            self.deinit_node(else_s.body.*);
                            allocator.destroy(else_s.body);
                        },
                        .fit_stmt => |fit| {
                            self.deinit_node(fit.exp.*);
                            allocator.destroy(fit.exp);
                            for (fit.branches.items()) |branch| {
                                if (branch.condition) |condition| {
                                    self.deinit_node(condition.*);
                                    allocator.destroy(condition);
                                }
                                self.deinit_node(branch.body.*);
                                allocator.destroy(branch.body);
                            }
                            fit.branches.deinit();
                        },
                        .assert_stmt => |asrt| {
                            self.deinit_node(asrt.condition.*);
                            allocator.destroy(asrt.condition);
                            if (asrt.message) |msg| {
                                self.deinit_node(msg.*);
                                allocator.destroy(msg);
                            }
                        },
                        .warning_ctrl => {
                            // reason points into token memory and is not owned by AST nodes.
                        },
                        .fork_stmt => |f| {
                            self.deinit_node(f.expr.*);
                            allocator.destroy(f.expr);
                        },
                    }
                },
                else => {},
            }
        }
    }

    /// Deinitializes the transpiler by closing input and output files and deinitializing tokens.
    ///
    /// This function performs the following actions:
    /// - Closes the input file associated with the transpiler.
    /// - Closes the output file associated with the transpiler.
    /// - Deinitializes the tokens used by the transpiler.
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler to deinitialize.
    ///
    /// Returns:
    /// - This function does not return any value.
    pub fn deinit(self: *Self) void {
        if (self.type_registry) |*reg| {
            reg.deinit();
            self.type_registry = null;
        }
        self.ifile.close(self.io);
        if (self.ofile) |f| {
            f.close(self.io);
        }
        if (self.outbuf) |*buf| {
            buf.deinit();
        }
        for (self.tokens.items()) |t| {
            switch (t.data) {
                .sval => t.data.sval.deinit(),
                else => {},
            }
        }
        self.tokens.deinit();
        for (self.nodes.items()) |node| {
            self.deinit_node(node);
        }
        self.nodes.deinit();

        self.warnings.deinit();
        self.pending_warning_allows.deinit();
        self.pending_warning_expects.deinit();

        // Most allocations in a `TranspileProcess` are arena-backed; deinit the
        // containers, then release the arena at the end.
        self.owned_scope_entities.deinit();
        self.owned_nodes.deinit();
        self.defer_stack.deinit();
        self.defer_scope_stack.deinit();
        if (self.symbols.active_table) |table| {
            table.symbols.deinit();
        }
        for (self.symbols.tables.items()) |table| {
            table.symbols.deinit();
        }
        self.symbols.tables.deinit();

        self.imported_files.deinit();
        self.import_chain.deinit();
        self.global_symbols.deinit();

        if (self.import_aliases.count() > 0) {
            var ait = self.import_aliases.iterator();
            while (ait.next()) |entry| {
                self.allocator.free(entry.key_ptr.*);
                self.allocator.free(entry.value_ptr.*);
            }
        }
        self.import_aliases.deinit();

        // Deinit children TranspileProcesses
        for (self.children.items) |child| {
            child.deinit();
            self.backing_allocator.destroy(child);
        }
        self.children.deinit();

        self.std_imports.deinit();

        if (self.emitted_generic_spec_keys.count() > 0) {
            var esit = self.emitted_generic_spec_keys.iterator();
            while (esit.next()) |e| {
                self.allocator.free(e.key_ptr.*);
            }
        }
        self.emitted_generic_spec_keys.deinit();

        // Generic function instantiation tracking.
        if (self.generic_fn_instantiation_keys.count() > 0) {
            var it = self.generic_fn_instantiation_keys.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
            }
        }
        self.generic_fn_instantiation_keys.deinit();
        self.generic_fn_instantiations.deinit();

        // Keys are arena-allocated call-position strings; avoid per-key frees here.
        // Imported/module process graphs can observe shared key lifetimes, and arena
        // teardown below releases all allocations in one pass.
        self.generic_call_overrides.deinit();

        // Same ownership model as generic_call_overrides (keys + values are arena-
        // allocated; the arena teardown below frees them in one pass).
        self.enum_ctor_overrides.deinit();

        // Same ownership model as generic_call_overrides.
        self.await_call_overrides.deinit();

        // Values are plain optional pointers (no owned strings); keys follow
        // the same arena-allocated ownership model as generic_call_overrides.
        self.for_iter_overrides.deinit();

        // Release all arena allocations back to the backing allocator.
        self.arena.deinit();
        self.backing_allocator.destroy(self.arena);
    }

    /// Gets the output as a string. Only valid when outf is false.
    pub fn get_output(self: *Self) ?[]const u8 {
        if (self.outbuf) |*buf| {
            return buf.items;
        }
        return null;
    }

    /// Helper function to format and write values
    fn print(self: *Self, comptime fmt: []const u8, args: anytype) TranspileError!void {
        if (self.flags.outf) {
            const s = std.fmt.allocPrint(self.backing_allocator, fmt, args) catch return TranspileError.MemoryAllocationFailed;
            defer self.backing_allocator.free(s);
            self.ofile.?.writeStreamingAll(self.io, s) catch {
                return TranspileError.FileWriteError;
            };
        } else {
            self.outbuf.?.print(fmt, args) catch {
                return TranspileError.BufferWriteError;
            };
        }
    }

    /// Emits the shared `fprintf(...); abort();` pair a `panic(msg)` lowers to,
    /// as bare C STATEMENTS (no wrapping expression, no trailing dummy value).
    /// Used directly in return-statement position (where `abort()` never
    /// returning means no value is needed at all) and wrapped in a `({ ...
    /// 0; })` GNU statement expression everywhere else `.Panic` is emitted as
    /// a general expression (see the `.Panic` case in the main transpile
    /// switch).
    fn write_panic_message_and_abort(self: *Self, message: ast.Node) TranspileError!void {
        try self.write("fprintf(stderr_stream(), \"panic: %s\\n\", ");
        try self.transpile_node(message);
        try self.write("); abort();");
    }

    fn node_needs_trailing_semicolon(self: *Self, node: ast.Node) bool {
        _ = self;
        return switch (node.type) {
            .Expression, .ExpressionParenthesis, .Unary, .Panic => true,
            else => false,
        };
    }

    fn emit_defer_body(self: *Self, node: *ast.Node) TranspileError!void {
        if (node.type == .Body) {
            try self.transpile_node(node.*);
            return;
        }
        try self.transpile_node(node.*);
        if (self.node_needs_trailing_semicolon(node.*)) {
            try self.write(";");
        }
    }

    fn reset_function_defer_state(self: *Self) void {
        self.defer_stack.clearRetainingCapacity();
        self.defer_scope_stack.clearRetainingCapacity();
    }

    fn push_defer_scope(self: *Self, kind: DeferScopeKind) TranspileError!void {
        self.defer_scope_stack.append(.{
            .start_index = self.defer_stack.items.len,
            .kind = kind,
        }) catch return TranspileError.MemoryAllocationFailed;
    }

    fn pop_defer_scope(self: *Self) void {
        if (self.defer_scope_stack.items.len == 0) return;
        const frame = self.defer_scope_stack.pop().?;
        self.defer_stack.shrinkRetainingCapacity(frame.start_index);
    }

    fn register_scope_defer(self: *Self, body: *ast.Node, pos: ?token.Pos) TranspileError!void {
        if (self.defer_scope_stack.items.len == 0) return;
        self.defer_stack.append(.{ .body = body, .pos = pos }) catch return TranspileError.MemoryAllocationFailed;
    }

    fn emit_defers_from_index(self: *Self, start_index: usize) TranspileError!void {
        if (self.defer_stack.items.len <= start_index) return;
        var i: usize = self.defer_stack.items.len;
        while (i > start_index) : (i -= 1) {
            const d = self.defer_stack.items[i - 1];
            if (self.flags.debug_info) {
                self.pending_line_directive = d.pos;
            }
            try self.write_indent();
            try self.emit_defer_body(d.body);
        }
    }

    fn emit_current_scope_defers(self: *Self) TranspileError!void {
        if (self.defer_scope_stack.items.len == 0) return;
        const frame = self.defer_scope_stack.items[self.defer_scope_stack.items.len - 1];
        try self.emit_defers_from_index(frame.start_index);
    }

    /// When `fork` is used, `main` must drain the scheduler before returning so
    /// fire-and-forget tasks complete. Emit `__fun_sched_wait_idle();` immediately
    /// before each `main` exit (body-end, bare `ret;`, `ret <expr>`).
    fn emit_fork_wait_idle_if_main(self: *Self) TranspileError!void {
        if (!self.in_main or !self.uses_fork) return;
        try self.write_indent();
        try self.write("__fun_sched_wait_idle();\n");
    }

    fn emit_function_scope_defers(self: *Self) TranspileError!void {
        if (self.defer_scope_stack.items.len == 0) return;

        var i: usize = self.defer_scope_stack.items.len;
        while (i > 0) : (i -= 1) {
            const frame = self.defer_scope_stack.items[i - 1];
            if (frame.kind == .function) {
                try self.emit_defers_from_index(frame.start_index);
                return;
            }
        }

        // Safety fallback for malformed scope stacks.
        try self.emit_defers_from_index(0);
    }

    /// True if any defer is currently pending up to (and including) the enclosing
    /// function scope — i.e. `emit_function_scope_defers` would emit something. Used
    /// to decide whether `ret <expr>` must snapshot its value into a temp BEFORE the
    /// defers run (defers may mutate variables the return expression reads).
    fn has_pending_function_defers(self: *Self) bool {
        if (self.defer_scope_stack.items.len == 0) return false;
        var i: usize = self.defer_scope_stack.items.len;
        while (i > 0) : (i -= 1) {
            const frame = self.defer_scope_stack.items[i - 1];
            if (frame.kind == .function) {
                return self.defer_stack.items.len > frame.start_index;
            }
        }
        return self.defer_stack.items.len > 0;
    }

    fn emit_loop_scope_defers(self: *Self) TranspileError!void {
        if (self.defer_scope_stack.items.len == 0) return;

        var i: usize = self.defer_scope_stack.items.len;
        while (i > 0) : (i -= 1) {
            const frame = self.defer_scope_stack.items[i - 1];
            if (frame.kind == .loop) {
                try self.emit_defers_from_index(frame.start_index);
                return;
            }
        }
    }

    fn transpile_statement_in_current_scope(self: *Self, statement: *ast.Node) TranspileError!void {
        if (statement.type == .Variable) {
            try self.register_scope_variable(statement);
        }
        // When debug info is enabled, queue a #line directive for write_indent() to emit.
        if (self.flags.debug_info) {
            self.pending_line_directive = statement.pos;
        }
        if (statement.type != .StatementReturn and statement.type != .StatementDefer) {
            try self.write_indent();
        }
        try self.transpile_node(statement.*);
        if (self.node_needs_trailing_semicolon(statement.*)) {
            try self.write(";");
        }
    }

    fn transpile_block_contents(self: *Self, body_node: *ast.Node) TranspileError!void {
        if (body_node.type == .Body) {
            const body = body_node.node_variant.?.body;
            for (body.statements.items()) |statement| {
                try self.transpile_statement_in_current_scope(statement);
            }
            return;
        }

        try self.transpile_statement_in_current_scope(body_node);
    }

    fn node_is_scope_terminator(node: *ast.Node) bool {
        return switch (node.type) {
            .StatementReturn, .StatementBreak, .StatementContinue => true,
            // A bare `panic("msg");` statement ALWAYS aborts (unlike `assert`,
            // whose condition might not fire) -- treat it as a terminator too,
            // so it doesn't trigger a false-positive `missing_return` when
            // it's a function's last statement, and so codegen doesn't emit
            // dead defer/fork-wait-idle cleanup after it.
            .Panic => true,
            else => false,
        };
    }

    /// True when a `Body` node is GUARANTEED to exit its scope on every path (a `ret`
    /// on all branches). Conservative: when it can't prove termination it returns false
    /// (so a genuine fall-through is flagged), but it never claims termination it can't
    /// justify (so it won't false-positive on code that does return everywhere).
    /// True when every branch's condition names a distinct `Enum.Variant` (or
    /// `.Variant` shorthand) path and, together, they cover every variant the
    /// subject enum declares — mirroring the coverage check
    /// `warn_if_fit_not_exhausted` already does structurally from the branch
    /// list alone (no type inference needed: the enum name is read straight
    /// off the first `Enum.Variant`-shaped branch condition).
    fn fit_covers_all_enum_variants(self: *Self, branches: []const ast.FitBranch) bool {
        var enum_name: ?[]const u8 = null;
        for (branches) |branch| {
            const cond = branch.condition orelse continue;
            if (cond.type != .Expression or cond.node_variant == null) continue;
            const exp = cond.node_variant.?.exp;
            if (!mem.eql(u8, exp.op, ".")) continue;
            const left = exp.left orelse continue;
            const right = exp.right orelse continue;
            if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                enum_name = left.*.data.?.sval.items;
                break;
            }
        }
        const en = enum_name orelse return false;

        const root = self.get_root();
        if (root.type_registry == null) return false;
        const reg = &root.type_registry.?;
        const enode = reg.enums_by_name.get(en) orelse return false;
        if (enode.node_variant == null) return false;
        const variants = enode.node_variant.?.enum_decl.variants.items();
        if (variants.len == 0) return false;

        var covered = std.StringHashMap(bool).init(self.backing_allocator);
        defer covered.deinit();
        for (branches) |branch| {
            const bcond = branch.condition orelse continue;
            if (dot_shorthand_variant_name(bcond)) |short_name| {
                covered.put(short_name, true) catch {};
                continue;
            }
            if (bcond.*.type != .Expression or bcond.*.node_variant == null) continue;
            const exp = bcond.*.node_variant.?.exp;
            if (!mem.eql(u8, exp.op, ".")) continue;
            const left = exp.left orelse continue;
            const right = exp.right orelse continue;
            if (left.*.type != .Identifier or left.*.data == null) continue;
            if (right.*.type != .Identifier or right.*.data == null) continue;
            covered.put(right.*.data.?.sval.items, true) catch {};
        }

        for (variants) |v| {
            if (!covered.contains(v.name.items)) return false;
        }
        return true;
    }

    fn body_always_returns(self: *Self, body: *ast.Node) bool {
        if (body.type != .Body or body.node_variant == null) return false;
        const stmts = body.node_variant.?.body.statements.items();
        return self.stmts_always_return(stmts);
    }

    /// True when executing this flat statement list always ends in a scope exit. Walks
    /// statements in order; an if/elif/else chain counts only when an `else` is present
    /// AND every branch body always-returns; an exhaustive `fit` counts when every arm
    /// body always-returns. A bare `ret`/`break`/`continue` ends the analysis as true.
    fn stmts_always_return(self: *Self, stmts: []const *ast.Node) bool {
        var i: usize = 0;
        while (i < stmts.len) : (i += 1) {
            const s = stmts[i];
            switch (s.type) {
                // A bare `panic("msg");` ALWAYS aborts (unlike `assert`, whose
                // condition might not fire), so it terminates the scope just
                // like `ret`/`break`/`continue`.
                .StatementReturn, .StatementBreak, .StatementContinue, .Panic => return true,
                .StatementIf => {
                    // Gather the if + following elif* + optional else (siblings).
                    const if_v = s.node_variant.?.statement.if_stmt;
                    var all_branches_return = self.body_always_returns(if_v.body);
                    var has_else = false;
                    var j = i + 1;
                    while (j < stmts.len) : (j += 1) {
                        const nb = stmts[j];
                        if (nb.type == .StatementElseIf) {
                            const ev = nb.node_variant.?.statement.elif_stmt;
                            if (!self.body_always_returns(ev.body)) all_branches_return = false;
                            continue;
                        }
                        if (nb.type == .StatementElse) {
                            const elv = nb.node_variant.?.statement.else_stmt;
                            if (!self.body_always_returns(elv.body)) all_branches_return = false;
                            has_else = true;
                        }
                        break;
                    }
                    // Without an `else`, the if-chain can fall through, so it does not by
                    // itself guarantee a return — keep scanning the statements after it.
                    if (has_else and all_branches_return) return true;
                    i = j - 1; // skip the consumed elif/else siblings
                },
                .StatementFit => {
                    // A `fit` guarantees return only if it's exhaustive (no fall-through)
                    // AND every arm body always-returns. Exhaustiveness is signalled by a
                    // default branch OR by every arm naming a distinct variant of the
                    // subject enum (the same coverage `warn_if_fit_not_exhausted` computes
                    // to decide whether to warn) — a fit lacking a `_` catch-all but
                    // covering `Enum.A`/`Enum.B`/... for every declared variant is just as
                    // exhaustive and must not be treated as possibly-falling-through.
                    const fit_v = s.node_variant.?.statement.fit_stmt;
                    if (!fit_v.has_default_branch and !self.fit_covers_all_enum_variants(fit_v.branches.items())) {
                        // Not provably exhaustive here — don't count it; keep scanning.
                        continue;
                    }
                    var all_arms_return = true;
                    for (fit_v.branches.items()) |br| {
                        if (!self.body_always_returns(br.body)) {
                            all_arms_return = false;
                            break;
                        }
                    }
                    if (all_arms_return) return true;
                },
                .StatementFor => {
                    // An UNCONDITIONAL loop (`for { ... }` or `for true { ... }`) that
                    // contains no `break` never falls through to the statements after it
                    // — control either loops forever or exits via a `ret` inside. So the
                    // function can't reach its end past such a loop. Idiom: `for true {
                    // ... ret x; ... }` (e.g. string.fn `equals`).
                    const fv = s.node_variant.?.statement.for_stmt;
                    switch (fv) {
                        .cond => |c| {
                            const is_infinite = c.condition == null or
                                (c.condition.?.type == .Boolean and c.condition.?.data != null and c.condition.?.data.?.bval);
                            if (is_infinite and !self.body_has_break(c.body)) return true;
                        },
                        else => {},
                    }
                },
                else => {},
            }
        }
        return false;
    }

    /// True if `body` contains a `break` that targets THIS loop (does not descend into
    /// nested loops, whose `break`s target the inner loop, nor into nested functions).
    /// Used to decide whether an unconditional loop can fall through.
    fn body_has_break(self: *Self, body: *ast.Node) bool {
        if (body.type != .Body or body.node_variant == null) return false;
        for (body.node_variant.?.body.statements.items()) |st| {
            if (self.node_has_break_for_this_loop(st)) return true;
        }
        return false;
    }

    fn node_has_break_for_this_loop(self: *Self, n: *ast.Node) bool {
        switch (n.type) {
            .StatementBreak => return true,
            // Nested loops capture their own `break`s — don't descend.
            .StatementFor => return false,
            .StatementIf => return self.body_has_break(n.node_variant.?.statement.if_stmt.body),
            .StatementElseIf => return self.body_has_break(n.node_variant.?.statement.elif_stmt.body),
            .StatementElse => return self.body_has_break(n.node_variant.?.statement.else_stmt.body),
            .StatementFit => {
                for (n.node_variant.?.statement.fit_stmt.branches.items()) |br| {
                    if (self.body_has_break(br.body)) return true;
                }
                return false;
            },
            else => return false,
        }
    }

    fn block_ends_with_scope_terminator(self: *Self, body_node: *ast.Node) bool {
        _ = self;
        if (body_node.type == .Body) {
            const statements = body_node.node_variant.?.body.statements.items();
            if (statements.len == 0) return false;
            return node_is_scope_terminator(statements[statements.len - 1]);
        }
        return node_is_scope_terminator(body_node);
    }

    fn transpile_scoped_block(self: *Self, body_node: *ast.Node, kind: DeferScopeKind) TranspileError!void {
        try self.write("{");
        self.indent();
        _ = try self.new_scope();
        defer self.finish_scope();

        try self.push_defer_scope(kind);
        defer self.pop_defer_scope();

        try self.transpile_block_contents(body_node);
        if (!self.block_ends_with_scope_terminator(body_node)) {
            try self.emit_current_scope_defers();
        }

        self.dedent();
        try self.write_indent();
        try self.write("}");
    }

    /// Write to output (either file or buffer)
    pub fn write(self: *Self, bytes: []const u8) TranspileError!void {
        // Fast path: no newline in this chunk (the overwhelming majority of
        // calls -- identifiers, punctuation, single tokens) -- just update
        // the trailing-newline-run counter and pass through unmodified.
        if (mem.indexOfScalar(u8, bytes, '\n') == null) {
            if (bytes.len > 0) self.consecutive_newlines = 0;
            return self.write_raw(bytes);
        }

        // Slow path: this chunk contains at least one newline. Collapse any
        // run of 3+ consecutive newlines (2+ blank lines) down to exactly 2
        // (one blank line), with the run tracked in `consecutive_newlines`
        // so it collapses correctly even when split across separate
        // write() calls (one ending "...\n", the next starting "\n\n...").
        // Purely cosmetic -- C ignores blank lines -- but keeps generated
        // output readable instead of accumulating long blank-line runs at
        // section boundaries where several independent emission passes
        // each add their own trailing separator.
        var buf = ArrayList(u8).init(self.backing_allocator);
        defer buf.deinit();
        for (bytes) |c| {
            if (c == '\n') {
                self.consecutive_newlines += 1;
                if (self.consecutive_newlines > 2) continue;
            } else {
                self.consecutive_newlines = 0;
            }
            buf.append(c) catch return TranspileError.MemoryAllocationFailed;
        }
        return self.write_raw(buf.items);
    }

    fn write_raw(self: *Self, bytes: []const u8) TranspileError!void {
        if (self.flags.outf) {
            self.ofile.?.writeStreamingAll(self.io, bytes) catch {
                return TranspileError.FileWriteError;
            };
        } else {
            self.outbuf.?.appendSlice(bytes) catch {
                return TranspileError.BufferWriteError;
            };
        }
    }

    /// Maps fun language types to C types
    fn map_type_to_c(type_str: []const u8) []const u8 {
        if (mem.eql(u8, type_str, "num")) return "int64_t";
        if (mem.eql(u8, type_str, "dec")) return "double";
        if (mem.eql(u8, type_str, "f32")) return "float";
        if (mem.eql(u8, type_str, "f64")) return "double";
        if (mem.eql(u8, type_str, "i8")) return "int8_t";
        if (mem.eql(u8, type_str, "i16")) return "int16_t";
        if (mem.eql(u8, type_str, "i32")) return "int32_t";
        if (mem.eql(u8, type_str, "i64")) return "int64_t";
        if (mem.eql(u8, type_str, "u8")) return "uint8_t";
        if (mem.eql(u8, type_str, "u16")) return "uint16_t";
        if (mem.eql(u8, type_str, "u32")) return "uint32_t";
        if (mem.eql(u8, type_str, "u64")) return "uint64_t";
        if (mem.eql(u8, type_str, "str")) return "char*";
        if (mem.eql(u8, type_str, "bin")) return "bool";
        if (mem.eql(u8, type_str, "chr")) return "char";
        if (mem.eql(u8, type_str, "raw")) return "void";
        return type_str;
    }

    fn write_dynamic_int_type(self: *Self, type_str: []const u8) TranspileError!bool {
        const dyn = utils.parse_dynamic_int_datatype(type_str) orelse return false;
        switch (dyn.bits) {
            8 => {
                try self.write(if (dyn.is_signed) "int8_t" else "uint8_t");
                return true;
            },
            16 => {
                try self.write(if (dyn.is_signed) "int16_t" else "uint16_t");
                return true;
            },
            32 => {
                try self.write(if (dyn.is_signed) "int32_t" else "uint32_t");
                return true;
            },
            64 => {
                try self.write(if (dyn.is_signed) "int64_t" else "uint64_t");
                return true;
            },
            else => {
                if (dyn.is_signed) {
                    try self.print("_BitInt({d})", .{dyn.bits});
                } else {
                    try self.print("unsigned _BitInt({d})", .{dyn.bits});
                }
                return true;
            },
        }
    }

    fn append_mangled_type_depth(self: *Self, buf: *ArrayList(u8), dt: *const dtype.DataType, depth: usize) TranspileError!void {
        const max_depth: usize = 32;
        const max_segment_len: usize = 256;
        const max_total_len: usize = 8192;

        // Guard against malformed/cyclic dtype graphs that would recurse forever.
        if (depth > max_depth) {
            return TranspileError.TypeMismatch;
        }
        if (dt.type_str.items.len > 0 and @intFromPtr(dt.type_str.items.ptr) == 0) {
            return TranspileError.TypeMismatch;
        }

        if (dt.type_str.items.len > max_segment_len) {
            return TranspileError.TypeMismatch;
        }
        if (buf.items.len >= max_total_len or dt.type_str.items.len > (max_total_len - buf.items.len)) {
            return TranspileError.TypeMismatch;
        }

        buf.appendSlice(dt.type_str.items) catch return TranspileError.MemoryAllocationFailed;
        // A generic ARG's pointer depth must be part of its mangled identity:
        // `Vec<Node>` and `Vec<Node*>` are genuinely different monomorphizations
        // (a `T*` field/param substituting T=Node* needs an extra level of
        // indirection than T=Node), but without this both mangled to the
        // identical "Vec__Node" — colliding into ONE emitted struct/method set
        // with whichever arg's pointer_depth happened to be seen last, a real
        // miscompile (e.g. `push(T value)` monomorphized to take `Node` by
        // value instead of `Node*`). Only applies at nested (arg) depth, not
        // the OUTER/top-level type: `type_name_mangled` on a *pointer-typed
        // variable* (`Vec<num>* p`) is called constantly to get just the bare
        // struct name, with the caller's own C syntax adding the "*" — suffixing
        // depth 0 too would wrongly rename every one of those existing uses.
        if (depth > 0 and dt.pointer_depth > 0) {
            buf.print("_ptr{d}", .{dt.pointer_depth}) catch return TranspileError.MemoryAllocationFailed;
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                if (buf.items.len + 2 > max_total_len) {
                    return TranspileError.TypeMismatch;
                }
                buf.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
                try self.append_mangled_type_depth(buf, ga, depth + 1);
            }
        }
    }

    fn append_mangled_type(self: *Self, buf: *ArrayList(u8), dt: *const dtype.DataType) TranspileError!void {
        try self.append_mangled_type_depth(buf, dt, 0);
    }

    /// Like `type_name_mangled`, but for a dtype being manually concatenated
    /// as a generic ARGUMENT segment into a larger `Outer__Arg` name (as
    /// opposed to naming the dtype's own struct/variable, where a pointer is
    /// a separate C token the caller adds itself). Starts the depth counter
    /// at 1 so `append_mangled_type_depth`'s pointer-suffix logic (gated on
    /// depth > 0) applies here too — without this, code that manually builds
    /// a combined name by calling the depth-0 `type_name_mangled` on just the
    /// argument piece silently lost the argument's own pointer depth again.
    fn type_name_mangled_as_arg(self: *Self, dt: *const dtype.DataType) TranspileError![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        try self.append_mangled_type_depth(&buf, dt, 1);
        return buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
    }

    fn type_name_mangled(self: *Self, dt: *const dtype.DataType) TranspileError![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        try self.append_mangled_type(&buf, dt);
        return buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
    }

    fn append_mangled_type_with_subst_depth(
        self: *Self,
        buf: *ArrayList(u8),
        dt: *const dtype.DataType,
        params: utils.Vector(ArrayList(u8)),
        args: []*dtype.DataType,
        depth: usize,
    ) TranspileError!void {
        const max_depth: usize = 32;
        const max_segment_len: usize = 256;
        const max_total_len: usize = 8192;

        // Guard against malformed/cyclic dtype graphs that would recurse forever.
        if (depth > max_depth) {
            return TranspileError.TypeMismatch;
        }
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            for (params.items(), 0..) |p, i| {
                if (mem.eql(u8, p.items, dt.type_str.items)) {
                    try self.append_mangled_type_depth(buf, args[i], depth + 1);
                    return;
                }
            }
        }

        if (dt.type_str.items.len > max_segment_len) {
            return TranspileError.TypeMismatch;
        }
        if (buf.items.len >= max_total_len or dt.type_str.items.len > (max_total_len - buf.items.len)) {
            return TranspileError.TypeMismatch;
        }

        buf.appendSlice(dt.type_str.items) catch return TranspileError.MemoryAllocationFailed;
        // See the matching comment in `append_mangled_type_depth`: a generic
        // ARG's pointer depth must be part of its mangled identity, or
        // `Vec<Node>`/`Vec<Node*>` collide into the same name. Only at nested
        // (arg) depth, never the outer/top-level type.
        if (depth > 0 and dt.pointer_depth > 0) {
            buf.print("_ptr{d}", .{dt.pointer_depth}) catch return TranspileError.MemoryAllocationFailed;
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                if (buf.items.len + 2 > max_total_len) {
                    return TranspileError.TypeMismatch;
                }
                buf.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
                try self.append_mangled_type_with_subst_depth(buf, ga, params, args, depth + 1);
            }
        }
    }

    fn append_mangled_type_with_subst(self: *Self, buf: *ArrayList(u8), dt: *const dtype.DataType, params: utils.Vector(ArrayList(u8)), args: []*dtype.DataType) TranspileError!void {
        try self.append_mangled_type_with_subst_depth(buf, dt, params, args, 0);
    }

    fn type_name_mangled_with_subst(self: *Self, dt: *const dtype.DataType, params: utils.Vector(ArrayList(u8)), args: []*dtype.DataType) TranspileError![]const u8 {
        var buf = ArrayList(u8).init(self.allocator);
        errdefer buf.deinit();
        try self.append_mangled_type_with_subst(&buf, dt, params, args);
        return buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
    }

    fn type_name_mangled_for_emit(self: *Self, dt: *const dtype.DataType) TranspileError![]const u8 {
        if (self.type_subst_params != null and self.type_subst_args != null) {
            if (self.dtype_needs_subst(dt)) {
                return self.type_name_mangled_with_subst(dt, self.type_subst_params.?.*, self.type_subst_args.?);
            }
        }
        return self.type_name_mangled(dt);
    }

    fn type_from_dtype_with_subst(self: *Self, dt: *const dtype.DataType, params: utils.Vector(ArrayList(u8)), args: []*dtype.DataType) TranspileError!CheckedType {
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            const params_items = params.items();
            var i: usize = 0;
            while (i < params_items.len and i < args.len) : (i += 1) {
                const p = params_items[i];
                if (mem.eql(u8, p.items, dt.type_str.items)) {
                    const sub = args[i];
                    var out = type_from_dtype(sub);
                    if (dt.flags != null and dt.flags.?.is_array) {
                        out.is_array = true;
                        // Carry the array depth so a substituted `T[]` param matches a
                        // concrete `num[]` argument (CheckedType.eql compares
                        // array_depth). Without this, `Vec.push_many(T[] src)` rejected
                        // a `num[]` arg with a bogus type mismatch.
                        out.array_depth = if (dt.array_depth == 0) 1 else dt.array_depth;
                    }
                    out.pointer_depth += dt.pointer_depth;
                    out.dtype_ref = sub;
                    if (sub.generic_args != null and (sub.type == null or sub.type == .Unknown)) {
                        out.mangled_name = try self.type_name_mangled(sub);
                    }
                    return out;
                }
            }
        }

        if (dt.generic_args != null and (dt.type == null or dt.type == .Unknown)) {
            const sub_dt = try self.clone_dtype_with_subst_for_inst(dt, &params, args);
            var out = type_from_dtype(sub_dt);
            out.mangled_name = try self.type_name_mangled_with_subst(dt, params, args);
            return out;
        }

        const out = type_from_dtype(dt);
        return out;
    }

    fn dtype_needs_subst(self: *Self, dt: *const dtype.DataType) bool {
        const params = self.type_subst_params orelse return false;
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            for (params.items()) |p| {
                if (mem.eql(u8, p.items, dt.type_str.items)) return true;
            }
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                if (self.dtype_needs_subst(ga)) return true;
            }
        }
        return false;
    }

    /// Resolves a (possibly type-param) dtype to its concrete dtype under the active
    /// generic substitution. For a bare type param `K` it returns the substituted
    /// arg; otherwise the dtype itself. Used by the `__fun_key_eq`/`__fun_key_hash`
    /// intrinsics to choose string vs byte semantics in a monomorphized method.
    fn resolve_subst_dtype(self: *Self, dt: *const dtype.DataType) *const dtype.DataType {
        const params = self.type_subst_params orelse return dt;
        const args = self.type_subst_args orelse return dt;
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0 and dt.pointer_depth == 0) {
            for (params.items(), 0..) |p, i| {
                if (mem.eql(u8, p.items, dt.type_str.items) and i < args.len) return args[i];
            }
        }
        return dt;
    }

    /// True when an expression argument's concrete type (after generic subst) is the
    /// builtin string type. The argument is a parameter/local whose declared dtype
    /// may be a type param (`K`) that resolves to `str` in this monomorphization.
    fn arg_concrete_type_is_str(self: *Self, arg: ast.Node) bool {
        if (arg.type != .Identifier or arg.data == null) return false;
        const dt = self.identifier_declared_dtype(arg.data.?.sval.items) orelse return false;
        const resolved = self.resolve_subst_dtype(dt);
        if (resolved.pointer_depth != 0) return false;
        return resolved.type == .Str or mem.eql(u8, resolved.type_str.items, "str");
    }

    fn dtype_contains_type_param(self: *Self, dt: *const dtype.DataType, params: *const utils.Vector(ArrayList(u8))) bool {
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            for (params.items()) |p| {
                if (mem.eql(u8, p.items, dt.type_str.items)) return true;
            }
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                if (self.dtype_contains_type_param(ga, params)) return true;
            }
        }
        return false;
    }

    fn mangled_contains_type_param(self: *Self, mangled: []const u8, params: *const utils.Vector(ArrayList(u8))) bool {
        _ = self;
        for (params.items()) |p| {
            const needle = p.items;
            if (needle.len == 0) continue;
            var start: usize = 0;
            while (true) {
                const idx_opt = mem.indexOfPos(u8, mangled, start, "__") orelse break;
                const seg_start = idx_opt + 2;
                if (seg_start + needle.len <= mangled.len and mem.eql(u8, mangled[seg_start .. seg_start + needle.len], needle)) {
                    const seg_end = seg_start + needle.len;
                    if (seg_end == mangled.len or (seg_end + 2 <= mangled.len and mem.eql(u8, mangled[seg_end .. seg_end + 2], "__"))) {
                        return true;
                    }
                }
                start = seg_start;
            }
        }
        return false;
    }

    fn mangled_contains_unresolved_placeholder(self: *Self, mangled: []const u8) bool {
        var i: usize = 0;
        while (i + 2 <= mangled.len) {
            const sep = mem.indexOfPos(u8, mangled, i, "__") orelse break;
            const seg_start = sep + 2;
            if (seg_start >= mangled.len) break;

            const next_sep = mem.indexOfPos(u8, mangled, seg_start, "__") orelse mangled.len;
            const seg = mangled[seg_start..next_sep];
            // A single-uppercase-letter segment is an unresolved generic
            // placeholder (T/K/V) ONLY if it is not the name of an actual declared
            // single-letter type or quirk (e.g. `quirk Q`, `compound G`). Without
            // this, a single-letter quirk/type name in a mangled identifier (e.g.
            // `Foo__Q__getX`) was misread as a placeholder, so the impl method
            // definition was skipped and the program failed to link.
            if (seg.len == 1 and seg[0] >= 'A' and seg[0] <= 'Z') {
                const is_declared_type = has_compound_named(self, seg) or has_quirk_named(self, seg) or
                    (if (self.root_registry()) |reg| reg.enums_by_name.contains(seg) else false);
                if (!is_declared_type) return true;
            }
            i = next_sep;
        }
        return false;
    }

    fn generic_args_are_concrete(self: *Self, params: *const utils.Vector(ArrayList(u8)), gargs: []*dtype.DataType) bool {
        for (gargs) |ga| {
            if (self.dtype_contains_type_param(ga, params)) return false;
        }
        return true;
    }

    fn dtype_has_unresolved_placeholder(self: *Self, dt: *const dtype.DataType) bool {
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len == 1) {
            const c = dt.type_str.items[0];
            // A single uppercase letter is treated as an unresolved generic
            // placeholder (T/K/V) — UNLESS it is an actual declared single-letter
            // type (e.g. `compound G<T>` / `quirk Q`), which is a concrete type,
            // not a placeholder. Without this exclusion, single-letter type names
            // were misread as placeholders, producing false "cyclic compound
            // dependency" errors and dropped impl-method emission.
            if (c >= 'A' and c <= 'Z') {
                const name = dt.type_str.items;
                const is_declared_type = has_compound_named(self, name) or has_quirk_named(self, name) or
                    (if (self.root_registry()) |reg| reg.enums_by_name.contains(name) else false);
                if (!is_declared_type) return true;
            }
        }
        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                if (self.dtype_has_unresolved_placeholder(ga)) return true;
            }
        }
        return false;
    }

    fn function_has_unresolved_placeholder(self: *Self, node: ast.Node) bool {
        if (node.type != .Function or node.node_variant == null) return false;
        const function = node.node_variant.?.function;
        if (function.rtype) |rt| {
            if (self.dtype_has_unresolved_placeholder(&rt)) return true;
        }
        if (function.args) |args| {
            for (args.items()) |arg| {
                if (arg.*.type != .Variable or arg.*.node_variant == null) continue;
                if (self.dtype_has_unresolved_placeholder(arg.*.node_variant.?.variable.type)) return true;
            }
        }
        return false;
    }

    fn write_type_array_suffix(self: *Self, data_type: *const dtype.DataType) TranspileError!void {
        if (data_type.array) |array| {
            if (!array.brackets.is_empty()) {
                for (array.brackets.items()) |bracket_node| {
                    try self.write("[");
                    if (bracket_node.type == .Bracket) {
                        try self.transpile_node(bracket_node.node_variant.?.bracket.inner.*);
                    } else {
                        try self.transpile_node(bracket_node);
                    }
                    try self.write("]");
                }
                return;
            }
        }

        if (data_type.array_depth > 0) {
            var depth_i: usize = 0;
            while (depth_i < data_type.array_depth) : (depth_i += 1) {
                try self.write("[]");
            }
            return;
        }

        if (data_type.flags != null and data_type.flags.?.is_array) {
            try self.write("[]");
        }
    }

    /// Helper function to write data type to output (no substitutions).
    fn write_type_no_subst(self: *Self, data_type: dtype.DataType) TranspileError!void {
        if (data_type.generic_args != null and data_type.type == .Unknown) {
            const mangled = try self.type_name_mangled(&data_type);
            defer self.allocator.free(mangled);
            try self.write(mangled);
        } else {
            const type_name = if ((data_type.type == null or data_type.type == .Unknown) and data_type.type_str.items.len > 0)
                self.c_type_name_for_user_type(data_type.type_str.items)
            else
                data_type.type_str.items;

            if (!(try self.write_dynamic_int_type(type_name))) {
                const c_type = map_type_to_c(type_name);
                try self.write(c_type);
            }
        }

        const ptr_depth: usize = if (data_type.pointer_depth > 0) data_type.pointer_depth else blk: {
            if (data_type.flags != null and data_type.flags.?.is_pointer) break :blk 1;
            break :blk 0;
        };
        if (ptr_depth > 0) {
            var i: usize = 0;
            while (i < ptr_depth) : (i += 1) {
                try self.write("*");
            }
        }
    }

    /// Helper function to write data type to output
    fn write_type(self: *Self, data_type: dtype.DataType) TranspileError!void {
        if (self.type_subst_params != null and self.type_subst_args != null) {
            if (self.dtype_needs_subst(&data_type)) {
                return self.write_type_with_subst(&data_type, self.type_subst_params.?.*, self.type_subst_args.?);
            }
        }
        return self.write_type_no_subst(data_type);
    }

    /// Writes a function/method's C return type, INCLUDING the extra pointer
    /// level(s) a `T[]` return type needs. Unlike a parameter or local
    /// variable -- which express an array via C's postfix `T name[]`
    /// declarator or an explicit `array_as_pointer` prefix star, both handled
    /// separately from `write_type` at their own call sites -- a C function
    /// return type has no such postfix form (you can't write `T f()[]`), so
    /// the array-ness has to become an ordinary leading `*` here instead, one
    /// per array dimension. Shared by every call site that emits a return
    /// type as part of a real C function/method signature (prototypes,
    /// definitions, quirk vtables/wrappers, generic instantiations, async
    /// support scaffolding) so none of them silently drop this again.
    fn write_return_type(self: *Self, rt: dtype.DataType) TranspileError!void {
        try self.write_type(rt);
        if (rt.flags != null and rt.flags.?.is_array) {
            const depth: usize = if (rt.array_depth > 0) rt.array_depth else 1;
            var i: usize = 0;
            while (i < depth) : (i += 1) try self.write("*");
        }
    }

    fn c_ident_sanitize(self: *Self, raw: []const u8) TranspileError![]const u8 {
        var out = ArrayList(u8).init(self.allocator);
        errdefer out.deinit();
        for (raw) |c| {
            if ((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_') {
                out.append(c) catch return TranspileError.MemoryAllocationFailed;
            } else {
                out.append('_') catch return TranspileError.MemoryAllocationFailed;
            }
        }
        return out.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
    }

    const SanitizedIdent = struct {
        slice: []const u8,
        owned: bool,
    };

    fn c_ident_sanitize_temp(self: *Self, raw: []const u8, stack_buf: []u8) TranspileError!SanitizedIdent {
        if (raw.len <= stack_buf.len) {
            var i: usize = 0;
            while (i < raw.len) : (i += 1) {
                const c = raw[i];
                stack_buf[i] = if ((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_') c else '_';
            }
            return .{ .slice = stack_buf[0..raw.len], .owned = false };
        }

        // Fallback for unusually long identifiers: allocate from the backing allocator
        // so the memory is promptly freed and doesn't bloat the arena.
        const heap_buf = self.backing_allocator.alloc(u8, raw.len) catch return TranspileError.MemoryAllocationFailed;
        var i: usize = 0;
        while (i < raw.len) : (i += 1) {
            const c = raw[i];
            heap_buf[i] = if ((c >= 'a' and c <= 'z') or (c >= 'A' and c <= 'Z') or (c >= '0' and c <= '9') or c == '_') c else '_';
        }
        return .{ .slice = heap_buf, .owned = true };
    }

    /// Builds a generated C identifier by formatting `fmt` with `args` onto the
    /// backing allocator. Use this (instead of a fixed `bufPrint` stack buffer)
    /// whenever the format includes an unbounded `{s}` such as a (sanitized) type
    /// or method name — those can be arbitrarily long for deeply-nested generics
    /// or long user identifiers and would otherwise overflow a fixed buffer and
    /// panic. The returned slice is owned by the caller, which must free it via
    /// `backing_allocator` (typically with `defer`).
    fn c_name_alloc(self: *Self, comptime fmt: []const u8, args: anytype) TranspileError![]u8 {
        return std.fmt.allocPrint(self.backing_allocator, fmt, args) catch return TranspileError.MemoryAllocationFailed;
    }

    fn quirk_sig_hash(sig: []const u8) u64 {
        return std.hash.Wyhash.hash(0, sig);
    }

    fn quirk_sig_hash_cached(self: *Self, sig: []const u8) u64 {
        const reg = self.root_registry() orelse return quirk_sig_hash(sig);
        return reg.quirk_hash_by_sig.get(sig) orelse quirk_sig_hash(sig);
    }

    const QuirkCNames = struct {
        quirk: [64]u8,
        quirk_len: usize,
        vtable: [72]u8,
        vtable_len: usize,
    };

    fn write_quirk_c_names_hash(h: u64) TranspileError!QuirkCNames {
        var out: QuirkCNames = undefined;
        out.quirk_len = (std.fmt.bufPrint(&out.quirk, "__fun_quirk_{x}", .{h}) catch unreachable).len;
        out.vtable_len = (std.fmt.bufPrint(&out.vtable, "__fun_quirk_{x}_vtable", .{h}) catch unreachable).len;
        return out;
    }

    fn write_quirk_c_names(sig: []const u8) TranspileError!QuirkCNames {
        return write_quirk_c_names_hash(quirk_sig_hash(sig));
    }

    fn root_registry(self: *Self) ?*TypeRegistry {
        const root = self.get_root();
        if (root.type_registry) |*reg| return reg;
        return null;
    }

    fn c_type_name_for_user_type(self: *Self, name: []const u8) []const u8 {
        const reg = self.root_registry() orelse return name;

        if (reg.enums_by_name.get(name)) |enode| {
            if (enode.node_variant != null) {
                return enode.node_variant.?.enum_decl.name.items;
            }
        }

        if (reg.compounds_by_name.get(name)) |cnode| {
            if (cnode.node_variant != null) {
                return cnode.node_variant.?.compound.name.items;
            }
        }

        if (reg.quirk_sig_by_name.get(name)) |sig| {
            if (reg.quirks_by_sig.get(sig)) |qnode| {
                if (qnode.node_variant != null) {
                    return qnode.node_variant.?.quirk.name.items;
                }
            }
        }

        return name;
    }

    fn is_quirk_name(self: *Self, name: []const u8) bool {
        const reg = self.root_registry() orelse return false;
        return reg.quirk_sig_by_name.contains(name);
    }

    fn identifier_declared_dtype(self: *Self, ident: []const u8) ?*const dtype.DataType {
        const ent = self.get_scope_entity(ident) orelse return null;
        const ent_node = ent.node orelse return null;
        if (ent_node.type != .Variable or ent_node.node_variant == null) return null;
        return ent_node.node_variant.?.variable.type;
    }

    fn identifier_is_quirk_typed(self: *Self, ident: []const u8) bool {
        const dt = self.identifier_declared_dtype(ident) orelse return false;
        if (dt.type != .Unknown) return false;
        return self.is_quirk_name(dt.type_str.items);
    }

    fn expr_named_type_from_scope(self: *Self, node: ast.Node) ?[]const u8 {
        switch (node.type) {
            .Identifier => {
                if (node.data == null) return null;
                const dt = self.identifier_declared_dtype(node.data.?.sval.items) orelse return null;
                if (dt.type != .Unknown) return null;
                return dt.type_str.items;
            },
            .ExpressionParenthesis => {
                if (node.node_variant == null) return null;
                return self.expr_named_type_from_scope(node.node_variant.?.paren.exp.*);
            },
            .Expression => {
                if (node.node_variant == null) return null;
                const exp = node.node_variant.?.exp;
                // Array element `arr[i]`: the element's named type is the array
                // variable's declared element type (drop array-ness). Lets quirk
                // dispatch recognize `arr[i].method()` on a `Quirk[]`.
                if (mem.eql(u8, exp.op, "[]")) {
                    const arr_left = exp.left orelse return null;
                    if (arr_left.type == .Identifier and arr_left.data != null) {
                        const dt = self.identifier_declared_dtype(arr_left.data.?.sval.items) orelse return null;
                        if (dt.type != .Unknown) return null;
                        return dt.type_str.items;
                    }
                    return null;
                }
                // A call expression (`recv.unwrap()`, `make()`, ...) reached as a link
                // in a longer chain (`recv.unwrap().field.method()`): its named type is
                // the call's return type, resolved the same way a call-rooted receiver
                // is resolved elsewhere (`expr_compound_return_type_name` handles both
                // free-function and method calls, including generic monomorphization).
                // Without this, only a chain rooted at a plain identifier/field access
                // was ever recognized here -- a call in the MIDDLE of the chain broke
                // resolution for every link after it.
                if (mem.eql(u8, exp.op, "()")) {
                    return self.expr_compound_return_type_name(node);
                }
                if (!mem.eql(u8, exp.op, ".")) return null;

                const left = exp.left orelse return null;
                const right = exp.right orelse return null;
                if (right.*.type != .Identifier or right.*.data == null) return null;

                // `left` may itself be a call expression in the middle of the chain
                // (e.g. `found.unwrap().diagnostics`, where `found.unwrap()` is a
                // plain/method call). `expr_resolved_compound_type_name` combines
                // this scope-based lookup with `expr_compound_return_type_name` (call
                // results), so it resolves both a named value AND a call's return
                // type -- recursing through it here (instead of back into this
                // narrower function) lets a call-rooted chain resolve at every hop,
                // not just a single field before the terminal method call.
                const left_name = self.expr_resolved_compound_type_name(left.*) orelse return null;
                const left_name_canon = self.canonical_compound_name(left_name);
                const fdt = self.lookup_compound_field(left_name_canon, right.*.data.?.sval.items) orelse return null;
                if (fdt.type != .Unknown) return null;
                return fdt.type_str.items;
            },
            else => return null,
        }
    }

    fn expr_is_quirk_typed_from_scope(self: *Self, node: ast.Node) bool {
        const tname = self.expr_named_type_from_scope(node) orelse return false;
        return self.is_quirk_name(tname);
    }

    /// True when `node` is an addressable C lvalue: a named identifier, or a
    /// field/index access chain rooted in one. False for a call expression (its
    /// result is a C rvalue -- `&(call())` is invalid) and anything else this
    /// function can't prove is addressable. Used to decide whether a receiver
    /// reached through a field access (`x.field.method()`) can have `&(...)`
    /// taken directly, or must first be materialized into a temp (see
    /// `emit_materialized_field_method_call`).
    fn expr_is_addressable_lvalue(self: *Self, node: ast.Node) bool {
        return switch (node.type) {
            .Identifier => true,
            .ExpressionParenthesis => if (node.node_variant) |nv| self.expr_is_addressable_lvalue(nv.paren.exp.*) else false,
            .Expression => blk: {
                const exp = (node.node_variant orelse break :blk false).exp;
                if (!mem.eql(u8, exp.op, ".") and !mem.eql(u8, exp.op, "[]")) break :blk false;
                const left = exp.left orelse break :blk false;
                break :blk self.expr_is_addressable_lvalue(left.*);
            },
            else => false,
        };
    }

    /// Emits a full method-call expression for a receiver reached through
    /// `fbase.field_name` where `fbase` is NOT an addressable lvalue (e.g. a
    /// call in the middle of the chain, like `found.unwrap().diagnostics.free()`
    /// -- `found.unwrap()` is a plain function call, so its result is a C
    /// rvalue and `&(fbase.field_name)` would be invalid). Materializes `fbase`
    /// into a temp local of type `fbase_type_name` once, then addresses (or
    /// passes directly, if the field is itself a pointer) the temp's field --
    /// evaluating `fbase` exactly once: `({ T __t = fbase; (fn(&(__t.field), args)); })`.
    fn emit_materialized_field_method_call(self: *Self, fbase: ast.Node, fbase_type_name: []const u8, field_name: []const u8, field_is_pointer: bool, fn_name: []const u8, args_node: ?*ast.Node) TranspileError!void {
        const tmp = try self.next_tmp_name("frecv");
        defer self.allocator.free(tmp);
        try self.write("({ ");
        try self.write(self.canonical_compound_name(fbase_type_name));
        try self.write(" ");
        try self.write(tmp);
        try self.write(" = ");
        try self.transpile_node(fbase);
        try self.write("; (");
        try self.write_module_impl_method_ref(fn_name);
        try self.write("(");
        if (!field_is_pointer) try self.write("&(");
        try self.write(tmp);
        try self.write(".");
        try self.write(field_name);
        if (!field_is_pointer) try self.write(")");
        if (args_node) |right| {
            const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                right.node_variant.?.paren.exp.*
            else
                right.*;
            if (inner.type != .Blank) {
                try self.write(", ");
                try self.transpile_node(inner);
            }
        }
        try self.write(")); })");
    }

    /// Classifies a `fit` subject expression so codegen can choose a lowering:
    /// `.Str`/`.Dec` subjects can't use a C `switch` (which needs an integer) and
    /// must lower to an if/else-if comparison chain; everything else (num, chr,
    /// bin, enum) uses a `switch`. Inspects the subject's declared dtype when it is
    /// an in-scope identifier, falling back to the branch conditions' literal types.
    /// Best-effort C element type for an array literal used as a compound literal
    /// `(T[]){...}`. Inspects the first element's kind/declared type. Returns null
    /// when it can't be determined (caller falls back to a bare brace-list). Caller
    /// owns the returned slice.
    fn bracket_element_c_type(self: *Self, bracket_node: ast.Node) ?[]const u8 {
        if (bracket_node.node_variant == null) return null;
        var elems = ArrayList(*ast.Node).init(self.allocator);
        defer elems.deinit();
        self.flatten_call_args_ptr(bracket_node.node_variant.?.bracket.inner, &elems) catch return null;
        if (elems.items.len == 0) return null;
        const first = elems.items[0].*;
        switch (first.type) {
            .Number => {
                if (first.data) |d| {
                    switch (d) {
                        .dnum => return self.allocator.dupe(u8, "double") catch null,
                        .cval => return self.allocator.dupe(u8, "char") catch null,
                        else => return self.allocator.dupe(u8, "int64_t") catch null,
                    }
                }
                return self.allocator.dupe(u8, "int64_t") catch null;
            },
            .String => return self.allocator.dupe(u8, "char*") catch null,
            .Boolean => return self.allocator.dupe(u8, "bool") catch null,
            .Identifier => {
                // A named value: use its declared type's C form.
                if (first.data) |d| {
                    if (self.identifier_declared_dtype(d.sval.items)) |dt| {
                        if (dt.type == .Unknown) {
                            // Compound/enum: the C type is the (canonical) name.
                            return self.allocator.dupe(u8, self.canonical_compound_name(dt.type_str.items)) catch null;
                        }
                        return self.allocator.dupe(u8, map_type_to_c(dt.type_str.items)) catch null;
                    }
                }
                return null;
            },
            else => return null,
        }
    }

    fn fit_subject_base_type(self: *Self, fit_exp: ast.Node, branches: []const ast.FitBranch) dtype.DataTypeType {
        // Subject is a named local/param: use its declared base type.
        if (fit_exp.type == .Identifier and fit_exp.data != null) {
            if (self.identifier_declared_dtype(fit_exp.data.?.sval.items)) |dt| {
                if (dt.pointer_depth == 0) {
                    // Only str/dec require the comparison-chain lowering; num, chr,
                    // bin, and enums (`.Unknown` named) all use a C `switch`.
                    if (dt.type == .Str) return .Str;
                    if (dt.type == .Dec) return .Dec;
                }
            }
        }
        // Fall back to branch-condition literal types (covers literal subjects and
        // cases where the subject dtype isn't resolvable at codegen time).
        for (branches) |branch| {
            if (branch.condition) |c| {
                if (c.*.type == .String) return .Str;
            }
        }
        return .Num;
    }

    /// If the fit subject is a value of a tagged-union (data-carrying) enum, return
    /// that enum's name; otherwise null. Resolves via the subject's declared type
    /// (identifier) or its branch conditions' variant paths (fallback).
    fn fit_subject_tagged_union_name(self: *Self, fit_exp: ast.Node, branches: []const ast.FitBranch) ?[]const u8 {
        // A named local/param subject: use its declared base type.
        if (fit_exp.type == .Identifier and fit_exp.data != null) {
            if (self.identifier_declared_dtype(fit_exp.data.?.sval.items)) |dt| {
                if (dt.pointer_depth == 0 and dt.type_str.items.len > 0) {
                    const nm = dt.type_str.items;
                    if (self.enum_name_is_tagged_union(nm)) {
                        // A GENERIC enum subject (`Option<num>`) is the monomorphized
                        // `Option__num`; switch on its mangled tag. Dupe onto the
                        // arena (stable, auto-freed) so the return is always a
                        // borrowed slice the caller need not free.
                        if (dt.generic_args != null) {
                            if (self.type_name_mangled(dt) catch null) |mangled| {
                                defer self.allocator.free(mangled);
                                return self.arena.allocator().dupe(u8, mangled) catch nm;
                            }
                        }
                        return nm;
                    }
                }
            }
        }
        // `fit *l { ... }` dereferencing a pointer identifier: same idea as
        // the bare-identifier case above, but resolved from the POINTEE's
        // declared type. Without this, a fit over a generic tagged-union
        // enum through a pointer (`fit *l` where `l: List<dec>*`) from a
        // PLAIN, non-generic function fell all the way through to the
        // arm-based fallback below, which -- with no active generic-function
        // substitution to mangle through -- switched on the bare,
        // never-emitted template name instead of the concrete instantiation.
        if (fit_exp.type == .Unary and fit_exp.node_variant != null) {
            const u = fit_exp.node_variant.?.unary;
            if (mem.eql(u8, u.op, "*") and u.operand.type == .Identifier and u.operand.data != null) {
                if (self.identifier_declared_dtype(u.operand.data.?.sval.items)) |dt| {
                    if (dt.pointer_depth == 1 and dt.type_str.items.len > 0) {
                        const nm = dt.type_str.items;
                        if (self.enum_name_is_tagged_union(nm)) {
                            if (dt.generic_args != null) {
                                // Prefer the ACTIVE generic-function/method substitution
                                // when one is in effect (e.g. `self`'s declared type inside
                                // a generic enum's own template method body is still the
                                // abstract `Option<T>` — mangling it bare would wrongly
                                // give "Option__T" instead of the instantiation actually
                                // being emitted). Only fall back to the dtype's own
                                // (already-concrete, e.g. `List<dec>`) mangling when no
                                // substitution is active.
                                if (self.type_name_mangled_for_emit(dt) catch null) |mangled| {
                                    defer self.allocator.free(mangled);
                                    return self.arena.allocator().dupe(u8, mangled) catch nm;
                                }
                            }
                            return nm;
                        }
                    }
                }
            }
        }
        // A call/method-call subject (`it.next()`, `some(7)`, `box.at()`) returning a
        // data enum: resolve the call's MONOMORPHIZED return type so the switch uses
        // the mangled instance (`Option__num`/`Option__num_Some`) rather than the bare
        // base. This must precede the arm-based fallback, which cannot recover the
        // type args from `Option.Some` alone.
        if (self.expr_compound_return_type_name(fit_exp)) |rtn| {
            // `rtn` may be a monomorphized instance (`Option__num`); test the base
            // (`Option`) for tagged-union-ness, then return the mangled instance so the
            // switch uses `Option__num`/`Option__num_Some`.
            const rbase = if (mem.indexOf(u8, rtn, "__")) |bi| rtn[0..bi] else rtn;
            if (self.enum_name_is_tagged_union(rbase)) return rtn;
        }
        // A non-identifier subject (e.g. `*self` inside an impl method, a channel
        // recv `<- ch`, any call returning a data-enum) has no simple declared name.
        // Fall back to the arms: an `Enum.Variant` condition names the tagged-union
        // enum being matched, so the subject is switched on `.tag` (via
        // emit_tagged_union_fit) rather than mis-emitted as a switch on the struct.
        for (branches) |branch| {
            const cond = branch.condition orelse continue;
            if (self.enum_variant_path(cond)) |vp| {
                if (self.enum_name_is_tagged_union(vp.enum_name)) {
                    // Inside a monomorphized generic-enum method (`impl Option<T>`),
                    // `fit *self` matches `Option.Some` — but the concrete subject is
                    // `Option__num`. Mangle the base with the active substitution
                    // context so the switch uses `Option__num`/`Option__num_Some`.
                    if (self.mangled_enum_with_active_subst(vp.enum_name)) |m| return m;
                    return vp.enum_name;
                }
            }
        }
        return null;
    }

    /// If `enum_name` is a generic data enum AND a type-parameter substitution is
    /// active (we're emitting a monomorphized method), return the mangled instance
    /// name (`Option__num`) by substituting the enum's type params through the
    /// active args. Returns null when the enum isn't generic or no subst is active.
    /// The result is arena-owned (stable, no manual free).
    fn mangled_enum_with_active_subst(self: *Self, enum_name: []const u8) ?[]const u8 {
        const params = self.type_subst_params orelse return null;
        const args = self.type_subst_args orelse return null;

        // Prefer resolving directly from the CURRENT method's own declared
        // return type when it names this enum directly (e.g. `wrap<U>(U x)
        // Maybe<U>` constructing `Maybe.Has(...)` in its body) -- this reads
        // the ACTUAL written type structure, so unlike the name-matching loop
        // below it can't be fooled by a coincidental NAME collision between
        // the enum's own template param and one of the active substitution's
        // params (e.g. both conventionally called "T": the enclosing impl's
        // `Box<T>` and an unrelated `Maybe<T>`'s own internal param).
        if (self.current_method_return_dtype) |rdt| {
            if (mem.eql(u8, rdt.type_str.items, enum_name)) {
                if (self.type_name_mangled_with_subst(rdt, params.*, args) catch null) |m| {
                    // m is owned by the allocator; copy onto the arena for a
                    // stable, no-free return, matching this function's contract.
                    defer self.allocator.free(m);
                    return self.arena.allocator().dupe(u8, m) catch null;
                }
            }
        }

        const reg = self.root_registry() orelse return null;
        const enode = reg.enums_by_name.get(enum_name) orelse return null;
        if (enode.node_variant == null) return null;
        const eparams = enode.node_variant.?.enum_decl.type_params orelse return null;

        // Build mangled name: `<enum>__<arg0>[__<arg1>...]`, where each enum type
        // param is mapped to its concrete type via the active (impl) substitution.
        var buf = ArrayList(u8).init(self.arena.allocator());
        buf.appendSlice(enum_name) catch return null;
        for (eparams.items()) |ep| {
            // Find the active substitution for this enum param name.
            var resolved: ?*dtype.DataType = null;
            for (params.items(), 0..) |p, i| {
                if (mem.eql(u8, p.items, ep.items) and i < args.len) {
                    resolved = args[i];
                    break;
                }
            }
            if (resolved == null) return null; // unresolved param -> not concrete
            const rt = resolved.?;
            const arg_name = self.type_name_mangled_as_arg(rt) catch return null;
            defer self.allocator.free(arg_name);
            buf.appendSlice("__") catch return null;
            buf.appendSlice(arg_name) catch return null;
        }
        return buf.items;
    }

    /// Lower a `fit` over a tagged-union subject:
    ///   { Enum __fitN = <subj>; switch (__fitN.tag) {
    ///       if (__fitN.tag == Enum_Variant) { <Type b = __fitN.payload.Variant._i;>* <body> }
    ///       else if (...) { ... } else { <default body> } }
    /// The subject is snapshotted into a temp so payload reads and a possibly
    /// side-effecting subject expression are evaluated exactly once.
    ///
    /// An `if`/`else-if` chain (rather than a `switch`) is used deliberately: a user
    /// `break`/`continue` inside a `fit` arm must escape the ENCLOSING LOOP, not a
    /// `switch`. With a switch, `fit it.next() { Option.None -> { break; } }` inside
    /// `for true { ... }` would break only the switch and loop forever. The chain has
    /// no such hidden control-flow target, so user `break`/`continue` behave naturally.
    /// Register a for-loop binding (`name`, typed `elem_dt`) as a scope variable so the
    /// body's references to it resolve with the right type. The C declaration line was
    /// already emitted by the caller via `__auto_type`.
    fn bind_loop_var(self: *Self, name: []const u8, elem_dt: *const dtype.DataType) TranspileError!void {
        const item_dt = try self.clone_dtype(elem_dt);
        const item_node = self.allocator.create(ast.Node) catch return TranspileError.MemoryAllocationFailed;
        var item_name_buf = ArrayList(u8).init(self.allocator);
        item_name_buf.appendSlice(name) catch return TranspileError.MemoryAllocationFailed;
        item_node.* = .{
            .type = .Variable,
            .node_variant = .{ .variable = .{ .type = item_dt, .name = item_name_buf, .val = null } },
        };
        const item_ent = self.allocator.create(scope.ScopeEntity) catch return TranspileError.MemoryAllocationFailed;
        item_ent.* = .{ .flags = .{ .on_stack = false }, .node = item_node, .name = name };
        try self.push_scope_entity(item_ent);
        self.owned_scope_entities.append(item_ent) catch return TranspileError.MemoryAllocationFailed;
    }

    /// Lower `for item : iterable { body }` via the Iterator protocol when `iterable`
    /// is a Map/Set/user iterator/collection (anything `resolve_iterable_elem` accepts).
    /// Returns true when handled; false to defer to the legacy array/Vec fast path.
    ///
    /// Emitted shape (the established next()/Option consumption idiom, with an
    /// if/else-if `fit` so a user `break`/`continue` targets THIS loop):
    ///   { <IterT> __it = <iterable>[.iter()]; for (;;) {
    ///       <OptT> __o = __it.next();
    ///       if (__o.tag == Opt_None) break;
    ///       <ElemT> item = __o.payload.Some._0;  <body> } }
    fn emit_iter_protocol_for(self: *Self, fi: anytype) TranspileError!bool {
        // Resolve the iterable expression's compound/instance type name.
        const ty = self.expr_resolved_compound_type_name(fi.iterable.*) orelse return false;
        const dt = (self.dtype_from_mangled_type(self.canonical_compound_name(ty)) catch null) orelse
            (self.lookup_receiver_dtype(fi.iterable.*) orelse return false);
        const base = if (mem.indexOf(u8, dt.type_str.items, "__")) |i| dt.type_str.items[0..i] else dt.type_str.items;
        // A plain Vec identifier keeps the faster direct-index legacy path.
        if (mem.eql(u8, base, "Vec") and fi.iterable.type == .Identifier) return false;
        const ie = self.resolve_iterable_elem(dt) orelse return false;

        // Resolve the EMITTED C function names for `iter` (on the collection) and
        // `next` (on the iterator). Fun method calls lower to mangled free functions
        // (`Set__num__iter`, `SetIter__num__Iterator__next`), so we cannot write
        // `.iter()`/`.next()` as C member access — resolve and call them directly.
        const coll_canon = self.canonical_compound_name(ty);
        const next_fn = self.lookup_plain_impl_method_fn(null, ie.iter_type_name, "next") orelse return false;
        const iter_fn: ?[]const u8 = if (ie.needs_iter_call)
            (self.lookup_plain_impl_method_fn(null, coll_canon, "iter") orelse return false)
        else
            null;

        const it_tmp = try self.next_tmp_name("iter");
        defer self.allocator.free(it_tmp);
        const opt_tmp = try self.next_tmp_name("opt");
        defer self.allocator.free(opt_tmp);

        // The element is a generic ARGUMENT of the `Option__<Elem>` name built
        // below, so its own pointer depth belongs in the mangled segment
        // (`Node_ptr1`). The depth-0 helper drops it, which named a type that
        // was never emitted (`Option__Node` for a `Vec<Node*>`).
        const opt_name = self.type_name_mangled_as_arg(ie.elem) catch return false;
        defer self.allocator.free(opt_name);
        // The iterator's next() returns Option<ElemT>; mangle that instance name.
        const opt_inst = std.fmt.allocPrint(self.allocator, "Option__{s}", .{opt_name}) catch return TranspileError.MemoryAllocationFailed;
        defer self.allocator.free(opt_inst);

        try self.write("{");
        self.indent();

        // When the iterable is an rvalue (e.g. a call like `map.keys()`), we cannot
        // take its address directly (`&(rvalue)` is invalid C, and iter()/get()
        // receive `self` by pointer). Materialize it into a named source temp first
        // and reference the temp wherever `&<iterable>` is needed. A plain
        // identifier is already an lvalue, so we address it in place (and avoid
        // copying a potentially non-copyable collection header unnecessarily).
        const iterable_is_lvalue = fi.iterable.type == .Identifier;
        var src_tmp: ?[]const u8 = null;
        defer if (src_tmp) |s| self.allocator.free(s);
        if (!iterable_is_lvalue) {
            // Declare the temp with the MANGLED collection type (e.g. `Vec__num`,
            // not the bare base `Vec`). `coll_canon` is the instantiated/canonical
            // name already used for the iter()/get() lookups below.
            const src_type = if (coll_canon.len != 0) coll_canon else ty;
            const s = try self.next_tmp_name("iter_src");
            src_tmp = s;
            try self.write_indent();
            try self.write(src_type);
            try self.write(" ");
            try self.write(s);
            try self.write(" = ");
            try self.transpile_node(fi.iterable.*);
            try self.write(";");
        }

        // Materialize the iterator into a temp (call iter() when the source is a
        // collection; otherwise the value already IS the iterator). The iterator is
        // taken by address since iter()/next() receive `self` by pointer.
        try self.write_indent();
        try self.write(ie.iter_type_name);
        try self.write(" ");
        try self.write(it_tmp);
        try self.write(" = ");
        if (iter_fn) |ifn| {
            try self.write(ifn);
            try self.write("(&(");
            if (src_tmp) |s| {
                try self.write(s);
            } else {
                try self.transpile_node(fi.iterable.*);
            }
            try self.write("))");
        } else if (src_tmp) |s| {
            try self.write(s);
        } else {
            try self.transpile_node(fi.iterable.*);
        }
        try self.write(";");

        try self.write_indent();
        try self.write("for (;;) {");
        self.indent();

        // Pull the next Option<Elem>; break on None.
        try self.write_indent();
        try self.write(opt_inst);
        try self.write(" ");
        try self.write(opt_tmp);
        try self.print(" = {s}(&{s});", .{ next_fn, it_tmp });
        try self.write_indent();
        try self.print("if ({s}.tag == {s}_None) break;", .{ opt_tmp, opt_inst });

        try self.push_defer_scope(.loop);
        defer self.pop_defer_scope();
        _ = try self.new_scope();
        defer self.finish_scope();

        // `for k, v :: map` — pair iteration over a Map. The iterator yields KEYS, so
        // the payload binds to the index/key name and the value is looked up via the
        // map's `get`. Detected when an index name is present AND the source is a Map.
        const map_kv: ?MapKV = if (fi.index_name != null) self.map_kv_dtypes(dt) else null;
        if (map_kv) |kv| {
            const get_fn = self.lookup_plain_impl_method_fn(null, coll_canon, "get") orelse return false;
            // key = the yielded Some payload
            try self.write_indent();
            try self.write_type(kv.key.*);
            try self.write(" ");
            try self.write(fi.index_name.?);
            try self.print(" = {s}.payload.Some._0;\n", .{opt_tmp});
            // value = map.get(key)
            try self.write_indent();
            try self.write_type(kv.val.*);
            try self.write(" ");
            try self.write(fi.item_name);
            try self.print(" = {s}(&(", .{get_fn});
            if (src_tmp) |s| {
                try self.write(s);
            } else {
                try self.transpile_node(fi.iterable.*);
            }
            try self.print("), {s});\n", .{fi.index_name.?});

            try self.bind_loop_var(fi.index_name.?, kv.key);
            try self.bind_loop_var(fi.item_name, kv.val);
        } else {
            // Bind the Some payload as the loop item.
            try self.write_indent();
            try self.write_type(ie.elem.*);
            try self.write(" ");
            try self.write(fi.item_name);
            try self.print(" = {s}.payload.Some._0;\n", .{opt_tmp});
            try self.bind_loop_var(fi.item_name, ie.elem);
        }

        try self.transpile_block_contents(fi.body);
        if (!self.block_ends_with_scope_terminator(fi.body)) {
            try self.emit_current_scope_defers();
        }

        self.dedent();
        try self.write_indent();
        try self.write("}");
        self.dedent();
        try self.write_indent();
        try self.write("}");
        return true;
    }

    fn emit_tagged_union_fit(self: *Self, fit: anytype, enum_name: []const u8) TranspileError!void {
        const tmp = try self.next_tmp_name("fit");
        defer self.allocator.free(tmp);

        try self.write("{");
        self.indent();
        try self.write_indent();
        try self.write(enum_name);
        try self.write(" ");
        try self.write(tmp);
        try self.write(" = ");
        try self.transpile_node(fit.exp.*);
        try self.write(";");

        var first = true;
        for (fit.branches.items()) |branch| {
            if (branch.condition) |condition| {
                // The condition is the variant path `Enum.Variant` (or `.Variant`).
                const variant_name = self.fit_variant_name_of(condition.*) orelse {
                    self.report_type_error(condition.*, "fit arm on a data-carrying enum must match a variant", .{});
                    return TranspileError.TypeMismatch;
                };
                try self.write_indent();
                if (first) {
                    try self.write("if (");
                } else {
                    try self.write("else if (");
                }
                first = false;
                try self.print("{s}.tag == {s}_{s}) {{", .{ tmp, enum_name, variant_name });
                self.indent();

                // Each arm body gets its own scope so payload bindings are visible to
                // method/field resolution inside it (and don't leak to sibling arms).
                _ = try self.new_scope();

                // Bind the matched variant's payload fields into locals.
                if (branch.bindings) |binds| {
                    const variant = self.lookup_enum_variant(enum_name, variant_name);
                    const payload = if (variant) |v| v.payload else null;
                    for (binds.items(), 0..) |bname, i| {
                        try self.write_indent();
                        if (payload) |pl| {
                            if (i < pl.count) {
                                // A type-parameter payload (`Some(T)` of a generic
                                // enum) has no concrete spelling here — let C infer
                                // the binding type from the (already-monomorphized)
                                // payload field via `__auto_type`. Concrete payloads
                                // (`Circle(num)`) emit their explicit type. A payload
                                // that merely REFERENCES a type param without bare-
                                // BEING one (`List<T>*` in a self-referential
                                // `enum List<T> { Cons(T, List<T>*), Nil }`) needs the
                                // same `__auto_type` treatment: outside an active
                                // generic-function substitution context, `write_type`
                                // below has no way to resolve the abstract `T` down to
                                // the concrete instantiation actually in play, and
                                // emitted an undeclared `List__T*` instead of
                                // `List__dec*`. The RHS (`tmp.payload.Variant._i`) is
                                // already the correctly-monomorphized C field, so
                                // `__auto_type` just infers from it directly.
                                if (self.enum_payload_is_type_param(enum_name, pl.items()[i])) {
                                    if (self.resolve_fit_payload_dtype(enum_name, pl.items()[i])) |concrete_dt| {
                                        try self.write_type(concrete_dt.*);
                                        try self.write(" ");
                                    } else {
                                        try self.write("__auto_type ");
                                    }
                                } else if (self.enum_payload_references_type_param(enum_name, pl.items()[i])) {
                                    try self.write("__auto_type ");
                                } else {
                                    try self.write_type(pl.items()[i].*);
                                    try self.write(" ");
                                }
                            } else {
                                try self.write("__auto_type ");
                            }
                        } else {
                            try self.write("__auto_type ");
                        }
                        try self.write(bname.items);
                        try self.print(" = {s}.payload.{s}._{d};", .{ tmp, variant_name, i });

                        // Register the payload binding in scope with its RESOLVED type so
                        // the arm body can call methods on it (`a.len()` where `a:
                        // Vec<Json>`, or `doc.get()` where `doc: JsonValue` bound from
                        // `Result__JsonValue.Ok`); without this, resolution falls back to
                        // field access (`a.len`). A type-parameter payload (`Ok(T)`) is
                        // resolved to the mangled subject's concrete arg.
                        if (payload) |pl| {
                            if (i < pl.count) {
                                if (self.resolve_fit_payload_dtype(enum_name, pl.items()[i])) |bdt| {
                                    try self.bind_loop_var(bname.items, bdt);
                                }
                            }
                        }
                    }
                }

                try self.write_indent();
                try self.transpile_node(branch.body.*);
                if (self.node_needs_trailing_semicolon(branch.body.*)) try self.write(";");
                self.finish_scope();
                self.dedent();
                try self.write_indent();
                try self.write("}");
            } else {
                // A catch-all arm. Without any prior arm it is an unconditional block;
                // otherwise it is the chain's trailing `else`.
                try self.write_indent();
                if (first) {
                    try self.write("{");
                } else {
                    try self.write("else {");
                }
                first = false;
                self.indent();
                try self.write_indent();
                try self.transpile_node(branch.body.*);
                if (self.node_needs_trailing_semicolon(branch.body.*)) try self.write(";");
                self.dedent();
                try self.write_indent();
                try self.write("}");
            }
        }

        self.dedent();
        try self.write_indent();
        try self.write("}");
    }

    /// Extract the variant name from a fit-arm variant path: `Enum.Variant` or the
    /// shorthand `.Variant` (blank LHS). Returns null if it isn't a `.`-path.
    fn fit_variant_name_of(self: *Self, condition: ast.Node) ?[]const u8 {
        _ = self;
        if (condition.type != .Expression or condition.node_variant == null) return null;
        const cexp = condition.node_variant.?.exp;
        if (!mem.eql(u8, cexp.op, ".")) return null;
        const right = cexp.right orelse return null;
        if (right.*.type != .Identifier or right.*.data == null) return null;
        return right.*.data.?.sval.items;
    }

    /// Flattens a `fit` branch condition into its individual labels. A comma
    /// condition (`1, 2 ->`) is a `,`-operator Expression tree; this collects each
    /// leaf label (`1`, `2`). A single-label condition yields one entry.
    fn collect_fit_labels(self: *Self, condition: *ast.Node, out: *ArrayList(*ast.Node)) TranspileError!void {
        if (condition.type == .Expression and condition.node_variant != null and
            mem.eql(u8, condition.node_variant.?.exp.op, ","))
        {
            const exp = condition.node_variant.?.exp;
            if (exp.left) |l| try self.collect_fit_labels(l, out);
            if (exp.right) |r| try self.collect_fit_labels(r, out);
            return;
        }
        out.append(condition) catch return TranspileError.MemoryAllocationFailed;
    }

    /// A structural key for a `fit` case label, used to dedup duplicate labels
    /// (e.g. two `Color.Green` arms) which would otherwise emit duplicate C `case`
    /// labels (a compile error). Caller owns the returned slice.
    fn fit_label_key(self: *Self, label: ast.Node) TranspileError![]const u8 {
        switch (label.type) {
            .Number => {
                // Number/char literals are a tagged union; read the active field.
                if (label.data) |d| {
                    switch (d) {
                        .llnum => |v| return std.fmt.allocPrint(self.allocator, "n:{d}", .{v}) catch return TranspileError.MemoryAllocationFailed,
                        .lnum => |v| return std.fmt.allocPrint(self.allocator, "n:{d}", .{v}) catch return TranspileError.MemoryAllocationFailed,
                        .inum => |v| return std.fmt.allocPrint(self.allocator, "n:{d}", .{v}) catch return TranspileError.MemoryAllocationFailed,
                        .cval => |v| return std.fmt.allocPrint(self.allocator, "c:{d}", .{v}) catch return TranspileError.MemoryAllocationFailed,
                        else => {},
                    }
                }
            },
            // A char literal (`'+'`) is its OWN node type (.Character), not
            // .Number — it was falling through to the unrecognized-node
            // fallback below, which keys off `@intFromPtr(&label)` (the
            // address of this function's BY-VALUE parameter). That address
            // is frequently reused across separate calls to this function
            // from the same call site (e.g. every branch label in a `fit`
            // over `chr`), so every char-literal branch after the first
            // collided as a "duplicate" and got silently dropped from the
            // emitted C switch — matching the observed "only the first
            // branch of `fit` on a chr subject ever matches" bug.
            .Character => {
                if (label.data) |d| {
                    switch (d) {
                        .cval => |v| return std.fmt.allocPrint(self.allocator, "c:{d}", .{v}) catch return TranspileError.MemoryAllocationFailed,
                        else => {},
                    }
                }
            },
            .Identifier => {
                if (label.data) |d| {
                    return std.fmt.allocPrint(self.allocator, "i:{s}", .{d.sval.items}) catch return TranspileError.MemoryAllocationFailed;
                }
            },
            .Expression => {
                // Enum dot-access `Enum.Variant` or shorthand `.Variant`.
                if (label.node_variant) |nv| {
                    if (mem.eql(u8, nv.exp.op, ".")) {
                        var buf = ArrayList(u8).init(self.allocator);
                        defer buf.deinit();
                        buf.appendSlice("e:") catch return TranspileError.MemoryAllocationFailed;
                        if (nv.exp.left) |l| {
                            if (l.type == .Identifier and l.data != null) {
                                buf.appendSlice(l.data.?.sval.items) catch return TranspileError.MemoryAllocationFailed;
                            }
                        }
                        buf.append('.') catch return TranspileError.MemoryAllocationFailed;
                        if (nv.exp.right) |r| {
                            if (r.type == .Identifier and r.data != null) {
                                buf.appendSlice(r.data.?.sval.items) catch return TranspileError.MemoryAllocationFailed;
                            }
                        }
                        return buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
                    }
                }
            },
            else => {},
        }
        // Fall back to a per-node-identity key so unrecognized labels never collide
        // (no false dedup). Identity via the node's address.
        return std.fmt.allocPrint(self.allocator, "p:{x}", .{@intFromPtr(&label)}) catch return TranspileError.MemoryAllocationFailed;
    }

    /// If `node` is a free-function call `f(...)` whose declared return type is a
    /// quirk (e.g. `fun make(...) Weighable`), return that quirk's type name;
    /// otherwise null. Used to dispatch a quirk method directly on a call result
    /// (`make(&s).weight()`), which has no name in scope to look up.
    fn expr_call_return_quirk_name(self: *Self, node: ast.Node) ?[]const u8 {
        if (node.type == .ExpressionParenthesis) {
            if (node.node_variant == null) return null;
            return self.expr_call_return_quirk_name(node.node_variant.?.paren.exp.*);
        }
        if (node.type != .Expression or node.node_variant == null) return null;
        const exp = node.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, "()")) return null;
        const callee = exp.left orelse return null;
        // Resolve the callee name: a bare identifier or a `mod.fn` member access.
        var fname: ?[]const u8 = null;
        if (callee.type == .Identifier and callee.data != null) {
            fname = callee.data.?.sval.items;
        } else if (callee.type == .Expression and callee.node_variant != null and
            mem.eql(u8, callee.node_variant.?.exp.op, "."))
        {
            const dot = callee.node_variant.?.exp;
            if (dot.right) |rhs| {
                if (rhs.type == .Identifier and rhs.data != null) fname = rhs.data.?.sval.items;
            }
        }
        const name = fname orelse return null;

        // A quirk-method call `recv.m(...)` where `recv` is quirk-typed: the result
        // type is that quirk method's declared return type. Handles chaining a method
        // on a quirk-returning quirk method, e.g. `qa.to_b().gv()`.
        if (callee.type == .Expression and callee.node_variant != null and
            mem.eql(u8, callee.node_variant.?.exp.op, "."))
        {
            const dot = callee.node_variant.?.exp;
            if (dot.left) |recv| {
                // Receiver quirk type: from scope (identifier/field) OR, for a deeper
                // chain like `qa.to_b().to_c()`, recursively from the receiver call's
                // own return-quirk type. This makes 3+ level quirk chains resolve.
                var recv_q: ?[]const u8 = self.expr_named_type_from_scope(recv.*);
                if (recv_q == null or !self.is_quirk_name(recv_q.?)) {
                    recv_q = self.expr_call_return_quirk_name(recv.*);
                }
                if (recv_q) |rq| {
                    if (self.is_quirk_name(rq)) {
                        if (self.quirk_method_return_quirk_name(rq, name)) |ret_q| return ret_q;
                    }
                }
            }
        }

        var fnode = self.find_function_node(name);
        if (fnode == null) {
            const base = if (std.mem.lastIndexOf(u8, name, "__")) |sep| name[sep + 2 ..] else name;
            if (!mem.eql(u8, base, name)) fnode = self.find_function_node(base);
        }
        const fn_node = fnode orelse return null;
        if (fn_node.node_variant == null) return null;
        const rt = fn_node.node_variant.?.function.rtype orelse return null;
        if (rt.type != .Unknown or rt.pointer_depth != 0) return null;
        if (!self.is_quirk_name(rt.type_str.items)) return null;
        return rt.type_str.items;
    }

    /// Returns the quirk type name a quirk method returns, if that return type is
    /// itself a quirk (e.g. quirk `QA { to_b() QB; }` -> `to_b` returns `QB`).
    /// Null otherwise. Used to chain a method on a quirk-method result.
    fn quirk_method_return_quirk_name(self: *Self, quirk_name: []const u8, method_name: []const u8) ?[]const u8 {
        const reg = self.root_registry() orelse return null;
        const sig = reg.quirk_sig_by_name.get(quirk_name) orelse return null;
        const qnode = reg.quirks_by_sig.get(sig) orelse return null;
        if (qnode.node_variant == null) return null;
        for (qnode.node_variant.?.quirk.methods.items()) |m| {
            if (!mem.eql(u8, m.name.items, method_name)) continue;
            const rt = m.rtype;
            if (rt.type != .Unknown or rt.pointer_depth != 0) return null;
            if (!self.is_quirk_name(rt.type_str.items)) return null;
            return rt.type_str.items;
        }
        return null;
    }

    /// Resolves the by-value COMPOUND type a call expression yields, for chaining a
    /// method on a call result (`b.add(2).get()`, `makeBox(7).get()`). Returns the
    /// compound type name (e.g. `B`) when `node` is:
    ///   - a free-function call `f(...)` whose return type is a compound, or
    ///   - a plain-impl method call `recv.m(...)` whose method returns a compound.
    /// Returns null for anything else (pointers, primitives, quirks, unresolved).
    /// The receiver of such a chain is an rvalue, so callers must materialize it
    /// into a temp (you can't take the address of a C rvalue).
    fn expr_compound_return_type_name(self: *Self, node: ast.Node) ?[]const u8 {
        if (node.type == .ExpressionParenthesis) {
            if (node.node_variant == null) return null;
            return self.expr_compound_return_type_name(node.node_variant.?.paren.exp.*);
        }
        if (node.type != .Expression or node.node_variant == null) return null;
        const exp = node.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, "()")) return null;
        const callee = exp.left orelse return null;

        if (callee.type == .Identifier and callee.data != null) {
            // Free-function call: use the callee's declared return type.
            const name = callee.data.?.sval.items;
            var fnode = self.find_function_node(name);
            if (fnode == null) {
                const base = if (std.mem.lastIndexOf(u8, name, "__")) |sep| name[sep + 2 ..] else name;
                if (!mem.eql(u8, base, name)) fnode = self.find_function_node(base);
            }
            const fn_node = fnode orelse return null;
            if (fn_node.node_variant == null) return null;
            const fnv = fn_node.node_variant.?.function;
            const rt = fnv.rtype orelse return null;
            if (rt.pointer_depth != 0) return null;
            // Generic function: the return type (e.g. `Option<T>`) must be
            // MONOMORPHIZED for this call (`some(7)` -> `Option__num`). Recover the
            // call's instantiation (matched via the registered call override) and
            // substitute the type args into the return type.
            if (fnv.type_params != null) {
                if (self.lookup_generic_call_override(node)) |spec_name| {
                    const root = self.get_root();
                    for (root.generic_fn_instantiations.items) |inst| {
                        if (!mem.eql(u8, inst.name, spec_name)) continue;
                        const mangled = self.type_name_mangled_with_subst(&rt, inst.params.*, inst.args) catch return null;
                        // The result is an owned, mangled type name like `Option__num`.
                        // Keep it when it names a compound OR a (data) enum (so a chain
                        // like `some(7).unwrap_or(0)` materializes the rvalue receiver).
                        const base = if (mem.indexOf(u8, mangled, "__")) |bi| mangled[0..bi] else mangled;
                        const reg = root.type_registry;
                        if (reg != null and (reg.?.compounds_by_name.contains(base) or reg.?.enums_by_name.contains(base))) {
                            // NOTE: caller treats the returned slice as borrowed; we leak
                            // this small allocation into the arena (freed at process end).
                            return mangled;
                        }
                        self.allocator.free(@constCast(mangled));
                        return null;
                    }
                }
                return null;
            }
            if (rt.type != .Unknown) return null;
            // A non-generic function returning a GENERIC-INSTANCE compound
            // (`fun make(num) Option<num>`) must yield the MONOMORPHIZED name
            // `Option__num`, not the base `Option`, so the chained method resolves.
            if (rt.generic_args != null) {
                const mangled = self.type_name_mangled(&rt) catch return null;
                const base = if (mem.indexOf(u8, mangled, "__")) |bi| mangled[0..bi] else mangled;
                const reg = self.get_root().type_registry;
                if (reg != null and (reg.?.compounds_by_name.contains(base) or reg.?.enums_by_name.contains(base))) return mangled; // arena-owned
                self.allocator.free(@constCast(mangled));
                return null;
            }
            if (self.is_compound_named(rt.type_str.items)) return rt.type_str.items;
            // A non-generic data enum returned by value also supports method chaining.
            if (self.enum_name_is_tagged_union(rt.type_str.items)) return rt.type_str.items;
            return null;
        }

        if (callee.type == .Expression and callee.node_variant != null and
            mem.eql(u8, callee.node_variant.?.exp.op, "."))
        {
            // Method call `recv.m(...)`: resolve recv's compound type, then the
            // plain-impl method's return type.
            const dot = callee.node_variant.?.exp;
            const recv = dot.left orelse return null;
            const member = dot.right orelse return null;
            if (member.type != .Identifier or member.data == null) return null;
            const recv_type = self.expr_resolved_compound_type_name(recv.*) orelse return null;
            const recv_canon = self.canonical_compound_name(recv_type);
            const base = if (mem.indexOf(u8, recv_canon, "__")) |idx| recv_canon[0..idx] else recv_canon;
            // Match plain- AND quirk-impl methods: a quirk method like `Iterator.next`
            // is dispatched statically on a concrete receiver and has a real return
            // type to monomorphize (so `it.next()` resolves to `Option__num`).
            const hit = self.find_any_impl_method_node(base, member.data.?.sval.items) orelse return null;
            if (hit.method_node.node_variant == null) return null;
            const rt = hit.method_node.node_variant.?.function.rtype orelse return null;
            if (rt.pointer_depth != 0) return null;

            // A method with its OWN type param (`pub wrap<U>(U x) Box<U>`) needs
            // its return type substituted through the COMBINED impl+method
            // params/args for THIS specific call (recovered via the registered
            // call-site override), not just the impl's own -- mirroring the
            // free-function generic case above. Otherwise e.g. `Box<U>` would
            // substitute nothing (U isn't one of the impl's own params) and
            // leak the literal, un-mangled placeholder name `Box__U`.
            if (hit.method_node.node_variant.?.function.type_params != null) {
                if (self.lookup_generic_call_override(node)) |spec_name| {
                    const root = self.get_root();
                    for (root.generic_fn_instantiations.items) |inst| {
                        if (!mem.eql(u8, inst.name, spec_name)) continue;
                        const mangled = self.type_name_mangled_with_subst(&rt, inst.params.*, inst.args) catch return null;
                        const mbase = if (mem.indexOf(u8, mangled, "__")) |bi| mangled[0..bi] else mangled;
                        const reg = root.type_registry;
                        if (reg != null and (reg.?.compounds_by_name.contains(mbase) or reg.?.enums_by_name.contains(mbase))) {
                            return mangled; // arena-owned
                        }
                        self.allocator.free(@constCast(mangled));
                        return null;
                    }
                }
                return null;
            }

            // If the receiver is a GENERIC instance and the method's return type
            // mentions the type params (e.g. `with(T) Box<T>` on a `Box<num>`, or
            // `values() Vec<V>` on a `Map<num,num>`), MONOMORPHIZE the return type
            // using the receiver's type args -> `Box__num` / `Vec__num`. Otherwise
            // the chained method would resolve against the un-monomorphized base.
            if (self.impl_type_params(hit.impl_node)) |params| {
                if ((self.dtype_from_mangled_type(recv_canon) catch null)) |recv_dt| {
                    if (recv_dt.generic_args) |gargs_vec| {
                        const gargs = gargs_vec.items();
                        if (gargs.len == params.count) {
                            const mangled = self.type_name_mangled_with_subst(&rt, params.*, gargs) catch return null;
                            const mbase = if (mem.indexOf(u8, mangled, "__")) |bi| mangled[0..bi] else mangled;
                            const reg = self.get_root().type_registry;
                            // Accept a compound OR a (data) enum instance, so a method
                            // returning `Option<T>`/`Result<T>` supports chaining
                            // (`box.at().unwrap_or(0)`).
                            if (reg != null and (reg.?.compounds_by_name.contains(mbase) or reg.?.enums_by_name.contains(mbase))) return mangled; // arena-owned
                            self.allocator.free(@constCast(mangled));
                        }
                    }
                }
            }

            // A method on a NON-generic type whose return type is a GENERIC INSTANCE
            // (`JsonParser.parse_string() Result<str>`) must yield the MONOMORPHIZED name
            // `Result__str` so a `fit` over the call switches on the right tag.
            if (rt.generic_args != null) {
                const mangled = self.type_name_mangled(&rt) catch return null;
                const mbase = if (mem.indexOf(u8, mangled, "__")) |bi| mangled[0..bi] else mangled;
                const reg = self.get_root().type_registry;
                if (reg != null and (reg.?.compounds_by_name.contains(mbase) or reg.?.enums_by_name.contains(mbase))) return mangled; // arena-owned
                self.allocator.free(@constCast(mangled));
                return null;
            }
            if (rt.type != .Unknown) return null;
            if (self.is_compound_named(rt.type_str.items)) return rt.type_str.items;
            // A non-generic data enum return (`fun f() Option<num>`... but here a
            // method returning a plain data enum) also supports chaining.
            if (self.enum_name_is_tagged_union(rt.type_str.items)) return rt.type_str.items;
            return null;
        }
        return null;
    }

    /// Resolves the compound type name of an expression that may be a named value
    /// in scope OR a call result, by combining `expr_named_type_from_scope` (locals,
    /// field access) with `expr_compound_return_type_name` (call/method-call
    /// results). Enables chained method calls of arbitrary depth.
    fn expr_resolved_compound_type_name(self: *Self, node: ast.Node) ?[]const u8 {
        // For a generic-instance variable (`Box<num> b`), prefer the MANGLED name
        // (`Box__num`) so a chained method's generic return type can be monomorphized
        // against the receiver's type args. `expr_named_type_from_scope` returns the
        // bare base name, which loses the args.
        if (node.type == .Identifier and node.data != null) {
            if (self.identifier_declared_dtype(node.data.?.sval.items)) |dt| {
                if (dt.type == .Unknown and dt.pointer_depth <= 1 and dt.generic_args != null) {
                    if (self.type_name_mangled_for_emit(dt) catch null) |mangled| {
                        return mangled; // arena-owned
                    }
                }
            }
        }
        // Same for a FIELD holding a generic instance (`Holder.entries:
        // Map<str, num>`): the field lookup below yields the bare base name
        // (`Map`), which loses the args a chained method's return type must be
        // monomorphized against -- leaving the placeholder (`Option__V`) in the
        // materialized-receiver temp of `h.entries.at(k).is_some()`.
        if (node.type == .Expression and node.node_variant != null and
            mem.eql(u8, node.node_variant.?.exp.op, "."))
        {
            const dot = node.node_variant.?.exp;
            if (dot.left) |left| {
                if (dot.right) |right| {
                    if (right.type == .Identifier and right.data != null) {
                        if (self.expr_named_type_from_scope(left.*)) |left_name| {
                            const canon = self.canonical_compound_name(left_name);
                            if (self.lookup_compound_field(canon, right.data.?.sval.items)) |fdt| {
                                if (fdt.type == .Unknown and fdt.pointer_depth <= 1 and fdt.generic_args != null) {
                                    if (self.type_name_mangled_for_emit(fdt) catch null) |mangled| {
                                        return mangled; // arena-owned
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        if (self.expr_named_type_from_scope(node)) |n| {
            // Accept a compound OR a data enum: a method receiver can be an enum value
            // (`v.as_num()` where `v: JsonValue`), not just a compound.
            if (self.is_compound_named(n) or self.enum_name_is_tagged_union(n)) return n;
        }
        return self.expr_compound_return_type_name(node);
    }

    fn is_compound_named(self: *Self, name: []const u8) bool {
        const reg = self.root_registry() orelse return false;
        const canon = self.canonical_compound_name(name);
        const base = if (mem.indexOf(u8, canon, "__")) |idx| canon[0..idx] else canon;
        return reg.compounds_by_name.contains(canon) or reg.compounds_by_name.contains(base);
    }

    fn same_module(ref_node: ?*const ast.Node, def_node: *const ast.Node) bool {
        if (ref_node == null) return true;
        const ref_pos = ref_node.?.pos orelse return true;
        const def_pos = def_node.pos orelse return true;
        return mem.eql(u8, ref_pos.filename, def_pos.filename);
    }

    fn can_access(self: *Self, ref_node: ?*const ast.Node, def_node: *const ast.Node) bool {
        _ = self;
        return node_is_public(def_node) or same_module(ref_node, def_node);
    }

    fn method_is_public(self: *Self, impl_node: *const ast.Node, method_node: *const ast.Node) bool {
        _ = self;
        return node_is_public(method_node) or node_is_public(impl_node);
    }

    fn can_access_method(self: *Self, ref_node: ?*const ast.Node, impl_node: *const ast.Node, method_node: *const ast.Node) bool {
        return self.method_is_public(impl_node, method_node) or same_module(ref_node, method_node);
    }

    fn same_node_file(self: *Self, a: *const ast.Node, b: *const ast.Node) bool {
        _ = self;
        const apos = a.pos orelse return false;
        const bpos = b.pos orelse return false;
        return mem.eql(u8, apos.filename, bpos.filename);
    }

    fn is_std_c_signature_node(self: *Self, node: *const ast.Node) bool {
        _ = self;
        const pos = node.pos orelse return false;
        if (std.mem.indexOf(u8, pos.filename, "/std/c/") != null) return true;
        if (std.mem.indexOf(u8, pos.filename, "\\std\\c\\") != null) return true;
        return false;
    }

    fn expr_pointer_depth_from_scope(self: *Self, node: ast.Node) usize {
        switch (node.type) {
            .Identifier => {
                if (node.data == null) return 0;
                const name = node.data.?.sval.items;
                const ent = self.get_scope_entity(name) orelse return 0;
                const ent_node = ent.node orelse return 0;
                if (ent_node.type != .Variable or ent_node.node_variant == null) return 0;
                return ent_node.node_variant.?.variable.type.pointer_depth;
            },
            .ExpressionParenthesis => {
                if (node.node_variant == null) return 0;
                return self.expr_pointer_depth_from_scope(node.node_variant.?.paren.exp.*);
            },
            .Unary => {
                const u = node.node_variant.?.unary;
                const base = self.expr_pointer_depth_from_scope(u.operand.*);
                if (u.indirection) |ind| {
                    if (base < ind.depth) return 0;
                    return base - ind.depth;
                }
                if (mem.eql(u8, u.op, "&")) return base + 1;
                return base;
            },
            .Expression => {
                if (node.node_variant == null) return 0;
                const exp = node.node_variant.?.exp;
                // A method-call RESULT used as the base of a further `.` access
                // (`vec.get(i).field` where `get` returns `T*`, e.g. any
                // `Vec<T*>.get`): resolve the callee method's declared return
                // pointer depth so the outer field access picks `->` correctly.
                // Only handles a plain `recv.method(...)` callee shape (not a
                // bare function call or a further-chained call), matching the
                // narrowest case actually needed today; anything else falls
                // through to the `.`-op case below (or returns 0).
                if (mem.eql(u8, exp.op, "()")) {
                    const callee = exp.left orelse return 0;
                    if (callee.type != .Expression or callee.node_variant == null or !mem.eql(u8, callee.node_variant.?.exp.op, ".")) return 0;
                    const dot = callee.node_variant.?.exp;
                    const recv = dot.left orelse return 0;
                    const member = dot.right orelse return 0;
                    if (member.type != .Identifier or member.data == null) return 0;
                    const recv_type = self.expr_resolved_compound_type_name(recv.*) orelse return 0;
                    const recv_canon = self.canonical_compound_name(recv_type);
                    const base = if (mem.indexOf(u8, recv_canon, "__")) |idx| recv_canon[0..idx] else recv_canon;
                    const hit = self.find_any_impl_method_node(base, member.data.?.sval.items) orelse return 0;
                    if (hit.method_node.node_variant == null) return 0;
                    const rt = hit.method_node.node_variant.?.function.rtype orelse return 0;

                    // The method's return type may be (or embed) the impl's own
                    // type param written bare (`pub get(num i) T` on `impl Vec<T>`):
                    // its REAL pointer depth on a concrete receiver (`Vec<DataType*>`)
                    // is the template's own depth plus whatever depth the matching
                    // generic arg itself carries (e.g. `T` at depth 0 substituted
                    // with `DataType*` at depth 1 -> depth 1 overall).
                    if (self.impl_type_params(hit.impl_node)) |params| {
                        if ((self.dtype_from_mangled_type(recv_canon) catch null)) |recv_dt| {
                            if (recv_dt.generic_args) |gargs_vec| {
                                const gargs = gargs_vec.items();
                                if (gargs.len == params.count) {
                                    for (params.items(), 0..) |p, i| {
                                        if (mem.eql(u8, p.items, rt.type_str.items)) {
                                            return rt.pointer_depth + gargs[i].pointer_depth;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    return rt.pointer_depth;
                }
                // Indexing `arr[i]`. The element's pointer depth depends on whether
                // the base is a true array or a pointer used as an array:
                //   - `T*[]` (is_array, pointer_depth=1): the `[]` consumes the array
                //     dimension; each element is a `T*` -> element depth = pointer_depth.
                //     (So `arr[0]->id` correctly uses `->`.)
                //   - `T*` used as an array (pointer_depth=1, NOT is_array, e.g. a
                //     malloc'd buffer): the `[]` consumes one pointer level; the
                //     element is a `T` value -> element depth = pointer_depth - 1.
                //     (So `pts[0].x` correctly uses `.`.)
                if (mem.eql(u8, exp.op, "[]")) {
                    const arr_left = exp.left orelse return 0;
                    if (arr_left.type == .Identifier and arr_left.data != null) {
                        const dt = self.identifier_declared_dtype(arr_left.data.?.sval.items) orelse return 0;
                        const is_arr = dt.flags != null and dt.flags.?.is_array;
                        if (is_arr) return dt.pointer_depth;
                        return if (dt.pointer_depth > 0) dt.pointer_depth - 1 else 0;
                    }
                    return 0;
                }
                if (!mem.eql(u8, exp.op, ".")) return 0;
                const left = exp.left orelse return 0;
                const right = exp.right orelse return 0;
                if (right.type != .Identifier or right.data == null) return 0;

                // Determine the named (compound) type of the left expression.
                const lt_name: []const u8 = blk: {
                    if (left.type == .Identifier and left.data != null) {
                        const dt = self.identifier_declared_dtype(left.data.?.sval.items) orelse break :blk "";
                        if (dt.type != .Unknown) break :blk "";
                        break :blk dt.type_str.items;
                    }

                    if (left.type == .Expression and left.node_variant != null and mem.eql(u8, left.node_variant.?.exp.op, ".")) {
                        // For chained field access, we only support resolving compound types.
                        // If we can't resolve, fall back to '.' (pointer depth 0).
                        // NOTE: pointer depth of the left doesn't matter for field type lookup here.
                        var cur: ast.Node = left.*;
                        var base_name: []const u8 = "";

                        // Walk to the left-most identifier to find the base variable's declared type.
                        while (cur.type == .Expression and cur.node_variant != null and mem.eql(u8, cur.node_variant.?.exp.op, ".")) {
                            const cur_left = cur.node_variant.?.exp.left orelse break;
                            cur = cur_left.*;
                        }
                        if (cur.type == .Identifier and cur.data != null) {
                            const dt0 = self.identifier_declared_dtype(cur.data.?.sval.items) orelse break :blk "";
                            if (dt0.type != .Unknown) break :blk "";
                            base_name = dt0.type_str.items;
                        } else {
                            break :blk "";
                        }

                        // Now replay the chain from the original left expression to compute the final named type.
                        // We only care about the named type (base Unknown + name).
                        var t: CheckedType = .{ .base = .Unknown, .name = base_name, .pointer_depth = 0 };
                        cur = left.*;
                        while (cur.type == .Expression and cur.node_variant != null and mem.eql(u8, cur.node_variant.?.exp.op, ".")) {
                            const dot = cur.node_variant.?.exp;
                            const seg = dot.right orelse break;
                            if (seg.type != .Identifier or seg.data == null) break;
                            const fdt = self.lookup_compound_field(t.name.?, seg.data.?.sval.items) orelse break;
                            t = type_from_dtype(fdt);
                            const nl = dot.left orelse break;
                            cur = nl.*;
                        }
                        if (t.base != .Unknown or t.name == null) break :blk "";
                        break :blk t.name.?;
                    }

                    break :blk "";
                };
                if (lt_name.len == 0) return 0;

                const fdt = self.lookup_compound_field(lt_name, right.data.?.sval.items) orelse return 0;
                return fdt.pointer_depth;
            },
            else => return 0,
        }
    }

    fn expr_named_pointee_from_scope(self: *Self, node: ast.Node) ?[]const u8 {
        // Returns the named type `T` if the expression evaluates to a `T*` (a
        // concrete pointer coercible to a quirk). Delegates to the dtype variant so
        // all recognized RHS shapes (identifier, `&lvalue`, `&arr[i]`, `*pp`, `(&p)`,
        // `s.ptrfield`) stay in one place.
        const dt = self.expr_named_pointee_dtype_from_scope(node) orelse return null;
        if (dt.type != .Unknown) return null;
        return dt.type_str.items;
    }

    /// Detects the `&arr[i]` shape (parsed as `[] (& arr) i`) and returns the
    /// array's element dtype (a named/compound type). Null for any other shape.
    fn amp_index_pointee_dtype(self: *Self, node: ast.Node) ?*const dtype.DataType {
        if (node.type != .Expression or node.node_variant == null) return null;
        const exp = node.node_variant.?.exp;
        if (!mem.eql(u8, exp.op, "[]")) return null;
        const left = exp.left orelse return null;
        if (left.type != .Unary or left.node_variant == null) return null;
        const u = left.node_variant.?.unary;
        if (!mem.eql(u8, u.op, "&")) return null;
        // The element type of the addressed array.
        return self.addressed_lvalue_dtype(u.operand.*);
    }

    /// Named (compound/enum) type of an addressable lvalue used as the operand of
    /// `&` — supports a bare identifier (`x`), a field access (`s.field`,
    /// `o.inner.field`), and an array element (`arr[i]`). Returns null for
    /// non-named or unresolvable operands. Used so quirk coercion (`Quirk q =
    /// &arr[i]` / `&s.field`) works on more than bare identifiers.
    fn addressed_lvalue_type_name(self: *Self, op: ast.Node) ?[]const u8 {
        const dt = self.addressed_lvalue_dtype(op) orelse return null;
        if (dt.type != .Unknown) return null;
        return dt.type_str.items;
    }

    /// Full dtype of an addressable lvalue (see `addressed_lvalue_type_name`).
    fn addressed_lvalue_dtype(self: *Self, op: ast.Node) ?*const dtype.DataType {
        switch (op.type) {
            .Identifier => {
                if (op.data == null) return null;
                const ent = self.get_scope_entity(op.data.?.sval.items) orelse return null;
                const ent_node = ent.node orelse return null;
                if (ent_node.type != .Variable or ent_node.node_variant == null) return null;
                return ent_node.node_variant.?.variable.type;
            },
            .ExpressionParenthesis => {
                if (op.node_variant == null) return null;
                return self.addressed_lvalue_dtype(op.node_variant.?.paren.exp.*);
            },
            .Expression => {
                if (op.node_variant == null) return null;
                const exp = op.node_variant.?.exp;
                if (mem.eql(u8, exp.op, ".")) {
                    // `recv.field`: resolve recv's compound type, then the field's dtype.
                    const left = exp.left orelse return null;
                    const right = exp.right orelse return null;
                    if (right.type != .Identifier or right.data == null) return null;
                    const recv_type = self.expr_named_type_from_scope(left.*) orelse return null;
                    const recv_canon = self.canonical_compound_name(recv_type);
                    return self.lookup_compound_field(recv_canon, right.data.?.sval.items);
                }
                if (mem.eql(u8, exp.op, "[]")) {
                    // `arr[i]`: element type is the array variable's declared element
                    // type (drop the array-ness, keep the named type).
                    const arr_left = exp.left orelse return null;
                    return self.addressed_lvalue_dtype(arr_left.*);
                }
                return null;
            },
            else => return null,
        }
    }

    /// Like `expr_named_pointee_from_scope`, but returns the full pointee dtype
    /// (so callers can mangle a generic instantiation, e.g. `Box<num>` ->
    /// `Box__num`). Used to emit the correct `__fun_coerce_<mangled>_<hash>`
    /// helper name, which is DEFINED using the mangled concrete type name.
    fn expr_named_pointee_dtype_from_scope(self: *Self, node: ast.Node) ?*dtype.DataType {
        switch (node.type) {
            .Identifier => {
                if (node.data == null) return null;
                const ent = self.get_scope_entity(node.data.?.sval.items) orelse return null;
                const ent_node = ent.node orelse return null;
                if (ent_node.type != .Variable or ent_node.node_variant == null) return null;
                const dt = ent_node.node_variant.?.variable.type;
                if (dt.pointer_depth != 1 or dt.type != .Unknown) return null;
                return dt;
            },
            .ExpressionParenthesis => {
                // `(&p)` / `(*pp)`: unwrap the grouping and recurse.
                if (node.node_variant == null) return null;
                return self.expr_named_pointee_dtype_from_scope(node.node_variant.?.paren.exp.*);
            },
            .Unary => {
                const u = node.node_variant.?.unary;
                if (mem.eql(u8, u.op, "&")) {
                    // &lvalue: pointee dtype of `x` or `s.field`.
                    const dt = self.addressed_lvalue_dtype(u.operand.*) orelse return null;
                    if (dt.type != .Unknown) return null;
                    return @constCast(dt);
                }
                // Dereference `*operand`: if `operand` is a `T**` (depth 2), the
                // result `*operand` is a `T*` whose pointee is the compound `T`.
                // `u.indirection.depth` levels of `*` are applied.
                if (u.indirection) |ind| {
                    const od = self.expr_underlying_dtype(u.operand.*) orelse return null;
                    if (od.type != .Unknown) return null;
                    // After `ind.depth` derefs the remaining pointer depth must be 1
                    // (so the value is a `T*` coercible to a quirk).
                    if (od.pointer_depth < ind.depth) return null;
                    if (od.pointer_depth - ind.depth != 1) return null;
                    return @constCast(od);
                }
                return null;
            },
            .Expression => {
                if (node.node_variant) |nv| {
                    // `o.inner` where field `inner` is a `T*` pointer-field.
                    if (mem.eql(u8, nv.exp.op, ".")) {
                        const left = nv.exp.left orelse return null;
                        const right = nv.exp.right orelse return null;
                        if (right.type == .Identifier and right.data != null) {
                            if (self.expr_named_type_from_scope(left.*)) |recv_t| {
                                const recv_canon = self.canonical_compound_name(recv_t);
                                if (self.lookup_compound_field(recv_canon, right.data.?.sval.items)) |fdt| {
                                    if (fdt.pointer_depth == 1 and fdt.type == .Unknown) return @constCast(fdt);
                                }
                            }
                        }
                    }
                }
                // `&items[0]` (parsed as `[] (& items) i`): the element dtype.
                const dt = self.amp_index_pointee_dtype(node) orelse return null;
                if (dt.type != .Unknown) return null;
                return @constCast(dt);
            },
            else => return null,
        }
    }

    /// The full declared dtype of an in-scope value expression (identifier or a
    /// chain of derefs/parens over one), WITHOUT requiring pointer_depth==1. Used to
    /// resolve `*pp` where `pp` is a `T**`.
    fn expr_underlying_dtype(self: *Self, node: ast.Node) ?*const dtype.DataType {
        switch (node.type) {
            .Identifier => {
                if (node.data == null) return null;
                return self.identifier_declared_dtype(node.data.?.sval.items);
            },
            .ExpressionParenthesis => {
                if (node.node_variant == null) return null;
                return self.expr_underlying_dtype(node.node_variant.?.paren.exp.*);
            },
            else => return null,
        }
    }

    /// Returns the C identifier used in `__fun_coerce_<NAME>_<hash>` for a
    /// concrete (possibly generic) type, matching how the helper is DEFINED:
    /// the mangled instantiation name for generics (`Box__num`), the sanitized
    /// base name otherwise (`Dog`). The returned slice is owned by
    /// `self.allocator`; the caller must free it.
    fn coerce_type_ident_for(self: *Self, base_name: []const u8, pointee_dt: ?*dtype.DataType) TranspileError![]const u8 {
        if (pointee_dt) |dt| {
            if (dt.generic_args != null) {
                // `type_name_mangled_for_emit` already returns self.allocator memory.
                return try self.type_name_mangled_for_emit(dt);
            }
        }
        // Sanitize the base name the same way the definition site does, into a
        // freshly self.allocator-owned slice.
        var buf: [128]u8 = undefined;
        const s = try self.c_ident_sanitize_temp(base_name, &buf);
        defer if (s.owned) self.backing_allocator.free(s.slice);
        return self.allocator.dupe(u8, s.slice) catch return TranspileError.MemoryAllocationFailed;
    }

    /// Does the pointee of `node` (a `T*` expression like `&x` or a `T*` variable)
    /// implement the quirk identified by `sig`? Returns the C identifier to use in
    /// `__fun_coerce_<NAME>_<hash>` — ALWAYS the mangled instantiation name for a
    /// generic pointee (`Box__num`), matching how the helper is DEFINED — or null
    /// when no impl applies. The returned slice is owned by `self.allocator`; the
    /// caller must free it.
    ///
    /// Impl presence is checked under BOTH names because an impl registers under:
    ///   - the mangled name (`Box__num`) for a concrete `impl Box<num> as Q`, and
    ///   - the base name (`Box`) for a parametric `impl Box<T> as Q` (one impl
    ///     covering every instantiation).
    /// Either match means the pointee implements the quirk; the emitted helper name
    /// is the mangled one regardless, since the coerce helper is emitted per
    /// concrete instantiation.
    fn pointee_quirk_impl_name(self: *Self, node: ast.Node, sig: []const u8) TranspileError!?[]const u8 {
        const reg = self.root_registry() orelse return null;
        const base = self.expr_named_pointee_from_scope(node) orelse return null;
        const pointee_dt = self.expr_named_pointee_dtype_from_scope(node);
        // The emit identifier: `Box__num` for a generic instantiation, sanitized
        // base name otherwise.
        const ident = try self.coerce_type_ident_for(base, pointee_dt);
        const matched = reg.impls_by_key.contains(.{ .type_name = ident, .quirk_sig = sig }) or
            reg.impls_by_key.contains(.{ .type_name = base, .quirk_sig = sig });
        if (matched) return ident;
        self.allocator.free(@constCast(ident));
        return null;
    }

    /// Direct call-site quirk coercion: when a free function `callee(args)` has a
    /// quirk-typed parameter and the matching argument is a concrete pointer
    /// (`&dog` or a `Dog*` variable) whose pointee implements that quirk, wrap the
    /// argument in `__fun_coerce_<Type>_<hash>(...)` — mirroring the var-init /
    /// assignment / return coercion paths. Without this, `call_it(&d)` emits a raw
    /// `Dog*` where a quirk fat-pointer is expected (a C type error).
    ///
    /// Emits the WHOLE call and returns `true` when at least one argument needs
    /// coercion; returns `false` (writing nothing) so the caller's normal emission
    /// path runs unchanged otherwise — this keeps codegen byte-identical for every
    /// call that doesn't actually cross a concrete→quirk boundary.
    fn try_emit_call_with_quirk_coercion(self: *Self, call_node: ast.Node, fname: []const u8, fname_base: []const u8, left: *ast.Node, exp_right: ?*ast.Node) TranspileError!bool {
        const reg = self.root_registry() orelse return false;

        // Resolve the callee function node (try the mangled name, then the base).
        var fn_node = self.find_function_node(fname);
        if (fn_node == null and !mem.eql(u8, fname_base, fname)) {
            fn_node = self.find_function_node(fname_base);
        }
        const fnode = fn_node orelse return false;
        if (fnode.node_variant == null) return false;
        const fnv = fnode.node_variant.?.function;
        // Variadic callees are handled by the dedicated path above; skip here.
        if (fnv.is_variadic) return false;
        const args_vec = fnv.args orelse return false;
        const params = args_vec.items();
        if (params.len == 0) return false;

        // Does ANY parameter have a quirk type? If not, nothing to coerce. A
        // CONCRETE instantiation of a generic quirk (`To<num> v`) registers
        // under its MANGLED name (`To__num`, see `synthesize_quirk_instantiation`),
        // not the bare `type_str` ("To", the unbound template) — mangle first
        // so this recognizes it too.
        var any_quirk_param = false;
        for (params) |p| {
            if (p.type != .Variable or p.node_variant == null) continue;
            const pdt = p.node_variant.?.variable.type;
            if (pdt.pointer_depth != 0 or pdt.type != .Unknown) continue;
            if (pdt.generic_args != null) {
                const mangled = try self.type_name_mangled(pdt);
                defer self.allocator.free(mangled);
                if (self.is_quirk_name(mangled)) {
                    any_quirk_param = true;
                    break;
                }
            } else if (self.is_quirk_name(pdt.type_str.items)) {
                any_quirk_param = true;
                break;
            }
        }
        if (!any_quirk_param) return false;

        // Flatten the call arguments so we can pair them positionally with params.
        var args_nodes = ArrayList(*ast.Node).init(self.allocator);
        defer args_nodes.deinit();
        if (exp_right) |right| {
            try self.flatten_call_args_ptr(right, &args_nodes);
        }
        const min_args = count_required_args_from_node(args_vec);
        if (args_nodes.items.len < min_args or args_nodes.items.len > params.len) return false;

        // Determine, per argument, whether it actually crosses a concrete->quirk
        // boundary that we can coerce. Only commit to per-arg emission if at least
        // one does — otherwise fall back so unrelated calls stay byte-identical.
        // `coerce_ident[i]` holds the impl-key type name (mangled for generics,
        // e.g. `Box__num`), reused as the `__fun_coerce_<ident>_<hash>` name.
        var coerce_ident = self.allocator.alloc(?[]const u8, args_nodes.items.len) catch return TranspileError.MemoryAllocationFailed;
        defer {
            for (coerce_ident) |ci| if (ci) |s| self.allocator.free(@constCast(s));
            self.allocator.free(coerce_ident);
        }
        var coerce_sig = self.allocator.alloc(?[]const u8, args_nodes.items.len) catch return TranspileError.MemoryAllocationFailed;
        defer self.allocator.free(coerce_sig);
        var any = false;
        var i: usize = 0;
        while (i < args_nodes.items.len) : (i += 1) {
            coerce_ident[i] = null;
            coerce_sig[i] = null;
            const p = params[i];
            if (p.type != .Variable or p.node_variant == null) continue;
            const pdt = p.node_variant.?.variable.type;
            if (pdt.pointer_depth != 0 or pdt.type != .Unknown) continue;
            var mangled_owned: ?[]const u8 = null;
            defer if (mangled_owned) |m| self.allocator.free(m);
            const pname: []const u8 = blk: {
                if (pdt.generic_args != null) {
                    const m = try self.type_name_mangled(pdt);
                    mangled_owned = m;
                    break :blk m;
                }
                break :blk pdt.type_str.items;
            };
            if (!self.is_quirk_name(pname)) continue;
            const sig = reg.quirk_sig_by_name.get(pname) orelse continue;
            const ident = (try self.pointee_quirk_impl_name(args_nodes.items[i].*, sig)) orelse continue;
            coerce_ident[i] = ident;
            coerce_sig[i] = sig;
            any = true;
        }
        if (!any) return false;

        const default_info = self.resolve_free_call_default_info(call_node, left);

        // Emit `callee(arg0, arg1, ...)`, wrapping the coercible args.
        try self.transpile_node(left.*);
        try self.write("(");
        i = 0;
        while (i < args_nodes.items.len) : (i += 1) {
            if (i > 0) try self.write(", ");
            const arg = args_nodes.items[i].*;
            if (coerce_ident[i]) |ident| {
                const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(coerce_sig[i].?) });
                defer self.backing_allocator.free(coerce_name);
                try self.write(coerce_name);
                try self.write("(");
                try self.transpile_node(arg);
                try self.write(")");
            } else {
                try self.transpile_node(arg);
            }
        }
        try self.emit_omitted_default_args_from_params(
            params,
            args_nodes.items.len,
            args_nodes.items.len > 0,
            if (default_info) |info| info.subst_params else null,
            if (default_info) |info| info.subst_args else null,
        );
        try self.write(")");
        return true;
    }

    /// True when an enum is a tagged union (sum type) — i.e. at least one of its
    /// variants carries a payload. Payload-free enums keep the plain C `enum`
    /// lowering for full backward compatibility.
    fn enum_is_tagged_union(e: anytype) bool {
        for (e.variants.items()) |v| {
            if (v.payload != null) return true;
        }
        return false;
    }

    /// Emit a data-carrying enum as a tagged union:
    ///   typedef enum E_tag { E_A, E_B, ... } E_tag;
    ///   typedef struct E { E_tag tag; union { struct {..} A; ... } payload; } E;
    /// Variants with no payload occupy a tag slot but no union member.
    fn emit_tagged_union_enum(self: *Self, e: anytype) TranspileError!void {
        // Non-generic data enum: the emitted C name IS the declared name, and
        // payload types need no substitution.
        try self.emit_tagged_union_enum_named(e, e.name.items, null, null);
    }

    /// Core tagged-union emitter. `emit_name` is the C type name to define (the
    /// declared name for a plain enum, the mangled name like `Option__num` for a
    /// monomorphized generic instance). When `params`/`args` are non-null, payload
    /// types are emitted with type-parameter substitution (T -> the concrete arg).
    fn emit_tagged_union_enum_named(
        self: *Self,
        e: anytype,
        emit_name: []const u8,
        params: ?utils.Vector(ArrayList(u8)),
        args: ?[]*dtype.DataType,
    ) TranspileError!void {
        // Discriminant enum.
        try self.write("typedef enum ");
        try self.write(emit_name);
        try self.write("_tag {\n");
        for (e.variants.items()) |v| {
            try self.write("  ");
            try self.write(emit_name);
            try self.write("_");
            try self.write(v.name.items);
            try self.write(",\n");
        }
        try self.write("} ");
        try self.write(emit_name);
        try self.write("_tag;\n");

        // Tagged struct with a payload union.
        try self.write("typedef struct ");
        try self.write(emit_name);
        try self.write(" {\n  ");
        try self.write(emit_name);
        try self.write("_tag tag;\n  union {\n");
        for (e.variants.items()) |v| {
            const payload = v.payload orelse continue;
            try self.write("    struct { ");
            for (payload.items(), 0..) |pt, i| {
                if (params) |p| {
                    try self.write_type_with_subst(pt, p, args.?);
                } else {
                    try self.write_type(pt.*);
                }
                try self.print(" _{d}; ", .{i});
            }
            try self.write("} ");
            try self.write(v.name.items);
            try self.write(";\n");
        }
        try self.write("  } payload;\n} ");
        try self.write(emit_name);
        try self.write(";\n\n");
    }

    /// Emit every concrete monomorphized specialization of a GENERIC data enum
    /// (`enum Option<T> { Some(T), None }` -> `Option__num`, `Option__str`, ...).
    /// Mirrors `emit_generic_compound_specializations`: discover instantiations by
    /// scanning all type annotations, then emit each unique concrete one.
    fn emit_generic_enum_specializations(self: *Self, enode: *ast.Node) TranspileError!void {
        const e = enode.node_variant.?.enum_decl;
        const params = e.type_params orelse return;

        var inst_keys = std.StringHashMap(bool).init(self.allocator);
        defer {
            var it = inst_keys.iterator();
            while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
            inst_keys.deinit();
        }
        var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
        defer inst_list.deinit();

        try self.collect_generic_instantiations_recursive(self, e.name.items, &inst_keys, &inst_list);

        for (inst_list.items) |dt| {
            if (dt.generic_args == null) continue;
            const gargs = dt.generic_args.?.items();
            if (gargs.len != params.count) continue;
            if (!self.generic_args_are_concrete(&params, gargs)) continue;
            if (self.dtype_contains_type_param(dt, &params)) continue;

            const mangled = try self.type_name_mangled(dt);
            defer self.allocator.free(mangled);
            if (self.mangled_contains_type_param(mangled, &params)) continue;
            if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

            try self.emit_tagged_union_enum_named(e, mangled, params, dt.generic_args.?.items());
        }
    }

    /// Forward-declare each concrete monomorphized instance of a generic data enum
    /// (`typedef struct Option__num Option__num;`) so pointer-typed references
    /// (`Option__num* p`, `Channel<Option<num>>`) resolve before the full struct.
    fn forward_declare_generic_enum_specializations(self: *Self, enode: *ast.Node) TranspileError!void {
        const e = enode.node_variant.?.enum_decl;
        const params = e.type_params orelse return;

        var inst_keys = std.StringHashMap(bool).init(self.allocator);
        defer {
            var it = inst_keys.iterator();
            while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
            inst_keys.deinit();
        }
        var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
        defer inst_list.deinit();

        try self.collect_generic_instantiations_recursive(self, e.name.items, &inst_keys, &inst_list);

        for (inst_list.items) |dt| {
            if (dt.generic_args == null) continue;
            const gargs = dt.generic_args.?.items();
            if (gargs.len != params.count) continue;
            if (!self.generic_args_are_concrete(&params, gargs)) continue;
            if (self.dtype_contains_type_param(dt, &params)) continue;

            const mangled = try self.type_name_mangled(dt);
            defer self.allocator.free(mangled);
            if (self.mangled_contains_type_param(mangled, &params)) continue;
            if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

            try self.write("typedef struct ");
            try self.write(mangled);
            try self.write(" ");
            try self.write(mangled);
            try self.write(";\n");
        }
    }

    /// Emit a tagged-union compound literal for `EnumName.Variant(args...)`:
    ///   ((Enum){ .tag = Enum_Variant, .payload.Variant = { ._0 = (a0), ... } })
    /// `args_node` is the (possibly comma-flattened) call argument expression. The
    /// payload field names `_0`, `_1`, ... match the union struct layout emitted by
    /// `emit_tagged_union_enum`.
    fn emit_enum_variant_construction(self: *Self, enum_name: []const u8, variant_name: []const u8, args_node: ?*ast.Node) TranspileError!void {
        var args = ArrayList(*ast.Node).init(self.allocator);
        defer args.deinit();
        if (args_node) |an| {
            try self.flatten_call_args_ptr(an, &args);
        }
        try self.write("((");
        try self.write(enum_name);
        try self.write("){ .tag = ");
        try self.write(enum_name);
        try self.write("_");
        try self.write(variant_name);
        try self.write(", .payload.");
        try self.write(variant_name);
        try self.write(" = { ");
        for (args.items, 0..) |arg, i| {
            if (i > 0) try self.write(", ");
            try self.print("._{d} = (", .{i});
            try self.transpile_node(arg.*);
            try self.write(")");
        }
        try self.write(" } })");
    }

    fn emit_user_types(self: *Self) TranspileError!void {
        if (self.did_emit_user_types) return;
        self.did_emit_user_types = true;

        const registry = self.root_registry() orelse return;

        try self.write("// --- User types ---\n\n");

        // Enums (must come before compounds that use them by-value)
        var enum_nodes = ArrayList(*ast.Node).init(self.allocator);
        defer enum_nodes.deinit();

        var seen_enum_names = std.StringHashMap(bool).init(self.allocator);
        defer seen_enum_names.deinit();

        var e_it = registry.enums_by_name.iterator();
        while (e_it.next()) |entry| {
            const enode = entry.value_ptr.*;
            if (enode.node_variant == null) continue;
            const e = enode.node_variant.?.enum_decl;
            if (seen_enum_names.contains(e.name.items)) continue;
            seen_enum_names.put(e.name.items, true) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            enum_nodes.append(enode) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        std.sort.pdq(*ast.Node, enum_nodes.items, {}, struct {
            fn lessThan(_: void, a: *ast.Node, b: *ast.Node) bool {
                if (a.node_variant == null or b.node_variant == null) return false;
                return mem.lessThan(u8, a.node_variant.?.enum_decl.name.items, b.node_variant.?.enum_decl.name.items);
            }
        }.lessThan);

        var emitted_enum_names = std.StringHashMap(bool).init(self.allocator);
        defer emitted_enum_names.deinit();

        for (enum_nodes.items) |enode| {
            if (enode.node_variant == null) continue;
            if (self.is_std_c_signature_node(enode)) continue;
            const e = enode.node_variant.?.enum_decl;
            // Tagged-union (data-carrying) enums are emitted AFTER compounds, since a
            // by-value payload field (`Branch(Point)`) needs the compound's full
            // definition to already exist. Plain enums have no such dependency and
            // are emitted here, before compounds (a compound may hold an enum field).
            if (enum_is_tagged_union(e)) continue;
            if (emitted_enum_names.contains(e.name.items)) continue;
            emitted_enum_names.put(e.name.items, true) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            try self.write("typedef enum ");
            try self.write(e.name.items);
            try self.write(" {\n");
            for (e.variants.items()) |v| {
                try self.write("  ");
                try self.write(e.name.items);
                try self.write("_");
                try self.write(v.name.items);
                if (v.value) |val| {
                    try self.write(" = ");
                    try self.print("{d}", .{val});
                }
                try self.write(",\n");
            }
            try self.write("} ");
            try self.write(e.name.items);
            try self.write(";\n\n");
        }

        // Compounds
        // NOTE: `std.StringHashMap` iteration order is not stable and can place
        // dependent compounds before their dependencies (e.g. Rectangle before Point).
        // Emit compounds in a stable order that respects by-value dependencies.

        var compound_nodes = ArrayList(*ast.Node).init(self.allocator);
        defer compound_nodes.deinit();

        var seen_compound_names = std.StringHashMap(bool).init(self.allocator);
        defer seen_compound_names.deinit();

        var c_it = registry.compounds_by_name.iterator();
        while (c_it.next()) |entry| {
            const cnode = entry.value_ptr.*;
            if (cnode.node_variant == null) continue;
            const c = cnode.node_variant.?.compound;
            if (seen_compound_names.contains(c.name.items)) continue;
            seen_compound_names.put(c.name.items, true) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            compound_nodes.append(cnode) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        std.sort.pdq(*ast.Node, compound_nodes.items, {}, struct {
            fn lessThan(_: void, a: *ast.Node, b: *ast.Node) bool {
                if (a.node_variant == null or b.node_variant == null) return false;
                return mem.lessThan(u8, a.node_variant.?.compound.name.items, b.node_variant.?.compound.name.items);
            }
        }.lessThan);

        var emitted_compounds = std.StringHashMap(bool).init(self.allocator);
        defer emitted_compounds.deinit();

        var remaining = ArrayList(*ast.Node).init(self.allocator);
        defer remaining.deinit();
        remaining.appendSlice(compound_nodes.items) catch {
            return TranspileError.MemoryAllocationFailed;
        };

        var spec_keys = std.StringHashMap(bool).init(self.allocator);
        defer spec_keys.deinit();

        var specs = ArrayList(GenericSpec).init(self.allocator);
        defer {
            for (specs.items) |s| self.allocator.free(s.mangled);
            specs.deinit();
        }

        // Collect concrete generic compound specializations.
        for (compound_nodes.items) |cnode| {
            if (cnode.node_variant == null) continue;
            if (self.is_std_c_signature_node(cnode)) continue;
            const c = cnode.node_variant.?.compound;
            const params = c.type_params orelse continue;

            var inst_keys = std.StringHashMap(bool).init(self.allocator);
            defer {
                var it = inst_keys.iterator();
                while (it.next()) |e| {
                    self.allocator.free(e.key_ptr.*);
                }
                inst_keys.deinit();
            }

            var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
            defer inst_list.deinit();

            try self.collect_generic_instantiations_recursive(self, c.name.items, &inst_keys, &inst_list);

            for (inst_list.items) |dt| {
                if (dt.generic_args == null) continue;
                const gargs = dt.generic_args.?.items();
                if (gargs.len != params.count) continue;
                if (self.dtype_contains_type_param(dt, &params)) continue;

                // Ensure field-level generic dependencies are registered with concrete args.
                for (c.fields.items()) |f| {
                    if (f.dtype.generic_args == null) continue;
                    const dep = try self.clone_dtype_with_subst_for_inst(f.dtype, &params, gargs);
                    try self.register_generic_instantiations_from_dtype(dep);
                }

                const mangled = try self.type_name_mangled(dt);
                if (self.mangled_contains_type_param(mangled, &params)) {
                    self.allocator.free(mangled);
                    continue;
                }
                if (self.mangled_contains_unresolved_placeholder(mangled)) {
                    self.allocator.free(mangled);
                    continue;
                }
                if (!spec_keys.contains(mangled)) {
                    spec_keys.put(mangled, true) catch return TranspileError.MemoryAllocationFailed;
                    specs.append(.{ .cnode = cnode, .dt = dt, .mangled = mangled }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                } else {
                    self.allocator.free(mangled);
                }
            }

            // Include forced generic instantiations for this compound.
            const root = self.get_root();
            for (root.forced_generic_instantiations.items) |dt| {
                if (dt.generic_args == null) continue;
                const dt_base = if (mem.indexOf(u8, dt.type_str.items, "__")) |idx| dt.type_str.items[0..idx] else dt.type_str.items;
                if (!mem.eql(u8, dt_base, c.name.items)) continue;
                const gargs = dt.generic_args.?.items();
                if (gargs.len != params.count) continue;
                if (self.dtype_contains_type_param(dt, &params)) continue;
                const mangled = try self.type_name_mangled(dt);
                if (self.mangled_contains_type_param(mangled, &params)) {
                    self.allocator.free(mangled);
                    continue;
                }
                if (self.mangled_contains_unresolved_placeholder(mangled)) {
                    self.allocator.free(mangled);
                    continue;
                }
                if (!spec_keys.contains(mangled)) {
                    spec_keys.put(mangled, true) catch return TranspileError.MemoryAllocationFailed;
                    specs.append(.{ .cnode = cnode, .dt = dt, .mangled = mangled }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                } else {
                    self.allocator.free(mangled);
                }
            }
        }

        // Expand specs with field-level generic dependencies (e.g. Set<str> -> Map<str, bin>).
        var si_expand: usize = 0;
        while (si_expand < specs.items.len) {
            const s = specs.items[si_expand];
            si_expand += 1;
            if (s.cnode.node_variant == null) continue;
            const c = s.cnode.node_variant.?.compound;
            const params = c.type_params orelse continue;
            const gargs_vec = s.dt.generic_args orelse continue;
            const gargs = gargs_vec.items();

            for (c.fields.items()) |f| {
                if (f.dtype.generic_args == null) continue;
                const dep_dt = try self.clone_dtype_with_subst_for_inst(f.dtype, &params, gargs);
                if (dep_dt.generic_args == null) continue;
                if (self.dtype_has_unresolved_placeholder(dep_dt)) continue;

                const dep_base = if (mem.indexOf(u8, dep_dt.type_str.items, "__")) |idx| dep_dt.type_str.items[0..idx] else dep_dt.type_str.items;
                const dep_cnode = registry.compounds_by_name.get(dep_base) orelse continue;
                if (dep_cnode.node_variant == null) continue;
                if (dep_cnode.node_variant.?.compound.type_params == null) continue;

                const dep_mangled = try self.type_name_mangled(dep_dt);
                if (self.mangled_contains_unresolved_placeholder(dep_mangled)) {
                    self.allocator.free(dep_mangled);
                    continue;
                }
                if (!spec_keys.contains(dep_mangled)) {
                    spec_keys.put(dep_mangled, true) catch return TranspileError.MemoryAllocationFailed;
                    specs.append(.{ .cnode = dep_cnode, .dt = dep_dt, .mangled = dep_mangled }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                } else {
                    self.allocator.free(dep_mangled);
                }
            }
        }

        // Expand specs with impl signature dependencies (e.g. Map<K,V>::values -> Vec<V>).
        var si_impl: usize = 0;
        while (si_impl < specs.items.len) {
            const s = specs.items[si_impl];
            si_impl += 1;
            if (s.cnode.node_variant == null) continue;
            const c = s.cnode.node_variant.?.compound;
            const params = c.type_params orelse continue;
            const gargs_vec = s.dt.generic_args orelse continue;
            const gargs = gargs_vec.items();

            var proc_stack = ArrayList(*Self).init(self.allocator);
            defer proc_stack.deinit();
            const root_proc = self.get_root();
            proc_stack.append(root_proc) catch return TranspileError.MemoryAllocationFailed;

            while (proc_stack.items.len > 0) {
                const proc_opt = proc_stack.pop();
                const proc = proc_opt orelse continue;
                for (proc.nodes.items()) |node| {
                    var node_copy = node;
                    const node_ptr = &node_copy;
                    if (node_ptr.type != .Impl or node_ptr.node_variant == null) continue;
                    const im = node_ptr.node_variant.?.impl;
                    if (im.quirk_name != null) continue;
                    const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
                    if (!mem.eql(u8, base_name, c.name.items)) continue;
                    const impl_params = self.impl_type_params(node_ptr) orelse continue;
                    if (impl_params.count != params.count) continue;
                    if (gargs.len != impl_params.count) continue;

                    for (im.methods.items()) |m| {
                        if (m.type != .Function or m.node_variant == null) continue;
                        const fnv = m.node_variant.?.function;
                        if (fnv.rtype) |rt| {
                            const rt_sub = try self.clone_dtype_with_subst_for_inst(&rt, impl_params, gargs);
                            if (!self.dtype_has_unresolved_placeholder(rt_sub)) {
                                try self.register_generic_instantiations_from_dtype(rt_sub);
                                try self.add_spec_from_dtype(registry, rt_sub, &spec_keys, &specs);
                            }
                        }
                        if (fnv.args) |args_nodes| {
                            for (args_nodes.items()) |arg| {
                                if (arg.type != .Variable or arg.node_variant == null) continue;
                                const adt = arg.node_variant.?.variable.type;
                                const adt_sub = try self.clone_dtype_with_subst_for_inst(adt, impl_params, gargs);
                                if (!self.dtype_has_unresolved_placeholder(adt_sub)) {
                                    try self.register_generic_instantiations_from_dtype(adt_sub);
                                    try self.add_spec_from_dtype(registry, adt_sub, &spec_keys, &specs);
                                }
                            }
                        }
                    }
                }

                for (proc.owned_nodes.items) |n| {
                    if (n.type != .Impl or n.node_variant == null) continue;
                    const im = n.node_variant.?.impl;
                    if (im.quirk_name != null) continue;
                    const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
                    if (!mem.eql(u8, base_name, c.name.items)) continue;
                    const impl_params = self.impl_type_params(n) orelse continue;
                    if (impl_params.count != params.count) continue;
                    if (gargs.len != impl_params.count) continue;

                    for (im.methods.items()) |m| {
                        if (m.type != .Function or m.node_variant == null) continue;
                        const fnv = m.node_variant.?.function;
                        if (fnv.rtype) |rt| {
                            const rt_sub = try self.clone_dtype_with_subst_for_inst(&rt, impl_params, gargs);
                            if (!self.dtype_has_unresolved_placeholder(rt_sub)) {
                                try self.register_generic_instantiations_from_dtype(rt_sub);
                                try self.add_spec_from_dtype(registry, rt_sub, &spec_keys, &specs);
                            }
                        }
                        if (fnv.args) |args_nodes| {
                            for (args_nodes.items()) |arg| {
                                if (arg.type != .Variable or arg.node_variant == null) continue;
                                const adt = arg.node_variant.?.variable.type;
                                const adt_sub = try self.clone_dtype_with_subst_for_inst(adt, impl_params, gargs);
                                if (!self.dtype_has_unresolved_placeholder(adt_sub)) {
                                    try self.register_generic_instantiations_from_dtype(adt_sub);
                                    try self.add_spec_from_dtype(registry, adt_sub, &spec_keys, &specs);
                                }
                            }
                        }
                    }
                }

                for (proc.children.items) |child| {
                    proc_stack.append(child) catch return TranspileError.MemoryAllocationFailed;
                }
            }
        }

        // Ensure impl emission sees all emitted generic specializations.
        for (specs.items) |s| {
            try self.register_generic_instantiations_from_dtype(s.dt);
        }

        // Forward typedefs allow pointer fields (including self-pointers) to refer to
        // types declared later.
        for (compound_nodes.items) |cnode| {
            if (cnode.node_variant == null) continue;
            if (self.is_std_c_signature_node(cnode)) continue;
            const c = cnode.node_variant.?.compound;

            if (c.type_params != null) continue;
            try self.write("typedef struct ");
            try self.write(c.name.items);
            try self.write(" ");
            try self.write(c.name.items);
            try self.write(";\n");
        }

        // Forward declare tagged-union (data-carrying) enums BEFORE specializations.
        // A data-enum lowers to `struct Name { tag; union; }`; its full definition is
        // emitted late (PASS 4, after compounds, so by-value payloads see compound
        // defs). But a generic specialization like `Channel<Msg>` has a pointer field
        // `Msg* data` and is emitted earlier — without this forward `typedef struct
        // Msg Msg;` that pointer references an undeclared `Msg`. Pointer fields only
        // need the type name, so a forward decl is sufficient.
        for (enum_nodes.items) |enode| {
            if (enode.node_variant == null) continue;
            if (self.is_std_c_signature_node(enode)) continue;
            const e = enode.node_variant.?.enum_decl;
            if (!enum_is_tagged_union(e)) continue;
            if (e.type_params != null) {
                // Generic data enum: forward-declare each concrete monomorphized
                // instance (`Option__num`) rather than the template name.
                try self.forward_declare_generic_enum_specializations(enode);
                continue;
            }
            try self.write("typedef struct ");
            try self.write(e.name.items);
            try self.write(" ");
            try self.write(e.name.items);
            try self.write(";\n");
        }

        // Forward declare concrete generic specializations so pointer-typed fields
        // can reference them before their full definitions are emitted.
        for (specs.items) |s| {
            try self.write("typedef struct ");
            try self.write(s.mangled);
            try self.write(" ");
            try self.write(s.mangled);
            try self.write(";\n");
        }

        if (compound_nodes.items.len > 0 or specs.items.len > 0) try self.write("\n");

        // Emit quirk object structs early so compounds can store quirks by-value.
        // Vtable structs are forward-declared here and defined later once all
        // argument/return types are available.
        var qf_sig_it = registry.quirks_by_sig.iterator();
        while (qf_sig_it.next()) |entry| {
            const sig = entry.key_ptr.*;
            const qnode = entry.value_ptr.*;
            // Generic quirks have no monomorphic quirk-object/vtable (see vtable pass).
            if (qnode.node_variant != null and qnode.node_variant.?.quirk.is_generic) continue;
            const h = self.quirk_sig_hash_cached(sig);
            const names = try write_quirk_c_names_hash(h);
            const quirk_c = names.quirk[0..names.quirk_len];
            const vtable_c = names.vtable[0..names.vtable_len];

            try self.write("typedef struct ");
            try self.write(vtable_c);
            try self.write(" ");
            try self.write(vtable_c);
            try self.write(";\n");

            try self.write("typedef struct ");
            try self.write(quirk_c);
            try self.write(" {\n");
            try self.write("  void* self;\n");
            try self.write("  const ");
            try self.write(vtable_c);
            try self.write("* vtable;\n");
            try self.write("} ");
            try self.write(quirk_c);
            try self.write(";\n");
        }

        var qf_name_it = registry.quirk_sig_by_name.iterator();
        while (qf_name_it.next()) |entry| {
            const qname = entry.key_ptr.*;
            const sig = entry.value_ptr.*;
            // Generic quirks have no quirk-object struct to alias to.
            if (registry.quirks_by_sig.get(sig)) |qn| {
                if (qn.node_variant != null and qn.node_variant.?.quirk.is_generic) continue;
            }
            const h = self.quirk_sig_hash_cached(sig);
            const names = try write_quirk_c_names_hash(h);
            const quirk_c = names.quirk[0..names.quirk_len];

            try self.write("typedef ");
            try self.write(quirk_c);
            try self.write(" ");
            try self.write(qname);
            try self.write(";\n");
        }
        if (registry.quirks_by_sig.count() > 0 or registry.quirk_sig_by_name.count() > 0) try self.write("\n");

        var remaining_specs = ArrayList(GenericSpec).init(self.allocator);
        defer remaining_specs.deinit();
        remaining_specs.appendSlice(specs.items) catch {
            return TranspileError.MemoryAllocationFailed;
        };

        // Generic data-enum instances (`Option__str`, `Result__File`) join the
        // topological pass as first-class nodes: each is emitted once its by-value
        // payload dependencies (other compounds/enums) are emitted, and compounds
        // that hold one by value wait for it. This resolves the mutual ordering —
        // `Person { Option<str> }` needs `Option__str` first, while `Result<File>`
        // needs `File` first.
        const EnumSpec = struct { enode: *ast.Node, dt: *const dtype.DataType, mangled: []const u8 };
        var remaining_enum_specs = ArrayList(EnumSpec).init(self.allocator);
        defer remaining_enum_specs.deinit();
        {
            for (enum_nodes.items) |enode| {
                if (enode.node_variant == null) continue;
                if (self.is_std_c_signature_node(enode)) continue;
                const e = enode.node_variant.?.enum_decl;
                if (!enum_is_tagged_union(e)) continue;
                if (e.type_params == null) continue;
                const params = e.type_params.?;
                // Discover concrete instantiations of this generic enum.
                var inst_keys = std.StringHashMap(bool).init(self.allocator);
                defer {
                    var it = inst_keys.iterator();
                    while (it.next()) |entry| self.allocator.free(entry.key_ptr.*);
                    inst_keys.deinit();
                }
                var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
                defer inst_list.deinit();
                try self.collect_generic_instantiations_recursive(self, e.name.items, &inst_keys, &inst_list);
                for (inst_list.items) |dt| {
                    if (dt.generic_args == null) continue;
                    const gargs = dt.generic_args.?.items();
                    if (gargs.len != params.count) continue;
                    if (!self.generic_args_are_concrete(&params, gargs)) continue;
                    if (self.dtype_contains_type_param(dt, &params)) continue;
                    const mangled = try self.type_name_mangled(dt);
                    if (self.mangled_contains_type_param(mangled, &params) or self.mangled_contains_unresolved_placeholder(mangled)) {
                        self.allocator.free(mangled);
                        continue;
                    }
                    // Dedup by mangled name (arena-owned for the loop's lifetime).
                    var dup = false;
                    for (remaining_enum_specs.items) |es| {
                        if (mem.eql(u8, es.mangled, mangled)) {
                            dup = true;
                            break;
                        }
                    }
                    if (dup) {
                        self.allocator.free(mangled);
                        continue;
                    }
                    const owned = self.arena.allocator().dupe(u8, mangled) catch {
                        self.allocator.free(mangled);
                        return TranspileError.MemoryAllocationFailed;
                    };
                    remaining_enum_specs.append(.{ .enode = enode, .dt = dt, .mangled = owned }) catch {};
                    self.allocator.free(mangled);
                }
            }
        }

        // Non-generic data (tagged-union) enums participate in the SAME topo-sort as
        // compounds/specs so a RECURSIVE enum (`Json { Arr(Vec<Json>), Obj(Map<str,Json>) }`)
        // and its by-value wrappers (`Option<Json>`, `Vec__Json`, `Map__str__Json`) all
        // order correctly: `Json` is forward-declared early (so `Vec__Json`'s `Json* data`
        // resolves), emitted once its by-value payload deps are met, and recorded in
        // `emitted_compounds` so wrappers that embed `Json` BY VALUE wait for it.
        var remaining_nongeneric_enums = ArrayList(*ast.Node).init(self.allocator);
        defer remaining_nongeneric_enums.deinit();
        for (enum_nodes.items) |enode| {
            if (enode.node_variant == null) continue;
            if (self.is_std_c_signature_node(enode)) continue;
            const e = enode.node_variant.?.enum_decl;
            if (!enum_is_tagged_union(e)) continue;
            if (e.type_params != null) continue;
            if (emitted_enum_names.contains(e.name.items)) continue;
            remaining_nongeneric_enums.append(enode) catch return TranspileError.MemoryAllocationFailed;
        }

        while (remaining.items.len > 0 or remaining_specs.items.len > 0 or remaining_enum_specs.items.len > 0 or remaining_nongeneric_enums.items.len > 0) {
            var progress = false;

            var si: usize = 0;
            while (si < remaining_specs.items.len) {
                const s = remaining_specs.items[si];
                if (!try self.generic_spec_deps_satisfied(s.cnode, s.dt, &emitted_compounds)) {
                    si += 1;
                    continue;
                }

                try self.emit_generic_compound_specialization(s.cnode, s.dt);
                emitted_compounds.put(s.mangled, true) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                const root = self.get_root();
                if (!root.emitted_generic_spec_keys.contains(s.mangled)) {
                    const key = root.allocator.dupe(u8, s.mangled) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                    root.emitted_generic_spec_keys.put(key, true) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }
                _ = remaining_specs.swapRemove(si);
                progress = true;
            }

            // Emit a generic data-enum instance once its by-value payload type
            // dependencies are emitted (tracked in `emitted_compounds`, which also
            // records emitted enum instances).
            var ei: usize = 0;
            while (ei < remaining_enum_specs.items.len) {
                const es = remaining_enum_specs.items[ei];
                if (!self.generic_enum_spec_deps_satisfied(es.enode, es.dt, &emitted_compounds)) {
                    ei += 1;
                    continue;
                }
                const e = es.enode.node_variant.?.enum_decl;
                try self.emit_tagged_union_enum_named(e, es.mangled, e.type_params, es.dt.generic_args.?.items());
                emitted_compounds.put(es.mangled, true) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                _ = remaining_enum_specs.swapRemove(ei);
                progress = true;
            }

            // Emit a non-generic data enum once its by-value payload deps are emitted.
            // Record it in `emitted_compounds` (alongside compounds/enum-instances) so
            // anything embedding it by value (Option<Json>, Vec__Json) orders after it.
            var ni: usize = 0;
            while (ni < remaining_nongeneric_enums.items.len) {
                const enode = remaining_nongeneric_enums.items[ni];
                const e = enode.node_variant.?.enum_decl;
                if (!self.nongeneric_enum_deps_satisfied(e, &emitted_compounds)) {
                    ni += 1;
                    continue;
                }
                if (!emitted_enum_names.contains(e.name.items)) {
                    try self.emit_tagged_union_enum(e);
                    emitted_enum_names.put(e.name.items, true) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                }
                emitted_compounds.put(e.name.items, true) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                _ = remaining_nongeneric_enums.swapRemove(ni);
                progress = true;
            }

            var i: usize = 0;
            while (i < remaining.items.len) {
                const cnode = remaining.items[i];
                if (cnode.node_variant == null) {
                    _ = remaining.swapRemove(i);
                    progress = true;
                    continue;
                }
                const c = cnode.node_variant.?.compound;
                if (c.type_params != null) {
                    // Generic templates are never emitted directly (only their
                    // concrete specializations are, via `remaining_specs`). Removing
                    // one IS forward progress — without flagging it, a `remaining`
                    // list that contains ONLY uninstantiated generic templates would
                    // drain to empty yet still trip the `!progress` guard below,
                    // raising a false "cyclic by-value compound dependency" error for
                    // a generic compound that was merely declared and never used.
                    _ = remaining.swapRemove(i);
                    progress = true;
                    continue;
                }

                var deps_satisfied = true;
                for (c.fields.items()) |f| {
                    // Only enforce ordering for by-value named compound dependencies.
                    // Pointer-typed fields can refer to incomplete types.
                    if (f.dtype.flags != null and f.dtype.flags.?.is_array) continue;
                    if (f.dtype.pointer_depth != 0) continue;
                    if (f.dtype.type != .Unknown) continue;
                    if (f.dtype.type_str.items.len == 0) continue;
                    if (f.dtype.generic_args != null) {
                        const dep = try self.type_name_mangled(f.dtype);
                        defer self.allocator.free(dep);
                        if (!emitted_compounds.contains(dep)) {
                            deps_satisfied = false;
                            break;
                        }
                    } else {
                        const dep = f.dtype.type_str.items;
                        // A by-value field may be a compound OR a tagged-union data
                        // enum (e.g. `Logger { Sink sink; }` where `Sink` is a data
                        // enum). Both are emitted as full structs and recorded in
                        // `emitted_compounds`; either must precede this compound.
                        // Plain (non-payload) enums lower to a C enum (complete on
                        // forward decl), so only tagged-union enums create an
                        // ordering dependency.
                        const is_compound_dep = registry.compounds_by_name.contains(dep);
                        const is_data_enum_dep = blk: {
                            if (registry.enums_by_name.get(dep)) |enode| {
                                if (enode.node_variant) |nv| break :blk enum_is_tagged_union(nv.enum_decl);
                            }
                            break :blk false;
                        };
                        if (!is_compound_dep and !is_data_enum_dep) continue;
                        if (!emitted_compounds.contains(dep)) {
                            deps_satisfied = false;
                            break;
                        }
                    }
                }

                if (deps_satisfied) {
                    try self.write("typedef struct ");
                    try self.write(c.name.items);
                    try self.write(" {\n");

                    for (c.fields.items()) |f| {
                        try self.write("  ");
                        const is_fixed_array = f.dtype.array != null and !f.dtype.array.?.brackets.is_empty();
                        if (is_fixed_array) {
                            // Fixed-size array field (`num[3] data;`): emit an INLINE
                            // C array (`int64_t data[3];`) so the storage lives in the
                            // struct. Previously every array field was demoted to a
                            // bare pointer, which gave the wrong layout/size and left
                            // the field uninitialized (dangling) — a silent miscompile.
                            var base = f.dtype.*;
                            if (base.flags) |*flags| flags.is_array = false;
                            base.array = null;
                            base.array_depth = 0;
                            try self.write_type(base);
                            try self.write(" ");
                            try self.write(f.name.items);
                            try self.write_type_array_suffix(f.dtype);
                        } else if (f.dtype.flags != null and f.dtype.flags.?.is_array) {
                            // Unsized array field (`num[] data;`): no concrete extent,
                            // so store it as a pointer (C struct members can't be
                            // flexible arrays except as a trailing member).
                            var dt = f.dtype.*;
                            if (dt.flags) |*flags| flags.is_array = false;
                            if (dt.pointer_depth == 0) dt.pointer_depth = 1;
                            try self.write_type(dt);
                            try self.write(" ");
                            try self.write(f.name.items);
                        } else {
                            try self.write_type(f.dtype.*);
                            try self.write(" ");
                            try self.write(f.name.items);
                        }
                        try self.write(";\n");
                    }
                    try self.write("} ");
                    try self.write(c.name.items);
                    try self.write(";\n\n");

                    emitted_compounds.put(c.name.items, true) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                    _ = remaining.swapRemove(i);
                    progress = true;
                    continue;
                }

                i += 1;
            }

            if (!progress) {
                self.report_error(null, "cyclic by-value compound dependency (use pointers to break the cycle)", .{});
                return TranspileError.CyclicCompoundDependency;
            }
        }

        // Tagged-union (data-carrying) enums, emitted AFTER all compounds so a
        // by-value payload field (`Branch(Point)`) sees the compound's definition.
        for (enum_nodes.items) |enode| {
            if (enode.node_variant == null) continue;
            if (self.is_std_c_signature_node(enode)) continue;
            const e = enode.node_variant.?.enum_decl;
            if (!enum_is_tagged_union(e)) continue;
            // A GENERIC data enum (`enum Option<T>`) is a template — never emit it
            // directly. Its monomorphized instances were already emitted before the
            // compound pass (so by-value enum fields see the full definition); skip
            // here to avoid a duplicate definition.
            if (e.type_params != null) continue;
            if (emitted_enum_names.contains(e.name.items)) continue;
            emitted_enum_names.put(e.name.items, true) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            try self.emit_tagged_union_enum(e);
        }

        // Quirk canonical structs per signature
        var q_it = registry.quirks_by_sig.iterator();
        while (q_it.next()) |entry| {
            const sig = entry.key_ptr.*;
            const qnode = entry.value_ptr.*;
            if (qnode.node_variant == null) continue;
            const q = qnode.node_variant.?.quirk;
            // Generic quirks (`Iterator<T>`) dispatch statically; an unbound `T` in a
            // method return/arg cannot be expressed in one C vtable signature, so skip.
            if (q.is_generic) continue;

            const h = self.quirk_sig_hash_cached(sig);
            const names = try write_quirk_c_names_hash(h);
            const vtable_c = names.vtable[0..names.vtable_len];

            // Vtable type
            try self.write("typedef struct ");
            try self.write(vtable_c);
            try self.write(" {\n");
            for (q.methods.items()) |m| {
                try self.write("  ");
                try self.write_return_type(m.rtype);
                try self.write(" (*");
                try self.write(m.name.items);
                try self.write(")(void* self");
                for (m.args.items(), 0..) |a, i| {
                    _ = i;
                    try self.write(", ");
                    try self.write_type(a.dtype.*);
                }
                try self.write(");\n");
            }
            try self.write("} ");
            try self.write(vtable_c);
            try self.write(";\n\n");
        }

        // Quirk aliases are emitted above as forward typedefs.
    }

    fn emit_quirk_impl_instance(
        self: *Self,
        impl_node: *ast.Node,
        type_name: []const u8,
        quirk_name: []const u8,
        sig_h: u64,
        q: anytype,
        params: ?*const utils.Vector(ArrayList(u8)),
        gargs: ?[]*dtype.DataType,
    ) TranspileError!void {
        return self.emit_quirk_impl_instance_opt(impl_node, type_name, quirk_name, sig_h, q, params, gargs, false);
    }

    /// `protos_only`: emit just the method forward-declarations and return. Used to
    /// pre-declare all generic-quirk-impl methods up front, so one quirk-impl body can
    /// call another's method (`SetIter.next` -> `MapIter.next`) regardless of emission
    /// order. The full call (protos_only=false) additionally emits bodies and, for
    /// non-generic quirks, the vtable/wrapper/coercion machinery.
    fn emit_quirk_impl_instance_opt(
        self: *Self,
        impl_node: *ast.Node,
        type_name: []const u8,
        quirk_name: []const u8,
        sig_h: u64,
        q: anytype,
        params: ?*const utils.Vector(ArrayList(u8)),
        gargs: ?[]*dtype.DataType,
        protos_only: bool,
    ) TranspileError!void {
        if (impl_node.node_variant == null) return;
        const im = impl_node.node_variant.?.impl;

        const names = try write_quirk_c_names_hash(sig_h);
        const quirk_c = names.quirk[0..names.quirk_len];
        const vtable_c = names.vtable[0..names.vtable_len];

        const prev_params = self.type_subst_params;
        const prev_args = self.type_subst_args;
        self.type_subst_params = params;
        self.type_subst_args = gargs;
        defer {
            self.type_subst_params = prev_params;
            self.type_subst_args = prev_args;
        }

        var type_stack: [128]u8 = undefined;
        const type_s = try self.c_ident_sanitize_temp(type_name, &type_stack);
        defer if (type_s.owned) self.backing_allocator.free(type_s.slice);

        const vtbl_name = try self.c_name_alloc("__fun_impl_{s}_{x}_vtable", .{ type_s.slice, sig_h });
        defer self.backing_allocator.free(vtbl_name);

        const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ type_s.slice, sig_h });
        defer self.backing_allocator.free(coerce_name);

        // Forward declare generated impl methods so wrappers can call them.
        for (im.methods.items()) |m| {
            if (m.type != .Function or m.node_variant == null) continue;
            const fnv = m.node_variant.?.function;
            if (fnv.name == null) continue;
            const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;

            var impl_fn_name = fnv.name.?.items;
            var impl_fn_owned = false;
            if (!mem.eql(u8, type_name, im.type_name.items)) {
                impl_fn_name = std.fmt.allocPrint(self.allocator, "{s}__{s}__{s}", .{ type_name, quirk_name, base }) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                impl_fn_owned = true;
            }
            defer if (impl_fn_owned) self.allocator.free(impl_fn_name);

            if (fnv.rtype) |rt| {
                try self.write_return_type(rt);
            } else {
                try self.write("void");
            }
            try self.write(" ");
            try self.write(impl_fn_name);
            try self.write("(");
            self.in_function_params = true;
            if (fnv.args) |args| {
                for (args.items(), 0..) |arg, i| {
                    if (i > 0) try self.write(", ");
                    try self.transpile_node(arg.*);
                }
            }
            self.in_function_params = false;
            try self.write(");\n");

            if (fnv.is_async) {
                const prev_override = self.override_fn_name;
                self.override_fn_name = impl_fn_name;
                defer self.override_fn_name = prev_override;
                try self.write_async_function_support_prototypes(m.*);
            }
        }

        // Prototype-only pass stops here: the method forward-declarations above are all
        // that other quirk-impl bodies need to call across emission order.
        if (protos_only) return;

        // A generic quirk has no monomorphic vtable/quirk-object struct, so dispatch is
        // purely static (direct calls to the method bodies below). Skip the coercion
        // forward-decl, the `void* self` wrappers, the vtable instance, and the
        // coercion definition — all of which reference the (absent) quirk-object type.
        const emit_vtable = !q.is_generic;

        // Forward-declare the coercion helper BEFORE the method bodies. A quirk-impl
        // method may `ret self;` (returning the concrete coerced to the quirk), which
        // calls this helper — but its definition is emitted at the end of this
        // function, so without a prototype the body referenced an undeclared function.
        if (emit_vtable) {
            try self.write("static inline ");
            try self.write(quirk_c);
            try self.write(" ");
            try self.write(coerce_name);
            try self.write("(");
            try self.write(type_name);
            try self.write("* self);\n");
        }

        try self.write("\n");

        // Emit method bodies.
        for (im.methods.items()) |m| {
            if (m.type != .Function or m.node_variant == null) continue;
            const fnv = m.node_variant.?.function;
            if (fnv.body == null) continue;
            if (fnv.name == null) continue;
            const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;

            var impl_fn_name = fnv.name.?.items;
            var impl_fn_owned = false;
            if (!mem.eql(u8, type_name, im.type_name.items)) {
                impl_fn_name = std.fmt.allocPrint(self.allocator, "{s}__{s}__{s}", .{ type_name, quirk_name, base }) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                impl_fn_owned = true;
            }
            const prev_override = self.override_fn_name;
            self.override_fn_name = impl_fn_name;
            defer self.override_fn_name = prev_override;

            // Expose the method's return type so a constructed generic enum whose own
            // param isn't in the active subst (`Option<K>` here) can be monomorphized.
            const prev_ret = self.current_method_return_dtype;
            self.current_method_return_dtype = if (fnv.rtype) |*rt| rt else null;
            defer self.current_method_return_dtype = prev_ret;

            try self.transpile_node(m.*);
            if (impl_fn_owned) self.allocator.free(impl_fn_name);
            try self.write("\n\n");
        }

        // Wrappers with `void* self` to match vtable signature.
        if (emit_vtable) {
            for (q.methods.items()) |m| {
                var impl_fn_name: ?[]const u8 = null;
                var impl_fn_owned = false;
                if (!mem.eql(u8, type_name, im.type_name.items)) {
                    impl_fn_name = std.fmt.allocPrint(self.allocator, "{s}__{s}__{s}", .{ type_name, quirk_name, m.name.items }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };
                    impl_fn_owned = true;
                } else {
                    for (im.methods.items()) |fm| {
                        if (fm.type != .Function or fm.node_variant == null) continue;
                        const fnv = fm.node_variant.?.function;
                        if (fnv.name == null) continue;
                        const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                        if (mem.eql(u8, base, m.name.items)) {
                            impl_fn_name = fnv.name.?.items;
                            break;
                        }
                    }
                }
                if (impl_fn_name == null) continue;
                defer if (impl_fn_owned) self.allocator.free(impl_fn_name.?);

                var m_stack: [128]u8 = undefined;
                const m_s = try self.c_ident_sanitize_temp(m.name.items, &m_stack);
                defer if (m_s.owned) self.backing_allocator.free(m_s.slice);
                const wrap_name = try self.c_name_alloc("__fun_wrap_{s}_{x}_{s}", .{ type_s.slice, sig_h, m_s.slice });
                defer self.backing_allocator.free(wrap_name);

                try self.write("static ");
                try self.write_return_type(m.rtype);
                try self.write(" ");
                try self.write(wrap_name);
                try self.write("(void* self");
                for (m.args.items(), 0..) |a, i| {
                    try self.write(", ");
                    try self.write_type(a.dtype.*);
                    var an: [16]u8 = undefined;
                    const aname = (std.fmt.bufPrint(&an, " a{d}", .{i}) catch unreachable);
                    try self.write(aname);
                }
                try self.write(") {\n");

                try self.write("  ");
                if (m.rtype.type != .Void) {
                    try self.write("return ");
                }
                if (m.is_async) {
                    try self.write("__fun_async_call_");
                }
                try self.write(impl_fn_name.?);
                try self.write("((");
                try self.write(type_name);
                try self.write("*)self");
                for (m.args.items(), 0..) |_, i| {
                    var an2: [16]u8 = undefined;
                    const aname2 = (std.fmt.bufPrint(&an2, ", a{d}", .{i}) catch unreachable);
                    try self.write(aname2);
                }
                try self.write(");\n");
                try self.write("}\n\n");
            }

            // Vtable instance
            try self.write("static const ");
            try self.write(vtable_c);
            try self.write(" ");
            try self.write(vtbl_name);
            try self.write(" = {\n");
            for (q.methods.items()) |m| {
                var m_stack2: [128]u8 = undefined;
                const m_s = try self.c_ident_sanitize_temp(m.name.items, &m_stack2);
                defer if (m_s.owned) self.backing_allocator.free(m_s.slice);
                const wrap_name2 = try self.c_name_alloc("__fun_wrap_{s}_{x}_{s}", .{ type_s.slice, sig_h, m_s.slice });
                defer self.backing_allocator.free(wrap_name2);
                try self.write("  .");
                try self.write(m.name.items);
                try self.write(" = ");
                try self.write(wrap_name2);
                try self.write(",\n");
            }
            try self.write("};\n\n");

            // Coercion helper
            try self.write("static inline ");
            try self.write(quirk_c);
            try self.write(" ");
            try self.write(coerce_name);
            try self.write("(");
            try self.write(type_name);
            try self.write("* self) {\n");
            try self.write("  return (");
            try self.write(quirk_c);
            try self.write("){ .self = self, .vtable = &");
            try self.write(vtbl_name);
            try self.write(" };\n");
            try self.write("}\n\n");
        }
    }

    fn emit_impls_and_vtables(self: *Self) TranspileError!void {
        if (self.did_emit_impls) return;
        self.did_emit_impls = true;

        const reg = self.root_registry() orelse return;

        // Plain impl methods (`impl Type { ... }`) can be called from within quirk impl
        // method bodies. Emit their forward declarations up-front so C compilation
        // never relies on implicit declarations.
        // NOTE: Prototypes will also be emitted again in the "Plain impl methods" block;
        // duplicate identical prototypes are OK in C.
        var plain_emitted = std.StringHashMap(bool).init(self.backing_allocator);
        defer plain_emitted.deinit();
        try self.emit_plain_impl_method_prototypes_registry(&plain_emitted);
        try self.emit_plain_impl_method_prototypes_module(self, &plain_emitted);
        try self.write("\n");

        // Forward-declare ALL quirk-coercion helpers up front. A quirk-impl method
        // body can return a coercion of ANY concrete type (e.g. `A.to_b()` does
        // `ret &self.b;` -> `__fun_coerce_B_...`), and impls are emitted in registry
        // order, so a body may reference a helper whose definition comes later. The
        // per-impl forward-decl alone covers only the impl's own type; this covers
        // cross-impl references too. (Only concrete, non-type-param impls — generic
        // template impls emit their helpers per-instantiation.)
        {
            var coerce_protos = std.StringHashMap(bool).init(self.allocator);
            defer {
                var pit = coerce_protos.keyIterator();
                while (pit.next()) |k| self.allocator.free(k.*);
                coerce_protos.deinit();
            }
            var cit = reg.impls_by_key.iterator();
            while (cit.next()) |entry| {
                const impl_node = entry.value_ptr.*;
                if (impl_node.node_variant == null) continue;
                const im = impl_node.node_variant.?.impl;
                if (im.quirk_name == null) continue;
                if (self.impl_type_params(impl_node) != null) continue; // generic templates: per-inst
                if (self.mangled_contains_unresolved_placeholder(im.type_name.items)) continue;
                // A CONCRETE quirk-instantiation binding (`impl Point as To<num>`)
                // has its own synthesized, non-generic quirk identity — prefer that
                // for the vtable/coercion machinery so it emits a real coercion
                // (unlike a SYMBOLIC binding, e.g. `impl Counter as Iterator<num>`
                // with no `quirk_concrete_instantiation`, which stays on the bare
                // name and is correctly skipped below: generic quirks dispatch
                // statically, with no quirk-object/coercion to emit).
                const quirk_name = if (im.quirk_concrete_instantiation) |qci| qci.items else im.quirk_name.?.items;
                const sig = reg.quirk_sig_by_name.get(quirk_name) orelse continue;
                // Generic quirks have no canonical quirk-object/coercion (dispatch is
                // static), so a concrete impl of one (`Counter as Iterator<num>`) must
                // not emit a coercion forward-decl referencing the absent quirk struct.
                if (reg.quirks_by_sig.get(sig)) |qn| {
                    if (qn.node_variant != null and qn.node_variant.?.quirk.is_generic) continue;
                }
                const sig_h = self.quirk_sig_hash_cached(sig);
                var ts: [128]u8 = undefined;
                const ts_s = try self.c_ident_sanitize_temp(im.type_name.items, &ts);
                defer if (ts_s.owned) self.backing_allocator.free(ts_s.slice);
                const cname = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ts_s.slice, sig_h });
                defer self.backing_allocator.free(cname);
                if (coerce_protos.contains(cname)) continue;
                coerce_protos.put(self.allocator.dupe(u8, cname) catch return TranspileError.MemoryAllocationFailed, true) catch return TranspileError.MemoryAllocationFailed;
                const names = try write_quirk_c_names_hash(sig_h);
                try self.write("static inline ");
                try self.write(names.quirk[0..names.quirk_len]);
                try self.write(" ");
                try self.write(cname);
                try self.write("(");
                try self.write(im.type_name.items);
                try self.write("* self);\n");
            }
            try self.write("\n");
        }

        // Pre-pass: forward-declare every generic-quirk-impl method up front, so a
        // quirk-impl body can call another quirk-impl's method irrespective of the
        // order their bodies are emitted (`SetIter.next` -> `MapIter.next`).
        {
            var proto_it = reg.impls_by_key.iterator();
            while (proto_it.next()) |entry| {
                const impl_node = entry.value_ptr.*;
                if (impl_node.node_variant == null) continue;
                const im = impl_node.node_variant.?.impl;
                if (self.mangled_contains_unresolved_placeholder(im.type_name.items)) continue;
                const quirk_name = if (im.quirk_name) |qn| qn.items else continue;
                const sig = reg.quirk_sig_by_name.get(quirk_name) orelse continue;
                const sig_h = self.quirk_sig_hash_cached(sig);
                const qnode = reg.quirks_by_sig.get(sig) orelse continue;
                if (qnode.node_variant == null) continue;
                const q = qnode.node_variant.?.quirk;
                if (!q.is_generic) continue; // non-generic quirk methods are not called directly

                if (self.impl_type_params(impl_node)) |params| {
                    var inst_keys = std.StringHashMap(bool).init(self.allocator);
                    defer {
                        var it = inst_keys.iterator();
                        while (it.next()) |e| self.allocator.free(e.key_ptr.*);
                        inst_keys.deinit();
                    }
                    var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
                    defer inst_list.deinit();
                    const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
                    try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);
                    for (inst_list.items) |dt| {
                        if (dt.generic_args == null) continue;
                        const gargs = dt.generic_args.?.items();
                        if (gargs.len != params.items().len) continue;
                        if (!self.generic_args_are_concrete(params, gargs)) continue;
                        if (self.dtype_contains_type_param(dt, params)) continue;
                        const mangled = try self.type_name_mangled(dt);
                        defer self.allocator.free(mangled);
                        if (self.mangled_contains_type_param(mangled, params)) continue;
                        if (self.mangled_contains_unresolved_placeholder(mangled)) continue;
                        try self.emit_quirk_impl_instance_opt(impl_node, mangled, quirk_name, sig_h, q, params, gargs, true);
                    }
                } else {
                    try self.emit_quirk_impl_instance_opt(impl_node, im.type_name.items, quirk_name, sig_h, q, null, null, true);
                }
            }
        }

        // Impl wrappers/vtables/coercions
        try self.write("// --- Quirk impl vtables ---\n\n");
        // A CONCRETE quirk-instantiation binding (`impl Counter as Iterator<num>`)
        // is registered in `impls_by_key` under BOTH its bare quirk name AND its
        // mangled concrete identity (see `collect_impls_module`), so the SAME
        // impl node can appear twice in this iteration — dedupe by node pointer
        // so its method bodies aren't emitted (and redefined in C) twice.
        var body_emitted_nodes = std.AutoHashMap(*ast.Node, void).init(self.backing_allocator);
        defer body_emitted_nodes.deinit();
        var impl_it = reg.impls_by_key.iterator();
        while (impl_it.next()) |entry| {
            const impl_node = entry.value_ptr.*;
            if (impl_node.node_variant == null) continue;
            const im = impl_node.node_variant.?.impl;
            if (self.mangled_contains_unresolved_placeholder(im.type_name.items)) continue;
            // Prefer the CONCRETE instantiation's own synthesized (non-generic)
            // quirk identity when this binding names one (`impl Point as
            // To<num>`) — its vtable/coercion should be emitted like an
            // ordinary concrete quirk's. A SYMBOLIC binding (`impl Counter as
            // Iterator<num>`, no `quirk_concrete_instantiation`) stays on the
            // bare name, where `emit_quirk_impl_instance` already knows to
            // skip the vtable/coercion machinery for the still-generic quirk.
            const quirk_name = if (im.quirk_concrete_instantiation) |qci| qci.items else if (im.quirk_name) |qn| qn.items else continue;
            const sig = reg.quirk_sig_by_name.get(quirk_name) orelse continue;
            if (body_emitted_nodes.contains(impl_node)) continue;
            body_emitted_nodes.put(impl_node, {}) catch return TranspileError.MemoryAllocationFailed;
            const sig_h = self.quirk_sig_hash_cached(sig);
            const qnode = reg.quirks_by_sig.get(sig) orelse continue;
            if (qnode.node_variant == null) continue;
            const q = qnode.node_variant.?.quirk;
            // NOTE: generic quirks still flow through emit_quirk_impl_instance so their
            // monomorphized method bodies are emitted; that function internally skips
            // the vtable/wrapper/coercion machinery (which has no monomorphic form for
            // an unbound `T`) and emits only the static method bodies.

            if (self.impl_type_params(impl_node)) |params| {
                var inst_keys = std.StringHashMap(bool).init(self.allocator);
                defer {
                    var it = inst_keys.iterator();
                    while (it.next()) |e| {
                        self.allocator.free(e.key_ptr.*);
                    }
                    inst_keys.deinit();
                }

                var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
                defer inst_list.deinit();
                const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
                try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);

                for (inst_list.items) |dt| {
                    if (dt.generic_args == null) continue;
                    const gargs = dt.generic_args.?.items();
                    if (gargs.len != params.items().len) continue;
                    if (!self.generic_args_are_concrete(params, gargs)) continue;
                    if (self.dtype_contains_type_param(dt, params)) continue;

                    const mangled = try self.type_name_mangled(dt);
                    defer self.allocator.free(mangled);
                    if (self.mangled_contains_type_param(mangled, params)) continue;
                    if (self.mangled_contains_unresolved_placeholder(mangled)) continue;
                    try self.emit_quirk_impl_instance(impl_node, mangled, quirk_name, sig_h, q, params, gargs);
                }
            } else {
                try self.emit_quirk_impl_instance(impl_node, im.type_name.items, quirk_name, sig_h, q, null, null);
            }
        }

        // Plain impl method bodies (non-quirk): `impl Type { ... }`
        try self.write("// --- Plain impl methods ---\n\n");
        var emitted = std.StringHashMap(bool).init(self.backing_allocator);
        defer emitted.deinit();
        try self.emit_plain_impl_methods_registry(&emitted);
        try self.emit_plain_impl_methods_module(self, &emitted);
    }

    fn emit_plain_impl_method_prototypes_registry(self: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        const reg = self.root_registry() orelse return;
        var it = reg.impls_by_key.iterator();
        while (it.next()) |entry| {
            const impl_node = entry.value_ptr.*;
            try self.emit_plain_impl_method_prototypes_from_node(impl_node, emitted);
        }
    }

    fn emit_plain_impl_method_prototypes_from_node(self: *Self, n: *ast.Node, emitted: *std.StringHashMap(bool)) TranspileError!void {
        if (n.type != .Impl or n.node_variant == null) return;
        const im = n.node_variant.?.impl;
        // A GENERIC quirk impl (`impl Box<T> as Iterator<T>`) still skips this
        // pass entirely -- the branch below (gated on `self.impl_type_params`)
        // mangles each instantiation as `mangled__base`, with no quirk-name
        // segment at all, which would be WRONG for a quirk impl (the real
        // symbol is `mangled__QuirkName__base`, see `emit_quirk_impl_instance`'s
        // own identical naming a few hundred lines up). A NON-generic quirk
        // impl (`impl Gender as Display`, e.g.) falls through instead: its
        // own `fnv.name` is ALREADY the fully-mangled `Type__Quirk__method`
        // string (see the near-identical forward-declare loop just above this
        // function, which only re-mangles when `type_name` differs from
        // `im.type_name` -- the common case already matches), so the plain
        // per-method loop below emits a correct prototype unchanged. Without
        // this, a quirk impl's own method body calling ANOTHER quirk impl's
        // method declared LATER in the same file/module (`impl User as
        // Display`'s `to_string()` calling `self.gender.to_string()`, where
        // `Gender`'s own `as Display` impl comes after `User`'s in source
        // order) hit "implicit function declaration" followed by "conflicting
        // types" -- confirmed via a real minimal repro, not previously
        // exercised by the existing test/example corpus.
        if (im.quirk_name != null and self.impl_type_params(n) != null) return;
        if (self.mangled_contains_unresolved_placeholder(im.type_name.items)) return;

        if (self.impl_type_params(n)) |params| {
            var inst_keys = std.StringHashMap(bool).init(self.allocator);
            defer {
                var it = inst_keys.iterator();
                while (it.next()) |e| {
                    self.allocator.free(e.key_ptr.*);
                }
                inst_keys.deinit();
            }

            var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
            defer inst_list.deinit();
            const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);

            for (inst_list.items) |dt| {
                if (dt.generic_args == null) continue;
                const gargs = dt.generic_args.?.items();
                if (gargs.len != params.count) continue;
                if (!self.generic_args_are_concrete(params, gargs)) continue;
                if (self.dtype_contains_type_param(dt, params)) continue;

                const mangled = try self.type_name_mangled(dt);
                defer self.allocator.free(mangled);
                if (self.mangled_contains_type_param(mangled, params)) continue;
                if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

                for (im.methods.items()) |m| {
                    if (m.type != .Function or m.node_variant == null) continue;
                    const fnv = m.node_variant.?.function;
                    // Methods with their OWN type param (`pub map<U>(...)`) are
                    // emitted via `generic_fn_instantiations` instead (registered
                    // per-call-site, since a method can be called with several
                    // DIFFERENT concrete U's) -- skip them here to avoid emitting
                    // a broken, un-substituted duplicate.
                    if (fnv.type_params != null) continue;
                    if (fnv.name == null) continue;
                    const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                    const spec_name = std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ mangled, base }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };

                    const gop = emitted.getOrPut(spec_name) catch return TranspileError.MemoryAllocationFailed;
                    if (gop.found_existing) continue;
                    gop.value_ptr.* = true;

                    {
                        const prev_params = self.type_subst_params;
                        const prev_args = self.type_subst_args;
                        self.type_subst_params = params;
                        self.type_subst_args = gargs;
                        defer {
                            self.type_subst_params = prev_params;
                            self.type_subst_args = prev_args;
                        }

                        if (fnv.rtype) |rt| {
                            try self.write_return_type(rt);
                        } else {
                            try self.write("void");
                        }
                        try self.write(" ");
                        try self.write(spec_name);
                        try self.write("(");
                        self.in_function_params = true;
                        if (fnv.args) |args| {
                            for (args.items(), 0..) |arg, i| {
                                if (i > 0) try self.write(", ");
                                try self.transpile_node(arg.*);
                            }
                        }
                        self.in_function_params = false;
                        try self.write(");\n");

                        if (fnv.is_async) {
                            const prev_override = self.override_fn_name;
                            self.override_fn_name = spec_name;
                            defer self.override_fn_name = prev_override;
                            try self.write_async_function_support_prototypes(m.*);
                        }
                    }
                }
            }

            const root = self.get_root();
            var spec_it = root.emitted_generic_spec_keys.iterator();
            while (spec_it.next()) |entry| {
                const mangled_name = entry.key_ptr.*;
                const idx = mem.indexOf(u8, mangled_name, "__") orelse continue;
                const spec_base = mangled_name[0..idx];
                if (!mem.eql(u8, spec_base, base_name)) continue;
                if (self.mangled_contains_unresolved_placeholder(mangled_name)) continue;
                if (self.mangled_contains_type_param(mangled_name, params)) continue;
                const dt = (try self.dtype_from_mangled_type(mangled_name)) orelse continue;
                if (dt.generic_args == null) continue;
                const gargs = dt.generic_args.?.items();
                if (gargs.len != params.count) continue;
                if (!self.generic_args_are_concrete(params, gargs)) continue;
                if (self.dtype_contains_type_param(dt, params)) continue;

                for (im.methods.items()) |m| {
                    if (m.type != .Function or m.node_variant == null) continue;
                    const fnv = m.node_variant.?.function;
                    if (fnv.type_params != null) continue;
                    if (fnv.name == null) continue;
                    const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                    const spec_name = std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ mangled_name, base }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };

                    const gop = emitted.getOrPut(spec_name) catch return TranspileError.MemoryAllocationFailed;
                    if (gop.found_existing) continue;
                    gop.value_ptr.* = true;

                    {
                        const prev_params = self.type_subst_params;
                        const prev_args = self.type_subst_args;
                        self.type_subst_params = params;
                        self.type_subst_args = gargs;
                        defer {
                            self.type_subst_params = prev_params;
                            self.type_subst_args = prev_args;
                        }

                        if (fnv.rtype) |rt| {
                            try self.write_return_type(rt);
                        } else {
                            try self.write("void");
                        }
                        try self.write(" ");
                        try self.write(spec_name);
                        try self.write("(");
                        self.in_function_params = true;
                        if (fnv.args) |args| {
                            for (args.items(), 0..) |arg, i| {
                                if (i > 0) try self.write(", ");
                                try self.transpile_node(arg.*);
                            }
                        }
                        self.in_function_params = false;
                        try self.write(");\n");

                        if (fnv.is_async) {
                            const prev_override = self.override_fn_name;
                            self.override_fn_name = spec_name;
                            defer self.override_fn_name = prev_override;
                            try self.write_async_function_support_prototypes(m.*);
                        }
                    }
                }
            }
            return;
        }

        if (mem.indexOf(u8, im.type_name.items, "__") != null) {
            if (!(try self.concrete_impl_is_instantiated(im.type_name.items))) return;
        }

        for (im.methods.items()) |m| {
            if (m.type != .Function or m.node_variant == null) continue;
            const fnv = m.node_variant.?.function;
            if (fnv.type_params != null) continue;
            if (fnv.name == null) continue;
            const fname = fnv.name.?.items;

            if (emitted.contains(fname)) continue;
            emitted.put(fname, true) catch return TranspileError.MemoryAllocationFailed;

            if (fnv.rtype) |rt| {
                try self.write_return_type(rt);
            } else {
                try self.write("void");
            }
            try self.write(" ");
            try self.write(fname);
            try self.write("(");
            self.in_function_params = true;
            if (fnv.args) |args| {
                for (args.items(), 0..) |arg, i| {
                    if (i > 0) try self.write(", ");
                    try self.transpile_node(arg.*);
                }
            }
            self.in_function_params = false;
            try self.write(");\n");

            // An ASYNC quirk method's own payload-struct/helper prototypes
            // are already emitted by a separate, quirk-specific mechanism
            // (see `emit_quirk_impl_instance`) -- this whole loop only
            // started reaching quirk impls at all for the plain prototype
            // LINE just above (see this function's own doc comment on
            // exactly this branch), and duplicating the async support
            // prototypes here too produced a real "redefinition of
            // __fun_async_payload_..." C error, confirmed via the existing
            // test suite.
            if (fnv.is_async and im.quirk_name == null) {
                const prev_override = self.override_fn_name;
                self.override_fn_name = fname;
                defer self.override_fn_name = prev_override;
                try self.write_async_function_support_prototypes(m.*);
            }
        }
    }

    fn emit_plain_impl_method_prototypes_module(self: *Self, proc: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        const prev_alias = self.import_alias;
        const prev_aliases_override = self.import_aliases_override;
        const prev_emit_input_file_path = self.emit_input_file_path;
        const prev_emit_module_proc = self.emit_module_proc;
        self.import_alias = proc.import_alias;
        self.import_aliases_override = &proc.import_aliases;
        self.emit_input_file_path = proc.input_file_path;
        self.emit_module_proc = proc;
        defer {
            self.import_alias = prev_alias;
            self.import_aliases_override = prev_aliases_override;
            self.emit_input_file_path = prev_emit_input_file_path;
            self.emit_module_proc = prev_emit_module_proc;
        }

        for (proc.nodes.items()) |*n| {
            try self.emit_plain_impl_method_prototypes_from_node(n, emitted);
        }
        for (proc.owned_nodes.items) |n| {
            try self.emit_plain_impl_method_prototypes_from_node(n, emitted);
        }

        for (proc.children.items) |child| {
            try self.emit_plain_impl_method_prototypes_module(child, emitted);
        }
    }

    fn emit_plain_impl_methods_registry(self: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        const reg = self.root_registry() orelse return;
        var it = reg.impls_by_key.iterator();
        while (it.next()) |entry| {
            const impl_node = entry.value_ptr.*;
            const prev_aliases_override = self.import_aliases_override;
            if (impl_node.pos) |p| {
                const root = self.get_root();
                if (root.find_process_for_file(p.filename)) |proc| {
                    self.import_aliases_override = &proc.import_aliases;
                }
            }
            defer self.import_aliases_override = prev_aliases_override;
            try self.emit_plain_impl_methods_from_node(impl_node, emitted);
        }
    }

    fn emit_generic_compound_specializations(self: *Self, cnode: *ast.Node) TranspileError!void {
        const c = cnode.node_variant.?.compound;
        const params = c.type_params orelse return;

        var inst_keys = std.StringHashMap(bool).init(self.allocator);
        defer {
            var it = inst_keys.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
            }
            inst_keys.deinit();
        }

        var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
        defer inst_list.deinit();

        try self.collect_generic_instantiations_recursive(self, c.name.items, &inst_keys, &inst_list);

        for (inst_list.items) |dt| {
            if (dt.generic_args == null) continue;
            const gargs = dt.generic_args.?.items();
            if (gargs.len != params.count) continue;
            if (!self.generic_args_are_concrete(&params, gargs)) continue;
            if (self.dtype_contains_type_param(dt, &params)) continue;

            const mangled = try self.type_name_mangled(dt);
            defer self.allocator.free(mangled);
            if (self.mangled_contains_type_param(mangled, &params)) continue;
            if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

            try self.emit_generic_compound_specialization(cnode, dt);
        }
    }

    fn emit_generic_compound_specialization(self: *Self, cnode: *ast.Node, dt: *const dtype.DataType) TranspileError!void {
        const c = cnode.node_variant.?.compound;
        const params = c.type_params orelse return;
        const gargs = dt.generic_args orelse return;

        const mangled = try self.type_name_mangled(dt);
        defer self.allocator.free(mangled);

        try self.write("typedef struct ");
        try self.write(mangled);
        try self.write(" {\n");

        for (c.fields.items()) |f| {
            try self.write("  ");
            const is_fixed_array = f.dtype.array != null and !f.dtype.array.?.brackets.is_empty();
            if (is_fixed_array) {
                // Fixed-size array field in a GENERIC compound (`T[3] items;`):
                // emit an INLINE C array (`int64_t items[3];`) after substituting
                // the type param, so the storage lives in the struct. Mirrors the
                // non-generic compound fix; the generic path had been left demoting
                // every array field to a pointer (wrong layout/sizeof, dangling) —
                // a silent miscompile / crash on `T[N]` generic fields.
                var base = f.dtype.*;
                if (base.flags) |*flags| flags.is_array = false;
                base.array = null;
                base.array_depth = 0;
                try self.write_type_with_subst(&base, params, gargs.items());
                try self.write(" ");
                try self.write(f.name.items);
                try self.write_type_array_suffix(f.dtype);
            } else if (f.dtype.flags != null and f.dtype.flags.?.is_array) {
                // Unsized array field (`T[] items;`): no concrete extent -> pointer.
                var field_dt = f.dtype.*;
                if (field_dt.flags) |*flags| flags.is_array = false;
                if (field_dt.pointer_depth == 0) field_dt.pointer_depth = 1;
                try self.write_type_with_subst(&field_dt, params, gargs.items());
                try self.write(" ");
                try self.write(f.name.items);
            } else {
                try self.write_type_with_subst(f.dtype, params, gargs.items());
                try self.write(" ");
                try self.write(f.name.items);
            }
            try self.write(";\n");
        }

        try self.write("} ");
        try self.write(mangled);
        try self.write(";\n\n");
    }

    fn generic_spec_deps_satisfied(self: *Self, cnode: *ast.Node, dt: *const dtype.DataType, emitted: *std.StringHashMap(bool)) TranspileError!bool {
        const c = cnode.node_variant.?.compound;
        const params = c.type_params orelse return true;
        const gargs = dt.generic_args orelse return true;

        for (c.fields.items()) |f| {
            if (f.dtype.flags != null and f.dtype.flags.?.is_array) continue;
            if (f.dtype.pointer_depth != 0) continue;

            var dep_name: ?[]const u8 = null;
            var needs_free = false;

            if (f.dtype.generic_args != null) {
                dep_name = try self.type_name_mangled_with_subst(f.dtype, params, gargs.items());
                needs_free = true;
            } else if (f.dtype.type == .Unknown and f.dtype.type_str.items.len > 0) {
                const params_items = params.items();
                var matched_param = false;
                for (params_items, 0..) |p, i| {
                    if (!mem.eql(u8, p.items, f.dtype.type_str.items)) continue;
                    matched_param = true;
                    const arg_dt = gargs.items()[i];
                    if (arg_dt.pointer_depth != 0) break;
                    if (arg_dt.flags != null and arg_dt.flags.?.is_array) break;
                    if (arg_dt.type != .Unknown or arg_dt.type_str.items.len == 0) break;
                    if (arg_dt.generic_args != null) {
                        dep_name = try self.type_name_mangled(arg_dt);
                        needs_free = true;
                    } else {
                        dep_name = arg_dt.type_str.items;
                    }
                    break;
                }
                if (!matched_param) {
                    dep_name = f.dtype.type_str.items;
                }
            }

            if (dep_name) |dep| {
                defer if (needs_free) self.allocator.free(dep);
                const reg = self.root_registry() orelse return true;
                const dep_base = if (mem.indexOf(u8, dep, "__")) |idx| dep[0..idx] else dep;
                // A by-value field that is a compound OR a (generic) data-enum
                // instance must be fully emitted first. Other names (primitives,
                // plain enums that are emitted up front) impose no ordering.
                const is_compound_dep = reg.compounds_by_name.contains(dep_base);
                // A by-value enum dep is either a MANGLED generic instance (`Option__num`,
                // dep != dep_base) OR a non-generic tagged-union enum named directly
                // (`Json`, dep == dep_base) — the latter matters for RECURSIVE enums where
                // a spec embeds the enum by value. Plain (payload-free) enums emit up front
                // and impose no ordering.
                const is_enum_inst_dep = reg.enums_by_name.contains(dep_base) and
                    (!mem.eql(u8, dep, dep_base) or self.enum_name_is_tagged_union(dep_base));
                if (!is_compound_dep and !is_enum_inst_dep) continue;
                if (!emitted.contains(dep)) return false;
            }
        }

        return true;
    }

    /// Like `generic_spec_deps_satisfied` but for a generic data-enum instance:
    /// true once every BY-VALUE payload type that is a compound or another data-enum
    /// instance has been emitted (tracked in `emitted`). Pointer payloads and
    /// primitives impose no ordering.
    fn generic_enum_spec_deps_satisfied(self: *Self, enode: *ast.Node, dt: *const dtype.DataType, emitted: *std.StringHashMap(bool)) bool {
        const e = enode.node_variant.?.enum_decl;
        const params = e.type_params orelse return true;
        const gargs = dt.generic_args orelse return true;
        const reg = self.root_registry() orelse return true;
        for (e.variants.items()) |v| {
            const payload = v.payload orelse continue;
            for (payload.items()) |pt| {
                if (pt.pointer_depth != 0) continue; // pointer: incomplete type is fine
                if (pt.flags != null and pt.flags.?.is_array) continue;
                if (pt.type != null and pt.type != .Unknown) continue;
                if (pt.type_str.items.len == 0) continue;
                // Resolve the payload type after substituting the enum's type params.
                var dep_name: ?[]const u8 = null;
                var needs_free = false;
                if (pt.generic_args != null) {
                    dep_name = self.type_name_mangled_with_subst(pt, params, gargs.items()) catch return true;
                    needs_free = true;
                } else {
                    // Maybe the payload IS a type param -> map to the concrete arg.
                    var matched = false;
                    for (params.items(), 0..) |p, i| {
                        if (!mem.eql(u8, p.items, pt.type_str.items)) continue;
                        matched = true;
                        const arg = gargs.items()[i];
                        if (arg.pointer_depth != 0 or (arg.flags != null and arg.flags.?.is_array)) break;
                        if (arg.type != null and arg.type != .Unknown) break;
                        if (arg.type_str.items.len == 0) break;
                        dep_name = if (arg.generic_args != null) blk: {
                            needs_free = true;
                            break :blk self.type_name_mangled(arg) catch return true;
                        } else arg.type_str.items;
                        break;
                    }
                    if (!matched) dep_name = pt.type_str.items;
                }
                if (dep_name) |dep| {
                    defer if (needs_free) self.allocator.free(dep);
                    const dep_base = if (mem.indexOf(u8, dep, "__")) |idx| dep[0..idx] else dep;
                    const is_compound = reg.compounds_by_name.contains(dep_base);
                    // See generic_spec_deps_satisfied: accept a directly-named non-generic
                    // tagged-union enum (recursive-enum by-value payload) as a dep too.
                    const is_enum_inst = reg.enums_by_name.contains(dep_base) and
                        (!mem.eql(u8, dep, dep_base) or self.enum_name_is_tagged_union(dep_base));
                    if (!is_compound and !is_enum_inst) continue;
                    if (!emitted.contains(dep)) return false;
                }
            }
        }
        return true;
    }

    /// True once every BY-VALUE payload type of a NON-GENERIC data enum has been emitted
    /// (tracked in `emitted`). Pointer/array payloads impose no ordering — which is why a
    /// recursive `Json { Arr(Vec<Json>) }` resolves: `Vec<Json>`'s only Json reference is
    /// `Json* data` (a pointer), so `Vec__Json` emits with just Json's forward decl, then
    /// satisfies this check for `Json` itself.
    fn nongeneric_enum_deps_satisfied(self: *Self, e: anytype, emitted: *std.StringHashMap(bool)) bool {
        const reg = self.root_registry() orelse return true;
        for (e.variants.items()) |v| {
            const payload = v.payload orelse continue;
            for (payload.items()) |pt| {
                if (pt.pointer_depth != 0) continue;
                if (pt.flags != null and pt.flags.?.is_array) continue;
                if (pt.type != null and pt.type != .Unknown) continue;
                if (pt.type_str.items.len == 0) continue;
                var needs_free = false;
                const dep = if (pt.generic_args != null) blk: {
                    needs_free = true;
                    break :blk self.type_name_mangled(pt) catch return true;
                } else pt.type_str.items;
                defer if (needs_free) self.allocator.free(dep);
                const dep_base = if (mem.indexOf(u8, dep, "__")) |idx| dep[0..idx] else dep;
                const is_compound = reg.compounds_by_name.contains(dep_base);
                // A directly-named non-generic data enum payload (mutual recursion between
                // two data enums) or a generic enum/compound instance is a real dep.
                const is_enum_dep = reg.enums_by_name.contains(dep_base) and
                    (!mem.eql(u8, dep, dep_base) or self.enum_name_is_tagged_union(dep_base));
                if (!is_compound and !is_enum_dep) continue;
                // A variant payload that is the enum ITSELF by value would be an infinite
                // size (illegal in C anyway); only pointer self-reference is valid, already
                // skipped above. So a self-named by-value dep can't be satisfied — but that
                // case doesn't arise for well-formed enums (Vec/Map wrap the recursion).
                if (!emitted.contains(dep)) return false;
            }
        }
        return true;
    }

    fn write_type_with_subst(self: *Self, dt: *const dtype.DataType, params: utils.Vector(ArrayList(u8)), args: []*dtype.DataType) TranspileError!void {
        var idx: ?usize = null;
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            for (params.items(), 0..) |p, i| {
                if (mem.eql(u8, p.items, dt.type_str.items)) {
                    idx = i;
                    break;
                }
            }
        }

        if (idx != null) {
            var sub = args[idx.?].*;
            if (dt.pointer_depth > 0) {
                var flags = sub.flags orelse dtype.DataTypeFlags{};
                flags.is_pointer = true;
                sub.flags = flags;
                sub.pointer_depth += dt.pointer_depth;
            }
            if ((dt.flags != null and dt.flags.?.is_array) or dt.array != null or dt.array_depth > 0) {
                var flags = sub.flags orelse dtype.DataTypeFlags{};
                flags.is_array = true;
                sub.flags = flags;
                if (dt.array != null) sub.array = dt.array;
                if (dt.array_depth > sub.array_depth) sub.array_depth = dt.array_depth;
            }
            try self.write_type_no_subst(sub);
            return;
        }

        if (dt.generic_args != null and (dt.type == null or dt.type == .Unknown)) {
            const mangled = try self.type_name_mangled_with_subst(dt, params, args);
            defer self.allocator.free(mangled);
            try self.write(mangled);
            const ptr_depth: usize = if (dt.pointer_depth > 0) dt.pointer_depth else blk: {
                if (dt.flags != null and dt.flags.?.is_pointer) break :blk 1;
                break :blk 0;
            };
            if (ptr_depth > 0) {
                var i: usize = 0;
                while (i < ptr_depth) : (i += 1) {
                    try self.write("*");
                }
            }
            return;
        }

        try self.write_type_no_subst(dt.*);
    }

    fn collect_generic_instantiations(self: *Self, proc: *Self, name: []const u8, keys: *std.StringHashMap(bool), out: *ArrayList(*const dtype.DataType)) TranspileError!void {
        for (proc.nodes.items()) |*node| {
            try self.collect_generic_instantiations_node(node, name, keys, out);
        }
        for (proc.owned_nodes.items) |node| {
            try self.collect_generic_instantiations_node(node, name, keys, out);
        }
    }

    fn collect_generic_instantiations_recursive(self: *Self, proc: *Self, name: []const u8, keys: *std.StringHashMap(bool), out: *ArrayList(*const dtype.DataType)) TranspileError!void {
        try self.collect_generic_instantiations(proc, name, keys, out);
        for (proc.children.items) |child| {
            try self.collect_generic_instantiations_recursive(child, name, keys, out);
        }

        const root = self.get_root();
        for (root.forced_generic_instantiations.items) |dt| {
            if (dt.type_str.items.len == 0) continue;
            if (@intFromPtr(dt.type_str.items.ptr) == 0) continue;
            const dt_base = if (mem.indexOf(u8, dt.type_str.items, "__")) |idx| dt.type_str.items[0..idx] else dt.type_str.items;
            if (!mem.eql(u8, dt_base, name)) continue;
            if (self.dtype_has_unresolved_placeholder(dt)) continue;

            const key = try self.type_name_mangled(dt);
            if (self.mangled_contains_unresolved_placeholder(key)) {
                self.allocator.free(key);
                continue;
            }
            if (!keys.contains(key)) {
                keys.put(key, true) catch return TranspileError.MemoryAllocationFailed;
                out.append(dt) catch return TranspileError.MemoryAllocationFailed;
            } else {
                self.allocator.free(key);
            }
        }

        // Monomorphized generic FUNCTIONS reference a generic enum only through the
        // template's type params (e.g. `wrap<T>() RecvResult<T>` instantiated at
        // `T = num` needs `RecvResult__num`). The template node still says
        // `RecvResult<T>`, so the concrete `RecvResult<num>` is invisible to the
        // node scan above. Substitute each instantiation's params->args into its
        // return type and argument types so the concrete enum instance is collected.
        for (root.generic_fn_instantiations.items) |inst| {
            const fnv = inst.fn_node.node_variant.?.function;
            if (fnv.rtype) |*rt| {
                const sub = self.clone_dtype_with_subst_for_inst(rt, inst.params, inst.args) catch null;
                if (sub) |s| try self.collect_generic_instantiations_dtype(s, name, keys, out);
            }
            if (fnv.args) |fargs| {
                for (fargs.items()) |a| {
                    if (a.node_variant) |av| {
                        const sub = self.clone_dtype_with_subst_for_inst(av.variable.type, inst.params, inst.args) catch null;
                        if (sub) |s| try self.collect_generic_instantiations_dtype(s, name, keys, out);
                    }
                }
            }
        }
    }

    fn concrete_impl_is_instantiated(self: *Self, type_name: []const u8) TranspileError!bool {
        const idx_opt = mem.indexOf(u8, type_name, "__") orelse return true;
        const base = type_name[0..idx_opt];
        if (self.mangled_contains_unresolved_placeholder(type_name)) return false;

        var inst_keys = std.StringHashMap(bool).init(self.allocator);
        defer {
            var it = inst_keys.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
            }
            inst_keys.deinit();
        }

        var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
        defer inst_list.deinit();

        try self.collect_generic_instantiations_recursive(self, base, &inst_keys, &inst_list);

        for (inst_list.items) |dt| {
            if (self.dtype_has_unresolved_placeholder(dt)) continue;
            const mangled = try self.type_name_mangled(dt);
            defer self.allocator.free(mangled);
            if (self.mangled_contains_unresolved_placeholder(mangled)) continue;
            if (mem.eql(u8, mangled, type_name)) return true;
        }
        return false;
    }

    fn collect_generic_instantiations_node(self: *Self, node: *const ast.Node, name: []const u8, keys: *std.StringHashMap(bool), out: *ArrayList(*const dtype.DataType)) TranspileError!void {
        switch (node.type) {
            .Variable => if (node.node_variant) |*v| try self.collect_generic_instantiations_dtype(v.variable.type, name, keys, out),
            .Function => if (node.node_variant) |*f| {
                if (f.function.rtype) |*rt| try self.collect_generic_instantiations_dtype(rt, name, keys, out);
                if (f.function.args) |args| {
                    for (args.items()) |a| {
                        if (a.node_variant) |av| {
                            try self.collect_generic_instantiations_dtype(av.variable.type, name, keys, out);
                        }
                    }
                }
                if (f.function.body) |body| {
                    try self.collect_generic_instantiations_in_body(body, name, keys, out);
                }
            },
            .Compound => if (node.node_variant) |*c| {
                for (c.compound.fields.items()) |f| {
                    try self.collect_generic_instantiations_dtype(f.dtype, name, keys, out);
                }
            },
            .Enum => if (node.node_variant) |*en| {
                // Scan data-enum variant payload types so a payload that is itself a
                // generic instance (`Branch(Box<num>)`, nested `Result<Option<T>,E>`)
                // is discovered for monomorphization.
                for (en.enum_decl.variants.items()) |v| {
                    if (v.payload) |payload| {
                        for (payload.items()) |pt| {
                            try self.collect_generic_instantiations_dtype(pt, name, keys, out);
                        }
                    }
                }
            },
            .Body => if (node.node_variant) |*b| {
                const body_node = ast.Node{ .type = .Body, .node_variant = .{ .body = b.body } };
                try self.collect_generic_instantiations_in_body(&body_node, name, keys, out);
            },
            else => {},
        }
    }

    fn collect_generic_instantiations_in_body(self: *Self, body: *const ast.Node, name: []const u8, keys: *std.StringHashMap(bool), out: *ArrayList(*const dtype.DataType)) TranspileError!void {
        if (body.type != .Body or body.node_variant == null) return;
        const stmts = body.node_variant.?.body.statements;
        for (stmts.items()) |stmt_ptr| {
            const stmt = stmt_ptr.*;
            switch (stmt.type) {
                .Variable => {
                    const v = stmt.node_variant.?.variable;
                    try self.collect_generic_instantiations_dtype(v.type, name, keys, out);
                },
                .StatementIf => {
                    const ifs = stmt.node_variant.?.statement.if_stmt;
                    try self.collect_generic_instantiations_in_body(ifs.body, name, keys, out);
                },
                .StatementElseIf => {
                    const elif = stmt.node_variant.?.statement.elif_stmt;
                    try self.collect_generic_instantiations_in_body(elif.body, name, keys, out);
                },
                .StatementElse => {
                    const els = stmt.node_variant.?.statement.else_stmt;
                    try self.collect_generic_instantiations_in_body(els.body, name, keys, out);
                },
                .StatementFit => {
                    const fit = stmt.node_variant.?.statement.fit_stmt;
                    for (fit.branches.items()) |br| {
                        try self.collect_generic_instantiations_in_body(br.body, name, keys, out);
                    }
                },
                .StatementFor => {
                    const f = stmt.node_variant.?.statement.for_stmt;
                    switch (f) {
                        .cond => |fc| try self.collect_generic_instantiations_in_body(fc.body, name, keys, out),
                        .iter => |fi| try self.collect_generic_instantiations_in_body(fi.body, name, keys, out),
                        .range => |fr| try self.collect_generic_instantiations_in_body(fr.body, name, keys, out),
                    }
                },
                else => {},
            }
        }
    }

    fn collect_generic_instantiations_dtype(self: *Self, dt: *const dtype.DataType, name: []const u8, keys: *std.StringHashMap(bool), out: *ArrayList(*const dtype.DataType)) TranspileError!void {
        if (dt.type_str.items.len > 0 and @intFromPtr(dt.type_str.items.ptr) == 0) return;
        if (dt.type_str.items.len > 0) {
            const dt_base = if (mem.indexOf(u8, dt.type_str.items, "__")) |idx| dt.type_str.items[0..idx] else dt.type_str.items;
            if (!mem.eql(u8, dt_base, name)) {
                if (dt.generic_args) |gargs| {
                    for (gargs.items()) |ga| {
                        try self.collect_generic_instantiations_dtype(ga, name, keys, out);
                    }
                }
                return;
            }
        }
        if (dt.type_str.items.len > 0) {
            if (dt.generic_args != null) {
                if (self.dtype_has_unresolved_placeholder(dt)) return;
                const key = try self.type_name_mangled(dt);
                if (self.mangled_contains_unresolved_placeholder(key)) {
                    self.allocator.free(key);
                    return;
                }
                if (!keys.contains(key)) {
                    keys.put(key, true) catch return TranspileError.MemoryAllocationFailed;
                    out.append(dt) catch return TranspileError.MemoryAllocationFailed;
                } else {
                    self.allocator.free(key);
                }
            } else if (mem.indexOf(u8, dt.type_str.items, "__") != null) {
                if (try self.dtype_from_mangled_type(dt.type_str.items)) |synthetic| {
                    if (!self.dtype_has_unresolved_placeholder(synthetic)) {
                        const key = try self.type_name_mangled(synthetic);
                        if (!keys.contains(key)) {
                            keys.put(key, true) catch return TranspileError.MemoryAllocationFailed;
                            out.append(synthetic) catch return TranspileError.MemoryAllocationFailed;
                        } else {
                            self.allocator.free(key);
                        }
                    }
                }
            }
        }

        if (dt.generic_args) |gargs| {
            for (gargs.items()) |ga| {
                try self.collect_generic_instantiations_dtype(ga, name, keys, out);
            }
        }
    }

    fn clone_dtype_with_subst_for_inst(self: *Self, dt: *const dtype.DataType, params: *const utils.Vector(ArrayList(u8)), args: []*dtype.DataType) TranspileError!*dtype.DataType {
        if ((dt.type == null or dt.type == .Unknown) and dt.type_str.items.len > 0) {
            for (params.items(), 0..) |p, i| {
                if (!mem.eql(u8, p.items, dt.type_str.items)) continue;
                const out = try self.clone_dtype(args[i]);
                if (dt.pointer_depth > 0) {
                    var flags = out.flags orelse dtype.DataTypeFlags{};
                    flags.is_pointer = true;
                    out.flags = flags;
                    out.pointer_depth += dt.pointer_depth;
                }
                if (dt.flags != null and dt.flags.?.is_array) {
                    var flags = out.flags orelse dtype.DataTypeFlags{};
                    flags.is_array = true;
                    out.flags = flags;
                }
                return out;
            }
        }

        if (dt.array != null) return TranspileError.TypeMismatch;

        const out = self.allocator.create(dtype.DataType) catch return TranspileError.MemoryAllocationFailed;
        out.* = dt.*;
        out.type_str = ArrayList(u8).init(self.allocator);
        out.type_str.appendSlice(dt.type_str.items) catch return TranspileError.MemoryAllocationFailed;
        out.generic_args = null;

        if (dt.generic_args) |gargs| {
            var out_args = utils.Vector(*dtype.DataType).init(self.allocator);
            for (gargs.items()) |ga| {
                const ga_sub = try self.clone_dtype_with_subst_for_inst(ga, params, args);
                out_args.push(ga_sub) catch return TranspileError.MemoryAllocationFailed;
            }
            out.generic_args = out_args;
        }

        return out;
    }

    fn seed_forced_generic_instantiations_from_impl_signatures_node(self: *Self, n: *ast.Node) TranspileError!void {
        if (n.type != .Impl or n.node_variant == null) return;
        const im = n.node_variant.?.impl;
        const params = self.impl_type_params(n) orelse return;

        var inst_keys = std.StringHashMap(bool).init(self.allocator);
        defer {
            var it = inst_keys.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
            }
            inst_keys.deinit();
        }

        var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
        defer inst_list.deinit();
        const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
        try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);

        for (inst_list.items) |dt| {
            if (dt.generic_args == null) continue;
            const gargs = dt.generic_args.?.items();
            if (gargs.len != params.count) continue;
            if (!self.generic_args_are_concrete(params, gargs)) continue;
            if (self.dtype_contains_type_param(dt, params)) continue;

            const mangled = try self.type_name_mangled(dt);
            defer self.allocator.free(mangled);
            if (self.mangled_contains_type_param(mangled, params)) continue;
            if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;

                if (fnv.rtype) |rt| {
                    const rt_sub = try self.clone_dtype_with_subst_for_inst(&rt, params, gargs);
                    if (!self.dtype_has_unresolved_placeholder(rt_sub)) {
                        try self.register_generic_instantiations_from_dtype(rt_sub);
                    }
                }

                if (fnv.args) |args_nodes| {
                    for (args_nodes.items()) |arg| {
                        if (arg.type != .Variable or arg.node_variant == null) continue;
                        const adt = arg.node_variant.?.variable.type;
                        const adt_sub = try self.clone_dtype_with_subst_for_inst(adt, params, gargs);
                        if (!self.dtype_has_unresolved_placeholder(adt_sub)) {
                            try self.register_generic_instantiations_from_dtype(adt_sub);
                        }
                    }
                }
            }
        }
    }

    fn seed_forced_generic_instantiations_from_impl_signatures_module(self: *Self, proc: *Self) TranspileError!void {
        for (proc.nodes.items()) |*n| {
            try self.seed_forced_generic_instantiations_from_impl_signatures_node(n);
        }
        for (proc.owned_nodes.items) |n| {
            try self.seed_forced_generic_instantiations_from_impl_signatures_node(n);
        }

        for (proc.children.items) |child| {
            try self.seed_forced_generic_instantiations_from_impl_signatures_module(child);
        }
    }

    fn seed_forced_generic_instantiations_from_impl_signatures(self: *Self) TranspileError!void {
        try self.seed_forced_generic_instantiations_from_impl_signatures_module(self.get_root());
    }

    /// Mirrors `seed_forced_generic_instantiations_from_impl_signatures_node`'s
    /// discovery of concrete instantiations of a generic impl (`Box<num>` for
    /// `impl Box<T>`), but instead of registering the METHOD's own return/arg
    /// types, it treats each `(concrete instantiation, method)` pair as an
    /// implicit `GenericFnInstantiation` and hands it to
    /// `resolve_transitive_generic_fn_instantiations` -- the same worklist-seeding
    /// helper written for a generic FREE function calling a different generic
    /// free function. That helper only needs `.fn_node`/`.params`/`.args` (the
    /// synthesized `.name` is never read), and already scopes its substitution
    /// by `owner_fn` IDENTITY, so it works unmodified for a method's own node
    /// standing in as the "owner" of any placeholder calls found inside it.
    fn seed_generic_impl_method_transitive_fn_instantiations_node(self: *Self, n: *ast.Node) TranspileError!void {
        if (n.type != .Impl or n.node_variant == null) return;
        const im = n.node_variant.?.impl;
        const params = self.impl_type_params(n) orelse return;

        var inst_keys = std.StringHashMap(bool).init(self.allocator);
        defer {
            var it = inst_keys.iterator();
            while (it.next()) |e| {
                self.allocator.free(e.key_ptr.*);
            }
            inst_keys.deinit();
        }

        var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
        defer inst_list.deinit();
        const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
        try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);

        for (inst_list.items) |dt| {
            if (dt.generic_args == null) continue;
            const gargs = dt.generic_args.?.items();
            if (gargs.len != params.count) continue;
            if (!self.generic_args_are_concrete(params, gargs)) continue;
            if (self.dtype_contains_type_param(dt, params)) continue;

            const mangled = try self.type_name_mangled(dt);
            defer self.allocator.free(mangled);
            if (self.mangled_contains_type_param(mangled, params)) continue;
            if (self.mangled_contains_unresolved_placeholder(mangled)) continue;

            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const synthetic_inst = GenericFnInstantiation{ .fn_node = m, .params = params, .args = gargs, .name = "" };
                try self.resolve_transitive_generic_fn_instantiations(synthetic_inst);
            }
        }
    }

    fn seed_generic_impl_method_transitive_fn_instantiations_module(self: *Self, proc: *Self) TranspileError!void {
        for (proc.nodes.items()) |*n| {
            try self.seed_generic_impl_method_transitive_fn_instantiations_node(n);
        }
        for (proc.owned_nodes.items) |n| {
            try self.seed_generic_impl_method_transitive_fn_instantiations_node(n);
        }

        for (proc.children.items) |child| {
            try self.seed_generic_impl_method_transitive_fn_instantiations_module(child);
        }
    }

    fn seed_generic_impl_method_transitive_fn_instantiations(self: *Self) TranspileError!void {
        try self.seed_generic_impl_method_transitive_fn_instantiations_module(self.get_root());
    }

    /// For each impl with `type_param_forced_insts` (from constrained type params such as
    /// `impl Vec<T: num | dec>`), register the concrete specializations as forced generic
    /// instantiations so that all methods are emitted even if those types are never
    /// explicitly referenced in user code.
    fn seed_constrained_impl_instantiations_node(self: *Self, n: *ast.Node) TranspileError!void {
        if (n.type != .Impl or n.node_variant == null) return;
        const im = &n.node_variant.?.impl;
        const forced_insts = im.type_param_forced_insts orelse return;
        const params = im.type_params orelse return;

        const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx|
            im.type_name.items[0..idx]
        else
            im.type_name.items;

        for (forced_insts.items()) |inst| {
            if (inst.items().len != params.count) continue;

            // Build the mangled name (e.g. "Vec__num") so we can round-trip through
            // dtype_from_mangled_type, which correctly reconstructs the generic_args tree.
            var mangled = ArrayList(u8).init(self.allocator);
            defer mangled.deinit();
            mangled.appendSlice(base_name) catch return TranspileError.MemoryAllocationFailed;
            for (inst.items()) |t| {
                mangled.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
                mangled.appendSlice(t.items) catch return TranspileError.MemoryAllocationFailed;
            }

            const synthetic = (try self.dtype_from_mangled_type(mangled.items)) orelse continue;
            defer {
                if (synthetic.generic_args) |*gargs| {
                    for (gargs.items()) |ga| {
                        ga.type_str.deinit();
                        self.allocator.destroy(ga);
                    }
                    gargs.deinit();
                }
                synthetic.type_str.deinit();
                self.allocator.destroy(synthetic);
            }
            try self.register_generic_instantiation(synthetic);
        }
    }

    fn seed_constrained_impl_instantiations_module(self: *Self, proc: *Self) TranspileError!void {
        for (proc.nodes.items()) |*n| {
            try self.seed_constrained_impl_instantiations_node(n);
        }
        for (proc.owned_nodes.items) |n| {
            try self.seed_constrained_impl_instantiations_node(n);
        }
        for (proc.children.items) |child| {
            try self.seed_constrained_impl_instantiations_module(child);
        }
    }

    fn seed_constrained_impl_instantiations(self: *Self) TranspileError!void {
        try self.seed_constrained_impl_instantiations_module(self.get_root());
    }

    fn checked_type_matches_constraint_name(t: CheckedType, expected: []const u8) bool {
        const normalized = normalize_builtin_named_checked_type(t);
        if (normalized.base != .Unknown) {
            return switch (normalized.base) {
                .Num => mem.eql(u8, expected, "num"),
                .Dec => mem.eql(u8, expected, "dec"),
                .Str => mem.eql(u8, expected, "str"),
                .Chr => mem.eql(u8, expected, "chr"),
                .Bin => mem.eql(u8, expected, "bin"),
                .Raw => mem.eql(u8, expected, "raw"),
                .Void => mem.eql(u8, expected, "void"),
                else => false,
            };
        }

        if (normalized.mangled_name) |name| {
            if (mem.eql(u8, name, expected)) return true;
            const base = if (mem.indexOf(u8, name, "__")) |idx| name[0..idx] else name;
            if (mem.eql(u8, base, expected)) return true;
        }

        if (normalized.name) |name| {
            if (mem.eql(u8, name, expected)) return true;
            const base = if (mem.indexOf(u8, name, "__")) |idx| name[0..idx] else name;
            if (mem.eql(u8, base, expected)) return true;
        }

        return false;
    }

    fn generic_args_match_forced_inst(gargs: []*dtype.DataType, inst: *const utils.Vector(ArrayList(u8))) bool {
        const expected = inst.items();
        if (gargs.len != expected.len) return false;

        for (gargs, expected) |ga, want| {
            if (!checked_type_matches_constraint_name(type_from_dtype(ga), want.items)) return false;
        }
        return true;
    }

    fn impl_allows_generic_args(forced: ?utils.Vector(utils.Vector(ArrayList(u8))), gargs: []*dtype.DataType) bool {
        const insts = forced orelse return true;
        for (insts.items()) |*inst| {
            if (generic_args_match_forced_inst(gargs, inst)) return true;
        }
        return false;
    }

    fn emit_plain_impl_methods_from_node(self: *Self, n: *ast.Node, emitted: *std.StringHashMap(bool)) TranspileError!void {
        if (n.type != .Impl or n.node_variant == null) return;
        const im = n.node_variant.?.impl;
        if (im.quirk_name != null) return;
        if (self.mangled_contains_unresolved_placeholder(im.type_name.items)) return;

        if (self.impl_type_params(n)) |params| {
            var inst_keys = std.StringHashMap(bool).init(self.allocator);
            defer {
                var it = inst_keys.iterator();
                while (it.next()) |e| {
                    self.allocator.free(e.key_ptr.*);
                }
                inst_keys.deinit();
            }

            var inst_list = ArrayList(*const dtype.DataType).init(self.allocator);
            defer inst_list.deinit();
            const base_name = if (mem.indexOf(u8, im.type_name.items, "__")) |idx| im.type_name.items[0..idx] else im.type_name.items;
            try self.collect_generic_instantiations_recursive(self, base_name, &inst_keys, &inst_list);

            for (inst_list.items) |dt| {
                if (dt.generic_args == null) continue;
                const gargs = dt.generic_args.?.items();
                if (gargs.len != params.count) continue;
                if (self.dtype_contains_type_param(dt, params)) continue;
                if (!impl_allows_generic_args(im.type_param_forced_insts, gargs)) continue;

                const mangled = try self.type_name_mangled(dt);
                defer self.allocator.free(mangled);
                if (self.mangled_contains_type_param(mangled, params)) continue;

                for (im.methods.items()) |m| {
                    if (m.type != .Function or m.node_variant == null) continue;
                    const fnv = m.node_variant.?.function;
                    // See the matching skip in `emit_plain_impl_method_prototypes_from_node`.
                    if (fnv.type_params != null) continue;
                    if (fnv.body == null) continue;
                    if (fnv.name == null) continue;
                    const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                    const spec_name = std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ mangled, base }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };

                    const gop = emitted.getOrPut(spec_name) catch return TranspileError.MemoryAllocationFailed;
                    if (gop.found_existing) continue;
                    gop.value_ptr.* = true;

                    {
                        const prev_params = self.type_subst_params;
                        const prev_args = self.type_subst_args;
                        const prev_override = self.override_fn_name;
                        const prev_ret = self.current_method_return_dtype;
                        self.type_subst_params = params;
                        self.type_subst_args = gargs;
                        self.override_fn_name = spec_name;
                        self.current_method_return_dtype = if (fnv.rtype) |*rt| rt else null;
                        defer {
                            self.type_subst_params = prev_params;
                            self.type_subst_args = prev_args;
                            self.override_fn_name = prev_override;
                            self.current_method_return_dtype = prev_ret;
                        }

                        try self.transpile_node(m.*);
                    }
                    try self.write("\n\n");
                }
            }

            const root = self.get_root();
            var spec_it = root.emitted_generic_spec_keys.iterator();
            while (spec_it.next()) |entry| {
                const mangled_name = entry.key_ptr.*;
                const idx = mem.indexOf(u8, mangled_name, "__") orelse continue;
                const spec_base = mangled_name[0..idx];
                if (!mem.eql(u8, spec_base, base_name)) continue;
                if (self.mangled_contains_unresolved_placeholder(mangled_name)) continue;
                if (self.mangled_contains_type_param(mangled_name, params)) continue;
                const dt = (try self.dtype_from_mangled_type(mangled_name)) orelse continue;
                if (dt.generic_args == null) continue;
                const gargs = dt.generic_args.?.items();
                if (gargs.len != params.count) continue;
                if (self.dtype_contains_type_param(dt, params)) continue;
                if (!impl_allows_generic_args(im.type_param_forced_insts, gargs)) continue;

                for (im.methods.items()) |m| {
                    if (m.type != .Function or m.node_variant == null) continue;
                    const fnv = m.node_variant.?.function;
                    if (fnv.type_params != null) continue;
                    if (fnv.body == null) continue;
                    if (fnv.name == null) continue;
                    const base = base_method_name_from_generated(fnv.name.?.items) orelse continue;
                    const spec_name = std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ mangled_name, base }) catch {
                        return TranspileError.MemoryAllocationFailed;
                    };

                    const gop = emitted.getOrPut(spec_name) catch return TranspileError.MemoryAllocationFailed;
                    if (gop.found_existing) continue;
                    gop.value_ptr.* = true;

                    {
                        const prev_params = self.type_subst_params;
                        const prev_args = self.type_subst_args;
                        const prev_override = self.override_fn_name;
                        const prev_ret = self.current_method_return_dtype;
                        self.type_subst_params = params;
                        self.type_subst_args = gargs;
                        self.override_fn_name = spec_name;
                        self.current_method_return_dtype = if (fnv.rtype) |*rt| rt else null;
                        defer {
                            self.type_subst_params = prev_params;
                            self.type_subst_args = prev_args;
                            self.override_fn_name = prev_override;
                            self.current_method_return_dtype = prev_ret;
                        }

                        try self.transpile_node(m.*);
                    }
                    try self.write("\n\n");
                }
            }
            return;
        }

        if (mem.indexOf(u8, im.type_name.items, "__") != null) {
            if (!(try self.concrete_impl_is_instantiated(im.type_name.items))) return;
        }

        for (im.methods.items()) |m| {
            if (m.type != .Function or m.node_variant == null) continue;
            const fnv = m.node_variant.?.function;
            if (fnv.type_params != null) continue;
            if (fnv.body == null) continue;
            if (fnv.name == null) continue;
            const fname = fnv.name.?.items;
            if (emitted.contains(fname)) continue;
            emitted.put(fname, true) catch return TranspileError.MemoryAllocationFailed;
            const prev_override = self.override_fn_name;
            self.override_fn_name = fname;
            defer self.override_fn_name = prev_override;
            try self.transpile_node(m.*);
            try self.write("\n\n");
        }
    }

    fn emit_plain_impl_methods_module(self: *Self, proc: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        const prev_alias = self.import_alias;
        const prev_aliases_override = self.import_aliases_override;
        const prev_emit_input_file_path = self.emit_input_file_path;
        const prev_emit_module_proc = self.emit_module_proc;
        self.import_alias = proc.import_alias;
        self.import_aliases_override = &proc.import_aliases;
        self.emit_input_file_path = proc.input_file_path;
        self.emit_module_proc = proc;
        defer {
            self.import_alias = prev_alias;
            self.import_aliases_override = prev_aliases_override;
            self.emit_input_file_path = prev_emit_input_file_path;
            self.emit_module_proc = prev_emit_module_proc;
        }

        for (proc.nodes.items()) |*n| {
            try self.emit_plain_impl_methods_from_node(n, emitted);
        }
        for (proc.owned_nodes.items) |n| {
            try self.emit_plain_impl_methods_from_node(n, emitted);
        }

        for (proc.children.items) |child| {
            try self.emit_plain_impl_methods_module(child, emitted);
        }
    }

    fn emit_generic_function_specializations(self: *Self) TranspileError!void {
        const root = self.get_root();
        var emitted = std.StringHashMap(bool).init(self.allocator);
        defer emitted.deinit();

        // Index-based, re-reading `.items.len` every iteration: emitting one
        // instantiation's body can register further ones (a generic function
        // calling a DIFFERENT generic function -- see
        // `resolve_transitive_generic_fn_instantiations`), and those newly
        // appended entries must still be visited by this same pass.
        var i: usize = 0;
        while (i < root.generic_fn_instantiations.items.len) : (i += 1) {
            const inst = root.generic_fn_instantiations.items[i];
            if (self.mangled_contains_unresolved_placeholder(inst.name)) continue;
            if (emitted.contains(inst.name)) continue;
            emitted.put(inst.name, true) catch return TranspileError.MemoryAllocationFailed;

            {
                const prev_params = self.type_subst_params;
                const prev_args = self.type_subst_args;
                const prev_override = self.override_fn_name;
                const prev_ret = self.current_method_return_dtype;
                self.type_subst_params = inst.params;
                self.type_subst_args = inst.args;
                self.override_fn_name = inst.name;
                // Needed by `mangled_enum_with_active_subst`'s fallback: without
                // it, a method whose own type param (e.g. `wrap<U>(U x) Maybe<U>`)
                // appears in a constructed enum's type arg can wrongly resolve
                // via a coincidental NAME collision instead (e.g. `Maybe<T>`'s own
                // internal template param also happens to be called "T", same as
                // the enclosing impl's own T) -- see the fallback's own comment.
                const inst_fnv = if (inst.fn_node.node_variant) |nv| nv.function else null;
                self.current_method_return_dtype = if (inst_fnv) |fnv| (if (fnv.rtype) |*rt| rt else null) else null;
                defer {
                    self.type_subst_params = prev_params;
                    self.type_subst_args = prev_args;
                    self.override_fn_name = prev_override;
                    self.current_method_return_dtype = prev_ret;
                }

                try self.resolve_transitive_generic_fn_instantiations(inst);
                try self.transpile_node(inst.fn_node.*);
            }
            try self.write("\n\n");
        }
    }

    /// Transpiles all nodes in the AST to C code
    pub fn transpile(self: *Self) GeneralError!void {
        // The parser uses scopes only for parse-time identifier validation.
        // Transpilation needs its own scope for type-driven features (e.g. warnings).
        var did_init_scope = false;
        if (self.scope == null or self.scope.?.current == null) {
            _ = try self.init_root_scope();
            did_init_scope = true;
        }
        defer if (did_init_scope) self.deinit_root_scope();

        // Add source file name at the top of the output
        const source_file = std.fs.path.basename(self.input_file_path);
        try self.write("// Source file: ");
        try self.write(source_file);
        try self.write("\n");

        // Process import nodes first
        var import_nodes = ArrayList(usize).init(self.allocator);
        defer import_nodes.deinit();

        // Identify import nodes
        for (self.nodes.items(), 0..) |node, i| {
            if (node.type == .Import) {
                import_nodes.append(i) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
        }

        // Process the identified import nodes
        for (import_nodes.items) |i| {
            try self.process_import(self.nodes.items()[i]);
        }

        // Test-compile mode (`fun test file.fn`) implicitly needs the
        // concurrent test-runner module -- its `run_discovered_tests` is
        // called directly by `emit_test_mode_functions_and_runner` later,
        // so it must go through the SAME early import/typecheck/generic-
        // instantiation pipeline every other import does (rather than being
        // synthesized only at emission time, which would skip typechecking
        // it entirely). `!self.is_importing` keeps this to the root module
        // only -- test_mode is copied onto every child process too (see
        // `child_flags.test_mode` above), so without this guard every
        // ordinary import would ALSO try to pull this in.
        if (self.flags.test_mode and !self.is_importing) {
            const synthetic_testing_import = ast.Node{
                .type = .Import,
                .node_variant = .{ .import = .{ .path = "std.testing" } },
            };
            try self.process_import(synthetic_testing_import);
        }

        // Allow running entrypoint scripts that reference workspace-defined types
        // without explicitly importing their defining modules.
        // This is intentionally conservative: only auto-imports when a single
        // matching declaration is found.
        try self.auto_import_missing_user_types();

        // Imported modules share the same active scope pointers during codegen.
        // This avoids crashes when we transpile function nodes owned by child modules
        // (e.g. when emitting impl method bodies) without calling `child.transpile()`.
        const ScopeOpt = @TypeOf(self.scope);
        const binder = struct {
            fn bind(proc: *Self, shared: ScopeOpt) void {
                proc.scope = shared;
                for (proc.children.items) |child| {
                    bind(child, shared);
                }
            }
        };
        binder.bind(self, self.scope);

        // Collect user-defined type declarations across imports before typechecking.
        try self.collect_type_registry_all();

        if (self.parent == null) {
            try self.check_no_duplicate_private_function_names();
        }

        // Type check after imports are parsed (so imported signatures are available).
        try self.typecheck_all();

        // In diagnostics-only mode, skip C emission entirely.  Warnings/errors have
        // already been written to stderr by typecheck_all; we just need to verify
        // that any warning-expect annotations were fulfilled.
        if (self.flags.diag_only) {
            try self.finalize_warning_expectations();
            return;
        }

        // Seed generic instantiations from signatures/locals across all modules.
        try self.seed_forced_generic_instantiations_from_signatures();

        // Seed additional generic instantiations that appear only after substituting
        // generic impl method signatures (e.g. Map<K,V>::keys -> Vec<K>).
        try self.seed_forced_generic_instantiations_from_impl_signatures();

        // Seed forced instantiations from constrained impl type params
        // (e.g. `impl Vec<T: num | dec>` forces Vec<num> and Vec<dec>).
        try self.seed_constrained_impl_instantiations();

        // Detect `fork` usage across the whole module tree BEFORE the prelude is
        // emitted, so the scheduler runtime and wait-idle calls can be gated on it.
        if (uses_fork_recursive(self)) self.uses_fork = true;

        // Write standard library includes and prelude
        try self.transpile_prelude();

        // Emit user-defined types (compounds/quirks) once at the root.
        // NOTE: Impl method bodies/vtables are emitted later so the global function
        // prototype block can appear before any function bodies that might call
        // imported functions.
        if (!self.is_importing) {
            try self.emit_user_types();
        }

        // Re-seed impl signature instantiations after emitting user types so
        // field-driven generic specializations are visible to impl emission.
        try self.seed_forced_generic_instantiations_from_impl_signatures();
        try self.seed_constrained_impl_instantiations();

        // A generic impl method calling a DIFFERENT generic free function from
        // its own body (e.g. `identity(self.value)` inside `Box<T>.get()`) only
        // gets a placeholder instantiation registered at typecheck time
        // (`identity__T`) -- concrete impl methods are emitted through a
        // separate mechanism (`emit_plain_impl_methods_from_node`) that never
        // touches `generic_fn_instantiations` at all, so nothing ever resolves
        // that placeholder the way an ordinary generic-free-function caller
        // does. Must run before `emit_function_prototypes_all()` below so the
        // newly-registered concrete callee gets forward-declared in time.
        try self.seed_generic_impl_method_transitive_fn_instantiations();

        // Emit forward declarations for all functions so calls work even when
        // function bodies are declared later in the file.
        if (!self.is_importing) {
            try self.emit_function_prototypes_all();
        }

        // Emit forward declarations (`extern ...;`) for all top-level global
        // variables/constants, mirroring the function-prototype pass above --
        // unlike functions, a global's C definition previously had no
        // forward-declared form at all, so any earlier-emitted code (e.g. an
        // async function's lowered body, which is written out ahead of the
        // module's ordinary top-level declarations) referencing a global/const
        // declared later in program order hit a raw "undeclared identifier"
        // from the C compiler.
        if (!self.is_importing) {
            try self.emit_global_variable_prototypes_all();
        }

        // Emit impl method bodies/vtables/coercions after the prototype block.
        if (!self.is_importing) {
            try self.emit_impls_and_vtables();
        }

        // Emit generic function specializations after impls and before user code.
        if (!self.is_importing) {
            try self.emit_generic_function_specializations();
        }

        // Output content from child imports recursively
        if (!self.is_importing) {
            var seen_children = std.StringHashMap(?[]const u8).init(self.backing_allocator);
            defer seen_children.deinit();
            try self.transpile_children_recursive(self, &seen_children);
        }

        // Now output the main file content
        for (self.nodes.items()) |node| {
            if (node.type != .Import) { // Skip import nodes as they've been processed
                if (node.type == .Compound or node.type == .Quirk) continue;
                // `test`/`fuzz` blocks are handled separately below (only in
                // their own respective compile modes, via
                // `emit_test_mode_functions_and_runner`/
                // `emit_fuzz_mode_harness`) -- an ordinary compile ignores
                // both entirely.
                if (node.type == .Test) continue;
                if (node.type == .Fuzz) continue;
                if (node.type == .Function and node.node_variant != null) {
                    const function = node.node_variant.?.function;
                    if (function.type_params != null) continue;
                    if (self.function_has_unresolved_placeholder(node)) continue;
                    if (function.name) |fname| {
                        if (self.mangled_contains_unresolved_placeholder(fname.items)) continue;
                        // The generated test-runner `main` (below) replaces any
                        // user-defined `main` in test mode.
                        if (self.flags.test_mode and mem.eql(u8, fname.items, "main")) continue;
                        // Same reasoning in fuzz mode: the fuzzing engine's own
                        // driver supplies `main`, so a user-defined one would
                        // collide with it at link time.
                        if (self.flags.fuzz_mode and mem.eql(u8, fname.items, "main")) continue;
                    }
                }
                try self.transpile_node(node);
                try self.write("\n\n");
            }
        }

        if (self.flags.test_mode and !self.is_importing) {
            try self.emit_test_mode_functions_and_runner();
        }

        if (self.flags.fuzz_mode and !self.is_importing) {
            try self.emit_fuzz_mode_harness();
        }

        try self.finalize_warning_expectations();
    }

    /// Emits each `test "name" { ... }` block (from this module and any
    /// imported/child modules) as its own C function, plus two small
    /// bridge functions (`__fun_test_name`/`__fun_run_test`) that the
    /// concurrent runner (`std.testing`'s `run_discovered_tests`, force-
    /// imported for every test-mode compile -- see `transpile`) calls
    /// back into by index. `main` itself only resolves `argv[1]` (an
    /// optional per-test name filter, see below) into the matching
    /// subset, then hands off to the runner, which dispatches each
    /// matched test onto its own virtual task (`fork`) and reports
    /// results as they complete -- see std/testing.fn.
    ///
    /// A failing `assert` is recovered (not aborted) via a per-thread
    /// jump back into `__fun_run_test` instead (see
    /// `transpile_prelude`'s `__fun_test_jmp` doc comment and the
    /// `.assert_stmt` transpile case), so one failing test no longer
    /// prevents the rest of the suite from running.
    ///
    /// `argv[1]`, when present, filters to just the test(s) whose name
    /// matches EXACTLY -- lets an editor's per-test "Run"/"Debug" CodeLens
    /// (see editors/vscode/src/extension.ts's FunCodeLensProvider) execute
    /// one test instead of the whole file's suite, via the ordinary
    /// `fun test file.fn -- "name"` program-argument passthrough -- no
    /// separate CLI flag needed.
    fn emit_test_mode_functions_and_runner(self: *Self) TranspileError!void {
        const TestRef = struct { name: []const u8, body: *ast.Node };
        var tests = ArrayList(TestRef).init(self.allocator);
        defer tests.deinit();

        const Collector = struct {
            fn collect(proc: *Self, out: *ArrayList(TestRef)) TranspileError!void {
                for (proc.nodes.items()) |node| {
                    if (node.type != .Test or node.node_variant == null) continue;
                    const tv = node.node_variant.?.test_decl;
                    out.append(.{ .name = tv.name, .body = tv.body }) catch return TranspileError.MemoryAllocationFailed;
                }
                for (proc.children.items) |child| {
                    try collect(child, out);
                }
            }
        };
        try Collector.collect(self, &tests);

        if (tests.items.len == 0) {
            try self.write("int main(void) {\n  printf(\"no tests found\\n\");\n  return 0;\n}\n");
            return;
        }

        for (tests.items, 0..) |t, i| {
            self.reset_function_defer_state();
            const prev_in_fn_body = self.in_function_body;
            const prev_body_depth = self.function_body_depth;
            const prev_var = self.current_fn_is_variadic;
            const prev_fn_return = self.current_fn_return;
            self.in_function_body = true;
            self.function_body_depth = 0;
            self.current_fn_is_variadic = false;
            self.current_fn_return = .{ .base = .Void };
            defer {
                self.in_function_body = prev_in_fn_body;
                self.function_body_depth = prev_body_depth;
                self.current_fn_is_variadic = prev_var;
                self.current_fn_return = prev_fn_return;
            }

            try self.print("static void __fun_test_{d}(void) {{\n", .{i});
            try self.transpile_node(t.body.*);
            try self.write("\n}\n\n");
        }

        // Maps a MATCHED index (0..__fun_test_map_count, what the runner
        // sees) back to the REAL test index (what the switch statements
        // below dispatch on) -- built once in main() from the optional
        // name filter, then read (never written) concurrently by every
        // forked test task, so no synchronization is needed here.
        try self.print("static int __fun_test_map[{d}];\n", .{tests.items.len});
        try self.write("static int __fun_test_map_count = 0;\n\n");

        try self.write("static bool __fun_run_test(int64_t __i) {\n");
        try self.write("  if (setjmp(__fun_test_jmp)) { return false; }\n");
        try self.write("  switch (__fun_test_map[__i]) {\n");
        for (tests.items, 0..) |_, i| {
            try self.print("    case {d}: __fun_test_{d}(); break;\n", .{ i, i });
        }
        try self.write("  }\n");
        try self.write("  return true;\n");
        try self.write("}\n\n");

        try self.write("static char* __fun_test_name(int64_t __i) {\n");
        try self.write("  switch (__fun_test_map[__i]) {\n");
        for (tests.items, 0..) |t, i| {
            try self.print("    case {d}: return \"", .{i});
            try self.write_c_string_literal_body(t.name);
            try self.write("\";\n");
        }
        try self.write("  }\n");
        try self.write("  return \"\";\n");
        try self.write("}\n\n");

        try self.write("int main(int argc, char** argv) {\n");
        try self.write("  const char* filter = argc > 1 ? argv[1] : (const char*)0;\n");
        for (tests.items, 0..) |t, i| {
            try self.write("  if (!filter || strcmp(filter, \"");
            try self.write_c_string_literal_body(t.name);
            try self.print("\") == 0) {{ __fun_test_map[__fun_test_map_count] = {d}; __fun_test_map_count++; }}\n", .{i});
        }
        try self.write("  if (filter && __fun_test_map_count == 0) {\n");
        try self.write("    printf(\"no test named \\\"%s\\\" found\\n\", filter);\n");
        try self.write("    return 1;\n");
        try self.write("  }\n");
        try self.write("  return (int)run_discovered_tests((int64_t)__fun_test_map_count, __fun_test_name, __fun_run_test);\n");
        try self.write("}\n");
    }

    /// Emits exactly one `fuzz "name" (data, len) { ... }` block (selected
    /// by `fuzz_target`, or auto-selected when there's exactly one
    /// declared across this module and any imported/child modules) as a
    /// single harness function under the fixed ABI name a coverage-guided
    /// fuzzing engine's own driver looks for, replacing any user-defined
    /// `main` (see `transpile`'s own `.Fuzz`/main-skip logic -- the
    /// engine's driver supplies `main` itself). The two Fun-level
    /// parameter names (whatever the source chose) are locally aliased to
    /// the engine's own data-pointer/length arguments right at the top of
    /// the function body.
    ///
    /// Unlike `emit_test_mode_functions_and_runner`'s recovered-assert
    /// mechanism, a failing `assert` inside a fuzz body still aborts the
    /// process outright (`fuzz_mode` leaves `flags.test_mode` false, so
    /// the `.assert_stmt` transpile case takes its ordinary abort() path)
    /// -- that IS the point of fuzzing: the engine detects the crash and
    /// keeps the input that triggered it.
    fn emit_fuzz_mode_harness(self: *Self) TranspileError!void {
        const FuzzRef = struct { name: []const u8, data_param: *ast.Node, len_param: *ast.Node, body: *ast.Node };
        var targets = ArrayList(FuzzRef).init(self.allocator);
        defer targets.deinit();

        const Collector = struct {
            fn collect(proc: *Self, out: *ArrayList(FuzzRef)) TranspileError!void {
                for (proc.nodes.items()) |node| {
                    if (node.type != .Fuzz or node.node_variant == null) continue;
                    const fv = node.node_variant.?.fuzz_decl;
                    out.append(.{ .name = fv.name, .data_param = fv.data_param, .len_param = fv.len_param, .body = fv.body }) catch return TranspileError.MemoryAllocationFailed;
                }
                for (proc.children.items) |child| {
                    try collect(child, out);
                }
            }
        };
        try Collector.collect(self, &targets);

        if (targets.items.len == 0) {
            self.report_type_error(null, "no 'fuzz' target declared, fuzz mode needs at least one fuzz \"name\" (data, len) {{ ... }} block", .{});
            return TranspileError.TypeMismatch;
        }

        var chosen: ?FuzzRef = null;
        if (self.fuzz_target) |target_name| {
            for (targets.items) |t| {
                if (mem.eql(u8, t.name, target_name)) {
                    chosen = t;
                    break;
                }
            }
            if (chosen == null) {
                self.report_type_error(null, "no fuzz target named '{s}' found", .{target_name});
                return TranspileError.TypeMismatch;
            }
        } else if (targets.items.len == 1) {
            chosen = targets.items[0];
        } else {
            self.report_type_error(null, "multiple fuzz targets declared, specify which one to build", .{});
            return TranspileError.TypeMismatch;
        }

        const target = chosen.?;

        self.reset_function_defer_state();
        const prev_in_fn_body = self.in_function_body;
        const prev_body_depth = self.function_body_depth;
        const prev_var = self.current_fn_is_variadic;
        const prev_fn_return = self.current_fn_return;
        const prev_in_main = self.in_main;
        self.in_function_body = true;
        self.function_body_depth = 0;
        self.current_fn_is_variadic = false;
        self.current_fn_return = .{ .base = .Void };
        // Reuses the SAME mechanism a Fun-level `void main() { ... ret; }`
        // already needs for its own C `int main(void)` wrapper: a bare
        // `ret;` (no value -- the only form typecheck allows here, since
        // this body's context is void) must become C `return 0;`, not a
        // bare `return;`, or the emitted `int LLVMFuzzerTestOneInput(...)`
        // fails to compile ("non-void function should return a value").
        // `in_main` also happens to drain any forked tasks before
        // returning (`emit_fork_wait_idle_if_main`), which is exactly
        // right here too -- a fuzz body using `fork` shouldn't leave tasks
        // still running into the next input.
        self.in_main = true;
        defer {
            self.in_function_body = prev_in_fn_body;
            self.function_body_depth = prev_body_depth;
            self.current_fn_is_variadic = prev_var;
            self.current_fn_return = prev_fn_return;
            self.in_main = prev_in_main;
        }

        const data_name = target.data_param.node_variant.?.variable.name.items;
        const len_name = target.len_param.node_variant.?.variable.name.items;

        try self.write("int LLVMFuzzerTestOneInput(const unsigned char* __fun_fuzz_data, unsigned long __fun_fuzz_size) {\n");
        try self.print("  void* {s} = (void*)__fun_fuzz_data;\n", .{data_name});
        try self.print("  int64_t {s} = (int64_t)__fun_fuzz_size;\n", .{len_name});
        try self.transpile_node(target.body.*);
        try self.write("\n  return 0;\n}\n");
    }

    fn emit_function_prototypes_all(self: *Self) TranspileError!void {
        // Only the root module emits this block.
        if (self.is_importing) return;
        try self.write("\n// Function prototypes (allow out-of-order definitions)\n");
        var emitted = std.StringHashMap(bool).init(self.backing_allocator);
        defer {
            var it = emitted.iterator();
            while (it.next()) |e| {
                self.backing_allocator.free(e.key_ptr.*);
            }
            emitted.deinit();
        }
        try self.emit_function_prototypes_module(self, &emitted);
        try self.emit_generic_function_prototypes(&emitted);
        try self.write("\n");
    }

    fn emit_function_prototypes_module(self: *Self, proc: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        const prev_alias = self.import_alias;
        self.import_alias = proc.import_alias;
        defer self.import_alias = prev_alias;

        for (proc.nodes.items()) |node| {
            if (node.type != .Function or node.node_variant == null) continue;
            if (self.is_std_c_signature_node(&node)) continue;
            const function = node.node_variant.?.function;
            if (function.body == null) continue;
            if (function.type_params != null) continue;
            if (self.function_has_unresolved_placeholder(node)) continue;
            if (function.name != null and mem.eql(u8, function.name.?.items, "main")) continue;

            if (function.name) |fname| {
                var effective_name: []const u8 = fname.items;
                var effective_name_owned = false;
                if (proc.import_alias) |alias| {
                    effective_name = try self.make_alias_qualified_symbol_name(alias, fname.items);
                    effective_name_owned = true;
                }
                defer if (effective_name_owned) self.allocator.free(effective_name);

                if (self.mangled_contains_unresolved_placeholder(effective_name)) continue;
                if (emitted.contains(effective_name)) continue;
                const emitted_key = self.backing_allocator.dupe(u8, effective_name) catch return TranspileError.MemoryAllocationFailed;
                emitted.put(emitted_key, true) catch return TranspileError.MemoryAllocationFailed;
            }

            try self.write_function_prototype(node);
        }

        for (proc.children.items) |child| {
            try self.emit_function_prototypes_module(child, emitted);
        }
    }

    fn emit_global_variable_prototypes_all(self: *Self) TranspileError!void {
        // Only the root module emits this block.
        if (self.is_importing) return;
        try self.write("\n// Global variable/constant forward declarations (allow out-of-order references)\n");
        var emitted = std.StringHashMap(bool).init(self.backing_allocator);
        defer {
            var it = emitted.iterator();
            while (it.next()) |e| {
                self.backing_allocator.free(e.key_ptr.*);
            }
            emitted.deinit();
        }
        try self.emit_global_variable_prototypes_module(self, &emitted);
        try self.write("\n");
    }

    fn emit_global_variable_prototypes_module(self: *Self, proc: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        for (proc.nodes.items()) |node| {
            if (node.type != .Variable or node.node_variant == null) continue;
            const variable = node.node_variant.?.variable;
            const name = variable.name.items;

            if (emitted.contains(name)) continue;
            const emitted_key = self.backing_allocator.dupe(u8, name) catch return TranspileError.MemoryAllocationFailed;
            emitted.put(emitted_key, true) catch return TranspileError.MemoryAllocationFailed;

            try self.write_global_variable_prototype(node);
        }

        for (proc.children.items) |child| {
            try self.emit_global_variable_prototypes_module(child, emitted);
        }
    }

    /// Forward-declares a top-level global variable/constant (`extern ...;`),
    /// mirroring the const/pointer-placement and array-declarator logic in the
    /// `.Variable` case of `transpile_node` (see the comment there for why
    /// `const` lands after the pointer stars for a pointer-typed binding).
    fn write_global_variable_prototype(self: *Self, node: ast.Node) TranspileError!void {
        if (node.type != .Variable or node.node_variant == null) return;
        const variable = node.node_variant.?.variable;

        if (variable.type.fn_sig) |sig| {
            try self.write("extern ");
            try self.write_type(sig.rtype.*);
            try self.write(" (*");
            try self.write(variable.name.items);
            try self.write(")(");
            for (sig.params.items(), 0..) |p, i| {
                if (i > 0) try self.write(", ");
                try self.write_type(p.*);
            }
            try self.write(");\n");
            return;
        }

        const array_as_pointer = blk: {
            if (variable.type.flags == null or !variable.type.flags.?.is_array) break :blk false;
            const unsized = (variable.type.array == null or variable.type.array.?.brackets.is_empty()) and variable.type.array_depth <= 1;
            if (!unsized) break :blk false;
            const val = variable.val orelse break :blk false;
            break :blk val.type != .Bracket;
        };

        const is_ptr_binding = variable.type.pointer_depth > 0 or
            (variable.type.flags != null and variable.type.flags.?.is_pointer) or
            array_as_pointer;

        try self.write("extern ");
        if (variable.is_const and !is_ptr_binding) try self.write("const ");
        try self.write_type(variable.type.*);
        if (array_as_pointer) try self.write("*");
        if (variable.is_const and is_ptr_binding) try self.write(" const");
        try self.write(" ");
        try self.write(variable.name.items);

        if (!array_as_pointer and variable.type.flags != null and variable.type.flags.?.is_array) {
            if (variable.type.array) |array| {
                if (!array.brackets.is_empty()) {
                    for (array.brackets.items()) |bracket_node| {
                        try self.write("[");
                        if (bracket_node.type == .Bracket) {
                            try self.transpile_node(bracket_node.node_variant.?.bracket.inner.*);
                        } else {
                            try self.transpile_node(bracket_node);
                        }
                        try self.write("]");
                    }
                } else {
                    try self.write("[]");
                }
            } else if (variable.type.array_depth > 1) {
                try self.write("[]");
                if (variable.val) |val| {
                    if (val.type == .Bracket) {
                        try self.emit_multidim_inner_declarators(val, variable.type.array_depth - 1);
                    } else {
                        var d: usize = 1;
                        while (d < variable.type.array_depth) : (d += 1) try self.write("[]");
                    }
                } else {
                    var d: usize = 1;
                    while (d < variable.type.array_depth) : (d += 1) try self.write("[]");
                }
            } else {
                try self.write("[]");
            }
        }
        try self.write(";\n");
    }

    fn emit_generic_function_prototypes(self: *Self, emitted: *std.StringHashMap(bool)) TranspileError!void {
        const root = self.get_root();
        // Index-based, re-reading `.items.len` every iteration: see the matching
        // comment in `emit_generic_function_specializations` -- resolving one
        // instantiation's binding can register further ones that this same
        // pass must still visit (so their prototypes are forward-declared too).
        var i: usize = 0;
        while (i < root.generic_fn_instantiations.items.len) : (i += 1) {
            const inst = root.generic_fn_instantiations.items[i];
            if (self.mangled_contains_unresolved_placeholder(inst.name)) continue;
            if (emitted.contains(inst.name)) continue;
            const emitted_key = self.backing_allocator.dupe(u8, inst.name) catch return TranspileError.MemoryAllocationFailed;
            emitted.put(emitted_key, true) catch return TranspileError.MemoryAllocationFailed;

            {
                const prev_params = self.type_subst_params;
                const prev_args = self.type_subst_args;
                const prev_override = self.override_fn_name;
                self.type_subst_params = inst.params;
                self.type_subst_args = inst.args;
                self.override_fn_name = inst.name;
                defer {
                    self.type_subst_params = prev_params;
                    self.type_subst_args = prev_args;
                    self.override_fn_name = prev_override;
                }

                try self.resolve_transitive_generic_fn_instantiations(inst);
                try self.write_function_prototype(inst.fn_node.*);
            }
        }
    }

    /// True when some imported `std.c.*` module declares a BODYLESS binding named
    /// `name` (e.g. `pub fun log(dec x) dec;` in std.c.math, which maps to libc
    /// `log`). Used to detect that a Fun-defined free function of the same name
    /// would collide with the raw libc symbol in generated C.
    fn c_binding_symbol_exists_in(self: *Self, proc: *Self, name: []const u8) bool {
        if (proc_is_c_binding_module(proc)) {
            for (proc.nodes.items()) |n| {
                if (n.type != .Function or n.node_variant == null) continue;
                const fnv = n.node_variant.?.function;
                if (fnv.body != null) continue; // only bodyless bindings map to raw libc
                if (fnv.name != null and mem.eql(u8, fnv.name.?.items, name)) return true;
            }
            for (proc.owned_nodes.items) |n| {
                if (n.type != .Function or n.node_variant == null) continue;
                const fnv = n.node_variant.?.function;
                if (fnv.body != null) continue;
                if (fnv.name != null and mem.eql(u8, fnv.name.?.items, name)) return true;
            }
        }
        for (proc.children.items) |child| {
            if (self.c_binding_symbol_exists_in(child, name)) return true;
        }
        return false;
    }

    /// True if there is a REAL (body-having, non-`std.c.*`) Fun function
    /// definition named `name` anywhere in `proc`'s subtree. Unlike
    /// `find_function_node` (used for ordinary call-site resolution, where
    /// "first match in scope/search order" is the intentionally correct
    /// behavior), this is scoped to exactly the question
    /// `fun_fn_name_needs_c_shadow_rename` needs answered — so it can't be
    /// short-circuited by an UNRELATED bodyless `std.c.*` binding of the
    /// same name being reached first in the tree (see that function's own
    /// doc comment for a worked example of exactly that happening).
    fn find_real_fn_definition_in(self: *Self, proc: *Self, name: []const u8) ?*ast.Node {
        for (proc.nodes.items()) |*n| {
            if (n.type != .Function or n.node_variant == null) continue;
            const fnv = n.node_variant.?.function;
            if (fnv.name == null or !mem.eql(u8, fnv.name.?.items, name)) continue;
            if (fnv.body == null) continue; // a bodyless std.c.* binding stub, not this
            return n;
        }
        for (proc.children.items) |child| {
            if (self.find_real_fn_definition_in(child, name)) |found| return found;
        }
        return null;
    }

    /// A Fun-defined free function whose name collides with a libc symbol pulled in
    /// by an imported `std.c.*` binding (e.g. `std.log`'s `pub fun log(LogLevel, str)`
    /// vs libc `log` from `<math.h>` via std.math) must be emitted under a
    /// collision-safe C symbol. Its Fun surface name is UNCHANGED; only the C name is
    /// rewritten, consistently at its declaration and its bare-identifier call sites.
    /// The `std.c.*` binding calls themselves resolve to the RAW libc name and are not
    /// affected (they never route through this — they carry a module alias and go
    /// through `resolve_alias_qualified_symbol_name`).
    ///
    /// Uses `find_real_fn_definition_in` (not `find_function_node`) specifically
    /// because a bare-name search can otherwise resolve to the WRONG same-named
    /// node: e.g. `imp std.json; imp std.log;` (in that order) transitively
    /// imports `std.c.math`'s bodyless `log` binding (via std.json -> std.math)
    /// BEFORE std.log's own real `log` function is ever reached in the import
    /// tree's depth-first search order. `find_function_node` (first match wins,
    /// correct for its OTHER callers — genuine call-site resolution) would find
    /// that bodyless stub first and this function would wrongly conclude "log"
    /// has no real Fun definition to rename, silently leaving the collision in
    /// place (confirmed directly: this is exactly how `std.log`'s `log` reached
    /// codegen unrenamed and collided with libc's `<math.h>` `log(double)`).
    fn fun_fn_name_needs_c_shadow_rename(self: *Self, name: []const u8) bool {
        if (mem.eql(u8, name, "main")) return false;
        const root = self.get_root();
        const fn_node = self.find_real_fn_definition_in(root, name) orelse return false;
        // If the resolved definition itself lives in a std.c.* module it IS the binding;
        // don't rename it.
        if (fn_node.pos) |pos| {
            if (std.mem.indexOf(u8, pos.filename, "/std/c/") != null) return false;
            if (std.mem.indexOf(u8, pos.filename, "\\std\\c\\") != null) return false;
        }
        return self.c_binding_symbol_exists_in(root, name);
    }

    fn write_effective_function_name(self: *Self, node: ast.Node, name: []const u8) TranspileError!void {
        _ = node;
        if (self.override_fn_name) |ov| {
            try self.write(ov);
            return;
        }

        if (self.import_alias) |alias| {
            if (!mem.eql(u8, name, "main")) {
                try self.write(alias);
                try self.write("__");
                try self.write(name);
                return;
            }
        }

        if (self.fun_fn_name_needs_c_shadow_rename(name)) {
            try self.write("__fun_shadow__");
            try self.write(name);
            return;
        }

        try self.write(name);
    }

    fn alloc_effective_function_name(self: *Self, name: []const u8) TranspileError![]const u8 {
        if (self.override_fn_name) |ov| {
            return self.allocator.dupe(u8, ov) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        if (self.import_alias) |alias| {
            if (!mem.eql(u8, name, "main")) {
                return std.fmt.allocPrint(self.allocator, "{s}__{s}", .{ alias, name }) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
        }

        if (self.fun_fn_name_needs_c_shadow_rename(name)) {
            return std.fmt.allocPrint(self.allocator, "__fun_shadow__{s}", .{name}) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        return self.allocator.dupe(u8, name) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    fn write_async_function_support_prototypes(self: *Self, node: ast.Node) TranspileError!void {
        if (node.type != .Function or node.node_variant == null) return;
        const fnv = node.node_variant.?.function;
        if (!fnv.is_async) return;
        if (fnv.name == null or fnv.body == null) return;

        const effective_name = try self.alloc_effective_function_name(fnv.name.?.items);
        defer self.allocator.free(effective_name);

        try self.write("typedef struct __fun_async_payload_");
        try self.write(effective_name);
        try self.write(" {\n");

        if (fnv.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (arg.type != .Variable or arg.node_variant == null) continue;
                const v = arg.node_variant.?.variable;
                try self.write("  ");
                // A function-TYPE argument (`fun(T1, T2) R name`) needs C's
                // function-pointer declarator shape, which wraps the field
                // NAME (`R (*__argN)(T1, T2)`) instead of following a plain
                // type name — the same special case an ordinary parameter's
                // `.Variable` transpile_node handling already has (see
                // there). Calling `write_type` directly here (as this payload
                // struct used to) can't express that shape at all and wrote
                // out the fn_sig's own raw, un-lowered type text instead —
                // invalid as a struct field declaration.
                if (v.type.fn_sig) |sig| {
                    try self.write_type(sig.rtype.*);
                    try self.write(" (*__arg");
                    try self.print("{d}", .{i});
                    try self.write(")(");
                    for (sig.params.items(), 0..) |p, pi| {
                        if (pi > 0) try self.write(", ");
                        try self.write_type(p.*);
                    }
                    try self.write(");\n");
                    continue;
                }
                try self.write_type(v.type.*);
                try self.write(" __arg");
                try self.print("{d}", .{i});
                try self.write(";\n");
            }
        }

        if (fnv.rtype) |rt| {
            if (rt.type != .Void) {
                try self.write("  ");
                try self.write_return_type(rt);
                try self.write(" __result;\n");
            }
        }

        try self.write("} __fun_async_payload_");
        try self.write(effective_name);
        try self.write(";\n");

        try self.write("static void* __fun_async_entry_");
        try self.write(effective_name);
        try self.write("(void* __arg);\n");

        try self.write("static int __fun_async_spawn_");
        try self.write(effective_name);
        try self.write("(__fun_async_payload_");
        try self.write(effective_name);
        try self.write("* __payload, __fun_thread_t* __thr);\n");

        if (fnv.rtype) |rt| {
            try self.write("static ");
            try self.write_return_type(rt);
        } else {
            try self.write("static void");
        }
        try self.write(" __fun_async_await_");
        try self.write(effective_name);
        try self.write("(__fun_async_payload_");
        try self.write(effective_name);
        try self.write("* __payload, __fun_thread_t __thr);\n");

        if (fnv.rtype) |rt| {
            try self.write("static ");
            try self.write_return_type(rt);
        } else {
            try self.write("static void");
        }
        try self.write(" __fun_async_call_");
        try self.write(effective_name);
        try self.write("(");
        self.in_function_params = true;
        if (fnv.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (i > 0) try self.write(", ");
                try self.transpile_node(arg.*);
            }
        }
        self.in_function_params = false;
        try self.write(");\n");
    }

    /// Emits a `#line N "filename"` directive for the given source position.
    /// Used to anchor compiler-generated C code back to a known Fun source line
    /// so the debugger does not land on unrelated lines when stepping.
    fn write_pos_line_directive(self: *Self, pos: token.Pos) TranspileError!void {
        try self.write("#line ");
        try self.print("{d}", .{pos.line});
        try self.write(" \"");
        for (pos.filename) |ch| {
            if (ch == '\\') try self.write("\\\\") else try self.print("{c}", .{ch});
        }
        try self.write("\"\n");
    }

    fn write_async_function_support_definitions(self: *Self, node: ast.Node) TranspileError!void {
        if (node.type != .Function or node.node_variant == null) return;
        const fnv = node.node_variant.?.function;
        if (!fnv.is_async) return;
        if (fnv.name == null or fnv.body == null) return;

        const effective_name = try self.alloc_effective_function_name(fnv.name.?.items);
        defer self.allocator.free(effective_name);

        // When debug info is enabled we emit a `#line pos.line "file"` directive
        // before EVERY C statement inside the generated helpers.  This pins every
        // line of every trampoline to the Fun function's own definition line so
        // the debugger always shows that line while stepping through the helper
        // internals.  Without this, the C preprocessor's line counter drifts from
        // pos.line into adjacent blank lines, comments, and the next method's
        // header — causing confusing "wrong line" stops.
        const pos_opt: ?token.Pos = if (self.flags.debug_info) node.pos else null;

        // ----- Entry trampoline -----
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("static void* __fun_async_entry_");
        try self.write(effective_name);
        try self.write("(void* __arg) {\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  __fun_async_payload_");
        try self.write(effective_name);
        try self.write("* __payload = (__fun_async_payload_");
        try self.write(effective_name);
        try self.write("*)__arg;\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        if (fnv.rtype) |rt| {
            if (rt.type != .Void) {
                try self.write("  __payload->__result = ");
            } else {
                try self.write("  ");
            }
        } else {
            try self.write("  ");
        }
        try self.write(effective_name);
        try self.write("(");
        if (fnv.args) |args| {
            for (args.items(), 0..) |_, i| {
                if (i > 0) try self.write(", ");
                try self.write("__payload->__arg");
                try self.print("{d}", .{i});
            }
        }
        try self.write(");\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  return NULL;\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("}\n");

        // ----- Spawn helper -----
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("static int __fun_async_spawn_");
        try self.write(effective_name);
        try self.write("(__fun_async_payload_");
        try self.write(effective_name);
        try self.write("* __payload, __fun_thread_t* __thr) {\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  return __fun_thread_start(__thr, __fun_async_entry_");
        try self.write(effective_name);
        try self.write(", __payload);\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("}\n");

        // ----- Await helper -----
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        if (fnv.rtype) |rt| {
            try self.write("static ");
            try self.write_return_type(rt);
        } else {
            try self.write("static void");
        }
        try self.write(" __fun_async_await_");
        try self.write(effective_name);
        try self.write("(__fun_async_payload_");
        try self.write(effective_name);
        try self.write("* __payload, __fun_thread_t __thr) {\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  (void)__fun_thread_join(__thr);\n");
        if (fnv.rtype) |rt| {
            if (rt.type != .Void) {
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("  ");
                try self.write_return_type(rt);
                try self.write(" __result = __payload->__result;\n");
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("  free(__payload);\n");
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("  return __result;\n");
            } else {
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("  free(__payload);\n");
            }
        } else {
            if (pos_opt) |pos| try self.write_pos_line_directive(pos);
            try self.write("  free(__payload);\n");
        }
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("}\n");

        // ----- High-level call helper (what `await` lowers to) -----
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        if (fnv.rtype) |rt| {
            try self.write("static ");
            try self.write_return_type(rt);
        } else {
            try self.write("static void");
        }
        try self.write(" __fun_async_call_");
        try self.write(effective_name);
        try self.write("(");
        self.in_function_params = true;
        if (fnv.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (i > 0) try self.write(", ");
                try self.transpile_node(arg.*);
            }
        }
        self.in_function_params = false;
        try self.write(") {\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  __fun_async_payload_");
        try self.write(effective_name);
        try self.write("* __payload = (__fun_async_payload_");
        try self.write(effective_name);
        try self.write("*)malloc(sizeof(__fun_async_payload_");
        try self.write(effective_name);
        try self.write("));\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  if (__payload == NULL) {\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        if (fnv.rtype) |rt| {
            if (rt.type != .Void) {
                try self.write("    return ");
            } else {
                try self.write("    ");
            }
        } else {
            try self.write("    ");
        }
        try self.write(effective_name);
        try self.write("(");
        if (fnv.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (arg.type != .Variable or arg.node_variant == null) continue;
                if (i > 0) try self.write(", ");
                try self.write(arg.node_variant.?.variable.name.items);
            }
        }
        try self.write(");\n");
        if (fnv.rtype) |rt| {
            if (rt.type == .Void) {
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("    return;\n");
            }
        }
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  }\n");
        if (fnv.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (arg.type != .Variable or arg.node_variant == null) continue;
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("  __payload->__arg");
                try self.print("{d}", .{i});
                try self.write(" = ");
                try self.write(arg.node_variant.?.variable.name.items);
                try self.write(";\n");
            }
        }
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  __fun_thread_t __thr;\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  int __rc = __fun_async_spawn_");
        try self.write(effective_name);
        try self.write("(__payload, &__thr);\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  if (__rc != 0) {\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("    free(__payload);\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        if (fnv.rtype) |rt| {
            if (rt.type != .Void) {
                try self.write("    return ");
            } else {
                try self.write("    ");
            }
        } else {
            try self.write("    ");
        }
        try self.write(effective_name);
        try self.write("(");
        if (fnv.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (arg.type != .Variable or arg.node_variant == null) continue;
                if (i > 0) try self.write(", ");
                try self.write(arg.node_variant.?.variable.name.items);
            }
        }
        try self.write(");\n");
        if (fnv.rtype) |rt| {
            if (rt.type == .Void) {
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("    return;\n");
            }
        }
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("  }\n");
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        if (fnv.rtype) |rt| {
            if (rt.type != .Void) {
                try self.write("  return ");
            } else {
                try self.write("  ");
            }
        } else {
            try self.write("  ");
        }
        try self.write("__fun_async_await_");
        try self.write(effective_name);
        try self.write("(__payload, __thr);\n");
        if (fnv.rtype) |rt| {
            if (rt.type == .Void) {
                if (pos_opt) |pos| try self.write_pos_line_directive(pos);
                try self.write("  return;\n");
            }
        }
        if (pos_opt) |pos| try self.write_pos_line_directive(pos);
        try self.write("}\n");

        // ----- fork (fire-and-forget) support -----
        // Only when `fork` is used anywhere. Reuses the async payload struct above.
        // `__fun_fork_entry_<fn>` runs the function then FREES the payload (no join),
        // and is the task body enqueued onto the scheduler. `__fun_fork_call_<fn>`
        // mirrors `__fun_async_call_<fn>` but enqueues via `__fun_go` instead of
        // spawning+joining, returning nothing (the result is discarded).
        if (self.uses_fork) {
            // Entry: unpack payload, call, free, done.
            try self.write("static void __fun_fork_entry_");
            try self.write(effective_name);
            try self.write("(void* __arg) {\n");
            try self.write("  __fun_async_payload_");
            try self.write(effective_name);
            try self.write("* __payload = (__fun_async_payload_");
            try self.write(effective_name);
            try self.write("*)__arg;\n  ");
            try self.write(effective_name);
            try self.write("(");
            if (fnv.args) |args| {
                for (args.items(), 0..) |_, i| {
                    if (i > 0) try self.write(", ");
                    try self.write("__payload->__arg");
                    try self.print("{d}", .{i});
                }
            }
            try self.write(");\n  free(__payload);\n}\n");

            // Call wrapper: alloc payload, set args, enqueue (degrade to sync on OOM).
            try self.write("static void __fun_fork_call_");
            try self.write(effective_name);
            try self.write("(");
            self.in_function_params = true;
            if (fnv.args) |args| {
                for (args.items(), 0..) |arg, i| {
                    if (i > 0) try self.write(", ");
                    try self.transpile_node(arg.*);
                }
            }
            self.in_function_params = false;
            try self.write(") {\n");
            try self.write("  __fun_async_payload_");
            try self.write(effective_name);
            try self.write("* __payload = (__fun_async_payload_");
            try self.write(effective_name);
            try self.write("*)malloc(sizeof(__fun_async_payload_");
            try self.write(effective_name);
            try self.write("));\n");
            try self.write("  if (__payload == NULL) { ");
            try self.write(effective_name);
            try self.write("(");
            if (fnv.args) |args| {
                var wrote = false;
                for (args.items()) |arg| {
                    if (arg.type != .Variable or arg.node_variant == null) continue;
                    if (wrote) try self.write(", ");
                    try self.write(arg.node_variant.?.variable.name.items);
                    wrote = true;
                }
            }
            try self.write("); return; }\n");
            if (fnv.args) |args| {
                for (args.items(), 0..) |arg, i| {
                    if (arg.type != .Variable or arg.node_variant == null) continue;
                    try self.write("  __payload->__arg");
                    try self.print("{d}", .{i});
                    try self.write(" = ");
                    try self.write(arg.node_variant.?.variable.name.items);
                    try self.write(";\n");
                }
            }
            try self.write("  __fun_go(__fun_fork_entry_");
            try self.write(effective_name);
            try self.write(", __payload);\n}\n");
        }
    }

    fn write_function_prototype(self: *Self, node: ast.Node) TranspileError!void {
        if (node.type != .Function or node.node_variant == null) return;
        const function = node.node_variant.?.function;
        if (function.body == null) return;

        if (function.name) |name| {
            const out_name = if (self.override_fn_name) |ov| ov else name.items;
            if (self.mangled_contains_unresolved_placeholder(out_name)) return;
        }

        if (function.rtype) |rtype| {
            try self.write_return_type(rtype);
        } else {
            try self.write("void");
        }

        try self.write(" ");
        if (function.name) |name| {
            try self.write_effective_function_name(node, name.items);
        }

        try self.write("(");
        self.in_function_params = true;
        var wrote_any_param = false;
        if (function.args) |args| {
            for (args.items(), 0..) |arg, i| {
                if (i > 0) try self.write(", ");
                try self.transpile_node(arg.*);
                wrote_any_param = true;
            }
        }
        if (function.is_variadic) {
            if (wrote_any_param) try self.write(", ");
            try self.write("const char* __fun_vtags");
            try self.write(", ...");
        }
        self.in_function_params = false;
        try self.write(");\n");

        try self.write_async_function_support_prototypes(node);
    }

    // Emit C `#define` stubs so that `new_alias__funcName` resolves to the already-emitted
    // `canonical_alias__funcName` (or the bare name when canonical has no alias).
    // This handles any module — stdlib or user-defined — that appears under two different
    // aliases in the import tree.
    fn emit_module_alias_stubs(self: *Self, child: *TranspileProcess, canonical_alias: ?[]const u8) TranspileError!void {
        const new_alias = child.import_alias;

        // If both aliases are the same (including both-null), nothing to do.
        const same = blk: {
            if (new_alias == null and canonical_alias == null) break :blk true;
            if (new_alias != null and canonical_alias != null)
                break :blk mem.eql(u8, new_alias.?, canonical_alias.?);
            break :blk false;
        };
        if (same) return;

        // `child` may be a lightweight alias-stub with no nodes (created when a module is
        // re-imported under a different alias).  Find the canonical process to enumerate
        // the module's public functions.
        const source_proc: *TranspileProcess = blk: {
            if (child.nodes.items().len > 0 or child.owned_nodes.items.len > 0) break :blk child;
            // Prefer a proc that actually carries the module's nodes. `find_process_for_file`
            // matches by basename and can return ANOTHER node-less stub for the same file
            // (there may be several aliased re-imports), so use the path-exact,
            // nodes-carrying lookup first and only fall back to the basename match.
            if (self.get_root().find_parsed_proc_by_path(child.input_file_path)) |p| break :blk p;
            if (self.get_root().find_process_for_file(child.input_file_path)) |p| {
                if (p.nodes.items().len > 0 or p.owned_nodes.items.len > 0) break :blk p;
            }
            return; // Can't find node list — skip.
        };

        var wrote_header = false;
        var emitted = std.StringHashMap(void).init(self.allocator);
        defer emitted.deinit();
        // Stdlib module functions live in `owned_nodes`; user-module functions in
        // `nodes`. Scan BOTH so a diamond-imported stdlib module (imported once
        // unaliased, once `as x`) still gets its `x__fn -> fn` #define stubs —
        // without them an `x.fn(...)` call emits an undeclared `x__fn` (implicit
        // int in C), which fails to compile.
        inline for (.{ true, false }) |use_nodes| {
            const count = if (use_nodes) source_proc.nodes.items().len else source_proc.owned_nodes.items.len;
            var idx: usize = 0;
            while (idx < count) : (idx += 1) {
                const node = if (use_nodes) source_proc.nodes.items()[idx] else source_proc.owned_nodes.items[idx].*;
                if (node.type != .Function or node.node_variant == null) continue;
                const f = node.node_variant.?.function;
                if (f.body == null or f.name == null) continue;
                if (f.type_params != null) continue;
                const fname = f.name.?.items;
                if (mem.eql(u8, fname, "main")) continue;
                if (emitted.contains(fname)) continue;
                emitted.put(fname, {}) catch {};

                if (!wrote_header) {
                    try self.write("\n// Alias stubs: ");
                    try self.write(if (new_alias) |a| a else "(unaliased)");
                    try self.write(" -> ");
                    try self.write(if (canonical_alias) |a| a else "(unaliased)");
                    try self.write("\n");
                    wrote_header = true;
                }
                try self.write("#define ");
                if (new_alias) |na| {
                    try self.write(na);
                    try self.write("__");
                }
                try self.write(fname);
                try self.write(" ");
                if (canonical_alias) |ca| {
                    try self.write(ca);
                    try self.write("__");
                }
                try self.write(fname);
                try self.write("\n");
            }
        }
    }

    // Helper function to recursively transpile children.
    // `seen` maps file path -> the alias the module was first emitted under (null = no alias).
    // When a module is re-encountered under a different alias, C #define stubs are emitted
    // instead of re-emitting the full implementation.  This works for any module —
    // stdlib or user-defined.
    fn transpile_children_recursive(self: *Self, parent_proc: *TranspileProcess, seen: *std.StringHashMap(?[]const u8)) TranspileError!void {
        for (parent_proc.children.items) |child| {
            if (seen.get(child.input_file_path)) |canonical_alias| {
                // Module already emitted under `canonical_alias`.  If the current import
                // uses a different alias, emit #define stubs and recurse for sub-children.
                try self.emit_module_alias_stubs(child, canonical_alias);
                try self.transpile_children_recursive(child, seen);
                continue;
            }
            seen.put(child.input_file_path, child.import_alias) catch return TranspileError.MemoryAllocationFailed;
            // Recursively transpile the child's children first
            try self.transpile_children_recursive(child, seen);

            const prev_alias = self.import_alias;
            const prev_aliases_override = self.import_aliases_override;
            const prev_emit_input_file_path = self.emit_input_file_path;
            const prev_emit_module_proc = self.emit_module_proc;
            self.import_alias = child.import_alias;
            self.import_aliases_override = &child.import_aliases;
            self.emit_input_file_path = child.input_file_path;
            self.emit_module_proc = child;

            // Then, transpile the child's own nodes (excluding imports and main functions)
            for (child.nodes.items()) |node| {
                if (node.type != .Import) {
                    if (node.type == .Compound or node.type == .Quirk) continue;
                    if (self.is_std_c_signature_node(&node)) continue;
                    // Skip main functions in imported modules
                    if (node.type == .Function and node.node_variant != null) {
                        const function = node.node_variant.?.function;
                        if (function.name != null and mem.eql(u8, function.name.?.items, "main")) {
                            continue; // Skip this main function from an imported module
                        }
                        if (function.type_params != null) {
                            continue;
                        }
                        if (self.function_has_unresolved_placeholder(node)) {
                            continue;
                        }
                        if (function.name) |fname| {
                            if (self.mangled_contains_unresolved_placeholder(fname.items)) {
                                continue;
                            }
                        }
                    }

                    try self.transpile_node(node);
                    try self.write("\n\n");
                }
            }

            self.import_alias = prev_alias;
            self.import_aliases_override = prev_aliases_override;
            self.emit_input_file_path = prev_emit_input_file_path;
            self.emit_module_proc = prev_emit_module_proc;
        }
    }

    fn module_has_function_named(self: *Self, proc: *const TranspileProcess, name: []const u8) bool {
        _ = self;
        for (proc.nodes.items()) |n| {
            if (n.type != .Function or n.node_variant == null) continue;
            const f = n.node_variant.?.function;
            if (f.body == null or f.name == null) continue;
            if (mem.eql(u8, f.name.?.items, name)) return true;
        }
        return false;
    }

    fn module_has_impl_method_named(self: *Self, proc: *const TranspileProcess, name: []const u8) bool {
        _ = self;

        for (proc.nodes.items()) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                if (mem.eql(u8, fnv.name.?.items, name)) return true;
            }
        }

        for (proc.owned_nodes.items) |n| {
            if (n.type != .Impl or n.node_variant == null) continue;
            const im = n.node_variant.?.impl;
            for (im.methods.items()) |m| {
                if (m.type != .Function or m.node_variant == null) continue;
                const fnv = m.node_variant.?.function;
                if (fnv.name == null) continue;
                if (mem.eql(u8, fnv.name.?.items, name)) return true;
            }
        }
        return false;
    }

    fn find_import_alias_for_impl_method(self: *Self, proc: *const TranspileProcess, name: []const u8) ?[]const u8 {
        if (proc.import_alias) |alias| {
            if (self.module_has_impl_method_named(proc, name)) return alias;
        }

        for (proc.children.items) |child| {
            if (self.find_import_alias_for_impl_method(child, name)) |alias| return alias;
        }
        return null;
    }

    fn write_module_function_ref(self: *Self, name: []const u8) TranspileError!void {
        if (self.import_alias) |alias| {
            if (self.emit_module_proc) |mproc| {
                if (self.module_has_function_named(mproc, name)) {
                    try self.write(alias);
                    try self.write("__");
                    try self.write(name);
                    return;
                }
            }
        }
        try self.write(name);
    }

    fn write_module_impl_method_ref(self: *Self, name: []const u8) TranspileError!void {
        try self.write(name);
    }

    /// Transpiles the prelude code to C
    fn transpile_prelude(self: *Self) TranspileError!void {
        try self.write_std_imports();
        try self.write("\n");

        if (!self.is_importing) {
            // stdio.h/stdlib.h are already unconditionally included by
            // write_std_imports's "core headers" above -- don't re-include
            // them here (this used to emit a literal duplicate
            // `#include <stdlib.h>#include <stdio.h>` pair every time).
            if (self.flags.test_mode) {
                // Recoverable assertion failure: a failing `assert` inside a
                // test-mode compile jumps back to whichever test dispatched
                // it (via the runner's own setjmp, see
                // emit_test_mode_functions_and_runner) instead of aborting
                // the whole process -- see the `.assert_stmt` transpile
                // case. `_Thread_local` because tests run concurrently, one
                // per virtual task, potentially on different worker
                // threads; a single shared jmp_buf would be a data race if
                // two tests failed at once.
                try self.write("#include <setjmp.h>\n");
                try self.write("static _Thread_local jmp_buf __fun_test_jmp;\n");
            }
            // Standard-stream accessors. `stdout`/`stderr`/`stdin` are macros/globals
            // (not callable), and differ per libc (glibc/musl/macOS/MSVCRT resolve
            // them differently — MSVCRT via a function call). Wrapping them in tiny
            // `static` functions lets Fun name them as `FILE*`-returning bindings
            // (std.c.io.stdout_stream()/...) portably; a bare `extern FILE* stdout;`
            // would fail to link on Windows.
            try self.write("static FILE* stdout_stream(void){ return stdout; }\n");
            try self.write("static FILE* stderr_stream(void){ return stderr; }\n");
            try self.write("static FILE* stdin_stream(void){ return stdin; }\n");
            // MSVCRT's default text-mode stdio silently translates every `\n`
            // byte written to stdout/stderr into `\r\n`, unlike glibc/macOS's
            // libc. Fun's own string literals treat `\n` as a single LF byte
            // (see `write_c_string_literal_body`), so left alone, a compiled
            // program's actual output would only match that on POSIX. Force
            // both streams to binary (untranslated) mode before `main` runs,
            // via a constructor, so process output is consistent everywhere.
            try self.write("#ifdef _WIN32\n");
            try self.write("#pragma push_macro(\"close\")\n");
            try self.write("#undef close\n");
            try self.write("#include <io.h>\n");
            try self.write("#include <fcntl.h>\n");
            try self.write("#pragma pop_macro(\"close\")\n");
            try self.write("__attribute__((constructor)) static void __fun_win_stdio_binary(void) {\n");
            try self.write("  _setmode(_fileno(stdout), _O_BINARY);\n");
            try self.write("  _setmode(_fileno(stderr), _O_BINARY);\n");
            try self.write("}\n");
            try self.write("#endif\n");
            // `environ` (the process environment, needed by std.c.process's
            // posix_spawn binding to inherit the parent's env) is a global, not a
            // callable symbol -- same reasoning as the stdout/stderr/stdin
            // wrappers above: a bare `extern char** environ;` declaration is not
            // portable (MinGW/MSVC spell it `_environ`), so wrap it.
            try self.write("#ifdef _WIN32\n");
            try self.write("static char** environ_ptr(void){ return _environ; }\n");
            try self.write("#else\n");
            try self.write("extern char** environ;\n");
            try self.write("static char** environ_ptr(void){ return environ; }\n");
            try self.write("#endif\n");
            // `setenv` is POSIX and has no Windows CRT equivalent under that
            // name, so Windows gets one written in terms of what it does have.
            // Same approach as `environ_ptr` above: the wrapper's C signature
            // matches the POSIX one exactly, so `std.c.mem`'s single binding is
            // correct on every platform. `_putenv_s` is declared by <stdlib.h>
            // on both MSVC and MinGW-w64, neither of which declares `setenv`.
            try self.write("#ifdef _WIN32\n");
            try self.write("static int setenv(const char* name, const char* value, int overwrite) {\n");
            try self.write("  if (!overwrite && getenv(name) != NULL) { return 0; }\n");
            try self.write("  return _putenv_s(name, value);\n");
            try self.write("}\n");
            try self.write("static int unsetenv(const char* name) { return _putenv_s(name, \"\"); }\n");
            try self.write("#endif\n");
            // Suspends the calling thread for whole seconds, used by
            // `std.time`'s `sleep_seconds`. Not a direct libc binding since
            // POSIX's `nanosleep` has no Windows equivalent under the same
            // name; Windows gets its own implementation in terms of `Sleep`,
            // the same approach `setenv` above takes.
            try self.write("#ifdef _WIN32\n");
            // Not covered by whatever else in this translation unit
            // happens to include <windows.h> (e.g. std.c.dirent's
            // Windows branch, emitted later): `Sleep`/`DWORD` need it
            // directly here too, or a program using only `sleep_seconds`
            // sees an implicit-declaration conflict against `Sleep`'s
            // real prototype once something else does include it later
            // in the same file.
            try self.write("#include <windows.h>\n");
            try self.write("static void __fun_sleep_seconds(long long seconds) {\n");
            try self.write("  if (seconds < 0) seconds = 0;\n");
            try self.write("  Sleep((DWORD)(seconds * 1000));\n");
            try self.write("}\n");
            // `clock_gettime` is missing from UCRT (real MSVC/clang-cl
            // builds) entirely, but MinGW's own headers already declare
            // a real one with the standard POSIX signature - defining
            // ours unconditionally conflicts with that declaration
            // there. std.channel's own deadline math calls this
            // directly (not gated on `fork`), so it still needs a
            // definition on UCRT, just not on MinGW.
            try self.write("#ifndef __MINGW32__\n");
            try self.write("static long long clock_gettime(long long clk_id, void* tp) {\n");
            try self.write("  (void)clk_id;\n");
            try self.write("  if (!tp) return -1;\n");
            try self.write("  long long* __fun_cgt_out = (long long*)tp;\n");
            try self.write("  FILETIME __fun_cgt_ft;\n");
            try self.write("  GetSystemTimeAsFileTime(&__fun_cgt_ft);\n");
            try self.write("  unsigned long long __fun_cgt_t = ((unsigned long long)__fun_cgt_ft.dwHighDateTime << 32) | __fun_cgt_ft.dwLowDateTime;\n");
            try self.write("  __fun_cgt_t -= 116444736000000000ULL;\n");
            try self.write("  __fun_cgt_out[0] = (long long)(__fun_cgt_t / 10000000ULL);\n");
            try self.write("  __fun_cgt_out[1] = (long long)((__fun_cgt_t % 10000000ULL) * 100);\n");
            try self.write("  return 0;\n");
            try self.write("}\n");
            try self.write("#endif\n");
            try self.write("#else\n");
            // Not covered by `std.c.time`'s own conditional `#include
            // <time.h>` (this helper is unconditional, unlike that
            // module), so it needs its own; a repeated include of the
            // same standard header is harmless.
            try self.write("#include <time.h>\n");
            try self.write("static void __fun_sleep_seconds(long long seconds) {\n");
            try self.write("  if (seconds < 0) seconds = 0;\n");
            try self.write("  struct timespec __fun_sleep_ts; __fun_sleep_ts.tv_sec = seconds; __fun_sleep_ts.tv_nsec = 0;\n");
            try self.write("  nanosleep(&__fun_sleep_ts, NULL);\n");
            try self.write("}\n");
            try self.write("#endif\n");
            // Directory iteration/creation/kind-check helpers for `std.c.dirent`
            // (backing `std.fs`'s `list_dir`/`walk_dir`/`is_dir`/`make_dir`). Real
            // libc directory APIs differ enough across platforms (POSIX
            // opendir/readdir/DIR* vs. Win32 FindFirstFile/FindNextFile, and
            // `struct dirent`'s layout isn't something Fun can safely mirror as a
            // compound) that hand-written wrappers -- same approach as
            // `environ_ptr` above -- are the portable option: each wrapper's C
            // signature is written to match a Fun type EXACTLY (`void*` <->
            // `raw*`, `long long` <-> `num`, `char*`/`const char*` <-> `str`),
            // sidestepping the ABI-width mismatches a raw libc binding risks.
            try self.write("#ifdef _WIN32\n");
            // `std.c.net` (if imported) redefines `close` to `closesocket` via a
            // plain `#define` before this point (see the net-compat block in
            // `write_std_imports`). If that's already active, textually
            // including <windows.h>/<direct.h>/<sys/stat.h> here would rename
            // THEIR OWN `close()` declarations too (they transitively pull in
            // MinGW's io.h), conflicting with winsock2's real `closesocket`
            // signature. Shield these includes from whatever `close` currently
            // means and restore it after, regardless of whether the net
            // compat layer was active.
            try self.write("#pragma push_macro(\"close\")\n");
            try self.write("#undef close\n");
            try self.write("#include <windows.h>\n");
            try self.write("#include <direct.h>\n");
            try self.write("#include <sys/stat.h>\n");
            try self.write("#pragma pop_macro(\"close\")\n");
            try self.write("typedef struct { HANDLE h; WIN32_FIND_DATAA data; int started; } __fun_dir_iter;\n");
            try self.write("static void* __fun_dir_open(const char* path) { if (!path) return NULL; char pattern[4096]; snprintf(pattern, sizeof(pattern), \"%s\\\\*\", path); __fun_dir_iter* it = (__fun_dir_iter*)malloc(sizeof(__fun_dir_iter)); if (!it) return NULL; it->h = FindFirstFileA(pattern, &it->data); it->started = 0; if (it->h == INVALID_HANDLE_VALUE) { free(it); return NULL; } return it; }\n");
            try self.write("static char* __fun_dir_read_name(void* dirp) { __fun_dir_iter* it = (__fun_dir_iter*)dirp; if (!it) return NULL; if (it->started) { if (!FindNextFileA(it->h, &it->data)) return NULL; } else { it->started = 1; } return it->data.cFileName; }\n");
            try self.write("static long long __fun_dir_close(void* dirp) { __fun_dir_iter* it = (__fun_dir_iter*)dirp; if (!it) return -1; FindClose(it->h); free(it); return 0; }\n");
            try self.write("static long long __fun_path_is_dir(const char* path) { if (!path) return 0; struct _stat st; if (_stat(path, &st) != 0) return 0; return (st.st_mode & _S_IFDIR) ? 1 : 0; }\n");
            try self.write("static long long __fun_make_dir(const char* path) { if (!path) return -1; return _mkdir(path); }\n");
            try self.write("#else\n");
            try self.write("#include <dirent.h>\n");
            try self.write("#include <sys/stat.h>\n");
            try self.write("static void* __fun_dir_open(const char* path) { if (!path) return NULL; return (void*)opendir(path); }\n");
            try self.write("static char* __fun_dir_read_name(void* dirp) { if (!dirp) return NULL; struct dirent* e = readdir((DIR*)dirp); return e ? e->d_name : NULL; }\n");
            try self.write("static long long __fun_dir_close(void* dirp) { if (!dirp) return -1; return (long long)closedir((DIR*)dirp); }\n");
            try self.write("static long long __fun_path_is_dir(const char* path) { if (!path) return 0; struct stat st; if (stat(path, &st) != 0) return 0; return S_ISDIR(st.st_mode) ? 1 : 0; }\n");
            try self.write("static long long __fun_make_dir(const char* path) { if (!path) return -1; return mkdir(path, 0755); }\n");
            try self.write("#endif\n");
            try self.write("#ifdef _WIN32\n");
            try self.write("#include <windows.h>\n");
            try self.write("typedef HANDLE __fun_thread_t;\n");
            try self.write("typedef void* (*__fun_thread_entry_t)(void*);\n");
            try self.write("typedef struct __fun_thread_start_pack { __fun_thread_entry_t entry; void* arg; } __fun_thread_start_pack;\n");
            try self.write("static DWORD WINAPI __fun_thread_entry_win(LPVOID p) { __fun_thread_start_pack* pack = (__fun_thread_start_pack*)p; if (pack) { pack->entry(pack->arg); free(pack); } return 0; }\n");
            // A worker thread's stack is set explicitly to 8 MiB on both
            // platforms rather than left at the OS default: a secondary
            // pthread's default stack is far smaller than the main
            // thread's on some platforms (512 KiB on macOS, for example),
            // which is enough for a deeply recursive compiler pass (e.g.
            // parsing a pathologically nested expression) to overflow it
            // even though the same input is fine on the main thread.
            try self.write("static int __fun_thread_start(__fun_thread_t* t, __fun_thread_entry_t entry, void* arg) { __fun_thread_start_pack* pack = (__fun_thread_start_pack*)malloc(sizeof(__fun_thread_start_pack)); if (!pack) return -1; pack->entry = entry; pack->arg = arg; HANDLE h = CreateThread(NULL, 8 * 1024 * 1024, __fun_thread_entry_win, pack, 0, NULL); if (!h) { free(pack); return -1; } *t = h; return 0; }\n");
            try self.write("static int __fun_thread_join(__fun_thread_t t) { DWORD rc = WaitForSingleObject(t, INFINITE); CloseHandle(t); return rc == WAIT_OBJECT_0 ? 0 : -1; }\n");
            try self.write("#else\n");
            try self.write("#include <pthread.h>\n");
            try self.write("typedef pthread_t __fun_thread_t;\n");
            try self.write("typedef void* (*__fun_thread_entry_t)(void*);\n");
            try self.write("static int __fun_thread_start(__fun_thread_t* t, __fun_thread_entry_t entry, void* arg) { pthread_attr_t __fun_tattr; pthread_attr_init(&__fun_tattr); pthread_attr_setstacksize(&__fun_tattr, 8 * 1024 * 1024); int __fun_trc = pthread_create(t, &__fun_tattr, entry, arg); pthread_attr_destroy(&__fun_tattr); return __fun_trc; }\n");
            try self.write("static int __fun_thread_join(__fun_thread_t t) { return pthread_join(t, NULL); }\n");
            try self.write("#endif\n\n");

            // M:N cooperative virtual-thread scheduler, emitted only when `fork` is
            // used. A fixed pool of OS worker threads (sized to the CPU count) drains
            // a shared FIFO task queue; each `fork f(args)` enqueues one task. The
            // pool starts lazily on the first fork and `__fun_sched_wait_idle()` (run
            // at every `main` exit) blocks until all queued tasks complete.
            if (self.uses_fork) {
                try self.emit_scheduler_runtime();
            } else {
                // No fork scheduler in this program, but channel.fn still calls the
                // watchdog hooks around every blocking channel wait — a plain
                // (non-fork) program can deadlock too (e.g. a lone `ch.recv()` with
                // no sender). Emit a minimal, self-contained watchdog: no task queue
                // to track (nothing is scheduled), so the stall condition is simply
                // "at least one blocking wait is open, with no enter/leave transition
                // for the configured threshold". Dormant unless FUN_DEADLOCK_WATCHDOG_MS
                // is set (the `armed` check below), so the default hot path is
                // unchanged. Mirrors `emit_scheduler_runtime`'s fork-based watchdog.
                try self.write(
                    \\typedef struct __fun_wd_state { int armed; long long threshold_ms; int abort_on_fire; int blocked; long long progress_seq; int started; } __fun_wd_state;
                    \\static __fun_wd_state __fun_g_wd;
                    \\void __fun_wd_warn(long long blocked_or_count, long long pending_or_cap, long long stall_ms){
                    \\  fprintf(stderr, "fun: possible deadlock: %lld blocked, %lld pending/cap, no progress for %lldms\n", blocked_or_count, pending_or_cap, stall_ms);
                    \\}
                    \\static void* __fun_wd_thread(void* unused){ (void)unused;
                    \\  long long last_seq=-1; long long stall_ms=0;
                    \\  long long step=__fun_g_wd.threshold_ms/4; if(step<1)step=1; if(step>1000)step=1000;
                    \\  for(;;){
                    \\#ifdef _WIN32
                    \\    Sleep((DWORD)step);
                    \\#else
                    \\    struct timespec __ts; __ts.tv_sec=step/1000; __ts.tv_nsec=(step%1000)*1000000L; nanosleep(&__ts,NULL);
                    \\#endif
                    \\    int blk=__fun_g_wd.blocked; long long seq=__fun_g_wd.progress_seq;
                    \\    if(blk>0 && seq==last_seq){ stall_ms+=step; } else { stall_ms=0; }
                    \\    last_seq=seq;
                    \\    if(stall_ms>=__fun_g_wd.threshold_ms){
                    \\      __fun_wd_warn((long long)blk, 0, stall_ms);
                    \\      if(__fun_g_wd.abort_on_fire) abort();
                    \\      stall_ms=0;
                    \\    }
                    \\  }
                    \\}
                    \\void __fun_wd_enter_wait(void){
                    \\  if(!__fun_g_wd.started){
                    \\    __fun_g_wd.started=1;
                    \\    const char* w=getenv("FUN_DEADLOCK_WATCHDOG_MS");
                    \\    long long wm=(w && w[0])?atoll(w):0;
                    \\    __fun_g_wd.armed=(wm>0)?1:0; __fun_g_wd.threshold_ms=(wm>0)?wm:0;
                    \\    const char* a=getenv("FUN_DEADLOCK_ABORT");
                    \\    __fun_g_wd.abort_on_fire=(a && a[0]=='1')?1:0;
                    \\    if(__fun_g_wd.armed){ __fun_thread_t th; __fun_thread_start(&th, __fun_wd_thread, NULL); }
                    \\  }
                    \\  if(!__fun_g_wd.armed) return;
                    \\  __fun_g_wd.blocked++;
                    \\}
                    \\void __fun_wd_leave_wait(void){ if(!__fun_g_wd.armed) return; if(__fun_g_wd.blocked>0)__fun_g_wd.blocked--; __fun_g_wd.progress_seq++; }
                    \\
                    \\
                );
            }

            try self.write("#define __fun_tag(x) _Generic((x), ");
            try self.write("char*: 's', const char*: 's', ");
            try self.write("long long: 'n', long: 'n', int: 'n', unsigned long long: 'n', unsigned long: 'n', unsigned int: 'n', ");
            try self.write("double: 'd', float: 'd', _Bool: 'b', char: 'c', void*: 'p', default: 'p')\n\n");

            // Runtime helper for the `__fun_key_hash` intrinsic on string keys:
            // an FNV-1a-style hash over the string CONTENTS (the value-based map/set
            // key hash). Value-typed keys hash their raw bytes inline at the call
            // site; only the string case needs to follow the pointer.
            try self.write("#include <string.h>\n");
            try self.write("static long long __fun_str_key_hash(const char* s) { long long h = 2166136261LL; if (s) { for (; *s; ++s) { h ^= (unsigned char)*s; if (h < 0) h = -h; h = (h % 1000000007LL) * 16777619LL % 1000000007LL; } } if (h < 0) h = -h; return h; }\n");
            try self.write("static long long __fun_bytes_key_hash(const void* p, unsigned long n) { long long h = 2166136261LL; const unsigned char* b = (const unsigned char*)p; for (unsigned long i = 0; i < n; ++i) { h ^= b[i]; if (h < 0) h = -h; h = (h % 1000000007LL) * 16777619LL % 1000000007LL; } if (h < 0) h = -h; return h; }\n\n");
        }
    }

    /// Emit the M:N cooperative task scheduler runtime used by the `fork` keyword.
    ///
    /// Design: a fixed pool of OS worker threads (sized to the CPU count) drains a
    /// shared FIFO task queue. Each `fork f(args)` enqueues one task — a function
    /// pointer plus a heap-allocated argument payload — which a worker pops and runs
    /// to completion. This is genuine M:N scheduling (many cheap `fork` tasks → a few
    /// OS threads), not one-thread-per-spawn. The pool is started lazily on the first
    /// fork; `__fun_sched_wait_idle()` (run at every `main` exit) blocks until every
    /// queued task has run. Cooperative, not preemptive: a task that blocks (e.g. on a
    /// channel op) holds its worker — the yield points are the blocking primitives.
