    /// Transpiles a node to C code
    /// Emit inner dimension specifiers `[N1][N2]...` for a multi-dimensional array
    /// literal. `outer_lit` is the Bracket node at the current level, `remaining`
    /// is how many inner dimensions still need to be emitted.
    fn emit_multidim_inner_declarators(self: *Self, outer_lit: *ast.Node, remaining: usize) TranspileError!void {
        if (remaining == 0 or outer_lit.type != .Bracket) return;

        var outer_elems = ArrayList(*ast.Node).init(self.allocator);
        defer outer_elems.deinit();
        try self.flatten_call_args_ptr(outer_lit.node_variant.?.bracket.inner, &outer_elems);

        if (outer_elems.items.len == 0 or outer_elems.items[0].type != .Bracket) return;

        const first_elem = outer_elems.items[0];
        var inner_elems = ArrayList(*ast.Node).init(self.allocator);
        defer inner_elems.deinit();
        try self.flatten_call_args_ptr(first_elem.node_variant.?.bracket.inner, &inner_elems);

        try self.write("[");
        try self.print("{d}", .{inner_elems.items.len});
        try self.write("]");

        if (remaining > 1) {
            try self.emit_multidim_inner_declarators(first_elem, remaining - 1);
        }
    }

    /// Emits the indexed-loop body for `for item : <arr_name>` over a Vec
    /// (`arr_name.len`/`arr_name.data[idx]`), given the already-resolved item
    /// type `vec_item_dt`. `arr_name` may name the iterable directly (the
    /// common case) or a temp variable a caller bound it to first (for an
    /// iterable that isn't a bare identifier -- see the `.iter` call site's
    /// own comment for why that's needed). Assumes the caller has already
    /// positioned the cursor at the start of a fresh, indented line.
    fn emit_vec_iter_fast_path(self: *Self, fi: anytype, arr_name: []const u8, vec_item_dt: *dtype.DataType) TranspileError!void {
        const idx_name = fi.index_name orelse "__fun_i";

        try self.write("for (int64_t ");
        try self.write(idx_name);
        try self.write(" = 0; ");
        try self.write(idx_name);
        try self.write(" < ");
        try self.write(arr_name);
        try self.write(".len; ");
        try self.write(idx_name);
        try self.write("++) {");
        self.indent();

        try self.push_defer_scope(.loop);
        defer self.pop_defer_scope();

        _ = try self.new_scope();
        defer self.finish_scope();

        try self.write_indent();
        try self.write_type(vec_item_dt.*);
        try self.write(" ");
        try self.write(fi.item_name);
        try self.write(" = ");
        try self.write(arr_name);
        try self.write(".data[");
        try self.write(idx_name);
        try self.write("];\n");

        const item_dt = try self.clone_dtype(vec_item_dt);
        const item_node = self.allocator.create(ast.Node) catch return TranspileError.MemoryAllocationFailed;
        var item_name_buf = ArrayList(u8).init(self.allocator);
        item_name_buf.appendSlice(fi.item_name) catch return TranspileError.MemoryAllocationFailed;
        item_node.* = .{
            .type = .Variable,
            .node_variant = .{ .variable = .{
                .type = item_dt,
                .name = item_name_buf,
                .val = null,
            } },
        };

        const item_ent = self.allocator.create(scope.ScopeEntity) catch return TranspileError.MemoryAllocationFailed;
        item_ent.* = .{
            .flags = .{ .on_stack = false },
            .node = item_node,
            .name = fi.item_name,
        };
        try self.push_scope_entity(item_ent);
        self.owned_scope_entities.append(item_ent) catch return TranspileError.MemoryAllocationFailed;

        try self.transpile_block_contents(fi.body);
        if (!self.block_ends_with_scope_terminator(fi.body)) {
            try self.emit_current_scope_defers();
        }

        self.dedent();
        try self.write_indent();
        try self.write("}");
    }

    fn transpile_node(self: *Self, node: ast.Node) TranspileError!void {
        if (self.recursion_depth >= max_expr_recursion_depth) {
            self.report_error(node, "expression nests too deeply for the compiler to emit (limit {d})", .{max_expr_recursion_depth});
            return TranspileError.ExpressionTooDeep;
        }
        self.recursion_depth += 1;
        defer self.recursion_depth -= 1;
        switch (node.type) {
            .Bracket => {
                // An array literal in a value position (e.g. a call argument
                // `f([10, 20])`) must be a C compound literal `(T[]){...}` — a bare
                // `{...}` is only valid as an initializer. In an initializer context
                // (`in_array_initializer`), emit the bare brace-list as before.
                const wrap_compound = !self.in_array_initializer;
                if (wrap_compound) {
                    if (self.bracket_element_c_type(node)) |elem_c| {
                        defer self.allocator.free(@constCast(elem_c));
                        try self.write("(");
                        try self.write(elem_c);
                        try self.write("[]){");
                    } else {
                        // Element type unresolved — fall back to a bare list (no worse
                        // than before; avoids emitting a malformed cast).
                        try self.write("{");
                    }
                } else {
                    try self.write("{");
                }
                const saved = self.in_array_initializer;
                self.in_array_initializer = true; // nested elements stay bare
                try self.transpile_node(node.node_variant.?.bracket.inner.*);
                self.in_array_initializer = saved;
                try self.write("}");
            },
            .CompoundInit => {
                const ci = node.node_variant.?.compound_init;
                const dt = ci.dtype orelse {
                    self.report_type_error(node, "compound initializer requires a concrete type", .{});
                    return TranspileError.TypeMismatch;
                };

                try self.write("(");
                try self.write_type(dt.*);
                try self.write("){");

                if (ci.fields.count == 0) {
                    try self.write("0");
                } else {
                    const target_compound_name = if (dt.type == .Unknown and dt.type_str.items.len > 0)
                        self.canonical_compound_name(dt.type_str.items)
                    else
                        "";

                    for (ci.fields.items(), 0..) |f, i| {
                        if (i > 0) try self.write(", ");
                        try self.write(".");
                        try self.write(f.name.items);
                        try self.write(" = ");

                        // Implicit quirk coercion for compound initializer fields,
                        // e.g. `Holder{ q = &c }` where `q` is a quirk-typed field.
                        const field_dt = if (target_compound_name.len > 0)
                            self.lookup_compound_field(target_compound_name, f.name.items)
                        else
                            null;
                        if (field_dt != null and field_dt.?.type == .Unknown and field_dt.?.pointer_depth == 0 and self.is_quirk_name(field_dt.?.type_str.items)) {
                            const reg = self.root_registry() orelse {
                                try self.transpile_node(f.value.*);
                                continue;
                            };
                            const sig = reg.quirk_sig_by_name.get(field_dt.?.type_str.items) orelse null;
                            if (sig != null) {
                                if (try self.pointee_quirk_impl_name(f.value.*, sig.?)) |ident| {
                                    defer self.allocator.free(@constCast(ident));
                                    const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(sig.?) });
                                    defer self.backing_allocator.free(coerce_name);
                                    try self.write(coerce_name);
                                    try self.write("(");
                                    try self.transpile_node(f.value.*);
                                    try self.write(")");
                                    continue;
                                }
                            }
                        }

                        // An array-literal value for an ARRAY-typed field must be a
                        // bare C brace-list `{...}` (a field initializer), not the
                        // compound-literal form `(T[]){...}` used in value positions.
                        const field_is_array = field_dt != null and field_dt.?.flags != null and field_dt.?.flags.?.is_array;
                        if (field_is_array and f.value.*.type == .Bracket) {
                            const saved = self.in_array_initializer;
                            self.in_array_initializer = true;
                            try self.transpile_node(f.value.*);
                            self.in_array_initializer = saved;
                            continue;
                        }

                        try self.transpile_node(f.value.*);
                    }
                }

                try self.write("}");
                return;
            },
            .Expression => {
                const exp = node.node_variant.?.exp;
                if (mem.eql(u8, exp.op, "()")) {
                    // Data-carrying enum construction `EnumName.Variant(args...)`
                    // lowers to a tagged-union compound literal.
                    if (exp.left) |callee| {
                        if (self.enum_variant_path(callee)) |path| {
                            if (self.lookup_enum_variant(path.enum_name, path.variant)) |variant| {
                                if (variant.payload != null) {
                                    // For a generic enum, the construction site uses a
                                    // monomorphized name: from a typecheck-recorded
                                    // override (`Option<num> x = Option.Some(..)`), or —
                                    // when the construction is INSIDE a monomorphized
                                    // generic method body (no per-site override exists,
                                    // only the template was typechecked) — from the
                                    // active type-parameter substitution. Else plain.
                                    const ctor_name = self.lookup_enum_ctor_override(node) orelse
                                        (self.mangled_enum_with_active_subst(path.enum_name) orelse path.enum_name);
                                    try self.emit_enum_variant_construction(ctor_name, path.variant, exp.right);
                                    return;
                                }
                            }
                        }
                    }
                    if (exp.left) |left| {
                        var callee_base_name: ?[]const u8 = null;
                        var callee_module_alias: ?[]const u8 = null;
                        if (left.type == .Identifier and left.data != null) {
                            callee_base_name = left.data.?.sval.items;
                        } else if (left.type == .Expression and left.node_variant != null and mem.eql(u8, left.node_variant.?.exp.op, ".")) {
                            const dot = left.node_variant.?.exp;
                            if (dot.right) |rhs| {
                                if (rhs.type == .Identifier and rhs.data != null) {
                                    callee_base_name = rhs.data.?.sval.items;
                                }
                            }
                            // Extract module alias from the left side of the dot (e.g. `io2` in `io2.print_fmt`).
                            if (dot.left) |lhs| {
                                if (lhs.type == .Identifier and lhs.data != null) {
                                    callee_module_alias = lhs.data.?.sval.items;
                                }
                            }
                        }

                        if (callee_base_name) |fname| {
                            const fname_base = if (std.mem.lastIndexOf(u8, fname, "__")) |sep| fname[sep + 2 ..] else fname;
                            if (mem.eql(u8, fname_base, "print_fmt") or mem.eql(u8, fname_base, "println_fmt")) {
                                const is_newline = mem.eql(u8, fname_base, "println_fmt");
                                if (try self.emit_print_fmt_literal(node, is_newline, exp.right, callee_module_alias)) {
                                    return;
                                }
                            }
                            if (mem.eql(u8, fname_base, "format")) {
                                if (try self.emit_format_literal(node, exp.right, callee_module_alias)) {
                                    return;
                                }
                            }
                        }
                    }

                    // Builtin: `sizeof(Type)`
                    // The argument is a type name, not a value expression.
                    if (exp.left) |left| {
                        if (left.type == .Identifier and left.data != null and mem.eql(u8, left.data.?.sval.items, "sizeof")) {
                            const right = exp.right orelse {
                                self.report_type_error(node, "sizeof expects exactly 1 argument", .{});
                                return TranspileError.InvalidSizeof;
                            };

                            const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                right.node_variant.?.paren.exp.*
                            else
                                right.*;

                            if (inner.type != .Identifier or inner.data == null) {
                                self.report_type_error(node, "sizeof argument must be a type name", .{});
                                return TranspileError.InvalidSizeof;
                            }

                            const type_name = inner.data.?.sval.items;
                            if (self.type_subst_params != null and self.type_subst_args != null) {
                                const params = self.type_subst_params.?.*;
                                const args = self.type_subst_args.?;
                                for (params.items(), 0..) |p, i| {
                                    if (mem.eql(u8, p.items, type_name)) {
                                        try self.write("(long long)(sizeof(");
                                        try self.write_type_no_subst(args[i].*);
                                        try self.write("))");
                                        return;
                                    }
                                }
                            }

                            // `sizeof(v)` where `v` is a value in scope: emit the C type
                            // of its declared dtype (mangled for generic instances, e.g.
                            // `Box__num`), not the variable name. Only a non-builtin,
                            // non-type identifier can be a value here (the type checker
                            // already accepted it).
                            if (!utils.keyword_is_datatype(type_name) and utils.get_datatype_type(type_name) == .Unknown) {
                                if (self.get_scope_entity(type_name)) |ent| {
                                    if (ent.node) |en| {
                                        if (en.type == .Variable and en.node_variant != null) {
                                            const vdt = en.node_variant.?.variable.type;
                                            try self.write("(long long)(sizeof(");
                                            // Use the variable's full C TYPE, not its mangled
                                            // Fun name: for a primitive (`num`/`str`/`dec`/...)
                                            // the raw keyword is not a C type, so `sizeof(num)`
                                            // failed to compile. `write_type` maps primitives
                                            // (num->int64_t), keeps compound names, and applies
                                            // pointer/array suffixes.
                                            try self.write_type(vdt.*);
                                            try self.write("))");
                                            return;
                                        }
                                    }
                                }
                            }

                            // A mangled generic type name (`Box__num`) is the concrete C
                            // struct name; emit it directly. A trailing pointer suffix
                            // (`num*`, `raw*` from `sizeof(num*)`) is split off, the base
                            // mapped, then the `*`s re-appended so we emit `int64_t*`.
                            var star_count: usize = 0;
                            var base_len = type_name.len;
                            while (base_len > 0 and type_name[base_len - 1] == '*') {
                                base_len -= 1;
                                star_count += 1;
                            }
                            const base_name = type_name[0..base_len];

                            // A generic instance name mangled at parse time (`Node__T`) can
                            // still carry a bare type param of the ENCLOSING constrained
                            // generic function/impl (`T`) when this `sizeof` sits inside
                            // that template body — `Node__T` is never emitted (only its
                            // monomorphized instances are), so re-mangle every `__`-joined
                            // segment that matches an active type param against the real
                            // substitution: `sizeof(Node<T>)` inside `fun make<T>(...)`
                            // then emits `Node__num`, not the undeclared `Node__T`.
                            var substituted_owned: ?[]u8 = null;
                            defer if (substituted_owned) |s| self.allocator.free(s);
                            const c_type_base: []const u8 = blk: {
                                if (self.type_subst_params == null or self.type_subst_args == null or mem.indexOf(u8, base_name, "__") == null) {
                                    break :blk base_name;
                                }
                                const params = self.type_subst_params.?.*;
                                const args = self.type_subst_args.?;
                                var buf = ArrayList(u8).init(self.allocator);
                                errdefer buf.deinit();
                                var it = mem.splitSequence(u8, base_name, "__");
                                var first = true;
                                var changed = false;
                                while (it.next()) |seg| {
                                    if (!first) buf.appendSlice("__") catch return TranspileError.MemoryAllocationFailed;
                                    first = false;
                                    var replaced = false;
                                    for (params.items(), 0..) |p, i| {
                                        if (!mem.eql(u8, p.items, seg)) continue;
                                        const m = self.type_name_mangled(args[i]) catch break;
                                        defer self.allocator.free(m);
                                        buf.appendSlice(m) catch return TranspileError.MemoryAllocationFailed;
                                        replaced = true;
                                        changed = true;
                                        break;
                                    }
                                    if (!replaced) buf.appendSlice(seg) catch return TranspileError.MemoryAllocationFailed;
                                }
                                if (!changed) {
                                    buf.deinit();
                                    break :blk base_name;
                                }
                                const owned = buf.toOwnedSlice() catch return TranspileError.MemoryAllocationFailed;
                                substituted_owned = owned;
                                break :blk owned;
                            };
                            const c_type = map_type_to_c(c_type_base);
                            try self.write("(long long)(sizeof(");
                            try self.write(c_type);
                            var si: usize = 0;
                            while (si < star_count) : (si += 1) try self.write("*");
                            try self.write("))");
                            return;
                        }
                    }

                    // Quirk method call: `q.method(...)` emits `q.vtable->method(q.self, ...)`.
                    if (exp.left) |left| {
                        if (left.type == .Expression and left.node_variant != null and mem.eql(u8, left.node_variant.?.exp.op, ".")) {
                            const force_dynamic_quirk_dispatch = if (self.lookup_await_call_override(node)) |ov|
                                ov.dynamic_quirk_dispatch
                            else
                                false;

                            const dot = left.node_variant.?.exp;
                            const recv = dot.left orelse null;
                            const member = dot.right orelse null;
                            if (recv != null and member != null and member.?.type == .Identifier and member.?.data != null) {
                                // Quirk method on a CALL RESULT, e.g. `make(&s).weight()`.
                                // The receiver is an rvalue (no name in scope), so vtable
                                // dispatch must materialize it once into a temp — emitting
                                // `recv` twice would evaluate the call twice. Lower to a
                                // statement-expression: `({ Q __t = recv; __t.vtable->m(__t.self, args); })`.
                                if (!force_dynamic_quirk_dispatch and !self.expr_is_quirk_typed_from_scope(recv.?.*)) {
                                    if (self.expr_call_return_quirk_name(recv.?.*)) |qname| {
                                        const mname = member.?.data.?.sval.items;
                                        const tmp = try self.next_tmp_name("qrecv");
                                        defer self.allocator.free(tmp);
                                        try self.write("({ ");
                                        try self.write(qname);
                                        try self.write(" ");
                                        try self.write(tmp);
                                        try self.write(" = ");
                                        try self.transpile_node(recv.?.*);
                                        try self.write("; ");
                                        try self.write(tmp);
                                        try self.write(".vtable->");
                                        try self.write(mname);
                                        try self.write("(");
                                        try self.write(tmp);
                                        try self.write(".self");
                                        if (exp.right) |right| {
                                            const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                right.node_variant.?.paren.exp.*
                                            else
                                                right.*;
                                            if (inner.type != .Blank) {
                                                try self.write(", ");
                                                try self.transpile_node(inner);
                                            }
                                        }
                                        try self.write("); })");
                                        return;
                                    }
                                }
                                // Special-case quirk method calls for any receiver expression
                                // we can resolve as quirk-typed from the current scope.
                                if (force_dynamic_quirk_dispatch or self.expr_is_quirk_typed_from_scope(recv.?.*)) {
                                    const mname = member.?.data.?.sval.items;
                                    const recv_is_identifier = recv.?.type == .Identifier;
                                    try self.write("(");
                                    if (recv_is_identifier) {
                                        try self.transpile_node(recv.?.*);
                                        try self.write(".vtable->");
                                    } else {
                                        try self.write("(");
                                        try self.transpile_node(recv.?.*);
                                        try self.write(").vtable->");
                                    }
                                    try self.write(mname);
                                    try self.write("(");
                                    if (recv_is_identifier) {
                                        try self.transpile_node(recv.?.*);
                                        try self.write(".self");
                                    } else {
                                        try self.write("(");
                                        try self.transpile_node(recv.?.*);
                                        try self.write(").self");
                                    }

                                    // Append call args.
                                    if (exp.right) |right| {
                                        // Right is an ExpressionParenthesis node.
                                        const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                            right.node_variant.?.paren.exp.*
                                        else
                                            right.*;
                                        if (inner.type != .Blank) {
                                            // Render arg expression(s) as a comma list.
                                            try self.write(", ");
                                            try self.transpile_node(inner);
                                        }
                                    }

                                    try self.write(")");
                                    try self.write(")");
                                    return;
                                }

                                // Plain impl method call on compounds: `x.method(...)`.
                                // `fbase` is usually a plain identifier (`x.field.method()`),
                                // but a receiver reached through a longer chain of field
                                // accesses (`a.b.field.method()`, e.g. `self.active_table.symbols.push(s)`)
                                // has `fbase` itself be a `.`-Expression. Resolve its owner
                                // type name via `expr_named_type_from_scope`, which already
                                // recurses through arbitrary-depth `.` chains (used elsewhere
                                // for chained-method return-type resolution) -- without this,
                                // only a SINGLE field hop before the method call was ever
                                // recognized as a method call at all; anything deeper fell
                                // through every case below and got emitted as a literal,
                                // uncompilable `.method(...)` (C has no member functions).
                                if (recv.?.type == .Expression and recv.?.node_variant != null and mem.eql(u8, recv.?.node_variant.?.exp.op, ".")) {
                                    const fexp = recv.?.node_variant.?.exp;
                                    const fbase = fexp.left orelse null;
                                    const fmember = fexp.right orelse null;
                                    const base_owner_type_name: ?[]const u8 = blk: {
                                        const fb = fbase orelse break :blk null;
                                        if (fb.type == .Identifier and fb.data != null) {
                                            const base_dt = self.identifier_declared_dtype(fb.data.?.sval.items) orelse break :blk null;
                                            if (base_dt.type != .Unknown or self.is_quirk_name(base_dt.type_str.items) or (base_dt.pointer_depth != 0 and base_dt.pointer_depth != 1)) break :blk null;
                                            break :blk base_dt.type_str.items;
                                        }
                                        break :blk self.expr_named_type_from_scope(fb.*);
                                    };
                                    if (fmember != null and fmember.?.type == .Identifier and fmember.?.data != null and base_owner_type_name != null) {
                                        const field_name = fmember.?.data.?.sval.items;
                                        {
                                            if (self.lookup_compound_field(base_owner_type_name.?, field_name)) |fdt| {
                                                const field_type = type_from_dtype(fdt);
                                                if (field_type.name != null and !self.is_quirk_name(field_type.name.?)) {
                                                    var type_name = field_type.name.?;
                                                    var owned_name = false;
                                                    if (fdt.generic_args != null) {
                                                        type_name = try self.type_name_mangled_for_emit(fdt);
                                                        owned_name = true;
                                                    }
                                                    const type_name_canon = self.canonical_compound_name(type_name);
                                                    const mname = member.?.data.?.sval.items;
                                                    // `fbase` may itself be an rvalue (e.g. a call in the
                                                    // middle of the chain: `found.unwrap().diagnostics`).
                                                    // `&(fbase.field)` is invalid C when `fbase` isn't an
                                                    // addressable lvalue, so materialize it into a temp first.
                                                    const fbase_addressable = self.expr_is_addressable_lvalue(fbase.?.*);

                                                    if (self.lookup_plain_impl_method_fn(&node, type_name_canon, mname)) |fn_name| {
                                                        if (!fbase_addressable) {
                                                            try self.emit_materialized_field_method_call(fbase.?.*, base_owner_type_name.?, field_name, field_type.pointer_depth != 0, fn_name, exp.right);
                                                            if (owned_name) self.allocator.free(@constCast(type_name));
                                                            return;
                                                        }
                                                        try self.write("(");
                                                        try self.write_module_impl_method_ref(fn_name);
                                                        try self.write("(");

                                                        if (field_type.pointer_depth == 0) {
                                                            try self.write("&(");
                                                            try self.transpile_node(recv.?.*);
                                                            try self.write(")");
                                                        } else {
                                                            try self.transpile_node(recv.?.*);
                                                        }

                                                        if (exp.right) |right| {
                                                            const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                                right.node_variant.?.paren.exp.*
                                                            else
                                                                right.*;
                                                            if (inner.type != .Blank) {
                                                                try self.write(", ");
                                                                try self.transpile_node(inner);
                                                            }
                                                        }

                                                        try self.write(")");
                                                        try self.write(")");
                                                        if (owned_name) self.allocator.free(@constCast(type_name));
                                                        return;
                                                    }

                                                    const qres = self.resolve_quirk_impl_method_for_concrete(node, type_name_canon, mname);
                                                    if (owned_name) self.allocator.free(@constCast(type_name));
                                                    if (!qres.ambiguous) {
                                                        if (qres.fn_name) |qfn_name| {
                                                            if (!fbase_addressable) {
                                                                try self.emit_materialized_field_method_call(fbase.?.*, base_owner_type_name.?, field_name, field_type.pointer_depth != 0, qfn_name, exp.right);
                                                                return;
                                                            }
                                                            try self.write("(");
                                                            try self.write_module_impl_method_ref(qfn_name);
                                                            try self.write("(");

                                                            if (field_type.pointer_depth == 0) {
                                                                try self.write("&(");
                                                                try self.transpile_node(recv.?.*);
                                                                try self.write(")");
                                                            } else {
                                                                try self.transpile_node(recv.?.*);
                                                            }

                                                            if (exp.right) |right| {
                                                                const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                                    right.node_variant.?.paren.exp.*
                                                                else
                                                                    right.*;
                                                                if (inner.type != .Blank) {
                                                                    try self.write(", ");
                                                                    try self.transpile_node(inner);
                                                                }
                                                            }

                                                            try self.write(")");
                                                            try self.write(")");
                                                            return;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }

                                // Plain-impl (or quirk-impl) method on a CALL RESULT
                                // (chaining), e.g. `b.add(2).get()`, `makeBox(7).get()`,
                                // or `make_vec().len()` where `len()` comes from `impl
                                // Vec<T> as Sized`. The receiver is an rvalue with no
                                // name in scope, so materialize it once into a temp
                                // (emitting it twice would re-run the call) and
                                // dispatch: `({ T __t = recv; (T__method(&__t, args)); })`.
                                if (recv.?.type != .Identifier) {
                                    if (self.expr_compound_return_type_name(recv.?.*)) |rtype| {
                                        const recv_canon = self.canonical_compound_name(rtype);
                                        const mname = member.?.data.?.sval.items;
                                        const plain_fn_name = self.lookup_plain_impl_method_fn(&node, recv_canon, mname);
                                        const quirk_res = if (plain_fn_name == null) self.resolve_quirk_impl_method_for_concrete(node, recv_canon, mname) else QuirkImplMethodResolution{};
                                        const fn_name = plain_fn_name orelse (if (!quirk_res.ambiguous) quirk_res.fn_name else null);
                                        if (fn_name) |resolved_fn_name| {
                                            const tmp = try self.next_tmp_name("mrecv");
                                            defer self.allocator.free(tmp);
                                            try self.write("({ ");
                                            try self.write(recv_canon);
                                            try self.write(" ");
                                            try self.write(tmp);
                                            try self.write(" = ");
                                            try self.transpile_node(recv.?.*);
                                            try self.write("; (");
                                            try self.write_module_impl_method_ref(resolved_fn_name);
                                            try self.write("(&");
                                            try self.write(tmp);
                                            if (exp.right) |right| {
                                                const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                    right.node_variant.?.paren.exp.*
                                                else
                                                    right.*;
                                                if (inner.type != .Blank) {
                                                    try self.write(", ");
                                                    try self.transpile_node(inner);
                                                }
                                            }
                                            try self.write(")); })");
                                            return;
                                        }
                                    }
                                }

                                if (recv.?.type == .Identifier and recv.?.data != null and !self.identifier_is_quirk_typed(recv.?.data.?.sval.items)) {
                                    const rname = recv.?.data.?.sval.items;
                                    const dt = self.identifier_declared_dtype(rname) orelse null;
                                    if (dt != null and dt.?.type == .Unknown and !self.is_quirk_name(dt.?.type_str.items) and (dt.?.pointer_depth == 0 or dt.?.pointer_depth == 1)) {
                                        var type_name: []const u8 = dt.?.type_str.items;
                                        var owned_name = false;
                                        if (dt.?.generic_args != null) {
                                            type_name = try self.type_name_mangled_for_emit(dt.?);
                                            owned_name = true;
                                        }
                                        const type_name_canon = self.canonical_compound_name(type_name);
                                        const mname = member.?.data.?.sval.items;
                                        // A method with its OWN type param (`pub map<U>(...)`)
                                        // was registered at typecheck time under a combined
                                        // name (`Box__num__map__str`) recorded as a call-site
                                        // override -- `lookup_plain_impl_method_fn` alone would
                                        // only ever find the un-substituted `Box__num__map`.
                                        if (self.lookup_generic_call_override(node) orelse self.lookup_plain_impl_method_fn(&node, type_name_canon, mname)) |fn_name| {
                                            try self.write("(");
                                            try self.write_module_impl_method_ref(fn_name);
                                            try self.write("(");

                                            if (dt.?.pointer_depth == 0) {
                                                try self.write("&");
                                                try self.transpile_node(recv.?.*);
                                            } else {
                                                try self.transpile_node(recv.?.*);
                                            }
                                            var c_args: usize = 1; // receiver

                                            if (exp.right) |right| {
                                                const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                    right.node_variant.?.paren.exp.*
                                                else
                                                    right.*;
                                                if (inner.type != .Blank) {
                                                    try self.write(", ");
                                                    try self.transpile_node(inner);
                                                    var ua = ArrayList(*ast.Node).init(self.allocator);
                                                    defer ua.deinit();
                                                    self.flatten_call_args_ptr(right, &ua) catch {};
                                                    c_args += ua.items.len;
                                                }
                                            }
                                            // Fill omitted trailing params with defaults.
                                            try self.emit_trailing_default_args_for_method(type_name_canon, mname, c_args);

                                            try self.write(")");
                                            try self.write(")");
                                            if (owned_name) self.allocator.free(@constCast(type_name));
                                            return;
                                        }

                                        // Also allow calling quirk-impl methods directly on concrete types.
                                        const qres = self.resolve_quirk_impl_method_for_concrete(node, type_name_canon, mname);
                                        if (owned_name) self.allocator.free(@constCast(type_name));
                                        if (!qres.ambiguous) {
                                            if (qres.fn_name) |qfn_name| {
                                                try self.write("(");
                                                try self.write_module_impl_method_ref(qfn_name);
                                                try self.write("(");

                                                if (dt.?.pointer_depth == 0) {
                                                    try self.write("&");
                                                    try self.transpile_node(recv.?.*);
                                                } else {
                                                    try self.transpile_node(recv.?.*);
                                                }

                                                if (exp.right) |right| {
                                                    const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                        right.node_variant.?.paren.exp.*
                                                    else
                                                        right.*;
                                                    if (inner.type != .Blank) {
                                                        try self.write(", ");
                                                        try self.transpile_node(inner);
                                                    }
                                                }

                                                try self.write(")");
                                                try self.write(")");
                                                return;
                                            }
                                        }

                                        // Quirk impl method call on `self` inside `impl Type as Quirk { ... }`.
                                        // `self.method()` is not a struct member call in C; emit a direct call to
                                        // the generated impl function when we can resolve it.
                                        if (mem.eql(u8, rname, "self")) {
                                            if (self.lookup_quirk_impl_method_fn_for_self(type_name_canon, mname)) |qfn_name| {
                                                try self.write("(");
                                                try self.write_module_impl_method_ref(qfn_name);
                                                try self.write("(");

                                                if (dt.?.pointer_depth == 0) {
                                                    try self.write("&");
                                                    try self.transpile_node(recv.?.*);
                                                } else {
                                                    try self.transpile_node(recv.?.*);
                                                }

                                                if (exp.right) |right| {
                                                    const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                                        right.node_variant.?.paren.exp.*
                                                    else
                                                        right.*;
                                                    if (inner.type != .Blank) {
                                                        try self.write(", ");
                                                        try self.transpile_node(inner);
                                                    }
                                                }

                                                try self.write(")");
                                                try self.write(")");
                                                return;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    if (exp.left) |left| {
                        var callee_base_name: ?[]const u8 = null;
                        if (left.type == .Identifier and left.data != null) {
                            callee_base_name = left.data.?.sval.items;
                        } else if (left.type == .Expression and left.node_variant != null and mem.eql(u8, left.node_variant.?.exp.op, ".")) {
                            const dot = left.node_variant.?.exp;
                            if (dot.right) |rhs| {
                                if (rhs.type == .Identifier and rhs.data != null) {
                                    callee_base_name = rhs.data.?.sval.items;
                                }
                            }
                        }

                        if (callee_base_name) |fname| {
                            const fname_base = if (std.mem.lastIndexOf(u8, fname, "__")) |sep| fname[sep + 2 ..] else fname;
                            // Type-aware map/set key intrinsics. In a monomorphized
                            // generic method the key type `K` is concrete here, so we
                            // pick string vs byte semantics: string keys compare/hash
                            // by CONTENTS (strcmp / FNV over chars), value keys by raw
                            // bytes. This is the fix for `Map<str>`/`Set<str>` keys
                            // that previously compared/hashed the POINTER.
                            if (mem.eql(u8, fname, "__fun_key_eq")) {
                                var ka = ArrayList(*ast.Node).init(self.allocator);
                                defer ka.deinit();
                                if (exp.right) |right| try self.flatten_call_args_ptr(right, &ka);
                                if (ka.items.len != 2) {
                                    self.report_error(node, "__fun_key_eq expects 2 arguments", .{});
                                    return;
                                }
                                if (self.arg_concrete_type_is_str(ka.items[0].*)) {
                                    try self.write("(strcmp((");
                                    try self.transpile_node(ka.items[0].*);
                                    try self.write("), (");
                                    try self.transpile_node(ka.items[1].*);
                                    try self.write(")) == 0)");
                                } else {
                                    try self.write("(memcmp(&(");
                                    try self.transpile_node(ka.items[0].*);
                                    try self.write("), &(");
                                    try self.transpile_node(ka.items[1].*);
                                    try self.write("), sizeof(");
                                    try self.transpile_node(ka.items[0].*);
                                    try self.write(")) == 0)");
                                }
                                return;
                            }
                            if (mem.eql(u8, fname, "__fun_key_hash")) {
                                var kh = ArrayList(*ast.Node).init(self.allocator);
                                defer kh.deinit();
                                if (exp.right) |right| try self.flatten_call_args_ptr(right, &kh);
                                if (kh.items.len != 1) {
                                    self.report_error(node, "__fun_key_hash expects 1 argument", .{});
                                    return;
                                }
                                if (self.arg_concrete_type_is_str(kh.items[0].*)) {
                                    try self.write("__fun_str_key_hash((");
                                    try self.transpile_node(kh.items[0].*);
                                    try self.write("))");
                                } else {
                                    try self.write("__fun_bytes_key_hash(&(");
                                    try self.transpile_node(kh.items[0].*);
                                    try self.write("), sizeof(");
                                    try self.transpile_node(kh.items[0].*);
                                    try self.write("))");
                                }
                                return;
                            }
                            if (mem.eql(u8, fname, "va_start") or mem.eql(u8, fname, "va_end") or mem.eql(u8, fname, "va_copy") or
                                mem.eql(u8, fname, "va_arg_num") or mem.eql(u8, fname, "va_arg_dec") or mem.eql(u8, fname, "va_arg_bin") or
                                mem.eql(u8, fname, "va_arg_chr") or mem.eql(u8, fname, "va_arg_str") or mem.eql(u8, fname, "va_arg_raw"))
                            {
                                var args_nodes = ArrayList(*ast.Node).init(self.allocator);
                                defer args_nodes.deinit();
                                if (exp.right) |right| {
                                    try self.flatten_call_args_ptr(right, &args_nodes);
                                }

                                if (mem.eql(u8, fname, "va_start")) {
                                    if (args_nodes.items.len != 2) {
                                        self.report_error(node, "va_start expects 2 arguments", .{});
                                        return;
                                    }
                                    try self.write("va_start(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", ");
                                    try self.transpile_node(args_nodes.items[1].*);
                                    try self.write(")");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_end")) {
                                    if (args_nodes.items.len != 1) {
                                        self.report_error(node, "va_end expects 1 argument", .{});
                                        return;
                                    }
                                    try self.write("va_end(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(")");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_copy")) {
                                    if (args_nodes.items.len != 2) {
                                        self.report_error(node, "va_copy expects 2 arguments", .{});
                                        return;
                                    }
                                    try self.write("va_copy(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", ");
                                    try self.transpile_node(args_nodes.items[1].*);
                                    try self.write(")");
                                    return;
                                }
                                if (args_nodes.items.len != 1) {
                                    self.report_error(node, "{s} expects 1 argument", .{fname});
                                    return;
                                }

                                if (mem.eql(u8, fname, "va_arg_num")) {
                                    try self.write("va_arg(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", long long)");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_arg_dec")) {
                                    try self.write("va_arg(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", double)");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_arg_bin")) {
                                    try self.write("(bool)va_arg(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", int)");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_arg_chr")) {
                                    try self.write("(char)va_arg(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", int)");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_arg_str")) {
                                    try self.write("va_arg(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", char*)");
                                    return;
                                }
                                if (mem.eql(u8, fname, "va_arg_raw")) {
                                    try self.write("va_arg(");
                                    try self.transpile_node(args_nodes.items[0].*);
                                    try self.write(", void*)");
                                    return;
                                }
                            }

                            const known_variadic_builtin = mem.eql(u8, fname_base, "print_fmt") or mem.eql(u8, fname_base, "println_fmt") or mem.eql(u8, fname_base, "format");

                            var callee_is_variadic = false;
                            var fixed_len: usize = 0;

                            if (self.find_function_node(fname)) |fn_node| {
                                if (fn_node.node_variant != null and fn_node.node_variant.?.function.is_variadic and !self.is_std_c_signature_node(fn_node)) {
                                    callee_is_variadic = true;
                                    const fnv = fn_node.node_variant.?.function;
                                    fixed_len = if (fnv.args) |a| a.count else 0;
                                }
                            } else if (!mem.eql(u8, fname_base, fname)) {
                                if (self.find_function_node(fname_base)) |fn_node| {
                                    if (fn_node.node_variant != null and fn_node.node_variant.?.function.is_variadic and !self.is_std_c_signature_node(fn_node)) {
                                        callee_is_variadic = true;
                                        const fnv = fn_node.node_variant.?.function;
                                        fixed_len = if (fnv.args) |a| a.count else 0;
                                    }
                                }
                            }

                            if (!callee_is_variadic and known_variadic_builtin) {
                                // format/print_fmt/println_fmt take at least the format string.
                                callee_is_variadic = true;
                                fixed_len = 1;
                            }

                            if (callee_is_variadic) {
                                var args_nodes = ArrayList(*ast.Node).init(self.allocator);
                                defer args_nodes.deinit();
                                if (exp.right) |right| {
                                    try self.flatten_call_args_ptr(right, &args_nodes);
                                }

                                const total_len: usize = args_nodes.items.len;
                                const var_len: usize = if (total_len > fixed_len) total_len - fixed_len else 0;

                                if (var_len == 0) {
                                    try self.transpile_node(left.*);
                                    try self.write("(");
                                    var idx0: usize = 0;
                                    while (idx0 < fixed_len) : (idx0 += 1) {
                                        if (idx0 > 0) try self.write(", ");
                                        try self.transpile_node(args_nodes.items[idx0].*);
                                    }
                                    if (fixed_len > 0) try self.write(", ");
                                    try self.write("(const char[]){0}");
                                    try self.write(")");
                                    return;
                                }

                                // Emit the variadic call without GNU ({}) statement expressions or
                                // __auto_type — both are GCC extensions rejected by MSVC. Instead,
                                // inline each variadic argument expression directly at its use sites
                                // (format-tag array and argument list). For display-typed args the
                                // display function is called inline; for plain args __fun_tag() is
                                // applied inline. Identifiers and field accesses (the vast majority of
                                // variadic args in practice) are side-effect-free so double-emission
                                // is safe. Complex expression args are emitted twice but correctness
                                // matters more than the rare double-evaluation edge case.
                                try self.transpile_node(left.*);
                                try self.write("(");
                                var i: usize = 0;
                                while (i < fixed_len) : (i += 1) {
                                    if (i > 0) try self.write(", ");
                                    try self.transpile_node(args_nodes.items[i].*);
                                }
                                if (fixed_len > 0) try self.write(", ");

                                // Format-tag array: 's' for display args, __fun_tag(expr) for plain.
                                try self.write("(const char[]){");
                                var v: usize = 0;
                                while (v < var_len) : (v += 1) {
                                    if (v > 0) try self.write(", ");
                                    const var_node = args_nodes.items[fixed_len + v].*;
                                    if (self.resolve_display_call_for_expr(node, var_node) != null) {
                                        try self.write("'s'");
                                    } else {
                                        try self.write("__fun_tag(");
                                        try self.emit_va_arg_expr(var_node);
                                        try self.write(")");
                                    }
                                }
                                if (var_len > 0) try self.write(", ");
                                try self.write("0}");

                                // Argument list: display_fn(&arg) for display args, arg for plain.
                                v = 0;
                                while (v < var_len) : (v += 1) {
                                    try self.write(", ");
                                    const var_node = args_nodes.items[fixed_len + v].*;
                                    if (self.resolve_display_call_for_expr(node, var_node)) |disp| {
                                        try self.write(disp.fn_name);
                                        try self.write("(");
                                        if (disp.pass_by_ref) try self.write("&");
                                        try self.emit_va_arg_expr(var_node);
                                        try self.write(")");
                                    } else {
                                        try self.emit_va_arg_expr(var_node);
                                    }
                                }
                                try self.write(")");
                                return;
                            }

                            if (self.lookup_generic_call_override(node)) |ov| {
                                try self.write(ov);
                                try self.write("(");
                                if (exp.right) |right| {
                                    try self.transpile_node(right.*);
                                }
                                try self.emit_trailing_default_args(node, left, exp.right);
                                try self.write(")");
                                return;
                            }

                            // Direct call-site quirk coercion: wrap concrete-pointer
                            // args passed to quirk-typed params. Returns false (and
                            // emits nothing) for calls that don't cross that
                            // boundary, so unrelated calls fall through unchanged.
                            if (try self.try_emit_call_with_quirk_coercion(node, fname, fname_base, left, exp.right)) {
                                return;
                            }
                        }
                        try self.transpile_node(left.*);
                        try self.write("(");
                        if (exp.right) |right| {
                            try self.transpile_node(right.*);
                        }
                        // Fill omitted trailing params with their default expressions.
                        try self.emit_trailing_default_args(node, left, exp.right);
                        try self.write(")");
                    }
                } else if (mem.eql(u8, exp.op, ",")) {
                    if (exp.left) |left| {
                        try self.transpile_node(left.*);
                    }
                    if (exp.right) |right| {
                        try self.write(", ");
                        try self.transpile_node(right.*);
                    }
                } else if (mem.eql(u8, exp.op, "[]")) {
                    if (exp.left) |left| {
                        try self.transpile_node(left.*);
                    }
                    try self.write("[");
                    if (exp.right) |right| {
                        if (right.type == .Bracket) {
                            try self.transpile_node(right.node_variant.?.bracket.inner.*);
                        } else {
                            try self.transpile_node(right.*);
                        }
                    }
                    try self.write("]");
                } else if (mem.eql(u8, exp.op, ".")) {
                    const left = exp.left orelse return;
                    const right = exp.right orelse return;

                    // Aliased enum variant constant:
                    // `alias.Enum.Variant` -> `alias__Enum_Variant` in C.
                    if (extract_alias_enum_variant_parts(left, right)) |parts| {
                        if (self.alias_map_for_node(&node).contains(parts.alias_name)) {
                            const qualified_enum = try self.make_alias_qualified_symbol_name(parts.alias_name, parts.enum_name);
                            defer self.allocator.free(qualified_enum);
                            if (self.root_registry()) |reg| {
                                if (reg.enums_by_name.get(qualified_enum)) |enode| {
                                    if (enode.node_variant == null) return;
                                    const emit_enum_name = enode.node_variant.?.enum_decl.name.items;
                                    try self.write(emit_enum_name);
                                    try self.write("_");
                                    try self.write(parts.variant_name);
                                    return;
                                }
                            }
                        }
                    }

                    // Module alias symbol access: `alias.symbol` -> `alias__symbol`.
                    if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                        const alias_name = left.*.data.?.sval.items;
                        const member_name = right.*.data.?.sval.items;
                        if (try self.resolve_alias_qualified_symbol_name(&node, alias_name, member_name)) |qualified| {
                            defer self.allocator.free(qualified);
                            try self.write(qualified);
                            return;
                        }
                    }

                    // Enum variant constant: `Enum.Variant` -> `Enum_Variant` in C.
                    if (left.*.type == .Identifier and left.*.data != null and right.*.type == .Identifier and right.*.data != null) {
                        const enum_name = left.*.data.?.sval.items;
                        const variant_name = right.*.data.?.sval.items;

                        var is_shadowed_by_variable = false;
                        if (self.get_scope_entity(enum_name)) |ent| {
                            if (ent.node) |ent_node| {
                                if (ent_node.type == .Variable) is_shadowed_by_variable = true;
                            }
                        }

                        if (!is_shadowed_by_variable) {
                            if (self.root_registry()) |reg| {
                                if (reg.enums_by_name.get(enum_name)) |enode| {
                                    if (enode.node_variant == null) return;
                                    const emit_enum_name = enode.node_variant.?.enum_decl.name.items;
                                    // In a tagged-union enum, a no-payload variant used
                                    // as a value must construct the struct with its tag
                                    // set: `((Enum){ .tag = Enum_Variant })`. The bare
                                    // `Enum_Variant` is only the discriminant constant.
                                    if (enum_is_tagged_union(enode.node_variant.?.enum_decl)) {
                                        // A generic enum's payload-free variant value
                                        // (`Option.None`) uses the monomorphized name:
                                        // a typecheck-recorded override, or the active
                                        // substitution inside a monomorphized method.
                                        const ctor_name = self.lookup_enum_ctor_override(node) orelse
                                            (self.mangled_enum_with_active_subst(emit_enum_name) orelse emit_enum_name);
                                        try self.write("((");
                                        try self.write(ctor_name);
                                        try self.write("){ .tag = ");
                                        try self.write(ctor_name);
                                        try self.write("_");
                                        try self.write(variant_name);
                                        try self.write(" })");
                                        return;
                                    }
                                    try self.write(emit_enum_name);
                                    try self.write("_");
                                    try self.write(variant_name);
                                    return;
                                }
                            }
                        }
                    }

                    try self.transpile_node(left.*);
                    const pd = self.expr_pointer_depth_from_scope(left.*);
                    try self.write(if (pd > 0) "->" else ".");
                    try self.transpile_node(right.*);
                } else if (mem.eql(u8, exp.op, "=")) {
                    // If assigning into a quirk-typed variable, coerce `T*` -> quirk when possible.
                    const left = exp.left orelse return;
                    const right = exp.right orelse return;
                    if (left.type == .Identifier and left.data != null and mem.eql(u8, left.data.?.sval.items, "_")) {
                        try self.write("(void)(");
                        try self.transpile_node(right.*);
                        try self.write(")");
                        return;
                    }
                    if (left.type == .Identifier and left.data != null) {
                        const lname = left.data.?.sval.items;
                        if (self.identifier_is_quirk_typed(lname)) {
                            const reg = self.root_registry() orelse {
                                try self.transpile_node(left.*);
                                try self.write(" = ");
                                try self.transpile_node(right.*);
                                return;
                            };
                            const ldt = self.identifier_declared_dtype(lname) orelse null;
                            const expected_sig = if (ldt != null) reg.quirk_sig_by_name.get(ldt.?.type_str.items) else null;
                            if (expected_sig != null) {
                                if (try self.pointee_quirk_impl_name(right.*, expected_sig.?)) |ident| {
                                    defer self.allocator.free(@constCast(ident));
                                    const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(expected_sig.?) });
                                    defer self.backing_allocator.free(coerce_name);
                                    try self.transpile_node(left.*);
                                    try self.write(" = ");
                                    try self.write(coerce_name);
                                    try self.write("(");
                                    try self.transpile_node(right.*);
                                    try self.write(")");
                                    return;
                                }
                            }
                        }
                    }
                    // Assigning into a quirk-typed struct FIELD: `obj.field = &concrete`
                    // where `field` is a quirk type. Coerce the concrete pointer.
                    if (left.type == .Expression and left.node_variant != null and
                        mem.eql(u8, left.node_variant.?.exp.op, "."))
                    {
                        if (self.expr_named_type_from_scope(left.*)) |ftype| {
                            if (self.is_quirk_name(ftype)) {
                                if (self.root_registry()) |reg| {
                                    if (reg.quirk_sig_by_name.get(ftype)) |esig| {
                                        if (try self.pointee_quirk_impl_name(right.*, esig)) |ident| {
                                            defer self.allocator.free(@constCast(ident));
                                            const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(esig) });
                                            defer self.backing_allocator.free(coerce_name);
                                            try self.transpile_node(left.*);
                                            try self.write(" = ");
                                            try self.write(coerce_name);
                                            try self.write("(");
                                            try self.transpile_node(right.*);
                                            try self.write(")");
                                            return;
                                        }
                                    }
                                }
                            }
                        }
                    }
                    // Assigning into a quirk-typed array element: `arr[i] = &concrete`
                    // where `arr` is a `Quirk[]`. Coerce the concrete pointer the same
                    // way as a quirk-typed scalar target.
                    if (left.type == .Expression and left.node_variant != null and
                        mem.eql(u8, left.node_variant.?.exp.op, "[]"))
                    {
                        const arr_left = left.node_variant.?.exp.left;
                        if (arr_left != null and arr_left.?.type == .Identifier and arr_left.?.data != null) {
                            if (self.identifier_declared_dtype(arr_left.?.data.?.sval.items)) |adt| {
                                if (adt.type == .Unknown and self.is_quirk_name(adt.type_str.items)) {
                                    if (self.root_registry()) |reg| {
                                        if (reg.quirk_sig_by_name.get(adt.type_str.items)) |esig| {
                                            if (try self.pointee_quirk_impl_name(right.*, esig)) |ident| {
                                                defer self.allocator.free(@constCast(ident));
                                                const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(esig) });
                                                defer self.backing_allocator.free(coerce_name);
                                                try self.transpile_node(left.*);
                                                try self.write(" = ");
                                                try self.write(coerce_name);
                                                try self.write("(");
                                                try self.transpile_node(right.*);
                                                try self.write(")");
                                                return;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    try self.transpile_node(left.*);
                    try self.write(" = ");
                    try self.transpile_node(right.*);
                } else if (exp.op.len > 0) {
                    if (exp.left) |left| {
                        try self.transpile_node(left.*);
                    }
                    // Special case: no space after reference operator '&' or '^' (address-of/reference)
                    if (mem.eql(u8, exp.op, "&") or mem.eql(u8, exp.op, "^")) {
                        try self.write(exp.op);
                        if (exp.right) |right| {
                            try self.transpile_node(right.*);
                        }
                    } else {
                        // Default: space before and after all other operators
                        try self.write(" ");
                        try self.write(exp.op);
                        try self.write(" ");
                        if (exp.right) |right| {
                            try self.transpile_node(right.*);
                        }
                    }
                } else if (exp.left) |left| {
                    try self.transpile_node(left.*);
                }
            },
            .ExpressionParenthesis => {
                const exp = node.node_variant.?.paren.exp;
                if (exp.*.type == .Blank) {
                    return;
                }
                if (exp.*.type == .Expression and exp.*.node_variant != null and mem.eql(u8, exp.*.node_variant.?.exp.op, ",")) {
                    try self.transpile_node(exp.*);
                } else {
                    try self.write("(");
                    try self.transpile_node(exp.*);
                    try self.write(")");
                }
            },
            .Number => {
                const d = node.data orelse {
                    try self.write("0");
                    return;
                };
                switch (d) {
                    .llnum => |v| try self.print("{d}", .{v}),
                    .lnum => |v| try self.print("{d}", .{v}),
                    .inum => |v| try self.print("{d}", .{v}),
                    .dnum => |v| try self.print("{e}", .{v}),
                    .cval => |v| try self.print("{d}", .{v}),
                    else => try self.write("0"),
                }
            },
            .Character => {
                const d = node.data orelse {
                    try self.write("'\\0'");
                    return;
                };
                const c: u8 = switch (d) {
                    .cval => |v| v,
                    else => 0,
                };
                try self.write("'");
                switch (c) {
                    '\\' => try self.write("\\\\"),
                    '\'' => try self.write("\\\'"),
                    '\n' => try self.write("\\n"),
                    '\r' => try self.write("\\r"),
                    '\t' => try self.write("\\t"),
                    0 => try self.write("\\0"),
                    else => {
                        if (c < 0x20 or c >= 0x7f) {
                            try self.print("\\x{x:0>2}", .{c});
                        } else {
                            var buf: [1]u8 = .{c};
                            try self.write(buf[0..]);
                        }
                    },
                }
                try self.write("'");
            },
            .String => {
                const str = node.data.?.sval.items;
                try self.write("\"");
                if (node.is_raw_string) {
                    try self.write_c_string_literal_body_from_raw(str);
                } else {
                    try self.write_c_string_literal_body(str);
                }
                try self.write("\"");
            },
            .Identifier => {
                const str = node.data.?.sval.items;
                // if (self.get_symbol(str) == null) {
                //     self.err("Symbol '{s}' not found", .{str});
                //     return TranspileError.SymbolNotDefined;
                // }
                if (self.import_alias) |alias| {
                    const shadowed_by_variable = if (self.get_scope_entity(str)) |ent|
                        if (ent.node) |ent_node| ent_node.type == .Variable else false
                    else
                        false;
                    if (!shadowed_by_variable) {
                        if (self.emit_module_proc) |mproc| {
                            if (!mem.eql(u8, str, "main") and self.module_has_function_named(mproc, str)) {
                                try self.write(alias);
                                try self.write("__");
                                try self.write(str);
                                return;
                            }
                        }

                        if (self.global_symbols.get(str)) |g| {
                            const current_emit_path = self.emit_input_file_path orelse self.input_file_path;
                            if (g.is_function and g.is_public and mem.eql(u8, g.file_path, current_emit_path) and !mem.eql(u8, str, "main")) {
                                try self.write(alias);
                                try self.write("__");
                                try self.write(str);
                                return;
                            }
                        }
                    }
                }
                // A reference to a Fun free function whose C name is shadow-renamed to
                // dodge a libc collision (see fun_fn_name_needs_c_shadow_rename) must emit
                // that renamed symbol here too, unless a local variable shadows the name.
                {
                    const shadowed_by_variable = if (self.get_scope_entity(str)) |ent|
                        if (ent.node) |ent_node| ent_node.type == .Variable else false
                    else
                        false;
                    if (!shadowed_by_variable and self.fun_fn_name_needs_c_shadow_rename(str)) {
                        try self.write("__fun_shadow__");
                        try self.write(str);
                        return;
                    }
                }
                try self.write(str);
            },
            .Variable => {
                const variable = node.node_variant.?.variable;

                // A function-TYPE parameter (`fun(T1, T2) R name`) needs C's
                // function-pointer declarator shape, which wraps the NAME
                // (`R (*name)(T1, T2)`) instead of following it like an
                // ordinary `Type name` declaration -- write it directly and
                // skip the rest of this case (no array/initializer handling
                // applies to a function-type parameter).
                if (variable.type.fn_sig) |sig| {
                    try self.write_type(sig.rtype.*);
                    try self.write(" (*");
                    try self.write(variable.name.items);
                    try self.write(")(");
                    for (sig.params.items(), 0..) |p, i| {
                        if (i > 0) try self.write(", ");
                        try self.write_type(p.*);
                    }
                    try self.write(")");
                    return;
                }

                // A local `T[]` variable initialized from a NON-array-literal rvalue
                // (a pointer/identifier/call, e.g. `num[] a = malloc(...)` — the
                // idiom for viewing heap memory as an array) must be emitted as a C
                // pointer `T* a = rhs`, not a C array `T a[] = rhs` (which is an
                // illegal "array initializer must be an initializer list").
                const array_as_pointer = blk: {
                    if (variable.type.flags == null or !variable.type.flags.?.is_array) break :blk false;
                    // Only the unsized `T[]` form (no explicit brackets, single dim).
                    const unsized = (variable.type.array == null or variable.type.array.?.brackets.is_empty()) and variable.type.array_depth <= 1;
                    if (!unsized) break :blk false;
                    const val = variable.val orelse break :blk false;
                    // An array literal initializer (`[..]`) stays a C array.
                    break :blk val.type != .Bracket;
                };

                // `const` on a POINTER-typed binding must land AFTER the
                // pointer star(s) (`Type* const name`, "the pointer itself
                // can't be reassigned") rather than before the base type
                // (`const Type* name`, "what it points to can't be mutated"
                // — a C pointer-to-const, a DIFFERENT and stricter guarantee
                // than what `const`'s own reassignment check enforces —
                // would wrongly reject legitimate writes through the
                // pointee). A non-pointer binding has no such ambiguity:
                // `const Type name` already means the whole value.
                const is_ptr_binding = variable.type.pointer_depth > 0 or
                    (variable.type.flags != null and variable.type.flags.?.is_pointer) or
                    array_as_pointer;
                if (variable.is_const and !is_ptr_binding) try self.write("const ");
                try self.write_type(variable.type.*);
                if (array_as_pointer) try self.write("*");
                if (variable.is_const and is_ptr_binding) try self.write(" const");
                try self.write(" ");
                try self.write(variable.name.items);

                // Array declarators come after the variable name in C.
                if (!array_as_pointer and variable.type.flags != null and variable.type.flags.?.is_array) {
                    if (variable.type.array) |array| {
                        if (!array.brackets.is_empty()) {
                            for (array.brackets.items()) |bracket_node| {
                                try self.write("[");
                                if (bracket_node.type == .Bracket) {
                                    try self.transpile_node(bracket_node.node_variant.?.bracket.inner.*);
                                } else {
                                    try self.transpile_node(bracket_node);
                                }
                                try self.write("]");
                            }
                        } else {
                            try self.write("[]");
                        }
                    } else if (variable.type.array_depth > 1) {
                        // Multi-dimensional unsized array: emit [][N1][N2]...
                        // The outer dim is always unsized (C deduces from initializer).
                        // Inner dims are derived from the literal.
                        try self.write("[]");
                        if (variable.val) |val| {
                            if (val.type == .Bracket) {
                                try self.emit_multidim_inner_declarators(val, variable.type.array_depth - 1);
                            } else {
                                var d: usize = 1;
                                while (d < variable.type.array_depth) : (d += 1) try self.write("[]");
                            }
                        } else {
                            var d: usize = 1;
                            while (d < variable.type.array_depth) : (d += 1) try self.write("[]");
                        }
                    } else {
                        try self.write("[]");
                    }
                }

                // A parameter's default value (`fun f(num x = 10)`) lives in `variable.val`
                // but must NOT be emitted into the C parameter list — C has no default
                // args. The default is materialized at each call site instead
                // (emit_trailing_default_args). So suppress the initializer in param position.
                if (self.in_function_params) {
                    return;
                }

                if (variable.val) |val| {
                    try self.write(" = ");

                    // Implicit quirk coercion in initializers: `Quirk q = &t;`.
                    // A CONCRETE instantiation of a generic quirk (`To<str> q =
                    // &t;`) registers under its MANGLED name (`To__str`, see
                    // `synthesize_quirk_instantiation`), not the bare `type_str`
                    // ("To", the unbound template) — mangle first so this finds it.
                    const var_quirk_name: ?[]const u8 = blk: {
                        if (variable.type.type != .Unknown) break :blk null;
                        if (variable.type.generic_args != null) {
                            const mangled = self.type_name_mangled(variable.type) catch break :blk null;
                            if (self.is_quirk_name(mangled)) break :blk mangled;
                            self.allocator.free(mangled);
                            break :blk null;
                        }
                        if (self.is_quirk_name(variable.type.type_str.items)) break :blk variable.type.type_str.items;
                        break :blk null;
                    };
                    defer if (var_quirk_name) |vqn| {
                        if (variable.type.generic_args != null) self.allocator.free(@constCast(vqn));
                    };
                    if (var_quirk_name) |vqn| {
                        const reg = self.root_registry() orelse {
                            try self.transpile_node(val.*);
                            if (!self.in_function_params) try self.write(";");
                            return;
                        };
                        const sig = reg.quirk_sig_by_name.get(vqn) orelse null;
                        if (sig != null) {
                            // `pointee_quirk_impl_name` uses the mangled instantiation
                            // name for generic pointees (e.g. `Box__num`) so the call
                            // matches the helper's definition name.
                            if (try self.pointee_quirk_impl_name(val.*, sig.?)) |ident| {
                                defer self.allocator.free(@constCast(ident));
                                const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(sig.?) });
                                defer self.backing_allocator.free(coerce_name);
                                try self.write(coerce_name);
                                try self.write("(");
                                try self.transpile_node(val.*);
                                try self.write(")");
                                if (!self.in_function_params) try self.write(";");
                                return;
                            }
                        }
                    }

                    if (val.type == .String) {
                        try self.write("\"");
                        if (val.is_raw_string) {
                            try self.write_c_string_literal_body_from_raw(val.data.?.sval.items);
                        } else {
                            try self.write_c_string_literal_body(val.data.?.sval.items);
                        }
                        try self.write("\"");
                    } else if (val.type == .Boolean) {
                        const bval = val.data.?.bval;
                        try self.write(if (bval) "true" else "false");
                    } else if (val.type == .Bracket and variable.type.flags != null and
                        variable.type.flags.?.is_array and variable.type.type == .Unknown and
                        self.is_quirk_name(variable.type.type_str.items))
                    {
                        // Quirk-typed array initializer `Q[] arr = [&p0, &p1]`: coerce
                        // each concrete-pointer element to the quirk fat-pointer. A
                        // CONCRETE instantiation of a generic quirk (`To<str>[]`)
                        // registers under its mangled name, not the bare `type_str`.
                        const qname = variable.type.type_str.items;
                        const arr_mangled: ?[]const u8 = if (variable.type.generic_args != null) (self.type_name_mangled(variable.type) catch null) else null;
                        defer if (arr_mangled) |m| self.allocator.free(m);
                        const sig = if (self.root_registry()) |reg| reg.quirk_sig_by_name.get(arr_mangled orelse qname) else null;
                        var els = ArrayList(*ast.Node).init(self.allocator);
                        defer els.deinit();
                        try self.flatten_call_args_ptr(val.node_variant.?.bracket.inner, &els);
                        try self.write("{");
                        for (els.items, 0..) |el, i| {
                            if (i > 0) try self.write(", ");
                            const ident_opt = if (sig) |s| try self.pointee_quirk_impl_name(el.*, s) else null;
                            if (ident_opt) |ident| {
                                defer self.allocator.free(@constCast(ident));
                                const coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(sig.?) });
                                defer self.backing_allocator.free(coerce_name);
                                try self.write(coerce_name);
                                try self.write("(");
                                try self.transpile_node(el.*);
                                try self.write(")");
                            } else {
                                try self.transpile_node(el.*);
                            }
                        }
                        try self.write("}");
                    } else if (val.type == .Bracket) {
                        // Array literal as a variable initializer: a bare C brace-list
                        // `{1, 2, 3}` (and nested `{{...}, {...}}` for multi-dim). Set
                        // `in_array_initializer` so nested rows stay bare instead of
                        // becoming compound literals.
                        const saved = self.in_array_initializer;
                        self.in_array_initializer = true;
                        try self.write("{");
                        try self.transpile_node(val.node_variant.?.bracket.inner.*);
                        try self.write("}");
                        self.in_array_initializer = saved;
                    } else {
                        try self.transpile_node(val.*);
                    }
                }
                if (!self.in_function_params) {
                    try self.write(";");
                }
            },
            .Function => {
                const function = node.node_variant.?.function;

                if (function.type_params != null and self.override_fn_name == null) {
                    return;
                }

                if (self.override_fn_name == null) {
                    if (self.function_has_unresolved_placeholder(node)) {
                        return;
                    }
                    if (function.name) |name| {
                        if (self.mangled_contains_unresolved_placeholder(name.items)) {
                            return;
                        }
                    }
                } else if (self.mangled_contains_unresolved_placeholder(self.override_fn_name.?)) {
                    return;
                }

                // Reset per-function defer state before emitting this function.
                self.reset_function_defer_state();

                const prev_fn_return = self.current_fn_return;
                defer self.current_fn_return = prev_fn_return;
                self.current_fn_return = if (function.rtype) |rt| type_from_dtype(&rt) else CheckedType{ .base = .Void };

                // Function scope (arguments live here; body gets its own nested scope).
                _ = try self.new_scope();
                defer self.finish_scope();

                if (function.is_async and function.name != null and !mem.eql(u8, function.name.?.items, "main")) {
                    try self.write_async_function_support_definitions(node);
                    try self.write("\n");
                }

                // Skip main functions in imported modules
                if (function.name != null and mem.eql(u8, function.name.?.items, "main")) {
                    // Only include main function from the main module (not from imported modules)
                    if (self.is_importing) {
                        return; // Skip this main function from an imported module
                    }

                    // Emit #line before the function signature when debug info is enabled.
                    if (self.flags.debug_info) {
                        if (node.pos) |pos| {
                            try self.write("#line ");
                            try self.print("{d}", .{pos.line});
                            try self.write(" \"");
                            for (pos.filename) |ch| {
                                if (ch == '\\') try self.write("\\\\") else try self.print("{c}", .{ch});
                            }
                            try self.write("\"\n");
                        }
                    }

                    try self.write("int");
                    try self.write(" ");
                    try self.write("main");

                    // Main parameter rules:
                    // - No params: emit standard `(int argc, char** argv)`.
                    // - Exactly one param of type `str[] name`: emit `(int argc, char** name)`.
                    //   This keeps the Fun surface as `main(str[] args)` (README style) while
                    //   still receiving OS argv.
                    // - Otherwise: emit user-declared params verbatim.
                    try self.write("(");

                    const args_vec_opt = function.args;
                    const argcnt: usize = if (args_vec_opt) |a| a.count else 0;

                    const is_single_str_array = blk: {
                        if (argcnt != 1) break :blk false;
                        const arg0 = args_vec_opt.?.items()[0];
                        if (arg0.type != .Variable or arg0.node_variant == null) break :blk false;
                        const dt = arg0.node_variant.?.variable.type.*;
                        if (!mem.eql(u8, dt.type_str.items, "str")) break :blk false;
                        if (dt.flags == null or !dt.flags.?.is_array) break :blk false;
                        break :blk true;
                    };

                    if (argcnt == 0) {
                        // Reserved names: a program may declare its own
                        // `argc` or `argv`, and naming a variable after what
                        // the program was given must not collide with the
                        // entry point's own parameters.
                        try self.write("int __fun_argc, char** __fun_argv");
                    } else if (is_single_str_array) {
                        // Register the Fun-visible param for later type queries.
                        const arg0 = args_vec_opt.?.items()[0];
                        try self.register_scope_variable(arg0);
                        self.in_function_params = true;
                        try self.write("int __fun_argc, ");
                        // `str[] args` prints as `char* args[]`, which is OK for argv.
                        try self.transpile_node(arg0.*);
                        self.in_function_params = false;
                    } else {
                        self.in_function_params = true;
                        if (function.args) |args| {
                            for (args.items(), 0..) |arg, i| {
                                if (i > 0) try self.write(", ");
                                if (arg.type == .Variable) {
                                    try self.register_scope_variable(arg);
                                }
                                try self.transpile_node(arg.*);
                            }
                        }
                        self.in_function_params = false;
                    }

                    try self.write(")");
                    if (function.body) |body| {
                        try self.write(" ");
                        const prev_in_main = self.in_main;
                        const prev_in_fn_body = self.in_function_body;
                        const prev_body_depth = self.function_body_depth;
                        self.in_main = true;
                        self.in_function_body = true;
                        self.function_body_depth = 0;
                        defer {
                            self.in_main = prev_in_main;
                            self.in_function_body = prev_in_fn_body;
                            self.function_body_depth = prev_body_depth;
                        }
                        try self.transpile_node(body.*);
                    } else {
                        try self.write(";");
                    }
                } else {
                    // Emit #line before the function signature when debug info is enabled.
                    if (self.flags.debug_info) {
                        if (node.pos) |pos| {
                            try self.write("#line ");
                            try self.print("{d}", .{pos.line});
                            try self.write(" \"");
                            for (pos.filename) |ch| {
                                if (ch == '\\') try self.write("\\\\") else try self.print("{c}", .{ch});
                            }
                            try self.write("\"\n");
                        }
                    }
                    if (function.rtype) |rtype| {
                        try self.write_return_type(rtype);
                    } else {
                        try self.write("void");
                    }
                    try self.write(" ");
                    if (function.name) |name| {
                        try self.write_effective_function_name(node, name.items);
                    }
                    try self.write("(");
                    self.in_function_params = true;
                    var wrote_any_param = false;
                    if (function.args) |args| {
                        for (args.items(), 0..) |arg, i| {
                            if (i > 0) try self.write(", ");
                            // Make args visible for later type queries.
                            if (arg.type == .Variable) {
                                try self.register_scope_variable(arg);
                            }
                            try self.transpile_node(arg.*);
                            wrote_any_param = true;
                        }
                    }
                    if (function.is_variadic) {
                        if (wrote_any_param) try self.write(", ");
                        try self.write("const char* __fun_vtags");
                        try self.write(", ...");
                    }
                    self.in_function_params = false;
                    try self.write(")");

                    if (function.body) |body| {
                        try self.write(" ");
                        const prev_in_fn_body = self.in_function_body;
                        const prev_body_depth = self.function_body_depth;
                        const prev_var = self.current_fn_is_variadic;
                        self.in_function_body = true;
                        self.function_body_depth = 0;
                        self.current_fn_is_variadic = function.is_variadic;
                        defer {
                            self.in_function_body = prev_in_fn_body;
                            self.function_body_depth = prev_body_depth;
                            self.current_fn_is_variadic = prev_var;
                        }
                        try self.transpile_node(body.*);
                    } else {
                        try self.write(";");
                    }
                }
            },
            .Body => {
                const body = node.node_variant.?.body;

                const is_fn_body = self.in_function_body and self.function_body_depth == 0;
                const scope_kind: DeferScopeKind = if (is_fn_body) .function else .normal;
                if (self.in_function_body) self.function_body_depth += 1;
                defer {
                    if (self.in_function_body) self.function_body_depth -= 1;
                }

                // Each body introduces a new scope.
                _ = try self.new_scope();
                defer self.finish_scope();

                try self.push_defer_scope(scope_kind);
                defer self.pop_defer_scope();

                try self.write("{");
                self.indent();
                if (is_fn_body and self.current_fn_is_variadic) {
                    try self.write("\n");
                    try self.write_indent();
                    try self.write("Vec__str vargs;\n");
                    try self.write_indent();
                    try self.write("vargs.len = 0; vargs.cap = 0; vargs.data = NULL;\n");
                    try self.write_indent();
                    try self.write("if (__fun_vtags) {\n");
                    self.indent();
                    try self.write_indent();
                    try self.write("size_t __fun_vc = 0; while (__fun_vtags[__fun_vc] != 0) { __fun_vc++; }\n");
                    try self.write_indent();
                    try self.write("vargs.len = (long long)__fun_vc; vargs.cap = (long long)__fun_vc;\n");
                    try self.write_indent();
                    try self.write("if (__fun_vc > 0) { vargs.data = (char**)malloc(sizeof(char*) * __fun_vc); }\n");
                    try self.write_indent();
                    try self.write("va_list __fun_ap; va_start(__fun_ap, __fun_vtags);\n");
                    try self.write_indent();
                    try self.write("size_t __fun_vi = 0; while (__fun_vi < __fun_vc) {\n");
                    self.indent();
                    try self.write_indent();
                    try self.write("char __fun_tagc = __fun_vtags[__fun_vi];\n");
                    try self.write_indent();
                    try self.write("switch (__fun_tagc) {\n");
                    self.indent();
                    try self.write_indent();
                    try self.write("case 's': vargs.data[__fun_vi] = va_arg(__fun_ap, char*); break;\n");
                    try self.write_indent();
                    try self.write("case 'n': vargs.data[__fun_vi] = ");
                    try self.write_module_function_ref("fmt_num");
                    try self.write("((long long)va_arg(__fun_ap, long long)); break;\n");
                    try self.write_indent();
                    try self.write("case 'd': vargs.data[__fun_vi] = ");
                    try self.write_module_function_ref("fmt_dec");
                    try self.write("((double)va_arg(__fun_ap, double)); break;\n");
                    try self.write_indent();
                    try self.write("case 'b': vargs.data[__fun_vi] = ");
                    try self.write_module_function_ref("fmt_bin");
                    try self.write("((bool)va_arg(__fun_ap, int)); break;\n");
                    try self.write_indent();
                    try self.write("case 'c': vargs.data[__fun_vi] = ");
                    try self.write_module_function_ref("fmt_chr");
                    try self.write("((char)va_arg(__fun_ap, int)); break;\n");
                    try self.write_indent();
                    try self.write("case 'p': vargs.data[__fun_vi] = ");
                    try self.write_module_function_ref("fmt_raw");
                    try self.write("((void*)va_arg(__fun_ap, void*)); break;\n");
                    try self.write_indent();
                    try self.write("default: vargs.data[__fun_vi] = ");
                    try self.write_module_function_ref("fmt_raw");
                    try self.write("((void*)va_arg(__fun_ap, void*)); break;\n");
                    self.dedent();
                    try self.write_indent();
                    try self.write("}\n");
                    try self.write_indent();
                    try self.write("__fun_vi = __fun_vi + 1;\n");
                    self.dedent();
                    try self.write_indent();
                    try self.write("}\n");
                    try self.write_indent();
                    try self.write("va_end(__fun_ap);\n");
                    self.dedent();
                    try self.write_indent();
                    try self.write("}\n");
                }
                for (body.statements.items()) |statement| {
                    try self.transpile_statement_in_current_scope(statement);
                }
                self.dedent();
                const body_statements = body.statements.items();
                if (body_statements.len == 0 or !node_is_scope_terminator(body_statements[body_statements.len - 1])) {
                    try self.emit_current_scope_defers();
                    // Drain forked tasks at main's implicit fall-off end.
                    try self.emit_fork_wait_idle_if_main();
                }
                try self.write_indent();
                try self.write("}");
            },
            .StatementReturn, .StatementDefer, .StatementAsm, .StatementIf, .StatementElseIf, .StatementElse, .StatementFit, .StatementFor, .StatementAssert, .StatementWarningControl, .StatementFork => {
                // `ret;` is represented as StatementReturn with no node_variant.
                if (node.type == .StatementReturn and node.node_variant == null) {
                    try self.emit_function_scope_defers();
                    try self.emit_fork_wait_idle_if_main();
                    if (self.flags.debug_info) {
                        self.pending_line_directive = node.pos;
                    }
                    try self.write_indent();
                    if (self.in_main) {
                        // `main` always emits as `int main(...)` in C.
                        // For default-void `main`, bare `ret;` maps to success status 0.
                        // For `main() num`, typecheck rejects bare `ret;`, but keep 0 as fallback.
                        try self.write("return 0;");
                    } else {
                        try self.write("return;");
                    }
                    return;
                }

                const statement = node.node_variant.?.statement;
                switch (statement) {
                    .defer_stmt => |d| {
                        try self.register_scope_defer(d.body, node.pos);
                    },
                    .asm_stmt => |a| {
                        // Validate optional arch selection.
                        if (a.arch) |arch_name| {
                            const arch_ok = blk: {
                                const arch = builtin.target.cpu.arch;
                                if (mem.eql(u8, arch_name.items, "x86_64") or mem.eql(u8, arch_name.items, "amd64")) {
                                    break :blk arch == .x86_64;
                                }
                                if (mem.eql(u8, arch_name.items, "x86") or mem.eql(u8, arch_name.items, "i386")) {
                                    break :blk arch == .x86;
                                }
                                if (mem.eql(u8, arch_name.items, "aarch64") or mem.eql(u8, arch_name.items, "arm64")) {
                                    break :blk arch == .aarch64;
                                }
                                if (mem.eql(u8, arch_name.items, "arm")) {
                                    break :blk arch == .arm;
                                }
                                break :blk false;
                            };
                            if (!arch_ok) {
                                self.report_error(node, "asm arch '{s}' does not match target", .{arch_name.items});
                                return TranspileError.InvalidAsm;
                            }
                        }

                        const escapeAsm = struct {
                            fn call(w: *Self, text: []const u8) TranspileError!void {
                                for (text) |ch| {
                                    switch (ch) {
                                        '\\' => try w.write("\\\\"),
                                        '"' => try w.write("\\\""),
                                        '\n' => try w.write("\\n"),
                                        '\r' => try w.write("\\r"),
                                        '\t' => try w.write("\\t"),
                                        0 => try w.write("\\0"),
                                        else => {
                                            var buf: [1]u8 = .{ch};
                                            try w.write(buf[0..]);
                                        },
                                    }
                                }
                            }
                        }.call;

                        try self.write_indent();
                        try self.write("__asm__");
                        if (a.is_volatile) {
                            try self.write(" __volatile__");
                        }
                        try self.write("(\"");
                        try escapeAsm(self, a.template.items);
                        try self.write("\"");

                        const has_outputs = a.outputs.items().len != 0;
                        const has_inputs = a.inputs.items().len != 0;
                        const has_clobbers = a.clobbers.items().len != 0;

                        if (has_outputs or has_inputs or has_clobbers) {
                            try self.write(" : ");
                            if (has_outputs) {
                                var first = true;
                                for (a.outputs.items()) |op| {
                                    if (!first) try self.write(", ");
                                    first = false;
                                    try self.write("[");
                                    try self.write(op.name.items);
                                    try self.write("] \"");
                                    try escapeAsm(self, op.constraint.items);
                                    try self.write("\"(");
                                    try self.transpile_node(op.expr.*);
                                    try self.write(")");
                                }
                            }

                            if (has_inputs or has_clobbers) {
                                try self.write(" : ");
                                if (has_inputs) {
                                    var first_in = true;
                                    for (a.inputs.items()) |op| {
                                        if (!first_in) try self.write(", ");
                                        first_in = false;
                                        try self.write("[");
                                        try self.write(op.name.items);
                                        try self.write("] \"");
                                        try escapeAsm(self, op.constraint.items);
                                        try self.write("\"(");
                                        try self.transpile_node(op.expr.*);
                                        try self.write(")");
                                    }
                                }

                                if (has_clobbers) {
                                    try self.write(" : ");
                                    var first_cl = true;
                                    for (a.clobbers.items()) |cl| {
                                        if (!first_cl) try self.write(", ");
                                        first_cl = false;
                                        try self.write("\"");
                                        try escapeAsm(self, cl.items);
                                        try self.write("\"");
                                    }
                                }
                            }
                        }

                        try self.write(");");
                    },
                    .if_stmt => |if_s| {
                        try self.write("if (");
                        try self.transpile_node(if_s.condition.*);
                        try self.write(") ");
                        try self.transpile_scoped_block(if_s.body, .normal);
                    },
                    .elif_stmt => |elif| {
                        try self.write("else if (");
                        try self.transpile_node(elif.condition.*);
                        try self.write(") ");
                        try self.transpile_scoped_block(elif.body, .normal);
                    },
                    .else_stmt => |else_s| {
                        try self.write("else ");
                        try self.transpile_scoped_block(else_s.body, .normal);
                    },
                    .return_stmt => |rn| {
                        // `ret panic("msg");` never actually returns a value (it prints
                        // the message and aborts), so bypass the whole return-value
                        // machinery below (defers/main/fork/quirk-coercion) entirely --
                        // same "abort now, no cleanup" semantics as `assert`'s codegen.
                        if (rn.*.type == .Panic) {
                            try self.write_indent();
                            try self.write_panic_message_and_abort(rn.*.node_variant.?.panic_expr.message.*);
                            return;
                        }
                        // A `ret <expr>` must compute its value BEFORE the defers run,
                        // because a defer may mutate a variable the expression reads
                        // (`num x = 5; defer x = 999; ret x + 1;` must return 6, not
                        // 1000). When defers are pending and there is a value, snapshot
                        // it into a temp, run the defers, then return the temp.
                        const has_defers = self.has_pending_function_defers();
                        if (self.flags.debug_info) {
                            self.pending_line_directive = node.pos;
                        }

                        if (self.in_main) {
                            const main_ret = self.current_fn_return orelse CheckedType{ .base = .Void };
                            if (main_ret.base == .Num and !main_ret.is_array and main_ret.pointer_depth == 0) {
                                if (has_defers) {
                                    const tmp = try self.next_tmp_name("ret");
                                    defer self.allocator.free(tmp);
                                    try self.write_indent();
                                    try self.write("int ");
                                    try self.write(tmp);
                                    try self.write(" = (int)(");
                                    try self.transpile_node(rn.*);
                                    try self.write(");");
                                    try self.emit_function_scope_defers();
                                    // Drain forked tasks before main returns its value.
                                    try self.emit_fork_wait_idle_if_main();
                                    try self.write_indent();
                                    try self.write("return ");
                                    try self.write(tmp);
                                    try self.write(";");
                                } else {
                                    // Snapshot the value before draining the scheduler so
                                    // the return expression isn't ordered after wait-idle.
                                    if (self.uses_fork) {
                                        const tmp = try self.next_tmp_name("ret");
                                        defer self.allocator.free(tmp);
                                        try self.write_indent();
                                        try self.write("int ");
                                        try self.write(tmp);
                                        try self.write(" = (int)(");
                                        try self.transpile_node(rn.*);
                                        try self.write(");");
                                        try self.emit_fork_wait_idle_if_main();
                                        try self.write_indent();
                                        try self.write("return ");
                                        try self.write(tmp);
                                        try self.write(";");
                                    } else {
                                        try self.write_indent();
                                        try self.write("return (int)(");
                                        try self.transpile_node(rn.*);
                                        try self.write(");");
                                    }
                                }
                            } else {
                                try self.emit_function_scope_defers();
                                try self.emit_fork_wait_idle_if_main();
                                try self.write_indent();
                                // Default-void main ignores expression and returns success.
                                try self.write("return 0;");
                            }
                            return;
                        }

                        const ret_t = self.current_fn_return orelse CheckedType{ .base = .Void };

                        // Resolve quirk-coercion of the return value first.
                        var coerce_name: ?[]u8 = null;
                        defer if (coerce_name) |cn| self.backing_allocator.free(cn);
                        if (self.is_quirk_named_type(ret_t)) {
                            if (self.root_registry()) |reg| {
                                if (reg.quirk_sig_by_name.get(ret_t.name.?)) |sig| {
                                    if (try self.pointee_quirk_impl_name(rn.*, sig)) |ident| {
                                        defer self.allocator.free(@constCast(ident));
                                        coerce_name = try self.c_name_alloc("__fun_coerce_{s}_{x}", .{ ident, self.quirk_sig_hash_cached(sig) });
                                    }
                                }
                            }
                        }

                        if (has_defers and ret_t.base != .Void) {
                            // Snapshot the (possibly coerced) value, run defers, return.
                            // Prefer an explicit C type over __auto_type (GCC-only). For
                            // primitive/concrete return types checked_type_to_dtype gives
                            // a usable dtype. For un-monomorphized generics (e.g. `Vec<T>`
                            // where `write_type` would emit the abstract `Vec__T`), fall
                            // back to __auto_type so at least GCC/Clang still work; MSVC
                            // support for that case requires deeper monomorphization tracking.
                            const tmp = try self.next_tmp_name("ret");
                            defer self.allocator.free(tmp);
                            try self.write_indent();
                            // Only use explicit type for primitive return types (Num, Str, Bin,
                            // Dec, Chr). Compound/Unknown types risk emitting un-monomorphized
                            // names like `Vec` instead of `Vec__str`; __auto_type stays correct
                            // for those on GCC/Clang.
                            const ret_dtype_opt = try self.checked_type_to_dtype(ret_t);
                            const use_explicit_type = ret_t.base != .Unknown and ret_dtype_opt != null;
                            if (use_explicit_type) {
                                try self.write_type(ret_dtype_opt.?.*);
                                try self.write(" ");
                            } else {
                                try self.write("__auto_type ");
                            }
                            try self.write(tmp);
                            try self.write(" = ");
                            if (coerce_name) |cn| {
                                try self.write(cn);
                                try self.write("(");
                                try self.transpile_node(rn.*);
                                try self.write(")");
                            } else {
                                try self.transpile_node(rn.*);
                            }
                            try self.write(";");
                            try self.emit_function_scope_defers();
                            try self.write_indent();
                            try self.write("return ");
                            try self.write(tmp);
                            try self.write(";");
                        } else {
                            try self.emit_function_scope_defers();
                            try self.write_indent();
                            if (coerce_name) |cn| {
                                try self.write("return ");
                                try self.write(cn);
                                try self.write("(");
                                try self.transpile_node(rn.*);
                                try self.write(");");
                            } else {
                                try self.write("return ");
                                try self.transpile_node(rn.*);
                                try self.write(";");
                            }
                        }
                    },
                    .assert_stmt => |asrt| {
                        try self.write_indent();
                        try self.write("if (!(");
                        try self.transpile_node(asrt.condition.*);
                        try self.write(")) { ");
                        if (asrt.message) |msg| {
                            try self.write("fprintf(stderr, \"Assertion failed at ");
                            if (node.pos) |p| {
                                try self.print("{s}:{d}: ", .{ p.filename, p.line });
                            }
                            try self.write("%s\\n\", ");
                            try self.transpile_node(msg.*);
                            try self.write("); ");
                        }
                        // In test mode, a failing assertion must not take down
                        // the whole runner -- it jumps back to the currently
                        // running test's own dispatch point instead (see
                        // transpile_prelude's `__fun_test_jmp` doc comment),
                        // so tests after this one still run. Outside test
                        // mode, an assertion failure is a real program bug;
                        // abort() (the original behavior) is still correct
                        // there.
                        if (self.flags.test_mode) {
                            try self.write("longjmp(__fun_test_jmp, 1); }");
                        } else {
                            try self.write("abort(); }");
                        }
                    },
                    .warning_ctrl => |ctrl| {
                        // Warning control was already queued during the typecheck pass;
                        // here we only emit the C comment marker.
                        try self.write("/* ");
                        try self.write(@tagName(ctrl.action));
                        try self.write(" ");
                        try self.write(ast.warning_id_to_string(ctrl.id));
                        try self.write(" */");
                    },
                    .for_stmt => |for_s| {
                        switch (for_s) {
                            .cond => |fc| {
                                if (fc.condition) |cond| {
                                    try self.write("while (");
                                    try self.transpile_node(cond.*);
                                    try self.write(") ");
                                } else {
                                    try self.write("while (1) ");
                                }
                                try self.transpile_scoped_block(fc.body, .loop);
                            },
                            .range => |fr| {
                                if (fr.range.type != .Expression or !mem.eql(u8, fr.range.node_variant.?.exp.op, "..")) {
                                    return TranspileError.UnsupportedNodeType;
                                }
                                const range_exp = fr.range.node_variant.?.exp;
                                const start = range_exp.left orelse return TranspileError.UnsupportedNodeType;
                                const end = range_exp.right orelse return TranspileError.UnsupportedNodeType;

                                try self.write("for (int64_t ");
                                try self.write(fr.index_name);
                                try self.write(" = ");
                                try self.transpile_node(start.*);
                                try self.write("; ");
                                try self.write(fr.index_name);
                                try self.write(" < ");
                                try self.transpile_node(end.*);
                                try self.write("; ");
                                try self.write(fr.index_name);
                                try self.write("++) ");
                                try self.transpile_scoped_block(fr.body, .loop);
                            },
                            .iter => |fi| iter_blk: {
                                // Iterator-protocol path (Map/Set/user types/iterators):
                                // any non-array, non-Vec iterable whose type drives the
                                // Iterator protocol is lowered to a next()/Option loop.
                                // Vec and raw arrays keep their direct indexed fast path
                                // below. The iterable may be any expression here (an
                                // identifier or a call like `m.iter()`), not just a name.
                                if (try self.emit_iter_protocol_for(fi)) {
                                    break :iter_blk;
                                }
                                // A Vec-typed iterable that ISN'T a bare identifier (a
                                // field access, a call, ...): the raw-array fast path
                                // below needs a real identifier (its length comes from
                                // a `sizeof`-based trick that only works on a genuine
                                // C array variable), but the Vec fast path only needs
                                // `.len`/`.data[idx]`, which work identically on any
                                // Vec-typed value. Resolved via typecheck's override
                                // (see `ForIterInfo`'s doc comment) instead of a scope-
                                // entity lookup by name, since there's no name here.
                                // The iterable is evaluated ONCE into a temp so a
                                // side-effecting expression (a call) isn't re-evaluated
                                // for both the length check and the element access.
                                if (fi.iterable.type != .Identifier) {
                                    const over = self.lookup_for_iter_override(node) orelse {
                                        self.err("for-each loops currently require an array identifier (a Vec-typed expression is also supported)", .{});
                                        return TranspileError.UnsupportedNodeType;
                                    };
                                    const vec_item_dt = over.vec_item_dt orelse {
                                        self.err("for-each loops over a raw array currently require an array identifier", .{});
                                        return TranspileError.UnsupportedNodeType;
                                    };
                                    const tmp_name = try self.next_tmp_name("iter");
                                    try self.write("__auto_type ");
                                    try self.write(tmp_name);
                                    try self.write(" = ");
                                    try self.transpile_node(fi.iterable.*);
                                    try self.write(";\n");
                                    try self.write_indent();
                                    try self.emit_vec_iter_fast_path(fi, tmp_name, vec_item_dt);
                                    break :iter_blk;
                                }
                                const arr_name = fi.iterable.data.?.sval.items;

                                const idx_name = fi.index_name orelse "__fun_i";

                                var vec_item_dt: ?*dtype.DataType = null;

                                // Determine array depth and multidim info from scope.
                                var arr_depth: usize = 1;
                                var mdim_root: ?[]const u8 = null;
                                var mdim_depth: usize = 0;
                                if (self.get_scope_entity(arr_name)) |arr_ent| {
                                    mdim_root = arr_ent.multidim_root;
                                    mdim_depth = arr_ent.multidim_depth;
                                    if (arr_ent.node) |arr_node| {
                                        if (arr_node.type == .Variable and arr_node.node_variant != null) {
                                            const arr_dt = arr_node.node_variant.?.variable.type;
                                            if (arr_dt.array_depth > 0) {
                                                arr_depth = arr_dt.array_depth;
                                            } else if (arr_dt.pointer_depth == 0 and arr_dt.generic_args != null and mem.eql(u8, arr_dt.type_str.items, "Vec")) {
                                                const gargs = arr_dt.generic_args.?.items();
                                                if (gargs.len == 1) {
                                                    vec_item_dt = gargs[0];
                                                }
                                            }
                                        }
                                    }
                                }

                                if (vec_item_dt != null) {
                                    try self.emit_vec_iter_fast_path(fi, arr_name, vec_item_dt.?);
                                } else {
                                    // The length expression root and offset:
                                    // - For regular arrays: root=arr_name, offset=0
                                    //   → sizeof(arr_name)/sizeof(arr_name[0])
                                    // - For multi-dim elements (mdim_root set): use root and offset
                                    //   → sizeof(root[0]*offset)/sizeof(root[0]*(offset+1))
                                    const len_root = mdim_root orelse arr_name;
                                    const len_offset = if (mdim_root != null) mdim_depth else 0;

                                    try self.write("for (int64_t ");
                                    try self.write(idx_name);
                                    try self.write(" = 0; ");
                                    try self.write(idx_name);
                                    try self.write(" < (int64_t)(sizeof(");
                                    try self.write(len_root);
                                    {
                                        var d: usize = 0;
                                        while (d < len_offset) : (d += 1) try self.write("[0]");
                                    }
                                    try self.write(")/sizeof(");
                                    try self.write(len_root);
                                    {
                                        var d: usize = 0;
                                        while (d <= len_offset) : (d += 1) try self.write("[0]");
                                    }
                                    try self.write(")); ");
                                    try self.write(idx_name);
                                    try self.write("++) {");
                                    self.indent();

                                    try self.push_defer_scope(.loop);
                                    defer self.pop_defer_scope();

                                    _ = try self.new_scope();
                                    defer self.finish_scope();

                                    // Determine base C type for the element.
                                    var item_c_type: []const u8 = "int64_t";
                                    if (self.get_scope_entity(arr_name)) |arr_ent_for_type| {
                                        if (arr_ent_for_type.node) |arr_node| {
                                            if (arr_node.type == .Variable and arr_node.node_variant != null) {
                                                const dt = arr_node.node_variant.?.variable.type.*;
                                                item_c_type = map_type_to_c(dt.type_str.items);
                                            }
                                        }
                                    }

                                    // element_depth = arr_depth - 1: number of pointer stars for the element.
                                    const element_depth = if (arr_depth > 0) arr_depth - 1 else 0;

                                    // Emit item declaration.
                                    // For elements that are themselves arrays (element_depth >= 2), use
                                    // __auto_type so the compiler infers the correct array-pointer type
                                    // (e.g. int64_t (*layer)[4] for a 3D tensor), avoiding the invalid
                                    // int64_t ** that would result from naive pointer-star expansion.
                                    try self.write_indent();
                                    if (element_depth >= 2) {
                                        try self.write("__auto_type ");
                                        try self.write(fi.item_name);
                                        try self.write(" = ");
                                        try self.write(arr_name);
                                        try self.write("[");
                                        try self.write(idx_name);
                                        try self.write("];\n");
                                    } else {
                                        try self.write(item_c_type);
                                        {
                                            var d: usize = 0;
                                            while (d < element_depth) : (d += 1) try self.write(" *");
                                        }
                                        try self.write(" ");
                                        try self.write(fi.item_name);
                                        try self.write(" = ");
                                        try self.write(arr_name);
                                        try self.write("[");
                                        try self.write(idx_name);
                                        try self.write("];\n");
                                    }

                                    // Register item in scope with multidim info if it is still an array.
                                    if (self.get_scope_entity(arr_name)) |arr_ent| {
                                        if (arr_ent.node) |arr_node| {
                                            if (arr_node.type == .Variable and arr_node.node_variant != null) {
                                                const arr_dt = arr_node.node_variant.?.variable.type;
                                                const item_dt = self.allocator.create(dtype.DataType) catch return TranspileError.MemoryAllocationFailed;
                                                item_dt.* = arr_dt.*;
                                                item_dt.array_depth = if (arr_dt.array_depth > 0) arr_dt.array_depth - 1 else 0;
                                                if (item_dt.array_depth == 0) {
                                                    if (item_dt.flags) |flags| {
                                                        var fcopy = flags;
                                                        fcopy.is_array = false;
                                                        item_dt.flags = fcopy;
                                                    }
                                                }
                                                item_dt.array = null;

                                                const item_node = self.allocator.create(ast.Node) catch return TranspileError.MemoryAllocationFailed;
                                                var item_name_buf = ArrayList(u8).init(self.allocator);
                                                item_name_buf.appendSlice(fi.item_name) catch return TranspileError.MemoryAllocationFailed;
                                                item_node.* = .{
                                                    .type = .Variable,
                                                    .node_variant = .{ .variable = .{
                                                        .type = item_dt,
                                                        .name = item_name_buf,
                                                        .val = null,
                                                    } },
                                                };

                                                // Create scope entity with multidim info if element is still an array.
                                                const item_ent = self.allocator.create(scope.ScopeEntity) catch return TranspileError.MemoryAllocationFailed;
                                                item_ent.* = .{
                                                    .flags = .{ .on_stack = false },
                                                    .node = item_node,
                                                    .name = fi.item_name,
                                                };
                                                if (element_depth > 0) {
                                                    item_ent.multidim_root = len_root;
                                                    item_ent.multidim_depth = len_offset + 1;
                                                }
                                                try self.push_scope_entity(item_ent);
                                                self.owned_scope_entities.append(item_ent) catch return TranspileError.MemoryAllocationFailed;
                                            }
                                        }
                                    }

                                    try self.transpile_block_contents(fi.body);
                                    if (!self.block_ends_with_scope_terminator(fi.body)) {
                                        try self.emit_current_scope_defers();
                                    }

                                    self.dedent();
                                    try self.write_indent();
                                    try self.write("}");
                                }
                            },
                        }
                    },
                    .fit_stmt => |fit| {
                        // Choose a lowering by the subject's type. `str`/`dec`
                        // subjects can't use a C `switch` (integer operand only), so
                        // they lower to an if/else-if comparison chain. Integral and
                        // enum subjects use a `switch`. A comma condition (`1, 2 ->`)
                        // matches any of its values; duplicate case labels (already
                        // flagged unreachable) are dropped so the C compiles.
                        const subject_type = self.fit_subject_base_type(fit.exp.*, fit.branches.items());
                        const use_chain = subject_type == .Str or subject_type == .Dec;
                        const is_str = subject_type == .Str;

                        // Tagged-union (data-carrying enum) subject: switch on the
                        // discriminant `.tag` and bind each arm's payload into locals.
                        if (self.fit_subject_tagged_union_name(fit.exp.*, fit.branches.items())) |enum_name| {
                            try self.emit_tagged_union_fit(fit, enum_name);
                            return;
                        }

                        if (use_chain) {
                            const tmp = try self.next_tmp_name("fit");
                            defer self.allocator.free(tmp);
                            try self.write("{");
                            self.indent();
                            try self.write_indent();
                            try self.write(if (is_str) "const char* " else "double ");
                            try self.write(tmp);
                            try self.write(" = ");
                            try self.transpile_node(fit.exp.*);
                            try self.write(";");

                            var wrote_branch = false;
                            var default_body: ?*ast.Node = null;
                            for (fit.branches.items()) |branch| {
                                if (branch.condition) |condition| {
                                    try self.write_indent();
                                    try self.write(if (wrote_branch) "else if (" else "if (");
                                    // Expand a comma condition into OR-ed comparisons.
                                    var labels = ArrayList(*ast.Node).init(self.allocator);
                                    defer labels.deinit();
                                    try self.collect_fit_labels(condition, &labels);
                                    for (labels.items, 0..) |lbl, li| {
                                        if (li > 0) try self.write(" || ");
                                        if (is_str) {
                                            try self.write("strcmp(");
                                            try self.write(tmp);
                                            try self.write(", ");
                                            try self.transpile_node(lbl.*);
                                            try self.write(") == 0");
                                        } else {
                                            try self.write(tmp);
                                            try self.write(" == ");
                                            try self.transpile_node(lbl.*);
                                        }
                                    }
                                    try self.write(") {");
                                    self.indent();
                                    try self.write_indent();
                                    try self.transpile_node(branch.body.*);
                                    if (self.node_needs_trailing_semicolon(branch.body.*)) try self.write(";");
                                    self.dedent();
                                    try self.write_indent();
                                    try self.write("}");
                                    wrote_branch = true;
                                } else {
                                    default_body = branch.body;
                                }
                            }
                            if (default_body) |body| {
                                try self.write_indent();
                                try self.write(if (wrote_branch) "else {" else "{");
                                self.indent();
                                try self.write_indent();
                                try self.transpile_node(body.*);
                                if (self.node_needs_trailing_semicolon(body.*)) try self.write(";");
                                self.dedent();
                                try self.write_indent();
                                try self.write("}");
                            }
                            self.dedent();
                            try self.write_indent();
                            try self.write("}");
                            return;
                        }

                        // Integral / enum subject: C `switch`.
                        try self.write("switch (");
                        try self.transpile_node(fit.exp.*);
                        try self.write(") {");
                        self.indent();
                        // Track emitted case-label keys to skip duplicates (which the
                        // analyzer already warns are unreachable). Without this, a
                        // duplicate `Color.Green` arm emits two identical C `case`
                        // labels — a hard compile error.
                        var seen_labels = ArrayList([]const u8).init(self.allocator);
                        defer {
                            for (seen_labels.items) |k| self.allocator.free(k);
                            seen_labels.deinit();
                        }
                        for (fit.branches.items()) |branch| {
                            if (branch.condition) |condition| {
                                // A branch may carry multiple comma-separated labels.
                                var labels = ArrayList(*ast.Node).init(self.allocator);
                                defer labels.deinit();
                                try self.collect_fit_labels(condition, &labels);

                                // Drop labels already emitted earlier (dedup).
                                var emitted_any = false;
                                for (labels.items) |lbl| {
                                    const key = try self.fit_label_key(lbl.*);
                                    defer self.allocator.free(key);
                                    var dup = false;
                                    for (seen_labels.items) |sk| {
                                        if (mem.eql(u8, sk, key)) {
                                            dup = true;
                                            break;
                                        }
                                    }
                                    if (dup) continue;
                                    seen_labels.append(self.allocator.dupe(u8, key) catch return TranspileError.MemoryAllocationFailed) catch return TranspileError.MemoryAllocationFailed;
                                    try self.write_indent();
                                    try self.write("case ");
                                    try self.transpile_node(lbl.*);
                                    try self.write(":");
                                    emitted_any = true;
                                }
                                // Every label of this arm was a duplicate -> skip the
                                // whole (unreachable) arm body.
                                if (!emitted_any) continue;
                                self.indent();
                                if (self.node_needs_trailing_semicolon(branch.body.*)) {
                                    try self.write_indent();
                                    try self.transpile_node(branch.body.*);
                                    try self.write(";");
                                } else {
                                    try self.write_indent();
                                    try self.transpile_node(branch.body.*);
                                }
                                try self.write_indent();
                                try self.write("break;");
                                self.dedent();
                            } else {
                                try self.write_indent();
                                try self.write("default:");

                                self.indent();
                                if (self.node_needs_trailing_semicolon(branch.body.*)) {
                                    try self.write_indent();
                                    try self.transpile_node(branch.body.*);
                                    try self.write(";");
                                } else {
                                    try self.write_indent();
                                    try self.transpile_node(branch.body.*);
                                }
                                try self.write_indent();
                                try self.write("break;");
                                self.dedent();
                            }
                        }
                        self.dedent();
                        try self.write_indent();
                        try self.write("}");
                    },
                    .fork_stmt => |fk| {
                        // `fork f(args);` — fire-and-forget spawn onto the M:N
                        // scheduler. The target must be an `async fun` (so its
                        // payload struct + entry trampoline already exist); we emit a
                        // call to the fork wrapper `__fun_fork_call_<fn>(args)` which
                        // packs the args and enqueues the entry via __fun_go(). The
                        // wrapper + a payload-freeing entry are emitted in the async
                        // support-definitions pass (gated by uses_fork).
                        self.uses_fork = true;
                        const call = fk.expr.*;
                        const lowering = (try self.resolve_await_lowering_info(call)) orelse {
                            self.report_type_error(node, "fork requires a statically resolvable async function call", .{});
                            return TranspileError.TypeMismatch;
                        };
                        defer self.allocator.free(lowering.callee_name);

                        const call_exp = call.node_variant.?.exp;
                        try self.write("__fun_fork_call_");
                        try self.write(lowering.callee_name);
                        try self.write("(");
                        var wrote_arg = false;
                        if (lowering.receiver_expr) |recv| {
                            if (lowering.receiver_pass_by_ref) try self.write("&");
                            try self.transpile_node(recv.*);
                            wrote_arg = true;
                        }
                        if (call_exp.right) |right| {
                            const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                right.node_variant.?.paren.exp.*
                            else
                                right.*;
                            if (inner.type != .Blank) {
                                if (wrote_arg) try self.write(", ");
                                try self.transpile_node(inner);
                            }
                        }
                        try self.write(");");
                    },
                    // return handled above with defers
                }
            },
            .StatementBreak => {
                try self.emit_loop_scope_defers();
                try self.write("break;");
            },
            .StatementContinue => {
                try self.emit_loop_scope_defers();
                try self.write("continue;");
            },
            .Unary => {
                const unary = node.node_variant.?.unary;
                if (mem.eql(u8, unary.op, "await")) {
                    const operand = unary.operand.*;
                    if (try self.resolve_await_lowering_info(operand)) |lowering| {
                        defer self.allocator.free(lowering.callee_name);

                        const call_exp = operand.node_variant.?.exp;
                        try self.write("__fun_async_call_");
                        try self.write(lowering.callee_name);
                        try self.write("(");

                        var wrote_arg = false;
                        var c_args: usize = 0;
                        if (lowering.receiver_expr) |recv| {
                            if (lowering.receiver_pass_by_ref) {
                                try self.write("&");
                            }
                            try self.transpile_node(recv.*);
                            wrote_arg = true;
                            c_args = 1;
                        }

                        if (call_exp.right) |right| {
                            const inner = if (right.type == .ExpressionParenthesis and right.node_variant != null)
                                right.node_variant.?.paren.exp.*
                            else
                                right.*;
                            if (inner.type != .Blank) {
                                if (wrote_arg) {
                                    try self.write(", ");
                                }
                                try self.transpile_node(inner);
                                var ua = ArrayList(*ast.Node).init(self.allocator);
                                defer ua.deinit();
                                self.flatten_call_args_ptr(right, &ua) catch {};
                                c_args += ua.items.len;
                            }
                        }

                        // Fill omitted trailing default args for an awaited method call.
                        // `callee_name` is the mangled `Type__method` (or `Type__args__method`
                        // for generics); split off the method base name to resolve the node.
                        if (lowering.receiver_expr != null) {
                            if (std.mem.lastIndexOf(u8, lowering.callee_name, "__")) |sep| {
                                const recv_type = lowering.callee_name[0..sep];
                                const method_base = lowering.callee_name[sep + 2 ..];
                                try self.emit_trailing_default_args_for_method(recv_type, method_base, c_args);
                            }
                        }

                        try self.write(")");
                        return;
                    }

                    if (self.is_await_dynamic_quirk_dispatch(operand)) {
                        try self.transpile_node(operand);
                        return;
                    }

                    self.report_type_error(node, "await currently supports statically resolved async calls only", .{});
                    return TranspileError.TypeMismatch;
                }
                if (unary.is_left_operanded_unary) {
                    try self.transpile_node(unary.operand.*);
                    try self.write(unary.op);
                } else {
                    // For a pointer indirection (`*`), `indirection.depth` records how
                    // many `*` were written (e.g. `**pp` has depth 2). Emit the
                    // operator once per level — previously only one `*` was written,
                    // silently dropping deeper indirections.
                    if (unary.indirection) |ind| {
                        var i: usize = 0;
                        while (i < ind.depth) : (i += 1) {
                            try self.write(unary.op);
                        }
                    } else {
                        try self.write(unary.op);
                    }
                    try self.transpile_node(unary.operand.*);
                }
            },
            .Tenary => {
                const tenary = node.node_variant.?.tenary;
                try self.transpile_node(tenary.condition.*);
                try self.write(" ? ");
                try self.transpile_node(tenary.true.*);
                try self.write(" : ");
                try self.transpile_node(tenary.false.*);
            },
            .Boolean => {
                const val = node.data.?.bval;
                try self.write(if (val) "true" else "false");
            },
            // The `nil` literal lowers to the C null-pointer constant `NULL`.
            .Nil => try self.write("NULL"),
            // `panic("msg")` used as a RETURN value is special-cased at the
            // `.return_stmt` site above (no dummy value needed there, since
            // `abort()` never returns). Everywhere ELSE (a `let` initializer,
            // fit-arm body, function argument, ...) still needs a single C
            // EXPRESSION of SOME concrete type, so this lowers to a GNU C
            // statement expression that prints the message, aborts, and
            // trails off with a plain `0` -- C's very permissive implicit
            // conversions accept that as almost any scalar/pointer type
            // (though NOT a struct/union return type; that combination isn't
            // supported yet). `stderr_stream()`/`abort()` are always present
            // (see `transpile_prelude`), so no import is required for this.
            .Panic => {
                if (node.node_variant) |nv| {
                    try self.write("({ ");
                    try self.write_panic_message_and_abort(nv.panic_expr.message.*);
                    try self.write(" 0; })");
                }
            },
            else => {},
        }
    }

    fn register_scope_variable(self: *Self, var_node: *ast.Node) TranspileError!void {
        if (self.scope == null or self.scope.?.current == null) return;
        if (var_node.type != .Variable) return;

        const ent = self.allocator.create(scope.ScopeEntity) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer self.allocator.destroy(ent);

        ent.* = .{
            .flags = .{ .on_stack = false },
            .node = var_node,
            .name = var_node.node_variant.?.variable.name.items,
        };

        try self.push_scope_entity(ent);
        self.owned_scope_entities.append(ent) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    /// Increase the indentation level
    pub fn indent(self: *Self) void {
        self.indent_level += 1;
    }

    /// Decrease the indentation level
    pub fn dedent(self: *Self) void {
        if (self.indent_level > 0) {
            self.indent_level -= 1;
        }
    }

    /// Write a newline followed by the current indentation
    pub fn write_indent(self: *Self) TranspileError!void {
        try self.write("\n");
        if (self.flags.debug_info) {
            if (self.pending_line_directive) |pos| {
                // Escape backslashes in path (needed on Windows).
                try self.write("#line ");
                try self.print("{d}", .{pos.line});
                try self.write(" \"");
                for (pos.filename) |ch| {
                    if (ch == '\\') try self.write("\\\\") else try self.print("{c}", .{ch});
                }
                try self.write("\"\n");
                self.pending_line_directive = null;
            }
        }
        try self.write_spaces(self.indent_level * 4); // 4 spaces per level
    }

    /// Write a specific number of spaces
    pub fn write_spaces(self: *Self, spaces: u32) TranspileError!void {
        var i: u32 = 0;
        while (i < spaces) : (i += 1) {
            try self.write(" ");
        }
    }

    /// Write formatted with indentation prefix
    pub fn write_indented(self: *Self, text: []const u8) TranspileError!void {
        try self.write_spaces(self.indent_level * 4);
        try self.write(text);
    }

    /// Process an import node to include standard library or local file
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `node`: The import node to process.
    ///
    /// Errors:
    /// - Returns an error if processing the import fails.
    fn process_import(self: *Self, node: ast.Node) GeneralError!void {
        const import_path = node.node_variant.?.import.path;
        const import_alias = node.node_variant.?.import.alias;
        if (import_alias) |alias| {
            try self.register_import_alias(alias, import_path);
        }
        // Canonicalize legacy/local stdlib prefix `stdlib.std.*` to `std.*`
        // so all stdlib imports resolve through the same stdlib root and avoid
        // duplicate symbol loading from mixed roots.
        const canonical_import_path = if (std.mem.startsWith(u8, import_path, "stdlib.std."))
            import_path["stdlib.".len..]
        else
            import_path;

        if (std.mem.startsWith(u8, canonical_import_path, "std.c.")) {
            try self.process_std_import(node, canonical_import_path);
        } else if (std.mem.startsWith(u8, canonical_import_path, "std.")) {
            try self.process_std_module_import(node, canonical_import_path);
        } else {
            try self.process_local_import(node, import_path, import_alias);
        }
    }

    /// Process a standard library import (e.g., "std.io")
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `import_path`: The import path as a string.
    ///
    /// Errors:
    /// - Returns an error if processing the import fails.
    fn process_std_import(self: *Self, import_node: ast.Node, import_path: []const u8) GeneralError!void {
        var header_name: []const u8 = undefined;

        if (mem.eql(u8, import_path, "std.c.io")) {
            header_name = self.allocator.dupe(u8, "stdio.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.mem")) {
            header_name = self.allocator.dupe(u8, "stdlib.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.string")) {
            header_name = self.allocator.dupe(u8, "string.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.math")) {
            header_name = self.allocator.dupe(u8, "math.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.ctype")) {
            header_name = self.allocator.dupe(u8, "ctype.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.time")) {
            header_name = self.allocator.dupe(u8, "time.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.net")) {
            self.requires_net_compat_layer = true;
            // `std.c.net` is handled specially in `write_std_imports`:
            // - on Windows, emit winsock headers and close()->closesocket alias
            // - otherwise, include POSIX socket headers
            try self.process_std_module_import(import_node, import_path);
            return;
        } else if (mem.eql(u8, import_path, "std.c.thread") or mem.eql(u8, import_path, "std.c.thread_windows")) {
            self.requires_thread_compat_layer = true;
            // `std.c.thread*` imports are handled specially in `write_std_imports`:
            // - on Windows, emit Win32-backed pthread-compatible definitions
            // - otherwise, include `<pthread.h>`
            try self.process_std_module_import(import_node, import_path);
            return;
        } else if (mem.eql(u8, import_path, "std.c.process")) {
            self.requires_process_compat_layer = true;
            // `std.c.process` is handled specially in `write_std_imports`:
            // - on POSIX, include spawn.h/sys/wait.h/unistd.h (the real
            //   posix_spawn/waitpid/pipe declarations)
            // - on Windows, emit a CreateProcess-backed compat layer (no
            //   posix_spawn/waitpid equivalent exists there at all)
            try self.process_std_module_import(import_node, import_path);
            return;
        } else if (mem.eql(u8, import_path, "std.c.limits")) {
            header_name = self.allocator.dupe(u8, "limits.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.stdint")) {
            header_name = self.allocator.dupe(u8, "stdint.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.def")) {
            header_name = self.allocator.dupe(u8, "stddef.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.errno")) {
            header_name = self.allocator.dupe(u8, "errno.h") catch {
                return TranspileError.MemoryAllocationFailed;
            };
        } else if (mem.eql(u8, import_path, "std.c.wd")) {
            // Deadlock-watchdog hooks: no libc header — the symbols
            // (`__fun_wd_enter_wait`/`__fun_wd_leave_wait`/`__fun_wd_warn`) are
            // emitted directly into the prelude by the compiler. Nothing to include.
            return;
        } else if (mem.eql(u8, import_path, "std.c.dirent")) {
            // Directory iteration/creation/kind-check helpers
            // (`__fun_dir_open`/`__fun_dir_read_name`/`__fun_dir_close`/
            // `__fun_path_is_dir`/`__fun_make_dir`) are emitted directly into
            // the prelude by the compiler (see `transpile_prelude`) — no
            // libc header to pull in here, unlike the rest of this chain.
            // Still load the signature module so type-checking sees these
            // functions' signatures.
            try self.process_std_module_import(import_node, import_path);
            return;
        } else {
            self.report_error(import_node, "Unsupported standard library import: {s}", .{import_path});
            return TranspileError.UnsupportedImport;
        }

        for (self.std_imports.items) |existing| {
            if (mem.eql(u8, existing, header_name)) {
                self.allocator.free(header_name);
                return;
            }
        }
        self.std_imports.append(header_name) catch {
            return TranspileError.MemoryAllocationFailed;
        };

        // Also load the std.c signature module so type checking sees function signatures.
        try self.process_std_module_import(import_node, import_path);
    }

    fn process_std_module_import(self: *Self, import_node: ast.Node, import_path: []const u8) GeneralError!void {
        const full_path_opt = try self.build_stdlib_module_path(import_path);
        if (full_path_opt == null) {
            self.report_error(import_node, "Import file not found: {s}", .{import_path});
            return TranspileError.ImportFileNotFound;
        }
        const full_path = full_path_opt.?;
        defer self.backing_allocator.free(full_path);
        try self.process_local_import_full_path(full_path, if (import_node.node_variant) |nv| nv.import.alias else null);
    }

    /// Process a local file import (e.g., "custom" or "folder.file")
    ///
    /// Parameters:
    /// - `self`: The instance of the transpiler.
    /// - `import_path`: The import path as a string.
    ///
    /// Errors:
    /// - Returns an error if processing the import fails.
    fn process_local_import(self: *Self, import_node: ast.Node, import_path: []const u8, import_alias: ?[]const u8) GeneralError!void {
        // Get full path of the file to import
        // This is a temporary helper string; keep it off the arena.
        var file_path = ArrayList(u8).init(self.backing_allocator);
        defer file_path.deinit();

        const dir_path = std.fs.path.dirname(self.input_file_path) orelse ".";
        file_path.appendSlice(dir_path) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        file_path.append('/') catch {
            return TranspileError.MemoryAllocationFailed;
        };

        // Convert dotted imports to a path. Additionally, support parent traversal via dot runs:
        // - `.`  => path separator
        // - `..` => `../` (one parent)
        // - `....` => `../../` (two parents)
        var i: usize = 0;
        while (i < import_path.len) {
            if (import_path[i] != '.') {
                file_path.append(import_path[i]) catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                i += 1;
                continue;
            }

            var j = i;
            while (j < import_path.len and import_path[j] == '.') : (j += 1) {}
            const run_len = j - i;
            const parents = run_len / 2;
            const sep = (run_len % 2) == 1;

            var p: usize = 0;
            while (p < parents) : (p += 1) {
                file_path.appendSlice("..") catch {
                    return TranspileError.MemoryAllocationFailed;
                };
                file_path.append('/') catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }
            if (sep) {
                file_path.append('/') catch {
                    return TranspileError.MemoryAllocationFailed;
                };
            }

            i = j;
        }

        file_path.appendSlice(".fn") catch {
            return TranspileError.MemoryAllocationFailed;
        };
        const full_path = file_path.toOwnedSlice() catch {
            return TranspileError.MemoryAllocationFailed;
        };
        defer self.backing_allocator.free(full_path);

        const canon_path = std.Io.Dir.cwd().realPathFileAlloc(self.io, full_path, self.allocator) catch null;
        const canon = canon_path orelse (self.allocator.dupe(u8, full_path) catch return TranspileError.MemoryAllocationFailed);
        errdefer self.allocator.free(canon);

        // Add a comment showing the import attempt
        try self.write("\n/* Attempting to import: ");
        try self.write(full_path);
        try self.write(" */\n");

        // Check if the file exists
        std.Io.Dir.cwd().access(self.io, canon, .{}) catch {
            // Keep the output comment (useful when dumping partial output), but also
            // emit a real diagnostic tied to the import statement.
            try self.write("\n/* ERROR: Import file not found: ");
            try self.write(full_path);
            try self.write(" */\n");

            self.report_error(import_node, "Import file not found: {s}", .{canon});
            return TranspileError.ImportFileNotFound;
        };

        // Robust direct circular dependency detection
        // First, check if the file being imported already has us in its import chain
        const file_contents = std.Io.Dir.cwd().readFileAlloc(self.io, canon, self.backing_allocator, .limited(1024 * 1024)) catch |read_err| {
            self.report_error(import_node, "Failed to read import file '{s}': {any}", .{ canon, read_err });
            return TranspileError.FileReadError;
        };
        defer self.backing_allocator.free(file_contents);

        // Check if the file imports us directly (crude but effective)
        const our_name = std.fs.path.stem(self.input_file_path);
        var import_line = ArrayList(u8).init(self.backing_allocator);
        defer import_line.deinit();
        import_line.appendSlice("imp ") catch {
            return TranspileError.MemoryAllocationFailed;
        };
        import_line.appendSlice(our_name) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        import_line.appendSlice(";") catch {
            return TranspileError.MemoryAllocationFailed;
        };

        // Check if the target file imports us
        if (std.mem.indexOf(u8, file_contents, import_line.items)) |_| {
            const basename1 = std.fs.path.basename(self.input_file_path);
            const basename2 = std.fs.path.basename(full_path);

            self.report_error(import_node, "CIRCULAR IMPORT DETECTED: '{s}' imports '{s}', but '{s}' also imports '{s}', creating a circular dependency", .{ basename1, basename2, basename2, basename1 });
            return TranspileError.CircularImport;
        }

        // Mark this file as imported.
        // Avoid importing the same file under different relative paths.
        // If the file is already imported but a new alias is being introduced, create
        // a minimal stub child process so transpile_children_recursive can emit #define stubs.
        //
        // Dedup of the expensive lex/parse is tracked compile-wide on the root
        // process (`imported_files_is_globally_parsed`), not just within this
        // import subtree. Without that, a module reachable through two sibling
        // import branches (a diamond) is fully re-parsed once per branch even
        // though its public symbols already propagate upward via
        // `sync_global_symbols_to_parent`. The local `self.imported_files` map
        // is still maintained for alias/stub bookkeeping below.
        if (self.imported_files.contains(canon) or self.imported_files_is_globally_parsed(canon)) {
            if (import_alias) |alias| {
                var stub_proc = self.backing_allocator.create(TranspileProcess) catch {
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
                stub_proc.* = TranspileProcess.init_with_stdlib_dir(self.backing_allocator, canon, "temp.c", .{ .outf = false }, self.stdlib_dir) catch {
                    self.backing_allocator.destroy(stub_proc);
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
                stub_proc.parent = self;
                stub_proc.is_importing = true;
                stub_proc.import_alias = stub_proc.allocator.dupe(u8, alias) catch {
                    stub_proc.deinit();
                    self.backing_allocator.destroy(stub_proc);
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
                self.children.append(stub_proc) catch {
                    stub_proc.deinit();
                    self.backing_allocator.destroy(stub_proc);
                    self.allocator.free(canon);
                    return TranspileError.MemoryAllocationFailed;
                };
            }
            self.allocator.free(canon);
            return;
        }
        self.imported_files.put(canon, true) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        self.mark_globally_parsed(canon);

        // Create and initialize child transpile process.
        // The child process struct itself must be backing-allocated so the parent
        // can safely destroy it after `child.deinit()`.
        var import_proc = self.backing_allocator.create(TranspileProcess) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer self.backing_allocator.destroy(import_proc);

        // Inherit ONLY the parent's test/warning-visibility mode (test_mode,
        // emit_unused_warnings) so e.g. `fun test entry.fn` also type-checks and emits
        // `test` blocks declared in an IMPORTED module, not just the entry file's own --
        // `typecheck_module`'s `.Test`-node handling is gated on exactly these two
        // fields. Without this, a child process always got `test_mode = false`
        // regardless of the parent, so an imported module's `test` block was parsed but
        // never type-checked -- yet codegen still tried to emit it, embedding the
        // unresolved `__let_infer__` placeholder for any `let` binding whose type only
        // typecheck ever resolves.
        //
        // Deliberately NOT a wholesale `self.flags` copy: `preload_imports`/
        // `preload_std_imports`/`emit_stderr`/etc. are parse-strategy/output flags the
        // ROOT process sets for its own reasons (e.g. the test harness disables import
        // preloading to avoid redundant filesystem probing) that must NOT cascade to
        // children -- doing so broke transitive import processing for std.channel/
        // std.net (children stopped preloading their OWN nested imports).
        var child_flags = TranspileProcessFlags{ .outf = false };
        child_flags.test_mode = self.flags.test_mode;
        child_flags.fuzz_mode = self.flags.fuzz_mode;
        child_flags.emit_unused_warnings = self.flags.emit_unused_warnings;
        import_proc.* = try TranspileProcess.init_with_stdlib_dir(self.backing_allocator, canon, "temp.c", child_flags, self.stdlib_dir);
        import_proc.fuzz_target = self.fuzz_target;

        if (import_alias) |alias| {
            import_proc.import_alias = import_proc.allocator.dupe(u8, alias) catch return TranspileError.MemoryAllocationFailed;
        }

        import_proc.parent = self;
        import_proc.is_importing = true;

        // Copy the import chain and add the current import for tracking
        for (self.import_chain.items) |chain_path| {
            const chain_path_copy = import_proc.allocator.dupe(u8, chain_path) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer import_proc.allocator.free(chain_path_copy);

            import_proc.import_chain.append(chain_path_copy) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }
        const import_path_copy = import_proc.allocator.dupe(u8, canon) catch {
            return TranspileError.MemoryAllocationFailed;
        };
        errdefer import_proc.allocator.free(import_path_copy);

        import_proc.import_chain.append(import_path_copy) catch {
            return TranspileError.MemoryAllocationFailed;
        };

        // Copy imported files to child
        var it = self.imported_files.iterator();
        while (it.next()) |entry| {
            const imported_file_copy = import_proc.allocator.dupe(u8, entry.key_ptr.*) catch {
                return TranspileError.MemoryAllocationFailed;
            };
            errdefer import_proc.allocator.free(imported_file_copy);

            import_proc.imported_files.put(imported_file_copy, true) catch {
                return TranspileError.MemoryAllocationFailed;
            };
        }

        // Process the imported file
        var lex_proc = lexer.LexProcess.init(import_proc);
        var parse_proc = parser.ParseProcess.init(import_proc);

        try lex_proc.lex();
        try parse_proc.parse();

        // Process imports within the imported file
        for (import_proc.nodes.items()) |node| {
            if (node.type == .Import) {
                try import_proc.process_import(node);
            }
        }

        // After processing is complete, sync all symbols back to parent
        try import_proc.sync_global_symbols_to_parent();

        // Add to children list
        self.children.append(import_proc) catch {
            return TranspileError.MemoryAllocationFailed;
        };
    }

    /// Synchronize global symbols from a child process to the parent process
    ///
    /// This ensures that symbols defined in imported files are visible to the parent process
    /// for duplicate detection across modules.
    ///
    /// Parameters:
    /// - `self`: The child process whose symbols will be synced to its parent
    ///
    /// Errors:
    /// - Returns an error if the synchronization fails.
    fn sync_global_symbols_to_parent(self: *Self) TranspileError!void {
        if (self.parent == null) return; // Not a child process

        var it = self.global_symbols.iterator();
        while (it.next()) |entry| {
            const symbol_name = entry.key_ptr.*;
            const symbol_info = entry.value_ptr.*;

            // Skip non-public and main functions entirely
            if (mem.eql(u8, symbol_name, "main")) continue;
            if (!symbol_info.is_public) continue;

            const exported_name = if (self.import_alias) |alias|
                (try self.make_alias_qualified_symbol_name(alias, symbol_name))
            else
                symbol_name;

            // Check if this symbol is already defined in the parent
            if (self.parent.?.global_symbols.get(exported_name)) |existing| {
                // If we find a conflict from a different file, report it.
                // Allow duplicates from the same file path (e.g. when symbols were
                // preloaded earlier for parsing).
                if (!mem.eql(u8, existing.file_path, symbol_info.file_path)) {
                    if (self.import_alias != null) self.allocator.free(exported_name);
                    self.err("Symbol '{s}' in module '{s}' conflicts with same symbol defined in module '{s}'", .{ exported_name, symbol_info.file_path, existing.file_path });
                    return TranspileError.DuplicateSymbol;
                }

                if (self.import_alias != null) self.allocator.free(exported_name);

                continue;
            }

            // Add this symbol to the parent's global registry
            self.parent.?.global_symbols.put(exported_name, .{
                .symbol_name = exported_name,
                .file_path = symbol_info.file_path,
                .is_function = symbol_info.is_function,
                .is_public = symbol_info.is_public,
            }) catch {
                if (self.import_alias != null) self.allocator.free(exported_name);
                return TranspileError.MemoryAllocationFailed;
            };
        }
    }

    /// Write standard library imports to the output
    fn write_std_imports(self: *Self) TranspileError!void {
        var seen = std.StringHashMap(bool).init(self.backing_allocator);
        defer seen.deinit();

        const add_header = struct {
            fn call(tp: *Self, map: *std.StringHashMap(bool), name: []const u8) TranspileError!void {
                if (map.contains(name)) return;
                map.put(name, true) catch return TranspileError.MemoryAllocationFailed;
                try tp.write("#include <");
                try tp.write(name);
                try tp.write(">\n");
            }
        }.call;

        const add_headers_recursive = struct {
            fn call(tp: *Self, map: *std.StringHashMap(bool), proc: *Self) TranspileError!void {
                for (proc.std_imports.items) |header| {
                    try add_header(tp, map, header);
                }
                for (proc.children.items) |child| {
                    try call(tp, map, child);
                }
            }
        }.call;

        try add_headers_recursive(self, &seen, self);

        // Always include core headers once.
        try add_header(self, &seen, "stdio.h");
        try add_header(self, &seen, "stdbool.h");
        try add_header(self, &seen, "stdint.h");
        try add_header(self, &seen, "stdarg.h");
        try add_header(self, &seen, "stdlib.h");
        try add_header(self, &seen, "string.h");

        if (requires_net_compat_recursive(self)) {
            try self.write("\n");
            try self.write("#if defined(_WIN32)\n");
            try self.write("#ifndef WIN32_LEAN_AND_MEAN\n");
            try self.write("#define WIN32_LEAN_AND_MEAN\n");
            try self.write("#endif\n");
            try self.write("#include <winsock2.h>\n");
            try self.write("#include <ws2tcpip.h>\n");
            try self.write("#pragma comment(lib, \"Ws2_32.lib\")\n");
            try self.write("#ifndef close\n");
            try self.write("#define close closesocket\n");
            try self.write("#endif\n");
            try self.write("#else\n");
            try self.write("#include <sys/socket.h>\n");
            try self.write("#include <netinet/in.h>\n");
            try self.write("#include <arpa/inet.h>\n");
            try self.write("#include <unistd.h>\n");
            try self.write("#endif\n");
        }

        if (requires_thread_compat_recursive(self)) {
            try self.write("\n");
            try self.write("#if defined(_WIN32) && !defined(__MINGW32__) && !defined(__MINGW64__)\n");
            try self.write("#ifndef WIN32_LEAN_AND_MEAN\n");
            try self.write("#define WIN32_LEAN_AND_MEAN\n");
            try self.write("#endif\n");
            try self.write("#include <windows.h>\n");
            try self.write("#include <process.h>\n");
            try self.write("#include <errno.h>\n");
            try self.write("#include <time.h>\n");
            try self.write("\n");
            try self.write("typedef HANDLE pthread_t;\n");
            try self.write("typedef void pthread_attr_t;\n");
            try self.write("typedef CRITICAL_SECTION pthread_mutex_t;\n");
            try self.write("typedef void pthread_mutexattr_t;\n");
            try self.write("typedef CONDITION_VARIABLE pthread_cond_t;\n");
            try self.write("typedef void pthread_condattr_t;\n");
            try self.write("typedef struct __fun_win_timespec {\n");
            try self.write("    time_t tv_sec;\n");
            try self.write("    long tv_nsec;\n");
            try self.write("} __fun_win_timespec;\n");
            try self.write("\n");
            // `clock_gettime` is POSIX-only; Windows has no equivalent in
            // <time.h>, so "now" comes from `GetSystemTimeAsFileTime`
            // instead, converted from its 100ns-since-1601 epoch to the
            // Unix (1970) one `__fun_win_timespec` expects.
            try self.write("static void __fun_win_clock_gettime(__fun_win_timespec* out) {\n");
            try self.write("    FILETIME ft;\n");
            try self.write("    GetSystemTimeAsFileTime(&ft);\n");
            try self.write("    unsigned long long t = ((unsigned long long)ft.dwHighDateTime << 32) | ft.dwLowDateTime;\n");
            try self.write("    t -= 116444736000000000ULL;\n");
            try self.write("    out->tv_sec = (time_t)(t / 10000000ULL);\n");
            try self.write("    out->tv_nsec = (long)((t % 10000000ULL) * 100);\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("typedef struct __fun_win_thread_ctx {\n");
            try self.write("    void* (*entry)(void*);\n");
            try self.write("    void* arg;\n");
            try self.write("} __fun_win_thread_ctx;\n");
            try self.write("\n");
            try self.write("static unsigned __stdcall __fun_win_thread_start(void* opaque) {\n");
            try self.write("    __fun_win_thread_ctx* ctx = (__fun_win_thread_ctx*)opaque;\n");
            try self.write("    if (ctx == NULL) {\n");
            try self.write("        _endthreadex(0);\n");
            try self.write("        return 0;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    void* (*entry)(void*) = ctx->entry;\n");
            try self.write("    void* arg = ctx->arg;\n");
            try self.write("    free(ctx);\n");
            try self.write("\n");
            try self.write("    if (entry != NULL) {\n");
            try self.write("        (void)entry(arg);\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    _endthreadex(0);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_create(pthread_t* thread, pthread_attr_t* attr, void* start_routine, void* arg) {\n");
            try self.write("    (void)attr;\n");
            try self.write("    if (thread == NULL || start_routine == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    __fun_win_thread_ctx* ctx = (__fun_win_thread_ctx*)malloc(sizeof(__fun_win_thread_ctx));\n");
            try self.write("    if (ctx == NULL) {\n");
            try self.write("        return (long long)ENOMEM;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    ctx->entry = (void* (*)(void*))start_routine;\n");
            try self.write("    ctx->arg = arg;\n");
            try self.write("\n");
            try self.write("    uintptr_t thread_raw = _beginthreadex(NULL, 0, __fun_win_thread_start, (void*)ctx, 0, NULL);\n");
            try self.write("    if (thread_raw == 0) {\n");
            try self.write("        free(ctx);\n");
            try self.write("        return (long long)errno;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    *thread = (HANDLE)thread_raw;\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_join(pthread_t thread, void* retval) {\n");
            try self.write("    if (thread == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    DWORD wait_rc = WaitForSingleObject(thread, INFINITE);\n");
            try self.write("    if (wait_rc != WAIT_OBJECT_0) {\n");
            try self.write("        return (long long)GetLastError();\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    if (retval != NULL) {\n");
            try self.write("        *((void**)retval) = NULL;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    if (CloseHandle(thread) == 0) {\n");
            try self.write("        return (long long)GetLastError();\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_detach(pthread_t thread) {\n");
            try self.write("    if (thread == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    if (CloseHandle(thread) == 0) {\n");
            try self.write("        return (long long)GetLastError();\n");
            try self.write("    }\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("pthread_t pthread_self(void) {\n");
            try self.write("    return GetCurrentThread();\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_equal(pthread_t t1, pthread_t t2) {\n");
            try self.write("    DWORD id1 = GetThreadId(t1);\n");
            try self.write("    DWORD id2 = GetThreadId(t2);\n");
            try self.write("    if (id1 == 0 || id2 == 0) {\n");
            try self.write("        return (t1 == t2) ? 1 : 0;\n");
            try self.write("    }\n");
            try self.write("    return (id1 == id2) ? 1 : 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_mutex_init(pthread_mutex_t* mutex, pthread_mutexattr_t* attr) {\n");
            try self.write("    (void)attr;\n");
            try self.write("    if (mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    InitializeCriticalSection(mutex);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_mutex_destroy(pthread_mutex_t* mutex) {\n");
            try self.write("    if (mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    DeleteCriticalSection(mutex);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_mutex_lock(pthread_mutex_t* mutex) {\n");
            try self.write("    if (mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    EnterCriticalSection(mutex);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_mutex_trylock(pthread_mutex_t* mutex) {\n");
            try self.write("    if (mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    return TryEnterCriticalSection(mutex) ? 0 : (long long)EBUSY;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_mutex_unlock(pthread_mutex_t* mutex) {\n");
            try self.write("    if (mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    LeaveCriticalSection(mutex);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_cond_init(pthread_cond_t* cond, pthread_condattr_t* attr) {\n");
            try self.write("    (void)attr;\n");
            try self.write("    if (cond == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    InitializeConditionVariable(cond);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_cond_destroy(pthread_cond_t* cond) {\n");
            try self.write("    if (cond == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_cond_wait(pthread_cond_t* cond, pthread_mutex_t* mutex) {\n");
            try self.write("    if (cond == NULL || mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    return SleepConditionVariableCS(cond, mutex, INFINITE) ? 0 : (long long)GetLastError();\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_cond_timedwait(pthread_cond_t* cond, pthread_mutex_t* mutex, void* abstime) {\n");
            try self.write("    if (cond == NULL || mutex == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    if (abstime == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    const __fun_win_timespec* ts = (const __fun_win_timespec*)abstime;\n");
            try self.write("    if (ts->tv_nsec < 0 || ts->tv_nsec >= 1000000000L) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    long long sec = (long long)ts->tv_sec;\n");
            try self.write("    if (sec < 0) {\n");
            try self.write("        return (long long)ETIMEDOUT;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    __fun_win_timespec now_ts;\n");
            try self.write("    __fun_win_clock_gettime(&now_ts);\n");
            try self.write("    if (now_ts.tv_nsec < 0 || now_ts.tv_nsec >= 1000000000L) {\n");
            try self.write("        return (long long)ETIMEDOUT;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    long long now_sec = (long long)now_ts.tv_sec;\n");
            try self.write("    long long now_nsec = (long long)now_ts.tv_nsec;\n");
            try self.write("    long long sec_diff = sec - now_sec;\n");
            try self.write("    long long nsec_diff = (long long)ts->tv_nsec - now_nsec;\n");
            try self.write("    if (nsec_diff < 0) {\n");
            try self.write("        sec_diff -= 1;\n");
            try self.write("        nsec_diff += 1000000000LL;\n");
            try self.write("    }\n");
            try self.write("    if (sec_diff < 0) {\n");
            try self.write("        return (long long)ETIMEDOUT;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    unsigned long long delta_ms = (unsigned long long)sec_diff * 1000ULL;\n");
            try self.write("    delta_ms += (unsigned long long)(nsec_diff / 1000000LL);\n");
            try self.write("    if ((nsec_diff % 1000000LL) != 0LL) {\n");
            try self.write("        delta_ms += 1ULL;\n");
            try self.write("    }\n");
            try self.write("    if (delta_ms == 0ULL) {\n");
            try self.write("        delta_ms = 1ULL;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    DWORD timeout_ms = 0;\n");
            try self.write("    if (delta_ms >= 0xFFFFFFFEULL) {\n");
            try self.write("        timeout_ms = 0xFFFFFFFEu;\n");
            try self.write("    } else {\n");
            try self.write("        timeout_ms = (DWORD)delta_ms;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    BOOL ok = SleepConditionVariableCS(cond, mutex, timeout_ms);\n");
            try self.write("    if (ok != 0) {\n");
            try self.write("        return 0;\n");
            try self.write("    }\n");
            try self.write("    DWORD err = GetLastError();\n");
            try self.write("    if (err == ERROR_TIMEOUT) {\n");
            try self.write("        return (long long)ETIMEDOUT;\n");
            try self.write("    }\n");
            try self.write("    return (long long)err;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_cond_signal(pthread_cond_t* cond) {\n");
            try self.write("    if (cond == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    WakeConditionVariable(cond);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long pthread_cond_broadcast(pthread_cond_t* cond) {\n");
            try self.write("    if (cond == NULL) {\n");
            try self.write("        return (long long)EINVAL;\n");
            try self.write("    }\n");
            try self.write("    WakeAllConditionVariable(cond);\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("#else\n");
            try self.write("#include <pthread.h>\n");
            try self.write("#endif\n");
        }

        if (requires_process_compat_recursive(self)) {
            try self.write("\n");
            try self.write("#if defined(_WIN32)\n");
            // Shield these first-time header inclusions from a `close`
            // macro an earlier `std.c.net` import may have already defined
            // (`close` -> `closesocket`; see the net-compat block above) --
            // same reasoning as the dir-iteration prelude block's own guard.
            try self.write("#pragma push_macro(\"close\")\n");
            try self.write("#undef close\n");
            try self.write("#include <windows.h>\n");
            try self.write("#include <io.h>\n");
            try self.write("#include <fcntl.h>\n");
            try self.write("#include <process.h>\n");
            try self.write("#pragma pop_macro(\"close\")\n");
            try self.write("\n");
            // <sys/types.h> typedefs `pid_t` on MinGW, but not on the
            // MSVC/clang-cl headers a Developer-Prompt build actually
            // uses, so it needs an explicit fallback. Unlike POSIX, real
            // Win32 process handles (HANDLE) and process IDs (DWORD) are
            // different things, so this compat layer stores the numeric PID
            // in `*pid` (matching real POSIX semantics exactly) and has
            // `waitpid` re-open a HANDLE from it via OpenProcess, rather
            // than repurposing `pid_t` to mean HANDLE.
            try self.write("#include <sys/types.h>\n");
            try self.write("#ifndef _PID_T_\n");
            try self.write("#define _PID_T_\n");
            try self.write("typedef int pid_t;\n");
            try self.write("#endif\n");
            try self.write("typedef void* posix_spawnattr_t;\n");
            try self.write("typedef struct {\n");
            try self.write("    int has_dup2_1; int dup2_1_fd;\n");
            try self.write("    int has_dup2_2; int dup2_2_fd;\n");
            try self.write("} posix_spawn_file_actions_t;\n");
            try self.write("\n");
            try self.write("long long posix_spawn_file_actions_init(posix_spawn_file_actions_t* fa) {\n");
            try self.write("    if (fa == NULL) return -1;\n");
            try self.write("    fa->has_dup2_1 = 0;\n");
            try self.write("    fa->has_dup2_2 = 0;\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long posix_spawn_file_actions_destroy(posix_spawn_file_actions_t* fa) {\n");
            try self.write("    (void)fa;\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            // Only stdout(1)/stderr(2) redirection is supported -- the only
            // shape `std/process.fn`'s `run()` actually uses.
            try self.write("long long posix_spawn_file_actions_adddup2(posix_spawn_file_actions_t* fa, long long fildes, long long newfildes) {\n");
            try self.write("    if (fa == NULL) return -1;\n");
            try self.write("    if (newfildes == 1) { fa->has_dup2_1 = 1; fa->dup2_1_fd = (int)fildes; return 0; }\n");
            try self.write("    if (newfildes == 2) { fa->has_dup2_2 = 1; fa->dup2_2_fd = (int)fildes; return 0; }\n");
            try self.write("    return -1;\n");
            try self.write("}\n");
            try self.write("\n");
            // A no-op: with STARTF_USESTDHANDLES, unlisted std handles are
            // simply left as the parent's own, so nothing needs closing in
            // the (nonexistent) child before CreateProcess -- unlike POSIX,
            // there is no fork'd child address space to prune fds in first.
            try self.write("long long posix_spawn_file_actions_addclose(posix_spawn_file_actions_t* fa, long long fildes) {\n");
            try self.write("    (void)fa; (void)fildes;\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            // Builds a Windows command-line string from argv, following the
            // standard MSVCRT argument-quoting rules: quote an argument if
            // it's empty or contains space/tab/quote, and backslash-escape
            // runs of backslashes that immediately precede a quote (or end
            // a quoted argument).
            try self.write("static char* __fun_win_build_cmdline(char** argv) {\n");
            try self.write("    size_t cap = 256, len = 0;\n");
            try self.write("    char* out = (char*)malloc(cap);\n");
            try self.write("    if (out == NULL) return NULL;\n");
            try self.write("    for (int i = 0; argv[i] != NULL; i++) {\n");
            try self.write("        const char* a = argv[i];\n");
            try self.write("        size_t alen = strlen(a);\n");
            try self.write("        int needs_quotes = (alen == 0);\n");
            try self.write("        for (size_t j = 0; j < alen && !needs_quotes; j++) {\n");
            try self.write("            if (a[j] == ' ' || a[j] == '\\t' || a[j] == '\"') needs_quotes = 1;\n");
            try self.write("        }\n");
            try self.write("        size_t need = alen * 2 + 3;\n");
            try self.write("        while (len + need + 2 > cap) {\n");
            try self.write("            cap *= 2;\n");
            try self.write("            char* n = (char*)realloc(out, cap);\n");
            try self.write("            if (n == NULL) { free(out); return NULL; }\n");
            try self.write("            out = n;\n");
            try self.write("        }\n");
            try self.write("        if (i > 0) out[len++] = ' ';\n");
            try self.write("        if (needs_quotes) out[len++] = '\"';\n");
            try self.write("        size_t backslashes = 0;\n");
            try self.write("        for (size_t j = 0; j < alen; j++) {\n");
            try self.write("            char c = a[j];\n");
            try self.write("            if (c == '\\\\') { backslashes++; out[len++] = c; continue; }\n");
            try self.write("            if (c == '\"') {\n");
            try self.write("                for (size_t k = 0; k <= backslashes; k++) out[len++] = '\\\\';\n");
            try self.write("                out[len++] = '\"';\n");
            try self.write("                backslashes = 0;\n");
            try self.write("                continue;\n");
            try self.write("            }\n");
            try self.write("            backslashes = 0;\n");
            try self.write("            out[len++] = c;\n");
            try self.write("        }\n");
            try self.write("        if (needs_quotes) {\n");
            try self.write("            for (size_t k = 0; k < backslashes; k++) out[len++] = '\\\\';\n");
            try self.write("            out[len++] = '\"';\n");
            try self.write("        }\n");
            try self.write("    }\n");
            try self.write("    out[len] = '\\0';\n");
            try self.write("    return out;\n");
            try self.write("}\n");
            try self.write("\n");
            try self.write("long long posix_spawnp(pid_t* pid, const char* file, posix_spawn_file_actions_t* file_actions, posix_spawnattr_t* attrp, char** argv, char** envp) {\n");
            try self.write("    (void)file; (void)attrp; (void)envp;\n");
            try self.write("    if (pid == NULL || argv == NULL) return -1;\n");
            try self.write("\n");
            try self.write("    STARTUPINFOA si;\n");
            try self.write("    PROCESS_INFORMATION pi;\n");
            try self.write("    memset(&si, 0, sizeof(si));\n");
            try self.write("    memset(&pi, 0, sizeof(pi));\n");
            try self.write("    si.cb = sizeof(si);\n");
            try self.write("\n");
            try self.write("    BOOL inherit = FALSE;\n");
            try self.write("    if (file_actions != NULL && (file_actions->has_dup2_1 || file_actions->has_dup2_2)) {\n");
            try self.write("        si.dwFlags |= STARTF_USESTDHANDLES;\n");
            try self.write("        si.hStdInput = GetStdHandle(STD_INPUT_HANDLE);\n");
            try self.write("        si.hStdOutput = file_actions->has_dup2_1 ? (HANDLE)_get_osfhandle(file_actions->dup2_1_fd) : GetStdHandle(STD_OUTPUT_HANDLE);\n");
            try self.write("        si.hStdError = file_actions->has_dup2_2 ? (HANDLE)_get_osfhandle(file_actions->dup2_2_fd) : GetStdHandle(STD_ERROR_HANDLE);\n");
            try self.write("        if (file_actions->has_dup2_1) SetHandleInformation(si.hStdOutput, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT);\n");
            try self.write("        if (file_actions->has_dup2_2) SetHandleInformation(si.hStdError, HANDLE_FLAG_INHERIT, HANDLE_FLAG_INHERIT);\n");
            try self.write("        inherit = TRUE;\n");
            try self.write("    }\n");
            try self.write("\n");
            try self.write("    char* cmdline = __fun_win_build_cmdline(argv);\n");
            try self.write("    if (cmdline == NULL) return -1;\n");
            try self.write("    BOOL ok = CreateProcessA(NULL, cmdline, NULL, NULL, inherit, 0, NULL, NULL, &si, &pi);\n");
            try self.write("    free(cmdline);\n");
            try self.write("    if (!ok) return -1;\n");
            try self.write("\n");
            try self.write("    CloseHandle(pi.hThread);\n");
            try self.write("    CloseHandle(pi.hProcess);\n");
            try self.write("    *pid = (pid_t)pi.dwProcessId;\n");
            try self.write("    return 0;\n");
            try self.write("}\n");
            try self.write("\n");
            // Decoded into the SAME bit layout `_decode_wait_status`
            // (std/process.fn) expects on POSIX: bits 0-6 the terminating
            // signal (always 0 here -- Windows reports no such thing the
            // same way), bits 8-15 the exit code.
            try self.write("long long waitpid(pid_t pid, int32_t* status, long long options) {\n");
            try self.write("    (void)options;\n");
            try self.write("    HANDLE h = OpenProcess(SYNCHRONIZE | PROCESS_QUERY_INFORMATION, FALSE, (DWORD)pid);\n");
            try self.write("    if (h == NULL) return -1;\n");
            try self.write("    WaitForSingleObject(h, INFINITE);\n");
            try self.write("    DWORD code = 0;\n");
            try self.write("    GetExitCodeProcess(h, &code);\n");
            try self.write("    CloseHandle(h);\n");
            try self.write("    if (status != NULL) *status = (int32_t)((code & 0xFF) << 8);\n");
            try self.write("    return (long long)pid;\n");
            try self.write("}\n");
            try self.write("\n");
            // `std.c.process.kill`'s Windows implementation. `sig` is
            // ignored (Windows has no signal-delivery equivalent):
            // `TerminateProcess` is the closest match to POSIX
            // `SIGKILL`, so that's what every signal maps to here.
            try self.write("long long kill(pid_t pid, long long sig) {\n");
            try self.write("    (void)sig;\n");
            try self.write("    HANDLE h = OpenProcess(PROCESS_TERMINATE, FALSE, (DWORD)pid);\n");
            try self.write("    if (h == NULL) return -1;\n");
            try self.write("    BOOL ok = TerminateProcess(h, 1);\n");
            try self.write("    CloseHandle(h);\n");
            try self.write("    return ok ? 0 : -1;\n");
            try self.write("}\n");
            try self.write("\n");
            // `_pipe` needs a buffer size + text/binary mode that POSIX's
            // 1-arg `pipe(fds)` has no room for -- arity mismatch, so unlike
            // close/read/write/dup2 (which MinGW's io.h already aliases to
            // their real msvcrt names with compatible signatures) this one
            // needs an actual wrapper, not just relying on io.h.
            try self.write("long long pipe(int32_t* fds) {\n");
            try self.write("    return (long long)_pipe(fds, 4096, _O_BINARY);\n");
            try self.write("}\n");
            try self.write("#else\n");
            try self.write("#include <spawn.h>\n");
            try self.write("#include <sys/wait.h>\n");
            try self.write("#include <unistd.h>\n");
            try self.write("#include <signal.h>\n");
            try self.write("#endif\n");
        }
    }

    fn requires_process_compat_recursive(proc: *Self) bool {
        if (proc.requires_process_compat_layer) return true;
        for (proc.children.items) |child| {
            if (requires_process_compat_recursive(child)) return true;
        }
        return false;
    }

    fn requires_thread_compat_recursive(proc: *Self) bool {
        if (proc.requires_thread_compat_layer) return true;
        for (proc.children.items) |child| {
            if (requires_thread_compat_recursive(child)) return true;
        }
        return false;
    }

    /// True if a `fork` statement appears anywhere in `node`'s subtree. Walks the
    /// statement/body shapes that can contain a `fork` (function bodies, blocks,
    /// control-flow arms, fit arms). Only structural recursion is needed — a `fork`
    /// is always a statement, never nested inside an expression.
    fn node_contains_fork(node: *const ast.Node) bool {
        if (node.type == .StatementFork) return true;
        const v = node.node_variant orelse return false;
        switch (v) {
            .body => |b| {
                for (b.statements.items()) |s| if (node_contains_fork(s)) return true;
            },
            .statement => |st| switch (st) {
                .if_stmt => |s| return node_contains_fork(s.body),
                .elif_stmt => |s| return node_contains_fork(s.body),
                .else_stmt => |s| return node_contains_fork(s.body),
                .defer_stmt => |s| return node_contains_fork(s.body),
                .for_stmt => |fs| switch (fs) {
                    .cond => |c| return node_contains_fork(c.body),
                    .range => |r| return node_contains_fork(r.body),
                    .iter => |it| return node_contains_fork(it.body),
                },
                .fit_stmt => |fit| {
                    for (fit.branches.items()) |br| if (node_contains_fork(br.body)) return true;
                },
                else => {},
            },
            .function => |fnv| {
                if (fnv.body) |b| return node_contains_fork(b);
            },
            .impl => |im| {
                for (im.methods.items()) |m| if (node_contains_fork(m)) return true;
            },
            else => {},
        }
        return false;
    }

    /// True if any `fork` statement appears in this module or its imported children.
    fn uses_fork_recursive(proc: *Self) bool {
        if (proc.uses_fork) return true;
        for (proc.nodes.items()) |*n| {
            if (node_contains_fork(n)) return true;
        }
        for (proc.children.items) |child| {
            if (uses_fork_recursive(child)) return true;
        }
        return false;
    }

    fn requires_net_compat_recursive(proc: *Self) bool {
        if (proc.requires_net_compat_layer) return true;
        for (proc.children.items) |child| {
            if (requires_net_compat_recursive(child)) return true;
        }
        return false;
    }
};

fn is_known_extern_function_name(name: []const u8) bool {
    return mem.eql(u8, name, "printf") or
        mem.eql(u8, name, "fprintf") or
        mem.eql(u8, name, "sprintf") or
        mem.eql(u8, name, "snprintf") or
        mem.eql(u8, name, "scanf") or
        mem.eql(u8, name, "sscanf") or
        mem.eql(u8, name, "puts") or
        mem.eql(u8, name, "putchar") or
        mem.eql(u8, name, "getchar") or
        mem.eql(u8, name, "fopen") or
        mem.eql(u8, name, "freopen") or
        mem.eql(u8, name, "fclose") or
        mem.eql(u8, name, "fflush") or
        mem.eql(u8, name, "fgetc") or
        mem.eql(u8, name, "fputc") or
        mem.eql(u8, name, "fgets") or
        mem.eql(u8, name, "fputs") or
        mem.eql(u8, name, "fread") or
        mem.eql(u8, name, "fwrite") or
        mem.eql(u8, name, "fseek") or
        mem.eql(u8, name, "ftell") or
        mem.eql(u8, name, "rewind") or
        mem.eql(u8, name, "feof") or
        mem.eql(u8, name, "ferror") or
        mem.eql(u8, name, "perror") or
        mem.eql(u8, name, "remove") or
        mem.eql(u8, name, "rename") or
        mem.eql(u8, name, "tmpfile") or
        mem.eql(u8, name, "tmpnam");
}
